// ---------------- LOGIN SCREEN ----------------
class LoginScreen extends StatefulWidget {
  const LoginScreen({super.key});

  @override
  State<LoginScreen> createState() => _LoginScreenState();
}

class _LoginScreenState extends State<LoginScreen> {
  final _emailController = TextEditingController();
  final _passwordController = TextEditingController();
  bool _isLoading = false;
  String _errorMessage = '';
  bool _obscurePassword = true;

  VideoPlayerController? _videoController;
  bool _videoInitialized = false;

  @override
  void initState() {
    super.initState();
    if (kIsWeb) {
      // Uri.parse on a bare relative path has no scheme/host, which the
      // video_player web backend can't turn into a network request at all —
      // resolving against the page's own URL is what actually gives it
      // something fetchable.
      final videoUri = Uri.base.resolve('assets/videos/login_bg.mp4');
      final controller = VideoPlayerController.networkUrl(videoUri);
      _videoController = controller;
      controller
          .initialize()
          .then((_) {
            if (!mounted) return;
            controller.setLooping(true);
            controller.setVolume(0.0);
            controller.play();
            setState(() => _videoInitialized = true);
          })
          .catchError((Object e, StackTrace st) {
            debugPrint('Login background video failed to initialize: $e');
          });
    }
  }

  @override
  void dispose() {
    _videoController?.dispose();
    super.dispose();
  }

  Future<void> _login() async {
    setState(() {
      _isLoading = true;
      _errorMessage = '';
    });

    try {
      // Step 1: Sign in with Firebase Auth
      final userCredential = await FirebaseAuth.instance
          .signInWithEmailAndPassword(
            email: _emailController.text.trim(),
            password: _passwordController.text.trim(),
          )
          .timeout(const Duration(seconds: 20));

      final uid = userCredential.user!.uid;

      // Step 2: Fetch role from Firestore "users" collection
      final userDoc = await FirebaseFirestore.instance
          .collection('users')
          .doc(uid)
          .get();

      if (!userDoc.exists) {
        setState(() {
          _errorMessage = 'User profile not found in database.';
          _isLoading = false;
        });
        return;
      }

      final role = userDoc.data()?['role'] ?? '';
      final name = userDoc.data()?['name'] ?? '';

      if (!mounted) return;

      if (role != 'admin' &&
          role != 'owner' &&
          role != 'supervisor' &&
          role != 'driver' &&
          role != 'field_worker' &&
          role != 'management' &&
          role != 'unloading_site' &&
          role != 'technical') {
        setState(() {
          _errorMessage = 'Unknown role. Contact Admin.';
        });
        await FirebaseAuth.instance.signOut();
        return;
      }

      if (role == 'management' && !kIsWeb) {
        setState(() {
          _errorMessage =
              'This account can only be used on the website, not the mobile app.';
        });
        await FirebaseAuth.instance.signOut();
        return;
      }

      if (role == 'field_worker' &&
          userDoc.data()?['canDriveTruck'] != true &&
          userDoc.data()?['canOperateMachine'] != true) {
        setState(() {
          _errorMessage = 'Account not configured. Contact Admin.';
        });
        await FirebaseAuth.instance.signOut();
        return;
      }

      // Force navigation directly instead of relying solely on AuthGate's stream rebuild
      Widget target;
      switch (role) {
        case 'admin':
          target = AdminDashboard(name: name);
          break;
        case 'owner':
          target = OwnerDashboard(name: name);
          break;
        case 'supervisor':
          target = userDoc.data()?['canAccessFuel'] == true
              ? SupervisorChoiceScreen(name: name)
              : SupervisorScreen(name: name);
          break;
        case 'driver':
          // Drivers only do the Daily Check (no Machines, no work entry).
          target = DriverHomeScreen(name: name);
          break;
        case 'management':
          // The !kIsWeb case already returned above, so reaching here means
          // this is the web build.
          target = ManagementDashboard(name: name);
          break;
        case 'unloading_site':
          final unloadingSiteIds =
              (userDoc.data()?['unloadingSiteIds'] as List?)
                  ?.map((e) => e.toString())
                  .toList() ??
              <String>[];
          target = UnloadingSiteViewerScreen(
            name: name,
            unloadingSiteIds: unloadingSiteIds,
          );
          break;
        case 'field_worker':
          final canDrive = userDoc.data()?['canDriveTruck'] == true;
          final canOperate = userDoc.data()?['canOperateMachine'] == true;
          if (canDrive && canOperate) {
            target = DriverTypeScreen(name: name);
          } else if (canDrive) {
            target = DriverHomeScreen(name: name);
          } else {
            target = DriverMachineTypeScreen(name: name);
          }
          break;
        case 'technical':
          target = TechnicalHomeScreen(name: name);
          break;
        default:
          target = const LoginScreen();
      }

      if (mounted) {
        Navigator.of(context).pushAndRemoveUntil(
          MaterialPageRoute(builder: (_) => target),
          (route) => false,
        );
      }
    } on FirebaseAuthException catch (e) {
      setState(() {
        _errorMessage = e.message ?? 'Login failed. Please try again.';
      });
    } catch (e) {
      setState(() {
        _errorMessage = 'Something went wrong. Try again.';
      });
    } finally {
      if (mounted) {
        setState(() {
          _isLoading = false;
        });
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    final screenWidth = MediaQuery.of(context).size.width;
    final isDesktop = screenWidth > 700;

    final loginContent = SafeArea(
      child: Center(
        child: ConstrainedBox(
          constraints: BoxConstraints(
            maxWidth: isDesktop ? 440 : double.infinity,
          ),
          child: SingleChildScrollView(
            padding: const EdgeInsets.all(24.0),
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                TweenAnimationBuilder<double>(
                  tween: Tween(begin: 0.0, end: 1.0),
                  duration: const Duration(milliseconds: 600),
                  curve: Curves.elasticOut,
                  builder: (context, value, child) {
                    return Transform.scale(scale: value, child: child);
                  },
                  child: Container(
                    width: 130,
                    height: 130,
                    decoration: BoxDecoration(
                      borderRadius: BorderRadius.circular(28),
                      boxShadow: [
                        BoxShadow(
                          color: AppTheme.accent.withOpacity(0.4),
                          blurRadius: 24,
                          spreadRadius: 2,
                        ),
                      ],
                    ),
                    child: ClipRRect(
                      borderRadius: BorderRadius.circular(28),
                      child: Image.asset(
                        'assets/images/logo_final_gradient.webp',
                        fit: BoxFit.cover,
                      ),
                    ),
                  ),
                ),
                const SizedBox(height: 24),
                const Text(
                  'NODA Civimech Engineering',
                  textAlign: TextAlign.center,
                  style: TextStyle(
                    fontSize: 22,
                    fontWeight: FontWeight.bold,
                    color: Colors.white,
                  ),
                ),
                const SizedBox(height: 6),
                Text(
                  'Login to continue',
                  style: TextStyle(
                    fontSize: 14,
                    color: Colors.white.withOpacity(0.7),
                  ),
                ),
                const SizedBox(height: 36),
                LoginFormCard(
                  child: Column(
                    children: [
                      TextField(
                        controller: _emailController,
                        style: const TextStyle(color: Colors.black87),
                        decoration: InputDecoration(
                          labelText: 'Email',
                          labelStyle: TextStyle(color: Colors.grey[700]),
                          prefixIcon: Icon(
                            Icons.email,
                            color: Colors.grey[700],
                          ),
                          enabledBorder: OutlineInputBorder(
                            borderRadius: BorderRadius.circular(12),
                            borderSide: BorderSide(color: Colors.grey[400]!),
                          ),
                          focusedBorder: OutlineInputBorder(
                            borderRadius: BorderRadius.circular(12),
                            borderSide: const BorderSide(
                              color: AppTheme.primaryMid,
                              width: 2,
                            ),
                          ),
                        ),
                      ),
                      const SizedBox(height: 16),
                      TextField(
                        controller: _passwordController,
                        obscureText: _obscurePassword,
                        style: const TextStyle(color: Colors.black87),
                        decoration: InputDecoration(
                          labelText: 'Password',
                          labelStyle: TextStyle(color: Colors.grey[700]),
                          prefixIcon: Icon(Icons.lock, color: Colors.grey[700]),
                          suffixIcon: IconButton(
                            icon: Icon(
                              _obscurePassword
                                  ? Icons.visibility_off
                                  : Icons.visibility,
                              color: Colors.grey[700],
                            ),
                            onPressed: () {
                              setState(
                                () => _obscurePassword = !_obscurePassword,
                              );
                            },
                          ),
                          enabledBorder: OutlineInputBorder(
                            borderRadius: BorderRadius.circular(12),
                            borderSide: BorderSide(color: Colors.grey[400]!),
                          ),
                          focusedBorder: OutlineInputBorder(
                            borderRadius: BorderRadius.circular(12),
                            borderSide: const BorderSide(
                              color: AppTheme.primaryMid,
                              width: 2,
                            ),
                          ),
                        ),
                      ),
                      if (_errorMessage.isNotEmpty) ...[
                        const SizedBox(height: 12),
                        Text(
                          _errorMessage,
                          style: const TextStyle(
                            color: Colors.redAccent,
                            fontSize: 13,
                          ),
                        ),
                      ],
                      const SizedBox(height: 24),
                      _isLoading
                          ? const CircularProgressIndicator(color: Colors.white)
                          : GradientButton(
                              label: 'LOGIN',
                              icon: Icons.login,
                              onTap: _login,
                            ),
                    ],
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );

    return Scaffold(
      body: kIsWeb
          ? Stack(
              children: [
                Positioned.fill(
                  child: Image.asset(
                    'assets/images/login_background_web.webp',
                    fit: BoxFit.cover,
                  ),
                ),
                if (_videoInitialized && _videoController != null)
                  Positioned.fill(
                    child: FittedBox(
                      fit: BoxFit.cover,
                      child: SizedBox(
                        width: _videoController!.value.size.width,
                        height: _videoController!.value.size.height,
                        child: VideoPlayer(_videoController!),
                      ),
                    ),
                  ),
                Positioned.fill(
                  child: Container(
                    decoration: BoxDecoration(
                      gradient: LinearGradient(
                        begin: Alignment.topCenter,
                        end: Alignment.bottomCenter,
                        colors: [
                          AppTheme.primaryDark.withOpacity(0.45),
                          AppTheme.primaryMid.withOpacity(0.45),
                        ],
                      ),
                    ),
                  ),
                ),
                loginContent,
              ],
            )
          : Container(
              decoration: const BoxDecoration(
                image: DecorationImage(
                  image: AssetImage('assets/images/login_background.webp'),
                  fit: BoxFit.cover,
                ),
              ),
              child: loginContent,
            ),
