  Widget _buildMenuCard(
    BuildContext context, {
    required IconData icon,
    required String title,
    required String subtitle,
    required Color color,
    required VoidCallback onTap,
  }) {
    return Card(
      elevation: 2,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
      child: ListTile(
        contentPadding: const EdgeInsets.all(16),
        leading: CircleAvatar(
          backgroundColor: color.withOpacity(0.15),
          child: Icon(icon, color: color),
        ),
        title: Text(title, style: const TextStyle(fontWeight: FontWeight.bold)),
        subtitle: Text(subtitle),
        trailing: const Icon(Icons.chevron_right),
        onTap: onTap,
      ),
    );
  }
}

// ---------------- ADD USER SCREEN (Admin creates Supervisor/Owner) ----------------
class AddUserScreen extends StatefulWidget {
  final FirebaseFirestore? firestoreOverride;
  final String? currentUidOverride;
  const AddUserScreen({super.key, this.firestoreOverride, this.currentUidOverride});

  @override
  State<AddUserScreen> createState() => _AddUserScreenState();
}

class _AddUserScreenState extends State<AddUserScreen> {
  FirebaseFirestore get _db => widget.firestoreOverride ?? FirebaseFirestore.instance;
  String? get _uid => widget.currentUidOverride ?? FirebaseAuth.instance.currentUser?.uid;

  final _nameController = TextEditingController();
  final _emailController = TextEditingController();
  final _passwordController = TextEditingController();
  String _selectedRole = 'supervisor';
  bool _canDriveTruck = false;
  bool _canOperateMachine = false;
  bool _isLoading = false;
  String _message = '';
  bool _isError = false;
  String? _photoBase64;
  bool _obscurePassword = true;
  bool _canAccessFuel = false;
  bool _canEditReports = false;
  bool _canAccessTransportRecords = false;
  bool _canAccessGarage = false;
  bool _canAccessWarehouse = false;
  // Reassigned (not just mutated) whenever the role crosses into/out of
  // 'technical' — see _selectRole() — so RepairPermissionsEditor is
  // recreated with fresh initialPermissions instead of keeping whatever
  // was ticked under the previous role.
  GlobalKey<RepairPermissionsEditorState> _repairPermsKey =
      GlobalKey<RepairPermissionsEditorState>();
  final Set<String> _selectedUnloadingSiteIds = {};
  // TECHNICAL is admin/owner only — this screen is only reachable from
  // AdminDashboard today, but checking the signed-in user's own role
  // directly (rather than relying on "well, only admin can reach this
  // screen") keeps the gate correct even if that ever changes.
  bool _canCreateTechnical = false;

  @override
  void initState() {
    super.initState();
    _loadCanCreateTechnical();
  }

  Future<void> _loadCanCreateTechnical() async {
    try {
      final uid = _uid;
      if (uid == null) return;
      final doc = await _db.collection('users').doc(uid).get();
      final role = doc.data()?['role'] as String?;
      if (mounted) {
        setState(() => _canCreateTechnical = role == 'admin' || role == 'owner');
      }
    } catch (_) {
      // Leave the Technical option hidden if this fails.
    }
  }

  // Shared by every role RadioListTile — bundles the TECHNICAL
  // preset/un-preset transition (Garage + Warehouse Access) with the role
  // change itself, so entering/leaving 'technical' is a single atomic
  // setState rather than two separate ones that could be observed
  // mid-way. The repairPermissions checkbox grid's own defaults are
  // re-seeded by keying it on _selectedRole (see the RepairPermissionsEditor
  // below) rather than from here.
  void _selectRole(String role) {
    setState(() {
      final enteringTechnical = role == 'technical' && _selectedRole != 'technical';
      final leavingTechnical = role != 'technical' && _selectedRole == 'technical';
      _selectedRole = role;
      if (enteringTechnical || leavingTechnical) {
        // Forces RepairPermissionsEditor to be recreated (a GlobalKey is
        // compared by identity) so its initialPermissions re-seeds from
        // the new role instead of keeping whatever was ticked before.
        _repairPermsKey = GlobalKey<RepairPermissionsEditorState>();
      }
      if (enteringTechnical) {
        _canAccessGarage = true;
        _canAccessWarehouse = true;
      } else if (leavingTechnical) {
        _canAccessGarage = false;
        _canAccessWarehouse = false;
      }
    });
  }

  Future<void> _pickPhoto(ImageSource source) async {
    try {
      final picker = ImagePicker();
      final pickedFile = await picker.pickImage(
        source: source,
        maxWidth: 400,
        maxHeight: 400,
        imageQuality: 60,
      );
      if (pickedFile == null) return;

      final bytes = await pickedFile.readAsBytes();
      final base64String = base64Encode(bytes);

      // Firestore document limit is 1MB; keep a safety margin
      if (base64String.length > 700000) {
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(
              content: Text('Image too large. Please choose a smaller photo.'),
            ),
          );
        }
        return;
      }

      setState(() => _photoBase64 = base64String);
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text('Error picking image: $e')));
      }
    }
  }

  void _showPhotoSourceSheet() {
    showModalBottomSheet(
      context: context,
      backgroundColor: Colors.transparent,
      builder: (_) => Container(
        decoration: const BoxDecoration(
          color: Colors.white,
          borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
        ),
        padding: const EdgeInsets.symmetric(vertical: 20),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            ListTile(
              leading: const Icon(Icons.camera_alt, color: Colors.blue),
              title: const Text('Take Photo'),
              onTap: () {
                Navigator.pop(context);
                _pickPhoto(ImageSource.camera);
              },
            ),
            ListTile(
              leading: const Icon(Icons.photo_library, color: Colors.blue),
              title: const Text('Choose from Gallery'),
              onTap: () {
                Navigator.pop(context);
                _pickPhoto(ImageSource.gallery);
              },
            ),
            if (_photoBase64 != null)
              ListTile(
                leading: const Icon(Icons.delete, color: Colors.red),
                title: const Text('Remove Photo'),
                onTap: () {
                  Navigator.pop(context);
                  setState(() => _photoBase64 = null);
                },
              ),
          ],
        ),
      ),
    );
  }

  Future<void> _createUser() async {
    if (_nameController.text.trim().isEmpty ||
        _emailController.text.trim().isEmpty ||
        _passwordController.text.trim().length < 6) {
      setState(() {
        _isError = true;
        _message = 'Please fill all fields. Password must be 6+ characters.';
      });
      return;
    }

    if (_selectedRole == 'field_worker' &&
        !_canDriveTruck &&
        !_canOperateMachine) {
      setState(() {
        _isError = true;
        _message = 'Please select at least one: Driver or Operator.';
      });
      return;
    }

    if (_selectedRole == 'unloading_site' &&
        _selectedUnloadingSiteIds.isEmpty) {
      setState(() {
        _isError = true;
        _message = 'Please select at least one unloading site.';
      });
      return;
    }

    setState(() {
      _isLoading = true;
      _message = '';
    });

    try {
      // Use a SECONDARY Firebase app so the Admin doesn't get logged out
      FirebaseApp tempApp = await Firebase.initializeApp(
        name: 'tempApp_${DateTime.now().millisecondsSinceEpoch}',
        options: Firebase.app().options,
      );

      FirebaseAuth tempAuth = FirebaseAuth.instanceFor(app: tempApp);

      UserCredential newUser = await tempAuth.createUserWithEmailAndPassword(
        email: _emailController.text.trim(),
        password: _passwordController.text.trim(),
      );

      // Save role info in Firestore "users" collection
      await FirebaseFirestore.instance
          .collection('users')
          .doc(newUser.user!.uid)
          .set({
            'name': _nameController.text.trim(),
            'email': _emailController.text.trim(),
            'role': _selectedRole,
            'canDriveTruck': newUserCanDriveTruck(_selectedRole, _canDriveTruck),
            'canOperateMachine': _selectedRole == 'field_worker'
                ? _canOperateMachine
                : false,
            'canAccessFuel': _selectedRole == 'supervisor'
                ? _canAccessFuel
                : false,
            'canEditReports': _selectedRole == 'management'
                ? _canEditReports
                : false,
            'canAccessTransportRecords': _selectedRole == 'management'
                ? _canAccessTransportRecords
                : false,
            // Per-task Truck Repair access — admin/owner always have every
            // permission (see hasRepairPerm), so nothing is stored for
            // 'owner' here; every other role gets whatever the checkbox
            // grid below has selected (including an empty list, meaning no
            // Truck Repair tasks at all for that account).
            'repairPermissions': _selectedRole == 'owner'
                ? <String>[]
                : (_repairPermsKey.currentState?.selected.toList() ?? <String>[]),
            // Not role-gated, unlike the flags above — Garage/Warehouse
            // Access can be granted independently, regardless of which role
            // is selected (see AuthGate's routing override, GarageScreen
            // and WarehouseScreen).
            'canAccessGarage': _canAccessGarage,
            'canAccessWarehouse': _canAccessWarehouse,
            // Read-only UnloadingSiteViewerScreen access — see AuthGate's
            // 'unloading_site' switch case. Only meaningful for that role.
            'unloadingSiteIds': _selectedRole == 'unloading_site'
                ? _selectedUnloadingSiteIds.toList()
                : <String>[],
            'photoBase64': _photoBase64,
            'createdAt': FieldValue.serverTimestamp(),
          });

      // Sign out and delete the temporary app instance
      await tempAuth.signOut();
      await tempApp.delete();

      setState(() {
        _isError = false;
        _message = 'Account created successfully!';
        _nameController.clear();
        _emailController.clear();
        _passwordController.clear();
        _photoBase64 = null;
        _canDriveTruck = false;
        _canOperateMachine = false;
        _selectedUnloadingSiteIds.clear();
      });
    } on FirebaseAuthException catch (e) {
      setState(() {
        _isError = true;
        _message = e.message ?? 'Failed to create user.';
      });
    } catch (e) {
      setState(() {
        _isError = true;
        _message = 'Something went wrong: $e';
      });
    } finally {
      setState(() {
        _isLoading = false;
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Add Supervisor / Owner'),
        backgroundColor: Colors.blue[800],
      ),
      body: SingleChildScrollView(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Center(
              child: GestureDetector(
                onTap: _showPhotoSourceSheet,
                child: Stack(
                  children: [
                    CircleAvatar(
                      radius: 50,
                      backgroundColor: Colors.blue[100],
                      backgroundImage: _photoBase64 != null
                          ? MemoryImage(base64Decode(_photoBase64!))
                          : null,
                      child: _photoBase64 == null
                          ? Icon(
                              Icons.person,
                              size: 50,
                              color: Colors.blue[800],
                            )
                          : null,
                    ),
                    Positioned(
                      bottom: 0,
                      right: 0,
                      child: Container(
                        padding: const EdgeInsets.all(6),
