                if (_selectedRole == 'field_worker')
                  Padding(
                    padding: const EdgeInsets.only(
                      left: 16,
                      right: 16,
                      bottom: 8,
                    ),
                    child: Container(
                      padding: const EdgeInsets.all(12),
                      decoration: BoxDecoration(
                        color: Colors.blue[50],
                        borderRadius: BorderRadius.circular(10),
                        border: Border.all(color: Colors.blue[200]!),
                      ),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          const Text(
                            'What can they operate?',
                            style: TextStyle(
                              fontWeight: FontWeight.bold,
                              fontSize: 13,
                            ),
                          ),
                          CheckboxListTile(
                            title: const Text('Driver (can operate trucks)'),
                            value: _canDriveTruck,
                            contentPadding: EdgeInsets.zero,
                            controlAffinity: ListTileControlAffinity.leading,
                            onChanged: (val) =>
                                setState(() => _canDriveTruck = val ?? false),
                          ),
                          CheckboxListTile(
                            title: const Text(
                              'Operator (can operate machines)',
                            ),
                            value: _canOperateMachine,
                            contentPadding: EdgeInsets.zero,
                            controlAffinity: ListTileControlAffinity.leading,
                            onChanged: (val) => setState(
                              () => _canOperateMachine = val ?? false,
                            ),
                          ),
                        ],
                      ),
                    ),
                  ),
                if (_selectedRole == 'unloading_site')
                  Padding(
                    padding: const EdgeInsets.only(
                      left: 16,
                      right: 16,
                      bottom: 8,
                    ),
                    child: Container(
                      padding: const EdgeInsets.all(12),
                      decoration: BoxDecoration(
                        color: Colors.blue[50],
                        borderRadius: BorderRadius.circular(10),
                        border: Border.all(color: Colors.blue[200]!),
                      ),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          const Text(
                            'Assign Unloading Site(s)',
                            style: TextStyle(
                              fontWeight: FontWeight.bold,
                              fontSize: 13,
                            ),
                          ),
                          StreamBuilder<QuerySnapshot>(
                            stream: ReferenceCollectionCache.stream('sites'),
                            builder: (context, snapshot) {
                              if (!snapshot.hasData) {
                                return const Padding(
                                  padding: EdgeInsets.all(12),
                                  child: Center(
                                    child: CircularProgressIndicator(),
                                  ),
                                );
                              }
                              final sites = snapshot.data!.docs.where((doc) {
                                final d = doc.data() as Map<String, dynamic>;
                                return d['canBeUnloadingSite'] != false;
                              }).toList();
                              if (sites.isEmpty) {
                                return const Padding(
                                  padding: EdgeInsets.all(12),
                                  child: Text('No unloading sites found.'),
                                );
                              }
                              return Column(
                                children: sites.map((doc) {
                                  final d = doc.data() as Map<String, dynamic>;
                                  final siteName = (d['name'] ?? '')
                                      .toString();
                                  return CheckboxListTile(
                                    title: Text(siteName),
                                    value: _selectedUnloadingSiteIds.contains(
                                      doc.id,
                                    ),
                                    contentPadding: EdgeInsets.zero,
                                    controlAffinity:
                                        ListTileControlAffinity.leading,
                                    onChanged: (val) => setState(() {
                                      if (val == true) {
                                        _selectedUnloadingSiteIds.add(doc.id);
                                      } else {
                                        _selectedUnloadingSiteIds.remove(
                                          doc.id,
                                        );
                                      }
                                    }),
                                  );
                                }).toList(),
                              );
                            },
                          ),
                        ],
                      ),
                    ),
                  ),
              ],
            ),
            const SizedBox(height: 16),
            TextField(
              controller: _nameController,
              inputFormatters: [UpperCaseTextFormatter()],
              textCapitalization: TextCapitalization.characters,
              decoration: InputDecoration(
                labelText: 'Full Name',
                prefixIcon: const Icon(Icons.person),
                border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(12),
                ),
              ),
            ),
            const SizedBox(height: 16),
            TextField(
              controller: _emailController,
              keyboardType: TextInputType.emailAddress,
              decoration: InputDecoration(
                labelText: 'Email',
                prefixIcon: const Icon(Icons.email),
                border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(12),
                ),
              ),
            ),
            const SizedBox(height: 16),
            TextField(
              controller: _passwordController,
              obscureText: _obscurePassword,
              decoration: InputDecoration(
                labelText: 'Password (min 6 characters)',
                prefixIcon: const Icon(Icons.lock),
                suffixIcon: IconButton(
                  icon: Icon(
                    _obscurePassword ? Icons.visibility_off : Icons.visibility,
                  ),
                  onPressed: () =>
                      setState(() => _obscurePassword = !_obscurePassword),
                ),
                border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(12),
                ),
              ),
            ),
            if (_selectedRole == 'supervisor')
              CheckboxListTile(
                title: const Text('Grant Fuel Entry Access'),
                value: _canAccessFuel,
                contentPadding: EdgeInsets.zero,
                controlAffinity: ListTileControlAffinity.leading,
                onChanged: (val) =>
                    setState(() => _canAccessFuel = val ?? false),
              ),
            const SizedBox(height: 8),
            if (_message.isNotEmpty)
              Padding(
                padding: const EdgeInsets.only(top: 8.0),
                child: Text(
                  _message,
                  style: TextStyle(
                    color: _isError ? Colors.red : Colors.green,
                    fontSize: 13,
                  ),
                ),
              ),
            const SizedBox(height: 24),
            SizedBox(
              width: double.infinity,
              height: 50,
              child: ElevatedButton(
                onPressed: _isLoading ? null : _createUser,
                style: ElevatedButton.styleFrom(
                  backgroundColor: Colors.blue[800],
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(12),
                  ),
                ),
                child: _isLoading
                    ? const CircularProgressIndicator(color: Colors.white)
                    : const Text(
                        'CREATE ACCOUNT',
                        style: TextStyle(fontSize: 16, color: Colors.white),
                      ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

// ---------------- MANAGE USERS SCREEN ----------------
class ManageUsersScreen extends StatefulWidget {
  // Test-only seam — every existing call site omits this and keeps using
  // the real FirebaseFirestore.instance exactly as before. Added so the
  // "Apply Technical Defaults" dialog's text can be rendered and checked
  // against a fake backend without touching the real one.
  final FirebaseFirestore? firestoreOverride;
  const ManageUsersScreen({super.key, this.firestoreOverride});

  @override
  State<ManageUsersScreen> createState() => _ManageUsersScreenState();
}

class _ManageUsersScreenState extends State<ManageUsersScreen> {
  FirebaseFirestore get _db => widget.firestoreOverride ?? FirebaseFirestore.instance;
  final TextEditingController _searchController = TextEditingController();
  String _searchQuery = '';
  String _roleFilter = 'ALL';

  @override
  void dispose() {
    _searchController.dispose();
    super.dispose();
  }

  bool _matchesSearch(Map<String, dynamic> data) {
    final q = _searchQuery.trim().toLowerCase();
    if (q.isEmpty) return true;
    final name = (data['name'] ?? '').toString().toLowerCase();
    final email = (data['email'] ?? '').toString().toLowerCase();
    final role = (data['role'] ?? '').toString().toLowerCase();
    final phone = (data['phone'] ?? '').toString().toLowerCase();
    return name.contains(q) ||
        email.contains(q) ||
        role.contains(q) ||
        phone.contains(q);
  }

  Widget _roleChip(String role) {
    final selected = _roleFilter == role;
    return Padding(
      padding: const EdgeInsets.only(right: 8),
      child: ChoiceChip(
        label: Text(role.toUpperCase()),
        selected: selected,
        onSelected: (_) => setState(() => _roleFilter = role),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Manage Users'),
        backgroundColor: Colors.blue[800],
      ),
      body: StreamBuilder<QuerySnapshot>(
        stream: _db.collection('users').snapshots(),
        builder: (context, snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting) {
            return const Center(child: CircularProgressIndicator());
          }
          if (!snapshot.hasData || snapshot.data!.docs.isEmpty) {
            return const Center(child: Text('No users found.'));
          }

          final allUsers = snapshot.data!.docs;
          final roleSet = <String>{};
          for (final doc in allUsers) {
            final r = ((doc.data() as Map<String, dynamic>)['role'] ?? '')
                .toString();
            if (r.isNotEmpty) roleSet.add(r);
          }
          final sortedRoles = roleSet.toList()..sort();

          final users = allUsers.where((doc) {
            final data = doc.data() as Map<String, dynamic>;
            if (_roleFilter != 'ALL' &&
                (data['role'] ?? '').toString() != _roleFilter) {
              return false;
            }
            return _matchesSearch(data);
          }).toList();

          return Column(
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(12, 12, 12, 8),
                child: TextField(
                  controller: _searchController,
                  onChanged: (val) => setState(() => _searchQuery = val),
                  decoration: InputDecoration(
                    hintText: 'SEARCH BY NAME, EMAIL, ROLE',
                    prefixIcon: const Icon(Icons.search),
                    suffixIcon: _searchQuery.isEmpty
                        ? null
                        : IconButton(
                            icon: const Icon(Icons.clear),
                            onPressed: () {
                              _searchController.clear();
                              setState(() => _searchQuery = '');
                            },
                          ),
                    filled: true,
                    fillColor: Colors.white,
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(10),
                      borderSide: BorderSide.none,
                    ),
                  ),
                ),
              ),
              Padding(
                padding: const EdgeInsets.fromLTRB(12, 0, 12, 8),
                child: SizedBox(
                  height: 36,
                  child: ListView(
                    scrollDirection: Axis.horizontal,
                    children: [
                      _roleChip('ALL'),
                      for (final r in sortedRoles) _roleChip(r),
                    ],
                  ),
                ),
              ),
              Padding(
                padding: const EdgeInsets.fromLTRB(12, 0, 12, 8),
                child: Align(
                  alignment: Alignment.centerLeft,
                  child: Text(
                    '${users.length} OF ${allUsers.length} USERS',
                    style: const TextStyle(
                      color: Colors.grey,
                      fontSize: 12,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                ),
              ),
              Expanded(
                child: users.isEmpty
                    ? EmptyState(
                        icon: Icons.search_off,
                        title: 'NO USERS FOUND',
                        actionLabel: 'CLEAR SEARCH',
                        onAction: () {
                          _searchController.clear();
                          setState(() {
                            _searchQuery = '';
                            _roleFilter = 'ALL';
                          });
                        },
                      )
                    : ListView.builder(
            padding: const EdgeInsets.all(12),
            itemCount: users.length,
            itemBuilder: (context, index) {
              final data = users[index].data() as Map<String, dynamic>;
              final role = data['role'] ?? '';
              Color roleColor = role == 'admin'
                  ? Colors.blue
                  : role == 'owner'
                  ? Colors.green
                  : Colors.orange;

              final userId = users[index].id;
              final currentUserUid = FirebaseAuth.instance.currentUser?.uid;
              final isSelf = userId == currentUserUid;
              final photoBase64 = data['photoBase64'] as String?;

              return _WebStaggeredFadeIn(
                index: index,
                child: _WebHoverCard(
                  child: Card(
                    margin: const EdgeInsets.only(bottom: 10),
                    child: ListTile(
                      leading: CircleAvatar(
                        backgroundColor: roleColor.withOpacity(0.15),
                        backgroundImage: photoBase64 != null
                            ? MemoryImage(base64Decode(photoBase64))
                            : null,
                        child: photoBase64 == null
                            ? Icon(Icons.person, color: roleColor)
                            : null,
                      ),
                      title: Text(data['name'] ?? 'No name'),
                      subtitle: Text('${data['email'] ?? ''}\nRole: $role'),
                      isThreeLine: true,
                      onTap: () {
                        pushWebAware(
                          context,
                          UserProfileScreen(
                            userId: userId,
                            userName: data['name'] ?? '',
                            userEmail: data['email'] ?? '',
                            userRole: role,
                            photoBase64: photoBase64,
                          ),
                        );
                      },
                      trailing: Row(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          if (role == 'supervisor')
                            IconButton(
                              icon: Icon(
                                Icons.local_gas_station,
                                color: data['canAccessFuel'] == true
                                    ? Colors.green
                                    : Colors.grey,
                              ),
                              onPressed: () {
                                final currentlyHasAccess =
                                    data['canAccessFuel'] == true;
                                final newValue = !currentlyHasAccess;
                                final userName = data['name'] ?? 'this user';
                                showDialog(
                                  context: context,
                                  builder: (_) => AlertDialog(
                                    title: Text(
                                      currentlyHasAccess
                                          ? 'Revoke Fuel Access?'
                                          : 'Grant Fuel Access?',
                                    ),
                                    content: Text(
                                      currentlyHasAccess
                                          ? 'Remove fuel entry access from $userName?'
                                          : 'Allow $userName to submit fuel entries?',
                                    ),
                                    actions: [
                                      TextButton(
                                        onPressed: () => Navigator.pop(context),
                                        child: const Text('Cancel'),
                                      ),
                                      ElevatedButton(
                                        onPressed: () async {
                                          await FirebaseFirestore.instance
                                              .collection('users')
                                              .doc(userId)
                                              .update({
                                                'canAccessFuel': newValue,
                                              });
                                          if (context.mounted) {
                                            Navigator.pop(context);
                                            ScaffoldMessenger.of(
                                              context,
                                            ).showSnackBar(
                                              SnackBar(
                                                content: Text(
                                                  newValue
                                                      ? 'Fuel access granted'
                                                      : 'Fuel access revoked',
                                                ),
                                              ),
                                            );
                                          }
                                        },
                                        child: const Text('CONFIRM'),
                                      ),
                                    ],
                                  ),
                                );
                              },
                            ),
                          if (role == 'management')
                            IconButton(
                              icon: Icon(
                                Icons.edit_note,
                                color: data['canEditReports'] == true
                                    ? Colors.green
                                    : Colors.grey,
                              ),
                              onPressed: () {
                                final currentlyCanEdit =
                                    data['canEditReports'] == true;
                                final newValue = !currentlyCanEdit;
                                final userName = data['name'] ?? 'this user';
                                showDialog(
                                  context: context,
                                  builder: (_) => AlertDialog(
                                    title: Text(
                                      currentlyCanEdit
                                          ? 'Revoke Report Edit Access?'
                                          : 'Grant Report Edit Access?',
                                    ),
                                    content: Text(
                                      currentlyCanEdit
                                          ? 'Remove report editing access from $userName?'
                                          : 'Allow $userName to edit report records?',
                                    ),
                                    actions: [
                                      TextButton(
                                        onPressed: () => Navigator.pop(context),
                                        child: const Text('Cancel'),
                                      ),
                                      ElevatedButton(
                                        onPressed: () async {
                                          await FirebaseFirestore.instance
                                              .collection('users')
                                              .doc(userId)
                                              .update({
                                                'canEditReports': newValue,
                                              });
                                          if (context.mounted) {
                                            Navigator.pop(context);
                                            ScaffoldMessenger.of(
                                              context,
                                            ).showSnackBar(
                                              SnackBar(
                                                content: Text(
                                                  newValue
                                                      ? 'Report edit access granted'
                                                      : 'Report edit access revoked',
                                                ),
                                              ),
                                            );
                                          }
                                        },
                                        child: const Text('CONFIRM'),
                                      ),
                                    ],
                                  ),
                                );
                              },
                            ),
                          if (role == 'management')
                            IconButton(
                              icon: Icon(
                                Icons.local_shipping,
                                color: data['canAccessTransportRecords'] == true
                                    ? Colors.green
                                    : Colors.grey,
                              ),
                              onPressed: () {
                                final currentlyHasAccess =
                                    data['canAccessTransportRecords'] == true;
                                final newValue = !currentlyHasAccess;
                                final userName = data['name'] ?? 'this user';
                                showDialog(
                                  context: context,
                                  builder: (_) => AlertDialog(
                                    title: Text(
                                      currentlyHasAccess
                                          ? 'Revoke Transport Records Access?'
                                          : 'Grant Transport Records Access?',
                                    ),
                                    content: Text(
                                      currentlyHasAccess
                                          ? 'Remove transport records access from $userName?'
                                          : 'Allow $userName to access transport records?',
                                    ),
                                    actions: [
                                      TextButton(
                                        onPressed: () => Navigator.pop(context),
                                        child: const Text('Cancel'),
                                      ),
                                      ElevatedButton(
                                        onPressed: () async {
                                          await FirebaseFirestore.instance
                                              .collection('users')
                                              .doc(userId)
                                              .update({
                                                'canAccessTransportRecords':
                                                    newValue,
                                              });
                                          if (context.mounted) {
                                            Navigator.pop(context);
                                            ScaffoldMessenger.of(
                                              context,
                                            ).showSnackBar(
                                              SnackBar(
                                                content: Text(
                                                  newValue
                                                      ? 'Transport records access granted'
                                                      : 'Transport records access revoked',
                                                ),
                                              ),
                                            );
                                          }
                                        },
                                        child: const Text('CONFIRM'),
                                      ),
                                    ],
                                  ),
                                );
                              },
                            ),
                          // Per-task Truck Repair access editor — replaces
                          // the old single-flag Can Approve Repairs / Can
                          // Manage Repair Payments toggles (still read as a
                          // fallback by hasRepairPerm() for accounts that
                          // predate repairPermissions, but never written to
                          // from here anymore). Not role-gated: any role
                          // except owner (which always has every permission)
                          // can be granted individual Truck Repair tasks.
                          if (role != 'owner' && role != 'admin')
                            IconButton(
                              icon: Icon(
                                Icons.checklist,
                                color: ((data['repairPermissions'] as List?)
                                            ?.isNotEmpty ??
                                        false)
                                    ? Colors.green
                                    : Colors.grey,
                              ),
                              tooltip: 'Truck Repair Access',
                              onPressed: () => pushWebAware(
                                context,
                                TruckRepairAccessScreen(
                                  userId: userId,
                                  userName: (data['name'] ?? 'this user').toString(),
                                  initialPermissions: ((data['repairPermissions']
                                              as List?) ??
                                          const [])
                                      .map((e) => e.toString())
                                      .toSet(),
                                ),
                              ),
                            ),
                          // Quick retrofit for an existing user of ANY role
                          // (not just role == 'technical') — merges in
                          // technicalDefaults()'s repairPermissions (union,
                          // never removes an existing one) and turns Garage
                          // + Warehouse Access ON. Does NOT change role —
                          // this only bundles the permission grant some
                          // "technical-ish" account needs, independent of
                          // the account-type radio in Add User.
                          if (role != 'owner' && role != 'admin')
                            IconButton(
                              icon: const Icon(Icons.engineering, color: Colors.deepOrange),
                              tooltip: 'Apply Technical Defaults',
                              onPressed: () {
                                final userName = (data['name'] ?? 'this user').toString();
                                showDialog(
                                  context: context,
                                  builder: (_) => AlertDialog(
                                    title: const Text('Apply Technical Defaults?'),
                                    content: Text(
                                      'Grants $userName Garage Access, Warehouse Access, and '
                                      'the standard Technical repair tasks (Repair Work, '
                                      'History View, Do Service, Service View). Existing '
                                      'permissions are kept — nothing is removed.',
                                    ),
                                    actions: [
                                      TextButton(
                                        onPressed: () => Navigator.pop(context),
                                        child: const Text('Cancel'),
                                      ),
                                      ElevatedButton(
                                        onPressed: () async {
                                          final defaults = technicalDefaults();
                                          final existingPerms = ((data['repairPermissions']
                                                      as List?) ??
                                                  const [])
                                              .map((e) => e.toString())
                                              .toSet();
                                          final merged = {
                                            ...existingPerms,
                                            ...defaults.repairPermissions,
                                          }.toList();
                                          await FirebaseFirestore.instance
                                              .collection('users')
                                              .doc(userId)
                                              .update({
                                                'repairPermissions': merged,
                                                'canAccessGarage': true,
                                                'canAccessWarehouse': true,
                                              });
                                          if (context.mounted) {
                                            Navigator.pop(context);
                                            ScaffoldMessenger.of(context).showSnackBar(
                                              const SnackBar(
                                                content: Text('Technical defaults applied.'),
                                              ),
                                            );
                                          }
                                        },
                                        child: const Text('APPLY'),
                                      ),
                                    ],
                                  ),
                                );
                              },
                            ),
                          // Not role-gated, unlike the toggles above — Garage
                          // Access (see GarageScreen and AuthGate's routing
                          // override) can be granted to any existing user
                          // regardless of role.
                          IconButton(
                            icon: Icon(
                              Icons.build,
                              color: data['canAccessGarage'] == true
                                  ? Colors.green
                                  : Colors.grey,
                            ),
