                                context: context,
                                builder: (_) => AlertDialog(
                                  title: Text(
                                    currentlyHasAccess
                                        ? 'Revoke Garage Access?'
                                        : 'Grant Garage Access?',
                                  ),
                                  content: Text(
                                    currentlyHasAccess
                                        ? 'Remove Garage access from $userName?'
                                        : 'Allow $userName to access the Garage module?',
                                  ),
                                  actions: [
                                    TextButton(
                                      onPressed: () => Navigator.pop(context),
                                      child: const Text('Cancel'),
                                    ),
                                    ElevatedButton(
                                      onPressed: () async {
