                            },
                          ),
                          // Same pattern as Garage Access above,
                          // independent of it — Warehouse Access (see
                          // WarehouseScreen and AuthGate's routing
                          // override) can be granted to any existing user
                          // regardless of role, and regardless of whether
                          // they also have Garage Access.
                          IconButton(
                            icon: Icon(
                              Icons.warehouse,
                              color: data['canAccessWarehouse'] == true
                                  ? Colors.green
                                  : Colors.grey,
                            ),
                            onPressed: () {
                              final currentlyHasAccess =
                                  data['canAccessWarehouse'] == true;
                              final newValue = !currentlyHasAccess;
                              final userName = data['name'] ?? 'this user';
                              showDialog(
                                context: context,
                                builder: (_) => AlertDialog(
                                  title: Text(
                                    currentlyHasAccess
                                        ? 'Revoke Warehouse Access?'
                                        : 'Grant Warehouse Access?',
                                  ),
                                  content: Text(
                                    currentlyHasAccess
                                        ? 'Remove Warehouse access from $userName?'
                                        : 'Allow $userName to access the Warehouse module?',
                                  ),
                                  actions: [
                                    TextButton(
                                      onPressed: () => Navigator.pop(context),
                                      child: const Text('Cancel'),
                                    ),
                                    ElevatedButton(
                                      onPressed: () async {
                                        await FirebaseFirestore.instance
                                            .collection('users')
                                            .doc(userId)
                                            .update({
                                              'canAccessWarehouse': newValue,
                                            });
                                        if (context.mounted) {
                                          Navigator.pop(context);
                                          ScaffoldMessenger.of(
