// Lets an Admin/Owner change which sites an existing 'unloading_site' user
// can see in UnloadingSiteViewerScreen, without needing to delete and
// recreate the account (the role value itself still has no post-creation
// edit path, same as every other role here — only this per-role list field
// gets one, since site assignment is expected to change over time).
void _showEditUnloadingSitesDialog({
  required BuildContext context,
  required String userId,
  required String userName,
  required Set<String> currentSiteIds,
}) {
  final selected = Set<String>.from(currentSiteIds);
  showDialog(
    context: context,
    builder: (dialogContext) => StatefulBuilder(
      builder: (dialogContext, setDialogState) => AlertDialog(
        title: Text('Unloading Sites — $userName'),
        content: SizedBox(
          width: 360,
          child: StreamBuilder<QuerySnapshot>(
            stream: ReferenceCollectionCache.stream('sites'),
            builder: (context, snapshot) {
              if (!snapshot.hasData) {
                return const Padding(
                  padding: EdgeInsets.all(12),
                  child: Center(child: CircularProgressIndicator()),
                );
              }
              final sites = snapshot.data!.docs.where((doc) {
                final d = doc.data() as Map<String, dynamic>;
                return d['canBeUnloadingSite'] != false;
              }).toList();
              if (sites.isEmpty) {
                return const Padding(
                  padding: EdgeInsets.all(12),
                  child: Text('No unloading sites found.'),
                );
              }
              return SingleChildScrollView(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: sites.map((doc) {
                    final d = doc.data() as Map<String, dynamic>;
                    final siteName = (d['name'] ?? '').toString();
                    return CheckboxListTile(
                      title: Text(siteName),
                      value: selected.contains(doc.id),
                      contentPadding: EdgeInsets.zero,
                      controlAffinity: ListTileControlAffinity.leading,
                      onChanged: (val) => setDialogState(() {
                        if (val == true) {
                          selected.add(doc.id);
                        } else {
                          selected.remove(doc.id);
                        }
                      }),
                    );
                  }).toList(),
                ),
              );
            },
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext),
            child: const Text('Cancel'),
          ),
          ElevatedButton(
            onPressed: () async {
              await FirebaseFirestore.instance
                  .collection('users')
                  .doc(userId)
                  .update({'unloadingSiteIds': selected.toList()});
              if (dialogContext.mounted) Navigator.pop(dialogContext);
            },
            child: const Text('SAVE'),
          ),
        ],
      ),
    ),
  );
}

