// ---------------- MANAGEMENT DASHBOARD (web-only) ----------------
// Management accounts can only sign in on the web build (see AuthGate and
// LoginScreen._login, which force-signOut and block this role on mobile).
class ManagementDashboard extends StatefulWidget {
  final String name;
  const ManagementDashboard({super.key, required this.name});

  @override
  State<ManagementDashboard> createState() => _ManagementDashboardState();
}

class _ManagementDashboardState extends State<ManagementDashboard> {
  // Gates the Transport Records and Garage sidebar/card items — fetched
  // once on mount rather than blocking the whole dashboard body behind a
  // FutureBuilder, so the items just appear a moment after load for
  // eligible users instead of delaying everything else.
  bool _canAccessTransportRecords = false;
  // AuthGate's isolated-override exemption for role == 'management' (see
  // its doc comment) means a management account with canAccessGarage: true
  // lands here, not on GarageScreen directly — this is what makes Garage
  // reachable as an additive item instead, same as Admin/Owner already get.
  bool _canAccessGarage = false;
  // Truck Repair v2 tiles below — gated by the same repairPermissions
  // array as TruckRepairHubScreen/TechnicalHomeScreen, fetched off the
  // same user doc read _loadAccessFlags already does (no extra Firestore
  // read).
  bool _hasApprove = false;
  bool _hasServiceApprove = false;
  bool _hasServiceView = false;
  // Gates the Manage Access tile — ManagementDashboard is only ever
  // reached by role == 'management' in practice (same as the comment on
  // _loadAccessFlags below), but checked explicitly rather than assumed,
  // since ManageAccessScreen itself is also open to admin/owner from
  // elsewhere and this flag is specifically "is this account the
  // restricted-management kind of grantor".
  bool _isManagement = false;

  @override
  void initState() {
    super.initState();
    _loadAccessFlags();
  }

  // ManagementDashboard is only ever reached by role == 'management'
  // accounts (Admin/Owner have their own dashboards with an unconditional
  // Transport Records item), so the isAdminOrOwner branch here is a no-op
  // in practice — kept explicit anyway so this matches the same
  // isAdminOrOwner || (isManagement && canAccessTransportRecords) pattern
  // used by TransportSummaryScreen's route guard and TransportRecordsScreen's.
  Future<void> _loadAccessFlags() async {
    try {
      final doc = await FirebaseFirestore.instance
          .collection('users')
          .doc(FirebaseAuth.instance.currentUser!.uid)
          .get();
      final data = doc.data();
      final role = data?['role'] as String?;
      final isAdminOrOwner = role == 'admin' || role == 'owner';
      final isManagement = role == 'management';
      if (mounted) {
        setState(() {
          _canAccessTransportRecords =
              isAdminOrOwner ||
              (isManagement && data?['canAccessTransportRecords'] == true);
          _canAccessGarage =
              isAdminOrOwner || (isManagement && data?['canAccessGarage'] == true);
          _hasApprove = hasRepairPerm(data, kPermApprove);
          _hasServiceApprove = hasRepairPerm(data, kPermServiceApprove);
          _hasServiceView = hasRepairPerm(data, kPermServiceView);
          _isManagement = isManagement;
        });
      }
    } catch (_) {
      // Leave the items hidden if this fails.
    }
  }

  Future<void> _logout() async {
    await FirebaseAuth.instance.signOut();
    if (mounted) {
      Navigator.pushReplacement(
        context,
        MaterialPageRoute(builder: (_) => const LoginScreen()),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    // WebAppShell only renders `menuItems` as a sidebar on wide desktop-web
    // viewports (see its own doc comment) — on anything narrower (a phone
    // browser, a resized window) it renders just this `child` instead, so
    // this card grid is what actually makes these items reachable there.
    // Same _WebStaggeredFadeIn/DashboardMenuCard pattern Admin/OwnerDashboard
    // use for their own mobile card grids.
    final bodyContent = SingleChildScrollView(
      padding: const EdgeInsets.all(24.0),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            'Welcome, ${widget.name}',
            style: const TextStyle(fontSize: 20, fontWeight: FontWeight.bold),
          ),
          const SizedBox(height: 20),
          const ServiceAlertsBanner(),
          const ServiceFleetSummaryCounts(),
          const RepairFleetSummaryCounts(),
          _WebStaggeredFadeIn(
            index: 0,
            child: DashboardMenuCard(
              icon: Icons.local_gas_station,
              title: 'Fuel Reports',
              subtitle: 'Filterable report, chart and Excel export',
              color: Colors.deepOrange,
              onTap: () => Navigator.push(
                context,
                MaterialPageRoute(
                  builder: (_) => const ManagementFuelReportsScreen(),
                ),
              ),
            ),
          ),
          const SizedBox(height: 12),
          _WebStaggeredFadeIn(
            index: 1,
            child: DashboardMenuCard(
              icon: Icons.location_on,
              title: 'Site Reports',
              subtitle: 'Filterable report, chart and Excel export',
              color: Colors.teal,
              onTap: () => Navigator.push(
                context,
                MaterialPageRoute(
                  builder: (_) => const ManagementSiteReportsScreen(),
                ),
              ),
            ),
          ),
          const SizedBox(height: 12),
          _WebStaggeredFadeIn(
            index: 2,
            child: DashboardMenuCard(
              icon: Icons.map,
              title: 'Live Tracking',
              subtitle: 'GPS map, truck/site markers and route history',
              color: Colors.blueGrey,
              onTap: () => Navigator.push(
                context,
                MaterialPageRoute(builder: (_) => const LiveTrackingScreen()),
              ),
            ),
          ),
          const SizedBox(height: 12),
          // Broad management access on purpose (isAdminOrOwner() ||
          // isManagement() in firestore.rules) — no canAccessX permission
          // flag gating this, unlike Transport Records/Garage below.
          _WebStaggeredFadeIn(
            index: 3,
            child: DashboardMenuCard(
              icon: Icons.route,
              title: 'Route Distances',
              subtitle: 'Admin-configured Company Load distances',
              color: Colors.teal,
              onTap: () => Navigator.push(
                context,
                MaterialPageRoute(
                  builder: (_) => const RouteDistanceManagementScreen(),
