  // Internal QC flag only — never triggers GoogleSheetsService.sendRow, the
  // Sheets sync is unrelated to this. Same tick-vs-untick confirmation
  // wording as ManagementFuelReportsScreen's version, kept in sync.
  Future<void> _toggleVerification(
    DocumentReference ref,
    bool currentlyVerified,
    String currentUserName,
  ) async {
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
        title: Text(
          currentlyVerified ? 'Remove Verification?' : 'Mark as Verified?',
        ),
        content: Text(
          currentlyVerified
              ? 'This will mark the report as unverified. Continue?'
              : 'Confirm this report is correct and verified?',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('Cancel'),
          ),
          ElevatedButton(
            onPressed: () => Navigator.pop(dialogContext, true),
            child: const Text('CONFIRM'),
          ),
        ],
      ),
    );
    if (confirmed != true) return;

    try {
      final nowVerified = !currentlyVerified;
      await ref.update({
        'isVerified': nowVerified,
        'verifiedBy': nowVerified ? currentUserName : null,
        'verifiedAt': nowVerified ? FieldValue.serverTimestamp() : null,
      });
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              nowVerified ? 'Marked as verified.' : 'Verification removed.',
            ),
          ),
        );
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text('Failed to update: $e')));
      }
    }
  }

  // Firestore-only delete — deliberately never touches Google Sheets (no
  // GoogleSheetsService call anywhere here), so removing a row from the
  // synced sheet is left to manual cleanup if that's ever needed. Works
  // uniformly for either source a record can come from — a top-level
  // manual_site_reports doc, or a nested
  // daily_sessions/{id}/work_records/{id} doc — since `ref` is always the
  // record's own correct DocumentReference (see _enrichRecords and the
  // manual-records mapping in build(), both of which set data['_ref'] to
  // doc.reference). Both source streams are live .snapshots(), so deleting
  // the doc removes it from the table automatically on the next snapshot —
  // no manual refetch needed.
  Future<void> _deleteRecord(DocumentReference ref) async {
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
        title: const Text('Delete Report?'),
        content: const Text(
          'Are you sure you want to permanently delete this report record? '
          'This action cannot be undone.',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('Cancel'),
          ),
          ElevatedButton(
            onPressed: () => Navigator.pop(dialogContext, true),
            style: ElevatedButton.styleFrom(backgroundColor: Colors.red),
            child: const Text('DELETE', style: TextStyle(color: Colors.white)),
          ),
        ],
      ),
    );
    if (confirmed != true) return;

    try {
      // unloading_feed cleanup — reads the doc's own stored unloadingSiteId
      // first (forward-fixed records always have it); falls back to
      // resolving the current unloadingSiteName if an older record never
      // got one (see RebuildUnloadingFeedScreen's "remove orphans" option
      // for anything this can't resolve, e.g. the site was renamed since).
      final snap = await ref.get();
      final snapData = snap.data() as Map<String, dynamic>?;
      final deleteBatch = _db.batch();
      if (snapData != null) {
        final siteId = await _resolveUnloadingSiteId(
          snapData['unloadingSiteId'] as String?,
          snapData['unloadingSiteName'] as String?,
        );
        if (siteId != null) {
          _stageUnloadingFeedDelete(
            batch: deleteBatch,
            siteId: siteId,
            recordId: ref.id,
          );
        }
      }
      deleteBatch.delete(ref);
      await deleteBatch.commit();
      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(const SnackBar(content: Text('Report deleted')));
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text('Failed to delete report: $e')));
      }
    }
  }

  // Backup fallback for when GPS arrival detection fails to fire — lets
  // Admin/Owner/Management (same canEdit gate as Edit/Delete) manually flip
  // an Active load to Completed. manuallyCompleted: true distinguishes this
  // from AutoArrivalDetectionService's own GPS-triggered writes (see
  // _completedBillBadge's "(Manual)" label above). Sync block below mirrors
  // _showEditRecordDialog's own Supervisor_Loads/Plant_Loads/site-specific
  // sheet sync exactly (same syncRow shape, same recordId-keyed
  // update-in-place calls) so a manual completion shows up in the same
  // sheets an edit would touch.
  Future<void> _markAsCompleted(
    DocumentReference ref,
    Map<String, dynamic> data,
    String currentUserName,
  ) async {
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
        title: const Text('Mark as Completed?'),
        content: const Text(
          'Mark this load as Completed manually? This action confirms the '
          'truck has reached the unloading site.',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('Cancel'),
          ),
          ElevatedButton(
            onPressed: () => Navigator.pop(dialogContext, true),
            style: ElevatedButton.styleFrom(
              backgroundColor: Colors.green[700],
            ),
            child: const Text(
              'CONFIRM',
              style: TextStyle(color: Colors.white),
            ),
          ),
        ],
      ),
    );
    if (confirmed != true) return;

    try {
      // unloading_feed refresh — same reasoning as
      // _WorkSessionScreenState's _completeLoadingRecord: a completion
      // write only, the site itself isn't changing, so this just refreshes
      // 'time' to the real (manual) completion moment.
      final completeBatch = _db.batch();
      await _reconcileUnloadingFeedEntry(
        batch: completeBatch,
        recordId: ref.id,
        oldSiteId: data['unloadingSiteId'] as String?,
        pickedSiteId: data['unloadingSiteId'] as String?,
        unloadingSiteName: data['unloadingSiteName'] as String?,
        billNumber: (data['billNumber'] ?? '').toString(),
        lorryNumber: (data['truckNumber'] ?? '').toString(),
        date: (data['date'] ?? '').toString(),
        time: FieldValue.serverTimestamp(),
        sourceType: 'work_record',
      );
      completeBatch.update(ref, {
        'isCompleted': true,
        'loadCompletedAt': FieldValue.serverTimestamp(),
        'isVerified': true,
        'manuallyCompleted': true,
        'completedByName': currentUserName,
      });
      await completeBatch.commit();

      final merged = {...data, 'isCompleted': true, 'isVerified': true};
      final syncRow = [
        (merged['date'] ?? '').toString(),
        (merged['machineName'] ?? '').toString(),
        (merged['siteName'] ?? '').toString(),
        (merged['supervisorName'] ?? '').toString(),
        (merged['category'] ?? '').toString(),
        (merged['truckNumber'] ?? '').toString(),
        (merged['billNumber'] ?? '').toString(),
        (merged['unloadingSiteName'] ?? '').toString(),
        merged['distanceKm']?.toString() ?? '',
        merged['startMeter']?.toString() ?? '',
        merged['endMeter']?.toString() ?? '',
        _formatSyncDuration((merged['totalDurationSeconds'] ?? 0) as int),
        GoogleSheetsService.formatTime(merged['loadStartedAt']),
        GoogleSheetsService.formatTime(Timestamp.now()),
        (merged['truckDriverName'] ?? '').toString(),
        (merged['cubeCount'] ?? '').toString(),
        (merged['machineOperatorName'] ?? '').toString(),
      ];
      GoogleSheetsService.sendRow(
        sheetName: 'Supervisor_Loads',
        row: syncRow,
        recordId: ref.id,
      );

      final siteName = (merged['siteName'] ?? '').toString();
      final siteQuery = await _db
          .collection('sites')
          .where('name', isEqualTo: siteName)
          .limit(1)
          .get();
      final siteData = siteQuery.docs.isNotEmpty
          ? siteQuery.docs.first.data()
          : null;
      final isPlantSite = siteData?['isPlantSite'] == true;
      final siteSpecificMatch =
          (siteData?['sheetName'] as String?) ??
          kSiteSheetMap[normalizeSiteNameForSheetLookup(siteName)];
      if (isPlantSite) {
        GoogleSheetsService.sendRow(
          sheetName: 'Plant_Loads',
          row: syncRow,
          recordId: ref.id,
        );
      }
      if (siteSpecificMatch != null) {
        GoogleSheetsService.sendRow(
          sheetName: siteSpecificMatch,
          row: syncRow,
          recordId: ref.id,
        );
      }

      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Load marked as completed manually.'),
          ),
        );
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Failed to mark as completed: $e')),
        );
      }
    }
  }

  Widget _buildTable(
    List<Map<String, dynamic>> records,
    bool canEdit,
    String currentUserName, {
    int startIndex = 0,
    required Map<String, String> siteNameById,
    bool showMeters = false,
  }) {
    final truckNumberColIndex = 1 + _columns.indexOf('Truck Number');
    final billNumberColIndex = 1 + _columns.indexOf('Bill Number');
    final siteColIndex = 1 + _columns.indexOf('Site');
    final distanceColIndex = 1 + _columns.indexOf('Distance KM');

    return SingleChildScrollView(
      scrollDirection: Axis.horizontal,
      child: DataTable(
        // '#' is column 0, Verified (when shown) is column 1.
        sortColumnIndex: _sortColumn == null
            ? null
            : (canEdit ? 2 : 1) + _columns.indexOf(_sortColumn!),
        sortAscending: _sortAscending,
        columns: [
          const DataColumn(
            label: Text('#', style: TextStyle(fontWeight: FontWeight.bold)),
          ),
          if (canEdit)
            const DataColumn(
              label: Text(
                'Verified',
                style: TextStyle(fontWeight: FontWeight.bold),
              ),
            ),
          ..._columns.asMap().entries.map((entry) {
            final colIndex = entry.key + 1;
            final sortable =
                colIndex == truckNumberColIndex ||
                colIndex == billNumberColIndex;
            return DataColumn(
              label: Text(
                entry.value,
                style: const TextStyle(fontWeight: FontWeight.bold),
              ),
              onSort: sortable
                  ? (_, ascending) => setState(() {
                      _sortColumn = entry.value;
                      _sortAscending = ascending;
                    })
                  : null,
            );
          }),
          if (showMeters)
            for (final label in kSiteReportMeterColumns)
              DataColumn(
                label: Text(
                  label,
                  style: const TextStyle(fontWeight: FontWeight.bold),
                ),
              ),
          if (canEdit)
            const DataColumn(
              label: Text(
                'Actions',
                style: TextStyle(fontWeight: FontWeight.bold),
              ),
            ),
        ],
        rows: records.asMap().entries.map((rowEntry) {
          final rowIndex = rowEntry.key;
          final data = rowEntry.value;
          final values = _rowValues(data, siteNameById);
          final isVerified = data['isVerified'] == true;
          final isManual = data['isManualEntry'] == true;
          final meterReversed = showMeters && isMeterReversed(data);
          return DataRow(
            color: meterReversed && data['loadType'] != 'private'
                ? WidgetStateProperty.all(kMeterReversedRowColor)
                : _rowStripeColor(
                    rowIndex,
                    isPrivateLoad: data['loadType'] == 'private',
                  ),
            cells: [
              DataCell(Text('${startIndex + rowIndex + 1}')),
              if (canEdit)
                DataCell(
                  IconButton(
                    icon: Icon(
                      isVerified
                          ? Icons.check_circle
                          : Icons.radio_button_unchecked,
                      color: isVerified ? Colors.green : Colors.grey,
                    ),
                    onPressed: () => _toggleVerification(
                      data['_ref'] as DocumentReference,
                      isVerified,
                      currentUserName,
                    ),
                  ),
                ),
              ...values.asMap().entries.map((v) {
                final colIndex = v.key + 1;
                final text = (colIndex == siteColIndex && isManual)
                    ? '${v.value} (Manual)'
                    : v.value;
                return DataCell(
                  colIndex == billNumberColIndex
                      ? Row(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            Text(text),
                            if (data['isCompleted'] == true) ...[
                              _completedBillBadge(),
                              if (data['manuallyCompleted'] == true)
                                const Padding(
                                  padding: EdgeInsets.only(left: 4),
                                  child: Text(
                                    '(Manual)',
                                    style: TextStyle(
                                      fontSize: 10,
                                      fontStyle: FontStyle.italic,
                                      color: Colors.grey,
                                    ),
                                  ),
                                ),
                            ] else if (!isManual)
                              _activeBillBadge(),
                          ],
                        )
                      : colIndex == distanceColIndex
                      ? _distanceKmCellContent(text, data)
                      : Text(text),
                );
              }),
              if (showMeters) ...[
                DataCell(Text(formatMeterReading(data['startMeter']))),
                DataCell(
                  meterReversed
                      ? Tooltip(
                          message: 'End Meter is less than Start Meter',
                          child: Text(
                            formatMeterReading(data['endMeter']),
                            style: TextStyle(
                              color: Colors.red[800],
                              fontWeight: FontWeight.bold,
                            ),
                          ),
                        )
                      : Text(formatMeterReading(data['endMeter'])),
                ),
              ],
              if (canEdit)
                DataCell(
                  Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      if (data['isCompleted'] != true)
                        IconButton(
                          icon: Icon(
                            Icons.check_circle_outline,
                            color: Colors.green[700],
                          ),
                          tooltip: 'Mark as Completed',
                          onPressed: () => _markAsCompleted(
                            data['_ref'] as DocumentReference,
                            data,
                            currentUserName,
                          ),
                        ),
                      IconButton(
                        icon: const Icon(
                          Icons.edit,
                          color: AppTheme.primaryMid,
                        ),
                        onPressed: () => _showEditRecordDialog(
                          data['_ref'] as DocumentReference,
                          data,
                        ),
                      ),
                      IconButton(
                        icon: const Icon(Icons.delete, color: Colors.red),
                        onPressed: () =>
                            _deleteRecord(data['_ref'] as DocumentReference),
                      ),
                    ],
                  ),
                ),
            ],
          );
        }).toList(),
      ),
    );
  }

  // Records created before the 'date'/'machineName'/'siteName'/
  // 'supervisorName' denormalization only have these fields on their parent
  // daily_sessions doc. Backfill just those, and only for records that are
  // actually missing them — already-denormalized records skip the fetch
  // entirely, and each parent session is only ever fetched once (cached in
  // _sessionDocCache) even though several of its records may be missing
  // fields.
  Future<List<Map<String, dynamic>>> _enrichRecords(
    List<QueryDocumentSnapshot> docs,
  ) async {
    final results = <Map<String, dynamic>>[];
    // (record, its parent session ref) for every record missing a
    // denormalized field — siteId is never stored on the record itself
    // (see RouteDistanceManagementScreen's doc comment on _enrichRecords),
    // so this is every record on every load, not just older/legacy ones.
    final pending = <(Map<String, dynamic>, DocumentReference)>[];
    // One Future per DISTINCT session id, fired together below via
    // Future.wait instead of one sequential await per record — with many
    // records sharing a handful of sessions, awaiting them one at a time
    // in the loop (the previous shape) meant total load time scaled with
    // record count instead of distinct-session count, which is what made
    // this screen feel slow to load.
    final sessionFetches = <String, Future<DocumentSnapshot>>{};

    for (final doc in docs) {
      final data = Map<String, dynamic>.from(
        doc.data() as Map<String, dynamic>,
      );
      // Kept for the Edit action (Part C) so it can write back to this exact
      // work_record doc. _rowValues() only reads specific named fields, so
      // this extra key never leaks into the table text or Excel export.
      data['_ref'] = doc.reference;
      final missingDenormalized =
          data['date'] == null ||
          data['machineName'] == null ||
          data['siteName'] == null ||
          data['supervisorName'] == null ||
          data['siteId'] == null;

      if (missingDenormalized) {
        final sessionRef = doc.reference.parent.parent;
        if (sessionRef != null) {
          pending.add((data, sessionRef));
          sessionFetches.putIfAbsent(
            sessionRef.id,
            () => _sessionDocCache.putIfAbsent(
              sessionRef.id,
              () => sessionRef.get(),
            ),
          );
        }
      }

      results.add(data);
    }

    if (sessionFetches.isNotEmpty) {
      try {
        await Future.wait(sessionFetches.values);
      } catch (_) {
        // A single failed session read is handled per-record below —
        // this only stops it from aborting the whole parallel batch.
      }
    }

    for (final (data, sessionRef) in pending) {
      try {
        final sessionDoc = await sessionFetches[sessionRef.id]!;
        final sessionData = sessionDoc.data() as Map<String, dynamic>?;
        if (sessionData != null) {
          data['date'] ??= sessionData['date'];
          data['machineName'] ??= sessionData['machineName'];
          data['siteName'] ??= sessionData['siteName'];
          data['supervisorName'] ??= sessionData['supervisorName'];
          data['siteId'] ??= sessionData['siteId'];
        }
      } catch (_) {
        // Leave fields missing if the parent session can't be read.
      }
    }

    return results;
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Site Reports'),
        backgroundColor: Colors.teal[800],
      ),
      body: FutureBuilder<DocumentSnapshot>(
        future: _currentUserFuture,
        builder: (context, userSnap) {
          final userData = userSnap.data?.data() as Map<String, dynamic>?;
          final role = userData?['role'] as String?;
          final canEdit =
              role == 'admin' ||
              role == 'owner' ||
              (role == 'management' && userData?['canEditReports'] == true);

          return StreamBuilder<QuerySnapshot>(
            stream: _workRecordsStream,
            builder: (context, snapshot) {
              // Only the true first load (no previous snapshot at all) gets
              // the spinner — once any data has been shown, a later
              // reconnect/metadata-only emission must never blank the
              // screen back to a spinner while real data is still on
              // screen underneath.
              if (snapshot.connectionState == ConnectionState.waiting &&
                  !snapshot.hasData &&
                  _lastSnapshot == null) {
                return const Center(child: CircularProgressIndicator());
              }
              if (snapshot.hasError) {
                return Center(
                  child: Text('Error loading records: ${snapshot.error}'),
                );
              }

              if (!identical(snapshot.data, _lastSnapshot)) {
                _lastSnapshot = snapshot.data;
                _enrichedFuture = _enrichRecords(snapshot.data?.docs ?? []);
              }

              return FutureBuilder<List<Map<String, dynamic>>>(
                future: _enrichedFuture,
                builder: (context, enrichSnap) {
                  if (!enrichSnap.hasData) {
                    return const Center(child: CircularProgressIndicator());
                  }

                  final workRecords = enrichSnap.data!;

                  // Manual "+ Add Report" entries (Part E) live in a separate
                  // top-level collection — merged client-side into the same
                  // filtered/sorted list the collectionGroup('work_records')
                  // query produces above, rather than trying to make one
                  // Firestore query span both collections.
                  return StreamBuilder<QuerySnapshot>(
                    stream: _manualSiteReportsStream,
                    builder: (context, manualSnap) {
                      final manualRecords = (manualSnap.data?.docs ?? []).map((
                        d,
                      ) {
                        final data = Map<String, dynamic>.from(
                          d.data() as Map<String, dynamic>,
                        );
                        data['_ref'] = d.reference;
                        return data;
                      }).toList();

                      final allRecords = [...workRecords, ...manualRecords];

                      // "Sort By" filters-row dropdown — a top-level sort
                      // preference. Both the table and the chart, plus Excel
                      // export, all read from this same sorted `filtered`
                      // list, so the choice applies everywhere automatically.
                      final filtered = allRecords
                          .where((d) => _matchesFilters(d, _siteNameById))
                          .toList();
                      if (_selectedSortBy == 'truckNumber') {
                        filtered.sort(
                          (a, b) => _naturalCompare(
                            (a['truckNumber'] ?? '').toString(),
                            (b['truckNumber'] ?? '').toString(),
                          ),
                        );
                      } else if (_selectedSortBy == 'billNumber') {
                        filtered.sort(
                          (a, b) => _naturalCompare(
                            (a['billNumber'] ?? '').toString(),
                            (b['billNumber'] ?? '').toString(),
                          ),
                        );
                      } else {
                        // Default: date ascending, then same-day records by
                        // when the load actually started (falling back to
                        // createdAt if that's missing) — oldest first,
                        // matching the Supervisor_Loads sheet's row order.
                        // Manual entries have no loadStartedAt, so they fall
                        // back to createdAt too.
                        filtered.sort((a, b) {
                          final dateCompare = (a['date'] ?? '')
                              .toString()
                              .compareTo((b['date'] ?? '').toString());
                          if (dateCompare != 0) return dateCompare;

                          final aTime =
                              (a['loadStartedAt'] as Timestamp?) ??
                              (a['createdAt'] as Timestamp?);
                          final bTime =
                              (b['loadStartedAt'] as Timestamp?) ??
                              (b['createdAt'] as Timestamp?);
                          if (aTime == null && bTime == null) return 0;
                          if (aTime == null) return -1;
                          if (bTime == null) return 1;
                          return aTime.compareTo(bTime);
                        });
                      }

                      // Truck Number / Bill Number header-click sort (Part D)
                      // — applied after the chronological default sort
                      // above, only when the user has actually clicked one
                      // of those headers.
                      if (_sortColumn != null) {
                        final sortField = _sortFieldByColumn[_sortColumn];
                        if (sortField != null) {
                          filtered.sort((a, b) {
                            final cmp = _naturalCompare(
                              (a[sortField] ?? '').toString(),
                              (b[sortField] ?? '').toString(),
                            );
                            return _sortAscending ? cmp : -cmp;
                          });
                        }
                      }

                      final sig =
                          '$_dateRange|$_allTime|$_selectedSiteId|$_selectedMachineName|$_truckNumberFilter|$_billNumberFilter|$_selectedOperatorName|$_selectedUnloadingSite|$_selectedSortBy|$_sortColumn|$_sortAscending|$_pageSize';
                      if (sig != _filterSig) {
                        _filterSig = sig;
                        _page = 0;
                      }
                      final totalPages = filtered.isEmpty
                          ? 1
                          : (filtered.length + _pageSize - 1) ~/ _pageSize;
                      if (_page >= totalPages) _page = totalPages - 1;
                      final pageStart = _page * _pageSize;
                      final pageEnd = (pageStart + _pageSize) > filtered.length
                          ? filtered.length
                          : pageStart + _pageSize;
                      final pageRecords = filtered.sublist(pageStart, pageEnd);

                      return SingleChildScrollView(
                        padding: const EdgeInsets.all(16),
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            _buildFiltersRow(allRecords, _siteNameById),
                            const SizedBox(height: 20),
                            if (canEdit) ...[
                              SizedBox(
                                width: 200,
                                child: GradientButton(
                                  label: '+ Add Report',
                                  icon: Icons.add,
                                  height: 44,
                                  onTap: () => _showAddReportDialog(
                                    (userData?['name'] ?? '').toString(),
                                  ),
                                ),
                              ),
                              const SizedBox(height: 16),
                            ],
                            Row(
                              mainAxisAlignment: MainAxisAlignment.spaceBetween,
                              children: [
                                Text(
                                  '${filtered.length} records',
                                  style: const TextStyle(
                                    fontWeight: FontWeight.bold,
                                  ),
                                ),
                                SizedBox(
                                  width: 200,
                                  child: GradientButton(
                                    label: 'Export to Excel',
                                    icon: Icons.download,
                                    height: 44,
                                    onTap: filtered.isEmpty
                                        ? () {}
                                        : () => _exportToExcel(filtered, _siteNameById),
                                  ),
                                ),
                              ],
                            ),
                            const SizedBox(height: 16),
                            _buildChart(filtered),
                            const SizedBox(height: 20),
                            _buildTable(
                              pageRecords,
                              canEdit,
                              (userData?['name'] ?? '').toString(),
                              startIndex: pageStart,
                              siteNameById: _siteNameById,
                              showMeters: canViewReportMeters(role),
                            ),
                            const SizedBox(height: 12),
                            Row(
                              mainAxisAlignment: MainAxisAlignment.end,
                              children: [
                                const Text('Rows per page: '),
                                DropdownButton<int>(
                                  value: _pageSize,
                                  items: [25, 50, 100]
                                      .map(
                                        (n) => DropdownMenuItem<int>(
                                          value: n,
                                          child: Text('$n'),
                                        ),
                                      )
                                      .toList(),
                                  onChanged: (v) {
                                    if (v != null) {
                                      setState(() => _pageSize = v);
                                    }
                                  },
                                ),
                                const SizedBox(width: 16),
                                Text(
                                  filtered.isEmpty
                                      ? '0 of 0'
                                      : '${pageStart + 1}-$pageEnd of ${filtered.length}',
                                ),
                                IconButton(
                                  icon: const Icon(Icons.chevron_left),
                                  onPressed: _page > 0
                                      ? () => setState(() => _page--)
                                      : null,
                                ),
                                IconButton(
                                  icon: const Icon(Icons.chevron_right),
                                  onPressed: _page < totalPages - 1
                                      ? () => setState(() => _page++)
                                      : null,
                                ),
                              ],
                            ),
                          ],
                        ),
                      );
                    },
                  );
                },
              );
            },
          );
        },
      ),
    );
  }
}

// ---------------- SHARED WEB DASHBOARD TOP BAR ----------------
// Used by the professional web layouts (ManagementDashboard, OwnerDashboard's
// desktop-web view). Fetches the current user's own doc once (for the
// profile photo) rather than on every rebuild.
class _DashboardTopBar extends StatefulWidget {
  final String name;
  final String roleLabel;
  final VoidCallback onLogout;

  const _DashboardTopBar({
    required this.name,
    required this.roleLabel,
    required this.onLogout,
  });

  @override
  State<_DashboardTopBar> createState() => _DashboardTopBarState();
}

class _DashboardTopBarState extends State<_DashboardTopBar> {
  late final Future<DocumentSnapshot> _userFuture;

  @override
