                                else if (!isRunning)
                                  Row(
                                    children: [
                                      Expanded(
                                        child: OutlinedButton.icon(
                                          onPressed: () =>
                                              _resumeRecord(doc.id),
                                          icon: const Icon(Icons.play_arrow),
                                          label: const Text('RESUME'),
                                        ),
                                      ),
                                      if (data['isLoadingCategory'] ==
                                          true) ...[
                                        const SizedBox(width: 8),
                                        Expanded(
                                          child: ElevatedButton.icon(
                                            onPressed: () {
                                              if (isCompanyLoadingTask) {
                                                _finishLoadingPhase(doc.id);
                                              } else {
                                                _completeLoadingRecord(doc.id);
                                              }
                                            },
                                            icon: const Icon(
                                              Icons.check,
                                              color: Colors.white,
                                            ),
                                            label: const Text(
                                              'COMPLETE',
                                              style: TextStyle(
                                                color: Colors.white,
                                              ),
                                            ),
                                            style: ElevatedButton.styleFrom(
                                              backgroundColor:
                                                  Colors.green[700],
                                            ),
                                          ),
                                        ),
                                      ],
                                    ],
                                  )
                                else if (isRunning)
                                  Row(
                                    children: [
                                      Expanded(
                                        child: OutlinedButton.icon(
                                          onPressed: () =>
                                              _pauseRunningRecord(),
                                          icon: const Icon(Icons.pause),
                                          label: const Text('PAUSE'),
                                        ),
                                      ),
                                      if (data['isLoadingCategory'] ==
                                          true) ...[
                                        const SizedBox(width: 8),
                                        Expanded(
                                          child: ElevatedButton.icon(
                                            onPressed: () {
                                              if (isCompanyLoadingTask) {
                                                _finishLoadingPhase(doc.id);
                                              } else {
                                                _completeLoadingRecord(doc.id);
                                              }
                                            },
                                            icon: const Icon(
                                              Icons.check,
                                              color: Colors.white,
                                            ),
                                            label: const Text(
                                              'COMPLETE',
                                              style: TextStyle(
                                                color: Colors.white,
                                              ),
                                            ),
                                            style: ElevatedButton.styleFrom(
                                              backgroundColor:
                                                  Colors.green[700],
                                            ),
                                          ),
                                        ),
                                      ],
                                    ],
                                  ),
                              ],
                            ),
                          ),
                        ),
                      ),
                    );
                  },
                );

                if (!isWideWeb) return list;
                return Center(
                  child: ConstrainedBox(
                    constraints: const BoxConstraints(maxWidth: 800),
                    child: list,
                  ),
                );
              },
            ),
          ),
        ],
      ),
      floatingActionButton: isWideWeb
          ? null
          : FloatingActionButton.extended(
              onPressed: _showNewWorkDialog,
              backgroundColor: Colors.orange[800],
              icon: const Icon(Icons.add, color: Colors.white),
              label: const Text(
                'NEW WORK',
                style: TextStyle(color: Colors.white),
              ),
            ),
      bottomNavigationBar: SafeArea(
        child: Padding(
          padding: const EdgeInsets.all(12.0),
          child: SizedBox(
            width: double.infinity,
            height: 48,
            child: ElevatedButton.icon(
              onPressed: _showEndDayDialog,
              icon: const Icon(Icons.flag, color: Colors.white),
              label: const Text(
                'END DAY',
                style: TextStyle(
                  color: Colors.white,
                  fontWeight: FontWeight.bold,
                ),
              ),
              style: ElevatedButton.styleFrom(backgroundColor: Colors.red[700]),
            ),
          ),
        ),
      ),
    );
  }
}

// ---------------- QR SCANNER SCREEN (WorkSessionScreen's QR Scan) ----------------
// Full-screen camera scanner. Works on both mobile and web — mobile_scanner
// uses the browser's camera API on web (kIsWeb) automatically, no separate
// codepath needed. Pops with the first successfully-decoded raw QR string,
// or null if the supervisor backs out without scanning anything.
class _QrScannerScreen extends StatefulWidget {
  const _QrScannerScreen();

  @override
  State<_QrScannerScreen> createState() => _QrScannerScreenState();
}

class _QrScannerScreenState extends State<_QrScannerScreen> {
  bool _handled = false;

  void _onDetect(BarcodeCapture capture) {
    if (_handled || capture.barcodes.isEmpty) return;
    final rawValue = capture.barcodes.first.rawValue;
    if (rawValue == null) return;
    _handled = true;
    Navigator.pop(context, rawValue);
  }

  // Without this, MobileScanner falls back to its own default error UI,
  // which for anything other than the few specifically-recognized native
  // error codes (permission denied, no camera, already started) just shows
  // "An unexpected error occurred." — MobileScannerException.errorDetails
  // carries the real underlying PlatformException code/message even in
  // that generic-error case, so this surfaces that instead, and gives a
  // way back out rather than leaving the supervisor stuck on a dead screen.
  String _describeError(MobileScannerException error) {
    switch (error.errorCode) {
      case MobileScannerErrorCode.permissionDenied:
        return 'Camera permission was denied. Please allow camera access '
            'for this app in your device settings and try again.';
      case MobileScannerErrorCode.unsupported:
        return 'No camera is available on this device.';
      default:
        final detail = error.errorDetails?.message;
        return 'Could not open the camera'
            '${detail != null && detail.isNotEmpty ? ': $detail' : '.'}';
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.black,
      appBar: AppBar(
        title: const Text('Scan Truck QR Code'),
        backgroundColor: Colors.black,
        foregroundColor: Colors.white,
      ),
      body: MobileScanner(
        onDetect: _onDetect,
        errorBuilder: (context, error) => Container(
          color: Colors.black,
          alignment: Alignment.center,
          padding: const EdgeInsets.all(24),
          child: Column(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              const Icon(
                Icons.camera_alt_outlined,
                color: Colors.white54,
                size: 48,
              ),
              const SizedBox(height: 16),
              Text(
                _describeError(error),
                textAlign: TextAlign.center,
                style: const TextStyle(color: Colors.white),
              ),
              const SizedBox(height: 20),
              OutlinedButton(
                onPressed: () => Navigator.pop(context),
                style: OutlinedButton.styleFrom(
                  foregroundColor: Colors.white,
                  side: const BorderSide(color: Colors.white54),
                ),
                child: const Text('Go Back'),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

// ---------------- NEW WORK DIALOG ----------------
class NewWorkDialog extends StatefulWidget {
  final List<String> loadingCategories;
  final List<String> otherCategories;
  // The supervisor's current loading site (WorkSessionScreen's widget.siteId)
  // — excluded from _showUnloadingSitePicker's selectable list, same as
  // _showQrUnloadingSitePicker's fix for the QR flow: selecting it as its
  // own "unloading site" would make AutoArrivalDetectionService's 50m
  // arrival check pass instantly, completing the load before the truck has
  // actually gone anywhere.
  final String currentSiteId;
  final Function(
    String category,
    String? truckNumber,
    String? billNumber,
    String? unloadingSiteName,
    double? distanceKm,
    double? startMeter,
    String? truckDriverName,
    String? cubeCount,
    String? machineOperatorName,
    String loadType,
  )
  onSubmit;

  const NewWorkDialog({
    super.key,
    required this.loadingCategories,
    required this.otherCategories,
    required this.currentSiteId,
    required this.onSubmit,
  });

  @override
  State<NewWorkDialog> createState() => _NewWorkDialogState();
}

class _NewWorkDialogState extends State<NewWorkDialog> {
  String? _selectedCategory;
  String? _selectedUnloadingSiteId;
  String? _selectedUnloadingSiteName;
  String? _selectedTruckNumber;
  final _truckDriverController = TextEditingController();
  final _cubeController = TextEditingController();
  String? _selectedOperatorUid;
  String? _selectedOperatorName;
  final _billNumberController = TextEditingController();
  final _distanceController = TextEditingController();
  String _selectedLoadType = 'company';
  String _errorText = '';
  // Company Load only — the admin-configured fixed route distance (see
  // RouteDistanceManagementScreen/_lookupRouteDistanceKm), looked up after
  // Unloading Site is selected. Private Load never touches these three —
  // its manual _distanceController entry is completely unaffected, see
  // build()'s _selectedLoadType branch below.
  double? _companyRouteDistanceKm;
  bool _companyRouteLookupInProgress = false;
  bool _companyRouteNotConfigured = false;

  // Search-bottom-sheet pattern: typing a name with no exact match surfaces
  // a "use as new unloading site" option instead of restricting selection
  // to the registered list, so any supervisor can log a delivery to a site
  // that hasn't been registered yet.
  Future<void> _showUnloadingSitePicker() async {
    final selected = await showModalBottomSheet<Map<String, String?>>(
      context: context,
      isScrollControlled: true,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
      ),
      builder: (sheetContext) {
        String searchText = '';
        return StatefulBuilder(
          builder: (sheetContext, setSheetState) {
            return Padding(
              padding: EdgeInsets.only(
                bottom: MediaQuery.of(sheetContext).viewInsets.bottom,
              ),
              child: SizedBox(
                height: MediaQuery.of(sheetContext).size.height * 0.75,
                child: Column(
                  children: [
                    const SizedBox(height: 12),
                    Container(
                      width: 40,
                      height: 4,
                      decoration: BoxDecoration(
                        color: Colors.grey[300],
                        borderRadius: BorderRadius.circular(2),
                      ),
                    ),
                    Padding(
                      padding: const EdgeInsets.all(16),
                      child: TextField(
                        autofocus: true,
                        inputFormatters: [UpperCaseTextFormatter()],
                        textCapitalization: TextCapitalization.characters,
                        decoration: InputDecoration(
                          hintText: 'Search or type a new site name',
                          prefixIcon: const Icon(Icons.search),
                          border: OutlineInputBorder(
                            borderRadius: BorderRadius.circular(12),
                          ),
                        ),
                        onChanged: (val) {
                          debugPrint('[UNLOADPICKER] onChanged val="$val"');
                          setSheetState(() => searchText = val);
                        },
                      ),
                    ),
                    Expanded(
                      child: StreamBuilder<QuerySnapshot>(
                        stream: ReferenceCollectionCache.stream('sites'),
                        builder: (context, snapshot) {
                          if (!snapshot.hasData) {
                            return const Center(
                              child: CircularProgressIndicator(),
                            );
                          }
                          debugPrint(
                            '[UNLOADPICKER_DEBUG] Total sites: ${snapshot.data!.docs.length}',
                          );
                          final trimmedSearch = searchText.trim();
                          final filtered = snapshot.data!.docs.where((doc) {
                            // Excludes the supervisor's own current loading
                            // site — see widget.currentSiteId's doc comment.
                            if (doc.id == widget.currentSiteId) return false;
                            final data = doc.data() as Map<String, dynamic>;
                            if (data['canBeUnloadingSite'] == false)
                              return false;
                            final name = (data['name'] ?? '').toString();
                            return name.toLowerCase().contains(
                              trimmedSearch.toLowerCase(),
                            );
                          }).toList();
                          debugPrint(
                            '[UNLOADPICKER_DEBUG] Filtered unloading sites: ${filtered.length}',
                          );
                          final hasExactMatch = filtered.any(
                            (doc) =>
                                ((doc.data() as Map<String, dynamic>)['name'] ??
                                        '')
                                    .toString()
                                    .toLowerCase() ==
                                trimmedSearch.toLowerCase(),
                          );
                          debugPrint(
                            '[UNLOADPICKER] build: searchText="$searchText" '
                            'trimmedSearch="$trimmedSearch" filtered=${filtered.length} '
                            'hasExactMatch=$hasExactMatch '
                            'showAddNew=${trimmedSearch.isNotEmpty && !hasExactMatch}',
                          );

                          return ListView(
                            children: [
                              if (trimmedSearch.isNotEmpty && !hasExactMatch)
                                ListTile(
                                  leading: const Icon(
                                    Icons.add_circle,
                                    color: AppTheme.accent,
                                  ),
                                  title: Text(
                                    "Use '$trimmedSearch' as new unloading site",
                                  ),
                                  onTap: () {
                                    debugPrint(
                                      '[UNLOADPICKER] add-new tapped, name="$trimmedSearch"',
                                    );
                                    Navigator.pop(sheetContext, {
                                      'id': null,
                                      'name': trimmedSearch,
                                    });
                                  },
                                ),
                              for (final doc in filtered)
                                Builder(
                                  builder: (context) {
                                    final data =
                                        doc.data() as Map<String, dynamic>;
                                    return ListTile(
                                      leading: const Icon(
                                        Icons.location_on,
                                        color: Colors.teal,
                                      ),
                                      title: Text(data['name'] ?? ''),
                                      subtitle: Text(data['location'] ?? ''),
                                      onTap: () => Navigator.pop(sheetContext, {
                                        'id': doc.id,
                                        'name': (data['name'] ?? '').toString(),
                                      }),
                                    );
                                  },
                                ),
                              if (filtered.isEmpty && trimmedSearch.isEmpty)
                                const Padding(
                                  padding: EdgeInsets.all(24),
                                  child: Text(
                                    'No sites yet — start typing to add one.',
                                  ),
                                ),
                            ],
                          );
                        },
                      ),
                    ),
                  ],
                ),
              ),
            );
          },
        );
      },
    );

    debugPrint('[UNLOADPICKER] sheet closed, selected=$selected');
    if (selected != null) {
      setState(() {
        _selectedUnloadingSiteId = selected['id'];
        _selectedUnloadingSiteName = selected['name'];
      });
      debugPrint(
        '[UNLOADPICKER] set _selectedUnloadingSiteName=$_selectedUnloadingSiteName',
      );
      if (_selectedLoadType == 'company') {
        await _lookupAndApplyCompanyRouteDistance();
      }
    }
  }

  // Company Load only — auto-looks-up the admin-configured route distance
  // for widget.currentSiteId -> the selected Unloading Site (see
  // RouteDistanceManagementScreen/_lookupRouteDistanceKm) and blocks with
  // an error dialog when none exists yet. Called right after Unloading
  // Site is picked (if already on Company Load), and again whenever Load
  // Type is switched to Company with a site already selected — see the
  // RadioListTile onChanged handlers in build() below.
  Future<void> _lookupAndApplyCompanyRouteDistance() async {
    final unloadingSiteId = _selectedUnloadingSiteId;
    if (unloadingSiteId == null) {
      // A free-typed "new site" (via "Use '...' as new unloading site")
      // has no registered doc id, so there is nothing to look up against —
      // same as "not configured".
      setState(() {
        _companyRouteDistanceKm = null;
        _companyRouteNotConfigured = true;
      });
      if (mounted) await showRouteDistanceNotConfiguredDialog(context);
      return;
    }
    setState(() {
      _companyRouteLookupInProgress = true;
      _companyRouteNotConfigured = false;
    });
    final distanceKm = await _lookupRouteDistanceKm(
      widget.currentSiteId,
      unloadingSiteId,
    );
    if (!mounted) return;
    setState(() {
      _companyRouteLookupInProgress = false;
      _companyRouteDistanceKm = distanceKm;
      _companyRouteNotConfigured = distanceKm == null;
    });
    if (distanceKm == null) {
      await showRouteDistanceNotConfiguredDialog(context);
    }
  }

  bool get _isLoadingCategory =>
      _selectedCategory != null &&
      widget.loadingCategories.contains(_selectedCategory);

  void _handleSubmit() {
    if (_selectedCategory == null) {
      setState(() => _errorText = 'Please select a work category.');
      return;
    }

    if (_isLoadingCategory) {
      if (_selectedTruckNumber == null ||
          _selectedTruckNumber!.trim().isEmpty) {
        setState(() => _errorText = 'Please select a truck.');
        return;
      }
      if (_billNumberController.text.trim().isEmpty) {
        setState(
          () => _errorText = 'Bill Number is required for loading work.',
        );
        return;
      }
      final unloadingSiteName = _selectedUnloadingSiteName?.trim();
      if (unloadingSiteName == null || unloadingSiteName.isEmpty) {
        setState(() => _errorText = 'Please select Unloading Site.');
        return;
      }

      double? resolvedDistanceKm;
      if (_selectedLoadType == 'company') {
        // Admin-configured fixed route distance only — see
        // _lookupAndApplyCompanyRouteDistance. Blocks submission (no
        // record created) until a route is actually configured.
        if (_companyRouteDistanceKm == null) {
          setState(
            () => _errorText = 'Distance not configured for this route.',
          );
          showRouteDistanceNotConfiguredDialog(context);
          return;
        }
        resolvedDistanceKm = _companyRouteDistanceKm;
      } else {
        if (_distanceController.text.trim().isEmpty) {
          setState(() => _errorText = 'Distance (KM) is required.');
          return;
        }
        resolvedDistanceKm = double.tryParse(_distanceController.text.trim());
      }

      widget.onSubmit(
        _selectedCategory!,
        _selectedTruckNumber!.trim(),
        _billNumberController.text.trim(),
        unloadingSiteName,
        resolvedDistanceKm,
        null,
        _truckDriverController.text.trim().isEmpty
            ? null
            : _truckDriverController.text.trim(),
        _cubeController.text.trim().isEmpty
            ? null
            : _cubeController.text.trim(),
        _selectedOperatorName,
        _selectedLoadType,
      );
    } else {
      widget.onSubmit(
        _selectedCategory!,
        null,
        null,
        null,
        null,
        null,
        null,
        null,
        null,
        'company',
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    return AlertDialog(
      title: const Text('Start New Work'),
      content: SingleChildScrollView(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Text(
              'Work Category',
              style: TextStyle(fontWeight: FontWeight.bold),
            ),
            const SizedBox(height: 8),
            DropdownButtonFormField<String>(
              initialValue: _selectedCategory,
              decoration: InputDecoration(
                border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(10),
                ),
              ),
              items: [
                ...widget.loadingCategories.map(
                  (c) => DropdownMenuItem(value: c, child: Text('$c 🚛')),
                ),
                ...widget.otherCategories.map(
                  (c) => DropdownMenuItem(value: c, child: Text(c)),
                ),
              ],
              onChanged: (val) => setState(() {
                _selectedCategory = val;
                _errorText = '';
              }),
            ),
            if (_isLoadingCategory) ...[
              const SizedBox(height: 16),
              const Text(
                'Select Truck',
                style: TextStyle(fontWeight: FontWeight.bold, fontSize: 13),
              ),
              const SizedBox(height: 8),
              StreamBuilder<QuerySnapshot>(
                stream: ReferenceCollectionCache.stream('trucks'),
                builder: (context, snapshot) {
                  final Set<String> truckNumbers = {};
                  // Truck Number -> assigned driver name (set via Truck
                  // Profile's "Change Driver" dialog), used below to
                  // auto pre-fill Truck Driver Name when a truck is picked —
                  // pure convenience: that field stays fully editable so a
                  // substitute driver can still be typed over it.
                  final Map<String, String> assignedDriverByTruckNumber = {};
                  if (snapshot.hasData) {
                    for (final doc in snapshot.data!.docs) {
                      final data = doc.data() as Map<String, dynamic>;
                      final number = data['truckNumber'];
                      if (number != null && number.toString().isNotEmpty) {
                        truckNumbers.add(number.toString());
                        final driverName = data['assignedDriverName'];
                        if (driverName != null &&
                            driverName.toString().isNotEmpty) {
                          assignedDriverByTruckNumber[number.toString()] =
                              driverName.toString();
                        }
                      }
                    }
                  }
                  // Always overwrites Truck Driver Name (falling back to
                  // empty when the newly picked truck has no assigned
                  // driver) so switching trucks never leaves a stale name
                  // behind from whichever truck was selected before.
                  void applyTruckSelection(String truckNumber) {
                    setState(() {
                      _selectedTruckNumber = truckNumber;
                      _truckDriverController.text =
                          assignedDriverByTruckNumber[truckNumber] ?? '';
                    });
                  }

                  return Autocomplete<String>(
                    optionsBuilder: (textEditingValue) {
                      if (textEditingValue.text.isEmpty)
                        return const Iterable<String>.empty();
                      return truckNumbers.where(
                        (number) => number.toLowerCase().contains(
                          textEditingValue.text.toLowerCase(),
                        ),
                      );
                    },
                    onSelected: applyTruckSelection,
                    fieldViewBuilder:
                        (context, controller, focusNode, onSubmit) {
                          controller.text = _selectedTruckNumber ?? '';
                          return TextField(
                            controller: controller,
                            focusNode: focusNode,
                            onChanged: (val) {
                              // Also cover typing a truck's exact number
                              // out without tapping the suggestion —
                              // onSelected alone wouldn't fire then.
                              if (truckNumbers.contains(val)) {
                                applyTruckSelection(val);
                              } else {
                                _selectedTruckNumber = val;
                              }
                            },
                            inputFormatters: [UpperCaseTextFormatter()],
                            textCapitalization: TextCapitalization.characters,
                            decoration: InputDecoration(
                              hintText: 'Enter or choose truck number',
                              border: OutlineInputBorder(
                                borderRadius: BorderRadius.circular(10),
                              ),
                            ),
                          );
                        },
                  );
                },
              ),
              const SizedBox(height: 12),
              TextField(
                controller: _billNumberController,
                keyboardType: TextInputType.number,
                inputFormatters: [FilteringTextInputFormatter.digitsOnly],
                decoration: InputDecoration(
                  labelText: 'Bill Number *',
                  border: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(10),
                  ),
                ),
              ),
              const SizedBox(height: 12),
              const Text(
                'Unloading Site *',
                style: TextStyle(fontWeight: FontWeight.bold),
              ),
              const SizedBox(height: 8),
              InkWell(
                borderRadius: BorderRadius.circular(10),
                onTap: _showUnloadingSitePicker,
                child: InputDecorator(
                  decoration: InputDecoration(
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(10),
                    ),
                  ),
                  child: Text(
                    _selectedUnloadingSiteName ??
                        'Search or type unloading site name',
                    style: TextStyle(
                      color: _selectedUnloadingSiteName == null
                          ? Colors.grey[600]
                          : Colors.black87,
                    ),
                  ),
                ),
              ),
              const SizedBox(height: 12),
              const Text(
                'Load Type',
                style: TextStyle(fontWeight: FontWeight.bold),
              ),
              RadioListTile<String>(
                contentPadding: EdgeInsets.zero,
                dense: true,
                title: const Text('Company Load'),
                value: 'company',
                groupValue: _selectedLoadType,
                onChanged: (val) {
                  setState(() => _selectedLoadType = val ?? 'company');
                  if (_selectedUnloadingSiteId != null ||
                      _selectedUnloadingSiteName != null) {
                    _lookupAndApplyCompanyRouteDistance();
                  }
                },
              ),
              RadioListTile<String>(
                contentPadding: EdgeInsets.zero,
                dense: true,
                title: const Text('Private Load'),
                value: 'private',
                groupValue: _selectedLoadType,
                onChanged: (val) => setState(() {
                  _selectedLoadType = val ?? 'company';
                  // Irrelevant for a Private Load — its manual
                  // _distanceController entry below is unaffected.
                  _companyRouteDistanceKm = null;
                  _companyRouteNotConfigured = false;
                  _companyRouteLookupInProgress = false;
                }),
              ),
              const SizedBox(height: 12),
              if (_selectedLoadType == 'company') ...[
                const Text(
                  'Distance (KM)',
                  style: TextStyle(fontWeight: FontWeight.bold),
                ),
                const SizedBox(height: 6),
                if (_companyRouteLookupInProgress)
                  const Padding(
                    padding: EdgeInsets.symmetric(vertical: 4),
                    child: Row(
                      children: [
                        SizedBox(
                          width: 16,
                          height: 16,
                          child: CircularProgressIndicator(strokeWidth: 2),
                        ),
                        SizedBox(width: 8),
                        Text(
                          'Looking up configured distance...',
                          style: TextStyle(fontSize: 12),
                        ),
                      ],
                    ),
                  )
                else if (_companyRouteDistanceKm != null)
                  IgnorePointer(
                    child: InputDecorator(
                      decoration: InputDecoration(
                        border: OutlineInputBorder(
                          borderRadius: BorderRadius.circular(10),
                        ),
                        filled: true,
                        fillColor: Colors.grey[200],
                        helperText: 'Admin-configured route distance',
                      ),
                      child: Text(
                        '${_companyRouteDistanceKm!.toStringAsFixed(1)} km',
                      ),
                    ),
                  )
                else if (_companyRouteNotConfigured)
                  Text(
                    'Distance not configured for this route. Ask '
                    'Admin/Management to set it in Route Distances.',
                    style: TextStyle(color: Colors.red[700], fontSize: 12),
                  )
                else
                  Text(
                    'Select Unloading Site to look up the route distance.',
                    style: TextStyle(color: Colors.grey[600], fontSize: 12),
                  ),
              ] else
                TextField(
                  controller: _distanceController,
                  keyboardType: TextInputType.number,
                  decoration: InputDecoration(
                    labelText: 'Distance (KM) *',
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(10),
                    ),
                  ),
                ),
              const SizedBox(height: 12),
              FutureBuilder<QuerySnapshot>(
                future: FirebaseFirestore.instance
                    .collection('daily_sessions')
                    .doc('_dummy_')
                    .collection('work_records')
                    .limit(1)
                    .get(),
                builder: (context, _) {
                  return StreamBuilder<QuerySnapshot>(
                    stream: FirebaseFirestore.instance
                        .collectionGroup('work_records')
                        .where('truckDriverName', isNotEqualTo: null)
                        .limit(50)
                        .snapshots(),
                    builder: (context, snapshot) {
                      final Set<String> pastNames = {};
                      if (snapshot.hasData) {
                        for (final doc in snapshot.data!.docs) {
                          final data = doc.data() as Map<String, dynamic>;
                          final name = data['truckDriverName'];
                          if (name != null && name.toString().isNotEmpty) {
                            pastNames.add(name.toString());
                          }
                        }
                      }
                      return Autocomplete<String>(
                        optionsBuilder: (textEditingValue) {
                          if (textEditingValue.text.isEmpty)
                            return const Iterable<String>.empty();
                          return pastNames.where(
                            (name) => name.toLowerCase().contains(
                              textEditingValue.text.toLowerCase(),
                            ),
                          );
                        },
                        onSelected: (selection) {
                          _truckDriverController.text = selection;
                        },
                        fieldViewBuilder:
                            (context, controller, focusNode, onSubmit) {
                              controller.text = _truckDriverController.text;
                              return TextField(
                                controller: controller,
                                focusNode: focusNode,
                                onChanged: (val) =>
                                    _truckDriverController.text = val,
                                inputFormatters: [UpperCaseTextFormatter()],
                                textCapitalization:
                                    TextCapitalization.characters,
                                decoration: InputDecoration(
                                  labelText: 'Truck Driver Name',
                                  border: OutlineInputBorder(
                                    borderRadius: BorderRadius.circular(10),
                                  ),
                                ),
                              );
                            },
                      );
                    },
                  );
                },
              ),
              const SizedBox(height: 12),
              TextField(
                controller: _cubeController,
                keyboardType: TextInputType.number,
                decoration: InputDecoration(
                  labelText: 'Cube (Quantity)',
                  border: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(10),
                  ),
                ),
              ),
              const SizedBox(height: 12),
              const Text(
                'Machine Operator',
                style: TextStyle(fontWeight: FontWeight.bold, fontSize: 13),
              ),
              const SizedBox(height: 8),
              StreamBuilder<QuerySnapshot>(
                stream: FirebaseFirestore.instance
                    .collection('users')
                    .where('canOperateMachine', isEqualTo: true)
                    .snapshots(),
                builder: (context, snapshot) {
                  if (!snapshot.hasData)
                    return const CircularProgressIndicator();
                  final operators = snapshot.data!.docs;
                  if (operators.isEmpty) {
                    return const Text(
                      'No operators registered.',
                      style: TextStyle(color: Colors.grey, fontSize: 12),
                    );
                  }
                  return DropdownButtonFormField<String>(
                    initialValue: _selectedOperatorUid,
                    decoration: InputDecoration(
                      hintText: 'Choose operator',
                      border: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(10),
                      ),
                    ),
                    items: operators.map((doc) {
                      final data = doc.data() as Map<String, dynamic>;
                      return DropdownMenuItem<String>(
                        value: doc.id,
                        child: Text(data['name'] ?? ''),
                      );
                    }).toList(),
                    onChanged: (val) {
                      final selected = operators.firstWhere((d) => d.id == val);
                      final data = selected.data() as Map<String, dynamic>;
                      setState(() {
                        _selectedOperatorUid = val;
                        _selectedOperatorName = data['name'];
                      });
                    },
                  );
                },
              ),
            ],
            if (_errorText.isNotEmpty) ...[
              const SizedBox(height: 12),
              Text(
                _errorText,
                style: const TextStyle(color: Colors.red, fontSize: 13),
              ),
            ],
          ],
        ),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.pop(context),
          child: const Text('Cancel'),
        ),
        ElevatedButton(
          onPressed: _handleSubmit,
          style: ElevatedButton.styleFrom(backgroundColor: Colors.orange[800]),
          child: const Text('START', style: TextStyle(color: Colors.white)),
        ),
      ],
    );
  }
}

// ---------------- LIVE TIMER TEXT (isolated rebuild) ----------------
class LiveTimerText extends StatefulWidget {
  final int totalDurationSeconds;
  final bool isRunning;
  final DateTime? lastResumedAt;

  // Set once a Company Load's loading phase is finished
  // (loadingFinishedAt - loadStartedAt): displayed as-is, with no ticking,
  // in place of the accumulated running total.
  final Duration? frozenDuration;

  const LiveTimerText({
    super.key,
    required this.totalDurationSeconds,
    required this.isRunning,
    required this.lastResumedAt,
    this.frozenDuration,
  });

  @override
  State<LiveTimerText> createState() => _LiveTimerTextState();
}

class _LiveTimerTextState extends State<LiveTimerText> {
  Timer? _timer;

  @override
  void initState() {
    super.initState();
    if (widget.isRunning && widget.frozenDuration == null) {
      _timer = Timer.periodic(const Duration(seconds: 1), (_) {
        if (mounted) setState(() {});
      });
    }
  }

  @override
  void didUpdateWidget(covariant LiveTimerText oldWidget) {
    super.didUpdateWidget(oldWidget);
    _timer?.cancel();
    if (widget.isRunning && widget.frozenDuration == null) {
      _timer = Timer.periodic(const Duration(seconds: 1), (_) {
        if (mounted) setState(() {});
      });
    }
  }

  @override
  void dispose() {
    _timer?.cancel();
    super.dispose();
  }

  String _formatDuration(int seconds) {
    final h = seconds ~/ 3600;
    final m = (seconds % 3600) ~/ 60;
    final s = seconds % 60;
    return '${h.toString().padLeft(2, '0')}:${m.toString().padLeft(2, '0')}:${s.toString().padLeft(2, '0')}';
  }

  @override
  Widget build(BuildContext context) {
    final frozen = widget.frozenDuration;
    int elapsed = frozen?.inSeconds ?? widget.totalDurationSeconds;
    if (frozen == null && widget.isRunning && widget.lastResumedAt != null) {
      elapsed += DateTime.now().difference(widget.lastResumedAt!).inSeconds;
    }

    return Text(
      _formatDuration(elapsed),
      style: const TextStyle(
        fontSize: 22,
        fontWeight: FontWeight.bold,
        fontFamily: 'monospace',
      ),
    );
  }
}

// ---------------- DRIVER: TYPE SELECT (Trucks / Machines) ----------------
class _DailyCheckCardState {
  final String? truckNumber;
  final String? siteId;
  final bool submittedToday;
  const _DailyCheckCardState({this.truckNumber, this.siteId, this.submittedToday = false});
}

class DriverTypeScreen extends StatefulWidget {
  final String name;
  final FirebaseFirestore? firestoreOverride;
  final String? currentUidOverride;
  const DriverTypeScreen({
    super.key,
    required this.name,
    this.firestoreOverride,
    this.currentUidOverride,
  });

  @override
  State<DriverTypeScreen> createState() => _DriverTypeScreenState();
}

class _DriverTypeScreenState extends State<DriverTypeScreen> {
  FirebaseFirestore get _db => widget.firestoreOverride ?? FirebaseFirestore.instance;
  String? get _uid => widget.currentUidOverride ?? FirebaseAuth.instance.currentUser?.uid;

  bool _checkingActiveSession = true;
  late Future<_DailyCheckCardState> _dailyCheckCardFuture;

  @override
  void initState() {
    super.initState();
    _checkForActiveSession();
    _dailyCheckCardFuture = _loadDailyCheckCardState();
    // Covers "the driver re-opens the app with an active session" — fires
    // once, right when the home screen first builds.
    _dailyCheckCardFuture.then(_maybeAutoPromptDailyCheck);
  }

  // The vehicle behind the "Daily Vehicle Check" card — a truck the driver
  // currently has an active truck_sessions doc for, plus whether today's
  // check is already submitted (drives the green DONE TODAY state) and the
  // session's siteId if one was captured. Daily level checks are scoped to
  // trucks (not machines): machines use the separate driver_sessions
  // collection and don't carry a vehicleNumber in the same sense.
  Future<_DailyCheckCardState> _loadDailyCheckCardState() async {
    final uid = _uid;
    if (uid == null) return const _DailyCheckCardState();
    QuerySnapshot<Map<String, dynamic>> snap;
    try {
      snap = await _db
          .collection('truck_sessions')
          .where('driverUid', isEqualTo: uid)
          .where('status', isEqualTo: 'active')
          .limit(1)
          .get();
    } catch (e) {
      debugPrint('[DRIVER] active truck session lookup ERROR: $e');
      return const _DailyCheckCardState();
    }
    if (snap.docs.isEmpty) return const _DailyCheckCardState();
    final data = snap.docs.first.data();
    final truckNumber = (data['truckNumber'] ?? '').toString();
    if (truckNumber.isEmpty) return const _DailyCheckCardState();
    final siteId = (data['siteId'] as String?);
    // Non-blocking: a failed daily_checks read must not hide the card or
    // skip the auto-prompt — fall back to "not submitted yet"
    // (requireDailyCheck=true default) and surface a small warning
    // instead of swallowing the vehicle entirely.
    bool submitted;
    try {
      submitted = await dailyCheckSubmittedToday(truckNumber, db: _db, uid: uid);
    } catch (e) {
      debugPrint('[DRIVER] daily check read FAILED — treating as NOT submitted: $e');
      submitted = false;
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text("Couldn't confirm today's check status — opening it anyway. $e"),
            duration: const Duration(seconds: 4),
          ),
        );
      }
    }
    return _DailyCheckCardState(
      truckNumber: truckNumber,
      siteId: siteId,
      submittedToday: submitted,
    );
  }

  Future<void> _maybeAutoPromptDailyCheck(_DailyCheckCardState state) async {
    if (state.truckNumber == null || state.submittedToday) return;
    bool allowSkip;
    try {
      allowSkip = await fetchDailyCheckAllowSkip(db: _db, uid: _uid);
    } catch (e) {
      debugPrint(
          '[DRIVER] allow-skip settings read FAILED — defaulting requireDailyCheck=true: $e');
      allowSkip = false;
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text("Couldn't load check settings — treating it as required. $e"),
            duration: const Duration(seconds: 4),
          ),
        );
      }
    }
    if (!mounted) return;
    debugPrint('[DRIVER] auto-prompting daily check for ${state.truckNumber} '
        'allowSkip=$allowSkip');
    try {
      await Navigator.push(
        context,
        MaterialPageRoute(
          builder: (_) => DriverDailyCheckScreen(
            vehicleNumber: state.truckNumber!,
            driverName: widget.name,
            siteId: state.siteId,
            allowSkip: allowSkip,
            firestoreOverride: widget.firestoreOverride,
            currentUidOverride: widget.currentUidOverride,
          ),
        ),
      );
      if (mounted) {
        setState(() => _dailyCheckCardFuture = _loadDailyCheckCardState());
      }
    } catch (e) {
      debugPrint('[DRIVER] daily check auto-prompt navigation ERROR: $e');
    }
  }

  Future<void> _checkForActiveSession() async {
    try {
      final today = DateTime.now();
      final dateString =
          "${today.year}-${today.month.toString().padLeft(2, '0')}-${today.day.toString().padLeft(2, '0')}";

      final uid = _uid;
      if (uid == null) {
        if (mounted) setState(() => _checkingActiveSession = false);
        return;
      }
      final existing = await _db
          .collection('driver_sessions')
          .where('driverUid', isEqualTo: uid)
          .where('date', isEqualTo: dateString)
          .where('status', isEqualTo: 'active')
          .limit(1)
          .get();

      if (existing.docs.isNotEmpty && mounted) {
        final data = existing.docs.first.data();
        Navigator.pushReplacement(
          context,
          MaterialPageRoute(
            builder: (_) => DriverWorkAreaScreen(
              sessionId: existing.docs.first.id,
              machineName: data['machineName'] ?? '',
              machineType: data['machineType'] ?? '',
              siteName: data['siteName'] ?? '',
              driverName: widget.name,
            ),
          ),
        );
        return;
      }
    } catch (e) {
      // Offline or error — fall through to normal selection screen
    }
    if (mounted) setState(() => _checkingActiveSession = false);
  }

  @override
  Widget build(BuildContext context) {
    if (_checkingActiveSession) {
      return Scaffold(
        body: Container(
          decoration: const BoxDecoration(gradient: AppTheme.mainGradient),
          child: const Center(
            child: CircularProgressIndicator(color: Colors.white),
          ),
        ),
      );
    }

    return Scaffold(
      body: Container(
        decoration: const BoxDecoration(gradient: AppTheme.mainGradient),
        child: SafeArea(
          child: Column(
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 8, 16, 0),
                child: Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    Expanded(
                      child: Text(
                        'Welcome, ${widget.name}',
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                          fontSize: 18,
                          fontWeight: FontWeight.bold,
                          color: Colors.white,
                        ),
                      ),
                    ),
                    IconButton(
                      icon: const Icon(Icons.logout, color: Colors.white),
                      onPressed: () async {
                        await FirebaseAuth.instance.signOut();
                        if (context.mounted) {
                          Navigator.pushReplacement(
                            context,
                            MaterialPageRoute(
                              builder: (_) => const LoginScreen(),
                            ),
                          );
                        }
                      },
                    ),
                  ],
                ),
              ),
              Expanded(
                child: Padding(
                  padding: const EdgeInsets.all(16.0),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    mainAxisAlignment: MainAxisAlignment.center,
                    children: [
                      Text(
                        'What are you operating today?',
                        style: TextStyle(
                          fontSize: 15,
                          color: Colors.white.withOpacity(0.8),
                        ),
                      ),
                      const SizedBox(height: 20),
                      GradientButton(
                        label: '1. Trucks',
                        icon: Icons.local_shipping,
                        height: 90,
                        onTap: () {
                          Navigator.push(
                            context,
                            MaterialPageRoute(
                              builder: (_) =>
                                  TruckTypeScreen(name: widget.name),
                            ),
                          );
                        },
                      ),
                      const SizedBox(height: 16),
                      GradientButton(
                        label: '2. Machines',
                        icon: Icons.precision_manufacturing,
                        height: 90,
                        onTap: () {
                          Navigator.push(
                            context,
                            MaterialPageRoute(
                              builder: (_) =>
                                  DriverMachineTypeScreen(name: widget.name),
                            ),
                          );
                        },
                      ),
                      FutureBuilder<_DailyCheckCardState>(
                        future: _dailyCheckCardFuture,
                        builder: (context, snap) {
                          final state = snap.data;
                          final truckNumber = state?.truckNumber;
                          if (snap.connectionState != ConnectionState.done ||
                              truckNumber == null ||
                              truckNumber.isEmpty) {
                            return const SizedBox.shrink();
                          }
                          final done = state!.submittedToday;
                          return Column(
                            children: [
                              const SizedBox(height: 16),
                              GradientButton(
                                label: done
                                    ? 'Daily Vehicle Check — $truckNumber (DONE TODAY)'
                                    : 'Daily Vehicle Check — $truckNumber',
                                icon: done ? Icons.check_circle : Icons.fact_check,
                                height: 90,
                                gradient: done
                                    ? LinearGradient(
                                        colors: [
                                          AppColors.success,
                                          AppColors.success.withOpacity(0.8),
                                        ],
                                        begin: Alignment.topLeft,
                                        end: Alignment.bottomRight,
                                      )
                                    : AppTheme.cardGradient,
                                onTap: () async {
                                  await Navigator.push(
                                    context,
                                    MaterialPageRoute(
                                      builder: (_) => DriverDailyCheckScreen(
                                        vehicleNumber: truckNumber,
                                        driverName: widget.name,
                                        siteId: state.siteId,
                                        firestoreOverride: widget.firestoreOverride,
                                        currentUidOverride: widget.currentUidOverride,
                                      ),
                                    ),
                                  );
                                  if (mounted) {
                                    setState(() =>
                                        _dailyCheckCardFuture = _loadDailyCheckCardState());
                                  }
                                },
                              ),
                            ],
                          );
                        },
                      ),
                    ],
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

// ---------------- DRIVER: DAILY VEHICLE LEVEL CHECK ----------------
// Reached from the "Daily Vehicle Check" card on DriverTypeScreen once an
// active truck_sessions doc gives a vehicleNumber. One SUBMIT writes/merges
// a single daily_checks/{vehicle}_{date} doc (resubmit same day overwrites
// it — _writeRepairEvent keeps the append-only audit trail), same
// mechanic-form shape as ServiceRecordFormScreen's checklist rows.
class _DailyCheckRowInput {
  final String id;
  final String label;
  final String defectCategory;
  String status;
  Uint8List? photoBytes;
  String? existingPhotoUrl;
  // Set once this row's current photoBytes uploaded OK, so a RETRY after
  // a later row failed doesn't upload it again. Cleared when the photo
  // is replaced.
  String? uploadedUrl;
  String? uploadedPath;
  final noteController = TextEditingController();
  _DailyCheckRowInput({
    required this.id,
    required this.label,
    required this.defectCategory,
    this.status = DailyCheckStatus.ok,
  });
  void dispose() => noteController.dispose();
}

// ---- Daily check photo upload helpers (pure, unit-tested) ----

/// Upload size guard. The picker already resizes to 1280px / JPEG q75
/// (≤5 MB); this only matters when that compression failed and the raw
/// camera bytes would be sent instead.
const int kDailyCheckMaxPhotoBytes = 12 * 1024 * 1024;

/// Real image type from the file's magic bytes; null when unknown.
String? detectImageContentType(Uint8List bytes) {
  if (bytes.length >= 3 && bytes[0] == 0xFF && bytes[1] == 0xD8 && bytes[2] == 0xFF) {
    return 'image/jpeg';
  }
  if (bytes.length >= 8 &&
      bytes[0] == 0x89 && bytes[1] == 0x50 && bytes[2] == 0x4E && bytes[3] == 0x47) {
    return 'image/png';
  }
  if (bytes.length >= 12 &&
      bytes[0] == 0x52 && bytes[1] == 0x49 && bytes[2] == 0x46 && bytes[3] == 0x46 &&
      bytes[8] == 0x57 && bytes[9] == 0x45 && bytes[10] == 0x42 && bytes[11] == 0x50) {
    return 'image/webp';
  }
  if (bytes.length >= 12 &&
      bytes[4] == 0x66 && bytes[5] == 0x74 && bytes[6] == 0x79 && bytes[7] == 0x70) {
    final brand = String.fromCharCodes(bytes.sublist(8, 12));
    if (brand.startsWith('hei') || brand.startsWith('hev') || brand == 'mif1' || brand == 'msf1') {
      return 'image/heic';
    }
  }
  return null;
}

/// Content type for the upload. Defaults to image/jpeg (what the picker
/// produces), never null — Storage rules that check
/// request.resource.contentType need it set on web AND Android.
String dailyCheckPhotoContentType(Uint8List bytes) =>
    detectImageContentType(bytes) ?? 'image/jpeg';

String fileExtensionForImageContentType(String contentType) {
  switch (contentType) {
    case 'image/png':
      return 'png';
    case 'image/webp':
      return 'webp';
    case 'image/heic':
      return 'heic';
    default:
      return 'jpg';
  }
}

/// repairs/daily_checks/{VEHICLE}/{yyyy-MM-dd}/{checkId}_{millis}.{ext}
String dailyCheckPhotoStoragePath({
  required String vehicleNumber,
  required String dateKey,
  required String checkId,
  required int millis,
  String contentType = 'image/jpeg',
}) =>
    'repairs/daily_checks/${normalizeVehicleNumber(vehicleNumber)}/$dateKey/'
    '${checkId}_$millis.${fileExtensionForImageContentType(contentType)}';

SettableMetadata dailyCheckPhotoMetadata(String contentType) =>
    SettableMetadata(contentType: contentType);

/// A daily-check photo upload that failed, with the non-secret context an
/// admin needs to match it against the Storage rules.
class DailyCheckUploadException implements Exception {
  final String checkLabel;
  final String code;
  final String uid;
  final String role;
  final String path;
  final String contentType;
  final int sizeBytes;
  final Object cause;
  DailyCheckUploadException({
    required this.checkLabel,
    required this.code,
    required this.uid,
    required this.role,
    required this.path,
    required this.contentType,
    required this.sizeBytes,
    required this.cause,
  });

  bool get isUnauthorized => code == 'unauthorized' || code == 'permission-denied';

  String get driverMessage => isUnauthorized
      ? 'The ${checkLabel.toUpperCase()} photo was refused by the server '
          '(not allowed for your account). Your answers are kept — tap RETRY, '
          'and if it keeps failing, show this to the admin.'
      : code == 'too-large'
          ? 'The ${checkLabel.toUpperCase()} photo is too large. Retake it '
              'and tap RETRY — your other answers are kept.'
          : 'The ${checkLabel.toUpperCase()} photo could not be uploaded '
              '($code). Check your connection and tap RETRY — your answers are kept.';

  /// No tokens/keys — only ids and sizes.
  String get details => 'uid: $uid\nrole: $role\npath: $path\n'
      'contentType: $contentType\nsize: ${formatByteSize(sizeBytes)} ($sizeBytes bytes)\n'
      'error: $code';

  @override
  String toString() => 'DailyCheckUploadException($code) path=$path uid=$uid '
      'role=$role contentType=$contentType size=$sizeBytes';
}

String formatByteSize(int bytes) {
  if (bytes < 1024) return '$bytes B';
  if (bytes < 1024 * 1024) return '${(bytes / 1024).toStringAsFixed(1)} KB';
  return '${(bytes / (1024 * 1024)).toStringAsFixed(2)} MB';
}

/// Test seam for the photo upload: returns the download URL.
typedef DailyCheckPhotoUploader = Future<String> Function(
    String path, Uint8List bytes, SettableMetadata metadata);

class DriverDailyCheckScreen extends StatefulWidget {
  final String vehicleNumber;
  final String driverName;
  // Best-known site for the active truck session, if any — written through
  // to the daily_checks doc but never required (this driver flow doesn't
  // always capture a site; see TruckTypeScreen).
  final String? siteId;
  // Controls the SKIP — DO LATER button and the AppBar back arrow —
  // computed by the caller via fetchDailyCheckAllowSkip() (settings.
  // requireDailyCheck, with an admin/owner override). Defaults to true for
  // voluntary re-entry from the driver home card, where there's nothing to
  // enforce beyond what the AppBar back arrow already allows.
  final bool allowSkip;
  final FirebaseFirestore? firestoreOverride;
  final String? currentUidOverride;
  // Tests only; production uses FirebaseStorage.instance (default app,
  // same bucket as every other repairs/ upload).
  final DailyCheckPhotoUploader? photoUploaderOverride;
  // Tests only: pre-staged photo bytes per check id (no camera in tests).
  final Map<String, Uint8List>? debugInitialPhotos;
  // Driver home (daily-check-only flow): on success, replace this screen
  // with DailyCheckSubmittedScreen instead of popping straight back.
  final bool showSuccessScreen;
  const DriverDailyCheckScreen({
    super.key,
    required this.vehicleNumber,
    required this.driverName,
    this.siteId,
    this.allowSkip = true,
    this.firestoreOverride,
    this.currentUidOverride,
    this.photoUploaderOverride,
    this.debugInitialPhotos,
    this.showSuccessScreen = false,
  });

  @override
  State<DriverDailyCheckScreen> createState() => _DriverDailyCheckScreenState();
}

class _DriverDailyCheckScreenState extends State<DriverDailyCheckScreen> {
  FirebaseFirestore get _db => widget.firestoreOverride ?? FirebaseFirestore.instance;
  String? get _uid => widget.currentUidOverride ?? FirebaseAuth.instance.currentUser?.uid;

  bool _loading = true;
  bool _busy = false;
  Object? _existingCreatedAt;
  late final List<_DailyCheckRowInput> _rows = kDefaultDailyChecks
      .map((d) => _DailyCheckRowInput(
            id: d.id,
            label: d.label,
            defectCategory: d.defectCategory,
          )..photoBytes = widget.debugInitialPhotos?[d.id])
      .toList();

  String get _docId => dailyCheckDocId(widget.vehicleNumber, DateTime.now());

  @override
  void initState() {
    super.initState();
    debugPrint('[DRIVER] DriverDailyCheckScreen opened for ${widget.vehicleNumber} '
        'allowSkip=${widget.allowSkip}');
    _load();
  }

  @override
  void dispose() {
    for (final r in _rows) {
      r.dispose();
    }
    super.dispose();
  }

  Future<void> _guarded(Future<void> Function() action) async {
    if (_busy) return;
    setState(() => _busy = true);
    try {
      await action();
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  Future<void> _load() async {
    setState(() => _loading = true);
    try {
      final snap = await logDriverFs(
        'GET daily_checks/$_docId',
        () => _db.collection('daily_checks').doc(_docId).get(),
      );
      final data = snap.data();
      if (data != null) {
        _existingCreatedAt = data['createdAt'];
        final existing = (data['checks'] as List?) ?? const [];
        for (final e in existing) {
          final m = e as Map<String, dynamic>;
          final id = (m['id'] ?? '').toString();
          for (final row in _rows) {
            if (row.id == id) {
              row.status = (m['status'] ?? DailyCheckStatus.ok).toString();
              row.existingPhotoUrl = (m['photoUrl'] as String?);
              row.noteController.text = (m['note'] ?? '').toString();
            }
          }
        }
      }
      debugPrint('[DRIVER] DriverDailyCheckScreen load done, existing=${data != null}');
    } catch (e) {
      // Non-blocking: a failed pre-fill read must never prevent today's
      // check from being done — fall back to a blank form (SUBMIT always
      // writes the same doc id regardless of whether this pre-fill
      // succeeded) and surface a small warning instead of an ErrorState
      // that would block the whole screen.
      debugPrint('[DRIVER] DriverDailyCheckScreen load FAILED — starting a blank form: $e');
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text("Couldn't load today's existing check — starting fresh. $e"),
            duration: const Duration(seconds: 4),
          ),
        );
      }
    } finally {
      if (mounted) setState(() => _loading = false);
    }
  }

  void _skip() {
    debugPrint('[DRIVER] DriverDailyCheckScreen skipped for ${widget.vehicleNumber}');
    Navigator.pop(context, false);
  }

  Future<void> _submit() async {
    final checksForValidation = _rows
        .map((r) => {
              'status': r.status,
              'hasPhoto': r.photoBytes != null ||
                  (r.existingPhotoUrl != null && r.existingPhotoUrl!.isNotEmpty),
            })
        .toList();
    if (!isDailyCheckSubmitValid(checksForValidation)) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Please add a photo for every check.')),
        );
      }
      return;
    }
    debugPrint('[DRIVER] daily check submit START vehicleNumber=${widget.vehicleNumber}');
    try {
      final dateKey = dailyCheckDateKey(DateTime.now());
      final normalizedVehicleNumber = normalizeVehicleNumber(widget.vehicleNumber);
      final uid = _uid ?? '';
      // users/{uid} read first: name for the doc + role for diagnostics.
      // Non-fatal — a failed read falls back to the passed-in name.
      String userName = widget.driverName;
      String role = 'unknown';
      try {
        final userDoc = await logDriverFs(
          'GET users/$uid',
          () => _db.collection('users').doc(uid).get(),
        );
        userName = (userDoc.data()?['name'] ?? widget.driverName).toString();
        role = (userDoc.data()?['role'] ?? 'unknown').toString();
      } catch (e) {
        debugPrint('[DRIVER] daily check users/$uid read failed (non-fatal): $e');
      }
      // Uploads all happen BEFORE the single daily_checks write, so a
      // failed upload never leaves a half-saved check.
      final checksData = <Map<String, dynamic>>[];
      for (final row in _rows) {
        String? url = row.existingPhotoUrl;
        String? path;
        if (row.photoBytes != null && row.uploadedUrl != null) {
          url = row.uploadedUrl;
          path = row.uploadedPath;
        } else if (row.photoBytes != null) {
          final bytes = row.photoBytes!;
          final contentType = dailyCheckPhotoContentType(bytes);
          final p = dailyCheckPhotoStoragePath(
            vehicleNumber: normalizedVehicleNumber,
            dateKey: dateKey,
            checkId: row.id,
            millis: DateTime.now().millisecondsSinceEpoch,
            contentType: contentType,
          );
          DailyCheckUploadException fail(String code, Object cause) =>
              DailyCheckUploadException(
                checkLabel: row.label,
                code: code,
                uid: uid,
                role: role,
                path: p,
                contentType: contentType,
                sizeBytes: bytes.length,
                cause: cause,
              );
          if (kDebugMode) {
            debugPrint('[DRIVER] UPLOAD daily check photo uid=$uid role=$role '
                'path=$p contentType=$contentType size=${bytes.length}');
          }
          if (bytes.length > kDailyCheckMaxPhotoBytes) {
            throw fail('too-large', 'size ${bytes.length} > $kDailyCheckMaxPhotoBytes');
          }
          try {
            final metadata = dailyCheckPhotoMetadata(contentType);
            final uploader = widget.photoUploaderOverride;
            if (uploader != null) {
              url = await uploader(p, bytes, metadata);
            } else {
              final ref = FirebaseStorage.instance.ref(p);
              await logDriverFs('UPLOAD storage:$p', () => ref.putData(bytes, metadata));
              url = await logDriverFs(
                  'GET downloadURL storage:$p', () => ref.getDownloadURL());
            }
          } catch (e) {
            final inner = e is FirebaseException ? e : null;
            final code = inner?.code ??
                RegExp(r'\((unauthorized|permission-denied|[a-z-]+)\)')
                    .firstMatch(e.toString())
                    ?.group(1) ??
                'upload-failed';
            throw fail(code, e);
          }
          path = p;
          row.uploadedUrl = url;
          row.uploadedPath = p;
        }
        checksData.add({
          'id': row.id,
          'label': row.label,
          'status': row.status,
          'photoUrl': url,
          if (path != null) 'photoPath': path,
          'note': row.noteController.text.trim(),
        });
      }
      final hasLow = dailyCheckAnyLow(checksData);
      await logDriverFs(
        'SET daily_checks/$_docId',
        () => _db.collection('daily_checks').doc(_docId).set({
          'vehicleNumber': normalizedVehicleNumber,
          'date': dateKey,
          'driverUid': uid,
          'driverName': userName,
          'siteId': widget.siteId ?? '',
          'checks': checksData,
          'hasLow': hasLow,
          'createdAt': _existingCreatedAt ?? FieldValue.serverTimestamp(),
          'submittedBy': uid,
          'submittedByName': userName,
          'submittedAt': FieldValue.serverTimestamp(),
          'updatedAt': FieldValue.serverTimestamp(),
        }, SetOptions(merge: true)),
      );
      await logDriverFs(
        'WRITE EVENT daily_checks/$_docId',
        () => _writeRepairEvent(
          collection: 'daily_checks',
          docId: _docId,
          action: 'SUBMITTED',
          summary: 'Daily check submitted by $userName for $normalizedVehicleNumber'
              '${hasLow ? ' — LOW reported' : ''}',
          actorUid: uid,
          actorName: userName,
          db: _db,
        ),
      );
      debugPrint('[DRIVER] daily check submit DONE vehicleNumber=$normalizedVehicleNumber');
      if (mounted && widget.showSuccessScreen) {
        Navigator.pushReplacement(
          context,
          MaterialPageRoute(
            builder: (_) => DailyCheckSubmittedScreen(
              truckNumber: normalizedVehicleNumber,
              dateKey: dateKey,
            ),
          ),
          result: true,
        );
        return;
      }
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Daily check submitted.')),
        );
        Navigator.pop(context, true);
      }
    } on DailyCheckUploadException catch (e) {
      debugPrint('[DRIVER] daily check upload ERROR: $e cause=${e.cause}');
      if (mounted) await _showSubmitError(e.driverMessage, e.details);
    } catch (e) {
      debugPrint('[DRIVER] daily check submit ERROR: $e');
      if (mounted) {
        await _showSubmitError(
          'The daily check could not be saved. Your answers are kept — tap RETRY.',
          e.toString(),
        );
      }
    }
  }

  // Dialog, not a snackbar: the form (statuses, photos, notes) stays
  // exactly as filled, and RETRY re-runs submit — photos that already
  // uploaded are not sent again.
  Future<void> _showSubmitError(String message, String details) async {
    final retry = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        key: const ValueKey('daily-check-submit-error'),
        title: const Text('Could not submit'),
        content: SingleChildScrollView(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(message),
              const SizedBox(height: 12),
              SelectableText(
                details,
                style: const TextStyle(fontSize: 11, color: Colors.black54),
              ),
            ],
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('CLOSE'),
          ),
          ElevatedButton(
            onPressed: () => Navigator.pop(dialogContext, true),
            child: const Text('RETRY'),
          ),
        ],
      ),
    );
    if (retry == true && mounted) {
      // _busy is still true here (we're inside _guarded), so run the
      // retry after this guarded call has finished.
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) _guarded(_submit);
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    if (_loading) {
      return const Scaffold(body: LoadingState());
    }
    return PopScope(
      // Hardware/browser back is never truly blockable (nor worth trying
      // to), but with allowSkip false we at least remove the in-UI escape
      // hatches (AppBar back arrow, SKIP button) so a normal tap-through
      // can't bypass "must complete before continuing to trips".
      canPop: widget.allowSkip,
      child: Scaffold(
      appBar: AppBar(
        automaticallyImplyLeading: widget.allowSkip,
        title: Text('Daily Check — ${widget.vehicleNumber}'),
        backgroundColor: AppColors.navy,
        foregroundColor: Colors.white,
      ),
      body: SingleChildScrollView(
        padding: const EdgeInsets.all(AppSpacing.md),
        child: Align(
          alignment: Alignment.topCenter,
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 560),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                for (final row in _rows) ...[
                  AppCard(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Row(
                          children: [
                            Expanded(
                              child: Text(row.label.toUpperCase(), style: AppText.section),
                            ),
                            ChoiceChip(
                              label: const Text('OK'),
                              selected: row.status == DailyCheckStatus.ok,
                              onSelected: (_) =>
                                  setState(() => row.status = DailyCheckStatus.ok),
                            ),
                            const SizedBox(width: 6),
                            ChoiceChip(
                              label: const Text('LOW'),
                              selected: row.status == DailyCheckStatus.low,
                              onSelected: (_) =>
                                  setState(() => row.status = DailyCheckStatus.low),
                            ),
                          ],
                        ),
                        const SizedBox(height: AppSpacing.sm),
                        _DailyCheckPhotoPicker(
                          key: ValueKey('photo_${row.id}'),
                          existingUrl: row.existingPhotoUrl,
                          onChanged: (bytes) {
                            row.photoBytes = bytes;
                            row.uploadedUrl = null;
                            row.uploadedPath = null;
                          },
                        ),
                        const SizedBox(height: AppSpacing.sm),
                        TextField(
                          controller: row.noteController,
                          inputFormatters: [UpperCaseTextFormatter()],
                          textCapitalization: TextCapitalization.characters,
                          decoration: const InputDecoration(
                            labelText: 'Note (optional)',
                            isDense: true,
                          ),
                        ),
                      ],
                    ),
                  ),
                  const SizedBox(height: AppSpacing.sm),
                ],
                const SizedBox(height: AppSpacing.md),
                SizedBox(
                  width: double.infinity,
                  child: ElevatedButton(
                    onPressed: _busy ? null : () => _guarded(_submit),
                    style: ElevatedButton.styleFrom(
                      padding: const EdgeInsets.symmetric(vertical: 14),
                      backgroundColor: AppColors.navy,
                    ),
                    child: _busy
                        ? const SizedBox(
                            width: 20,
                            height: 20,
                            child: CircularProgressIndicator(
                              strokeWidth: 2,
                              color: Colors.white,
                            ),
                          )
                        : const Text('SUBMIT'),
                  ),
                ),
                if (widget.allowSkip) ...[
                  const SizedBox(height: AppSpacing.sm),
                  SizedBox(
                    width: double.infinity,
                    child: TextButton(
                      onPressed: _busy ? null : _skip,
                      child: const Text('SKIP — DO LATER'),
                    ),
                  ),
                ],
              ],
            ),
          ),
        ),
      ),
      ),
    );
  }
}

// Single REQUIRED photo per daily-check line — pick (camera/gallery/web
// file picker) -> compress -> stage in memory; the parent uploads at
// SUBMIT time, same stage-then-upload-at-save shape as
// _InspectionAttachmentsSection, just for exactly one photo instead of a
// list. A stable key per row (ValueKey('photo_${row.id}')) keeps this
// State instance (and its staged bytes) alive across the parent's setState
// rebuilds (e.g. toggling OK/LOW on a different row).
class _DailyCheckPhotoPicker extends StatefulWidget {
  final String? existingUrl;
  final ValueChanged<Uint8List?> onChanged;
  const _DailyCheckPhotoPicker({super.key, this.existingUrl, required this.onChanged});

  @override
  State<_DailyCheckPhotoPicker> createState() => _DailyCheckPhotoPickerState();
}

class _DailyCheckPhotoPickerState extends State<_DailyCheckPhotoPicker> {
  Uint8List? _bytes;
  bool _busy = false;

  Future<void> _pick(bool fromCamera) async {
    Uint8List bytes;
    try {
      if (fromCamera) {
        final xfile = await ImagePicker().pickImage(source: ImageSource.camera);
        if (xfile == null) return;
        bytes = await xfile.readAsBytes();
      } else if (kIsWeb) {
        final selected = await FilePicker.pickFiles(type: FileType.image);
        if (selected.isEmpty) return;
        bytes = await selected.first.readAsBytes();
      } else {
        final xfile = await ImagePicker().pickImage(source: ImageSource.gallery);
        if (xfile == null) return;
        bytes = await xfile.readAsBytes();
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Failed to pick photo: $e')),
        );
      }
      return;
    }
    setState(() => _busy = true);
    Uint8List compressed;
    try {
      compressed = await compute(_compressInspectionPhotoBytes, bytes);
    } catch (_) {
      compressed = bytes;
    }
    if (!mounted) return;
    setState(() {
      _bytes = compressed;
      _busy = false;
    });
    widget.onChanged(compressed);
  }

  Future<void> _showAddSheet() async {
    final choice = await showModalBottomSheet<String>(
      context: context,
      builder: (sheetContext) => SafeArea(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            ListTile(
              leading: const Icon(Icons.camera_alt, color: AppColors.primary),
              title: const Text('Take Photo'),
              onTap: () => Navigator.pop(sheetContext, 'camera'),
            ),
            ListTile(
              leading: const Icon(Icons.photo_library, color: AppColors.primary),
              title: Text(kIsWeb ? 'Choose File' : 'Choose from Gallery'),
              onTap: () => Navigator.pop(sheetContext, 'gallery'),
            ),
          ],
        ),
      ),
    );
    if (choice == 'camera') {
      await _pick(true);
    } else if (choice == 'gallery') {
      await _pick(false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final hasPhoto =
        _bytes != null || (widget.existingUrl != null && widget.existingUrl!.isNotEmpty);
    return Row(
      children: [
        if (_bytes != null) ...[
          ClipRRect(
            borderRadius: BorderRadius.circular(8),
            child: Image.memory(_bytes!, width: 56, height: 56, fit: BoxFit.cover),
          ),
          const SizedBox(width: 8),
        ] else if (widget.existingUrl != null && widget.existingUrl!.isNotEmpty) ...[
          ClipRRect(
            borderRadius: BorderRadius.circular(8),
            child: Image.network(
              widget.existingUrl!,
              width: 56,
              height: 56,
              fit: BoxFit.cover,
              // Decodes the downloaded photo at this thumbnail's own size
              // (x3 for high-DPI screens) instead of full camera
              // resolution — same pixels on screen, far less memory/CPU
              // per thumbnail.
              cacheWidth: 168,
              cacheHeight: 168,
              errorBuilder: (_, __, ___) => Container(
                width: 56,
                height: 56,
                color: AppColors.textMuted.withOpacity(0.1),
                child: const Icon(Icons.broken_image, size: 20),
              ),
            ),
          ),
          const SizedBox(width: 8),
        ],
        Expanded(
          child: OutlinedButton.icon(
            onPressed: _busy ? null : _showAddSheet,
            icon: _busy
                ? const SizedBox(
                    width: 14,
                    height: 14,
                    child: CircularProgressIndicator(strokeWidth: 2),
                  )
                : Icon(hasPhoto ? Icons.refresh : Icons.add_a_photo, size: 18),
            label: Text(hasPhoto ? 'RETAKE PHOTO' : 'ADD PHOTO (REQUIRED)'),
          ),
        ),
      ],
    );
  }
}

