// ---------------- DRIVER: WORK AREA ----------------
class DriverWorkAreaScreen extends StatefulWidget {
  final String sessionId;
  final String machineName;
  final String machineType;
  final String siteName;
  final String driverName;

  const DriverWorkAreaScreen({
    super.key,
    required this.sessionId,
    required this.machineName,
    required this.machineType,
    required this.siteName,
    required this.driverName,
  });

  @override
  State<DriverWorkAreaScreen> createState() => _DriverWorkAreaScreenState();
}

class _DriverWorkAreaScreenState extends State<DriverWorkAreaScreen> {
  double? _startMeter;

  CollectionReference get _recordsRef => FirebaseFirestore.instance
      .collection('driver_sessions')
      .doc(widget.sessionId)
      .collection('work_records');

  List<String> get _tasks =>
      DriverMachineTypeScreen.machineTypeTasks[widget.machineType] ?? [];

  String _formatDuration(int seconds) {
    final h = seconds ~/ 3600;
    final m = (seconds % 3600) ~/ 60;
    final s = seconds % 60;
    return '${h.toString().padLeft(2, '0')}:${m.toString().padLeft(2, '0')}:${s.toString().padLeft(2, '0')}';
  }

  Future<void> _pauseRunningRecord() async {
    final runningSnap = await _recordsRef
        .where('status', isEqualTo: 'running')
        .get();
    for (final doc in runningSnap.docs) {
      final data = doc.data() as Map<String, dynamic>;
      final lastResumedAt = (data['lastResumedAt'] as Timestamp?)?.toDate();
      final currentTotal = (data['totalDurationSeconds'] ?? 0) as int;
      int addedSeconds = 0;
      if (lastResumedAt != null) {
        addedSeconds = DateTime.now().difference(lastResumedAt).inSeconds;
      }
      final newTotal = currentTotal + addedSeconds;

      await doc.reference.update({
        'status': 'paused',
        'totalDurationSeconds': newTotal,
        'lastResumedAt': null,
      });

      // Sync this task's accumulated time to Google Sheets
      GoogleSheetsService.sendRow(
        sheetName: 'Machine_Tasks',
        row: [
          GoogleSheetsService.formatDate(DateTime.now()),
          widget.machineName,
          widget.machineType,
          widget.siteName,
          widget.driverName,
          data['task'] ?? '',
          _formatDuration(newTotal),
          GoogleSheetsService.formatTime(Timestamp.now()),
          _startMeter?.toString() ?? '',
          data['truckNumber'] ?? '',
        ],
      );
    }
  }

  bool _isLoadingCategory(String category) =>
      category.toLowerCase().contains('loading');

  Future<void> _startTask(String taskName) async {
    if (_startMeter == null) {
      final meter = await _askStartMeter();
      if (meter == null) return;
      setState(() => _startMeter = meter);
    }

    final isLoading = _isLoadingCategory(taskName);
    String? truckNumber;
    if (isLoading) {
      // Always a fresh prompt — the previously selected truck is never
      // reused, since the driver may load a different truck each time.
      truckNumber = await _askTruckNumber();
      if (truckNumber == null) return;
    }

    await _pauseRunningRecord();

    final existingTaskSnap = await _recordsRef
        .where('task', isEqualTo: taskName)
        .limit(1)
        .get();

    if (existingTaskSnap.docs.isNotEmpty) {
      await existingTaskSnap.docs.first.reference.update({
        'status': 'running',
        'lastResumedAt': FieldValue.serverTimestamp(),
        if (isLoading) 'truckNumber': truckNumber,
      });
    } else {
      await _recordsRef.add({
        'task': taskName,
        'status': 'running',
        'totalDurationSeconds': 0,
        'lastResumedAt': FieldValue.serverTimestamp(),
        'createdAt': FieldValue.serverTimestamp(),
        if (isLoading) 'truckNumber': truckNumber,
      });
    }
  }

  Future<String?> _askTruckNumber() async {
    String? selectedTruckId;
    String? selectedTruckNumber;
    String? errorText;

    return showDialog<String>(
      context: context,
      barrierDismissible: false,
      builder: (dialogContext) => StatefulBuilder(
        builder: (dialogContext, setDialogState) => AlertDialog(
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(16),
          ),
          title: const Text('Select Truck'),
          content: StreamBuilder<QuerySnapshot>(
            stream: ReferenceCollectionCache.stream('trucks'),
            builder: (context, snapshot) {
              if (!snapshot.hasData) {
                return const SizedBox(
                  height: 60,
                  child: Center(child: CircularProgressIndicator()),
                );
              }
              final trucks = snapshot.data!.docs;
              if (trucks.isEmpty) {
                return const Text(
                  'No trucks registered. Contact Admin.',
                  style: TextStyle(color: Colors.red, fontSize: 13),
                );
              }
              return Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  DropdownButtonFormField<String>(
                    initialValue: selectedTruckId,
                    decoration: InputDecoration(
                      hintText: 'Choose truck',
                      prefixIcon: const Icon(Icons.local_shipping),
                      border: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(12),
                      ),
                    ),
                    items: trucks.map((doc) {
                      final data = doc.data() as Map<String, dynamic>;
                      return DropdownMenuItem<String>(
                        value: doc.id,
                        child: Text(data['truckNumber'] ?? ''),
                      );
                    }).toList(),
                    onChanged: (val) {
                      final selected = trucks.firstWhere((d) => d.id == val);
                      final data = selected.data() as Map<String, dynamic>;
                      setDialogState(() {
                        selectedTruckId = val;
                        selectedTruckNumber = data['truckNumber'];
                        errorText = null;
                      });
                    },
                  ),
                  if (errorText != null) ...[
                    const SizedBox(height: 8),
                    Text(
                      errorText!,
                      style: const TextStyle(color: Colors.red, fontSize: 12),
                    ),
                  ],
                ],
              );
            },
          ),
          actions: [
            ElevatedButton(
              onPressed: () {
                if (selectedTruckNumber == null) {
                  setDialogState(() => errorText = 'Please select a truck.');
                  return;
                }
                Navigator.pop(dialogContext, selectedTruckNumber);
              },
              style: ElevatedButton.styleFrom(
                backgroundColor: Colors.purple[800],
              ),
              child: const Text(
                'CONFIRM',
                style: TextStyle(color: Colors.white),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Future<double?> _askStartMeter() async {
    final controller = TextEditingController();
    return showDialog<double>(
      context: context,
      barrierDismissible: false,
      builder: (_) => AlertDialog(
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
        title: const Text('Start Meter Reading'),
        content: TextField(
          controller: controller,
          keyboardType: TextInputType.number,
          autofocus: true,
          decoration: InputDecoration(
            hintText: 'e.g. 1234.5',
            prefixIcon: const Icon(Icons.speed),
            border: OutlineInputBorder(borderRadius: BorderRadius.circular(12)),
          ),
        ),
        actions: [
          ElevatedButton(
            onPressed: () {
              final val = double.tryParse(controller.text.trim());
              if (val != null) Navigator.pop(context, val);
            },
            style: ElevatedButton.styleFrom(
              backgroundColor: Colors.purple[800],
            ),
            child: const Text('CONFIRM', style: TextStyle(color: Colors.white)),
          ),
        ],
      ),
    );
  }

  void _showEndDayDialog() {
    final endMeterController = TextEditingController();
    showDialog(
      context: context,
      builder: (_) => AlertDialog(
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
        title: const Text('End Day'),
        content: TextField(
          controller: endMeterController,
          keyboardType: TextInputType.number,
          decoration: InputDecoration(
            labelText: 'End Meter Reading',
            border: OutlineInputBorder(borderRadius: BorderRadius.circular(12)),
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: const Text('Cancel'),
          ),
          ElevatedButton(
            onPressed: () async {
              if (endMeterController.text.trim().isEmpty) return;
              await _pauseRunningRecord();
              await FirebaseFirestore.instance
                  .collection('driver_sessions')
                  .doc(widget.sessionId)
                  .update({
                    'startMeter': _startMeter,
                    'endMeter':
                        double.tryParse(endMeterController.text.trim()) ?? 0,
                    'status': 'completed',
                    'completedAt': FieldValue.serverTimestamp(),
                  });
              if (context.mounted) {
                Navigator.pop(context);
                Navigator.popUntil(context, (route) => route.isFirst);
              }
            },
            style: ElevatedButton.styleFrom(backgroundColor: Colors.red[700]),
            child: const Text('END DAY', style: TextStyle(color: Colors.white)),
          ),
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.grey[100],
      appBar: AppBar(
        leading: IconButton(
          icon: const Icon(Icons.arrow_back),
          onPressed: () {
            if (Navigator.canPop(context)) {
              Navigator.pop(context);
            } else {
              Navigator.pushReplacement(
                context,
                MaterialPageRoute(
                  builder: (_) => DriverTypeScreen(name: widget.driverName),
                ),
              );
            }
          },
        ),
        title: Text(widget.machineName),
        backgroundColor: Colors.purple[800],
        actions: [
          IconButton(
            icon: const Icon(Icons.history),
            onPressed: () {
              Navigator.push(
                context,
                MaterialPageRoute(
                  builder: (_) =>
                      DriverHistoryScreen(sessionId: widget.sessionId),
                ),
              );
            },
          ),
        ],
      ),
      body: Column(
        children: [
          Container(
            width: double.infinity,
            padding: const EdgeInsets.all(12),
            color: Colors.purple[50],
            child: Text(
              'Site: ${widget.siteName}  •  Driver: ${widget.driverName}',
              style: const TextStyle(fontSize: 13),
            ),
          ),

          // Active/paused task cards
          StreamBuilder<QuerySnapshot>(
            stream: _recordsRef
                .orderBy('createdAt', descending: true)
                .snapshots(),
            builder: (context, snapshot) {
              if (!snapshot.hasData || snapshot.data!.docs.isEmpty) {
                return const SizedBox.shrink();
              }
              final records = snapshot.data!.docs;

              return Container(
                constraints: const BoxConstraints(maxHeight: 220),
                padding: const EdgeInsets.symmetric(
                  horizontal: 12,
                  vertical: 8,
                ),
                child: ListView.builder(
                  itemCount: records.length,
                  itemBuilder: (context, index) {
                    final doc = records[index];
                    final data = doc.data() as Map<String, dynamic>;
                    final isRunning = data['status'] == 'running';

                    return AnimatedContainer(
                      duration: const Duration(milliseconds: 300),
                      margin: const EdgeInsets.only(bottom: 8),
                      decoration: BoxDecoration(
                        color: isRunning ? Colors.green[50] : Colors.white,
                        borderRadius: BorderRadius.circular(14),
                        border: Border.all(
                          color: isRunning ? Colors.green : Colors.grey[300]!,
                          width: isRunning ? 1.6 : 1,
                        ),
                        boxShadow: isRunning
                            ? [
                                BoxShadow(
                                  color: Colors.green.withOpacity(0.25),
                                  blurRadius: 8,
                                  spreadRadius: 1,
                                ),
                              ]
                            : [],
                      ),
                      padding: const EdgeInsets.all(12),
                      child: Row(
                        children: [
                          if (isRunning) const PulsingDot(),
                          if (isRunning) const SizedBox(width: 10),
                          Expanded(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              mainAxisSize: MainAxisSize.min,
                              children: [
                                Text(
                                  data['task'] ?? '',
                                  style: const TextStyle(
                                    fontWeight: FontWeight.bold,
                                    fontSize: 15,
                                  ),
                                ),
                                if (data['truckNumber'] != null)
                                  Text(
                                    'Truck: ${data['truckNumber']}',
                                    style: const TextStyle(
                                      fontSize: 12,
                                      color: Colors.grey,
                                    ),
                                  ),
                              ],
                            ),
                          ),
                          LiveTimerText(
                            totalDurationSeconds:
                                (data['totalDurationSeconds'] ?? 0) as int,
                            isRunning: isRunning,
                            lastResumedAt: (data['lastResumedAt'] as Timestamp?)
                                ?.toDate(),
                          ),
                        ],
                      ),
                    );
                  },
                ),
              );
            },
          ),
          const Divider(height: 1),
          Expanded(
            child: Padding(
              padding: const EdgeInsets.all(16),
              child: GridView.builder(
                gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
                  crossAxisCount: 2,
                  crossAxisSpacing: 14,
                  mainAxisSpacing: 14,
                  childAspectRatio: 1.3,
                ),
                itemCount: _tasks.length,
                itemBuilder: (context, index) {
                  return TaskButton(
                    label: _tasks[index],
                    onTap: () => _startTask(_tasks[index]),
                  );
                },
              ),
            ),
          ),
        ],
      ),
      bottomNavigationBar: SafeArea(
        child: Padding(
          padding: const EdgeInsets.all(12.0),
          child: Row(
            children: [
              Expanded(
                child: SizedBox(
                  height: 48,
                  child: OutlinedButton.icon(
                    onPressed: _pauseRunningRecord,
                    icon: const Icon(Icons.pause),
                    label: const Text('PAUSE'),
                  ),
                ),
              ),
              const SizedBox(width: 12),
              Expanded(
                child: SizedBox(
                  height: 48,
                  child: ElevatedButton.icon(
                    onPressed: _showEndDayDialog,
                    icon: const Icon(Icons.flag, color: Colors.white),
                    label: const Text(
                      'END',
                      style: TextStyle(color: Colors.white),
                    ),
                    style: ElevatedButton.styleFrom(
                      backgroundColor: Colors.red[700],
                    ),
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

// ---------------- DRIVER HISTORY SCREEN ----------------
class DriverHistoryScreen extends StatelessWidget {
  final String sessionId;
  const DriverHistoryScreen({super.key, required this.sessionId});

  String _formatDuration(int seconds) {
    final h = seconds ~/ 3600;
    final m = (seconds % 3600) ~/ 60;
    return '${h}h ${m}m';
  }

  int _liveElapsed(Map<String, dynamic> data) {
    int total = (data['totalDurationSeconds'] ?? 0) as int;
    if (data['status'] == 'running' && data['lastResumedAt'] != null) {
      final lastResumedAt = (data['lastResumedAt'] as Timestamp).toDate();
      total += DateTime.now().difference(lastResumedAt).inSeconds;
    }
    return total;
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Container(
        decoration: const BoxDecoration(gradient: AppTheme.mainGradient),
        child: SafeArea(
          child: Column(
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 8, 16, 0),
                child: Row(
                  children: [
                    IconButton(
                      icon: const Icon(Icons.arrow_back, color: Colors.white),
                      onPressed: () => Navigator.pop(context),
                    ),
                    const Text(
                      "Today's History",
                      style: TextStyle(
                        fontSize: 18,
                        fontWeight: FontWeight.bold,
                        color: Colors.white,
                      ),
                    ),
                  ],
                ),
              ),
              Expanded(
                child: StreamBuilder<DocumentSnapshot>(
                  stream: FirebaseFirestore.instance
                      .collection('driver_sessions')
                      .doc(sessionId)
                      .snapshots(),
                  builder: (context, sessionSnap) {
                    if (!sessionSnap.hasData) {
                      return const Center(
                        child: CircularProgressIndicator(color: Colors.white),
                      );
                    }
                    final sessionData =
                        sessionSnap.data!.data() as Map<String, dynamic>?;

                    return StreamBuilder<QuerySnapshot>(
                      stream: FirebaseFirestore.instance
                          .collection('driver_sessions')
                          .doc(sessionId)
                          .collection('work_records')
                          .orderBy('createdAt', descending: true)
                          .snapshots(),
                      builder: (context, snapshot) {
                        if (!snapshot.hasData) {
                          return const Center(
                            child: CircularProgressIndicator(
                              color: Colors.white,
                            ),
                          );
                        }
                        final records = snapshot.data!.docs;

                        int totalSeconds = 0;
                        for (final doc in records) {
                          final data = doc.data() as Map<String, dynamic>;
                          totalSeconds += _liveElapsed(data);
                        }

                        return SingleChildScrollView(
                          padding: const EdgeInsets.all(16),
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              GlassCard(
                                child: Column(
                                  children: [
                                    const Icon(
                                      Icons.timer,
                                      color: Colors.white,
                                      size: 32,
                                    ),
                                    const SizedBox(height: 8),
                                    Text(
                                      _formatDuration(totalSeconds),
                                      style: const TextStyle(
                                        fontSize: 28,
                                        fontWeight: FontWeight.bold,
                                        color: Colors.white,
                                      ),
                                    ),
                                    Text(
                                      'Total Worked Today',
                                      style: TextStyle(
                                        color: Colors.white.withOpacity(0.7),
                                        fontSize: 13,
                                      ),
                                    ),
                                    if (sessionData != null &&
                                        sessionData['startMeter'] != null) ...[
                                      const Divider(
                                        color: Colors.white24,
                                        height: 24,
                                      ),
                                      Row(
                                        mainAxisAlignment:
                                            MainAxisAlignment.spaceAround,
                                        children: [
                                          Column(
                                            children: [
                                              Text(
                                                '${sessionData['startMeter']}',
                                                style: const TextStyle(
                                                  color: Colors.white,
                                                  fontWeight: FontWeight.bold,
                                                ),
                                              ),
                                              Text(
                                                'Start Meter',
                                                style: TextStyle(
                                                  color: Colors.white
                                                      .withOpacity(0.6),
                                                  fontSize: 11,
                                                ),
                                              ),
                                            ],
                                          ),
                                          if (sessionData['endMeter'] != null)
                                            Column(
                                              children: [
                                                Text(
                                                  '${sessionData['endMeter']}',
                                                  style: const TextStyle(
                                                    color: Colors.white,
                                                    fontWeight: FontWeight.bold,
                                                  ),
                                                ),
                                                Text(
                                                  'End Meter',
                                                  style: TextStyle(
                                                    color: Colors.white
                                                        .withOpacity(0.6),
                                                    fontSize: 11,
                                                  ),
                                                ),
                                              ],
                                            ),
                                        ],
                                      ),
                                    ],
                                  ],
                                ),
                              ),
                              const SizedBox(height: 20),
                              const Text(
                                'Task Breakdown',
                                style: TextStyle(
                                  fontSize: 16,
                                  fontWeight: FontWeight.bold,
                                  color: Colors.white,
                                ),
                              ),
                              const SizedBox(height: 12),
                              if (records.isEmpty)
                                Padding(
                                  padding: const EdgeInsets.symmetric(
                                    vertical: 20,
                                  ),
                                  child: Text(
                                    'No tasks recorded yet.',
                                    style: TextStyle(
                                      color: Colors.white.withOpacity(0.7),
                                    ),
                                  ),
                                )
                              else
                                ...records.map((doc) {
                                  final data =
                                      doc.data() as Map<String, dynamic>;
                                  final elapsed = _liveElapsed(data);
                                  final isRunning = data['status'] == 'running';

                                  return Padding(
                                    padding: const EdgeInsets.only(bottom: 10),
                                    child: GlassCard(
                                      padding: const EdgeInsets.all(14),
                                      child: Row(
                                        children: [
                                          if (isRunning) const PulsingDot(),
                                          if (isRunning)
                                            const SizedBox(width: 10),
                                          Expanded(
                                            child: Text(
                                              data['task'] ?? '',
                                              style: const TextStyle(
                                                color: Colors.white,
                                                fontWeight: FontWeight.bold,
                                                fontSize: 14,
                                              ),
                                            ),
                                          ),
                                          Text(
                                            _formatDuration(elapsed),
                                            style: const TextStyle(
                                              color: Colors.white,
                                              fontWeight: FontWeight.bold,
                                              fontFamily: 'monospace',
                                            ),
                                          ),
                                        ],
                                      ),
                                    ),
                                  );
                                }),
                            ],
                          ),
                        );
                      },
                    );
                  },
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

// ---------------- APP THEME (Central Design System) ----------------
class AppTheme {
  static const primaryDark = Color(0xFF1A1B4B);
  static const primaryMid = Color(0xFF3D2C8D);
  static const accent = Color(0xFF00D9C6);

  static const mainGradient = LinearGradient(
    begin: Alignment.topLeft,
    end: Alignment.bottomRight,
    colors: [Color(0xFF1A1B4B), Color(0xFF3D2C8D)],
  );

  static const cardGradient = LinearGradient(
    begin: Alignment.topLeft,
    end: Alignment.bottomRight,
    colors: [Color(0xFF3D2C8D), Color(0xFF6B4CE6)],
  );

  static BoxShadow softShadow = BoxShadow(
    color: Colors.black.withOpacity(0.12),
    blurRadius: 16,
    offset: const Offset(0, 6),
  );

  // UI Redesign Phase A — the app-wide ThemeData for the new "modern
  // enterprise SaaS" look (see lib/app_theme.dart for the AppColors/
  // AppText/AppSpacing tokens this builds from). Added as a new member of
  // the EXISTING AppTheme class above, rather than a new class of the same
  // name, so primaryDark/primaryMid/accent/mainGradient/cardGradient/
  // softShadow above — already used throughout the app (GarageScreen,
  // DashboardMenuCard, etc.) — keep working completely unchanged.
  static ThemeData light() {
    final base = ThemeData(useMaterial3: true, brightness: Brightness.light);
    final textTheme = GoogleFonts.interTextTheme(base.textTheme).apply(
      bodyColor: AppColors.textPrimary,
      displayColor: AppColors.textPrimary,
      fontFamilyFallback: appSinhalaFontFallback,
    );
    return base.copyWith(
      colorScheme: ColorScheme.fromSeed(
        seedColor: AppColors.primary,
        brightness: Brightness.light,
      ).copyWith(
        primary: AppColors.primary,
        secondary: AppColors.navy,
        error: AppColors.danger,
        surface: AppColors.card,
      ),
      scaffoldBackgroundColor: AppColors.background,
      textTheme: textTheme,
      pageTransitionsTheme: const PageTransitionsTheme(
        builders: {
          TargetPlatform.android: AppPageTransitionsBuilder(),
          TargetPlatform.iOS: AppPageTransitionsBuilder(),
          TargetPlatform.macOS: AppPageTransitionsBuilder(),
          TargetPlatform.windows: AppPageTransitionsBuilder(),
          TargetPlatform.linux: AppPageTransitionsBuilder(),
          TargetPlatform.fuchsia: AppPageTransitionsBuilder(),
        },
      ),
      cardTheme: CardThemeData(
        color: AppColors.card,
        elevation: 0,
        margin: EdgeInsets.zero,
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(AppRadius.card),
          side: const BorderSide(color: AppColors.border),
        ),
      ),
      // minimumSize is intentionally FINITE-width here (not
      // Size.fromHeight(48) / Size(double.infinity, 48), which this used to
      // be): a button with an infinite-width minimumSize placed directly
      // inside a Row/Wrap/AppBar actions/horizontal ScrollView (anything
      // that hands a non-flex child unbounded main-axis width) crashes
      // layout with "BoxConstraints forces an infinite width" — every
      // screen's "full width" buttons already wrap themselves in an
      // explicit SizedBox(width: double.infinity, child: ...) to get that
      // look, so they render identically with a finite theme default; only
      // buttons that relied on the theme alone for full width (none,
      // confirmed) would change shape.
      elevatedButtonTheme: ElevatedButtonThemeData(
        style: ElevatedButton.styleFrom(
          backgroundColor: AppColors.primary,
          foregroundColor: Colors.white,
          minimumSize: const Size(64, 48),
          elevation: 0,
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(AppRadius.button),
          ),
        ),
      ),
      filledButtonTheme: FilledButtonThemeData(
        style: FilledButton.styleFrom(
          backgroundColor: AppColors.primary,
          foregroundColor: Colors.white,
          minimumSize: const Size(64, 48),
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(AppRadius.button),
          ),
        ),
      ),
      outlinedButtonTheme: OutlinedButtonThemeData(
        style: OutlinedButton.styleFrom(
          foregroundColor: AppColors.primary,
          minimumSize: const Size(64, 48),
          side: const BorderSide(color: AppColors.border),
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(AppRadius.button),
          ),
        ),
      ),
      textButtonTheme: TextButtonThemeData(
        style: TextButton.styleFrom(foregroundColor: AppColors.primary),
      ),
      inputDecorationTheme: InputDecorationTheme(
        filled: true,
        fillColor: AppColors.card,
        labelStyle: const TextStyle(color: AppColors.textSecondary),
        hintStyle: const TextStyle(color: AppColors.textMuted),
        border: OutlineInputBorder(
          borderRadius: BorderRadius.circular(AppRadius.button),
          borderSide: const BorderSide(color: AppColors.border),
        ),
        enabledBorder: OutlineInputBorder(
          borderRadius: BorderRadius.circular(AppRadius.button),
          borderSide: const BorderSide(color: AppColors.border),
        ),
        focusedBorder: OutlineInputBorder(
          borderRadius: BorderRadius.circular(AppRadius.button),
          borderSide: const BorderSide(color: AppColors.primary, width: 1.5),
        ),
      ),
      appBarTheme: const AppBarTheme(
        backgroundColor: AppColors.card,
        foregroundColor: AppColors.textPrimary,
        elevation: 0,
        centerTitle: false,
        surfaceTintColor: Colors.transparent,
      ),
      dialogTheme: DialogThemeData(
        backgroundColor: AppColors.card,
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(AppRadius.card),
        ),
      ),
      bottomSheetTheme: const BottomSheetThemeData(
        backgroundColor: AppColors.card,
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.vertical(
            top: Radius.circular(AppRadius.card),
          ),
        ),
      ),
      chipTheme: ChipThemeData(
        backgroundColor: AppColors.primarySoft,
        labelStyle: const TextStyle(color: AppColors.primary),
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(AppRadius.chip),
        ),
        side: BorderSide.none,
      ),
      snackBarTheme: SnackBarThemeData(
        behavior: SnackBarBehavior.floating,
        backgroundColor: AppColors.navy,
        contentTextStyle: const TextStyle(color: Colors.white),
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(AppRadius.button),
        ),
      ),
      tabBarTheme: const TabBarThemeData(
        labelColor: AppColors.primary,
        unselectedLabelColor: AppColors.textSecondary,
        indicatorColor: AppColors.primary,
      ),
      dataTableTheme: DataTableThemeData(
        headingRowColor: WidgetStateProperty.all(AppColors.background),
        dataRowColor: WidgetStateProperty.all(AppColors.card),
      ),
      listTileTheme: const ListTileThemeData(iconColor: AppColors.textSecondary),
      popupMenuTheme: PopupMenuThemeData(
        color: AppColors.card,
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(AppRadius.button),
        ),
      ),
      dropdownMenuTheme: DropdownMenuThemeData(
        textStyle: AppText.body,
        menuStyle: MenuStyle(
          backgroundColor: WidgetStateProperty.all(AppColors.card),
          shape: WidgetStateProperty.all(
            RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(AppRadius.button),
            ),
          ),
        ),
      ),
      dividerColor: AppColors.border,
    );
  }
}

// ---------------- WEB APP SHELL (desktop sidebar layout, web only) ----------------
class WebSidebarItem {
  final IconData icon;
  final String label;
  final VoidCallback onTap;

  const WebSidebarItem({
    required this.icon,
    required this.label,
    required this.onTap,
  });
}

// Reusable shell that adds a fixed desktop sidebar around a screen's body
// content on wide web viewports. On mobile (or a narrow web window) it's a
// pure pass-through — returns child as-is, no wrapper — so it can never
// affect the mobile app layout.
class WebAppShell extends StatelessWidget {
  static const double sidebarWidth = 250;
  static const double desktopBreakpoint = 900;

  final String appName;
  final List<WebSidebarItem> menuItems;
  final VoidCallback onLogout;
  final Widget child;

  const WebAppShell({
    super.key,
    required this.appName,
    required this.menuItems,
    required this.onLogout,
    required this.child,
  });

  @override
  Widget build(BuildContext context) {
    final isDesktopWeb =
        kIsWeb && MediaQuery.of(context).size.width > desktopBreakpoint;
    if (!isDesktopWeb) {
      return child;
    }

    return Row(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        Container(
          width: sidebarWidth,
          decoration: const BoxDecoration(gradient: AppTheme.mainGradient),
          child: SafeArea(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Padding(
                  padding: const EdgeInsets.fromLTRB(20, 28, 20, 24),
                  child: Row(
                    children: [
                      Container(
                        width: 36,
                        height: 36,
                        decoration: BoxDecoration(
                          color: AppTheme.accent,
                          borderRadius: BorderRadius.circular(8),
                        ),
                        alignment: Alignment.center,
                        child: const Text(
                          'N',
                          style: TextStyle(
                            color: AppTheme.primaryDark,
                            fontWeight: FontWeight.bold,
                            fontSize: 18,
                          ),
                        ),
                      ),
                      const SizedBox(width: 12),
                      Expanded(
                        child: Text(
                          appName,
                          style: const TextStyle(
                            color: Colors.white,
                            fontWeight: FontWeight.bold,
                            fontSize: 16,
                          ),
                          overflow: TextOverflow.ellipsis,
                        ),
                      ),
                    ],
                  ),
                ),
                Expanded(
                  child: ListView(
                    padding: const EdgeInsets.symmetric(vertical: 8),
                    children: menuItems
                        .map(
                          (item) => _WebSidebarTile(
                            icon: item.icon,
                            label: item.label,
                            onTap: item.onTap,
                          ),
                        )
                        .toList(),
                  ),
                ),
                const Divider(color: Colors.white24, height: 1),
                _WebSidebarTile(
                  icon: Icons.logout,
                  label: 'Logout',
                  onTap: onLogout,
                ),
                const SizedBox(height: 12),
              ],
            ),
          ),
        ),
        Expanded(child: child),
      ],
    );
  }
}

class _WebSidebarTile extends StatefulWidget {
