                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Row(
                                  children: [
                                    Icon(
                                      canLoad
                                          ? Icons.check_circle
                                          : Icons.cancel,
                                      color: canLoad
                                          ? Colors.greenAccent
                                          : Colors.redAccent,
                                      size: 16,
                                    ),
                                    const SizedBox(width: 6),
                                    const Text(
                                      'Loading Capability',
                                      style: TextStyle(
                                        color: Colors.white,
                                        fontSize: 13,
                                      ),
                                    ),
                                  ],
                                ),
                                const SizedBox(height: 6),
                                Row(
                                  children: [
                                    Icon(
                                      canUnload
                                          ? Icons.check_circle
                                          : Icons.cancel,
                                      color: canUnload
                                          ? Colors.greenAccent
                                          : Colors.redAccent,
                                      size: 16,
                                    ),
                                    const SizedBox(width: 6),
                                    const Text(
                                      'Unloading Capability',
                                      style: TextStyle(
                                        color: Colors.white,
                                        fontSize: 13,
                                      ),
                                    ),
                                  ],
                                ),
                              ],
                            ),
                          ),
                          TextButton.icon(
                            onPressed: () => _showChangeSiteCapabilityDialog(
                              context,
                              canLoad,
                              canUnload,
                            ),
                            icon: const Icon(
                              Icons.edit,
                              size: 16,
                              color: AppTheme.accent,
                            ),
                            label: const Text(
                              'Change',
                              style: TextStyle(color: AppTheme.accent),
                            ),
                          ),
                        ],
                      ),
                    );
                  },
                ),
              ),
              Expanded(
                child: StreamBuilder<QuerySnapshot>(
                  stream: FirebaseFirestore.instance
                      .collection('daily_sessions')
                      .where('siteId', isEqualTo: siteId)
                      .snapshots(),
                  builder: (context, snapshot) {
                    if (snapshot.hasError) {
                      return Center(
                        child: Padding(
                          padding: const EdgeInsets.all(24),
                          child: Text(
                            'Error: ${snapshot.error}',
                            style: const TextStyle(color: Colors.white),
                            textAlign: TextAlign.center,
                          ),
                        ),
                      );
                    }
                    if (!snapshot.hasData) {
                      return const Center(
                        child: CircularProgressIndicator(color: Colors.white),
                      );
                    }
                    final sessions = snapshot.data!.docs;
                    if (sessions.isEmpty) {
                      return const Center(
                        child: Text(
                          'No work history for this site yet.',
                          style: TextStyle(color: Colors.white),
                        ),
                      );
                    }

                    // Group sessions by date
                    final Map<String, List<QueryDocumentSnapshot>> grouped = {};
                    for (final doc in sessions) {
                      final data = doc.data() as Map<String, dynamic>;
                      final date = data['date'] ?? 'unknown';
                      grouped.putIfAbsent(date, () => []).add(doc);
                    }
                    final sortedDates = grouped.keys.toList()
                      ..sort((a, b) => b.compareTo(a));

                    // ONE batched query for every session on screen (see
                    // loadWorkRecordsBySessionDate's doc comment) instead
                    // of 2 work_records subcollection reads PER ROW. Every
                    // row's FutureBuilder below shares this SAME Future
                    // instance — one real query fires, each row still gets
                    // its own independent "waiting" -> "has data" loading
                    // state exactly as before.
                    final recordsBySessionFuture =
                        loadWorkRecordsBySessionDate(sessions);

                    return ListView.builder(
                      padding: const EdgeInsets.all(16),
                      itemCount: sortedDates.length,
                      itemBuilder: (context, dateIndex) {
                        final date = sortedDates[dateIndex];
                        final dayColor =
                            _dayColors[dateIndex % _dayColors.length];
                        final daySessions = grouped[date]!;

                        return Padding(
                          padding: const EdgeInsets.only(bottom: 20),
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Row(
                                children: [
                                  Container(
                                    width: 10,
                                    height: 10,
                                    decoration: BoxDecoration(
                                      color: dayColor,
                                      shape: BoxShape.circle,
                                    ),
                                  ),
                                  const SizedBox(width: 8),
                                  Text(
                                    _formatDateHeader(date),
                                    style: const TextStyle(
                                      color: Colors.white,
                                      fontWeight: FontWeight.bold,
                                      fontSize: 15,
                                    ),
                                  ),
                                ],
                              ),
                              const SizedBox(height: 10),
                              ...daySessions.map((doc) {
                                final data = doc.data() as Map<String, dynamic>;
                                final isActive = data['status'] == 'active';

                                return Padding(
                                  padding: const EdgeInsets.only(
                                    bottom: 10,
                                    left: 18,
                                  ),
                                  child: Container(
                                    decoration: BoxDecoration(
                                      color: Colors.white.withOpacity(0.1),
                                      borderRadius: BorderRadius.circular(14),
                                      border: Border(
                                        left: BorderSide(
                                          color: dayColor,
                                          width: 4,
                                        ),
                                      ),
                                    ),
                                    padding: const EdgeInsets.all(14),
                                    child: Column(
                                      crossAxisAlignment:
                                          CrossAxisAlignment.start,
                                      children: [
                                        Row(
                                          mainAxisAlignment:
                                              MainAxisAlignment.spaceBetween,
                                          children: [
                                            Expanded(
                                              child: Text(
                                                data['machineName'] ?? '',
                                                style: const TextStyle(
                                                  color: Colors.white,
                                                  fontWeight: FontWeight.bold,
                                                  fontSize: 14,
                                                ),
                                              ),
                                            ),
                                            GestureDetector(
                                              onTap: isActive
                                                  ? () => _showForceCloseDialog(
                                                      context,
                                                      doc.id,
                                                      data['startMeter'],
                                                    )
                                                  : null,
                                              child: Container(
                                                padding:
                                                    const EdgeInsets.symmetric(
                                                      horizontal: 8,
                                                      vertical: 3,
                                                    ),
                                                decoration: BoxDecoration(
                                                  color: isActive
                                                      ? Colors.green
                                                      : Colors.grey,
                                                  borderRadius:
                                                      BorderRadius.circular(20),
                                                ),
                                                child: Row(
                                                  mainAxisSize:
                                                      MainAxisSize.min,
                                                  children: [
                                                    Text(
                                                      isActive
                                                          ? 'ACTIVE'
                                                          : 'DONE',
                                                      style: const TextStyle(
                                                        color: Colors.white,
                                                        fontSize: 10,
                                                      ),
                                                    ),
                                                    if (isActive) ...[
                                                      const SizedBox(width: 4),
                                                      const Icon(
                                                        Icons.edit,
                                                        size: 11,
                                                        color: Colors.white,
                                                      ),
                                                    ],
                                                  ],
                                                ),
                                              ),
                                            ),
                                          ],
                                        ),
                                        const SizedBox(height: 4),
                                        Text(
                                          'Supervisor: ${data['supervisorName'] ?? '-'}',
                                          style: TextStyle(
                                            color: Colors.white.withOpacity(
                                              0.7,
                                            ),
                                            fontSize: 12,
                                          ),
                                        ),
                                        Text(
                                          'Started: ${_formatTime(data['createdAt'] as Timestamp?)}'
                                          '${data['completedAt'] != null ? "  •  Ended: ${_formatTime(data['completedAt'] as Timestamp?)}" : ""}',
                                          style: TextStyle(
                                            color: Colors.white.withOpacity(
                                              0.6,
                                            ),
                                            fontSize: 11,
                                          ),
                                        ),
                                        if (data['startMeter'] != null) ...[
                                          const SizedBox(height: 4),
                                          Row(
                                            children: [
                                              Icon(
                                                Icons.speed,
                                                size: 13,
                                                color: Colors.white.withOpacity(
                                                  0.7,
                                                ),
                                              ),
                                              const SizedBox(width: 4),
                                              Text(
                                                'Start Meter: ${data['startMeter']}'
                                                '${data['endMeter'] != null ? "  •  End Meter: ${data['endMeter']}" : ""}',
                                                style: TextStyle(
                                                  color: Colors.white
                                                      .withOpacity(0.7),
                                                  fontSize: 12,
                                                ),
                                              ),
                                            ],
                                          ),
                                        ],
                                        const SizedBox(height: 8),
                                        FutureBuilder<
                                            Map<String, List<Map<String, dynamic>>>>(
                                          future: recordsBySessionFuture,
                                          builder: (context, futureSnap) {
                                            if (!futureSnap.hasData) {
                                              return const SizedBox(
                                                height: 16,
                                                width: 16,
                                                child:
                                                    CircularProgressIndicator(
                                                      strokeWidth: 2,
                                                      color: Colors.white,
                                                    ),
                                              );
                                            }
                                            final records =
                                                futureSnap.data![doc.id] ??
                                                    const [];
                                            final loads =
                                                _loadCountFromRecords(records);
                                            final seconds =
                                                _totalSecondsFromRecords(records);
                                            return Row(
                                              children: [
                                                Icon(
                                                  Icons.local_shipping,
                                                  size: 14,
                                                  color: Colors.white
                                                      .withOpacity(0.7),
                                                ),
                                                const SizedBox(width: 4),
                                                Text(
                                                  '$loads loads',
                                                  style: TextStyle(
                                                    color: Colors.white
                                                        .withOpacity(0.8),
                                                    fontSize: 12,
                                                  ),
                                                ),
                                                const SizedBox(width: 16),
                                                Icon(
                                                  Icons.timer,
                                                  size: 14,
                                                  color: Colors.white
                                                      .withOpacity(0.7),
                                                ),
                                                const SizedBox(width: 4),
                                                Text(
                                                  _formatDuration(seconds),
                                                  style: TextStyle(
                                                    color: Colors.white
                                                        .withOpacity(0.8),
                                                    fontSize: 12,
                                                  ),
                                                ),
                                              ],
                                            );
                                          },
                                        ),
                                      ],
                                    ),
                                  ),
                                );
                              }),
                            ],
                          ),
                        );
                      },
                    );
                  },
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

// ---------------- ADMIN SITE LIST (navigates to shared SiteHistoryScreen) ----------------
class AdminSiteListScreen extends StatelessWidget {
  const AdminSiteListScreen({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Container(
        decoration: const BoxDecoration(gradient: AppTheme.mainGradient),
        child: SafeArea(
          child: Column(
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 8, 16, 0),
                child: Row(
                  children: [
                    IconButton(
                      icon: const Icon(Icons.arrow_back, color: Colors.white),
                      onPressed: () => Navigator.pop(context),
                    ),
                    const Text(
                      'Site History',
                      style: TextStyle(
                        fontSize: 18,
                        fontWeight: FontWeight.bold,
                        color: Colors.white,
                      ),
                    ),
                  ],
                ),
              ),
              Expanded(
                child: StreamBuilder<QuerySnapshot>(
                  stream: ReferenceCollectionCache.stream('sites'),
                  builder: (context, snapshot) {
                    if (!snapshot.hasData) {
                      return const Center(
                        child: CircularProgressIndicator(color: Colors.white),
                      );
                    }
                    final sites = snapshot.data!.docs;
                    if (sites.isEmpty) {
                      return const Center(
                        child: Text(
                          'No sites added yet.',
                          style: TextStyle(color: Colors.white),
                        ),
                      );
                    }

                    return ListView.builder(
                      padding: const EdgeInsets.all(16),
                      itemCount: sites.length,
                      itemBuilder: (context, index) {
                        final data =
                            sites[index].data() as Map<String, dynamic>;
                        return Padding(
                          padding: const EdgeInsets.only(bottom: 12),
                          child: _WebStaggeredFadeIn(
                            index: index,
                            child: DashboardMenuCard(
                              icon: Icons.location_on,
                              title: data['name'] ?? '',
                              subtitle: data['location'] ?? '',
                              color: Colors.teal,
                              onTap: () {
                                pushWebAware(
                                  context,
                                  SiteHistoryScreen(
                                    siteId: sites[index].id,
                                    siteName: data['name'] ?? '',
                                  ),
                                );
                              },
                            ),
                          ),
                        );
                      },
                    );
                  },
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

// Site name (trimmed, lowercase) -> dedicated Google Sheet tab name. Every
// completed load at a mapped site gets duplicated to its own tab,
// independent of and in addition to the Supervisor_Loads/Plant_Loads sync.
// Shared between _WorkSessionScreenState (task-complete time) and
// ManagementSiteReportsScreen's Edit dialog (post-edit resync), so both
// stay consistent. Add new loading site -> sheet name mappings here.
const Map<String, String> kSiteSheetMap = {
  'athukorala land': 'Athukorala_Land_Loads',
  // The actual Firestore site name is "Lalitha Land" (confirmed live on
  // device, from an active work session's denormalized siteName field) —
  // not "Lalith Land". The key must match the real site name exactly;
  // Lalith_Land_Loads is kept as the sheet tab name since that's what's
  // already referenced in the Google Sheet.
  'lalitha land': 'Lalith_Land_Loads',
  'hesei site': 'Hesei_Site_Loads',
  // Site was renamed "Dhompe Site" -> "Dompe Site" via Site Management's
  // edit feature — this key must track the CURRENT Firestore site name
  // (kSiteSheetMap is a static const, so a rename doesn't update it on its
  // own). The Google Sheet tab itself was also manually renamed to match
  // (Dhompe_Site_Loads -> Dompe_Site_Loads), so the value had to move too.
  'dompe site': 'Dompe_Site_Loads',
  'cmc plant': 'CMC_Plant_Loads',
  'maga site': 'Maga_Site_Loads',
  'rajakaruna land': 'Rajakaruna_Land_Loads',
};

// trim()+toLowerCase() alone doesn't catch a doubled internal space (e.g. a
// site named "Lalith  Land" typo'd with two spaces when it was added in
// Site Management) — that would silently fail a kSiteSheetMap lookup since
// the map's keys use a single space. Collapsing internal whitespace closes
// that gap. Always look up kSiteSheetMap through this, not a raw
// .trim().toLowerCase().
String normalizeSiteNameForSheetLookup(String siteName) {
  return siteName.trim().toLowerCase().replaceAll(RegExp(r'\s+'), ' ');
}

// ---------------- GOOGLE SHEETS SYNC SERVICE ----------------
class GoogleSheetsService {
  static const String _webAppUrl =
      'https://script.google.com/macros/s/AKfycbyDjLHlC7MuTeKw2gA6W-7Rlpj1a6aU17RWzHBLPI7B93bXAGOs99IzLpYpc4nd3AY/exec';

  // recordId (a Firestore work_record/fuel_entry doc ID) lets the Apps
  // Script update that row in place instead of always appending — see
  // doPost's recordId lookup against the sheet's last column. Omit it (or
  // pass null) for rows that should always append, e.g. the End Day summary
  // row, which never corresponds 1:1 with a single existing Sheet row.
  static Future<void> sendRow({
    required String sheetName,
    required List<dynamic> row,
    String? recordId,
  }) async {
    try {
      // Record ID is appended as the row's actual last column (visible in
      // the sheet, hideable manually there) — existing columns are
      // untouched, this is purely additive. It's also sent as its own
      // top-level field for the Apps Script's update-in-place lookup, so it
      // doesn't have to assume which index is "last".
      final rowWithRecordId = [...row, recordId ?? ''];

      // Content-Type must stay outside the CORS-safelisted set (text/plain,
      // not application/json) — Apps Script web apps don't answer the
      // OPTIONS preflight a JSON content-type forces, so on Flutter Web the
      // browser blocks the request before it ever reaches the script. The
      // Apps Script side reads the raw body text and JSON-decodes it itself,
      // so it doesn't care what the header says.
      await http.post(
        Uri.parse(_webAppUrl),
        headers: {'Content-Type': 'text/plain'},
        body: jsonEncode({
          'sheetName': sheetName,
          'row': rowWithRecordId,
          'recordId': recordId ?? '',
        }),
      );
    } catch (e) {
      // Silently fail - Sheets sync is a nice-to-have, shouldn't break the app
      debugPrint('Google Sheets sync error for sheetName=$sheetName: $e');
    }
  }

  static String formatDate(DateTime dt) {
    return "${dt.year}-${dt.month.toString().padLeft(2, '0')}-${dt.day.toString().padLeft(2, '0')}";
  }

  static String formatTime(dynamic ts) {
    if (ts == null) return '-';
    DateTime dt;
    if (ts is Timestamp) {
      dt = ts.toDate();
    } else {
      return '-';
    }
    final hour = dt.hour % 12 == 0 ? 12 : dt.hour % 12;
    final period = dt.hour >= 12 ? 'PM' : 'AM';
    final minute = dt.minute.toString().padLeft(2, '0');
    return '$hour:$minute $period';
  }
}

// ---------------- TRACCAR SERVICE (GPS Live Tracking, web-only — Phase 1) ----------------
// Thin REST client for the self-hosted Traccar server this fleet's GPS
// trackers report positions to. Traccar has its own separate auth model
// (server username/password, Basic-Authenticated — nothing to do with
// Firebase Auth), so every call here takes credentials explicitly rather
// than reading FirebaseAuth.instance.currentUser. Requires the Traccar
// server's web.origin CORS setting to allow this app's origin (see the
// firestore-adjacent /opt/traccar/conf/traccar.xml note given alongside
// this feature) — without it, the browser blocks these requests before
// they ever reach Traccar.
class TraccarService {
  // https, not the bare IP:8082 — a Flutter web build served over https
  // blocks plain-http requests as Mixed Content before they ever leave the
  // browser, regardless of Traccar's own CORS/web.origin setting.
  static const String baseUrl = 'https://traccar.noda.lk';

  // Regression fix (slow/local Traccar deployment): every call used to
  // share one uniform 5s hard timeout (via VehicleKmCache), which this
  // specific server routinely exceeds — so every km/device/position fetch
  // was being aborted before it ever had a chance to succeed, leaving
  // Garage with no GPS details and Live Tracking's map with no markers at
  // all. .timeout() never cancels the underlying HTTP request (Dart has no
  // way to abort an in-flight http.get call) — it only stops the CALLER
  // from waiting past this duration, so a slow-but-eventually-successful
  // response still completes in the background and still gets logged/
  // cached below; only a response slower than this is actually given up
  // on. /api/reports/summary gets longer than /api/devices or
  // /api/positions because it's the heaviest endpoint by far (a report
  // computed over a date range, not a simple lookup).
  static const Duration positionsTimeout = Duration(seconds: 25);
  static const Duration devicesTimeout = Duration(seconds: 25);
  static const Duration summaryTimeout = Duration(seconds: 30);

  static Map<String, String> _authHeaders(String username, String password) {
    final credentials = base64Encode(utf8.encode('$username:$password'));
    return {
      'Authorization': 'Basic $credentials',
      'Accept': 'application/json',
    };
  }

  // Every real HTTP call in this class goes through here (or _timedCall
  // below, for the 3 endpoints with a test-only override seam) —
  // centralizes the per-endpoint timeout above with kDebugMode-only
  // before/after logging (endpoint, duration, outcome), so a slow call is
  // visible in the Chrome console instead of silently degrading to a
  // fallback with no trace of why. Format: "[TRACCAR] <label> <ms>ms
  // <outcome>", outcome one of "status=<code>", "TIMEOUT (limit <n>s)", or
  // "ERROR <exception>".
  static Future<http.Response> _timedGet(
    String label,
    Uri uri,
    Map<String, String> headers,
    Duration timeout,
  ) async {
    final stopwatch = Stopwatch()..start();
    try {
      final response = await http.get(uri, headers: headers).timeout(timeout);
      if (kDebugMode) {
        debugPrint('[TRACCAR] $label ${stopwatch.elapsedMilliseconds}ms status=${response.statusCode}');
      }
      return response;
    } on TimeoutException {
      if (kDebugMode) {
        debugPrint(
          '[TRACCAR] $label ${stopwatch.elapsedMilliseconds}ms TIMEOUT '
          '(limit ${timeout.inSeconds}s)',
        );
      }
      rethrow;
    } catch (e) {
      if (kDebugMode) {
        debugPrint('[TRACCAR] $label ${stopwatch.elapsedMilliseconds}ms ERROR $e');
      }
      rethrow;
    }
  }

  // Same timing/logging/timeout contract as _timedGet, but wraps an
  // arbitrary async body instead of specifically an http.get — used by the
  // 3 methods below that have a test-only override seam
  // (fetchPositionsOverride/fetchDevicesOverride/
  // fetchDistanceSummaryOverride), so a test controlling WHEN the override
  // resolves/hangs exercises this exact timeout+logging path too, not just
  // production's real HTTP call. A successful call logs "ok" (a non-200
  // HTTP response is thrown as an Exception by the caller before reaching
  // here, so it's already captured by the ERROR branch's message, same as
  // a real network failure).
  static Future<T> _timedCall<T>(
    String label,
    Duration timeout,
    Future<T> Function() body,
  ) async {
    final stopwatch = Stopwatch()..start();
    try {
      final result = await body().timeout(timeout);
      if (kDebugMode) {
        debugPrint('[TRACCAR] $label ${stopwatch.elapsedMilliseconds}ms ok');
      }
      return result;
    } on TimeoutException {
      if (kDebugMode) {
        debugPrint(
          '[TRACCAR] $label ${stopwatch.elapsedMilliseconds}ms TIMEOUT '
          '(limit ${timeout.inSeconds}s)',
        );
      }
      rethrow;
    } catch (e) {
      if (kDebugMode) {
        debugPrint('[TRACCAR] $label ${stopwatch.elapsedMilliseconds}ms ERROR $e');
      }
      rethrow;
    }
  }

  // GET /api/positions — the latest known position for every device this
  // account can see. Each entry carries deviceId (Traccar's internal
  // numeric device id — NOT the same as a device's uniqueId/Identifier
  // string, see fetchDevices below), latitude, longitude, speed (knots,
  // Traccar's convention), and fixTime (when the GPS fix was actually
  // taken, as opposed to serverTime/when Traccar received it).
  // Test-only seam (see test/traccar_timeout_logging_test.dart) — null in
  // every production path.
  @visibleForTesting
  static Future<List<Map<String, dynamic>>> Function()? fetchPositionsOverride;

  // Last successful fetchPositions() result (any caller — Live Tracking,
  // arrival detection, VehicleKmCache.positions). Lets the km code reuse
  // positions that were already fetched instead of asking Traccar again.
  static List<Map<String, dynamic>>? lastPositions;
  static DateTime? lastPositionsAt;

  static Future<List<Map<String, dynamic>>> fetchPositions({
    required String username,
    required String password,
  }) {
    return _fetchPositionsTimed(username: username, password: password).then((p) {
      lastPositions = p;
      lastPositionsAt = DateTime.now();
      return p;
    });
  }

  static Future<List<Map<String, dynamic>>> _fetchPositionsTimed({
    required String username,
    required String password,
  }) {
    return _timedCall('GET /api/positions', positionsTimeout, () async {
      final override = fetchPositionsOverride;
      if (override != null) return override();
      final response = await http.get(
        Uri.parse('$baseUrl/api/positions'),
        headers: _authHeaders(username, password),
      );
      if (response.statusCode != 200) {
        throw Exception(
          'Traccar fetchPositions failed: HTTP ${response.statusCode}',
        );
      }
      final decoded = jsonDecode(response.body) as List<dynamic>;
      return decoded.cast<Map<String, dynamic>>();
    });
  }

  // GET /api/devices — id/uniqueId/name for every device registered on the
  // server. uniqueId is the "Identifier" shown in Traccar's own Devices
  // list — the same string an admin types into TruckProfileScreen's
  // Assigned GPS Device field (trucks/{id}.gpsDeviceId). LiveTrackingScreen
  // uses this to join a fetchPositions() entry's numeric deviceId back to a
  // specific truck: deviceId -> uniqueId (via this list) -> gpsDeviceId
  // match (via Firestore).
  // Test-only seam — null in every production path. Distinct from
  // VehicleKmCache.devicesFetcherOverride, which short-circuits BEFORE this
  // method is ever reached; this one exercises the real timeout/logging
  // path below.
  @visibleForTesting
  static Future<List<Map<String, dynamic>>> Function()? fetchDevicesOverride;

  static Future<List<Map<String, dynamic>>> fetchDevices({
    required String username,
    required String password,
  }) {
    return _timedCall('GET /api/devices', devicesTimeout, () async {
      final override = fetchDevicesOverride;
      if (override != null) return override();
      final response = await http.get(
        Uri.parse('$baseUrl/api/devices'),
        headers: _authHeaders(username, password),
      );
      if (response.statusCode != 200) {
        throw Exception(
          'Traccar fetchDevices failed: HTTP ${response.statusCode}',
        );
      }
      final decoded = jsonDecode(response.body) as List<dynamic>;
      return decoded.cast<Map<String, dynamic>>();
    });
  }

  // GET /api/reports/summary — total distance (meters) for one device over
  // a date range. Confirmed against Traccar's official OpenAPI spec: this
  // endpoint takes deviceId/groupId + from + to only — there is NO "daily"
  // boolean parameter, despite that being a natural thing to expect. A
  // per-day breakdown (see GpsDeviceManagementScreen's KM History panel)
  // is done by calling this once per day with a 24h from/to window, not by
  // a single call with a daily flag. deviceId here is Traccar's internal
  // numeric id (from fetchDevices' "id" field), not the uniqueId/Identifier
  // string stored as trucks/{id}.gpsDeviceId.
  // Test-only seam (see test/vehicle_km_cache_test.dart's delta-since-cache
  // coverage) — lets a test verify GarageService._fetchCurrentTotalKm's
  // from/to range without a real HTTP call, while VehicleKmCache's own
  // devicesFetcherOverride/kmFetcherOverride (which short-circuit BEFORE
  // this method) are left unset. Null in every production path.
  @visibleForTesting
  static Future<double> Function({required int deviceId, required DateTime from, required DateTime to})?
      fetchDistanceSummaryOverride;

  static Future<double> fetchDistanceSummary({
    required String username,
    required String password,
    required int deviceId,
    required DateTime from,
    required DateTime to,
  }) {
    return _timedCall('GET /api/reports/summary', summaryTimeout, () async {
      final override = fetchDistanceSummaryOverride;
      if (override != null) {
        return override(deviceId: deviceId, from: from, to: to);
      }
      final uri = Uri.parse('$baseUrl/api/reports/summary').replace(
        queryParameters: {
          'deviceId': deviceId.toString(),
          'from': from.toUtc().toIso8601String(),
          'to': to.toUtc().toIso8601String(),
        },
      );
      final response = await http.get(uri, headers: _authHeaders(username, password));
      if (response.statusCode != 200) {
        throw Exception(
          'Traccar fetchDistanceSummary failed: HTTP ${response.statusCode}',
        );
      }
      final decoded = jsonDecode(response.body) as List<dynamic>;
      double totalMeters = 0;
      for (final entry in decoded) {
        totalMeters +=
            ((entry as Map<String, dynamic>)['distance'] as num?)?.toDouble() ??
            0;
      }
      return totalMeters;
    });
  }

  // GET /api/positions?deviceId=X&from=ISO&to=ISO — position history for
  // one device over a date range, distinct from the no-filter
  // fetchPositions() above (which only returns each device's LATEST
  // position). deviceId is Traccar's internal numeric id, same convention
  // as fetchDistanceSummary — not the uniqueId/Identifier string stored as
  // trucks/{id}.gpsDeviceId. username/password are required here (Basic
  // Auth, same as every other call in this class) even though they weren't
  // in the originally sketched signature — this endpoint can't authenticate
  // without them.
  static Future<List<Map<String, double>>> fetchPositionHistory({
    required String username,
    required String password,
    required int deviceId,
    required DateTime from,
    required DateTime to,
  }) async {
    final uri = Uri.parse('$baseUrl/api/positions').replace(
      queryParameters: {
        'deviceId': deviceId.toString(),
        'from': from.toUtc().toIso8601String(),
        'to': to.toUtc().toIso8601String(),
      },
    );
    final response = await _timedGet(
      'GET /api/positions (history)',
      uri,
      _authHeaders(username, password),
      positionsTimeout,
    );
    if (response.statusCode != 200) {
      throw Exception(
        'Traccar fetchPositionHistory failed: HTTP ${response.statusCode}',
      );
    }
    final decoded = jsonDecode(response.body) as List<dynamic>;
    final points = <Map<String, double>>[];
    for (final entry in decoded) {
      final map = entry as Map<String, dynamic>;
      final lat = (map['latitude'] as num?)?.toDouble();
      final lng = (map['longitude'] as num?)?.toDouble();
      if (lat != null && lng != null) {
        points.add({'latitude': lat, 'longitude': lng});
      }
    }
    return points;
  }

  // GET /api/positions?deviceId=X&from=ISO&to=ISO — same endpoint and
  // deviceId convention as fetchPositionHistory above, but for
  // LiveTrackingScreen's Vehicle Speed feature, which additionally needs
  // each point's speed and fix time to color-code the route by speed band.
  // Kept as its own method with its own return shape ({latitude, longitude,
  // speedKmh, fixTime} per point, speed pre-converted from Traccar's knots
  // to km/h) rather than changing fetchPositionHistory's — that method's
  // existing {latitude, longitude}-only shape is exactly what the bill
  // route drawing already depends on, and widening it risks a regression
  // there for a completely unrelated feature.
  static Future<List<Map<String, dynamic>>> fetchPositionsWithSpeed({
    required String username,
    required String password,
    required int deviceId,
    required DateTime from,
    required DateTime to,
  }) async {
    final uri = Uri.parse('$baseUrl/api/positions').replace(
      queryParameters: {
        'deviceId': deviceId.toString(),
        'from': from.toUtc().toIso8601String(),
        'to': to.toUtc().toIso8601String(),
      },
    );
    final response = await _timedGet(
      'GET /api/positions (speed)',
      uri,
      _authHeaders(username, password),
      positionsTimeout,
    );
    if (response.statusCode != 200) {
      throw Exception(
        'Traccar fetchPositionsWithSpeed failed: HTTP ${response.statusCode}',
      );
    }
    final decoded = jsonDecode(response.body) as List<dynamic>;
    final points = <Map<String, dynamic>>[];
    for (final entry in decoded) {
      final map = entry as Map<String, dynamic>;
      final lat = (map['latitude'] as num?)?.toDouble();
      final lng = (map['longitude'] as num?)?.toDouble();
      final speedKnots = (map['speed'] as num?)?.toDouble() ?? 0;
      final fixTime = DateTime.tryParse((map['fixTime'] ?? '').toString());
      if (lat == null || lng == null || fixTime == null) continue;
      points.add({
        'latitude': lat,
        'longitude': lng,
        'speedKmh': speedKnots * 1.852,
        'fixTime': fixTime,
        // speedKmh above keeps its 0 fallback (route colors/history are
        // unchanged); the live badge uses this to show '-' instead of 0.
        'hasSpeed': map['speed'] is num,
      });
    }
    return points;
  }
}

// Emitted on AutoArrivalDetectionService.onLoadCompleted whenever a load
// auto-completes (Company or Private) — see LiveTrackingScreen, which shows
// a SnackBar for these.
class LoadCompletionEvent {
  final String truckNumber;
  final String billNumber;
  final String siteName;

  const LoadCompletionEvent({
    required this.truckNumber,
    required this.billNumber,
    required this.siteName,
  });
}

// ---------------- AUTO ARRIVAL DETECTION SERVICE ----------------
// Completes any work_record marked autoCompleteViaGps: true (QR-scanned
// Company/Private Loads, and manual-flow Private Loads — see
// WorkSessionScreen._startNewWork's doc comment on that parameter for who
// sets it). Company Loads complete once the truck's live GPS position lands
// within 50m of the load's pre-selected unloading site; Private Loads
// complete via return-path detection (see _checkPrivateLoadReturn).
// Triggered from LiveTrackingScreen's existing 15s position-refresh timer
// (_refreshPositions) — no separate timer of its own, per that requirement.
class AutoArrivalDetectionService {
  static const String _traccarUsername = 'it.noda.main01@gmail.com';
  static const String _traccarPassword = 'IT@2026';
  static const double _arrivalRadiusMeters = 100;
  // Private-load return-path detection (see _checkPrivateLoadReturn) — a
  // private load has no registered delivery site to arrive at, so instead
  // it's treated as complete once the truck has gone far enough from its
  // start (avoiding a false positive right at load-start) and then come
  // back close to its own outbound path.
  static const double _privateLoadMinTravelMeters = 500;
  static const double _privateLoadReturnRadiusMeters = 20;
  // Change-detection for checkAllActiveLoads' [COMPANY_CHECK_*] investigation
  // logging — keyed by "$truckNumber|$siteName", value is the last-printed
  // signature (nearest distance rounded to the metre + arrived + loading
  // site name) for that pair, so an unchanged truck+site combination isn't
  // re-logged every 15s tick.
  static final Map<String, String> _lastLoggedCompanyCheck = {};
  // Same idea for the catch-all failure line — a permanent failure (e.g.
  // permission-denied) is printed once, not every 15s tick.
  static String? _lastCompanyCheckError;

  // Broadcast (not single-subscription) so this doesn't break if more than
  // one listener ever attaches — currently just LiveTrackingScreen, which
  // subscribes in initState/cancels in dispose to show a completion
  // SnackBar. Never closed: this is a static, app-lifetime singleton
  // service, same as the rest of this class.
  static final StreamController<LoadCompletionEvent> _completionController =
      StreamController<LoadCompletionEvent>.broadcast();
  static Stream<LoadCompletionEvent> get onLoadCompleted =>
      _completionController.stream;

  static Future<void> checkAllActiveLoads() async {
    try {
      // isCompleted == false is the same single-field-equality query
      // LiveTrackingScreen's own bill-number lookup already uses — proven,
      // no composite index needed (no orderBy paired with it), unlike the
      // old unloadingSiteName == '' filter. This now matches every running
      // work_record (any category, either flow), so it's narrowed to just
      // autoCompleteViaGps: true ones client-side below.
      final activeLoadsSnap = await FirebaseFirestore.instance
          .collectionGroup('work_records')
          .where('isCompleted', isEqualTo: false)
          .get();
      // Both flows (QR and manual New Work) set autoCompleteViaGps: true on
      // a Company Load and omit it on a Private Load, which is created
      // already complete — so this narrows to exactly the Company Loads
      // still waiting on arrival.
      final activeLoads = activeLoadsSnap.docs
          .where((doc) => doc.data()['autoCompleteViaGps'] == true)
          .toList();
      if (activeLoads.isEmpty) return;

      final positions = await TraccarService.fetchPositions(
        username: _traccarUsername,
        password: _traccarPassword,
      );
      // Shared with VehicleKmCache's own device-list cache (2 min TTL) —
      // this runs on the same 15s timer tick as LiveTrackingScreen's own
      // _refreshPositions, which independently needed this same fleet-wide
      // list; routing both through the cache means at most one real
      // /api/devices call between them per TTL window instead of two.
      final devices = await VehicleKmCache.devices();
      // position.deviceId is Traccar's internal numeric id, not the
      // uniqueId/Identifier string stored as trucks/{id}.gpsDeviceId — see
      // fetchDevices' doc comment for the same bridge LiveTrackingScreen's
      // own _refreshPositions uses.
      final uniqueIdByDeviceId = <int, String>{
        for (final device in devices)
          if (device['id'] is int && device['uniqueId'] is String)
            device['id'] as int: device['uniqueId'] as String,
      };
      // Reverse of the above — needed to call
      // TraccarService.fetchPositionHistory (which takes Traccar's numeric
      // device id), both for the post-arrival distanceKm calculation below
      // and (originally) for a private load's truck in the now-disabled
      // _checkPrivateLoadReturn.
      final deviceIdByUniqueId = <String, int>{
        for (final device in devices)
          if (device['id'] is int && device['uniqueId'] is String)
            device['uniqueId'] as String: device['id'] as int,
      };
      final positionByGpsDeviceId = <String, LatLng>{};
      for (final position in positions) {
        final deviceId = position['deviceId'];
        final lat = (position['latitude'] as num?)?.toDouble();
        final lng = (position['longitude'] as num?)?.toDouble();
        if (deviceId is! int || lat == null || lng == null) continue;
        final uniqueId = uniqueIdByDeviceId[deviceId];
        if (uniqueId == null) continue;
        positionByGpsDeviceId[uniqueId] = LatLng(lat, lng);
      }
      if (positionByGpsDeviceId.isEmpty) return;

      final trucksSnap = await FirebaseFirestore.instance
          .collection('trucks')
          .get();
      final gpsDeviceIdByTruckNumber = <String, String>{
        for (final doc in trucksSnap.docs)
          if ((doc.data()['gpsDeviceId'] as String?)?.isNotEmpty == true)
            (doc.data()['truckNumber'] ?? '').toString():
                doc.data()['gpsDeviceId'] as String,
      };

      // Company-load site lookups are cached by name within this run — see
      // the company-load branch below. Several active loads commonly share
      // the same destination site, so this avoids repeat queries for those.
      final siteDataCache = <String, Map<String, dynamic>?>{};
      Future<Map<String, dynamic>?> fetchSiteDataByName(String name) async {
        if (siteDataCache.containsKey(name)) return siteDataCache[name];
        final query = await FirebaseFirestore.instance
            .collection('sites')
            .where('name', isEqualTo: name)
            .limit(1)
            .get();
        final data = query.docs.isEmpty ? null : query.docs.first.data();
        siteDataCache[name] = data;
        return data;
      }

      for (final loadDoc in activeLoads) {
        final loadData = loadDoc.data();
        final truckNumber = (loadData['truckNumber'] ?? '').toString();
        if (truckNumber.isEmpty) continue;
        final gpsDeviceId = gpsDeviceIdByTruckNumber[truckNumber];
        if (gpsDeviceId == null) continue;
        final truckPosition = positionByGpsDeviceId[gpsDeviceId];
        if (truckPosition == null) continue;

        // Disabled: Private Loads now use manual entry, no GPS detection
        // needed. A Private Load is created already isCompleted: true
        // (see WorkSessionScreen._startNewWork's completeImmediately
        // param), so it should never actually reach this branch for a
        // record created after that change — this only still matters for
        // any pre-existing Private Load record that was left running with
        // autoCompleteViaGps: true from before. _checkPrivateLoadReturn
        // itself (GPS return-path detection) is kept below, not deleted,
        // in case this ever needs reverting.
        if ((loadData['loadType'] ?? 'company').toString() == 'private') {
          // await _checkPrivateLoadReturn(
          //   loadDoc: loadDoc,
          //   loadData: loadData,
          //   currentPosition: truckPosition,
          //   deviceId: deviceIdByUniqueId[gpsDeviceId],
          // );
          continue;
        }

        // Grace period safety net (additive, on top of the root-cause fix
        // in _NewWorkDialog/_showQrUnloadingSitePicker) — a load can't
        // possibly have arrived at its unloading site within moments of
        // starting, so this guards against any future false-positive
        // regardless of cause.
        final companyLoadStartedAt = loadData['loadStartedAt'] as Timestamp?;
        if (companyLoadStartedAt != null &&
            DateTime.now().difference(companyLoadStartedAt.toDate()) <
                const Duration(seconds: 30)) {
          continue;
        }

        // Company Load's unloadingSiteName is pre-selected at QR Scan time
        // (see _showQrLoadTypeDialog's site picker step), so only that one
        // specific site needs checking — no need to loop every registered
        // unloading site.
        final siteName = (loadData['unloadingSiteName'] ?? '').toString();
        if (siteName.isEmpty) continue;
        final siteData = await fetchSiteDataByName(siteName);
        if (siteData == null) continue;

        // Multi-point support (see siteGpsLocations) — any one of a site's
        // entrance/gate points counts as an arrival, not just a single
        // lat/lng.
        final points = siteGpsLocations(siteData);

        // Temporary (V3) — confirms whether the selected unloading site's
        // coordinates suspiciously match the supervisor's own loading
        // site's coordinates (e.g. both captured from the same physical
        // spot during testing). Remove once the "completes regardless of
        // distance" report is confirmed fixed.
        final companyLoadingSiteName = (loadData['siteName'] ?? '').toString();
        final companyLoadingSiteData = companyLoadingSiteName.isEmpty
            ? null
            : await fetchSiteDataByName(companyLoadingSiteName);
        final companyLoadingSitePoints = companyLoadingSiteData == null
            ? const <Map<String, dynamic>>[]
            : siteGpsLocations(companyLoadingSiteData);

        // Distance to every point, same arrival decision as before — only
        // the LOGGING below this (kDebugMode-only, and only when something
        // actually changed) is new.
        var arrived = false;
        double? nearestDistanceMeters;
        for (final point in points) {
          final lat = (point['latitude'] as num?)?.toDouble();
          final lng = (point['longitude'] as num?)?.toDouble();
          if (lat == null || lng == null) continue;
          final distanceMeters = Geolocator.distanceBetween(
            truckPosition.latitude,
            truckPosition.longitude,
            lat,
            lng,
          );
          if (nearestDistanceMeters == null || distanceMeters < nearestDistanceMeters) {
            nearestDistanceMeters = distanceMeters;
          }
          if (distanceMeters <= _arrivalRadiusMeters) {
            arrived = true;
          }
        }

        // Temporary (V2/V3) investigation logging — kDebugMode only (used
        // to run as bare print(), unconditionally, even in release builds),
        // and only re-printed once the nearest-point distance (rounded to
        // the metre, so GPS jitter on a stationary truck doesn't count as
        // "changed") or the arrived/not-arrived result for this truck+site
        // actually differs from the last tick — a truck sitting far from
        // its site no longer floods the console every 15s with an
        // identical block of lines. Remove once the "completes regardless
        // of distance" report is confirmed fixed.
        if (kDebugMode) {
          final signatureKey = '$truckNumber|$siteName';
          // Result only (arrived / not, and which loading site) — not the
          // distance, which changes every tick while a truck is moving.
          final signature = '$arrived|$companyLoadingSiteName';
          if (_lastLoggedCompanyCheck[signatureKey] != signature) {
            _lastLoggedCompanyCheck[signatureKey] = signature;
            debugPrint(
              '[COMPANY_CHECK_V3] Selected Unloading Site Name: $siteName, '
              'Coordinates: '
              '${points.isNotEmpty ? points.first['latitude'] : null}, '
              '${points.isNotEmpty ? points.first['longitude'] : null}',
            );
            debugPrint(
              "[COMPANY_CHECK_V3] Supervisor's Loading Site Name: "
              '$companyLoadingSiteName, Coordinates: '
              '${companyLoadingSitePoints.isNotEmpty ? companyLoadingSitePoints.first['latitude'] : null}, '
              '${companyLoadingSitePoints.isNotEmpty ? companyLoadingSitePoints.first['longitude'] : null}',
            );
            debugPrint(
              '[COMPANY_CHECK_V3] Same Site?: ${siteName == companyLoadingSiteName}',
            );
            debugPrint(
              '[COMPANY_CHECK_V2] Truck: $truckNumber, '
              'Selected Unloading Site: $siteName',
            );
            debugPrint(
              '[COMPANY_CHECK_V2] Site GPS Points: '
              '${points.map((p) => '${p['latitude']},${p['longitude']}').join('|')}',
            );
            debugPrint(
              '[COMPANY_CHECK_V2] Truck Current Position: '
              '${truckPosition.latitude}, ${truckPosition.longitude}',
            );
            debugPrint('[COMPANY_CHECK_V2] Nearest Distance: ${nearestDistanceMeters}m');
            debugPrint(
              '[COMPANY_CHECK_V2] Comparison Result: '
              '${arrived ? 'MATCH - Will Complete' : 'No Match'}',
            );
          }
        }
        if (!arrived) continue;

        // Measures the GPS-actual distance travelled, now that arrival is
        // confirmed — the same "sum consecutive position-history points
        // with Geolocator.distanceBetween" approach _drawRouteForTruck
        // uses for the live tracking KM figure. Written to
        // gpsActualDistanceKm ONLY (see the update() below) — distanceKm
        // itself is now the admin-configured fixed route distance set at
        // creation time (see RouteDistanceManagementScreen/
        // _lookupRouteDistanceKm) and is never touched by this completion
        // write. Report screens show this value as a separate "GPS: X km"
        // reference line (_distanceKmCellContent), read-only. Company
        // Loads only: Private Loads keep their manual entry (loadType ==
        // 'private' never reaches this point — see the continue above).
        //
        // Own try/catch, separate from the outer one wrapping this whole
        // method: this is a purely additive reference measurement, made
        // AFTER arrival is already confirmed — a transient Traccar failure
        // here (this is an extra, second Traccar call this iteration
        // makes, on top of the fetchPositions/fetchDevices already done
        // for every load in the batch) must not silently abort the
        // completion write below, let alone every other load still left in
        // this same batch once the outer catch swallows it.
        double? calculatedDistanceKm;
        final numericDeviceId = deviceIdByUniqueId[gpsDeviceId];
        if (numericDeviceId != null && companyLoadStartedAt != null) {
          try {
            final historyPoints = await TraccarService.fetchPositionHistory(
              username: _traccarUsername,
              password: _traccarPassword,
              deviceId: numericDeviceId,
              from: companyLoadStartedAt.toDate(),
              to: DateTime.now(),
            );
            var totalMeters = 0.0;
            for (var i = 1; i < historyPoints.length; i++) {
              totalMeters += Geolocator.distanceBetween(
                historyPoints[i - 1]['latitude']!,
                historyPoints[i - 1]['longitude']!,
                historyPoints[i]['latitude']!,
                historyPoints[i]['longitude']!,
              );
            }
            calculatedDistanceKm = totalMeters / 1000;
          } catch (e) {
            if (kDebugMode) {
              debugPrint(
                '[COMPANY_CHECK_V2] gpsActualDistanceKm calc failed (completion '
                'proceeds anyway, reference field left unset): $e',
              );
            }
          }
        }

        final completionBatch = FirebaseFirestore.instance.batch();
        final resolvedSiteId = await _reconcileUnloadingFeedEntry(
          batch: completionBatch,
          recordId: loadDoc.id,
          oldSiteId: loadData['unloadingSiteId'] as String?,
          unloadingSiteName: siteName,
          billNumber: (loadData['billNumber'] ?? '').toString(),
          lorryNumber: truckNumber,
          date: (loadData['date'] ?? '').toString(),
          time: FieldValue.serverTimestamp(),
          sourceType: 'work_record',
        );
        completionBatch.update(loadDoc.reference, {
          'unloadingSiteName': siteName,
          if (resolvedSiteId != null) 'unloadingSiteId': resolvedSiteId,
          'isCompleted': true,
          'loadCompletedAt': FieldValue.serverTimestamp(),
          if (calculatedDistanceKm != null)
            'gpsActualDistanceKm': calculatedDistanceKm,
          // Auto-verified — GPS-confirmed arrival stands in for a human
          // reviewing and ticking Verified manually.
          'isVerified': true,
        });
        await completionBatch.commit();
        // Confirms the write itself actually completed, under the same
        // [COMPANY_CHECK_V2] filter already used for this whole
        // investigation — if "MATCH - Will Complete" printed above but this
        // line never does, the write itself threw (e.g. a Firestore
        // permission-denied) and landed in the outer catch below instead,
        // which is NOT tagged COMPANY_CHECK_V2 and would otherwise go
        // unnoticed under that same console filter.
        if (kDebugMode) {
          debugPrint(
            '[COMPANY_CHECK_V2] isCompleted:true write succeeded for record '
            '${loadDoc.id} (truck $truckNumber).',
          );
        }

        await _syncCompletedLoadToSheets(loadDoc.id, {
          ...loadData,
          'unloadingSiteName': siteName,
        });

        _completionController.add(
          LoadCompletionEvent(
            truckNumber: truckNumber,
            billNumber: (loadData['billNumber'] ?? '').toString(),
            siteName: siteName,
          ),
        );
      }
    } catch (e) {
      // Tagged to match [COMPANY_CHECK_V2] on purpose — a permission-denied
      // (or any other) failure anywhere in this method, including the
      // isCompleted:true write itself, lands here and would otherwise be
      // invisible under a console filter scoped to that tag, which is
      // exactly the filter this whole investigation has been using.
      if (kDebugMode && _lastCompanyCheckError != '$e') {
        _lastCompanyCheckError = '$e';
        debugPrint('[COMPANY_CHECK_V2] checkAllActiveLoads failed: $e');
      }
    }
  }

  // Completes a private load once its truck's live position comes back
  // close to its own outbound path — there's no registered delivery site
  // for a private load to arrive at, unlike the company-load proximity
  // check in checkAllActiveLoads above. Requires the truck to have first
  // travelled at least _privateLoadMinTravelMeters total (summed across the
  // whole loadStartedAt-to-now position history) so this can't fire in the
  // first few seconds after the load starts, before the truck has actually
  // left; "close to its own outbound path" means within
  // _privateLoadReturnRadiusMeters of any point from the first 30% of that
  // history (the outbound leg, before the truck would plausibly have
  // turned back).
  //
  // Disabled — see checkAllActiveLoads' now-commented-out call site.
  // Private Loads use manual entry instead of GPS detection now, but this
  // is kept (not deleted) in case that ever needs reverting.
  // ignore: unused_element
  static Future<void> _checkPrivateLoadReturn({
    required QueryDocumentSnapshot<Map<String, dynamic>> loadDoc,
    required Map<String, dynamic> loadData,
    required LatLng currentPosition,
    required int? deviceId,
  }) async {
    // Temporary — see PART of the fresh-verification request that asked
    // for these to be re-added after a prior session removed the earlier
    // AUTO_ARRIVAL_PRIVATE prints; remove again once confirmed working
    // against a load actually created after the autoCompleteViaGps fix.
    final truckNumber = (loadData['truckNumber'] ?? '').toString();
    print(
      '[PRIVATE_CHECK] Truck: $truckNumber, '
      'autoCompleteViaGps: ${loadData['autoCompleteViaGps']}',
    );
    if (deviceId == null) return;
    final loadStartedAt = loadData['loadStartedAt'] as Timestamp?;
    if (loadStartedAt == null) return;

    final points = await TraccarService.fetchPositionHistory(
      username: _traccarUsername,
      password: _traccarPassword,
      deviceId: deviceId,
      from: loadStartedAt.toDate(),
      to: DateTime.now(),
    );
    if (points.length < 2) {
      print(
        '[PRIVATE_CHECK] History points: ${points.length}, Total distance: 0m',
      );
      return;
    }

    var totalDistanceMeters = 0.0;
    for (var i = 1; i < points.length; i++) {
      totalDistanceMeters += Geolocator.distanceBetween(
        points[i - 1]['latitude']!,
        points[i - 1]['longitude']!,
        points[i]['latitude']!,
        points[i]['longitude']!,
      );
    }
    print(
      '[PRIVATE_CHECK] History points: ${points.length}, '
      'Total distance: ${totalDistanceMeters}m',
    );
    if (totalDistanceMeters < _privateLoadMinTravelMeters) return;

    final earlyPointCount = max(1, (points.length * 0.3).ceil());
    var minDistance = double.infinity;
    for (final point in points.take(earlyPointCount)) {
      final distance = Geolocator.distanceBetween(
        currentPosition.latitude,
        currentPosition.longitude,
        point['latitude']!,
        point['longitude']!,
      );
      if (distance < minDistance) minDistance = distance;
    }
    print(
      '[PRIVATE_CHECK] Current pos vs early points - min distance found: '
      '${minDistance}m (threshold: ${_privateLoadReturnRadiusMeters}m)',
    );
    if (minDistance > _privateLoadReturnRadiusMeters) return;

    await loadDoc.reference.update({
      // No registered site to record — see class doc comment on this
      // method. unloadingSiteNote carries the human-readable explanation
      // instead, for anything reading the record afterwards (e.g.
      // LiveTrackingScreen's bill detail card).
      'unloadingSiteName': '',
      'unloadingSiteNote': 'Private Delivery (GPS Auto-Detected)',
      'isCompleted': true,
      'loadCompletedAt': FieldValue.serverTimestamp(),
      // Auto-verified — GPS-confirmed return stands in for a human
      // reviewing and ticking Verified manually, same as the company-load
      // arrival case.
      'isVerified': true,
    });

    await _syncCompletedLoadToSheets(loadDoc.id, {
      ...loadData,
      'unloadingSiteName': 'Private Delivery (GPS Auto-Detected)',
    });

    _completionController.add(
      LoadCompletionEvent(
        truckNumber: truckNumber,
        billNumber: (loadData['billNumber'] ?? '').toString(),
        siteName: 'Private Delivery (GPS Auto-Detected)',
      ),
    );
  }

  // Same 17-column Supervisor_Loads row shape
  // WorkSessionScreen._completeLoadingRecord builds, and the same
  // Plant_Loads/site-specific-sheet follow-up — but sourced entirely from
  // the work_record's own already-denormalized fields (machineName/
  // siteName/supervisorName, written once by _startNewWork) rather than a
  // WorkSessionScreen widget instance, since this runs independently from
  // LiveTrackingScreen, with no supervisor session screen open at all.
  static Future<void> _syncCompletedLoadToSheets(
    String recordId,
    Map<String, dynamic> data,
  ) async {
    final totalDurationSeconds = (data['totalDurationSeconds'] ?? 0) as int;
    final h = totalDurationSeconds ~/ 3600;
    final m = (totalDurationSeconds % 3600) ~/ 60;
    final s = totalDurationSeconds % 60;
    final formattedDuration =
        '${h.toString().padLeft(2, '0')}:${m.toString().padLeft(2, '0')}:'
        '${s.toString().padLeft(2, '0')}';

    final row = [
      GoogleSheetsService.formatDate(DateTime.now()),
      data['machineName'] ?? '',
      data['siteName'] ?? '',
      data['supervisorName'] ?? '',
      data['category'] ?? '',
      data['truckNumber'] ?? '',
      data['billNumber'] ?? '',
      data['unloadingSiteName'] ?? '',
      data['distanceKm']?.toString() ?? '',
      data['startMeter']?.toString() ?? '',
      data['endMeter']?.toString() ?? '',
      formattedDuration,
      GoogleSheetsService.formatTime(data['loadStartedAt']),
      GoogleSheetsService.formatTime(data['loadCompletedAt']),
      data['truckDriverName'] ?? '',
      data['cubeCount'] ?? '',
      data['machineOperatorName'] ?? '',
    ];

    GoogleSheetsService.sendRow(
      sheetName: 'Supervisor_Loads',
      row: row,
      recordId: recordId,
    );

    // The loading site (data['siteName']) — work_records only store the
    // site name, not its id, so this is a live lookup by name, same as the
    // "edit historical record" dialogs elsewhere in this codebase.
    final loadingSiteName = (data['siteName'] ?? '').toString();
    final siteQuery = await FirebaseFirestore.instance
        .collection('sites')
        .where('name', isEqualTo: loadingSiteName)
        .limit(1)
        .get();
    final loadingSiteData = siteQuery.docs.isNotEmpty
        ? siteQuery.docs.first.data()
        : null;

    if (loadingSiteData?['isPlantSite'] == true) {
      GoogleSheetsService.sendRow(
        sheetName: 'Plant_Loads',
        row: row,
        recordId: recordId,
      );
    }

    final liveSiteName =
        (loadingSiteData?['name'] as String?) ?? loadingSiteName;
    final siteSpecificSheetName =
        (loadingSiteData?['sheetName'] as String?) ??
        kSiteSheetMap[normalizeSiteNameForSheetLookup(liveSiteName)];
    if (siteSpecificSheetName != null) {
      GoogleSheetsService.sendRow(
        sheetName: siteSpecificSheetName,
        row: row,
        recordId: recordId,
      );
    }
  }
}

// ---------------- GARAGE MODULE (Truck Maintenance) ----------------
// Service tracking built on the same GPS-odometer approach as GPS Devices'
// KM history (TraccarService.fetchDistanceSummary): a truck's "KM since
// last service" is its live GPS total KM minus a baseline snapshotted at
// the last logged service (trucks/{id}.gpsKmBaselineAtLastService) — not a
// running counter that has to be reset/decremented anywhere, logging a
// service just moves the baseline up to the current total.
// Covers both collections the Garage tracks — trucks and (see
// kBikesCollection) bikes. isBike is what tells them apart for display and
// for resolving which collection a service write goes to; everything else
// about the KM-since-service maths is identical for the two.
class GarageVehicleStatus {
  final String vehicleId;
  final String vehicleNumber;
  final bool isBike;
  final double currentTotalKm;
  final double kmSinceLastService;
  final double serviceIntervalKm;
  // Resolved Traccar numeric device id (see GarageService.fetchStatus) —
  // exposed here so Daily KM History (PART B) can reuse this same
  // resolution instead of calling TraccarService.fetchDevices() again. A
  // GarageVehicleStatus is only ever constructed once this has already
  // resolved successfully, so it's never null by the time UI code sees it.
  final int deviceId;

  const GarageVehicleStatus({
    required this.vehicleId,
    required this.vehicleNumber,
    required this.isBike,
    required this.currentTotalKm,
    required this.kmSinceLastService,
    required this.serviceIntervalKm,
    required this.deviceId,
  });

  double get kmRemaining => serviceIntervalKm - kmSinceLastService;

  String get collectionName => isBike ? kBikesCollection : 'trucks';
}

// Bikes are a deliberately separate collection from trucks, not a "type"
// field on trucks — the truck documents feed the QR system, GPS live
// tracking and every work_record flow, none of which apply to a bike.
const String kBikesCollection = 'bikes';

// Per-vehicle service log (trucks/{id}/serviceHistory,
// bikes/{id}/serviceHistory) — appended to on every logged service, never
// overwritten, so the Garage keeps a full history alongside the single
// "current status" fields on the parent vehicle doc.
const String kServiceHistorySubcollection = 'serviceHistory';

// Per-vehicle, per-service-type tracking (trucks/{id}/serviceTypes,
// bikes/{id}/serviceTypes) — additive to, and independent of, the single
// generic serviceIntervalKm/gpsKmBaselineAtLastService fields on the
// vehicle doc itself. A vehicle can have any number of these (Oil Change
// every 5000km, Brake Service every 10000km, ...), each tracked against
// its own gpsKmBaseline snapshot the same way the vehicle-level one is.
// Existing vehicles simply start with none — nothing to migrate.
const String kServiceTypesSubcollection = 'serviceTypes';

// One service-type's due-soon/overdue status for the Notifications tab and
// the daily push-notification check — same kmRemaining shape as
// GarageVehicleStatus, but scoped to one type rather than the whole
// vehicle, since a vehicle can now have several of these independently.
class GarageServiceTypeAlert {
  final String vehicleNumber;
  final bool isBike;
  final String typeName;
  final double kmRemaining;

  const GarageServiceTypeAlert({
    required this.vehicleNumber,
    required this.isBike,
    required this.typeName,
    required this.kmRemaining,
  });

  bool get isOverdue => kmRemaining < 0;
}

// ---------------- VEHICLE KM CACHE (shared Traccar GPS cache) ----------------
// Centralizes the two Traccar round trips every "current km for this
// vehicle" lookup needs (GarageService.fetchStatus: an /api/devices fetch to
// resolve gpsDeviceId -> Traccar's numeric id, then one /api/reports/summary
// per resolved device) behind one small in-memory cache + a hard timeout
// (25s for devices, 30s for the summary — see TraccarService's matching
// constants and doc comment on why these aren't 5s any more), so
// GarageScreen, TruckProfileScreen, ServiceOverviewScreen and
// VehicleHealthScreen never block on a slow/down Traccar forever, while
// still giving a real, slow-but-healthy server (like this one) long enough
// to actually succeed, and never re-hit it for the same vehicle/device more
// often than once per TTL — whether that's the SAME vehicle re-selected, or
// a different vehicle
// that happens to share the one fleet-wide /api/devices list. In-flight
// requests are de-duplicated (shared, not re-fired) so N callers asking for
// GPS at once (e.g. ServiceOverviewScreen's fleet tab) never cost more than
// one real /api/devices call. This only changes WHEN/HOW the Traccar calls
// behind GarageService's existing km computation happen — the computation
// itself (km since 2020-01-01, baseline math, etc.) is untouched.
const String kVehicleKmCacheCollection = 'vehicle_km_cache';

// Doc id convention for vehicle_km_cache — stable across a vehicle number's
// own formatting quirks (case, a '/' in some truck numbers, stray spaces).
String normalizeVehicleKmCacheId(String vehicleNumber) =>
    vehicleNumber.toUpperCase().replaceAll('/', '_').replaceAll(' ', '_');

// One vehicle_km_cache/{id} doc, as read back. `km`/`updatedAt` are the
// only fields every reader needs; `gpsDeviceId` is kept for the
// delta-since-cache Traccar optimization (see
// GarageService._fetchCurrentTotalKm).
class VehicleKmCacheEntry {
  final String vehicleNumber;
  final double km;
  final DateTime? updatedAt;
  final String? gpsDeviceId;
  const VehicleKmCacheEntry({
    required this.vehicleNumber,
    required this.km,
    this.updatedAt,
    this.gpsDeviceId,
  });

  // UI label threshold ("mark entries older than 24h as stale, but still
  // use them") — distinct from VehicleKmCache's own 30-minute
  // needsBackgroundRefresh threshold below.
  bool get isLabelStale =>
      updatedAt == null || DateTime.now().difference(updatedAt!) >= const Duration(hours: 24);

  // Background-Traccar-refresh threshold for fleet screens.
  bool get needsBackgroundRefresh =>
      updatedAt == null || DateTime.now().difference(updatedAt!) >= const Duration(minutes: 30);
}

// "HH:mm" for an entry updated today, else "yyyy-MM-dd HH:mm" — matches
// every other screen's existing plain (no comma-grouping) date/time
// formatting convention.
String formatVehicleKmCacheAge(DateTime? at) {
  if (at == null) return 'unknown time';
  final now = DateTime.now();
  final hh = at.hour.toString().padLeft(2, '0');
  final mm = at.minute.toString().padLeft(2, '0');
  if (at.year == now.year && at.month == now.month && at.day == now.day) {
    return '$hh:$mm';
  }
  return '${at.year}-${at.month.toString().padLeft(2, '0')}-${at.day.toString().padLeft(2, '0')} $hh:$mm';
}

// Single-doc read of vehicle_km_cache/{normalizeVehicleKmCacheId(vehicleNumber)}.
// Never throws — a read failure (permission-denied, offline, doc missing)
// is treated exactly like "no cached value yet", same convention as every
// other km source in this file.
Future<VehicleKmCacheEntry?> readVehicleKmCache(String vehicleNumber, {FirebaseFirestore? db}) async {
  // Rules denied this collection recently — don't fire one more failing
  // read per vehicle; callers fall through to their next km source.
  if (VehicleKmCache.readDenied) return null;
  try {
    final doc = await (db ?? FirebaseFirestore.instance)
        .collection(kVehicleKmCacheCollection)
        .doc(normalizeVehicleKmCacheId(vehicleNumber))
        .get();
    final data = doc.data();
    if (data == null) return null;
    final km = (data['km'] as num?)?.toDouble();
    if (km == null) return null;
    final ts = data['updatedAt'];
    return VehicleKmCacheEntry(
      vehicleNumber: (data['vehicleNumber'] ?? vehicleNumber).toString(),
      km: km,
      updatedAt: ts is Timestamp ? ts.toDate() : null,
      gpsDeviceId: data['gpsDeviceId'] as String?,
    );
  } catch (e) {
    if (VehicleKmCache.isPermissionDenied(e)) {
      VehicleKmCache.noteDenied('read', e);
    } else {
      debugPrint('readVehicleKmCache($vehicleNumber): $e');
    }
    return null;
  }
}

// Fast, Traccar-free "what should we show right now" peek — reads only
// vehicle_km_cache (one doc get), nothing else. Every truck screen fires
// this alongside its slower, Traccar-first fetchBestKnownKm/
// fetchVehicleServiceOverview call, so it can paint an instant placeholder
// ("Last GPS km: 12,345 (as of 10:42)") the moment it opens, long before
// the real fetch (bounded to ~5s by VehicleKmCache's own timeout) resolves
// and replaces it.
Future<({double km, String source})?> peekLastKnownKm(String vehicleNumber, {FirebaseFirestore? db}) async {
  final cached = await readVehicleKmCache(vehicleNumber, db: db);
  if (cached == null) return null;
  return (
    km: cached.km,
    source: 'Last GPS km (as of ${formatVehicleKmCacheAge(cached.updatedAt)})',
  );
}

// Live total km for one Traccar device from an /api/positions result:
// attributes.totalDistance is the device's cumulative odometer in METRES.
// Null when the device has no position, or the attribute is missing / not
// a positive number — "unknown", never a guessed 0.
double? totalDistanceKmFromPositions(List<Map<String, dynamic>> positions, int deviceId) {
  for (final p in positions) {
    if ((p['deviceId'] as num?)?.toInt() != deviceId) continue;
    final attrs = p['attributes'];
    if (attrs is! Map) return null;
    final meters = attrs['totalDistance'];
    if (meters is! num || meters <= 0) return null;
    return meters / 1000;
  }
  return null;
}

class VehicleKmCache {
  VehicleKmCache._();

  static const Duration ttl = Duration(minutes: 2);
  // Matches TraccarService's own per-endpoint timeout exactly (see its doc
  // comment on the slow-Traccar regression this fixes) — this wrapper
  // exists for devicesFetcherOverride/kmFetcherOverride's test-only path,
  // which bypasses TraccarService (and its internal timeout) entirely; the
  // real production path is bounded by both layers at the same duration,
  // never the old uniform 5s that was aborting slow-but-healthy requests.
  static const Duration devicesTimeout = TraccarService.devicesTimeout;
  static const Duration kmTimeout = TraccarService.summaryTimeout;
  // Separate, longer TTL for the whole-collection fleet read (vehicle_km_cache
  // has one doc per vehicle; re-reading all of them every 2 minutes for
  // every fleet screen that opens is wasteful when the per-vehicle write
  // throttle below already limits how often any one doc actually changes).
  static const Duration bulkTtl = Duration(minutes: 5);

  // Test-only seams (see test/vehicle_km_cache_test.dart) — null in every
  // production path, which falls through to the real TraccarService/
  // GarageService calls below exactly as before this cache existed.
  @visibleForTesting
  static Future<List<Map<String, dynamic>>> Function()? devicesFetcherOverride;
  @visibleForTesting
  static Future<double> Function(int deviceId)? kmFetcherOverride;

  static List<Map<String, dynamic>>? _devices;
  static DateTime? _devicesAt;
  static Future<List<Map<String, dynamic>>>? _devicesInFlight;

  static final Map<int, double> _km = {};
  static final Map<int, DateTime> _kmAt = {};
  static final Map<int, Future<double>> _kmInFlight = {};

  static Map<String, VehicleKmCacheEntry>? _bulk;
  static DateTime? _bulkAt;
  static Future<Map<String, VehicleKmCacheEntry>>? _bulkInFlight;

  // ---- permission-denied resilience ----
  // vehicle_km_cache is a best-effort cache: if Firestore rules deny it,
  // every caller must carry on with its next km source (live GPS,
  // service_records, manual_km_logs, or "unknown"), never fail a screen.
  // A denial is logged ONCE per operation (read / write / bulk) — not once
  // per vehicle — and further attempts of that operation are skipped for
  // deniedBackoff, so a 76-truck fleet doesn't fire 76 doomed reads.
  static const Duration deniedBackoff = Duration(minutes: 5);
  static final Map<String, DateTime> _deniedAt = {};
  static final Set<String> _deniedLogged = {};

  static bool isPermissionDenied(Object e) =>
      e is FirebaseException && e.code == 'permission-denied';

  static void noteDenied(String op, Object e) {
    _deniedAt[op] = DateTime.now();
    if (_deniedLogged.add(op)) {
      debugPrint(
        '[KMCACHE] $kVehicleKmCacheCollection $op denied by Firestore rules '
        '(permission-denied) — skipping this cache for ${deniedBackoff.inMinutes} min and '
        'using the next km source. Logged once. ($e)',
      );
    }
  }

  static bool _isDenied(String op) => _isFresh(_deniedAt[op], deniedBackoff);
  static bool get readDenied => _isDenied('read') || _isDenied('bulk');
  static bool get writeDenied => _isDenied('write');

  static bool _isFresh(DateTime? at, Duration ttlToUse) =>
      at != null && DateTime.now().difference(at) < ttlToUse;

  // ---- /api/positions reuse (primary live km source) ----
  // Positions this fresh (from ANY caller's fetchPositions) are reused
  // as-is; otherwise one shared fetch, de-duplicated across callers.
  static const Duration positionsTtl = Duration(seconds: 60);
  static Future<List<Map<String, dynamic>>>? _positionsInFlight;

  static Future<List<Map<String, dynamic>>> positions() {
    final cached = TraccarService.lastPositions;
    if (cached != null && _isFresh(TraccarService.lastPositionsAt, positionsTtl)) {
      return Future.value(cached);
    }
    final inFlight = _positionsInFlight;
    if (inFlight != null) return inFlight;
    final future = TraccarService.fetchPositions(
      username: GarageService._traccarUsername,
      password: GarageService._traccarPassword,
    ).whenComplete(() => _positionsInFlight = null);
    _positionsInFlight = future;
    return future;
  }

  static bool _positionsFailureLogged = false;

  static Future<double?> _kmFromPositions(int deviceId) async {
    try {
      final km = totalDistanceKmFromPositions(await positions(), deviceId);
      if (km == null && kDebugMode) {
        debugPrint('[TRACCAR] deviceId=$deviceId has no attributes.totalDistance in /api/positions');
      }
      return km;
    } catch (e) {
      if (!_positionsFailureLogged) {
        _positionsFailureLogged = true;
        debugPrint('[TRACCAR] /api/positions unavailable for km ($e) — using summary fallback');
      }
      return null;
    }
  }

  // ---- /api/reports/summary concurrency limit ----
  // Every summary call in the app (current-km fallback, Daily KM History
  // panels) goes through withSummarySlot, so at most
  // maxConcurrentSummaryCalls are ever in flight at once, app-wide. Each
  // call's own 30s timeout only starts once it has a slot.
  static const int maxConcurrentSummaryCalls = 3;
  static int _summaryActive = 0;
  static final List<Completer<void>> _summaryWaiters = [];
  @visibleForTesting
  static int peakConcurrentSummaryCalls = 0;

  static Future<T> withSummarySlot<T>(Future<T> Function() call) async {
    while (_summaryActive >= maxConcurrentSummaryCalls) {
      final waiter = Completer<void>();
      _summaryWaiters.add(waiter);
      await waiter.future;
    }
    _summaryActive++;
    if (_summaryActive > peakConcurrentSummaryCalls) {
      peakConcurrentSummaryCalls = _summaryActive;
    }
    try {
      return await call();
    } finally {
      _summaryActive--;
      if (_summaryWaiters.isNotEmpty) _summaryWaiters.removeAt(0).complete();
    }
  }

  // The fleet-wide device list — one Traccar account's registered devices,
  // id+uniqueId+name each. Needed to resolve any single vehicle's
  // gpsDeviceId (trucks/{id}.gpsDeviceId, a string) to Traccar's own numeric
  // device id, which every other Traccar endpoint keys on.
  static Future<List<Map<String, dynamic>>> devices({bool forceRefresh = false}) {
    if (!forceRefresh && _devices != null && _isFresh(_devicesAt, ttl)) {
      // Explicitly logged (distinct from TraccarService's own per-call
      // logging) so "no /api/devices line in the console" is readable as
      // "served from cache", not "silently never called" — see this
      // feature's regression report.
      if (kDebugMode) {
        debugPrint('[TRACCAR] devices cache hit (${_devices!.length} devices)');
      }
      return Future.value(_devices!);
    }
    if (!forceRefresh && _devicesInFlight != null) {
      if (kDebugMode) debugPrint('[TRACCAR] devices request already in flight, sharing it');
      return _devicesInFlight!;
    }
    final fetcher = devicesFetcherOverride ??
        () => TraccarService.fetchDevices(
              username: GarageService._traccarUsername,
              password: GarageService._traccarPassword,
            );
    final future = fetcher().timeout(devicesTimeout).then((d) {
      _devices = d;
      _devicesAt = DateTime.now();
      _devicesInFlight = null;
      return d;
    }, onError: (Object e, StackTrace st) {
      _devicesInFlight = null;
      throw e;
    });
    _devicesInFlight = future;
    return future;
  }

  // One Traccar device's current total km (see
  // GarageService._fetchCurrentTotalKm) — the heaviest single Traccar call
  // in the app (/api/reports/summary), now cached per resolved numeric
  // deviceId. When vehicleNumber/gpsDeviceId/db are supplied: (1) the
  // underlying Traccar fetch queries /api/reports/summary only from this
  // vehicle's own vehicle_km_cache baseline (or its last service record) to
  // now, instead of from 2020-01-01 — see
  // GarageService._fetchCurrentTotalKm's doc comment — and (2) a
  // successful fetch is written through to vehicle_km_cache (throttled,
  // swap-protected, best-effort — see _writeThrough).
  static Future<double> currentTotalKm(
    int deviceId, {
    bool forceRefresh = false,
    String? vehicleNumber,
    String? gpsDeviceId,
    FirebaseFirestore? db,
    String? uidOverride,
    // false = live km from /api/positions ONLY (fleet-wide background
    // passes for vehicles not on screen) — no totalDistance means the call
    // fails and the caller treats km as unknown / uses its next source.
    bool allowSummaryFallback = true,
  }) {
    if (!forceRefresh && _km.containsKey(deviceId) && _isFresh(_kmAt[deviceId], ttl)) {
      if (kDebugMode) {
        debugPrint('[TRACCAR] summary cache hit (deviceId=$deviceId, km=${_km[deviceId]})');
      }
      return Future.value(_km[deviceId]!);
    }
    final inFlight = _kmInFlight[deviceId];
    if (!forceRefresh && inFlight != null) {
      if (kDebugMode) {
        debugPrint('[TRACCAR] summary request already in flight for deviceId=$deviceId, sharing it');
      }
      return inFlight;
    }

    // Primary: attributes.totalDistance from (already-fetched, shared)
    // /api/positions. Fallback only: the heavy /api/reports/summary,
    // through the app-wide 3-at-a-time slot.
    Future<double> fetchFresh() async {
      final fromPositions = await _kmFromPositions(deviceId);
      if (fromPositions != null) return fromPositions;
      if (!allowSummaryFallback) {
        throw StateError('no live totalDistance for deviceId=$deviceId (summary fallback off)');
      }
      return withSummarySlot(() async {
        final baseline =
            vehicleNumber == null ? null : await _readKmBaseline(vehicleNumber, db: db);
        return GarageService._fetchCurrentTotalKm(
          deviceId,
          sinceDate: baseline?.at,
          sinceKm: baseline?.km,
        ).timeout(kmTimeout);
      });
    }

    final override = kmFetcherOverride;
    final source = override != null ? override(deviceId).timeout(kmTimeout) : fetchFresh();
    final future = source.then((km) async {
      _km[deviceId] = km;
      _kmAt[deviceId] = DateTime.now();
      _kmInFlight.remove(deviceId);
      if (vehicleNumber != null && gpsDeviceId != null) {
        await _writeThrough(
          vehicleNumber: vehicleNumber,
          km: km,
          gpsDeviceId: gpsDeviceId,
          db: db,
          uidOverride: uidOverride,
        );
      }
      return km;
    }, onError: (Object e, StackTrace st) {
      _kmInFlight.remove(deviceId);
      throw e;
    });
    _kmInFlight[deviceId] = future;
    return future;
  }

  // Baseline for the delta-since-cache Traccar optimization: prefer this
  // vehicle's own vehicle_km_cache entry (freshest, written by this very
  // cache); fall back to its latest service_records entry with a
  // currentKm/serviceDate (same single-field vehicleNumber query
  // fetchBestKnownKm's own fallback already uses — no new composite
  // index). Null means "no usable baseline" — callers fall back to
  // Traccar's full 2020-01-01 range, unchanged from before this feature.
  static Future<({double km, DateTime at})?> _readKmBaseline(
    String vehicleNumber, {
    FirebaseFirestore? db,
  }) async {
    final cached = await readVehicleKmCache(vehicleNumber, db: db);
    if (cached != null && cached.updatedAt != null) {
      return (km: cached.km, at: cached.updatedAt!);
    }
    try {
      final snap = await (db ?? FirebaseFirestore.instance)
          .collection('service_records')
          .where('vehicleNumber', isEqualTo: vehicleNumber)
          .get();
      DateTime? bestDate;
      double? bestKm;
      for (final doc in snap.docs) {
        final data = doc.data();
        final ts = data['serviceDate'];
        final dt = ts is Timestamp ? ts.toDate() : null;
        final km = (data['currentKm'] as num?)?.toDouble();
        if (dt != null && km != null && (bestDate == null || dt.isAfter(bestDate))) {
          bestDate = dt;
          bestKm = km;
        }
      }
      if (bestDate != null && bestKm != null) return (km: bestKm, at: bestDate);
    } catch (e) {
      debugPrint('VehicleKmCache: baseline lookup failed for $vehicleNumber: $e');
    }
    return null;
  }

  // Throttled, swap-protected, best-effort write to vehicle_km_cache. Only
  // called after a Traccar fetch actually SUCCEEDED (see currentTotalKm
  // above) — never on failure/timeout, never a 0/unknown value. Writes
  // when: no doc exists yet, OR the new reading differs from the cached one
  // by >= 1 km, OR the cached doc is older than 30 minutes. A new reading
  // LOWER than the cached one by more than 5 km is treated as a possible
  // GPS device swap: the write is skipped (the cached value is kept) and
  // logged, rather than silently moving the vehicle's km backwards.
  static Future<void> _writeThrough({
    required String vehicleNumber,
    required double km,
    required String gpsDeviceId,
    FirebaseFirestore? db,
    String? uidOverride,
  }) async {
    if (km <= 0) return;
    if (writeDenied) return;
    try {
      final firestore = db ?? FirebaseFirestore.instance;
      final ref = firestore
          .collection(kVehicleKmCacheCollection)
          .doc(normalizeVehicleKmCacheId(vehicleNumber));
      final snap = await ref.get();
      final data = snap.data();
      if (data != null) {
        final cachedKm = (data['km'] as num?)?.toDouble();
        if (cachedKm != null) {
          final drop = cachedKm - km;
          if (drop > 5) {
            debugPrint(
              'VehicleKmCache: $vehicleNumber reading dropped by '
              '${drop.toStringAsFixed(0)}km (cached $cachedKm -> new $km) — '
              'possible GPS device swap, keeping cached value',
            );
            return;
          }
          final ts = data['updatedAt'];
          final updatedAt = ts is Timestamp ? ts.toDate() : null;
          final stale = updatedAt == null ||
              DateTime.now().difference(updatedAt) >= const Duration(minutes: 30);
          final delta = (km - cachedKm).abs();
          if (delta < 1 && !stale) return; // throttled — nothing meaningful changed
        }
      }
      final uid = uidOverride ?? FirebaseAuth.instance.currentUser?.uid;
      await ref.set({
        'vehicleNumber': vehicleNumber,
        'km': km,
        'source': 'traccar',
        'gpsDeviceId': gpsDeviceId,
        'updatedAt': FieldValue.serverTimestamp(),
        'updatedBy': uid,
      });
    } catch (e) {
      if (isPermissionDenied(e)) {
        noteDenied('write', e);
      } else {
        debugPrint('VehicleKmCache: write-through failed for $vehicleNumber: $e');
      }
    }
  }

  // The whole vehicle_km_cache collection, one query, cached for bulkTtl —
  // used by fleet screens (ServiceOverviewScreen's Due tab,
  // fetchKmByVehicleForAlerts, VehicleHealthScreen's vehicle selector) to
  // compute every vehicle's due status instantly, with no Traccar call at
  // all, before any background per-vehicle refresh.
  static Future<Map<String, VehicleKmCacheEntry>> allCached({
    FirebaseFirestore? db,
    bool forceRefresh = false,
  }) {
    if (!forceRefresh && _bulk != null && _isFresh(_bulkAt, bulkTtl)) {
      return Future.value(_bulk!);
    }
    if (!forceRefresh && _bulkInFlight != null) return _bulkInFlight!;
    if (_isDenied('bulk')) return Future.value(const <String, VehicleKmCacheEntry>{});
    final future =
        (db ?? FirebaseFirestore.instance).collection(kVehicleKmCacheCollection).get().then((snap) {
      final map = <String, VehicleKmCacheEntry>{};
      for (final doc in snap.docs) {
        final data = doc.data();
        final km = (data['km'] as num?)?.toDouble();
        final vehicleNumber = (data['vehicleNumber'] ?? '').toString();
        if (km == null || vehicleNumber.isEmpty) continue;
        final ts = data['updatedAt'];
        map[vehicleNumber] = VehicleKmCacheEntry(
          vehicleNumber: vehicleNumber,
          km: km,
          updatedAt: ts is Timestamp ? ts.toDate() : null,
          gpsDeviceId: data['gpsDeviceId'] as String?,
        );
      }
      _bulk = map;
      _bulkAt = DateTime.now();
      _bulkInFlight = null;
      return map;
    }, onError: (Object e, StackTrace st) {
      _bulkInFlight = null;
      // Denied by rules: an empty cache (every vehicle "not cached") is the
      // honest answer — callers already handle a missing entry as unknown /
      // needs a live reading. Anything else still propagates as before.
      if (isPermissionDenied(e)) {
        noteDenied('bulk', e);
        return const <String, VehicleKmCacheEntry>{};
      }
      throw e;
    });
    _bulkInFlight = future;
    return future;
  }

  // Test-only — this cache is process-global, not scoped per test, same
  // convention as ServiceAlertsCache.reset().
  @visibleForTesting
  static void reset() {
    _devices = null;
    _devicesAt = null;
    _devicesInFlight = null;
    _km.clear();
    _kmAt.clear();
    _kmInFlight.clear();
    _bulk = null;
    _bulkAt = null;
    _bulkInFlight = null;
    _deniedAt.clear();
    _deniedLogged.clear();
    _positionsInFlight = null;
    _positionsFailureLogged = false;
    _summaryActive = 0;
    _summaryWaiters.clear();
    peakConcurrentSummaryCalls = 0;
    TraccarService.lastPositions = null;
    TraccarService.lastPositionsAt = null;
    devicesFetcherOverride = null;
    kmFetcherOverride = null;
    TraccarService.fetchDistanceSummaryOverride = null;
    TraccarService.fetchDevicesOverride = null;
    TraccarService.fetchPositionsOverride = null;
  }
}

// Runs `action` over `items` with at most `maxConcurrent` in flight at once.
// Used by list screens that need one GPS-derived value per row (e.g.
// ServiceOverviewScreen's fleet-wide "Due" tab) so a long vehicle list never
// fires one Traccar request per row all at once — each row still benefits
// from VehicleKmCache's own de-dup/caching, but this bounds how many COLD
// (cache-miss) requests can be in flight together.
Future<List<R>> mapWithConcurrencyLimit<T, R>(
  List<T> items,
  int maxConcurrent,
  Future<R> Function(T item) action,
) async {
  if (items.isEmpty) return const [];
  final results = List<R?>.filled(items.length, null);
  var nextIndex = 0;
  Future<void> worker() async {
    while (true) {
      final index = nextIndex;
      if (index >= items.length) return;
      nextIndex++;
      results[index] = await action(items[index]);
    }
  }
  await Future.wait(
    List.generate(min(maxConcurrent, items.length), (_) => worker()),
  );
  return results.cast<R>();
}

// Prevents a periodic poll (Timer.periodic) from stacking concurrent
// requests when one tick's work takes longer than the poll interval — e.g.
// LiveTrackingScreen's 15s _refreshPositions cycle against a slow Traccar
// server, which used to fire a brand-new overlapping fetch every 15s
// regardless of whether the previous one had finished. run() silently
// skips (not queues) a tick while a previous call is still in flight, so
// the next successful tick just picks up from wherever Traccar's state is
// by then — never a backlog of stacked requests.
class SingleFlightGuard {
  bool _inFlight = false;
  bool get inFlight => _inFlight;

  Future<void> run(Future<void> Function() action) async {
    if (_inFlight) return;
    _inFlight = true;
    try {
      await action();
    } finally {
      _inFlight = false;
    }
  }
}

class GarageService {
  static const String _traccarUsername = 'it.noda.main01@gmail.com';
  static const String _traccarPassword = 'IT@2026';
  // Default interval for a truck that hasn't logged a service yet.
  static const double defaultServiceIntervalKm = 5000;
  // Notifications tab / GarageNotificationService warning threshold.
  static const double lowKmWarningThreshold = 50;

  // Company trucks (isCompanyTruck == true) with a GPS device assigned —
  // the only trucks eligible for KM-based service tracking. gpsDeviceId is
  // filtered client-side rather than as a second `where`, same
  // composite-index-avoidance reasoning used throughout this codebase (see
  // AutoArrivalDetectionService.checkAllActiveLoads' doc comment).
  static Future<List<QueryDocumentSnapshot<Map<String, dynamic>>>>
  fetchCompanyTrucksWithGps() async {
    final snap = await FirebaseFirestore.instance
        .collection('trucks')
        .where('isCompanyTruck', isEqualTo: true)
        .get();
    return snap.docs.where((doc) {
      final gpsDeviceId = (doc.data()['gpsDeviceId'] as String?)?.trim();
      return gpsDeviceId != null && gpsDeviceId.isNotEmpty;
    }).toList();
  }

  // Bike equivalent of the above — same isCompanyBike + gpsDeviceId
  // eligibility rule, against the separate bikes collection.
  static Future<List<QueryDocumentSnapshot<Map<String, dynamic>>>>
  fetchCompanyBikesWithGps() async {
    final snap = await FirebaseFirestore.instance
        .collection(kBikesCollection)
        .where('isCompanyBike', isEqualTo: true)
        .get();
    return snap.docs.where((doc) {
      final gpsDeviceId = (doc.data()['gpsDeviceId'] as String?)?.trim();
      return gpsDeviceId != null && gpsDeviceId.isNotEmpty;
    }).toList();
  }

  // One truck's live GPS total KM. Historically always summed from
  // 2020-01-01 (same convention as GpsDeviceManagementScreen's
  // _KmHistoryPanel Total Distance figure) — the heaviest possible
  // /api/reports/summary call, re-run in full on every single fetch.
  // sinceDate/sinceKm (see VehicleKmCache._readKmBaseline) let a caller
  // that already knows a recent, trustworthy km reading ask Traccar for
  // only the DELTA since then: the summary call's range shrinks to
  // [sinceDate, now], and that distance is added on top of sinceKm,
  // instead of recomputing the vehicle's entire history every time. The
  // baseline math (meters/1000, kmSinceLastService, etc.) elsewhere is
  // unchanged — this only changes what Traccar is asked to add up.
  static Future<double> _fetchCurrentTotalKm(
    int deviceId, {
    DateTime? sinceDate,
    double? sinceKm,
  }) async {
    final now = DateTime.now();
    final useBaseline = sinceDate != null && sinceKm != null && sinceDate.isBefore(now);
    final meters = await TraccarService.fetchDistanceSummary(
      username: _traccarUsername,
      password: _traccarPassword,
      deviceId: deviceId,
      from: useBaseline ? sinceDate : DateTime(2020, 1, 1),
      to: now,
    );
    final delta = meters / 1000;
    return useBaseline ? sinceKm + delta : delta;
  }

  // Resolves gpsDeviceId (trucks/{id}'s uniqueId string) to Traccar's
  // numeric device id from an already-fetched devices list — passed in
  // rather than re-fetched per truck when checking many at once (see
  // fetchAllStatuses).
  static int? _resolveDeviceId(
    List<Map<String, dynamic>> devices,
    String gpsDeviceId,
  ) {
    final matched = devices.cast<Map<String, dynamic>?>().firstWhere(
      (d) => (d?['uniqueId'] ?? '').toString() == gpsDeviceId,
      orElse: () => null,
    );
    return (matched?['id'] as num?)?.toInt();
  }

  static GarageVehicleStatus _statusFromVehicle(
    QueryDocumentSnapshot<Map<String, dynamic>> vehicleDoc,
    double currentTotalKm, {
    required bool isBike,
    required int deviceId,
  }) {
    final data = vehicleDoc.data();
    final baseline =
        (data['gpsKmBaselineAtLastService'] as num?)?.toDouble() ?? 0;
    final serviceIntervalKm =
        (data['serviceIntervalKm'] as num?)?.toDouble() ??
        defaultServiceIntervalKm;
    return GarageVehicleStatus(
      vehicleId: vehicleDoc.id,
      vehicleNumber: (data[isBike ? 'bikeNumber' : 'truckNumber'] ?? '')
          .toString(),
      isBike: isBike,
      currentTotalKm: currentTotalKm,
      kmSinceLastService: max(0.0, currentTotalKm - baseline),
      serviceIntervalKm: serviceIntervalKm,
      deviceId: deviceId,
    );
  }

  // One vehicle's current status — used by GarageScreen's Trucks and Bikes
  // tabs once a truck/bike is selected. Routed through VehicleKmCache (TTL
  // 2 min, 25s/30s hard timeout per Traccar call) rather than calling
  // TraccarService directly, so reselecting/reopening the same vehicle
  // within the TTL is instant and a hung Traccar never blocks forever.
  // forceRefresh bypasses the cache (RETRY / explicit refresh).
  static Future<GarageVehicleStatus?> fetchStatus(
    QueryDocumentSnapshot<Map<String, dynamic>> vehicleDoc, {
    bool isBike = false,
    bool forceRefresh = false,
    FirebaseFirestore? db,
    String? uidOverride,
    bool allowSummaryFallback = true,
  }) async {
    final gpsDeviceId = (vehicleDoc.data()['gpsDeviceId'] as String?)?.trim();
    if (gpsDeviceId == null || gpsDeviceId.isEmpty) {
      if (kDebugMode) {
        debugPrint('[TRACCAR] fetchStatus(${vehicleDoc.id}): no gpsDeviceId configured — skipping');
      }
      return null;
    }
    final vehicleNumber =
        (vehicleDoc.data()[isBike ? 'bikeNumber' : 'truckNumber'] ?? '').toString();
    final devices = await VehicleKmCache.devices(forceRefresh: forceRefresh);
    final deviceId = _resolveDeviceId(devices, gpsDeviceId);
    if (deviceId == null) {
      // This is the case that used to look identical to "no gpsDeviceId
      // configured" in the UI (both just show "No GPS data available") —
      // logged distinctly so a real resolution failure (typo'd/unregistered
      // Identifier, or the account's device list genuinely not containing
      // it) is diagnosable instead of indistinguishable from "not set up
      // yet". This is also exactly why /api/reports/summary never gets
      // called/logged for this vehicle: fetchStatus returns here, before
      // ever reaching VehicleKmCache.currentTotalKm.
      if (kDebugMode) {
        debugPrint(
          '[TRACCAR] fetchStatus(${vehicleDoc.id}): gpsDeviceId "$gpsDeviceId" not '
          'found among ${devices.length} Traccar devices — no summary call made',
        );
      }
      return null;
    }
    final currentTotalKm = await VehicleKmCache.currentTotalKm(
      deviceId,
      forceRefresh: forceRefresh,
      vehicleNumber: vehicleNumber.isEmpty ? null : vehicleNumber,
      gpsDeviceId: gpsDeviceId,
      db: db,
      uidOverride: uidOverride,
      allowSummaryFallback: allowSummaryFallback,
    );
    return _statusFromVehicle(
      vehicleDoc,
      currentTotalKm,
      isBike: isBike,
      deviceId: deviceId,
    );
  }

  // Every company truck's AND bike's status in one batch, sharing a single
  // fetchDevices() call across all of them — used by the Notifications tab
  // and GarageNotificationService's daily check. Also collects each
  // vehicle's own serviceTypes alerts (due-soon/overdue only) in the same
  // pass, reusing the currentTotalKm this loop already fetched per vehicle
  // rather than a second round of Traccar calls just for that.
  static Future<
    ({List<GarageVehicleStatus> vehicleStatuses, List<GarageServiceTypeAlert> typeAlerts})
  >
  fetchAllStatuses({bool forceRefresh = false, bool allowSummaryFallback = true}) async {
    final trucks = await fetchCompanyTrucksWithGps();
    final bikes = await fetchCompanyBikesWithGps();
    if (trucks.isEmpty && bikes.isEmpty) {
      return (vehicleStatuses: <GarageVehicleStatus>[], typeAlerts: <GarageServiceTypeAlert>[]);
    }
    final devices = await VehicleKmCache.devices(forceRefresh: forceRefresh);
    final statuses = <GarageVehicleStatus>[];
    final typeAlerts = <GarageServiceTypeAlert>[];
    for (final entry in [
      ...trucks.map((doc) => (doc: doc, isBike: false)),
      ...bikes.map((doc) => (doc: doc, isBike: true)),
    ]) {
      final gpsDeviceId = (entry.doc.data()['gpsDeviceId'] as String).trim();
      final deviceId = _resolveDeviceId(devices, gpsDeviceId);
      if (deviceId == null) continue;
      try {
        final vehicleNumber =
            (entry.doc.data()[entry.isBike ? 'bikeNumber' : 'truckNumber'] ?? '').toString();
        final currentTotalKm = await VehicleKmCache.currentTotalKm(
          deviceId,
          forceRefresh: forceRefresh,
          vehicleNumber: vehicleNumber.isEmpty ? null : vehicleNumber,
          gpsDeviceId: gpsDeviceId,
          allowSummaryFallback: allowSummaryFallback,
        );
        final status = _statusFromVehicle(
          entry.doc,
          currentTotalKm,
          isBike: entry.isBike,
          deviceId: deviceId,
        );
        statuses.add(status);

        final typesSnap = await entry.doc.reference
            .collection(kServiceTypesSubcollection)
            .get();
        for (final typeDoc in typesSnap.docs) {
          final typeData = typeDoc.data();
          final intervalKm = (typeData['intervalKm'] as num?)?.toDouble();
          final baseline =
              (typeData['gpsKmBaseline'] as num?)?.toDouble() ?? 0;
          if (intervalKm == null) continue;
          final kmRemaining =
              intervalKm - max(0.0, currentTotalKm - baseline);
          if (kmRemaining > lowKmWarningThreshold) continue;
          typeAlerts.add(
            GarageServiceTypeAlert(
              vehicleNumber: status.vehicleNumber,
              isBike: entry.isBike,
              typeName: (typeData['typeName'] ?? '').toString(),
              kmRemaining: kmRemaining,
            ),
          );
        }
      } catch (e) {
        // Skip this one vehicle (e.g. a transient Traccar error) rather than
        // failing the whole batch.
        debugPrint('GarageService.fetchAllStatuses: skipped vehicle: $e');
      }
    }
    typeAlerts.sort((a, b) => a.kmRemaining.compareTo(b.kmRemaining));
    return (vehicleStatuses: statuses, typeAlerts: typeAlerts);
  }

  // Logs a service for one truck or bike — see the Trucks/Bikes tabs' Log
  // Service dialog. Moves the baseline up to the vehicle's current GPS
  // total KM, which resets "KM Since Last Service" back to 0 from here, and
  // appends an immutable serviceHistory entry alongside it.
  static Future<void> logService({
    required GarageVehicleStatus status,
    required double meterReadingToday,
    required double serviceIntervalKm,
    required String serviceNote,
    required String loggedBy,
  }) async {
    final vehicleRef = FirebaseFirestore.instance
        .collection(status.collectionName)
        .doc(status.vehicleId);
    await vehicleRef.update({
      'gpsKmBaselineAtLastService': status.currentTotalKm,
      'lastServiceMeterKm': meterReadingToday,
      'lastServiceDate': FieldValue.serverTimestamp(),
      'serviceIntervalKm': serviceIntervalKm,
    });
    await vehicleRef.collection(kServiceHistorySubcollection).add({
      'serviceDate': FieldValue.serverTimestamp(),
      'meterReading': meterReadingToday,
      'serviceIntervalKm': serviceIntervalKm,
      'serviceNote': serviceNote,
      'loggedBy': loggedBy,
    });
  }

  // Registers a new independently-tracked service type for one vehicle.
  // gpsKmBaseline starts at the vehicle's current GPS total KM (not 0), so
  // a freshly-added type starts its countdown from today rather than
  // showing overdue-by-however-many-thousand-km the vehicle already has on
  // its odometer.
  static Future<void> addServiceType({
    required String collectionName,
    required String vehicleId,
    required String typeName,
    required double intervalKm,
    required double currentTotalKm,
    String? note,
  }) async {
    await FirebaseFirestore.instance
        .collection(collectionName)
        .doc(vehicleId)
        .collection(kServiceTypesSubcollection)
        .add({
          'typeName': typeName,
          'intervalKm': intervalKm,
          'gpsKmBaseline': currentTotalKm,
          'lastServiceDate': null,
          'note': note,
        });
  }

  // Edits a service type's own metadata (name/interval/note) — leaves
  // gpsKmBaseline/lastServiceDate untouched; those only change via
  // logServiceForType below.
  static Future<void> updateServiceType({
    required String collectionName,
    required String vehicleId,
    required String typeId,
    required String typeName,
    required double intervalKm,
    String? note,
  }) async {
    await FirebaseFirestore.instance
        .collection(collectionName)
        .doc(vehicleId)
        .collection(kServiceTypesSubcollection)
        .doc(typeId)
        .update({'typeName': typeName, 'intervalKm': intervalKm, 'note': note});
  }

  static Future<void> deleteServiceType({
    required String collectionName,
    required String vehicleId,
    required String typeId,
  }) async {
    await FirebaseFirestore.instance
        .collection(collectionName)
        .doc(vehicleId)
        .collection(kServiceTypesSubcollection)
        .doc(typeId)
        .delete();
  }

  // Logs a service for one specific service type — same GPS-total-KM
  // fetch/baseline-reset idea as logService above, but scoped to this one
  // serviceTypes document instead of the whole vehicle (see PART A's
  // "Apply to the specific service type document, not whole vehicle").
  static Future<void> logServiceForType({
    required String collectionName,
    required String vehicleId,
    required String typeId,
    required double currentTotalKm,
    String? note,
  }) async {
    await FirebaseFirestore.instance
        .collection(collectionName)
        .doc(vehicleId)
        .collection(kServiceTypesSubcollection)
        .doc(typeId)
        .update({
          'gpsKmBaseline': currentTotalKm,
          'lastServiceDate': FieldValue.serverTimestamp(),
          'note': note,
        });
  }
}

// Shared by the Trucks and Bikes tabs — the two tabs keep their own list
// layout, but the write itself lives here so a truck service and a bike
// service can't drift apart (both go through GarageService.logService).
void showGarageLogServiceDialog({
  required BuildContext context,
  required GarageVehicleStatus status,
  required String loggedBy,
  required VoidCallback onLogged,
}) {
  final meterController = TextEditingController();
  final intervalController = TextEditingController(
    text: status.serviceIntervalKm.toStringAsFixed(0),
  );
  final noteController = TextEditingController();
  showDialog(
    context: context,
    builder: (dialogContext) => AlertDialog(
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      title: const Text('Log Service'),
      content: SingleChildScrollView(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            TextField(
              controller: meterController,
              autofocus: true,
              keyboardType: const TextInputType.numberWithOptions(
                decimal: true,
              ),
              decoration: const InputDecoration(
                labelText: 'Meter Reading Today',
                hintText: 'Physical odometer reading',
                border: OutlineInputBorder(),
              ),
            ),
            const SizedBox(height: 12),
            TextField(
              controller: intervalController,
              keyboardType: const TextInputType.numberWithOptions(
                decimal: true,
              ),
              decoration: const InputDecoration(
                labelText: 'Service Interval (KM)',
                border: OutlineInputBorder(),
              ),
            ),
            const SizedBox(height: 12),
            TextField(
              controller: noteController,
              maxLines: 3,
              inputFormatters: [UpperCaseTextFormatter()],
              textCapitalization: TextCapitalization.characters,
              decoration: const InputDecoration(
                labelText: 'Service Note (optional)',
                hintText: 'e.g. Oil Change, Brake Pads Replaced',
                border: OutlineInputBorder(),
                alignLabelWithHint: true,
              ),
            ),
          ],
        ),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.pop(dialogContext),
          child: const Text('Cancel'),
        ),
        ElevatedButton(
          onPressed: () async {
            final meterReading = double.tryParse(meterController.text.trim());
            final interval = double.tryParse(intervalController.text.trim());
            if (meterReading == null || interval == null || interval <= 0) {
              ScaffoldMessenger.of(dialogContext).showSnackBar(
                const SnackBar(
                  content: Text('Enter valid numbers for both fields.'),
                ),
              );
              return;
            }
            await GarageService.logService(
              status: status,
              meterReadingToday: meterReading,
              serviceIntervalKm: interval,
              serviceNote: noteController.text.trim(),
              loggedBy: loggedBy,
            );
            if (dialogContext.mounted) Navigator.pop(dialogContext);
            onLogged();
          },
          child: const Text('Save'),
        ),
      ],
    ),
  );
}

// Read-only view of a truck's/bike's serviceHistory subcollection, newest
// first — see GarageService.logService, which appends to it.
void showGarageServiceHistoryDialog({
  required BuildContext context,
  required String collectionName,
  required String vehicleId,
  required String vehicleNumber,
}) {
  showDialog(
    context: context,
    builder: (dialogContext) => AlertDialog(
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      title: Text('Service History — $vehicleNumber'),
      content: SizedBox(
        width: 420,
        child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
          stream: FirebaseFirestore.instance
              .collection(collectionName)
              .doc(vehicleId)
              .collection(kServiceHistorySubcollection)
              .orderBy('serviceDate', descending: true)
              .snapshots(),
          builder: (context, snapshot) {
            if (snapshot.connectionState == ConnectionState.waiting) {
              return const Padding(
                padding: EdgeInsets.all(24),
                child: Center(child: CircularProgressIndicator()),
              );
            }
            if (snapshot.hasError) {
              return Padding(
                padding: const EdgeInsets.all(16),
                child: Text('Failed to load history: ${snapshot.error}'),
              );
            }
            final entries = snapshot.data?.docs ?? [];
            if (entries.isEmpty) {
              return const Padding(
                padding: EdgeInsets.all(24),
                child: Text(
                  'No services logged yet.',
                  style: TextStyle(color: Colors.grey),
                ),
              );
            }
            return ListView.separated(
              shrinkWrap: true,
              itemCount: entries.length,
              separatorBuilder: (_, __) => const Divider(height: 16),
              itemBuilder: (context, index) {
                final data = entries[index].data();
                final serviceDate = (data['serviceDate'] as Timestamp?)
                    ?.toDate();
                final meterReading = (data['meterReading'] as num?)?.toDouble();
                final note = (data['serviceNote'] ?? '').toString();
                final loggedBy = (data['loggedBy'] ?? '').toString();
                return Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      serviceDate == null
                          ? 'Date pending'
                          : GoogleSheetsService.formatDate(serviceDate),
                      style: const TextStyle(fontWeight: FontWeight.bold),
                    ),
                    const SizedBox(height: 4),
                    Text(
                      'Meter Reading: '
                      '${meterReading?.toStringAsFixed(1) ?? '-'} km',
                      style: const TextStyle(fontSize: 13),
                    ),
                    if (note.isNotEmpty) ...[
                      const SizedBox(height: 4),
                      Text(note, style: const TextStyle(fontSize: 13)),
                    ],
                    if (loggedBy.isNotEmpty) ...[
                      const SizedBox(height: 4),
                      Text(
                        'Logged by: $loggedBy',
                        style: const TextStyle(
                          fontSize: 12,
                          color: Colors.grey,
                        ),
                      ),
                    ],
                  ],
                );
              },
            );
          },
        ),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.pop(dialogContext),
          child: const Text('Close'),
        ),
      ],
    ),
  );
}

// Add (existingType: null) / Edit (existingType: the doc being edited)
// dialog for one service type — same two fields either way (Interval KM,
// Note), Type Name only editable on Add since renaming an in-use type mid-
// tracking would be confusing. Add needs the vehicle's currentTotalKm to
// seed a fresh gpsKmBaseline (see GarageService.addServiceType); Edit
// doesn't touch that field at all.
void _showServiceTypeFormDialog({
  required BuildContext context,
  required GarageVehicleStatus status,
  QueryDocumentSnapshot<Map<String, dynamic>>? existingType,
}) {
  final isEdit = existingType != null;
  final existingData = existingType?.data();
  final nameController = TextEditingController(
    text: (existingData?['typeName'] ?? '').toString(),
  );
  final intervalController = TextEditingController(
    text: existingData == null
        ? ''
        : ((existingData['intervalKm'] as num?)?.toStringAsFixed(0) ?? ''),
  );
  final noteController = TextEditingController(
    text: (existingData?['note'] ?? '').toString(),
  );
  showDialog(
    context: context,
    builder: (dialogContext) => AlertDialog(
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      title: Text(isEdit ? 'Edit Service Type' : 'Add Service Type'),
      content: SingleChildScrollView(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            TextField(
              controller: nameController,
              autofocus: !isEdit,
              enabled: !isEdit,
              inputFormatters: [UpperCaseTextFormatter()],
              textCapitalization: TextCapitalization.characters,
              decoration: const InputDecoration(
                labelText: 'Type Name',
                hintText: 'e.g. Oil Change, Brake Service',
                border: OutlineInputBorder(),
              ),
            ),
            const SizedBox(height: 12),
            TextField(
              controller: intervalController,
              autofocus: isEdit,
              keyboardType: const TextInputType.numberWithOptions(
                decimal: true,
              ),
              decoration: const InputDecoration(
                labelText: 'Interval (KM)',
                border: OutlineInputBorder(),
              ),
            ),
            const SizedBox(height: 12),
            TextField(
              controller: noteController,
              maxLines: 3,
              inputFormatters: [UpperCaseTextFormatter()],
              textCapitalization: TextCapitalization.characters,
              decoration: const InputDecoration(
                labelText: 'Note (optional)',
                border: OutlineInputBorder(),
                alignLabelWithHint: true,
              ),
            ),
          ],
        ),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.pop(dialogContext),
          child: const Text('Cancel'),
        ),
        ElevatedButton(
          onPressed: () async {
            final typeName = nameController.text.trim();
            final intervalKm = double.tryParse(
              intervalController.text.trim(),
            );
            if (typeName.isEmpty || intervalKm == null || intervalKm <= 0) {
              ScaffoldMessenger.of(dialogContext).showSnackBar(
                const SnackBar(
                  content: Text('Enter a Type Name and a valid Interval KM.'),
                ),
              );
              return;
            }
            final note = noteController.text.trim();
            if (isEdit) {
              await GarageService.updateServiceType(
                collectionName: status.collectionName,
                vehicleId: status.vehicleId,
                typeId: existingType.id,
                typeName: typeName,
                intervalKm: intervalKm,
                note: note.isEmpty ? null : note,
              );
            } else {
              await GarageService.addServiceType(
                collectionName: status.collectionName,
                vehicleId: status.vehicleId,
                typeName: typeName,
                intervalKm: intervalKm,
                currentTotalKm: status.currentTotalKm,
                note: note.isEmpty ? null : note,
              );
            }
            if (dialogContext.mounted) Navigator.pop(dialogContext);
          },
          child: Text(isEdit ? 'Save' : 'Add'),
        ),
      ],
    ),
  );
}

// Confirms + logs a service for one specific type, reusing the vehicle's
// already-fetched currentTotalKm (same "no extra Traccar call" approach the
// vehicle-level Log Service dialog uses) rather than fetching it again.
void _showLogServiceTypeDialog({
  required BuildContext context,
  required GarageVehicleStatus status,
  required QueryDocumentSnapshot<Map<String, dynamic>> typeDoc,
}) {
  final data = typeDoc.data();
  final typeName = (data['typeName'] ?? '').toString();
  final noteController = TextEditingController(
    text: (data['note'] ?? '').toString(),
  );
  showDialog(
    context: context,
    builder: (dialogContext) => AlertDialog(
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      title: Text('Log Service — $typeName'),
      content: SingleChildScrollView(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              'This marks "$typeName" as serviced today at the current GPS '
              'total of ${status.currentTotalKm.toStringAsFixed(1)} km, '
              'resetting its countdown from here.',
              style: const TextStyle(fontSize: 13, color: Colors.black54),
            ),
            const SizedBox(height: 12),
            TextField(
              controller: noteController,
              maxLines: 3,
              inputFormatters: [UpperCaseTextFormatter()],
              textCapitalization: TextCapitalization.characters,
              decoration: const InputDecoration(
                labelText: 'Note (optional)',
                border: OutlineInputBorder(),
                alignLabelWithHint: true,
              ),
            ),
          ],
        ),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.pop(dialogContext),
          child: const Text('Cancel'),
        ),
        ElevatedButton(
          style: ElevatedButton.styleFrom(backgroundColor: Colors.brown[800]),
          onPressed: () async {
            final note = noteController.text.trim();
            await GarageService.logServiceForType(
              collectionName: status.collectionName,
              vehicleId: status.vehicleId,
              typeId: typeDoc.id,
              currentTotalKm: status.currentTotalKm,
              note: note.isEmpty ? null : note,
            );
            if (dialogContext.mounted) Navigator.pop(dialogContext);
          },
          child: const Text(
            'Log Service',
            style: TextStyle(color: Colors.white),
          ),
        ),
      ],
    ),
  );
}

// Additive "Service Types" section shown below the single-generic-service
// Card in both the Trucks and Bikes tabs' detail panel — see PART A's
// context: the old serviceIntervalKm/gpsKmBaselineAtLastService fields on
// the vehicle doc stay exactly as they are, untouched and unmigrated; this
// is a wholly separate, independent per-type tracking layer underneath it.
class _ServiceTypesSection extends StatelessWidget {
  final GarageVehicleStatus status;
  const _ServiceTypesSection({required this.status});

  @override
  Widget build(BuildContext context) {
    return Card(
      elevation: 2,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                const Text(
                  'Service Types',
                  style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold),
                ),
                TextButton.icon(
                  onPressed: () => _showServiceTypeFormDialog(
                    context: context,
                    status: status,
                  ),
                  icon: const Icon(Icons.add, size: 18),
                  label: const Text('Add Service Type'),
                ),
              ],
            ),
            const SizedBox(height: 4),
            StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
              stream: FirebaseFirestore.instance
                  .collection(status.collectionName)
                  .doc(status.vehicleId)
                  .collection(kServiceTypesSubcollection)
                  .orderBy('typeName')
                  .snapshots(),
              builder: (context, snapshot) {
                if (snapshot.connectionState == ConnectionState.waiting) {
                  return const Padding(
                    padding: EdgeInsets.symmetric(vertical: 16),
                    child: Center(child: CircularProgressIndicator()),
                  );
                }
                final types = snapshot.data?.docs ?? [];
                if (types.isEmpty) {
                  return const Padding(
                    padding: EdgeInsets.symmetric(vertical: 12),
                    child: Text(
                      'No service types yet — add one to track it '
                      'independently (e.g. Oil Change every 5000km).',
                      style: TextStyle(fontSize: 12, color: Colors.grey),
                    ),
                  );
                }
                return Column(
                  children: types.map((typeDoc) {
                    final data = typeDoc.data();
                    final typeName = (data['typeName'] ?? '').toString();
                    final intervalKm =
                        (data['intervalKm'] as num?)?.toDouble() ?? 0;
                    final baseline =
                        (data['gpsKmBaseline'] as num?)?.toDouble() ?? 0;
                    final note = (data['note'] as String?);
                    final kmSinceLastService = max(
                      0.0,
                      status.currentTotalKm - baseline,
                    );
                    final kmRemaining = intervalKm - kmSinceLastService;
                    final isOverdue = kmRemaining < 0;
                    final progress = intervalKm <= 0
                        ? 0.0
                        : (kmSinceLastService / intervalKm).clamp(0.0, 1.0);
                    return Container(
                      margin: const EdgeInsets.only(top: 10),
                      padding: const EdgeInsets.all(12),
                      decoration: BoxDecoration(
                        // Subtle brown-family gradient, matching the
                        // Garage module's own established theming
                        // (Colors.brown[800] appbar/buttons) rather than
                        // the global purple AppTheme.cardGradient, which
                        // would clash here.
                        gradient: LinearGradient(
                          begin: Alignment.topLeft,
                          end: Alignment.bottomRight,
                          colors: [
                            Colors.brown.shade50,
                            Colors.orange.shade50,
                          ],
                        ),
                        borderRadius: BorderRadius.circular(12),
                        border: Border.all(
                          color: isOverdue
                              ? Colors.red
                              : Colors.brown.shade100,
                          width: isOverdue ? 1.5 : 1,
                        ),
                      ),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Row(
                            mainAxisAlignment: MainAxisAlignment.spaceBetween,
                            children: [
                              Expanded(
                                child: Text(
                                  typeName,
                                  style: const TextStyle(
                                    fontWeight: FontWeight.bold,
                                  ),
                                ),
                              ),
                              IconButton(
                                icon: const Icon(Icons.edit, size: 18),
                                tooltip: 'Edit',
                                onPressed: () => _showServiceTypeFormDialog(
                                  context: context,
                                  status: status,
                                  existingType: typeDoc,
                                ),
                              ),
                              IconButton(
                                icon: const Icon(
                                  Icons.delete,
                                  size: 18,
                                  color: Colors.red,
                                ),
                                tooltip: 'Delete',
                                onPressed: () => confirmDelete(
                                  context: context,
                                  title: 'Delete Service Type?',
                                  message:
                                      'Are you sure you want to delete "$typeName"? This cannot be undone.',
                                  onConfirm: () =>
                                      GarageService.deleteServiceType(
                                        collectionName: status.collectionName,
                                        vehicleId: status.vehicleId,
                                        typeId: typeDoc.id,
                                      ),
                                ),
                              ),
                            ],
                          ),
                          if (note != null && note.isNotEmpty)
                            Padding(
                              padding: const EdgeInsets.only(bottom: 6),
                              child: Text(
                                note,
                                style: const TextStyle(fontSize: 12),
                              ),
                            ),
                          Text(
                            '${kmSinceLastService.toStringAsFixed(1)} km / '
                            '${intervalKm.toStringAsFixed(0)} km',
                            style: const TextStyle(
                              fontSize: 12,
                              fontWeight: FontWeight.bold,
                            ),
                          ),
                          const SizedBox(height: 6),
                          ClipRRect(
                            borderRadius: BorderRadius.circular(4),
                            child: LinearProgressIndicator(
                              value: progress.toDouble(),
                              minHeight: 8,
                              backgroundColor: Colors.white,
                              color: isOverdue
                                  ? Colors.red
                                  : AppTheme.accent,
                            ),
                          ),
                          const SizedBox(height: 6),
                          Text(
                            isOverdue
                                ? 'Overdue by ${(-kmRemaining).toStringAsFixed(1)} km'
                                : 'Remaining: ${kmRemaining.toStringAsFixed(1)} km',
                            style: TextStyle(
                              fontSize: 12,
                              fontWeight: FontWeight.bold,
                              color: isOverdue ? Colors.red : Colors.black54,
                            ),
                          ),
                          const SizedBox(height: 8),
                          SizedBox(
                            width: double.infinity,
                            child: OutlinedButton.icon(
                              onPressed: () => _showLogServiceTypeDialog(
                                context: context,
                                status: status,
                                typeDoc: typeDoc,
                              ),
                              icon: const Icon(Icons.build, size: 16),
                              label: const Text('Log Service'),
                              style: OutlinedButton.styleFrom(
                                foregroundColor: Colors.brown[800],
                              ),
                            ),
                          ),
                        ],
                      ),
                    );
                  }).toList(),
                );
              },
            ),
          ],
        ),
      ),
    );
  }
}

// The single-generic-service Card + _ServiceTypesSection — shared between
// _GarageTrucksTabState/_GarageBikesTabState's desktop side-by-side Row
// (wide screens, unchanged) and _GarageVehicleDetailScreen below (narrow
// screens, a separate pushed screen instead of a permanently-visible
// detail pane), so the two layouts can never drift apart.
class _GarageVehicleDetailBody extends StatelessWidget {
  final GarageVehicleStatus status;
  final VoidCallback onLogService;

  const _GarageVehicleDetailBody({
    required this.status,
    required this.onLogService,
  });

  @override
  Widget build(BuildContext context) {
    final progress = status.serviceIntervalKm <= 0
        ? 0.0
        : (status.kmSinceLastService / status.serviceIntervalKm).clamp(
            0.0,
            1.0,
          );
    final kmRemaining = status.kmRemaining;
    final isOverdue = kmRemaining < 0;
    return SingleChildScrollView(
      padding: const EdgeInsets.all(14),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Card(
            elevation: 2,
            shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(16),
            ),
            child: Padding(
              padding: const EdgeInsets.all(16),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    status.vehicleNumber,
                    style: const TextStyle(
                      fontSize: 20,
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                  const SizedBox(height: 16),
                  Text(
                    'KM Since Last Service: '
                    '${status.kmSinceLastService.toStringAsFixed(1)} km / '
                    '${status.serviceIntervalKm.toStringAsFixed(0)} km',
                    style: const TextStyle(fontWeight: FontWeight.bold),
                  ),
                  const SizedBox(height: 8),
                  ClipRRect(
                    borderRadius: BorderRadius.circular(4),
                    child: LinearProgressIndicator(
                      value: progress.toDouble(),
                      minHeight: 10,
                      backgroundColor: Colors.grey[300],
                      color: isOverdue ? Colors.red : AppTheme.primaryMid,
                    ),
                  ),
                  const SizedBox(height: 16),
                  Text(
                    isOverdue
                        ? 'Service Overdue by ${(-kmRemaining).toStringAsFixed(1)} km'
                        : 'KM Remaining to Next Service: ${kmRemaining.toStringAsFixed(1)} km',
                    style: TextStyle(
                      fontWeight: FontWeight.bold,
                      color: isOverdue ? Colors.red : Colors.black87,
                    ),
                  ),
                  const SizedBox(height: 16),
                  SizedBox(
                    width: double.infinity,
                    child: ElevatedButton.icon(
                      onPressed: onLogService,
                      icon: const Icon(Icons.build, color: Colors.white),
                      label: const Text(
                        'Log Service',
                        style: TextStyle(color: Colors.white),
                      ),
                      style: ElevatedButton.styleFrom(
                        backgroundColor: Colors.brown[800],
                        padding: const EdgeInsets.symmetric(vertical: 14),
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ),
          const SizedBox(height: 14),
          _ServiceTypesSection(status: status),
          const SizedBox(height: 14),
          _DailyKmHistorySection(status: status),
        ],
      ),
    );
  }
}

// PART B (isolated addition) — Daily KM History, shared via
// _GarageVehicleDetailBody above so it appears identically for both Trucks
// and Bikes tabs, on both the desktop side panel and the mobile
// full-screen route (_GarageVehicleDetailScreen below). Same concurrent-
// Future.wait/local-midnight-boundary approach as GpsDeviceManagementScreen's
// _KmHistoryPanel (_fetchDailyKm) — a proven pattern already in this
// codebase, reused rather than reinvented — but adds a 30-day total, a
// Today highlight, a retry button, and (that screen doesn't have) an
// in-memory cache so reopening the same vehicle later only refetches
// today's still-accumulating entry, not all 30 days again.
class _DailyKmHistorySection extends StatefulWidget {
  final GarageVehicleStatus status;
  const _DailyKmHistorySection({required this.status});

  @override
  State<_DailyKmHistorySection> createState() =>
      _DailyKmHistorySectionState();
}

class _DailyKmHistorySectionState extends State<_DailyKmHistorySection> {
  // Keyed by collectionName/vehicleId so trucks/bikes (or two different
  // vehicles) never collide. Static so it survives this widget's State
  // being recreated — e.g. navigating away and reopening the same vehicle
  // later — which a plain instance field would not. In-memory only
  // (cleared on a full app restart); Traccar itself is the real source of
  // truth regardless.
  static final Map<String, List<MapEntry<DateTime, double>>> _cache = {};

  late Future<List<MapEntry<DateTime, double>>> _historyFuture;

  String get _cacheKey =>
      '${widget.status.collectionName}/${widget.status.vehicleId}';

  @override
  void initState() {
    super.initState();
    _historyFuture = _loadHistory();
  }

  // GarageService._traccarUsername/_traccarPassword are private but this is
  // the same library (single-file app), so they're reachable here directly
  // — no need to duplicate the credentials or thread them through a
  // constructor param.
  Future<List<MapEntry<DateTime, double>>> _loadHistory() async {
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    final cached = _cache[_cacheKey];
    if (cached != null && cached.length == 30) {
      // Only today's entry is still accumulating — the other 29 days are
      // final, so this skips 29 of the 30 Traccar calls a full reload
      // would otherwise make.
      final todayMeters = await VehicleKmCache.withSummarySlot(
        () => TraccarService.fetchDistanceSummary(
          username: GarageService._traccarUsername,
          password: GarageService._traccarPassword,
          deviceId: widget.status.deviceId,
          from: today,
          to: today.add(const Duration(days: 1)),
        ),
      );
      final refreshed = [
        MapEntry(today, todayMeters),
        ...cached.where((e) => e.key != today),
      ];
      _cache[_cacheKey] = refreshed;
      return refreshed;
    }

    final days = List.generate(30, (i) => today.subtract(Duration(days: i)));
    final results = await Future.wait(
      days.map((day) async {
        // App-wide 3-at-a-time limit (was 30 parallel calls).
        final meters = await VehicleKmCache.withSummarySlot(
          () => TraccarService.fetchDistanceSummary(
            username: GarageService._traccarUsername,
            password: GarageService._traccarPassword,
            deviceId: widget.status.deviceId,
            from: day,
            to: day.add(const Duration(days: 1)),
          ),
        );
        return MapEntry(day, meters);
      }),
    );
    _cache[_cacheKey] = results;
    return results;
  }

  void _retry() {
    setState(() => _historyFuture = _loadHistory());
  }

  String _formatDate(DateTime d) =>
      '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';

  @override
  Widget build(BuildContext context) {
    return Card(
      elevation: 2,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Text(
              'Daily KM History (Last 30 Days)',
              style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold),
            ),
            const SizedBox(height: 12),
            FutureBuilder<List<MapEntry<DateTime, double>>>(
              future: _historyFuture,
              builder: (context, snapshot) {
                if (snapshot.connectionState == ConnectionState.waiting) {
                  return const Padding(
                    padding: EdgeInsets.symmetric(vertical: 20),
                    child: Center(child: CircularProgressIndicator()),
                  );
                }
                if (snapshot.hasError) {
                  return Padding(
                    padding: const EdgeInsets.symmetric(vertical: 12),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          'Failed to load Daily KM History: '
                          '${snapshot.error}',
                          style: const TextStyle(color: Colors.red),
                        ),
                        const SizedBox(height: 8),
                        OutlinedButton.icon(
                          onPressed: _retry,
                          icon: const Icon(Icons.refresh),
                          label: const Text('Retry'),
                        ),
                      ],
                    ),
                  );
                }
                final daily = (snapshot.data ?? []).toList()
                  ..sort((a, b) => b.key.compareTo(a.key));
                final totalKm =
                    daily.fold<double>(0, (sum, e) => sum + e.value) / 1000;
                final now = DateTime.now();
                final today = DateTime(now.year, now.month, now.day);
                return Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Container(
                      width: double.infinity,
                      padding: const EdgeInsets.all(10),
                      decoration: BoxDecoration(
                        color: AppTheme.primaryMid.withOpacity(0.08),
                        borderRadius: BorderRadius.circular(8),
                      ),
                      child: Text(
                        'Total (30 days): ${totalKm.toStringAsFixed(1)} km',
                        style: const TextStyle(
                          fontWeight: FontWeight.bold,
                          color: AppTheme.primaryMid,
                        ),
                      ),
                    ),
                    const SizedBox(height: 8),
                    ListView.separated(
                      shrinkWrap: true,
                      physics: const NeverScrollableScrollPhysics(),
                      itemCount: daily.length,
                      separatorBuilder: (_, __) => const Divider(height: 1),
                      itemBuilder: (context, index) {
                        final entry = daily[index];
                        final km = entry.value / 1000;
                        final isToday = entry.key == today;
                        return ListTile(
                          dense: true,
                          tileColor: isToday
                              ? AppTheme.accent.withOpacity(0.1)
                              : null,
                          title: Text(
                            isToday
                                ? '${_formatDate(entry.key)} (Today)'
                                : _formatDate(entry.key),
                            style: TextStyle(
                              fontWeight: isToday
                                  ? FontWeight.bold
                                  : FontWeight.normal,
                            ),
                          ),
                          trailing: Text(
                            '${km.toStringAsFixed(2)} km',
                            style: TextStyle(
                              fontWeight: FontWeight.bold,
                              color: isToday ? AppTheme.primaryMid : null,
                            ),
                          ),
                        );
                      },
                    ),
                  ],
                );
              },
            ),
          ],
        ),
      ),
    );
  }
}

// Instant, Traccar-free placeholder shown in every GarageScreen "waiting
// on GarageService.fetchStatus" spot below, while that slower (Traccar-
// first, up to 5s) fetch is still in flight — one fast vehicle_km_cache
// doc read, same pattern as _TruckServiceStatusBanner's _peek field.
class _GarageKmPeek extends StatefulWidget {
  final String vehicleNumber;
  const _GarageKmPeek({required this.vehicleNumber});

  @override
  State<_GarageKmPeek> createState() => _GarageKmPeekState();
}

class _GarageKmPeekState extends State<_GarageKmPeek> {
  late final Future<VehicleKmCacheEntry?> _future = readVehicleKmCache(widget.vehicleNumber);

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<VehicleKmCacheEntry?>(
      future: _future,
      builder: (context, snap) {
        final entry = snap.data;
        return Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            if (entry != null) ...[
              Text(
                'Last GPS km: ${entry.km.toStringAsFixed(0)} '
                '(as of ${formatVehicleKmCacheAge(entry.updatedAt)})',
                style: const TextStyle(fontSize: 12, color: Colors.grey),
              ),
              const SizedBox(height: 12),
            ],
            const CircularProgressIndicator(),
          ],
        );
      },
    );
  }
}

// Full-screen detail route for narrow (< WebAppShell.desktopBreakpoint)
// screens — same TruckProfileScreen pattern the rest of the app already
// uses for mobile (a Scaffold pushed via Navigator, with its own back
// button, instead of a permanent side-by-side split that would squeeze a
// detail pane into ~150-200px on a phone). Fetches its own status the same
// way _GarageTrucksTabState/_GarageBikesTabState do (GarageService.fetchStatus
// keyed on the tapped vehicle doc), since this is a separate screen with no
// state to share with the list it was pushed from.
class _GarageVehicleDetailScreen extends StatefulWidget {
  final QueryDocumentSnapshot<Map<String, dynamic>> vehicleDoc;
  final bool isBike;
  final String userName;

  const _GarageVehicleDetailScreen({
    required this.vehicleDoc,
    required this.isBike,
    required this.userName,
  });

  @override
  State<_GarageVehicleDetailScreen> createState() =>
      _GarageVehicleDetailScreenState();
}

class _GarageVehicleDetailScreenState
    extends State<_GarageVehicleDetailScreen> {
  late Future<GarageVehicleStatus?> _statusFuture;

  @override
  void initState() {
    super.initState();
    _statusFuture = GarageService.fetchStatus(
      widget.vehicleDoc,
      isBike: widget.isBike,
    );
  }

  void _refreshStatus() {
    setState(
      () => _statusFuture = GarageService.fetchStatus(
        widget.vehicleDoc,
        isBike: widget.isBike,
        forceRefresh: true,
      ),
    );
  }

  void _showLogServiceDialog(GarageVehicleStatus status) {
    showGarageLogServiceDialog(
      context: context,
      status: status,
      loggedBy: widget.userName,
      onLogged: () {
        if (!mounted) return;
        _refreshStatus();
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(const SnackBar(content: Text('Service logged.')));
      },
    );
  }

  @override
  Widget build(BuildContext context) {
    final vehicleNumber =
        (widget.vehicleDoc.data()[widget.isBike ? 'bikeNumber' : 'truckNumber'] ??
                '')
            .toString();
    return Scaffold(
      appBar: AppBar(
        title: Text(vehicleNumber),
        backgroundColor: Colors.brown[800],
        foregroundColor: Colors.white,
      ),
      body: FutureBuilder<GarageVehicleStatus?>(
        future: _statusFuture,
        builder: (context, snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting) {
            return Center(child: _GarageKmPeek(vehicleNumber: vehicleNumber));
          }
          if (snapshot.hasError) {
            return Center(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  const Text('GPS unavailable'),
                  if (kDebugMode) ...[
                    const SizedBox(height: 4),
                    Text(
                      '${snapshot.error}',
                      style: const TextStyle(fontSize: 11, color: Colors.grey),
                      textAlign: TextAlign.center,
                    ),
                  ],
                  const SizedBox(height: 8),
                  ElevatedButton(onPressed: _refreshStatus, child: const Text('RETRY')),
                ],
              ),
            );
          }
          final status = snapshot.data;
          if (status == null) {
            // null here means either no gpsDeviceId is configured, or the
            // configured gpsDeviceId wasn't found among this Traccar
            // account's devices — see GarageService.fetchStatus's
            // kDebugMode logging for which. RETRY re-resolves against a
            // forced-fresh device list (forceRefresh), in case the device
            // was only just registered/renamed on the Traccar side.
            return Center(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Text(
                    'No GPS data available for this ${widget.isBike ? 'bike' : 'truck'}.',
                  ),
                  if (kDebugMode) ...[
                    const SizedBox(height: 4),
                    const Text(
                      'Check gpsDeviceId matches a Traccar device Identifier '
                      'exactly (see console: [TRACCAR] fetchStatus...)',
                      style: TextStyle(fontSize: 11, color: Colors.grey),
                      textAlign: TextAlign.center,
                    ),
                  ],
                  const SizedBox(height: 8),
                  ElevatedButton(onPressed: _refreshStatus, child: const Text('RETRY')),
                ],
              ),
            );
          }
          return _GarageVehicleDetailBody(
            status: status,
            onLogService: () => _showLogServiceDialog(status),
          );
        },
      ),
    );
  }
}

