// ---------------- TECHNICAL HOME ----------------
// Landing screen for the TECHNICAL account type (mechanics/engineers) —
// see resolveUserLandingKind()/technicalDefaults(). Richer than the old
// Garage/Warehouse-only TechnicianDashboard: Vehicle Maintenance, Truck
// Repairs (defects/service/the RED ALERTS bell+banner live inside that
// hub already), Daily Checks (view), Warehouse — only the tiles this
// specific user's permissions actually grant (resolveTechnicalHomeTiles),
// so an admin who unticks something never leaves a dead-end tile visible.
// Every destination screen re-checks its own permission regardless (no
// new bypass is introduced here).
// 'SERVICE' card shown directly on TechnicalHomeScreen (below the alerts
// banner, no extra tap needed) — company vehicles that need attention,
// sorted RED (overdue/missed) -> KM UNKNOWN -> AMBER (due soon) ->
// AWAITING APPROVAL. Reuses the same ServiceAlertsCache the bell/banner
// already populate (per-uid, 5-minute refresh) via
// _loadAlertsForCurrentUser — pumping this card alongside them costs no
// extra Firestore read beyond the first. Own future in State (not a
// future passed in from the parent) so RETRY/ENTER KM can force a fresh
// fetch independently of the bell/banner.
class TechnicalHomeServiceCard extends StatefulWidget {
  final String name;
  final FirebaseFirestore? firestoreOverride;
  final String? currentUidOverride;
  const TechnicalHomeServiceCard({
    super.key,
    required this.name,
    this.firestoreOverride,
    this.currentUidOverride,
  });

  @override
  State<TechnicalHomeServiceCard> createState() => _TechnicalHomeServiceCardState();
}

class _TechnicalHomeServiceCardState extends State<TechnicalHomeServiceCard> {
  FirebaseFirestore get _db => widget.firestoreOverride ?? FirebaseFirestore.instance;
  String? get _uid => widget.currentUidOverride ?? FirebaseAuth.instance.currentUser?.uid;

  bool _loading = true;
  Object? _loadError;
  bool _qualifies = false;
  bool _canDoService = false;
  List<ServiceAlert> _rows = const [];

  @override
  void initState() {
    super.initState();
    _load();
  }

  // RED, then KM UNKNOWN, then AMBER, then AWAITING APPROVAL last.
  int _rank(ServiceAlert a) {
    if (a.kind == ServiceAlertKind.serviceAwaitingApproval) return 3;
    switch (a.severity) {
      case ServiceAlertSeverity.missed:
      case ServiceAlertSeverity.overdue:
        return 0;
      case ServiceAlertSeverity.kmUnknown:
        return 1;
      case ServiceAlertSeverity.dueSoon:
        return 2;
      default:
        return 4;
    }
  }

  Future<void> _load({bool forceRefresh = false}) async {
    setState(() {
      _loading = true;
      _loadError = null;
    });
    try {
      final result = await _loadAlertsForCurrentUser(
        db: _db,
        uid: _uid,
        forceRefresh: forceRefresh,
      );
      final rows = result.alerts
          .where((a) =>
              a.kind == ServiceAlertKind.serviceDue ||
              a.kind == ServiceAlertKind.serviceAwaitingApproval)
          .toList()
        ..sort((a, b) => _rank(a).compareTo(_rank(b)));
      if (mounted) {
        setState(() {
          _qualifies = result.qualifies;
          _canDoService = result.canDoService;
          _rows = rows;
          _loading = false;
        });
      }
    } catch (e) {
      if (mounted) {
        setState(() {
          _loadError = e;
          _loading = false;
        });
      }
    }
  }

  String _statusLabel(ServiceAlert a) {
    if (a.kind == ServiceAlertKind.serviceAwaitingApproval) return 'AWAITING APPROVAL';
    switch (a.severity) {
      case ServiceAlertSeverity.missed:
      case ServiceAlertSeverity.overdue:
        return a.overByKm != null
            ? 'OVERDUE BY ${a.overByKm!.toStringAsFixed(0)} km'
            : 'OVERDUE';
      case ServiceAlertSeverity.kmUnknown:
        return 'KM UNKNOWN - ENTER KM';
      case ServiceAlertSeverity.dueSoon:
        return (a.dueKm != null && a.currentKm != null)
            ? 'DUE IN ${(a.dueKm! - a.currentKm!).toStringAsFixed(0)} km'
            : 'DUE SOON';
      default:
        return 'GREEN';
    }
  }

  Color _statusColor(ServiceAlert a) {
    if (a.kind == ServiceAlertKind.serviceAwaitingApproval) return AppColors.textMuted;
    switch (a.severity) {
      case ServiceAlertSeverity.missed:
      case ServiceAlertSeverity.overdue:
        return AppColors.danger;
      case ServiceAlertSeverity.kmUnknown:
        return AppColors.textMuted;
      case ServiceAlertSeverity.dueSoon:
        return AppColors.warning;
      default:
        return AppColors.success;
    }
  }

  Widget? _primaryButton(ServiceAlert a) {
    // AWAITING APPROVAL has nothing left for the technician to do — it's
    // with management now.
    if (a.kind == ServiceAlertKind.serviceAwaitingApproval) return null;
    if (!_canDoService) return null;
    if (a.severity == ServiceAlertSeverity.kmUnknown) {
      return ElevatedButton(
        onPressed: () async {
          final saved = await showManualKmEntryDialog(
            context,
            vehicleNumber: a.vehicleNumber,
            firestoreOverride: widget.firestoreOverride,
            currentUidOverride: widget.currentUidOverride,
          );
          if (saved) _load(forceRefresh: true);
        },
        child: const Text('ENTER KM', softWrap: true),
      );
    }
    return ElevatedButton(
      onPressed: () => pushWebAware(
        context,
        ServiceRecordFormScreen(
          vehicleNumber: a.vehicleNumber,
          preselectScheduleId: a.scheduleId,
          firestoreOverride: widget.firestoreOverride,
          currentUidOverride: widget.currentUidOverride,
        ),
      ),
      child: const Text('DO SERVICE', softWrap: true),
    );
  }

  Widget _row(ServiceAlert a) {
    final button = _primaryButton(a);
    return Padding(
      padding: const EdgeInsets.only(bottom: AppSpacing.sm),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            a.vehicleNumber,
            style: AppText.section,
            softWrap: true,
          ),
          Text(
            a.dueKm != null ? '${a.title} — ${a.dueKm!.toStringAsFixed(0)} km' : a.title,
            style: AppText.caption,
            softWrap: true,
          ),
          const SizedBox(height: 4),
          Wrap(
            spacing: AppSpacing.sm,
            runSpacing: AppSpacing.xs,
            crossAxisAlignment: WrapCrossAlignment.center,
            children: [
              Container(
                constraints: const BoxConstraints(maxWidth: 260),
                padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                decoration: BoxDecoration(
                  color: _statusColor(a),
                  borderRadius: BorderRadius.circular(AppRadius.chip),
                ),
                child: Text(
                  _statusLabel(a),
                  style: const TextStyle(
                    color: Colors.white,
                    fontSize: 11,
                    fontWeight: FontWeight.bold,
                  ),
                  softWrap: true,
                ),
              ),
              if (button != null) button,
            ],
          ),
          const Divider(height: AppSpacing.lg),
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    if (_loading) {
      return const Padding(
        padding: EdgeInsets.only(bottom: AppSpacing.md),
        child: AppCard(child: LoadingState()),
      );
    }
    if (_loadError != null) {
      return Padding(
        padding: const EdgeInsets.only(bottom: AppSpacing.md),
        child: AppCard(
          child: ErrorState(
            message: 'Failed to load services: $_loadError',
            onRetry: () => _load(forceRefresh: true),
          ),
        ),
      );
    }
    if (!_qualifies) return const SizedBox.shrink();
    if (_rows.isEmpty) {
      return const Padding(
        padding: EdgeInsets.only(bottom: AppSpacing.md),
        child: AppCard(
          child: EmptyState(icon: Icons.build_circle_outlined, title: 'NO SERVICES DUE'),
        ),
      );
    }
    final shown = _rows.take(5).toList();
    return Padding(
      padding: const EdgeInsets.only(bottom: AppSpacing.md),
      child: AppCard(
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text('SERVICE', style: AppText.section),
            const SizedBox(height: AppSpacing.sm),
            for (final a in shown) _row(a),
            if (_rows.length > 5)
              Align(
                alignment: Alignment.centerRight,
                child: TextButton(
                  onPressed: () => Navigator.push(
                    context,
                    MaterialPageRoute(
                      builder: (_) => VehicleMaintenanceHubScreen(name: widget.name),
                    ),
                  ),
                  child: const Text('VIEW ALL'),
                ),
              ),
          ],
        ),
      ),
    );
  }
}

class TechnicalHomeScreen extends StatefulWidget {
  final String name;
  final FirebaseFirestore? firestoreOverride;
  final String? currentUidOverride;
  const TechnicalHomeScreen({
    super.key,
    required this.name,
    this.firestoreOverride,
    this.currentUidOverride,
  });

  @override
  State<TechnicalHomeScreen> createState() => _TechnicalHomeScreenState();
}

class _TechnicalHomeScreenState extends State<TechnicalHomeScreen> {
  FirebaseFirestore get _db => widget.firestoreOverride ?? FirebaseFirestore.instance;
  String? get _uid => widget.currentUidOverride ?? FirebaseAuth.instance.currentUser?.uid;
  late final Future<List<String>> _tilesFuture = _loadTiles();

  Future<List<String>> _loadTiles() async {
    final uid = _uid;
    Map<String, dynamic>? userData;
    if (uid != null) {
      final doc = await _db.collection('users').doc(uid).get();
      userData = doc.data();
    }
    return resolveTechnicalHomeTiles(
      canAccessGarage: userData?['canAccessGarage'] == true,
      hasRepairWork: hasRepairPerm(userData, kPermRepairWork),
      hasServiceView: hasRepairPerm(userData, kPermServiceView),
      canAccessWarehouse: userData?['canAccessWarehouse'] == true,
    );
  }

  Future<void> _logout() async {
    await FirebaseAuth.instance.signOut();
    if (mounted) {
      Navigator.pushReplacement(
        context,
        MaterialPageRoute(builder: (_) => const LoginScreen()),
      );
    }
  }

  Widget _tile({
    required IconData icon,
    required String title,
    required String subtitle,
    required VoidCallback onTap,
    Widget? badge,
  }) {
    return Padding(
      padding: const EdgeInsets.only(bottom: AppSpacing.md),
      child: AppCard(
        onTap: onTap,
        child: Row(
          children: [
            Container(
              width: 44,
              height: 44,
              decoration: BoxDecoration(
                color: AppColors.primarySoft,
                borderRadius: BorderRadius.circular(12),
              ),
              child: Icon(icon, color: AppColors.primary, size: 22),
            ),
            const SizedBox(width: AppSpacing.md),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(title, style: AppText.section),
                  const SizedBox(height: 2),
                  Text(subtitle, style: AppText.caption),
                ],
              ),
            ),
            if (badge != null) badge,
            const Icon(Icons.chevron_right, color: AppColors.textMuted),
          ],
        ),
      ),
    );
  }

  Widget? _buildTile(String tileId) {
    switch (tileId) {
      case TechnicalHomeTile.vehicleMaintenance:
        return _tile(
          icon: Icons.garage,
          title: 'Vehicle Maintenance',
          subtitle: 'Garage service tracking and vehicle inspections',
          onTap: () => Navigator.push(
            context,
            MaterialPageRoute(builder: (_) => VehicleMaintenanceHubScreen(name: widget.name)),
          ),
        );
      case TechnicalHomeTile.repairsToDo:
        return _tile(
          icon: Icons.car_repair,
          title: 'Repairs To Do',
          subtitle: 'Start, note and submit repairs for approval',
          badge: _RepairStatusCountBadge(
            statuses: const [RepairItemStatus.listed, RepairItemStatus.returned],
            firestoreOverride: widget.firestoreOverride,
          ),
          onTap: () => Navigator.push(
            context,
            MaterialPageRoute(
              builder: (_) => RepairsToDoScreen(
                firestoreOverride: widget.firestoreOverride,
                currentUidOverride: widget.currentUidOverride,
              ),
            ),
          ),
        );
      case TechnicalHomeTile.dailyChecks:
        return _tile(
          icon: Icons.fact_check,
          title: 'Daily Checks',
          subtitle: "Today's driver water/oil level checks",
          onTap: () => Navigator.push(
            context,
            MaterialPageRoute(builder: (_) => const DailyChecksScreen()),
          ),
        );
      case TechnicalHomeTile.warehouse:
        return _tile(
          icon: Icons.warehouse,
          title: 'Warehouse',
          subtitle: 'Oil, tools and spare parts stock',
          onTap: () => Navigator.push(
            context,
            MaterialPageRoute(builder: (_) => WarehouseScreen(name: widget.name)),
          ),
        );
      default:
        return null;
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: AppColors.background,
      appBar: AppBar(
        title: const Text('Technical Home'),
        backgroundColor: AppColors.navy,
        foregroundColor: Colors.white,
        actions: [
          ServiceAlertsBell(
            firestoreOverride: widget.firestoreOverride,
            currentUidOverride: widget.currentUidOverride,
          ),
          IconButton(icon: const Icon(Icons.logout), onPressed: _logout),
        ],
      ),
      body: FutureBuilder<List<String>>(
        future: _tilesFuture,
        builder: (context, snap) {
          if (snap.connectionState != ConnectionState.done) {
            return const LoadingState();
          }
          final tiles = snap.data ?? const [];
          if (tiles.isEmpty) {
            return const EmptyState(
              icon: Icons.lock_outline,
              title: 'NO ACCESS GRANTED YET',
              hint: 'ASK THE ADMIN',
            );
          }
          return SingleChildScrollView(
            child: Align(
              alignment: Alignment.topCenter,
              child: ConstrainedBox(
                constraints: const BoxConstraints(maxWidth: 480),
                child: Padding(
                  padding: const EdgeInsets.all(AppSpacing.lg),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Text('Welcome, ${widget.name}', style: AppText.title),
                      const SizedBox(height: AppSpacing.md),
                      ServiceAlertsBanner(
                        firestoreOverride: widget.firestoreOverride,
                        currentUidOverride: widget.currentUidOverride,
                      ),
                      TechnicalHomeServiceCard(
                        name: widget.name,
                        firestoreOverride: widget.firestoreOverride,
                        currentUidOverride: widget.currentUidOverride,
                      ),
                      for (final tile in tiles.map(_buildTile).whereType<Widget>()) tile,
                    ],
                  ),
                ),
              ),
            ),
          );
        },
      ),
    );
  }
}

// ---------------- UNLOADING SITE VIEWER ----------------
// Read-only landing screen for the 'unloading_site' role (see AuthGate's and
// LoginScreen._login()'s matching switch cases) — a stakeholder at one or
// more unloading sites who only needs to see which bills/lorries are headed
// their way, nothing else (no amounts, rates, site names of OTHER sites,
// supervisor/machine info, or edit/export capability).
//
// Matching note: work_records never actually saves an unloadingSiteId today
// — every unloading-site field in the app (Edit dialog, Add Report dialog,
// _startNewWork) only ever writes unloadingSiteName as free text (see
// _showUnloadingSiteFieldPicker, which resolves a real site id but the
// caller discards it, keeping only the name). So matching here is done by
// name against this user's assigned unloadingSiteIds (resolved to names via
// the sites collection) — the unloadingSiteId check below is kept as a
// forward-compatible first choice in case a future change starts saving it,
// but in the current data it is always null and the name fallback is what
// actually runs for every existing record.
class UnloadingSiteViewerScreen extends StatefulWidget {
  final String name;
  final List<String> unloadingSiteIds;
  const UnloadingSiteViewerScreen({
    super.key,
    required this.name,
    required this.unloadingSiteIds,
  });

  @override
  State<UnloadingSiteViewerScreen> createState() =>
      _UnloadingSiteViewerScreenState();
}

class _UnloadingSiteViewerScreenState
    extends State<UnloadingSiteViewerScreen> {
  DateTimeRange? _dateRange;
  final _billNumberController = TextEditingController();
  String _billNumberFilter = '';
  final _lorryNumberController = TextEditingController();
  String _lorryNumberFilter = '';
  int _pageSize = 25;
  int _page = 0;
  String _filterSig = '';

  // One subscription per assigned site (unloading_feed/{siteId}/loads),
  // re-created only when the date-range key actually changes — see
  // _subscribeAll. Each site's own latest docs are kept separately and
  // merged (then re-sorted) on every build, rather than trying to compose
  // several Streams into one — this screen never reads work_records,
  // manual_site_reports or the sites collection directly at all; the feed
  // path is already scoped to exactly this user's unloadingSiteIds, and a
  // feed doc's own unloadingSiteName (denormalized at write time) is what
  // the site-name header below is built from.
  final Map<String, StreamSubscription<QuerySnapshot>> _subscriptions = {};
  final Map<String, List<QueryDocumentSnapshot>> _docsBySite = {};
  final Map<String, String> _siteNameById = {};
  String? _subscribedRangeKey;

  String _ymd(DateTime d) =>
      '${d.year.toString().padLeft(4, '0')}-'
      '${d.month.toString().padLeft(2, '0')}-'
      '${d.day.toString().padLeft(2, '0')}';

  String get _defaultWindowStart =>
      _ymd(DateTime.now().subtract(const Duration(days: 30)));

  @override
  void initState() {
    super.initState();
    _subscribeAll();
  }

  void _subscribeAll() {
    final start = _dateRange != null
        ? _ymd(_dateRange!.start)
        : _defaultWindowStart;
    final end = _dateRange != null ? _ymd(_dateRange!.end) : null;
    final key = '$start|$end';
    if (key == _subscribedRangeKey) return;
    _subscribedRangeKey = key;

    for (final sub in _subscriptions.values) {
      sub.cancel();
    }
    _subscriptions.clear();
    _docsBySite.clear();

    for (final siteId in widget.unloadingSiteIds) {
      Query q = FirebaseFirestore.instance
          .collection('unloading_feed')
          .doc(siteId)
          .collection('loads')
          .where('date', isGreaterThanOrEqualTo: start);
      if (end != null) {
        q = q.where('date', isLessThanOrEqualTo: end);
      }
      q = q.orderBy('date', descending: true);
      _subscriptions[siteId] = q.snapshots().listen((snapshot) {
        _docsBySite[siteId] = snapshot.docs;
        for (final doc in snapshot.docs) {
          final data = doc.data() as Map<String, dynamic>;
          final name = (data['unloadingSiteName'] ?? '').toString();
          if (name.isNotEmpty) _siteNameById[siteId] = name;
        }
        if (mounted) setState(() {});
      });
    }
  }

  @override
  void dispose() {
    for (final sub in _subscriptions.values) {
      sub.cancel();
    }
    _billNumberController.dispose();
    _lorryNumberController.dispose();
    super.dispose();
  }

  Future<void> _logout() async {
    await FirebaseAuth.instance.signOut();
    if (mounted) {
      Navigator.pushReplacement(
        context,
        MaterialPageRoute(builder: (_) => const LoginScreen()),
      );
    }
  }

  Future<void> _pickDateRange() async {
    final picked = await showDateRangePicker(
      context: context,
      firstDate: DateTime(2020),
      lastDate: DateTime.now().add(const Duration(days: 1)),
      initialDateRange: _dateRange,
    );
    if (picked != null) {
      setState(() => _dateRange = picked);
      _subscribeAll();
    }
  }

  String _formatTime(dynamic ts) {
    if (ts is! Timestamp) return '-';
    final dt = ts.toDate();
    final hour = dt.hour % 12 == 0 ? 12 : dt.hour % 12;
    final period = dt.hour >= 12 ? 'PM' : 'AM';
    final minute = dt.minute.toString().padLeft(2, '0');
    return '$hour:$minute $period';
  }

  @override
  Widget build(BuildContext context) {
    final myLabels = widget.unloadingSiteIds
        .map((id) => _siteNameById[id] ?? id)
        .toList();
    final allDocs = _docsBySite.values.expand((docs) => docs).toList()
      ..sort((a, b) {
        final ad = a.data() as Map<String, dynamic>;
        final bd = b.data() as Map<String, dynamic>;
        final dateCompare = (bd['date'] ?? '').toString().compareTo(
          (ad['date'] ?? '').toString(),
        );
        if (dateCompare != 0) return dateCompare;
        final at = ad['time'];
        final bt = bd['time'];
        if (at is Timestamp && bt is Timestamp) return bt.compareTo(at);
        return 0;
      });

    final billQuery = _billNumberFilter.trim().toLowerCase();
    final lorryQuery = _lorryNumberFilter.trim().toLowerCase();
    final filtered = allDocs.where((doc) {
      final data = doc.data() as Map<String, dynamic>;
      if (billQuery.isNotEmpty) {
        final bill = (data['billNumber'] ?? '').toString().toLowerCase();
        if (!bill.contains(billQuery)) return false;
      }
      if (lorryQuery.isNotEmpty) {
        final lorry = (data['lorryNumber'] ?? '').toString().toLowerCase();
        if (!lorry.contains(lorryQuery)) return false;
      }
      return true;
    }).toList();

    final sig = '$_billNumberFilter|$_lorryNumberFilter|$_pageSize';
    if (sig != _filterSig) {
      _filterSig = sig;
      _page = 0;
    }
    final totalPages = filtered.isEmpty
        ? 1
        : (filtered.length + _pageSize - 1) ~/ _pageSize;
    if (_page >= totalPages) _page = totalPages - 1;
    if (_page < 0) _page = 0;
    final pageStart = _page * _pageSize;
    final pageEnd = (pageStart + _pageSize) > filtered.length
        ? filtered.length
        : pageStart + _pageSize;
    final pageDocs = filtered.isEmpty
        ? const <QueryDocumentSnapshot>[]
        : filtered.sublist(pageStart, pageEnd);

    return Scaffold(
      appBar: AppBar(
        title: const Text('Unloading Site — Loads'),
        backgroundColor: Colors.teal[800],
        foregroundColor: Colors.white,
        actions: [
          IconButton(icon: const Icon(Icons.logout), onPressed: _logout),
        ],
      ),
      body: Column(
        children: [
          Padding(
            padding: const EdgeInsets.fromLTRB(12, 12, 12, 0),
            child: Align(
              alignment: Alignment.centerLeft,
              child: Text(
                'Site: ${myLabels.isEmpty ? '-' : myLabels.join(', ')}',
                style: const TextStyle(fontWeight: FontWeight.bold),
              ),
            ),
          ),
          Padding(
            padding: const EdgeInsets.all(12),
            child: Wrap(
              spacing: 12,
              runSpacing: 12,
              crossAxisAlignment: WrapCrossAlignment.center,
              children: [
                SizedBox(
                  width: 230,
                  height: 48,
                  child: OutlinedButton.icon(
                    onPressed: _pickDateRange,
                    icon: const Icon(Icons.date_range),
                    label: Text(
                      _dateRange == null
                          ? 'Last 30 Days'
                          : '${_ymd(_dateRange!.start)} - '
                                '${_ymd(_dateRange!.end)}',
                      overflow: TextOverflow.ellipsis,
                    ),
                  ),
                ),
                SizedBox(
                  width: 180,
                  height: 48,
                  child: TextField(
                    controller: _billNumberController,
                    inputFormatters: [UpperCaseTextFormatter()],
                    textCapitalization: TextCapitalization.characters,
                    decoration: InputDecoration(
                      hintText: 'Bill Number',
                      isDense: true,
                      prefixIcon: const Icon(Icons.search),
                      border: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(10),
                      ),
                    ),
                    onChanged: (val) =>
                        setState(() => _billNumberFilter = val),
                  ),
                ),
                SizedBox(
                  width: 180,
                  height: 48,
                  child: TextField(
                    controller: _lorryNumberController,
                    inputFormatters: [UpperCaseTextFormatter()],
                    textCapitalization: TextCapitalization.characters,
                    decoration: InputDecoration(
                      hintText: 'Lorry Number',
                      isDense: true,
                      prefixIcon: const Icon(Icons.search),
                      border: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(10),
                      ),
                    ),
                    onChanged: (val) =>
                        setState(() => _lorryNumberFilter = val),
                  ),
                ),
              ],
            ),
          ),
          Expanded(
            child: widget.unloadingSiteIds.isEmpty
                ? const Center(
                    child: Text(
                      'No unloading sites assigned to this account.',
                    ),
                  )
                : filtered.isEmpty
                ? Center(
                    child: Text(
                      allDocs.isEmpty
                          ? 'No loads recorded for this period.'
                          : 'No matching loads.',
                    ),
                  )
                : Column(
                    children: [
                      Expanded(
                        child: SingleChildScrollView(
                          child: SingleChildScrollView(
                            scrollDirection: Axis.horizontal,
                            child: DataTable(
                              columns: const [
                                DataColumn(
                                  label: Text(
                                    'Bill Number',
                                    style: TextStyle(
                                      fontWeight: FontWeight.bold,
                                    ),
                                  ),
                                ),
                                DataColumn(
                                  label: Text(
                                    'Date',
                                    style: TextStyle(
                                      fontWeight: FontWeight.bold,
                                    ),
                                  ),
                                ),
                                DataColumn(
                                  label: Text(
                                    'Time',
                                    style: TextStyle(
                                      fontWeight: FontWeight.bold,
                                    ),
                                  ),
                                ),
                                DataColumn(
                                  label: Text(
                                    'Lorry Number',
                                    style: TextStyle(
                                      fontWeight: FontWeight.bold,
                                    ),
                                  ),
                                ),
                              ],
                              rows: pageDocs.map((doc) {
                                final data = doc.data() as Map<String, dynamic>;
                                return DataRow(
                                  cells: [
                                    DataCell(
                                      Text(
                                        (data['billNumber'] ?? '-').toString(),
                                      ),
                                    ),
                                    DataCell(
                                      Text((data['date'] ?? '-').toString()),
                                    ),
                                    DataCell(Text(_formatTime(data['time']))),
                                    DataCell(
                                      Text(
                                        (data['lorryNumber'] ?? '-').toString(),
                                      ),
                                    ),
                                  ],
                                );
                              }).toList(),
                            ),
                          ),
                        ),
                      ),
                      Padding(
                        padding: const EdgeInsets.symmetric(
                          horizontal: 12,
                          vertical: 8,
                        ),
                        child: Row(
                          mainAxisAlignment: MainAxisAlignment.end,
                          children: [
                            const Text('Rows per page: '),
                            DropdownButton<int>(
                              value: _pageSize,
                              items: [25, 50, 100]
                                  .map(
                                    (n) => DropdownMenuItem<int>(
                                      value: n,
                                      child: Text('$n'),
                                    ),
                                  )
                                  .toList(),
                              onChanged: (v) {
                                if (v != null) {
                                  setState(() => _pageSize = v);
                                }
                              },
                            ),
                            const SizedBox(width: 16),
                            Text(
                              '${pageStart + 1}-$pageEnd of ${filtered.length}',
                            ),
                            IconButton(
                              icon: const Icon(Icons.chevron_left),
                              onPressed: _page > 0
                                  ? () => setState(() => _page--)
                                  : null,
                            ),
                            IconButton(
                              icon: const Icon(Icons.chevron_right),
                              onPressed: _page < totalPages - 1
                                  ? () => setState(() => _page++)
                                  : null,
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),
          ),
        ],
      ),
    );
  }
}


