                      );
                    }
                    if (snapshot.hasError) {
                      return Center(
                        child: Column(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            const Text('GPS unavailable'),
                            if (kDebugMode) ...[
                              const SizedBox(height: 4),
                              Text(
                                '${snapshot.error}',
                                style: const TextStyle(fontSize: 11, color: Colors.grey),
                                textAlign: TextAlign.center,
                              ),
                            ],
                            const SizedBox(height: 8),
                            ElevatedButton(
                              onPressed: _refreshStatus,
                              child: const Text('RETRY'),
                            ),
                          ],
                        ),
                      );
                    }
                    final status = snapshot.data;
                    if (status == null) {
                      return Center(
                        child: Column(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            const Text('No GPS data available for this bike.'),
                            if (kDebugMode) ...[
                              const SizedBox(height: 4),
                              const Text(
                                'Check gpsDeviceId matches a Traccar device '
                                'Identifier exactly (see console: [TRACCAR] '
                                'fetchStatus...)',
                                style: TextStyle(fontSize: 11, color: Colors.grey),
                                textAlign: TextAlign.center,
                              ),
                            ],
                            const SizedBox(height: 8),
                            ElevatedButton(
                              onPressed: _refreshStatus,
                              child: const Text('RETRY'),
                            ),
                          ],
                        ),
                      );
                    }
                    return _GarageVehicleDetailBody(
                      status: status,
                      onLogService: () => _showLogServiceDialog(status),
                    );
                  },
                ),
        ),
      ],
    );
  }
}

// One row of the Garage Notifications table — either the vehicle's single
// generic interval (serviceType "General service") or one of its
// per-type serviceTypes entries. Built purely from fetchAllStatuses()'s
// existing result; currentKm comes from the matching GarageVehicleStatus
// when present, else null ("unknown").
class GarageServiceDueRow {
  final String vehicleNumber;
  final bool isBike;
  final String serviceType;
  final double? currentKm;
  final double kmRemaining;
  const GarageServiceDueRow({
    required this.vehicleNumber,
    required this.isBike,
    required this.serviceType,
    required this.currentKm,
    required this.kmRemaining,
  });
  bool get isOverdue => kmRemaining < 0;
}

List<GarageServiceDueRow> buildGarageServiceDueRows({
  required List<GarageVehicleStatus> vehicleStatuses,
  required List<GarageServiceTypeAlert> typeAlerts,
}) {
  final kmByVehicle = {
    for (final v in vehicleStatuses) '${v.isBike}|${v.vehicleNumber}': v.currentTotalKm,
  };
  return [
    for (final v in vehicleStatuses)
      if (v.kmRemaining <= GarageService.lowKmWarningThreshold)
        GarageServiceDueRow(
          vehicleNumber: v.vehicleNumber,
          isBike: v.isBike,
          serviceType: 'General service',
          currentKm: v.currentTotalKm,
          kmRemaining: v.kmRemaining,
        ),
    for (final a in typeAlerts)
      GarageServiceDueRow(
        vehicleNumber: a.vehicleNumber,
        isBike: a.isBike,
        serviceType: a.typeName,
        currentKm: kmByVehicle['${a.isBike}|${a.vehicleNumber}'],
        kmRemaining: a.kmRemaining,
      ),
  ];
}

// Overdue first, then due soon; then vehicle number; then service type.
int compareGarageServiceDueRows(GarageServiceDueRow a, GarageServiceDueRow b) {
  final r = (a.isOverdue ? 0 : 1).compareTo(b.isOverdue ? 0 : 1);
  if (r != 0) return r;
  final v = a.vehicleNumber.compareTo(b.vehicleNumber);
  if (v != 0) return v;
  return a.serviceType.compareTo(b.serviceType);
}

class _GarageNotificationsTab extends StatefulWidget {
  const _GarageNotificationsTab();

  @override
  State<_GarageNotificationsTab> createState() =>
      _GarageNotificationsTabState();
}

class _GarageNotificationsTabState extends State<_GarageNotificationsTab> {
  late Future<
    ({List<GarageVehicleStatus> vehicleStatuses, List<GarageServiceTypeAlert> typeAlerts})
  >
  _statusesFuture;
  final _searchController = TextEditingController();
  String _search = '';
  String _filter = kServiceTableFilterAll;
  final _table = DataTableController<GarageServiceDueRow>();

  static String _km(GarageServiceDueRow r) =>
      r.currentKm == null ? 'unknown' : '${r.currentKm!.toStringAsFixed(1)} km';
  static String _toDue(GarageServiceDueRow r) => r.isOverdue
      ? '-${(-r.kmRemaining).toStringAsFixed(1)} km'
      : '${r.kmRemaining.toStringAsFixed(1)} km';

  @override
  void dispose() {
    _searchController.dispose();
    super.dispose();
  }

  @override
  void initState() {
    super.initState();
    _statusesFuture = GarageService.fetchAllStatuses();
  }

  Future<void> _refresh() async {
    final future = GarageService.fetchAllStatuses();
    setState(() => _statusesFuture = future);
    await future;
  }

  @override
  Widget build(BuildContext context) {
    return RefreshIndicator(
      onRefresh: _refresh,
      child: FutureBuilder<
        ({List<GarageVehicleStatus> vehicleStatuses, List<GarageServiceTypeAlert> typeAlerts})
      >(
        future: _statusesFuture,
        builder: (context, snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting) {
            return const Center(child: CircularProgressIndicator());
          }
          if (snapshot.hasError) {
            return ListView(
              children: [
                Padding(
                  padding: const EdgeInsets.all(16),
                  child: Text('Failed to load: ${snapshot.error}'),
                ),
              ],
            );
          }
          final dueSoon =
              (snapshot.data?.vehicleStatuses ?? [])
                  .where(
                    (s) => s.kmRemaining <= GarageService.lowKmWarningThreshold,
                  )
                  .toList()
                ..sort((a, b) => a.kmRemaining.compareTo(b.kmRemaining));
          // Independent per-service-type alerts (see PART A) — a vehicle
          // can appear here multiple times, once per type nearing/overdue,
          // separately from (and in addition to) its single generic
          // dueSoon entry above.
          final typeDueSoon = snapshot.data?.typeAlerts ?? [];
          if (dueSoon.isEmpty && typeDueSoon.isEmpty) {
            return ListView(
              children: const [
                Padding(
                  padding: EdgeInsets.all(32),
                  child: Center(
                    child: Text(
                      'No upcoming services.',
                      style: TextStyle(color: Colors.grey),
                    ),
                  ),
                ),
              ],
            );
          }
          final rows = buildGarageServiceDueRows(
            vehicleStatuses: snapshot.data?.vehicleStatuses ?? const [],
            typeAlerts: typeDueSoon,
          );
          final q = _search.trim().toUpperCase();
          final searched = q.isEmpty
              ? rows
              : rows.where((r) => r.vehicleNumber.toUpperCase().contains(q)).toList();
          final shown = _filter == kServiceTableFilterAll
              ? searched
              : searched
                  .where((r) =>
                      (r.isOverdue ? ServiceItemDueStatus.overdue : ServiceItemDueStatus.dueSoon) ==
                      _filter)
                  .toList();
          return Padding(
            padding: const EdgeInsets.all(12),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                DataTableToolbar(
                  searchController: _searchController,
                  onSearchChanged: (v) => setState(() => _search = v),
                  onExport: (f) => exportDataTable<GarageServiceDueRow>(
                    context,
                    format: f,
                    controller: _table,
                    title: 'Garage Service Notifications',
                    filters: describeTableFilters(
                      statusLabel: _filter.replaceAll('_', ' '),
                      search: _search,
                    ),
                  ),
                  selectedFilter: _filter,
                  onFilterChanged: (v) => setState(() => _filter = v),
                  filters: [
                    DataTableFilterOption(
                        value: kServiceTableFilterAll, label: 'ALL', count: searched.length),
                    DataTableFilterOption(
                      value: ServiceItemDueStatus.overdue,
                      label: 'OVERDUE',
                      count: searched.where((r) => r.isOverdue).length,
                      color: AppColors.danger,
                    ),
                    DataTableFilterOption(
                      value: ServiceItemDueStatus.dueSoon,
                      label: 'DUE SOON',
                      count: searched.where((r) => !r.isOverdue).length,
                      color: AppColors.warning,
                    ),
                  ],
                ),
                const SizedBox(height: AppSpacing.sm),
                Expanded(
                  child: DataTableView<GarageServiceDueRow>(
                    rows: shown,
                    initialSortColumn: 5,
                    controller: _table,
                    resetPageKey: '$_filter|$_search',
                    emptyState: const Center(
                      child: Text('No services match this filter.',
                          style: TextStyle(color: Colors.grey)),
                    ),
                    columns: [
                      DataTableColumn(
                        label: 'Vehicle',
                        width: 110,
                        cellBuilder: (_, r) => Text(r.vehicleNumber,
                            style: const TextStyle(fontWeight: FontWeight.w700)),
                        compare: (a, b) => a.vehicleNumber.compareTo(b.vehicleNumber),
                        exportValue: (r) => r.vehicleNumber,
                      ),
                      DataTableColumn(
                        label: 'Type',
                        width: 80,
                        cellBuilder: (_, r) => Icon(
                          r.isBike ? Icons.two_wheeler : Icons.local_shipping,
                          size: 18,
                          color: Colors.grey[700],
                        ),
                        compare: (a, b) => (a.isBike ? 1 : 0).compareTo(b.isBike ? 1 : 0),
                        exportValue: (r) => r.isBike ? 'Bike' : 'Truck',
                      ),
                      DataTableColumn(
                        label: 'Service type',
                        width: 170,
                        cellBuilder: (_, r) => Text(r.serviceType),
                        compare: (a, b) => a.serviceType.compareTo(b.serviceType),
                        exportValue: (r) => r.serviceType,
                      ),
                      DataTableColumn(
                        label: 'Current km',
                        width: 120,
                        numeric: true,
                        cellBuilder: (_, r) => Text(
                          r.currentKm == null ? 'unknown' : '${r.currentKm!.toStringAsFixed(1)} km',
                        ),
                        compare: (a, b) => _compareNullable(a.currentKm, b.currentKm),
                        exportValue: _km,
                      ),
                      DataTableColumn(
                        label: 'Km to due',
                        width: 120,
                        numeric: true,
                        cellBuilder: (_, r) => Text(
                          r.isOverdue
                              ? '-${(-r.kmRemaining).toStringAsFixed(1)} km'
                              : '${r.kmRemaining.toStringAsFixed(1)} km',
                          style: TextStyle(
                            color: r.isOverdue ? Colors.red[900] : Colors.orange[900],
                            fontWeight: FontWeight.w600,
                          ),
                        ),
                        compare: (a, b) => a.kmRemaining.compareTo(b.kmRemaining),
                        exportValue: _toDue,
                      ),
                      DataTableColumn(
                        label: 'Status',
                        width: 120,
                        cellBuilder: (_, r) => DataTableStatusChip(
                          label: r.isOverdue ? 'OVERDUE' : 'DUE SOON',
                          color: r.isOverdue ? AppColors.danger : AppColors.warning,
                        ),
                        compare: compareGarageServiceDueRows,
                        exportValue: (r) => r.isOverdue ? 'OVERDUE' : 'DUE SOON',
                      ),
                    ],
                  ),
                ),
              ],
            ),
          );
        },
      ),
    );
  }
}

// ---------------- GARAGE NOTIFICATION SERVICE (mobile-only) ----------------
// "Phase 1" daily service-due check — this is NOT a true background daily
// notification (nothing fires while the app is fully closed). Instead it
// runs once on each day's first app open (see AuthGate, which calls this
// right after resolving the signed-in user's Firestore doc), using a
// SharedPreferences-stored date string so it doesn't repeat later the same
// day even across multiple app opens/rebuilds.
class GarageNotificationService {
  static final FlutterLocalNotificationsPlugin _plugin =
      FlutterLocalNotificationsPlugin();
  static bool _initialized = false;
  static const String _lastCheckDateKey = 'garage_last_notification_check_date';

  static Future<void> _ensureInitialized() async {
    if (_initialized) return;
    const androidSettings = AndroidInitializationSettings(
      '@mipmap/ic_launcher',
    );
    const settings = InitializationSettings(android: androidSettings);
    await _plugin.initialize(settings: settings);
    // Android 13+ requires this explicit runtime request — see
    // AndroidManifest.xml's POST_NOTIFICATIONS permission.
    await _plugin
        .resolvePlatformSpecificImplementation<
          AndroidFlutterLocalNotificationsPlugin
        >()
        ?.requestNotificationsPermission();
    _initialized = true;
  }

  static String _todayString() {
    final now = DateTime.now();
    return '${now.year}-${now.month.toString().padLeft(2, '0')}-'
        '${now.day.toString().padLeft(2, '0')}';
  }

  // Called once per app session from AuthGate, after a user is signed in
  // (the Firestore/Traccar reads below need that). Mobile-only, per this
  // feature's own design (see class doc comment) — it exists to reach a
  // "mechanic" on their phone, not the web dashboard.
  static Future<void> checkAndNotifyIfNeeded() async {
    if (kIsWeb) return;
    try {
      final prefs = await SharedPreferences.getInstance();
      final today = _todayString();
      if (prefs.getString(_lastCheckDateKey) == today) return;

      await _ensureInitialized();

      final result = await GarageService.fetchAllStatuses();
      final dueSoon = result.vehicleStatuses
          .where((s) => s.kmRemaining <= GarageService.lowKmWarningThreshold)
          .toList();
      final typeDueSoon = result.typeAlerts;

      var notificationId = 1000;
      for (final status in dueSoon) {
        final isOverdue = status.kmRemaining < 0;
        await _plugin.show(
          id: notificationId++,
          title: 'Garage: Service Due',
          body: isOverdue
              ? '${status.isBike ? 'Bike' : 'Truck'} ${status.vehicleNumber} '
                    'is overdue for service by '
                    '${(-status.kmRemaining).toStringAsFixed(0)} km.'
              : '${status.isBike ? 'Bike' : 'Truck'} ${status.vehicleNumber} '
                    'needs service in '
                    '${status.kmRemaining.toStringAsFixed(0)} km.',
          notificationDetails: const NotificationDetails(
            android: AndroidNotificationDetails(
              'garage_service_due',
              'Garage Service Due',
              channelDescription:
                  'Alerts when a company truck or bike is nearing its next '
                  'service.',
              importance: Importance.high,
              priority: Priority.high,
            ),
          ),
        );
      }
      // Independent per-service-type alerts (see PART A) — same
      // "Truck X - Oil Change due in Y km" wording the Notifications tab
      // shows, since a vehicle can have several of these due at once.
      for (final alert in typeDueSoon) {
        await _plugin.show(
          id: notificationId++,
          title: 'Garage: Service Due',
          body: alert.isOverdue
              ? '${alert.isBike ? 'Bike' : 'Truck'} ${alert.vehicleNumber} - '
                    '${alert.typeName} is overdue by '
                    '${(-alert.kmRemaining).toStringAsFixed(0)} km.'
              : '${alert.isBike ? 'Bike' : 'Truck'} ${alert.vehicleNumber} - '
                    '${alert.typeName} due in '
                    '${alert.kmRemaining.toStringAsFixed(0)} km.',
          notificationDetails: const NotificationDetails(
            android: AndroidNotificationDetails(
              'garage_service_due',
              'Garage Service Due',
              channelDescription:
                  'Alerts when a company truck or bike is nearing its next '
                  'service.',
              importance: Importance.high,
              priority: Priority.high,
            ),
          ),
        );
      }

      await prefs.setString(_lastCheckDateKey, today);
    } catch (e) {
      debugPrint('GarageNotificationService.checkAndNotifyIfNeeded failed: $e');
    }
  }
}

// ---------------- WAREHOUSE INVENTORY MANAGEMENT ----------------
