Future<bool> _isAdminOwnerOrManagement({
  FirebaseFirestore? db,
  String? uidOverride,
}) async {
  final uid = uidOverride ?? FirebaseAuth.instance.currentUser?.uid;
  if (uid == null) return false;
  final doc = await (db ?? FirebaseFirestore.instance).collection('users').doc(uid).get();
  final role = doc.data()?['role'] as String?;
  return role == 'admin' || role == 'owner' || role == 'management';
}

// ---------------- VEHICLE INSPECTION ----------------
// Daily inspection checklist for the company lorry fleet (see
// TruckManagementScreen/'trucks' collection — the same source every other
// Truck Number field in the app reads from). Weekly / Every 3 Weeks are
// future frequencies: the selector below already has a slot for each, shown
// disabled ("Coming Soon") until that work is built — only Daily is wired up.
class VehicleInspectionScreen extends StatefulWidget {
  final String name;
  // Test-only seams — every existing call site omits these and keeps
  // using the real FirebaseFirestore.instance/FirebaseAuth.instance.
  final FirebaseFirestore? firestoreOverride;
  final String? currentUidOverride;
  const VehicleInspectionScreen({
    super.key,
    required this.name,
    this.firestoreOverride,
    this.currentUidOverride,
  });

  @override
  State<VehicleInspectionScreen> createState() =>
      _VehicleInspectionScreenState();
}

class _VehicleInspectionScreenState extends State<VehicleInspectionScreen>
    with TickerProviderStateMixin {
  FirebaseFirestore get _db => widget.firestoreOverride ?? FirebaseFirestore.instance;
  String? get _uid => widget.currentUidOverride ?? FirebaseAuth.instance.currentUser?.uid;
  late final TabController _dailyTabController;
  // Weekly has no Monthly Summary tab (see _InspectionMonthlySummaryTab's
  // doc comment — stars/rating is a Daily-only concept), so it only needs
  // the New/Records pair, not a 3rd tab.
  late final TabController _weeklyTabController;
  String _frequency = 'daily';
  // Defence in depth — this screen had no permission check of its own at
  // all before (it's only ever reached today via VehicleMaintenanceHubScreen,
  // which is itself unreachable for 'driver'); 'driver' never reaches
  // anything past this one single read.
  late final Future<bool> _isDriverFuture = _checkIsDriver();

  Future<bool> _checkIsDriver() async {
    final uid = _uid;
    if (uid == null) return false;
    final doc = await _db.collection('users').doc(uid).get();
    return (doc.data()?['role'] as String?) == 'driver';
  }

  @override
  void initState() {
    super.initState();
    _dailyTabController = TabController(length: 3, vsync: this);
    _weeklyTabController = TabController(length: 2, vsync: this);
  }

  @override
  void dispose() {
    _dailyTabController.dispose();
    _weeklyTabController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<bool>(
      future: _isDriverFuture,
      builder: (context, driverSnap) {
        if (driverSnap.connectionState != ConnectionState.done) {
          return const Scaffold(body: LoadingState());
        }
        if (driverSnap.data == true) {
          return const Scaffold(
            body: EmptyState(
              icon: Icons.lock_outline,
              title: 'NO ACCESS',
            ),
          );
        }
        return _buildInspectionTabs(context);
      },
    );
  }

  Widget _buildInspectionTabs(BuildContext context) {
    final isDaily = _frequency == 'daily';
    final isWeekly = _frequency == 'weekly';
    return Scaffold(
      appBar: AppBar(
        title: const Text('Vehicle Inspection'),
        backgroundColor: Colors.deepOrange[800],
        foregroundColor: Colors.white,
        bottom: isDaily
            ? TabBar(
                controller: _dailyTabController,
                tabs: const [
                  Tab(text: 'New Inspection', icon: Icon(Icons.add_box)),
                  Tab(text: 'Records', icon: Icon(Icons.list_alt)),
                  Tab(text: 'Monthly Summary', icon: Icon(Icons.bar_chart)),
                ],
              )
            : isWeekly
            ? TabBar(
                controller: _weeklyTabController,
                tabs: const [
                  Tab(text: 'New Inspection', icon: Icon(Icons.add_box)),
                  Tab(text: 'Records', icon: Icon(Icons.list_alt)),
                ],
              )
            : null,
      ),
      body: Column(
        children: [
          Padding(
            padding: const EdgeInsets.all(12),
            child: Wrap(
              spacing: 8,
              runSpacing: 8,
              children: [
                ChoiceChip(
                  label: const Text('Daily'),
                  selected: isDaily,
                  onSelected: (_) => setState(() => _frequency = 'daily'),
                ),
                ChoiceChip(
                  label: const Text('Weekly'),
                  selected: isWeekly,
                  onSelected: (_) => setState(() => _frequency = 'weekly'),
                ),
                const ChoiceChip(
                  label: Text('Every 3 Weeks (Coming Soon)'),
                  selected: false,
                  onSelected: null,
                ),
              ],
            ),
          ),
          Expanded(
            child: isDaily
                ? TabBarView(
                    controller: _dailyTabController,
                    children: [
                      _NewDailyInspectionTab(
                        userName: widget.name,
                        firestoreOverride: widget.firestoreOverride,
                        currentUidOverride: widget.currentUidOverride,
                      ),
                      _InspectionRecordsTab(
                        userName: widget.name,
                        firestoreOverride: widget.firestoreOverride,
                        currentUidOverride: widget.currentUidOverride,
                      ),
                      const _InspectionMonthlySummaryTab(),
                    ],
                  )
                : isWeekly
                ? TabBarView(
                    controller: _weeklyTabController,
                    children: [
                      _NewWeeklyInspectionTab(
                        userName: widget.name,
                        firestoreOverride: widget.firestoreOverride,
                        currentUidOverride: widget.currentUidOverride,
                      ),
                      _WeeklyInspectionRecordsTab(
                        userName: widget.name,
                        firestoreOverride: widget.firestoreOverride,
                        currentUidOverride: widget.currentUidOverride,
                      ),
                    ],
                  )
                : const Center(
                    child: Text(
                      'This inspection frequency is coming soon.',
                      style: TextStyle(fontSize: 14, color: Colors.grey),
                    ),
                  ),
          ),
        ],
      ),
    );
  }
}

// Searchable bottom-sheet vehicle-number picker, same shape as the
// per-screen _showWorkingSiteFieldPicker pattern (search field +
// StreamBuilder + ListView, selection returned via Navigator.pop) — sourced
// from the 'trucks' collection, filtered to isCompanyTruck:true same as
// GarageScreen's own truck list.
Future<String?> _showVehicleNumberPicker(BuildContext context) {
  return showModalBottomSheet<String>(
    context: context,
    isScrollControlled: true,
    shape: const RoundedRectangleBorder(
      borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
    ),
    builder: (sheetContext) {
      String searchText = '';
      return StatefulBuilder(
        builder: (sheetContext, setSheetState) {
