                      stream: FirebaseFirestore.instance
                          .collection('trucks')
                          .where('isCompanyTruck', isEqualTo: true)
                          .snapshots(),
                      builder: (context, snapshot) {
                        if (!snapshot.hasData) {
                          return const Center(
                            child: CircularProgressIndicator(),
                          );
