// RED ALERTS-aware variant of _showVehicleNumberPicker, used ONLY by the
// "Do Service" entry point — every other caller of the plain picker
// (defect reports, repair jobs, etc.) has nothing to do with service-due
// status, so that shared picker is deliberately left untouched and this
// is a separate function rather than a new parameter on it. Vehicles
// OVERDUE/MISSED a service sort first with a red dot + "OVERDUE" chip.
Future<String?> _showServiceVehiclePicker(
  BuildContext context, {
  FirebaseFirestore? db,
  String? uidOverride,
}) async {
  final loaded = await _loadAlertsForCurrentUser(
    db: db,
    uid: uidOverride ?? FirebaseAuth.instance.currentUser?.uid,
  );
  final overdueVehicles = loaded.alerts
      .where((a) =>
          a.kind == ServiceAlertKind.serviceDue &&
          (a.severity == ServiceAlertSeverity.overdue ||
              a.severity == ServiceAlertSeverity.missed))
      .map((a) => a.vehicleNumber)
      .toSet();
  final dueSoonVehicles = loaded.alerts
      .where((a) =>
          a.kind == ServiceAlertKind.serviceDue &&
          (a.severity == ServiceAlertSeverity.dueSoon ||
              a.severity == ServiceAlertSeverity.kmUnknown))
      .map((a) => a.vehicleNumber)
      .toSet();
  if (!context.mounted) return null;
  return showModalBottomSheet<String>(
    context: context,
    isScrollControlled: true,
    shape: const RoundedRectangleBorder(
      borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
    ),
    builder: (sheetContext) {
      String searchText = '';
      return StatefulBuilder(
        builder: (sheetContext, setSheetState) {
          return Padding(
            padding: EdgeInsets.only(
              bottom: MediaQuery.of(sheetContext).viewInsets.bottom,
            ),
            child: SizedBox(
              height: MediaQuery.of(sheetContext).size.height * 0.75,
              child: Column(
                children: [
                  const SizedBox(height: 12),
                  Container(
                    width: 40,
                    height: 4,
                    decoration: BoxDecoration(
                      color: Colors.grey[300],
                      borderRadius: BorderRadius.circular(2),
                    ),
                  ),
                  Padding(
                    padding: const EdgeInsets.all(16),
                    child: TextField(
                      autofocus: true,
                      inputFormatters: [UpperCaseTextFormatter()],
                      textCapitalization: TextCapitalization.characters,
                      decoration: InputDecoration(
                        hintText: 'Search vehicle number',
                        prefixIcon: const Icon(Icons.search),
                        border: OutlineInputBorder(
                          borderRadius: BorderRadius.circular(12),
                        ),
                      ),
                      onChanged: (val) => setSheetState(() => searchText = val),
                    ),
                  ),
                  Expanded(
                    child: StreamBuilder<QuerySnapshot>(
                      stream: (db ?? FirebaseFirestore.instance)
                          .collection('trucks')
                          .where('isCompanyTruck', isEqualTo: true)
                          .snapshots(),
                      builder: (context, snapshot) {
                        if (!snapshot.hasData) {
                          return const Center(child: CircularProgressIndicator());
                        }
                        final filtered = snapshot.data!.docs.where((doc) {
                          final number =
                              ((doc.data() as Map<String, dynamic>)['truckNumber'] ?? '')
                                  .toString();
                          return number.toLowerCase().contains(searchText.toLowerCase());
                        }).toList()
                          ..sort((a, b) {
                            final an =
                                ((a.data() as Map<String, dynamic>)['truckNumber'] ?? '')
                                    .toString();
                            final bn =
                                ((b.data() as Map<String, dynamic>)['truckNumber'] ?? '')
                                    .toString();
                            final aOverdue = overdueVehicles.contains(an);
                            final bOverdue = overdueVehicles.contains(bn);
                            if (aOverdue != bOverdue) return aOverdue ? -1 : 1;
                            final aDueSoon = dueSoonVehicles.contains(an);
                            final bDueSoon = dueSoonVehicles.contains(bn);
                            if (aDueSoon != bDueSoon) return aDueSoon ? -1 : 1;
                            return an.compareTo(bn);
                          });
                        if (filtered.isEmpty) {
                          return const Center(child: Text('No matching vehicles.'));
                        }
                        return ListView.builder(
                          itemCount: filtered.length,
                          itemBuilder: (context, index) {
                            final data = filtered[index].data() as Map<String, dynamic>;
                            final number = (data['truckNumber'] ?? '').toString();
                            final overdue = overdueVehicles.contains(number);
                            final dueSoon = !overdue && dueSoonVehicles.contains(number);
                            final dotColor = overdue
                                ? AppColors.danger
                                : dueSoon
                                    ? AppColors.warning
                                    : null;
                            return ListTile(
                              leading: dotColor != null
                                  ? Container(
                                      width: 10,
                                      height: 10,
                                      decoration: BoxDecoration(
                                        color: dotColor,
                                        shape: BoxShape.circle,
                                      ),
                                    )
                                  : const Icon(Icons.local_shipping, color: Colors.brown),
                              title: Text(number),
                              trailing: dotColor != null
                                  ? Container(
                                      padding: const EdgeInsets.symmetric(
                                          horizontal: 8, vertical: 2),
                                      decoration: BoxDecoration(
                                        color: dotColor,
                                        borderRadius: BorderRadius.circular(AppRadius.chip),
                                      ),
                                      child: Text(
                                        overdue ? 'OVERDUE' : 'DUE SOON',
                                        style: const TextStyle(
                                          color: Colors.white,
                                          fontSize: 11,
                                          fontWeight: FontWeight.bold,
                                        ),
                                      ),
                                    )
                                  : null,
                              onTap: () => Navigator.pop(sheetContext, number),
                            );
                          },
                        );
                      },
                    ),
                  ),
                ],
              ),
            ),
          );
        },
      );
    },
  );
}

// Tap-to-select 1-5 star row, shared by the New Inspection form (interactive)
// and the Records list (read-only, via ignoring: true).
class _StarRatingSelector extends StatelessWidget {
  final int rating;
  final ValueChanged<int>? onChanged;
  final double size;

  const _StarRatingSelector({
    required this.rating,
    this.onChanged,
    this.size = 32,
  });

  @override
  Widget build(BuildContext context) {
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: List.generate(5, (index) {
        final starValue = index + 1;
        final filled = starValue <= rating;
        return IconButton(
          padding: EdgeInsets.zero,
          constraints: BoxConstraints(minWidth: size, minHeight: size),
          icon: Icon(
            filled ? Icons.star : Icons.star_border,
            color: filled ? Colors.amber[700] : Colors.grey,
            size: size * 0.75,
          ),
          onPressed: onChanged == null ? null : () => onChanged!(starValue),
        );
      }),
    );
  }
}

String _vehicleInspectionYmd(DateTime d) =>
    '${d.year.toString().padLeft(4, '0')}-'
    '${d.month.toString().padLeft(2, '0')}-'
    '${d.day.toString().padLeft(2, '0')}';

String _vehicleInspectionYm(DateTime d) =>
    '${d.year.toString().padLeft(4, '0')}-'
    '${d.month.toString().padLeft(2, '0')}';

// ISO-8601 week number (Mon-start weeks, week 1 is the week containing the
// year's first Thursday) — returns (isoYear, isoWeek). isoYear can differ
// from date.year for the first/last few days of a calendar year, which is
// why weekKey/doc id below use isoYear rather than date.year.
(int, int) _isoWeekOf(DateTime date) {
  final d = DateTime.utc(date.year, date.month, date.day);
  final thursdayOfThisWeek = d.add(Duration(days: 4 - d.weekday));
  final isoYear = thursdayOfThisWeek.year;
  final firstDayOfIsoYear = DateTime.utc(isoYear, 1, 1);
  final firstThursday = firstDayOfIsoYear.add(
    Duration(days: (4 - firstDayOfIsoYear.weekday + 7) % 7),
  );
  final weekNumber =
      1 + (thursdayOfThisWeek.difference(firstThursday).inDays ~/ 7);
  return (isoYear, weekNumber);
}

// Weekly Inspection's 4 check items — key (Firestore field name under
// items{}) paired with its display label. A const list on purpose (see the
// task's own note): relabeling later is a one-line edit here, nothing else
// needs to change.
const List<MapEntry<String, String>> kWeeklyInspectionItems = [
  MapEntry('bowFrontLeft', 'BOW FRONT LEFT'),
  MapEntry('bowFrontRight', 'BOW FRONT RIGHT'),
  MapEntry('bowBackLeft', 'BOW BACK LEFT'),
  MapEntry('bowBackRight', 'BOW BACK RIGHT'),
];

String _formatInspectionDateTime(dynamic ts) {
  if (ts is! Timestamp) return '—';
  final dt = ts.toDate();
  final hour = dt.hour % 12 == 0 ? 12 : dt.hour % 12;
  final period = dt.hour >= 12 ? 'PM' : 'AM';
  final minute = dt.minute.toString().padLeft(2, '0');
  return '${dt.year}-${dt.month.toString().padLeft(2, '0')}-'
      '${dt.day.toString().padLeft(2, '0')} $hour:$minute $period';
}

