// ---------------- INSPECTION PHOTOS / VOICE NOTES ----------------
// Shared by both Daily and Weekly Vehicle Inspection forms (New + Edit) —
// see _InspectionAttachmentsSection below. Storage layout (exact — Storage
// rules are published separately against this):
//   vehicle_inspections/{type}/{vehicleNumber}/{docId}/photos/{n}_{ts}.jpg
//   vehicle_inspections/{type}/{vehicleNumber}/{docId}/voice/{n}_{ts}.{ext}
// {docId} is the same deterministic id the Firestore doc itself uses
// (vehicleNumber_date for daily, vehicleNumber_Wyyyyww for weekly), built
// by each form's own _save() — see _inspectionStoragePathPrefix below.

String _inspectionStoragePathPrefix({
  required String type,
  required String vehicleNumber,
  required String docId,
}) => 'vehicle_inspections/$type/$vehicleNumber/$docId';

// Browsers' MediaRecorder generally can't encode AAC (record_web throws
// '<encoder> not supported.' if asked to) — Opus/webm is what Chrome/
// Firefox actually support, so the encoder/extension/contentType differ by
// platform. aacLc -> .m4a matches the task spec for mobile; opus -> .webm
// is what the task's own doc comment anticipated for web.
AudioEncoder _inspectionAudioEncoder() =>
    kIsWeb ? AudioEncoder.opus : AudioEncoder.aacLc;

String _inspectionAudioExtension() => kIsWeb ? 'webm' : 'm4a';

String _inspectionAudioContentType() =>
    kIsWeb ? 'audio/webm' : 'audio/mp4';

// Resize to a max 1280px long edge (never upscales) + re-encode as JPEG
// quality 75, then steps quality down further if still over 5MB. Runs via
// compute() so the decode/resize/encode doesn't jank the UI thread on
// native (web has no real isolates, so compute() just runs this inline
// there — still correct, just not off-thread).
Uint8List _compressInspectionPhotoBytes(Uint8List original) {
  final decoded = img.decodeImage(original);
  if (decoded == null) return original;
  const maxEdge = 1280;
  img.Image resized = decoded;
  if (decoded.width > maxEdge || decoded.height > maxEdge) {
    resized = decoded.width >= decoded.height
        ? img.copyResize(decoded, width: maxEdge)
        : img.copyResize(decoded, height: maxEdge);
  }
  var quality = 75;
  var out = img.encodeJpg(resized, quality: quality);
  const maxBytes = 5 * 1024 * 1024;
  while (out.length > maxBytes && quality > 30) {
    quality -= 10;
    out = img.encodeJpg(resized, quality: quality);
  }
  return out;
}

class _PhotoAttachmentItem {
  Uint8List? bytes;
  String? url;
  String? path;
  String? error;
  bool uploading = false;
  _PhotoAttachmentItem({this.bytes, this.url, this.path});
}

class _VoiceAttachmentItem {
  Uint8List? bytes;
  String? url;
  String? path;
  int durationSec;
  String? error;
  bool uploading = false;
  _VoiceAttachmentItem({
    this.bytes,
    this.url,
    this.path,
    required this.durationSec,
  });
}

class InspectionAttachmentsResult {
  final List<Map<String, dynamic>> photos;
  final List<Map<String, dynamic>> voices;
  final bool hadFailures;
  const InspectionAttachmentsResult({
    required this.photos,
    required this.voices,
    required this.hadFailures,
  });
}

// Reusable Photos + Voice Notes editor for both Daily and Weekly forms.
// Pick/record only stages attachments locally (no Storage write yet) — the
// parent form calls uploadAndFinalize(storagePathPrefix) at Save time
// (via a GlobalKey<_InspectionAttachmentsSectionState>), which uploads
// every not-yet-uploaded item, deletes any removed-and-previously-uploaded
// Storage files, and returns the final {n, url, path} lists to write onto
// the inspection doc. A failed upload never throws out of this method —
// the item keeps an `error` and is simply omitted from the returned list,
// so the caller's main Firestore save is never blocked by it (see the
// "Retry" row below, and each form's _save()).
class _InspectionAttachmentsSection extends StatefulWidget {
  final List<Map<String, dynamic>> initialPhotos;
  final List<Map<String, dynamic>> initialVoices;
  // Called after a Retry re-upload finishes (NOT after the initial Save —
  // that result is returned directly from uploadAndFinalize instead), so
  // the parent can .update() the already-saved doc with the newly
  // completed attachments.
  final Future<void> Function(InspectionAttachmentsResult result)?
  onRetrySaved;

  const _InspectionAttachmentsSection({
    super.key,
    this.initialPhotos = const [],
    this.initialVoices = const [],
    this.onRetrySaved,
  });

  @override
  State<_InspectionAttachmentsSection> createState() =>
      _InspectionAttachmentsSectionState();
}

class _InspectionAttachmentsSectionState
    extends State<_InspectionAttachmentsSection> {
  final List<_PhotoAttachmentItem> _photos = [];
  final List<_VoiceAttachmentItem> _voices = [];
  final Set<String> _removedStoragePaths = {};

  final AudioRecorder _recorder = AudioRecorder();
  final AudioPlayer _player = AudioPlayer();
  StreamSubscription<PlayerState>? _playerStateSub;
  bool _isRecording = false;
  int _recordingSeconds = 0;
  Timer? _recordingTimer;
  int? _playingIndex;
  bool _busy = false;
  bool _retrying = false;
  String? _lastStoragePathPrefix;

  @override
  void initState() {
    super.initState();
    for (final p in widget.initialPhotos) {
      _photos.add(
        _PhotoAttachmentItem(url: p['url'] as String?, path: p['path'] as String?),
      );
    }
    for (final v in widget.initialVoices) {
      _voices.add(
        _VoiceAttachmentItem(
          url: v['url'] as String?,
          path: v['path'] as String?,
          durationSec: (v['durationSec'] as num?)?.toInt() ?? 0,
        ),
      );
    }
    _playerStateSub = _player.onPlayerStateChanged.listen((state) {
      if (!mounted) return;
      if (state == PlayerState.completed || state == PlayerState.stopped) {
        setState(() => _playingIndex = null);
      }
    });
  }

  @override
  void dispose() {
    _recordingTimer?.cancel();
    _playerStateSub?.cancel();
    _recorder.dispose();
    _player.dispose();
    super.dispose();
  }

  void _showSnack(String message) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(message)));
  }

  String _formatElapsed(int seconds) {
    final m = seconds ~/ 60;
    final s = seconds % 60;
    return '${m.toString().padLeft(2, '0')}:${s.toString().padLeft(2, '0')}';
  }

  bool get _hasFailures =>
      _photos.any((p) => p.error != null) || _voices.any((v) => v.error != null);

  // ---------------- Photos ----------------

  Future<void> _showAddPhotoSheet() async {
    if (_photos.length >= 10) {
      _showSnack('Maximum 10 photos.');
      return;
    }
    final choice = await showModalBottomSheet<String>(
      context: context,
      builder: (sheetContext) => SafeArea(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            ListTile(
              leading: const Icon(Icons.camera_alt, color: Colors.deepOrange),
              title: const Text('Take Photo'),
              onTap: () => Navigator.pop(sheetContext, 'camera'),
            ),
            ListTile(
              leading: const Icon(
                Icons.photo_library,
                color: Colors.deepOrange,
              ),
              title: Text(kIsWeb ? 'Choose Files' : 'Choose from Gallery'),
              onTap: () => Navigator.pop(sheetContext, 'gallery'),
            ),
          ],
        ),
      ),
    );
    if (choice == null) return;

    List<Uint8List> picked = [];
    try {
      if (choice == 'camera') {
        final xfile = await ImagePicker().pickImage(source: ImageSource.camera);
        if (xfile != null) picked.add(await xfile.readAsBytes());
      } else if (kIsWeb) {
        final files = await FilePicker.pickFiles(type: FileType.image);
        for (final f in files) {
          picked.add(await f.readAsBytes());
        }
      } else {
        final xfiles = await ImagePicker().pickMultiImage();
        for (final f in xfiles) {
          picked.add(await f.readAsBytes());
        }
      }
    } catch (e) {
      _showSnack('Failed to pick photo: $e');
      return;
    }
    if (picked.isEmpty) return;

    final remaining = 10 - _photos.length;
    if (picked.length > remaining) {
      _showSnack('Only $remaining more photo(s) can be added (max 10).');
      picked = picked.sublist(0, remaining);
    }

    setState(() => _busy = true);
    final compressed = <Uint8List>[];
    for (final bytes in picked) {
      try {
        compressed.add(await compute(_compressInspectionPhotoBytes, bytes));
      } catch (_) {
        compressed.add(bytes);
      }
    }
    if (!mounted) return;
    setState(() {
      for (final bytes in compressed) {
        _photos.add(_PhotoAttachmentItem(bytes: bytes));
      }
      _busy = false;
    });
  }

  void _removePhoto(int index) {
    setState(() {
      final removed = _photos.removeAt(index);
      if (removed.path != null) _removedStoragePaths.add(removed.path!);
    });
  }

  void _showPhotoPreview(int index) {
    Navigator.push(
      context,
      MaterialPageRoute(
        builder: (_) =>
            _InspectionPhotoPreviewScreen(photos: List.of(_photos), initialIndex: index),
      ),
    );
  }

  // ---------------- Voice ----------------

  Future<void> _startRecording() async {
    if (_voices.length >= 10) {
      _showSnack('Maximum 10 voice notes.');
      return;
    }
    bool granted;
    try {
      granted = await _recorder.hasPermission();
    } catch (_) {
      granted = false;
    }
    if (!granted) {
      _showSnack(
        'Microphone permission denied. Please allow microphone access to '
        'record a voice note.',
      );
      return;
    }
    String recordPath = '';
    if (!kIsWeb) {
      final dir = await getTemporaryDirectory();
      recordPath =
          '${dir.path}/voice_${DateTime.now().millisecondsSinceEpoch}.'
          '${_inspectionAudioExtension()}';
    }
    try {
      await _recorder.start(
        RecordConfig(encoder: _inspectionAudioEncoder()),
        path: recordPath,
      );
    } catch (e) {
      _showSnack('Failed to start recording: $e');
      return;
    }
    if (!mounted) return;
    setState(() {
      _isRecording = true;
      _recordingSeconds = 0;
    });
    _recordingTimer = Timer.periodic(const Duration(seconds: 1), (_) {
      if (!mounted) return;
      setState(() => _recordingSeconds++);
      if (_recordingSeconds >= 180) _stopRecording();
    });
  }

  Future<void> _stopRecording() async {
    _recordingTimer?.cancel();
    _recordingTimer = null;
    final elapsedSec = _recordingSeconds;
    String? resultPath;
    try {
      resultPath = await _recorder.stop();
    } catch (e) {
      _showSnack('Recording failed: $e');
    }
    if (mounted) setState(() => _isRecording = false);
    if (resultPath == null || resultPath.isEmpty) return;
    if (_voices.length >= 10) {
      _showSnack('Maximum 10 voice notes.');
      return;
    }
    try {
      final bytes = kIsWeb
          ? (await http.get(Uri.parse(resultPath))).bodyBytes
          : await inspection_audio_io.readRecordedAudioBytes(resultPath);
      if (!mounted) return;
      setState(() {
        _voices.add(_VoiceAttachmentItem(bytes: bytes, durationSec: elapsedSec));
      });
    } catch (e) {
      _showSnack('Failed to process recording: $e');
    }
  }

  Future<void> _togglePlay(int index) async {
    final item = _voices[index];
    if (_playingIndex == index) {
      await _player.pause();
      if (mounted) setState(() => _playingIndex = null);
      return;
    }
    await _player.stop();
    try {
      if (item.url != null) {
        await _player.play(UrlSource(item.url!));
      } else if (item.bytes != null) {
        await _player.play(
          BytesSource(item.bytes!, mimeType: _inspectionAudioContentType()),
        );
      } else {
        return;
      }
      if (mounted) setState(() => _playingIndex = index);
    } catch (e) {
      _showSnack('Failed to play recording: $e');
    }
  }

  void _removeVoice(int index) {
    if (_playingIndex == index) {
      _player.stop();
      _playingIndex = null;
    }
    setState(() {
      final removed = _voices.removeAt(index);
      if (removed.path != null) _removedStoragePaths.add(removed.path!);
    });
  }

  // ---------------- Upload / finalize ----------------

  Future<InspectionAttachmentsResult> uploadAndFinalize(
    String storagePathPrefix,
  ) async {
    _lastStoragePathPrefix = storagePathPrefix;
    var hadFailures = false;

    for (final path in _removedStoragePaths) {
      try {
        await FirebaseStorage.instance.ref(path).delete();
      } catch (_) {
        // Already gone, or a transient failure — never block the save
        // over a leftover Storage file.
      }
    }
    _removedStoragePaths.clear();

    for (var i = 0; i < _photos.length; i++) {
      final item = _photos[i];
      if (item.url != null) continue;
      if (mounted) setState(() => item.uploading = true);
      try {
        final n = i + 1;
        final path =
            '$storagePathPrefix/photos/${n}_${DateTime.now().millisecondsSinceEpoch}.jpg';
        final ref = FirebaseStorage.instance.ref(path);
        await ref.putData(item.bytes!, SettableMetadata(contentType: 'image/jpeg'));
        item.url = await ref.getDownloadURL();
        item.path = path;
        item.error = null;
      } catch (e) {
        item.error = e.toString();
        hadFailures = true;
      } finally {
        if (mounted) setState(() => item.uploading = false);
      }
    }

    for (var i = 0; i < _voices.length; i++) {
      final item = _voices[i];
      if (item.url != null) continue;
      if (mounted) setState(() => item.uploading = true);
      try {
        final n = i + 1;
        final ext = _inspectionAudioExtension();
        final path =
            '$storagePathPrefix/voice/${n}_${DateTime.now().millisecondsSinceEpoch}.$ext';
        final ref = FirebaseStorage.instance.ref(path);
        await ref.putData(
          item.bytes!,
          SettableMetadata(contentType: _inspectionAudioContentType()),
        );
        item.url = await ref.getDownloadURL();
        item.path = path;
        item.error = null;
      } catch (e) {
        item.error = e.toString();
        hadFailures = true;
      } finally {
        if (mounted) setState(() => item.uploading = false);
      }
    }

    final photos = <Map<String, dynamic>>[];
    for (var i = 0; i < _photos.length; i++) {
      final item = _photos[i];
      if (item.url == null) continue;
      photos.add({'n': i + 1, 'url': item.url, 'path': item.path});
    }
    final voices = <Map<String, dynamic>>[];
    for (var i = 0; i < _voices.length; i++) {
      final item = _voices[i];
      if (item.url == null) continue;
      voices.add({
        'n': i + 1,
        'url': item.url,
        'path': item.path,
        'durationSec': item.durationSec,
      });
    }

    return InspectionAttachmentsResult(
      photos: photos,
      voices: voices,
      hadFailures: hadFailures,
    );
  }

  Future<void> _retryFailed() async {
    final prefix = _lastStoragePathPrefix;
    if (prefix == null || _retrying) return;
    setState(() => _retrying = true);
    try {
      final result = await uploadAndFinalize(prefix);
      if (widget.onRetrySaved != null) {
        await widget.onRetrySaved!(result);
      }
      if (mounted && !result.hadFailures) {
        _showSnack('Attachments uploaded successfully.');
      }
    } finally {
      if (mounted) setState(() => _retrying = false);
    }
  }

  // Called by the parent form after a successful save with no failures,
  // so a fresh "New Inspection" starts with an empty attachments section
  // instead of carrying over the previous submission's photos/voice notes
  // (those are already permanently attached to the doc that was just
  // saved — this only clears this widget's own local view of them).
  void clearAll() {
    setState(() {
      _photos.clear();
      _voices.clear();
      _removedStoragePaths.clear();
      _lastStoragePathPrefix = null;
    });
  }

  Widget _buildPhotoThumb(int index) {
    final item = _photos[index];
    return SizedBox(
      width: 84,
      height: 84,
      child: Stack(
        children: [
          Positioned.fill(
            child: GestureDetector(
              onTap: () => _showPhotoPreview(index),
              child: ClipRRect(
                borderRadius: BorderRadius.circular(8),
                child: item.bytes != null
                    ? Image.memory(item.bytes!, fit: BoxFit.cover)
                    : Image.network(
                        item.url!,
                        fit: BoxFit.cover,
                        cacheWidth: 252,
                        cacheHeight: 252,
                        errorBuilder: (_, __, ___) => Container(
                          color: Colors.grey[300],
                          child: const Icon(Icons.broken_image),
                        ),
                      ),
              ),
            ),
          ),
          Positioned(
            top: 3,
            left: 3,
            child: CircleAvatar(
              radius: 10,
              backgroundColor: Colors.black54,
              child: Text(
                '${index + 1}',
                style: const TextStyle(fontSize: 11, color: Colors.white),
              ),
            ),
          ),
          Positioned(
            top: 0,
            right: 0,
            child: InkWell(
              onTap: () => _removePhoto(index),
              child: const CircleAvatar(
                radius: 10,
                backgroundColor: Colors.red,
                child: Icon(Icons.close, size: 13, color: Colors.white),
              ),
            ),
          ),
          if (item.uploading)
            const Positioned.fill(
              child: ColoredBox(
                color: Colors.black38,
                child: Center(
                  child: SizedBox(
                    width: 20,
                    height: 20,
                    child: CircularProgressIndicator(
                      strokeWidth: 2,
                      color: Colors.white,
                    ),
                  ),
                ),
              ),
            ),
          if (item.error != null)
            Positioned(
              bottom: 0,
              left: 0,
              right: 0,
              child: Container(
                color: Colors.red.withOpacity(0.85),
                padding: const EdgeInsets.symmetric(vertical: 2),
                child: const Icon(
                  Icons.error_outline,
                  size: 14,
                  color: Colors.white,
                ),
              ),
            ),
        ],
      ),
    );
  }

  Widget _buildVoiceRow(int index) {
    final item = _voices[index];
    final isPlaying = _playingIndex == index;
    return Card(
      margin: const EdgeInsets.only(bottom: 6),
      child: ListTile(
        dense: true,
        leading: CircleAvatar(
          radius: 13,
          backgroundColor: Colors.deepOrange.withOpacity(0.15),
          child: Text(
            '${index + 1}',
            style: const TextStyle(fontSize: 11, color: Colors.deepOrange),
          ),
        ),
        title: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            IconButton(
              padding: EdgeInsets.zero,
              icon: Icon(
                isPlaying ? Icons.pause_circle : Icons.play_circle,
                color: Colors.deepOrange,
              ),
              onPressed: () => _togglePlay(index),
            ),
            Text(_formatElapsed(item.durationSec)),
          ],
        ),
        trailing: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            if (item.uploading)
              const Padding(
                padding: EdgeInsets.only(right: 8),
                child: SizedBox(
                  width: 16,
                  height: 16,
                  child: CircularProgressIndicator(strokeWidth: 2),
                ),
              ),
            if (item.error != null)
              const Padding(
                padding: EdgeInsets.only(right: 4),
                child: Icon(Icons.error_outline, color: Colors.red, size: 18),
              ),
            IconButton(
              icon: const Icon(Icons.delete, color: Colors.red),
              onPressed: () => _removeVoice(index),
            ),
          ],
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Row(
          children: [
            // Expanded (not Spacer) so this label shrinks on a narrow
            // screen instead of the Row demanding more width than it has —
            // a plain Text + Spacer + button here overflowed at 390px (see
            // the ServiceRecordFormScreen widget test this surfaced in).
            Expanded(
              child: Text(
                'Photos (${_photos.length}/10)',
                style: const TextStyle(fontWeight: FontWeight.bold),
                overflow: TextOverflow.ellipsis,
              ),
            ),
            TextButton.icon(
              onPressed: (_photos.length >= 10 || _busy)
                  ? null
                  : _showAddPhotoSheet,
              icon: const Icon(Icons.add_a_photo, size: 18),
              label: const Text('Add Photo'),
            ),
          ],
        ),
        if (_photos.isNotEmpty)
          Wrap(
            spacing: 8,
            runSpacing: 8,
            children: List.generate(_photos.length, _buildPhotoThumb),
          ),
        const SizedBox(height: 20),
        Row(
          children: [
            Expanded(
              child: Text(
                'Voice Notes (${_voices.length}/10)',
                style: const TextStyle(fontWeight: FontWeight.bold),
                overflow: TextOverflow.ellipsis,
              ),
            ),
            if (_isRecording)
              Text(
                _formatElapsed(_recordingSeconds),
                style: const TextStyle(
                  color: Colors.red,
                  fontWeight: FontWeight.bold,
                ),
              ),
          ],
        ),
        const SizedBox(height: 8),
        ...List.generate(_voices.length, _buildVoiceRow),
        Center(
          child: IconButton(
            iconSize: 44,
            icon: Icon(
              _isRecording ? Icons.stop_circle : Icons.mic_rounded,
              color: _isRecording ? Colors.red : Colors.deepOrange,
            ),
            tooltip: _isRecording ? 'Stop recording' : 'Record a voice note',
            onPressed: (_voices.length >= 10 && !_isRecording)
                ? null
                : (_isRecording ? _stopRecording : _startRecording),
          ),
        ),
        if (_hasFailures)
          Container(
            margin: const EdgeInsets.only(top: 8),
            padding: const EdgeInsets.all(10),
            decoration: BoxDecoration(
              color: Colors.red[50],
              borderRadius: BorderRadius.circular(8),
              border: Border.all(color: Colors.red[200]!),
            ),
            child: Row(
              children: [
                const Icon(Icons.error_outline, color: Colors.red, size: 18),
                const SizedBox(width: 8),
                const Expanded(
                  child: Text(
                    'Some attachments failed to upload.',
                    style: TextStyle(fontSize: 12),
                  ),
                ),
                TextButton(
                  onPressed: _retrying ? null : _retryFailed,
                  child: _retrying
                      ? const SizedBox(
                          width: 16,
                          height: 16,
                          child: CircularProgressIndicator(strokeWidth: 2),
                        )
                      : const Text('RETRY'),
                ),
              ],
            ),
          ),
      ],
    );
  }
}

class _InspectionPhotoPreviewScreen extends StatefulWidget {
