// Read-only photos gallery + voice players for the Records detail dialogs
// (Daily and Weekly) — shows already-uploaded attachments exactly as saved
// on the inspection doc; no pick/record/delete/upload here, see
// _InspectionAttachmentsSection for the editable version used in the forms.
class _InspectionAttachmentsViewer extends StatefulWidget {
  final List<Map<String, dynamic>> photos;
  final List<Map<String, dynamic>> voices;
  const _InspectionAttachmentsViewer({
    required this.photos,
    required this.voices,
  });

  @override
  State<_InspectionAttachmentsViewer> createState() =>
      _InspectionAttachmentsViewerState();
}

class _InspectionAttachmentsViewerState
    extends State<_InspectionAttachmentsViewer> {
  final AudioPlayer _player = AudioPlayer();
  StreamSubscription<PlayerState>? _playerStateSub;
  int? _playingIndex;

  @override
  void initState() {
    super.initState();
    _playerStateSub = _player.onPlayerStateChanged.listen((state) {
      if (!mounted) return;
      if (state == PlayerState.completed || state == PlayerState.stopped) {
        setState(() => _playingIndex = null);
      }
    });
  }

  @override
  void dispose() {
    _playerStateSub?.cancel();
    _player.dispose();
    super.dispose();
  }

  String _formatElapsed(int seconds) {
    final m = seconds ~/ 60;
    final s = seconds % 60;
    return '${m.toString().padLeft(2, '0')}:${s.toString().padLeft(2, '0')}';
  }

  Future<void> _togglePlay(int index) async {
    if (_playingIndex == index) {
      await _player.pause();
      if (mounted) setState(() => _playingIndex = null);
      return;
    }
    await _player.stop();
    final url = widget.voices[index]['url'] as String?;
    if (url == null) return;
    try {
      await _player.play(UrlSource(url));
      if (mounted) setState(() => _playingIndex = index);
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text('Failed to play recording: $e')));
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    if (widget.photos.isEmpty && widget.voices.isEmpty) {
      return const SizedBox.shrink();
    }
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        if (widget.photos.isNotEmpty) ...[
          const Text('Photos', style: TextStyle(fontWeight: FontWeight.bold)),
          const SizedBox(height: 6),
          Wrap(
            spacing: 8,
            runSpacing: 8,
            children: List.generate(widget.photos.length, (index) {
              final url = widget.photos[index]['url'] as String?;
              return GestureDetector(
                onTap: () {
                  final items = widget.photos
                      .map((p) => _PhotoAttachmentItem(url: p['url'] as String?))
                      .toList();
                  Navigator.push(
                    context,
                    MaterialPageRoute(
                      builder: (_) => _InspectionPhotoPreviewScreen(
                        photos: items,
                        initialIndex: index,
                      ),
                    ),
                  );
                },
                child: SizedBox(
                  width: 64,
                  height: 64,
                  child: ClipRRect(
                    borderRadius: BorderRadius.circular(8),
                    child: url == null
                        ? Container(
                            color: Colors.grey[300],
                            child: const Icon(Icons.broken_image),
                          )
                        : Image.network(
                            url,
                            fit: BoxFit.cover,
                            cacheWidth: 192,
                            cacheHeight: 192,
                            errorBuilder: (_, __, ___) => Container(
                              color: Colors.grey[300],
                              child: const Icon(Icons.broken_image),
                            ),
                          ),
                  ),
                ),
              );
            }),
          ),
          const SizedBox(height: 12),
        ],
        if (widget.voices.isNotEmpty) ...[
          const Text(
            'Voice Notes',
            style: TextStyle(fontWeight: FontWeight.bold),
          ),
          const SizedBox(height: 6),
          ...List.generate(widget.voices.length, (index) {
            final v = widget.voices[index];
            final durationSec = (v['durationSec'] as num?)?.toInt() ?? 0;
            final isPlaying = _playingIndex == index;
            return Padding(
              padding: const EdgeInsets.only(bottom: 4),
              child: Row(
                children: [
                  Text('${index + 1}.', style: const TextStyle(fontSize: 12)),
                  IconButton(
                    padding: EdgeInsets.zero,
                    icon: Icon(
                      isPlaying ? Icons.pause_circle : Icons.play_circle,
                      color: Colors.deepOrange,
                    ),
                    onPressed: () => _togglePlay(index),
                  ),
                  Text(_formatElapsed(durationSec)),
                ],
              ),
            );
          }),
        ],
      ],
    );
  }
}

// Shared "ADD REPAIR" entry point for all 4 Vehicle Inspection tabs —
// replaces the old separate REPORT DEFECT (conditional on a BAD/REPLACE
// tire or BAD/NOT_SUITABLE item) and ADD DEFECT (always-on multi-draft)
// buttons with a single action, gated by REPORT_DEFECT (checked once per
// mount; admin/owner always pass via hasRepairPerm). sourceInspectionId is
// the inspection's deterministic doc id (vehicleNumber_ymd for daily,
// vehicleNumber_Wyyyyww for weekly) — this works even before the
// inspection itself has been saved, since that id never depends on a
// server-assigned auto-id.
// The "REPAIRS FOUND" section glued onto the bottom of all 4 Vehicle
// Inspection tabs (daily/weekly, new/records) — an ADD REPAIR entry point
// (category-first AddRepairScreen) plus the list of repairs already logged
// against this inspection. Public (not `_`-prefixed) so it can be pumped
// and tested directly, independent of the real vehicle-number picker
// bottom sheet, which has no test seam.
//
// vehicleNumber is nullable/may be empty: that's the "no vehicle picked
// yet" state, shown as a disabled button rather than nothing at all.
class InspectionRepairsSection extends StatefulWidget {
  final String userName;
  final String? vehicleNumber;
  final String? inspectionId;
  final num? odometerKm;
  final FirebaseFirestore? firestoreOverride;
  final String? currentUidOverride;
  const InspectionRepairsSection({
    super.key,
    required this.userName,
    required this.vehicleNumber,
    required this.inspectionId,
    this.odometerKm,
    this.firestoreOverride,
    this.currentUidOverride,
  });

  @override
  State<InspectionRepairsSection> createState() => InspectionRepairsSectionState();
}

class InspectionRepairsSectionState extends State<InspectionRepairsSection> {
  FirebaseFirestore get _db => widget.firestoreOverride ?? FirebaseFirestore.instance;
  String? get _uid => widget.currentUidOverride ?? FirebaseAuth.instance.currentUser?.uid;
  late final Future<bool> _canAddRepair =
      _currentUserHasRepairPerm(kPermReportDefect, db: _db, uidOverride: _uid);

  @override
  Widget build(BuildContext context) {
    final vehicleNumber = widget.vehicleNumber;
    final hasVehicle = vehicleNumber != null && vehicleNumber.isNotEmpty;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        const Text('REPAIRS FOUND', style: TextStyle(fontWeight: FontWeight.bold)),
        const SizedBox(height: 8),
        if (!hasVehicle)
          const SizedBox(
            width: double.infinity,
            height: 48,
            child: OutlinedButton(
              onPressed: null,
              child: Text('Select a vehicle first'),
            ),
          )
        else
          FutureBuilder<bool>(
            future: _canAddRepair,
            builder: (context, snap) {
              if (snap.connectionState != ConnectionState.done) {
                return const SizedBox(height: 48);
              }
              if (snap.data != true) {
                return const Padding(
                  padding: EdgeInsets.symmetric(vertical: 8),
                  child: Text(
                    'No permission to add repairs - ask admin',
                    style: TextStyle(color: AppColors.textMuted, fontSize: 12),
                  ),
                );
              }
              return SizedBox(
                width: double.infinity,
                height: 48,
                child: OutlinedButton.icon(
                  onPressed: () => pushWebAware(
                    context,
                    AddRepairScreen(
                      userName: widget.userName,
                      vehicleNumber: vehicleNumber,
                      sourceInspectionId: widget.inspectionId,
                      odometerKm: widget.odometerKm,
                      firestoreOverride: widget.firestoreOverride,
                      currentUidOverride: widget.currentUidOverride,
                    ),
                  ),
                  icon: const Icon(Icons.build_circle_outlined),
                  label: const Text('ADD REPAIR'),
                ),
              );
            },
          ),
        if (hasVehicle) _repairsList(vehicleNumber),
      ],
    );
  }

  Widget _repairsList(String vehicleNumber) {
    final id = widget.inspectionId;
    if (id == null || id.isEmpty) return const SizedBox.shrink();
    return StreamBuilder<QuerySnapshot>(
      stream: _db.collection('repairs').where('inspectionId', isEqualTo: id).snapshots(),
      builder: (context, snapshot) {
        final docs = snapshot.data?.docs ?? const [];
        if (docs.isEmpty) return const SizedBox.shrink();
        return Padding(
          padding: const EdgeInsets.only(top: 12),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              const Text('Repairs Added', style: TextStyle(fontWeight: FontWeight.bold)),
              const SizedBox(height: 6),
              for (final doc in docs)
                _row(context, doc.data() as Map<String, dynamic>, vehicleNumber),
            ],
          ),
        );
      },
    );
  }

  Widget _row(BuildContext context, Map<String, dynamic> data, String vehicleNumber) {
    return InkWell(
      onTap: () => pushWebAware(
        context,
        RepairHistoryScreen(
          prefillVehicleNumber: vehicleNumber,
          firestoreOverride: widget.firestoreOverride,
          currentUidOverride: widget.currentUidOverride,
        ),
      ),
      child: Padding(
        padding: const EdgeInsets.symmetric(vertical: 6),
        child: Row(
          children: [
            Expanded(
              child: Text(
                '${data['code'] ?? ''} — ${data['categoryName'] ?? ''}: '
                '${data['description'] ?? ''}',
                softWrap: true,
              ),
            ),
            const Icon(Icons.chevron_right, size: 18),
          ],
        ),
      ),
    );
  }
}

class _NewDailyInspectionTab extends StatefulWidget {
  final String userName;
  final FirebaseFirestore? firestoreOverride;
  final String? currentUidOverride;
  const _NewDailyInspectionTab({
    required this.userName,
    this.firestoreOverride,
    this.currentUidOverride,
  });

  @override
  State<_NewDailyInspectionTab> createState() =>
      _NewDailyInspectionTabState();
}

class _NewDailyInspectionTabState extends State<_NewDailyInspectionTab> {
  DateTime _date = DateTime.now();
  final _driverNameController = TextEditingController();
  final _otherReportsController = TextEditingController();
  String? _vehicleNumber;
  String? _tireStatus;
  String? _cabinStatus;
  int _rating = 0;
  bool _saving = false;
  final _attachmentsKey = GlobalKey<_InspectionAttachmentsSectionState>();
  DocumentReference? _lastSavedRef;

  @override
  void dispose() {
    _driverNameController.dispose();
    _otherReportsController.dispose();
    super.dispose();
  }

  Future<void> _pickDate() async {
    final picked = await showDatePicker(
      context: context,
      initialDate: _date,
      firstDate: DateTime(2020),
      lastDate: DateTime.now().add(const Duration(days: 1)),
    );
    if (picked != null) setState(() => _date = picked);
  }

  Future<void> _pickVehicleNumber() async {
    final picked = await _showVehicleNumberPicker(context);
    if (picked != null) setState(() => _vehicleNumber = picked);
  }

  void _resetForm() {
    setState(() {
      _date = DateTime.now();
      _driverNameController.clear();
      _otherReportsController.clear();
      _vehicleNumber = null;
      _tireStatus = null;
      _cabinStatus = null;
      _rating = 0;
      _lastSavedRef = null;
    });
    _attachmentsKey.currentState?.clearAll();
  }

  Future<bool> _confirmOverwrite() async {
    final result = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Inspection already exists'),
        content: Text(
          'An inspection for $_vehicleNumber on '
          '${_vehicleInspectionYmd(_date)} already exists. '
          'Update it?',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('Cancel'),
          ),
          ElevatedButton(
            onPressed: () => Navigator.pop(dialogContext, true),
            child: const Text('Update'),
          ),
        ],
      ),
    );
    return result ?? false;
  }

  Future<void> _save() async {
    if (_driverNameController.text.trim().isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Please enter the driver name.')),
      );
      return;
    }
    if (_vehicleNumber == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Please select a vehicle number.')),
      );
      return;
    }
    if (_tireStatus == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Please select the tire inspection result.')),
      );
      return;
    }
    if (_cabinStatus == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Please select the cabin check result.')),
      );
      return;
    }
    if (_rating == 0) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Please select a condition rating.')),
      );
      return;
    }

    setState(() => _saving = true);
    try {
      final docId = '${_vehicleNumber}_${_vehicleInspectionYmd(_date)}';
      final ref = FirebaseFirestore.instance
          .collection('vehicle_inspections')
          .doc(docId);
      final existing = await ref.get();
      if (existing.exists) {
        final proceed = await _confirmOverwrite();
        if (!proceed) {
          setState(() => _saving = false);
          return;
        }
      }
      final existingData = existing.data();
      final currentUser = FirebaseAuth.instance.currentUser;
      final uid = currentUser?.uid ?? '';
      // Uploads whatever photos/voice notes aren't uploaded yet — never
      // throws on a failed item (see uploadAndFinalize's doc comment), so
      // the main doc save below always proceeds regardless.
      final storagePrefix = _inspectionStoragePathPrefix(
        type: 'daily',
        vehicleNumber: _vehicleNumber!,
        docId: docId,
      );
      final attachments = await _attachmentsKey.currentState!
          .uploadAndFinalize(storagePrefix);
      await ref.set({
        'type': 'daily',
        'date': _vehicleInspectionYmd(_date),
        'dateTs': Timestamp.fromDate(
          DateTime(_date.year, _date.month, _date.day),
        ),
        'driverName': _driverNameController.text.trim(),
        'vehicleNumber': _vehicleNumber,
        'tireStatus': _tireStatus,
        'cabinStatus': _cabinStatus,
        'otherReports': _otherReportsController.text.trim(),
        'rating': _rating,
        'month': _vehicleInspectionYm(_date),
        'photos': attachments.photos,
        'voices': attachments.voices,
        // Original submitter — never overwritten by a later edit, see
        // updatedBy/updatedByName/updatedAt below for that.
        'createdBy': existingData?['createdBy'] ?? uid,
        'createdByName': existingData?['createdByName'] ?? widget.userName,
        'createdByEmail':
            existingData?['createdByEmail'] ?? currentUser?.email,
        'createdAt': existingData?['createdAt'] ?? FieldValue.serverTimestamp(),
        'updatedBy': uid,
        'updatedByName': widget.userName,
        'updatedAt': FieldValue.serverTimestamp(),
      });
      _lastSavedRef = ref;
      if (mounted) {
        if (attachments.hadFailures) {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(
              content: Text(
                'Inspection saved, but some photos/voice notes failed to '
                'upload — use Retry below.',
              ),
            ),
          );
          // Form stays open (not reset) so the Retry banner stays visible.
        } else {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(content: Text('Inspection saved.')),
          );
          _resetForm();
        }
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Failed to save: $e')),
        );
      }
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }

  Widget _sectionLabel(String text) => Padding(
    padding: const EdgeInsets.only(bottom: 6),
    child: Text(text, style: const TextStyle(fontWeight: FontWeight.bold)),
  );

  @override
  Widget build(BuildContext context) {
    return SingleChildScrollView(
      padding: const EdgeInsets.all(16),
      child: ConstrainedBox(
        constraints: const BoxConstraints(maxWidth: 560),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            _sectionLabel('Date'),
            OutlinedButton.icon(
              onPressed: _pickDate,
              icon: const Icon(Icons.date_range),
              label: Text(_vehicleInspectionYmd(_date)),
            ),
            const SizedBox(height: 16),
            _sectionLabel('Driver Name'),
            TextField(
              controller: _driverNameController,
              inputFormatters: [UpperCaseTextFormatter()],
              textCapitalization: TextCapitalization.characters,
              decoration: InputDecoration(
                hintText: 'Enter driver name',
                border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(10),
                ),
              ),
            ),
            const SizedBox(height: 16),
            _sectionLabel('Vehicle Number'),
            InkWell(
              onTap: _pickVehicleNumber,
              child: InputDecorator(
                decoration: InputDecoration(
                  border: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(10),
                  ),
                  suffixIcon: const Icon(Icons.search),
                ),
                child: Text(_vehicleNumber ?? 'Select vehicle number'),
              ),
            ),
            const SizedBox(height: 16),
            _sectionLabel('Tire Inspection'),
            Wrap(
              spacing: 8,
              children: ['GOOD', 'BAD', 'REPLACE'].map((option) {
                return ChoiceChip(
                  label: Text(option),
                  selected: _tireStatus == option,
                  onSelected: (_) => setState(() => _tireStatus = option),
                );
              }).toList(),
            ),
            const SizedBox(height: 16),
            _sectionLabel('Cabin Check / Clean Check'),
            Wrap(
              spacing: 8,
              children: ['GOOD', 'BAD'].map((option) {
                return ChoiceChip(
                  label: Text(option),
                  selected: _cabinStatus == option,
                  onSelected: (_) => setState(() => _cabinStatus = option),
                );
              }).toList(),
            ),
            const SizedBox(height: 16),
            _sectionLabel('Other Reports (optional)'),
            TextField(
              controller: _otherReportsController,
              inputFormatters: [UpperCaseTextFormatter()],
              textCapitalization: TextCapitalization.characters,
              maxLines: 3,
              decoration: InputDecoration(
                hintText: 'Any other notes about this vehicle',
                border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(10),
                ),
              ),
            ),
            const SizedBox(height: 16),
            _sectionLabel('Vehicle Condition Rating'),
            _StarRatingSelector(
              rating: _rating,
              onChanged: (v) => setState(() => _rating = v),
            ),
            const SizedBox(height: 20),
            _InspectionAttachmentsSection(
              key: _attachmentsKey,
              onRetrySaved: (result) async {
                if (_lastSavedRef != null) {
                  await _lastSavedRef!.update({
                    'photos': result.photos,
                    'voices': result.voices,
                  });
                }
              },
            ),
            const SizedBox(height: 20),
            InspectionRepairsSection(
              userName: widget.userName,
              vehicleNumber: _vehicleNumber,
              inspectionId: _vehicleNumber == null
                  ? null
                  : '${_vehicleNumber}_${_vehicleInspectionYmd(_date)}',
              firestoreOverride: widget.firestoreOverride,
              currentUidOverride: widget.currentUidOverride,
            ),
            const SizedBox(height: 24),
            SizedBox(
              width: double.infinity,
              child: ElevatedButton(
                onPressed: _saving ? null : _save,
                style: ElevatedButton.styleFrom(
                  padding: const EdgeInsets.symmetric(vertical: 14),
                  backgroundColor: Colors.deepOrange[700],
                ),
                child: _saving
                    ? const SizedBox(
                        width: 20,
                        height: 20,
                        child: CircularProgressIndicator(
                          strokeWidth: 2,
                          color: Colors.white,
                        ),
                      )
                    : const Text(
                        'SAVE',
                        style: TextStyle(color: Colors.white),
                      ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

class _InspectionRecordsTab extends StatefulWidget {
  final String userName;
  final FirebaseFirestore? firestoreOverride;
  final String? currentUidOverride;
  const _InspectionRecordsTab({
    required this.userName,
    this.firestoreOverride,
    this.currentUidOverride,
  });

  @override
  State<_InspectionRecordsTab> createState() => _InspectionRecordsTabState();
}

class _InspectionRecordsTabState extends State<_InspectionRecordsTab> {
  DateTimeRange? _dateRange;
  bool _allTime = false;
  final _searchController = TextEditingController();
  String _searchText = '';
  String? _vehicleFilter;
  int _pageSize = 25;
  int _page = 0;
  String _filterSig = '';

  String? _streamKey;
  Stream<QuerySnapshot>? _cachedStream;

  String get _defaultWindowStart => _vehicleInspectionYmd(
    DateTime.now().subtract(const Duration(days: 30)),
  );

  // Memoized by date-range key only — typing in the search box or picking
  // the vehicle filter dropdown never resubscribes this stream (same
  // reasoning as ManagementSiteReportsScreen's _workRecordsStream).
  Stream<QuerySnapshot> get _recordsStream {
    String? start;
    String? end;
    if (_dateRange != null) {
      start = _vehicleInspectionYmd(_dateRange!.start);
      end = _vehicleInspectionYmd(_dateRange!.end);
    } else if (!_allTime) {
      start = _defaultWindowStart;
    }
    final key = '$start|$end';
    if (_cachedStream == null || key != _streamKey) {
      _streamKey = key;
      Query q = FirebaseFirestore.instance.collection('vehicle_inspections');
      if (start != null) {
        q = q.where('date', isGreaterThanOrEqualTo: start);
      }
      if (end != null) {
        q = q.where('date', isLessThanOrEqualTo: end);
      }
      _cachedStream = q.snapshots();
    }
    return _cachedStream!;
  }

  @override
  void dispose() {
    _searchController.dispose();
    super.dispose();
  }

  Future<void> _pickDateRange() async {
    final picked = await showDateRangePicker(
      context: context,
      firstDate: DateTime(2020),
      lastDate: DateTime.now().add(const Duration(days: 1)),
      initialDateRange: _dateRange,
    );
    if (picked != null) {
      setState(() {
        _dateRange = picked;
        _allTime = false;
      });
    }
  }

  Future<void> _delete(String docId) async {
    await FirebaseFirestore.instance
        .collection('vehicle_inspections')
        .doc(docId)
        .delete();
  }

  void _showDetailDialog(Map<String, dynamic> data, String docId) {
    final rating = (data['rating'] as num?)?.toInt() ?? 0;
    showDialog(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: Text(
          '${data['vehicleNumber'] ?? ''} — ${data['date'] ?? ''}',
        ),
        content: SingleChildScrollView(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            mainAxisSize: MainAxisSize.min,
            children: [
              Text('Driver: ${data['driverName'] ?? '—'}'),
              Text('Tire Inspection: ${data['tireStatus'] ?? '—'}'),
              Text('Cabin Check: ${data['cabinStatus'] ?? '—'}'),
              const SizedBox(height: 4),
              const Text(
                'Vehicle Condition Rating',
                style: TextStyle(fontWeight: FontWeight.bold),
              ),
              _StarRatingSelector(rating: rating, size: 20),
              if ((data['otherReports'] ?? '').toString().isNotEmpty) ...[
                const SizedBox(height: 8),
                Text('Other Reports: ${data['otherReports']}'),
              ],
              const Divider(height: 20),
              _InspectionAttachmentsViewer(
                photos:
                    (data['photos'] as List?)?.cast<Map<String, dynamic>>() ??
                    const [],
                voices:
                    (data['voices'] as List?)?.cast<Map<String, dynamic>>() ??
                    const [],
              ),
              const Divider(height: 20),
              Text(
                'Submitted by: ${data['createdByName'] ?? '—'} '
                'at ${_formatInspectionDateTime(data['createdAt'])}',
                style: const TextStyle(fontSize: 12),
              ),
              if (data['updatedByName'] != null)
                Text(
                  'Last updated by: ${data['updatedByName']} '
                  'at ${_formatInspectionDateTime(data['updatedAt'])}',
                  style: const TextStyle(fontSize: 12),
                ),
              const Divider(height: 20),
              InspectionRepairsSection(
                userName: widget.userName,
                vehicleNumber: (data['vehicleNumber'] ?? '').toString(),
                inspectionId: docId,
                firestoreOverride: widget.firestoreOverride,
                currentUidOverride: widget.currentUidOverride,
              ),
            ],
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext),
            child: const Text('Close'),
          ),
        ],
      ),
    );
  }

  Future<void> _showEditDialog(QueryDocumentSnapshot doc) async {
    final data = doc.data() as Map<String, dynamic>;
    final driverNameController = TextEditingController(
      text: (data['driverName'] ?? '').toString(),
    );
    final otherReportsController = TextEditingController(
      text: (data['otherReports'] ?? '').toString(),
    );
    String? tireStatus = data['tireStatus'] as String?;
    String? cabinStatus = data['cabinStatus'] as String?;
    int rating = (data['rating'] as num?)?.toInt() ?? 0;
    final attachmentsKey = GlobalKey<_InspectionAttachmentsSectionState>();
    final initialPhotos =
        (data['photos'] as List?)?.cast<Map<String, dynamic>>() ?? const [];
    final initialVoices =
        (data['voices'] as List?)?.cast<Map<String, dynamic>>() ?? const [];

    await showDialog(
      context: context,
      builder: (dialogContext) => StatefulBuilder(
        builder: (dialogContext, setDialogState) => AlertDialog(
          title: Text(
            'Edit Inspection — ${data['vehicleNumber'] ?? ''} '
            '(${data['date'] ?? ''})',
          ),
          content: SingleChildScrollView(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              mainAxisSize: MainAxisSize.min,
              children: [
                TextField(
                  controller: driverNameController,
                  inputFormatters: [UpperCaseTextFormatter()],
                  textCapitalization: TextCapitalization.characters,
                  decoration: const InputDecoration(labelText: 'Driver Name'),
                ),
                const SizedBox(height: 12),
                const Text(
                  'Tire Inspection',
                  style: TextStyle(fontWeight: FontWeight.bold),
                ),
                Wrap(
                  spacing: 8,
                  children: ['GOOD', 'BAD', 'REPLACE'].map((option) {
                    return ChoiceChip(
                      label: Text(option),
                      selected: tireStatus == option,
                      onSelected: (_) =>
                          setDialogState(() => tireStatus = option),
                    );
                  }).toList(),
                ),
                const SizedBox(height: 12),
                const Text(
                  'Cabin Check',
                  style: TextStyle(fontWeight: FontWeight.bold),
                ),
                Wrap(
                  spacing: 8,
                  children: ['GOOD', 'BAD'].map((option) {
                    return ChoiceChip(
                      label: Text(option),
                      selected: cabinStatus == option,
                      onSelected: (_) =>
                          setDialogState(() => cabinStatus = option),
                    );
                  }).toList(),
                ),
                const SizedBox(height: 12),
                TextField(
                  controller: otherReportsController,
                  inputFormatters: [UpperCaseTextFormatter()],
                  textCapitalization: TextCapitalization.characters,
                  maxLines: 3,
                  decoration: const InputDecoration(
                    labelText: 'Other Reports',
                  ),
                ),
                const SizedBox(height: 12),
                const Text(
                  'Vehicle Condition Rating',
                  style: TextStyle(fontWeight: FontWeight.bold),
                ),
                _StarRatingSelector(
                  rating: rating,
                  onChanged: (v) => setDialogState(() => rating = v),
                ),
                const SizedBox(height: 12),
                _InspectionAttachmentsSection(
                  key: attachmentsKey,
                  initialPhotos: initialPhotos,
                  initialVoices: initialVoices,
                  onRetrySaved: (result) => doc.reference.update({
                    'photos': result.photos,
                    'voices': result.voices,
                  }),
                ),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dialogContext),
              child: const Text('Cancel'),
            ),
            ElevatedButton(
              onPressed: () async {
                final storagePrefix = _inspectionStoragePathPrefix(
                  type: 'daily',
                  vehicleNumber: (data['vehicleNumber'] ?? '').toString(),
                  docId: doc.id,
                );
                final attachments = await attachmentsKey.currentState!
                    .uploadAndFinalize(storagePrefix);
                await doc.reference.update({
                  'driverName': driverNameController.text.trim(),
                  'tireStatus': tireStatus,
                  'cabinStatus': cabinStatus,
                  'otherReports': otherReportsController.text.trim(),
                  'rating': rating,
                  'photos': attachments.photos,
                  'voices': attachments.voices,
                  // createdBy/createdByName stay untouched — the original
                  // submitter — only these change on an edit.
                  'updatedBy': FirebaseAuth.instance.currentUser?.uid ?? '',
                  'updatedByName': widget.userName,
                  'updatedAt': FieldValue.serverTimestamp(),
                });
                if (dialogContext.mounted) Navigator.pop(dialogContext);
              },
              child: const Text('SAVE'),
            ),
          ],
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        Padding(
          padding: const EdgeInsets.all(12),
          child: Wrap(
            spacing: 12,
            runSpacing: 12,
            crossAxisAlignment: WrapCrossAlignment.center,
            children: [
              SizedBox(
                width: 230,
                height: 48,
                child: OutlinedButton.icon(
                  onPressed: _pickDateRange,
                  icon: const Icon(Icons.date_range),
                  label: Text(
                    _dateRange == null
                        ? (_allTime ? 'All Time' : 'Last 30 Days')
                        : '${_vehicleInspectionYmd(_dateRange!.start)} - '
                              '${_vehicleInspectionYmd(_dateRange!.end)}',
                    overflow: TextOverflow.ellipsis,
                  ),
                ),
              ),
              SizedBox(
                height: 48,
                child: FilterChip(
                  label: const Text('All Time'),
                  selected: _allTime,
                  onSelected: (val) => setState(() {
                    _allTime = val;
                    if (val) _dateRange = null;
                  }),
                ),
              ),
              SizedBox(
                width: 220,
                height: 48,
                child: TextField(
                  controller: _searchController,
                  inputFormatters: [UpperCaseTextFormatter()],
                  textCapitalization: TextCapitalization.characters,
                  decoration: InputDecoration(
                    hintText: 'Search vehicle number',
                    isDense: true,
                    prefixIcon: const Icon(Icons.search),
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(10),
                    ),
                  ),
                  onChanged: (val) => setState(() => _searchText = val),
                ),
              ),
            ],
          ),
        ),
        Expanded(
          child: StreamBuilder<QuerySnapshot>(
            stream: _recordsStream,
            builder: (context, snapshot) {
              if (snapshot.connectionState == ConnectionState.waiting &&
                  !snapshot.hasData) {
                return const Center(child: CircularProgressIndicator());
              }
              // Server-side query is date-range only (see _recordsStream's
              // doc comment on why) — this collection now also holds Weekly
              // docs (same date-range shape), so 'type' is filtered here,
              // client-side, rather than adding a second where() that would
              // need a composite index.
              final docs = (snapshot.data?.docs ?? [])
                  .where(
                    (doc) =>
                        (doc.data() as Map<String, dynamic>)['type'] ==
                        'daily',
                  )
                  .toList();
              final vehicleOptions =
                  docs
                      .map((d) => (d.data() as Map<String, dynamic>)['vehicleNumber'])
                      .whereType<String>()
                      .toSet()
                      .toList()
                    ..sort();

              final trimmedSearch = _searchText.trim().toLowerCase();
              final filtered = docs.where((doc) {
                final data = doc.data() as Map<String, dynamic>;
                final vehicleNumber = (data['vehicleNumber'] ?? '')
                    .toString();
                if (_vehicleFilter != null &&
                    vehicleNumber != _vehicleFilter) {
                  return false;
                }
                if (trimmedSearch.isEmpty) return true;
                return vehicleNumber.toLowerCase().contains(trimmedSearch);
              }).toList()
                ..sort((a, b) {
                  final ad = (a.data() as Map<String, dynamic>)['date'] ?? '';
                  final bd = (b.data() as Map<String, dynamic>)['date'] ?? '';
                  return bd.toString().compareTo(ad.toString());
                });

              if (filtered.isEmpty) {
                return Center(
                  child: Text(
                    docs.isEmpty
                        ? 'No inspections recorded for this period.'
                        : 'No matching inspections.',
                  ),
                );
              }

              final sig = '$_searchText|$_vehicleFilter|$_pageSize';
              if (sig != _filterSig) {
                _filterSig = sig;
                _page = 0;
              }
              final totalPages = (filtered.length + _pageSize - 1) ~/ _pageSize;
              if (_page >= totalPages) _page = totalPages - 1;
              if (_page < 0) _page = 0;
              final pageStart = _page * _pageSize;
              final pageEnd = (pageStart + _pageSize) > filtered.length
                  ? filtered.length
                  : pageStart + _pageSize;
              final pageDocs = filtered.sublist(pageStart, pageEnd);

              return Column(
                children: [
                  if (vehicleOptions.isNotEmpty)
                    Padding(
                      padding: const EdgeInsets.fromLTRB(12, 0, 12, 8),
                      child: Align(
                        alignment: Alignment.centerLeft,
                        child: SizedBox(
                          width: 220,
                          child: DropdownButtonFormField<String>(
                            initialValue: _vehicleFilter,
                            isExpanded: true,
                            decoration: InputDecoration(
                              labelText: 'Filter by Vehicle',
                              isDense: true,
                              border: OutlineInputBorder(
                                borderRadius: BorderRadius.circular(10),
                              ),
                            ),
                            items: [
                              const DropdownMenuItem<String>(
                                value: null,
                                child: Text('All Vehicles'),
                              ),
                              ...vehicleOptions.map(
                                (v) => DropdownMenuItem<String>(
                                  value: v,
                                  child: Text(v),
                                ),
                              ),
                            ],
                            onChanged: (val) =>
                                setState(() => _vehicleFilter = val),
                          ),
                        ),
                      ),
                    ),
                  Expanded(
                    child: ListView.builder(
                      padding: const EdgeInsets.all(12),
                      itemCount: pageDocs.length,
                      itemBuilder: (context, index) {
                        final doc = pageDocs[index];
                        final data = doc.data() as Map<String, dynamic>;
                        final rating = (data['rating'] as num?)?.toInt() ?? 0;
                        final photoCount =
                            (data['photos'] as List?)?.length ?? 0;
                        final voiceCount =
                            (data['voices'] as List?)?.length ?? 0;
                        return _WebStaggeredFadeIn(
                          index: index,
                          child: _WebHoverCard(
                            child: Card(
                              margin: const EdgeInsets.only(bottom: 10),
                              child: ListTile(
                                leading: CircleAvatar(
                                  backgroundColor: Colors.deepOrange
                                      .withOpacity(0.15),
                                  child: const Icon(
                                    Icons.fact_check,
                                    color: Colors.deepOrange,
                                  ),
                                ),
                                onTap: () => _showDetailDialog(data, doc.id),
                                title: Text(
                                  '${data['vehicleNumber'] ?? ''} — '
                                  '${data['date'] ?? ''}',
                                ),
                                subtitle: Column(
