  Widget _closeJobBlock(String? invoiceId, String paymentStatus, bool canManage) {
    if (!canManage) return const SizedBox.shrink();
    return FutureBuilder<Map<String, dynamic>?>(
      future: invoiceId == null
          ? Future.value(null)
          : FirebaseFirestore.instance
              .collection('repair_invoices')
              .doc(invoiceId)
              .get()
              .then((s) => s.data()),
      builder: (context, invSnap) {
        final invData = invSnap.data;
        final vStatus =
            ((invData?['verification'] as Map<String, dynamic>?)?['status'] ?? '').toString();
        final canClose = canCloseRepairJob(
          invoiceVerificationStatus: vStatus,
          paymentStatus: paymentStatus,
        );
        return Padding(
          padding: const EdgeInsets.only(top: AppSpacing.md),
          child: SizedBox(
            width: double.infinity,
            child: ElevatedButton(
              onPressed: (canClose && !_closing) ? _closeJob : null,
              style: ElevatedButton.styleFrom(backgroundColor: AppColors.success),
              child: _closing
                  ? const SizedBox(
                      width: 20,
                      height: 20,
                      child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white),
                    )
                  : const Text('CLOSE JOB'),
            ),
          ),
        );
      },
    );
  }

  void _initFormFromData(Map<String, dynamic> data) {
    if (_formInitialized) return;
    _formInitialized = true;
    _confirmedDiagnosisController.text = (data['confirmedDiagnosis'] ?? '').toString();
    _rootCauseController.text = (data['rootCause'] ?? '').toString();
    _recommendedRepairController.text = (data['recommendedRepair'] ?? '').toString();
    _priority = data['priority'] as String?;
    _safetyAssessment = data['safetyAssessment'] as String?;
    final parts = (data['partsList'] as List?) ?? const [];
    for (final part in parts) {
      final p = part as Map<String, dynamic>;
      _partRows.add(
        _PartRow(
          name: (p['name'] ?? '').toString(),
          qty: (p['qty'] ?? '').toString(),
          notes: (p['notes'] ?? '').toString(),
        ),
      );
    }
  }

  void _addPartRow() => setState(() => _partRows.add(_PartRow()));

  void _removePartRow(int index) => setState(() {
    _partRows[index].dispose();
    _partRows.removeAt(index);
  });

  Future<void> _saveDiagnosis(Map<String, dynamic> jobData) async {
    if (_confirmedDiagnosisController.text.trim().isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Please enter the confirmed diagnosis.')),
      );
      return;
    }
    if (_safetyAssessment == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Please select a safety assessment.')),
      );
      return;
    }
    final confirmed = await showAppConfirmDialog(
      context: context,
      title: 'Save Diagnosis?',
      message:
          'This marks the repair job as DIAGNOSED and records the parts '
          'list, root cause and safety assessment.',
      confirmLabel: 'Save',
    );
    if (!confirmed) return;

    setState(() => _saving = true);
    try {
      final uid = FirebaseAuth.instance.currentUser?.uid ?? '';
      final userDoc = await FirebaseFirestore.instance
          .collection('users')
          .doc(uid)
          .get();
      final userName = (userDoc.data()?['name'] ?? 'Unknown').toString();
      final wasDiagnosed = jobData['repairStatus'] == 'DIAGNOSED' ||
          kRepairStageOrder.indexOf((jobData['repairStatus'] ?? '').toString()) >
              kRepairStageOrder.indexOf('DIAGNOSED');

      final partsList = _partRows
          .where((r) => r.nameController.text.trim().isNotEmpty)
          .map(
            (r) => {
              'name': r.nameController.text.trim(),
              'qty': r.qtyController.text.trim(),
              'notes': r.notesController.text.trim(),
            },
          )
          .toList();

      await _ref.update({
        'confirmedDiagnosis': _confirmedDiagnosisController.text.trim(),
        'rootCause': _rootCauseController.text.trim(),
        'recommendedRepair': _recommendedRepairController.text.trim(),
        'priority': _priority ?? jobData['priority'],
        'safetyAssessment': _safetyAssessment,
        'partsList': partsList,
        'mechanicalSupervisorId': uid,
        'mechanicalSupervisorName': userName,
        if (!wasDiagnosed) 'repairStatus': 'DIAGNOSED',
        if (!wasDiagnosed) 'diagnosedAt': FieldValue.serverTimestamp(),
        'updatedBy': uid,
        'updatedByName': userName,
        'updatedAt': FieldValue.serverTimestamp(),
      });
      await _writeRepairEvent(
        collection: 'repair_jobs',
        docId: widget.jobId,
        action: wasDiagnosed ? 'DIAGNOSIS_UPDATED' : 'DIAGNOSED',
        summary: wasDiagnosed
            ? 'Diagnosis updated by $userName'
            : 'Diagnosis saved by $userName',
        actorUid: uid,
        actorName: userName,
      );
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Diagnosis saved.')),
        );
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Failed to save diagnosis: $e')),
        );
      }
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }

  Widget _linkedDefects(List<dynamic> defectIds) {
    if (defectIds.isEmpty) {
      return Text('No linked defects.', style: AppText.caption);
    }
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: defectIds.map((defectId) {
        return FutureBuilder<DocumentSnapshot>(
          future: FirebaseFirestore.instance
              .collection('defect_reports')
              .doc(defectId.toString())
              .get(),
          builder: (context, snap) {
            if (!snap.hasData) {
              return const Padding(
                padding: EdgeInsets.symmetric(vertical: 4),
                child: LinearProgressIndicator(),
              );
            }
            if (!snap.data!.exists) return const SizedBox.shrink();
            final d = snap.data!.data() as Map<String, dynamic>;
            return Padding(
              padding: const EdgeInsets.only(bottom: 6),
              child: InkWell(
                onTap: () => pushWebAware(
                  context,
                  DefectDetailScreen(defectId: defectId.toString()),
                ),
                child: Row(
                  children: [
                    Expanded(
                      child: Text(
                        '${d['defectNo'] ?? ''} — ${d['systemCategory'] ?? ''}: '
                        '${d['symptoms'] ?? ''}',
                        style: AppText.body,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                      ),
                    ),
                    const Icon(Icons.chevron_right, size: 18),
                  ],
                ),
              ),
            );
          },
        );
      }).toList(),
    );
  }

  @override
  Widget build(BuildContext context) {
    return TruckRepairScaffold(
      appBar: AppBar(
        title: const Text('Repair Job Detail'),
        backgroundColor: AppColors.navy,
        foregroundColor: Colors.white,
      ),
      body: StreamBuilder<DocumentSnapshot>(
        stream: _ref.snapshots(),
        builder: (context, snapshot) {
          if (snapshot.hasError) {
            return ErrorState(
              message: 'Failed to load repair job: ${snapshot.error}',
              onRetry: () => setState(() {}),
            );
          }
          if (!snapshot.hasData) return const LoadingState();
          if (!snapshot.data!.exists) {
            return const EmptyState(
              icon: Icons.error_outline,
              title: 'This repair job no longer exists.',
            );
          }
          final data = snapshot.data!.data() as Map<String, dynamic>;
          _initFormFromData(data);
          _initPartsUsedFromData(data);
          final repairStatus = (data['repairStatus'] ?? 'OPEN').toString();
          final defectIds = (data['defectIds'] as List?) ?? const [];
          final isClosed = repairStatus == 'CLOSED';

          return SingleChildScrollView(
            child: Align(
              alignment: Alignment.topCenter,
              child: ConstrainedBox(
                constraints: const BoxConstraints(maxWidth: 640),
                child: Padding(
                  padding: const EdgeInsets.all(AppSpacing.lg),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        '${data['jobNo'] ?? ''} — ${data['vehicleNumber'] ?? ''}',
                        style: AppText.title,
                      ),
                      const SizedBox(height: AppSpacing.sm),
                      Wrap(
                        spacing: 8,
                        runSpacing: 8,
                        children: [
                          StatusChip(status: (data['priority'] ?? '').toString()),
                          StatusChip(status: repairStatus),
                          StatusChip(
                            status: (data['paymentStatus'] ?? '').toString(),
                          ),
                        ],
                      ),
                      const SizedBox(height: AppSpacing.lg),
                      _RepairStageProgress(currentStage: repairStatus),
                      const SizedBox(height: AppSpacing.lg),
                      _NextStepCard(jobId: widget.jobId, jobData: data),
                      const SizedBox(height: AppSpacing.lg),
                      const SectionHeader(title: 'Linked Defects'),
                      const SizedBox(height: AppSpacing.sm),
                      AppCard(child: _linkedDefects(defectIds)),
                      const SizedBox(height: AppSpacing.lg),
                      FutureBuilder<bool>(
                        future: _canEditFuture,
                        builder: (context, canEditSnap) {
                          final canEdit = canEditSnap.data == true && !isClosed;
                          return AppCard(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Text(
                                  'Mechanical Diagnosis',
                                  style: AppText.section,
                                ),
                                const SizedBox(height: AppSpacing.sm),
                                TextField(
                                  controller: _confirmedDiagnosisController,
                                  enabled: canEdit,
                                  inputFormatters: [UpperCaseTextFormatter()],
                                  textCapitalization:
                                      TextCapitalization.characters,
                                  maxLines: 3,
                                  decoration: const InputDecoration(
                                    labelText: 'Confirmed Diagnosis',
                                  ),
                                ),
                                const SizedBox(height: AppSpacing.sm),
                                TextField(
                                  controller: _rootCauseController,
                                  enabled: canEdit,
                                  inputFormatters: [UpperCaseTextFormatter()],
                                  textCapitalization:
                                      TextCapitalization.characters,
                                  maxLines: 2,
                                  decoration: const InputDecoration(
                                    labelText: 'Root Cause',
                                  ),
                                ),
                                const SizedBox(height: AppSpacing.sm),
                                TextField(
                                  controller: _recommendedRepairController,
                                  enabled: canEdit,
                                  inputFormatters: [UpperCaseTextFormatter()],
                                  textCapitalization:
                                      TextCapitalization.characters,
                                  maxLines: 2,
                                  decoration: const InputDecoration(
                                    labelText: 'Recommended Repair',
                                  ),
                                ),
                                const SizedBox(height: AppSpacing.md),
                                Text('Priority', style: AppText.caption),
                                Wrap(
                                  spacing: 8,
                                  children: kRepairPriorities.map((p) {
                                    return ChoiceChip(
                                      label: Text(p),
                                      selected: _priority == p,
                                      onSelected: canEdit
                                          ? (_) => setState(() => _priority = p)
                                          : null,
                                    );
                                  }).toList(),
                                ),
                                const SizedBox(height: AppSpacing.md),
                                Text('Safety Assessment', style: AppText.caption),
                                Wrap(
                                  spacing: 8,
                                  children: kSafetyAssessments.map((s) {
                                    return ChoiceChip(
