                      _repairExecutionSection(data, repairStatus),
                      const SizedBox(height: AppSpacing.lg),
                      const SectionHeader(title: 'Timeline'),
                      const SizedBox(height: AppSpacing.sm),
                      _RepairEventTimeline(
                        collection: 'repair_jobs',
                        docId: widget.jobId,
                      ),
                    ],
