  Widget _approvalStatusCard() {
    return StreamBuilder<QuerySnapshot>(
      stream: FirebaseFirestore.instance
          .collection('repair_approvals')
          .where('repairJobId', isEqualTo: widget.jobId)
          .snapshots(),
      builder: (context, snapshot) {
        final docs = snapshot.data?.docs ?? [];
        if (docs.isEmpty) return const SizedBox.shrink();
        final sorted = [...docs]..sort((a, b) {
          final ac = ((a.data() as Map<String, dynamic>)['requestedAt'] as Timestamp?)
                  ?.millisecondsSinceEpoch ??
              0;
          final bc = ((b.data() as Map<String, dynamic>)['requestedAt'] as Timestamp?)
                  ?.millisecondsSinceEpoch ??
              0;
          return bc.compareTo(ac);
        });
        final data = sorted.first.data() as Map<String, dynamic>;
        final decision = (data['decision'] ?? 'PENDING').toString();
        final amountCents = (data['amountCents'] as num?)?.toInt() ?? 0;
        return Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const SizedBox(height: AppSpacing.lg),
            const SectionHeader(title: 'Approval'),
            const SizedBox(height: AppSpacing.sm),
            AppCard(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    children: [
                      Expanded(
                        child: Text(
                          '${data['approvalNo'] ?? ''} — '
                          '${_formatMoney(_centsToMoney(amountCents))}',
                          style: AppText.section,
                        ),
                      ),
                      StatusChip(status: decision),
                    ],
                  ),
                  Text(
                    'Requires: ${data['requiredLevel'] ?? ''}',
                    style: AppText.caption,
                  ),
                  if (decision != 'PENDING') ...[
                    const SizedBox(height: 4),
                    Text(
                      'Decided by ${data['decidedByName'] ?? ''} on '
                      '${_repairFormatDateTime(data['decidedAt'])}',
                      style: AppText.caption,
                    ),
                    if (decision == 'REJECTED' && data['rejectReason'] != null)
                      Text(
                        'Reason: ${data['rejectReason']}',
                        style: AppText.caption.copyWith(color: AppColors.danger),
                      ),
                  ],
                ],
              ),
            ),
          ],
        );
      },
    );
  }
}

// ---------------- VEHICLE REPAIR HISTORY ----------------
class VehicleRepairHistoryScreen extends StatefulWidget {
  final String? prefillVehicleNumber;
  const VehicleRepairHistoryScreen({super.key, this.prefillVehicleNumber});

  @override
  State<VehicleRepairHistoryScreen> createState() =>
      _VehicleRepairHistoryScreenState();
}

class _VehicleRepairHistoryScreenState
    extends State<VehicleRepairHistoryScreen> {
  String? _vehicleNumber;
  String? _categoryFilter;
  final _searchController = TextEditingController();
  String _searchText = '';

  // Memoized by vehicle number only — typing in the search box or tapping a
  // category chip calls setState() on every keystroke/tap, and without this
  // cache that would recreate all five .snapshots() calls below on every
  // rebuild, resetting every nested StreamBuilder back to
  // ConnectionState.waiting (same root cause as the Approval Detail
  // "stuck on loading" bug: a stream/future recreated every build never
  // gets a chance to settle). Same pattern as _InspectionRecordsTabState's
  // _recordsStream.
  String? _streamsKey;
  Stream<QuerySnapshot>? _defectStream;
  Stream<QuerySnapshot>? _jobStream;
  Stream<QuerySnapshot>? _quotationStream;
  Stream<QuerySnapshot>? _approvalStream;
  Stream<QuerySnapshot>? _invoiceStream;

  static const _loadTimeout = Duration(seconds: 15);

  void _ensureStreams() {
    if (_streamsKey == _vehicleNumber) return;
    _streamsKey = _vehicleNumber;
    final v = _vehicleNumber;
    if (v == null) {
      _defectStream = null;
      _jobStream = null;
      _quotationStream = null;
      _approvalStream = null;
      _invoiceStream = null;
      return;
    }
    Stream<QuerySnapshot> timed(String collection, Stream<QuerySnapshot> s) =>
        s.timeout(
          _loadTimeout,
          onTimeout: (sink) {
            debugPrint(
              'VehicleRepairHistoryScreen: $collection for $v produced no '
              'snapshot within $_loadTimeout',
            );
            sink.addError(TimeoutException('Taking too long to load $collection.'));
          },
        );
    _defectStream = timed(
      'defect_reports',
      FirebaseFirestore.instance
          .collection('defect_reports')
          .where('vehicleNumber', isEqualTo: v)
          .snapshots(),
    );
    _jobStream = timed(
      'repair_jobs',
      FirebaseFirestore.instance
          .collection('repair_jobs')
          .where('vehicleNumber', isEqualTo: v)
          .snapshots(),
    );
    _quotationStream = timed(
      'repair_quotations',
      FirebaseFirestore.instance
          .collection('repair_quotations')
          .where('vehicleNumber', isEqualTo: v)
          .snapshots(),
    );
    _approvalStream = timed(
      'repair_approvals',
      FirebaseFirestore.instance
          .collection('repair_approvals')
          .where('vehicleNumber', isEqualTo: v)
          .snapshots(),
    );
    _invoiceStream = timed(
      'repair_invoices',
      FirebaseFirestore.instance
          .collection('repair_invoices')
          .where('vehicleNumber', isEqualTo: v)
          .snapshots(),
    );
  }

  @override
  void initState() {
    super.initState();
    _vehicleNumber = widget.prefillVehicleNumber;
  }

  @override
  void dispose() {
    _searchController.dispose();
    super.dispose();
  }

  Future<void> _pickVehicleNumber() async {
    final picked = await _showVehicleNumberPicker(context);
    if (picked != null) {
      setState(() {
        _vehicleNumber = picked;
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    _ensureStreams();
    return FutureBuilder<bool>(
      future: _currentUserHasRepairPerm(kPermHistoryView),
      builder: (context, permSnap) {
        if (permSnap.connectionState != ConnectionState.done) {
          return const TruckRepairScaffold(body: LoadingState());
        }
        if (permSnap.data != true) {
          return const TruckRepairScaffold(
            body: EmptyState(
              icon: Icons.lock_outline,
              title: 'NO ACCESS',
              hint: 'ASK THE ADMIN TO GRANT THIS TRUCK REPAIR PERMISSION',
            ),
          );
        }
        return TruckRepairScaffold(
      appBar: AppBar(
        title: const Text('Vehicle Repair History'),
        backgroundColor: AppColors.navy,
        foregroundColor: Colors.white,
      ),
      body: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          OutlinedButton.icon(
            onPressed: _pickVehicleNumber,
            icon: const Icon(Icons.search),
            label: Text(_vehicleNumber ?? 'Select vehicle number'),
          ),
          const SizedBox(height: AppSpacing.md),
          if (_vehicleNumber != null) ...[
            SizedBox(
              width: double.infinity,
              child: TextField(
                controller: _searchController,
                inputFormatters: [UpperCaseTextFormatter()],
                textCapitalization: TextCapitalization.characters,
                decoration: const InputDecoration(
                  hintText: 'Search description / job no. / defect no.',
                  prefixIcon: Icon(Icons.search),
                ),
                onChanged: (val) => setState(() => _searchText = val),
              ),
            ),
            const SizedBox(height: AppSpacing.sm),
            Wrap(
              spacing: 8,
              runSpacing: 8,
              children: [
                ChoiceChip(
                  label: const Text('ALL'),
                  selected: _categoryFilter == null,
                  onSelected: (_) => setState(() => _categoryFilter = null),
                ),
                ...kDefectSystemCategories.map(
                  (c) => ChoiceChip(
                    label: Text(c),
                    selected: _categoryFilter == c,
                    onSelected: (_) => setState(
                      () => _categoryFilter = _categoryFilter == c ? null : c,
                    ),
                  ),
                ),
              ],
            ),
            const SizedBox(height: AppSpacing.md),
          ],
          if (_vehicleNumber == null)
            const Expanded(
              child: EmptyState(
                icon: Icons.local_shipping,
                title: 'Select a vehicle to see its repair history.',
              ),
            )
          else
            Expanded(
              child: StreamBuilder<QuerySnapshot>(
                stream: _defectStream,
                builder: (context, defectSnap) {
                  return StreamBuilder<QuerySnapshot>(
                    stream: _jobStream,
                    builder: (context, jobSnap) {
                      return StreamBuilder<QuerySnapshot>(
                        stream: _quotationStream,
                        builder: (context, quotationSnap) {
                          return StreamBuilder<QuerySnapshot>(
                            stream: _approvalStream,
                            builder: (context, approvalSnap) {
                              return StreamBuilder<QuerySnapshot>(
                                stream: _invoiceStream,
                                builder: (context, invoiceSnap) {
                              final firstError = defectSnap.error ??
                                  jobSnap.error ??
                                  quotationSnap.error ??
                                  approvalSnap.error ??
                                  invoiceSnap.error;
                              if (firstError != null) {
                                debugPrint(
                                  'VehicleRepairHistoryScreen: load error for '
                                  '$_vehicleNumber: $firstError',
                                );
                                return ErrorState(
                                  message: firstError is TimeoutException
                                      ? 'Taking too long — RETRY'
                                      : 'Failed to load history: $firstError',
                                  onRetry: () => setState(() {}),
                                );
                              }
                              final stillWaiting = [
                                defectSnap,
                                jobSnap,
                                quotationSnap,
                                approvalSnap,
                                invoiceSnap,
                              ].any(
                                (s) => !s.hasData && s.connectionState == ConnectionState.waiting,
                              );
                              if (stillWaiting) {
                                return const LoadingState();
                              }

                              final invoiceByJob = <String, Map<String, dynamic>>{};
                              for (final doc in invoiceSnap.data?.docs ?? []) {
                                final d = doc.data() as Map<String, dynamic>;
                                final jobId = (d['repairJobId'] ?? '').toString();
                                if (jobId.isEmpty) continue;
                                invoiceByJob[jobId] = d;
                              }

                              final quotationsByJob = <String, Map<String, dynamic>>{};
                              for (final doc in quotationSnap.data?.docs ?? []) {
                                final d = doc.data() as Map<String, dynamic>;
                                final jobId = (d['repairJobId'] ?? '').toString();
                                if (jobId.isEmpty) continue;
                                quotationsByJob[doc.id] = d;
                                quotationsByJob['job:$jobId'] = d;
                              }
                              final latestApprovalByJob = <String, Map<String, dynamic>>{};
                              for (final doc in approvalSnap.data?.docs ?? []) {
                                final d = doc.data() as Map<String, dynamic>;
                                final jobId = (d['repairJobId'] ?? '').toString();
                                if (jobId.isEmpty) continue;
                                final existing = latestApprovalByJob[jobId];
                                final existingAt = (existing?['requestedAt'] as Timestamp?)
                                        ?.millisecondsSinceEpoch ??
                                    0;
                                final thisAt = (d['requestedAt'] as Timestamp?)
                                        ?.millisecondsSinceEpoch ??
                                    0;
                                if (existing == null || thisAt >= existingAt) {
                                  latestApprovalByJob[jobId] = d;
                                }
                              }

                              final items = <({
                                Timestamp? at,
                                String label,
                                String status,
                                String summary,
                                String? extra,
                                String category,
                                VoidCallback onTap,
                              })>[];
                              for (final doc in defectSnap.data?.docs ?? []) {
                                final d = doc.data() as Map<String, dynamic>;
                                items.add((
                                  at: d['reportedAt'] as Timestamp?,
                                  label: (d['defectNo'] ?? '').toString(),
                                  status: (d['status'] ?? '').toString(),
                                  summary: (d['symptoms'] ?? '').toString(),
                                  extra: null,
                                  category: (d['systemCategory'] ?? '').toString(),
                                  onTap: () => pushWebAware(
                                    context,
                                    DefectDetailScreen(defectId: doc.id),
                                  ),
                                ));
                              }
                              for (final doc in jobSnap.data?.docs ?? []) {
                                final d = doc.data() as Map<String, dynamic>;
                                String? extra;
                                final selectedQuotationId =
                                    d['selectedQuotationId'] as String?;
                                if (selectedQuotationId != null) {
                                  final quotation =
                                      quotationsByJob[selectedQuotationId];
                                  if (quotation != null) {
                                    final totalCents =
                                        (quotation['totalCents'] as num?)
                                                ?.toInt() ??
                                            0;
                                    extra =
                                        '${quotation['garageName'] ?? ''} — '
                                        '${_formatMoney(_centsToMoney(totalCents))}';
                                  }
                                }
                                final approval = latestApprovalByJob[doc.id];
                                if (approval != null) {
                                  final decision =
                                      (approval['decision'] ?? 'PENDING')
                                          .toString();
                                  extra = extra == null
                                      ? decision
                                      : '$extra · $decision';
                                }
                                final invoice = invoiceByJob[doc.id];
                                if (invoice != null) {
                                  final invTotalCents =
                                      (invoice['totalCents'] as num?)
                                              ?.toInt() ??
                                          0;
                                  final invSummary =
                                      '${invoice['invoiceNo'] ?? ''} '
                                      '${_formatMoney(_centsToMoney(invTotalCents))} '
                                      '(${invoice['paymentStatus'] ?? 'NOT_BILLED'})';
                                  extra = extra == null
                                      ? invSummary
                                      : '$extra · $invSummary';
                                }
                                items.add((
                                  at: d['openedAt'] as Timestamp?,
                                  label: (d['jobNo'] ?? '').toString(),
                                  status: (d['repairStatus'] ?? '').toString(),
                                  summary: (d['confirmedDiagnosis'] ?? 'Repair job')
                                      .toString(),
                                  extra: extra,
                                  category: (d['systemCategory'] ?? '').toString(),
                                  onTap: () => pushWebAware(
                                    context,
                                    RepairJobDetailScreen(jobId: doc.id),
                                  ),
                                ));
                              }
                              items.sort((a, b) {
                                if (a.at == null || b.at == null) return 0;
                                return b.at!.compareTo(a.at!);
                              });
                              final trimmedSearch = _searchText.trim().toLowerCase();
                              final filteredItems = items.where((item) {
                                if (_categoryFilter != null &&
                                    item.category != _categoryFilter) {
                                  return false;
                                }
                                if (trimmedSearch.isNotEmpty) {
                                  final haystack =
                                      '${item.label} ${item.summary} ${item.extra ?? ''}'
                                          .toLowerCase();
                                  if (!haystack.contains(trimmedSearch)) return false;
                                }
                                return true;
                              }).toList();
                              if (filteredItems.isEmpty) {
                                return EmptyState(
                                  icon: Icons.history,
                                  title: items.isEmpty
                                      ? 'No defects or repair jobs for '
                                          '$_vehicleNumber yet.'
                                      : 'No matching history.',
                                );
                              }
                              return ListView.builder(
                                padding: const EdgeInsets.all(AppSpacing.md),
                                itemCount: filteredItems.length,
                                itemBuilder: (context, index) {
                                  final item = filteredItems[index];
                                  return AppStaggeredFadeIn(
                                    index: index,
                                    child: Padding(
                                      padding: const EdgeInsets.only(
                                        bottom: AppSpacing.sm,
                                      ),
                                      child: AppCard(
                                        onTap: item.onTap,
                                        child: Row(
                                          children: [
                                            Expanded(
                                              child: Column(
                                                crossAxisAlignment:
                                                    CrossAxisAlignment.start,
                                                children: [
                                                  Text(item.label, style: AppText.section),
                                                  Text(
                                                    item.summary,
                                                    style: AppText.caption,
                                                    maxLines: 1,
                                                    overflow: TextOverflow.ellipsis,
                                                  ),
                                                  if (item.extra != null)
                                                    Text(
                                                      item.extra!,
                                                      style: AppText.caption.copyWith(
                                                        fontWeight: FontWeight.w600,
                                                      ),
                                                    ),
                                                  Text(
                                                    _repairFormatDateTime(item.at),
                                                    style: AppText.caption,
                                                  ),
                                                ],
                                              ),
                                            ),
                                            StatusChip(status: item.status),
                                          ],
                                        ),
                                      ),
                                    ),
                                  );
                                },
                              );
                            },
                          );
                        },
                      );
                    },
                  );
                },
              );
            },
          ),
        ),
        ],
      ),
    );
      },
    );
  }
}


// ---------------- SIMPLE MODE (Daily Vehicle Inspection flow) ----------------
// Add Defect -> Mechanic form -> Supervisor approval -> Mark Done. Reuses
// defect_reports, repair_jobs and repair_approvals exactly as Phases 1-3
// defined them (no new collections) — only additive fields, gated by
// repair_jobs.simpleMode == true. Advanced Mode (quotations/invoices/
// payments) is untouched by any of this.

// Fetches a vehicle's past repair records (defects that became repair jobs)
// and normalizes them for previousRepairsForCategory(). NOT pure (does
// Firestore IO) — the sort/filter it feeds is the unit-tested part. Avoids
// any orderBy() combined with a different equality filter so no new
// composite index is needed; the (small) result set is sorted client-side.
Future<List<Map<String, dynamic>>> _fetchVehicleRepairRecords(
  String vehicleNumber,
) async {
  final defectsSnap = await FirebaseFirestore.instance
      .collection('defect_reports')
      .where('vehicleNumber', isEqualTo: vehicleNumber)
      .limit(50)
      .get();
  final withJob = defectsSnap.docs
      .where((d) => (d.data()['repairJobId'] as String?) != null)
      .toList();
  final jobDocs = await Future.wait(
    withJob.map(
      (d) => FirebaseFirestore.instance
          .collection('repair_jobs')
          .doc(d.data()['repairJobId'] as String)
          .get(),
    ),
  );
  final records = <Map<String, dynamic>>[];
  for (var i = 0; i < withJob.length; i++) {
    final defect = withJob[i].data();
    final job = jobDocs[i].data();
    if (job == null) continue;
    final at =
        (job['completedAt'] ?? job['closedAt'] ?? job['openedAt'] ?? defect['reportedAt'])
            as Timestamp?;
    final costCents = (job['actualCostCents'] as num?)?.toInt() ??
        (job['estimatedTotalCents'] as num?)?.toInt() ??
        (job['approvedAmountCents'] as num?)?.toInt() ??
        0;
    records.add({
      'category': (defect['systemCategory'] ?? '').toString(),
      'atMillis': at?.millisecondsSinceEpoch ?? 0,
      'dateLabel': _repairFormatDateTime(at),
      'garageName': (job['garageName'] ?? job['completionGarageName'] ?? '').toString(),
      'costCents': costCents,
      'whatWasDone': (job['confirmedDiagnosis'] ??
              job['recommendedRepair'] ??
              defect['symptoms'] ??
              '')
          .toString(),
    });
  }
  return records;
}

// "Previous CATEGORY repairs on this vehicle" warning card — used by both
// the Add Defect form (onlyMatchingCategory: true) and the mechanic's
// defect detail / diagnose form (onlyMatchingCategory: false, same-category
// first, per the spec's "PREVIOUS REPAIRS OF THIS VEHICLE (same category
// first)").
class _PreviousRepairsCard extends StatefulWidget {
  final String vehicleNumber;
  final String category;
  final bool onlyMatchingCategory;
  final int maxItems;
  const _PreviousRepairsCard({
    required this.vehicleNumber,
    required this.category,
    this.onlyMatchingCategory = true,
    this.maxItems = 3,
  });

  @override
  State<_PreviousRepairsCard> createState() => _PreviousRepairsCardState();
}

class _PreviousRepairsCardState extends State<_PreviousRepairsCard> {
  // Cached by vehicle number so a parent rebuild (e.g. ticking a category
  // chip elsewhere on the Add Defect form, which setState()s the whole
  // screen) doesn't recreate this Future every build — same "stuck
  // loading"/wasted-reads root cause as RepairApprovalDetailScreen and
  // VehicleRepairHistoryScreen. This card itself never shows a loader (a
  // blank card while loading is fine for a supplementary warning), but a
  // fresh Firestore read on every keystroke elsewhere is not.
  String? _loadedVehicleNumber;
  Future<List<Map<String, dynamic>>>? _recordsFuture;

  Future<List<Map<String, dynamic>>> _getRecordsFuture() {
    if (_loadedVehicleNumber != widget.vehicleNumber) {
      _loadedVehicleNumber = widget.vehicleNumber;
      _recordsFuture = _fetchVehicleRepairRecords(widget.vehicleNumber)
          .timeout(const Duration(seconds: 15))
          .catchError((Object e, StackTrace st) {
        debugPrint(
          'PreviousRepairsCard: failed to load repair history for '
          '${widget.vehicleNumber}: $e',
        );
        return <Map<String, dynamic>>[];
      });
    }
    return _recordsFuture!;
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<List<Map<String, dynamic>>>(
      future: _getRecordsFuture(),
      builder: (context, snap) {
        if (snap.connectionState != ConnectionState.done) {
          return const SizedBox.shrink();
        }
        final sorted = previousRepairsForCategory(
          records: snap.data ?? const [],
          category: widget.category,
        );
        final filtered = widget.onlyMatchingCategory
            ? sorted.where((r) => r['category'] == widget.category).toList()
            : sorted;
        final matches = filtered.take(widget.maxItems).toList();
        if (matches.isEmpty) return const SizedBox.shrink();
        return Container(
          width: double.infinity,
          margin: const EdgeInsets.only(top: AppSpacing.sm),
          padding: const EdgeInsets.all(AppSpacing.sm),
          decoration: BoxDecoration(
            color: AppColors.warning.withOpacity(0.08),
            borderRadius: BorderRadius.circular(AppRadius.card),
            border: Border.all(color: AppColors.warning.withOpacity(0.4)),
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                widget.onlyMatchingCategory
                    ? 'PREVIOUS ${widget.category} REPAIRS ON THIS VEHICLE'
                    : 'PREVIOUS REPAIRS OF THIS VEHICLE (${widget.category} FIRST)',
                style: AppText.caption.copyWith(fontWeight: FontWeight.bold),
              ),
              const SizedBox(height: 6),
              ...matches.map(
                (r) => Padding(
                  padding: const EdgeInsets.only(bottom: 4),
                  child: Text(
                    '${r['dateLabel']} • '
                    '${(r['garageName'] as String?)?.isEmpty ?? true ? '—' : r['garageName']} • '
                    '${_formatMoney(_centsToMoney((r['costCents'] as int?) ?? 0))} — '
                    '${r['whatWasDone']}',
                    style: AppText.caption,
                  ),
                ),
              ),
            ],
          ),
        );
      },
    );
  }
}

class _AddDefectDraft {
  String? category;
  final descController = TextEditingController();
  final attachmentsKey = GlobalKey<_InspectionAttachmentsSectionState>();
  void dispose() => descController.dispose();
}

// New general "ADD DEFECT" entry point for the Daily/Weekly Vehicle
// Inspection forms — distinct from (and coexists with) the existing
// conditional "REPORT DEFECT" shortcut those forms already show for a
// BAD/REPLACE tire or BAD cabin item. Lets the driver/inspector log several
// defects in one sitting, each with its own category/description/photos/
// voice note, then submit them all with one button. Writes plain
// defect_reports docs — same collection and shape ReportDefectScreen uses.
class AddDefectScreen extends StatefulWidget {
  final String userName;
  final String vehicleNumber;
  final String sourceInspectionId;
  const AddDefectScreen({
    super.key,
    required this.userName,
    required this.vehicleNumber,
    required this.sourceInspectionId,
  });

  @override
  State<AddDefectScreen> createState() => _AddDefectScreenState();
}

class _AddDefectScreenState extends State<AddDefectScreen> {
  final List<_AddDefectDraft> _drafts = [_AddDefectDraft()];
  bool _busy = false;
  // Cached once — every category chip tap / add-draft / remove-draft calls
  // setState() on this screen, which would otherwise hand the FutureBuilder
  // below a fresh Future on every keystroke-adjacent rebuild.
  late final Future<bool> _permFuture = _currentUserHasRepairPerm(kPermReportDefect);

  @override
  void dispose() {
    for (final d in _drafts) {
      d.dispose();
    }
    super.dispose();
  }

  Future<void> _guarded(Future<void> Function() action) async {
    if (_busy) return;
    setState(() => _busy = true);
    try {
      await action();
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  void _addDraft() => setState(() => _drafts.add(_AddDefectDraft()));

  void _removeDraft(int index) => setState(() {
    _drafts[index].dispose();
    _drafts.removeAt(index);
  });

  Future<void> _submit() async {
    for (final d in _drafts) {
      if (d.category == null) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Please select a category for every defect.')),
        );
        return;
      }
      if (d.descController.text.trim().isEmpty) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Please describe every defect.')),
        );
        return;
      }
    }
    final count = _drafts.length;
    final confirmed = await showAppConfirmDialog(
      context: context,
      title: 'Submit $count Defect${count > 1 ? 's' : ''}?',
      message: 'This reports $count defect${count > 1 ? 's' : ''} for ${widget.vehicleNumber}.',
      confirmLabel: 'Submit',
    );
    if (!confirmed) return;

    try {
      final currentUser = FirebaseAuth.instance.currentUser;
      final uid = currentUser?.uid ?? '';
      for (final d in _drafts) {
        final docRef = FirebaseFirestore.instance.collection('defect_reports').doc();
        final defectNo = await _nextRepairSequenceNumber('defect_reports', 'DEF');
        final attachments = await d.attachmentsKey.currentState!.uploadAndFinalize(
          _repairStoragePathPrefix(docRef.id),
        );
        await docRef.set({
          'defectNo': defectNo,
          'vehicleNumber': widget.vehicleNumber,
          'odometerKm': null,
          'systemCategory': d.category,
          'symptoms': d.descController.text.trim(),
          'severity': 'MEDIUM',
          'safetyCritical': false,
          'status': 'OPEN',
          'rejectReason': null,
          'repairJobId': null,
          'sourceInspectionId': widget.sourceInspectionId,
          'photos': attachments.photos,
          'voices': attachments.voices,
          'date': _repairYmd(DateTime.now()),
          'reportedBy': uid,
          'reportedByName': widget.userName,
          'reportedByEmail': currentUser?.email,
          'reportedAt': FieldValue.serverTimestamp(),
          'createdAt': FieldValue.serverTimestamp(),
          'updatedAt': FieldValue.serverTimestamp(),
        });
        await _writeRepairEvent(
          collection: 'defect_reports',
          docId: docRef.id,
          action: 'CREATED',
          summary: 'Defect reported ($defectNo) via Add Defect',
          actorUid: uid,
          actorName: widget.userName,
        );
      }
      if (!mounted) return;
      await showDialog<void>(
        context: context,
        builder: (dialogContext) => AlertDialog(
          title: const Text('Defects Reported'),
          content: Text(
            '$count defect${count > 1 ? 's' : ''} reported and sent to the '
            'mechanic\'s "Defects To Check" list.',
          ),
          actions: [
            ElevatedButton(
              onPressed: () => Navigator.pop(dialogContext),
              child: const Text('OK'),
            ),
          ],
        ),
      );
      if (mounted) Navigator.pop(context);
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Failed to submit defects: $e')),
        );
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<bool>(
      future: _permFuture,
      builder: (context, permSnap) {
        if (permSnap.connectionState != ConnectionState.done) {
          return const TruckRepairScaffold(body: LoadingState());
        }
        if (permSnap.data != true) {
          return const TruckRepairScaffold(
            body: EmptyState(
              icon: Icons.lock_outline,
              title: 'NO ACCESS',
              hint: 'ASK THE ADMIN TO GRANT THIS TRUCK REPAIR PERMISSION',
            ),
          );
        }
        return TruckRepairScaffold(
          appBar: AppBar(
            title: Text('Add Defect — ${widget.vehicleNumber}'),
            backgroundColor: AppColors.navy,
            foregroundColor: Colors.white,
          ),
          body: SingleChildScrollView(
            padding: const EdgeInsets.all(AppSpacing.md),
            child: Align(
              alignment: Alignment.topCenter,
              child: ConstrainedBox(
                constraints: const BoxConstraints(maxWidth: 560),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    for (var i = 0; i < _drafts.length; i++) ...[
                      AppCard(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Row(
                              children: [
                                Expanded(
                                  child: Text('Defect ${i + 1}', style: AppText.section),
                                ),
                                if (_drafts.length > 1)
                                  IconButton(
                                    icon: const Icon(Icons.close),
                                    onPressed: () => _removeDraft(i),
                                  ),
                              ],
                            ),
                            const SizedBox(height: AppSpacing.sm),
                            Text('Category', style: AppText.caption),
                            const SizedBox(height: 6),
                            Wrap(
                              spacing: 8,
                              runSpacing: 8,
                              children: kDefectSystemCategories.map((c) {
                                return ChoiceChip(
                                  label: Text(c),
                                  selected: _drafts[i].category == c,
                                  onSelected: (_) =>
                                      setState(() => _drafts[i].category = c),
                                );
                              }).toList(),
                            ),
                            if (_drafts[i].category != null)
                              _PreviousRepairsCard(
                                vehicleNumber: widget.vehicleNumber,
                                category: _drafts[i].category!,
                              ),
                            const SizedBox(height: AppSpacing.md),
                            Text('Description', style: AppText.caption),
                            const SizedBox(height: 6),
                            TextField(
                              controller: _drafts[i].descController,
                              inputFormatters: [UpperCaseTextFormatter()],
                              textCapitalization: TextCapitalization.characters,
                              maxLines: 3,
                              decoration: InputDecoration(
                                hintText: 'Describe the defect',
                                border: OutlineInputBorder(
                                  borderRadius: BorderRadius.circular(AppRadius.button),
                                ),
                              ),
                            ),
                            const SizedBox(height: AppSpacing.md),
                            _InspectionAttachmentsSection(key: _drafts[i].attachmentsKey),
                          ],
                        ),
                      ),
                      const SizedBox(height: AppSpacing.md),
                    ],
                    OutlinedButton.icon(
                      onPressed: _addDraft,
                      icon: const Icon(Icons.add),
                      label: const Text('ADD ANOTHER DEFECT'),
                    ),
                    const SizedBox(height: AppSpacing.lg),
                    SizedBox(
                      width: double.infinity,
                      child: ElevatedButton(
                        onPressed: _busy ? null : () => _guarded(_submit),
                        style: ElevatedButton.styleFrom(
                          padding: const EdgeInsets.symmetric(vertical: 14),
                          backgroundColor: AppColors.navy,
                        ),
                        child: _busy
                            ? const SizedBox(
                                width: 20,
                                height: 20,
                                child: CircularProgressIndicator(
                                  strokeWidth: 2,
                                  color: Colors.white,
                                ),
                              )
                            : Text('SUBMIT (${_drafts.length})'),
                      ),
                    ),
                  ],
                ),
              ),
            ),
          ),
        );
      },
    );
  }
}

// Mechanic's "DEFECTS TO CHECK" list — fresh REPORTED defects (defect_reports
// at status OPEN, not yet converted into a job) plus RETURNED simple-mode
// jobs (repairStatus DIAGNOSED with a returnReason, sent back by a
// supervisor). Deliberately phone-friendly: single-column cards, big tap
// targets, filter chips instead of a data table.
class DefectsToCheckScreen extends StatefulWidget {
  const DefectsToCheckScreen({super.key});

  @override
  State<DefectsToCheckScreen> createState() => _DefectsToCheckScreenState();
}

class _DefectsToCheckScreenState extends State<DefectsToCheckScreen> {
  String? _statusFilter;
  String? _categoryFilter;
  String? _vehicleFilter;
  DateTimeRange? _dateRange;
  final _searchController = TextEditingController();
  String _searchText = '';

  // Every filter chip/search keystroke here calls setState(), which
  // re-runs build() — these are declared once (not inline in build()) so
  // that doesn't recreate the permission Future or either Firestore stream
  // every time. All actual filtering below (status/category/vehicle/date/
  // search) happens client-side on the fetched docs, so neither query ever
  // needs to change — the ROOT CAUSE class of bug fixed in
  // RepairApprovalDetailScreen/VehicleRepairHistoryScreen: a
  // Future/Stream recreated on every rebuild resets its FutureBuilder/
  // StreamBuilder to ConnectionState.waiting before the previous call can
  // resolve and render.
  late final Future<bool> _permFuture =
      _currentUserHasAnyRepairPerm([kPermDiagnose, kPermRepairJobs]);
  static const _loadTimeout = Duration(seconds: 15);
  late final Stream<QuerySnapshot> _defectStream = FirebaseFirestore.instance
      .collection('defect_reports')
      .where('status', isEqualTo: 'OPEN')
      .snapshots()
      .timeout(
        _loadTimeout,
        onTimeout: (sink) {
          debugPrint('DefectsToCheckScreen: defect_reports produced no snapshot '
              'within $_loadTimeout');
          sink.addError(TimeoutException('Taking too long to load defects.'));
        },
      );
  late final Stream<QuerySnapshot> _jobStream = FirebaseFirestore.instance
      .collection('repair_jobs')
      .where('simpleMode', isEqualTo: true)
      .where('repairStatus', isEqualTo: RepairStatus.diagnosed)
      .snapshots()
      .timeout(
        _loadTimeout,
        onTimeout: (sink) {
          debugPrint('DefectsToCheckScreen: repair_jobs produced no snapshot '
              'within $_loadTimeout');
          sink.addError(TimeoutException('Taking too long to load returned jobs.'));
        },
      );

  @override
  void dispose() {
    _searchController.dispose();
    super.dispose();
  }

  Future<void> _pickDateRange() async {
    final picked = await showDateRangePicker(
      context: context,
      firstDate: DateTime(2020),
      lastDate: DateTime.now().add(const Duration(days: 1)),
      initialDateRange: _dateRange,
    );
    if (picked != null) setState(() => _dateRange = picked);
  }

  Future<void> _pickVehicleNumber() async {
    final picked = await _showVehicleNumberPicker(context);
    if (picked != null) setState(() => _vehicleFilter = picked);
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<bool>(
      future: _permFuture,
      builder: (context, permSnap) {
        if (permSnap.connectionState != ConnectionState.done) {
          return const TruckRepairScaffold(body: LoadingState());
        }
        if (permSnap.hasError) {
          debugPrint('DefectsToCheckScreen: permission check failed: ${permSnap.error}');
          return TruckRepairScaffold(
            body: ErrorState(
              message: 'Failed to check permissions: ${permSnap.error}',
              onRetry: () => setState(() {}),
            ),
          );
        }
        if (permSnap.data != true) {
          return const TruckRepairScaffold(
            body: EmptyState(
              icon: Icons.lock_outline,
              title: 'NO ACCESS',
              hint: 'ASK THE ADMIN TO GRANT THIS TRUCK REPAIR PERMISSION',
            ),
          );
        }
        return TruckRepairScaffold(
          appBar: AppBar(
            title: const Text('Defects To Check'),
            backgroundColor: AppColors.navy,
            foregroundColor: Colors.white,
          ),
          body: StreamBuilder<QuerySnapshot>(
            stream: _defectStream,
            builder: (context, defectSnap) {
              return StreamBuilder<QuerySnapshot>(
                stream: _jobStream,
                builder: (context, jobSnap) {
                  final firstError = defectSnap.error ?? jobSnap.error;
                  if (firstError != null) {
                    debugPrint('DefectsToCheckScreen: load error: $firstError');
                    return ErrorState(
                      message: firstError is TimeoutException
                          ? 'Taking too long — RETRY'
                          : 'Failed to load: $firstError',
                      onRetry: () => setState(() {}),
                    );
                  }
                  if (!defectSnap.hasData || !jobSnap.hasData) {
                    return const LoadingState();
                  }

                  final items = <({
                    String statusLabel,
                    String vehicleNumber,
                    String category,
                    String description,
                    Timestamp? at,
                    VoidCallback onTap,
                  })>[];
                  for (final doc in defectSnap.data!.docs) {
                    final d = doc.data() as Map<String, dynamic>;
                    items.add((
                      statusLabel: 'REPORTED',
                      vehicleNumber: (d['vehicleNumber'] ?? '').toString(),
                      category: (d['systemCategory'] ?? '').toString(),
                      description: (d['symptoms'] ?? '').toString(),
                      at: d['reportedAt'] as Timestamp?,
                      onTap: () => pushWebAware(
                        context,
                        DefectMechanicFormScreen(defectId: doc.id),
                      ),
                    ));
                  }
                  for (final doc in jobSnap.data!.docs) {
                    final d = doc.data() as Map<String, dynamic>;
                    if (d['returnReason'] == null) continue;
                    items.add((
                      statusLabel: 'RETURNED',
                      vehicleNumber: (d['vehicleNumber'] ?? '').toString(),
                      category: (d['systemCategory'] ?? '').toString(),
                      description: (d['confirmedDiagnosis'] ?? '').toString(),
                      at: d['returnedAt'] as Timestamp?,
                      onTap: () => pushWebAware(
                        context,
                        DefectMechanicFormScreen(jobId: doc.id),
                      ),
                    ));
                  }
                  items.sort((a, b) {
                    final at = a.at?.millisecondsSinceEpoch ?? 0;
                    final bt = b.at?.millisecondsSinceEpoch ?? 0;
                    return bt.compareTo(at);
                  });

                  final trimmedSearch = _searchText.trim().toLowerCase();
                  final filtered = items.where((item) {
                    if (_statusFilter != null && item.statusLabel != _statusFilter) {
                      return false;
                    }
                    if (_categoryFilter != null && item.category != _categoryFilter) {
                      return false;
                    }
                    if (_vehicleFilter != null && item.vehicleNumber != _vehicleFilter) {
                      return false;
                    }
                    if (_dateRange != null) {
                      if (item.at == null) return false;
                      final d = item.at!.toDate();
                      if (d.isBefore(_dateRange!.start) ||
                          d.isAfter(_dateRange!.end.add(const Duration(days: 1)))) {
                        return false;
                      }
                    }
                    if (trimmedSearch.isNotEmpty) {
                      final haystack =
                          '${item.vehicleNumber} ${item.description}'.toLowerCase();
                      if (!haystack.contains(trimmedSearch)) return false;
                    }
                    return true;
                  }).toList();

                  return Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Padding(
                        padding: const EdgeInsets.all(AppSpacing.md),
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            TextField(
                              controller: _searchController,
                              inputFormatters: [UpperCaseTextFormatter()],
                              textCapitalization: TextCapitalization.characters,
                              decoration: const InputDecoration(
                                hintText: 'Search vehicle no. / description',
                                prefixIcon: Icon(Icons.search),
                              ),
                              onChanged: (val) => setState(() => _searchText = val),
                            ),
                            const SizedBox(height: AppSpacing.sm),
                            Wrap(
                              spacing: 8,
                              runSpacing: 8,
                              children: [
                                OutlinedButton.icon(
                                  onPressed: _pickVehicleNumber,
                                  icon: const Icon(Icons.local_shipping),
                                  label: Text(_vehicleFilter ?? 'Any Vehicle'),
                                ),
                                OutlinedButton.icon(
                                  onPressed: _pickDateRange,
                                  icon: const Icon(Icons.date_range),
                                  label: Text(
                                    _dateRange == null
                                        ? 'Any Date'
                                        : '${_repairYmd(_dateRange!.start)} - '
                                            '${_repairYmd(_dateRange!.end)}',
                                  ),
                                ),
                                if (_vehicleFilter != null || _dateRange != null)
                                  TextButton(
                                    onPressed: () => setState(() {
                                      _vehicleFilter = null;
                                      _dateRange = null;
                                    }),
                                    child: const Text('CLEAR'),
                                  ),
                              ],
                            ),
                            const SizedBox(height: AppSpacing.sm),
                            Wrap(
                              spacing: 8,
                              runSpacing: 8,
                              children: [
                                ChoiceChip(
                                  label: const Text('ALL'),
                                  selected: _statusFilter == null,
                                  onSelected: (_) => setState(() => _statusFilter = null),
                                ),
                                for (final s in ['REPORTED', 'RETURNED'])
                                  ChoiceChip(
                                    label: Text(s),
                                    selected: _statusFilter == s,
                                    onSelected: (_) => setState(
                                      () => _statusFilter = _statusFilter == s ? null : s,
                                    ),
                                  ),
                              ],
                            ),
                            const SizedBox(height: AppSpacing.sm),
                            Wrap(
                              spacing: 8,
                              runSpacing: 8,
                              children: [
                                ChoiceChip(
                                  label: const Text('ALL CATEGORIES'),
                                  selected: _categoryFilter == null,
                                  onSelected: (_) => setState(() => _categoryFilter = null),
                                ),
                                ...kDefectSystemCategories.map(
                                  (c) => ChoiceChip(
                                    label: Text(c),
                                    selected: _categoryFilter == c,
                                    onSelected: (_) => setState(
                                      () => _categoryFilter = _categoryFilter == c ? null : c,
                                    ),
                                  ),
                                ),
                              ],
                            ),
                          ],
                        ),
                      ),
                      Expanded(
                        child: filtered.isEmpty
                            ? const EmptyState(
                                icon: Icons.task_alt,
                                title: 'NO DEFECTS TO CHECK',
                                hint: 'NEW DEFECTS AND RETURNED JOBS SHOW UP HERE',
                              )
                            : ListView.builder(
                                padding: const EdgeInsets.symmetric(
                                  horizontal: AppSpacing.md,
                                ),
                                itemCount: filtered.length,
                                itemBuilder: (context, index) {
                                  final item = filtered[index];
                                  return AppStaggeredFadeIn(
                                    index: index,
                                    child: Padding(
                                      padding: const EdgeInsets.only(bottom: AppSpacing.sm),
                                      child: AppCard(
                                        onTap: item.onTap,
                                        child: Column(
                                          crossAxisAlignment: CrossAxisAlignment.start,
                                          children: [
                                            Row(
                                              children: [
                                                Expanded(
                                                  child: Text(
                                                    item.vehicleNumber,
                                                    style: AppText.section,
                                                  ),
                                                ),
                                                StatusChip(status: item.statusLabel),
                                              ],
                                            ),
                                            const SizedBox(height: 4),
                                            Text(
                                              item.category,
                                              style: AppText.caption.copyWith(
                                                fontWeight: FontWeight.w600,
                                              ),
                                            ),
                                            Text(
                                              item.description,
                                              maxLines: 2,
                                              overflow: TextOverflow.ellipsis,
                                              style: AppText.caption,
                                            ),
                                            Text(
                                              _repairFormatDateTime(item.at),
                                              style: AppText.caption,
                                            ),
                                          ],
                                        ),
                                      ),
                                    ),
                                  );
                                },
                              ),
                      ),
                    ],
                  );
                },
              );
            },
          ),
        );
      },
    );
  }
}

class _PartNeededRow {
  final nameController = TextEditingController();
  final qtyController = TextEditingController(text: '1');
  final priceController = TextEditingController(text: '0');
  void dispose() {
    nameController.dispose();
    qtyController.dispose();
    priceController.dispose();
  }
}

// The mechanic form itself — reached either from a fresh REPORTED defect
// (defectId, creates a new repair_job) or a RETURNED simple-mode job
// (jobId, updates the existing one and clears the return note). One
// "SUBMIT FOR APPROVAL" button does diagnosis + approval-request together
// (simple mode skips the separate Quoting/Verified stages entirely).
class DefectMechanicFormScreen extends StatefulWidget {
  final String? defectId;
  final String? jobId;
  const DefectMechanicFormScreen({super.key, this.defectId, this.jobId})
      : assert(defectId != null || jobId != null);

  @override
  State<DefectMechanicFormScreen> createState() => _DefectMechanicFormScreenState();
}

class _DefectMechanicFormScreenState extends State<DefectMechanicFormScreen> {
  bool _loading = true;
  Object? _loadError;
  bool _busy = false;
  Map<String, dynamic>? _defectData;
  Map<String, dynamic>? _jobData;
  String? _jobId;
  String _vehicleNumber = '';
  String _category = '';

  final _noteController = TextEditingController();
  final List<_PartNeededRow> _partRows = [_PartNeededRow()];
  String? _garageId;
  String? _garageName;
  DateTime? _callAt;
  final _calledWithController = TextEditingController();
  DateTime? _plannedRepairDate;
  final _labourController = TextEditingController(text: '0');

  // Computed once per load (not inline in build()) — otherwise every
  // setState() in this screen (adding a part row, picking a garage/date,
  // toggling _busy) would hand the FutureBuilder below a brand-new Future
  // and reset it to ConnectionState.waiting, flashing the full-screen
  // loader on every interaction. Reassignable (not `late final`) so RETRY
  // actually retries instead of replaying the same completed Future.
  late Future<bool> _permFuture;

  @override
  void initState() {
    super.initState();
    _permFuture = _currentUserHasAnyRepairPerm([kPermDiagnose, kPermRepairJobs]);
    _load();
  }

  Future<void> _load() async {
    setState(() {
      _loading = true;
      _loadError = null;
    });
    try {
      await _doLoad().timeout(const Duration(seconds: 15));
      if (mounted) setState(() => _loading = false);
    } catch (e) {
      debugPrint('DefectMechanicFormScreen: failed to load '
          '(jobId=${widget.jobId}, defectId=${widget.defectId}): $e');
      if (mounted) {
        setState(() {
          _loading = false;
          _loadError = e;
        });
      }
    }
  }

  Future<void> _doLoad() async {
    final jobId = widget.jobId;
    final defectId = widget.defectId;
    if (jobId != null) {
      final jobSnap =
          await FirebaseFirestore.instance.collection('repair_jobs').doc(jobId).get();
      if (!jobSnap.exists) {
        throw Exception('Repair job $jobId no longer exists.');
      }
      final job = jobSnap.data();
      _jobData = job;
      _jobId = jobId;
      _vehicleNumber = (job?['vehicleNumber'] ?? '').toString();
      _category = (job?['systemCategory'] ?? '').toString();
      _noteController.text = (job?['confirmedDiagnosis'] ?? '').toString();
      _garageId = job?['garageId'] as String?;
      _garageName = job?['garageName'] as String?;
      final callAt = job?['callAt'];
      if (callAt is Timestamp) _callAt = callAt.toDate();
      _calledWithController.text = (job?['calledWithName'] ?? '').toString();
      final planned = job?['plannedRepairDate'];
      if (planned is Timestamp) _plannedRepairDate = planned.toDate();
      _labourController.text = _centsToMoney(
        ((job?['labourCostCents'] as num?)?.toInt() ?? 0),
      ).toStringAsFixed(2);
      final parts = (job?['partsList'] as List?) ?? const [];
      if (parts.isNotEmpty) {
        _partRows.clear();
        for (final p in parts) {
          final m = p as Map<String, dynamic>;
          final row = _PartNeededRow();
          row.nameController.text = (m['name'] ?? '').toString();
          row.qtyController.text = (m['qty'] ?? '').toString();
          row.priceController.text = _centsToMoney(
            ((m['estimatedPriceCents'] as num?)?.toInt() ?? 0),
          ).toStringAsFixed(2);
          _partRows.add(row);
        }
      }
      final defectIds = (job?['defectIds'] as List?) ?? const [];
      if (defectIds.isNotEmpty) {
        final firstDefectId = defectIds.first as String?;
        if (firstDefectId != null && firstDefectId.isNotEmpty) {
          final d = await FirebaseFirestore.instance
              .collection('defect_reports')
              .doc(firstDefectId)
              .get();
          _defectData = d.data();
        }
      }
    } else if (defectId != null && defectId.isNotEmpty) {
      final defectSnap =
          await FirebaseFirestore.instance.collection('defect_reports').doc(defectId).get();
      if (!defectSnap.exists) {
        throw Exception('Defect $defectId no longer exists.');
      }
      _defectData = defectSnap.data();
      _vehicleNumber = (_defectData?['vehicleNumber'] ?? '').toString();
      _category = (_defectData?['systemCategory'] ?? '').toString();
    } else {
      // Defensive: the widget's assert (stripped in release builds) is the
      // only other guard that neither id is ever both null.
      throw Exception('No defect or repair job id was given.');
    }
  }

  @override
  void dispose() {
    _noteController.dispose();
    for (final r in _partRows) {
      r.dispose();
    }
    _calledWithController.dispose();
    _labourController.dispose();
    super.dispose();
  }

  Future<void> _guarded(Future<void> Function() action) async {
    if (_busy) return;
    setState(() => _busy = true);
    try {
      await action();
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  void _addPartRow() => setState(() => _partRows.add(_PartNeededRow()));
  void _removePartRow(int i) => setState(() {
    _partRows[i].dispose();
    _partRows.removeAt(i);
  });

  Future<void> _pickGarage() async {
    final picked = await _showGaragePicker(context);
    if (picked != null) {
      setState(() {
        _garageId = picked['id'];
        _garageName = picked['name'];
      });
    }
  }

  Future<void> _pickCallAt() async {
    final date = await showDatePicker(
      context: context,
      initialDate: _callAt ?? DateTime.now(),
      firstDate: DateTime(2020),
      lastDate: DateTime.now().add(const Duration(days: 1)),
    );
    if (date == null) return;
    if (!mounted) return;
    final time = await showTimePicker(
      context: context,
      initialTime: TimeOfDay.fromDateTime(_callAt ?? DateTime.now()),
    );
    if (time == null) return;
    setState(() => _callAt = DateTime(date.year, date.month, date.day, time.hour, time.minute));
  }

  Future<void> _pickPlannedDate() async {
    final picked = await showDatePicker(
      context: context,
      initialDate: _plannedRepairDate ?? DateTime.now(),
      firstDate: DateTime.now().subtract(const Duration(days: 1)),
      lastDate: DateTime.now().add(const Duration(days: 180)),
    );
    if (picked != null) setState(() => _plannedRepairDate = picked);
  }

  List<Map<String, dynamic>> get _partsData => _partRows
      .where((r) => r.nameController.text.trim().isNotEmpty)
      .map((r) {
        final qty = num.tryParse(r.qtyController.text.trim()) ?? 0;
        final price = num.tryParse(r.priceController.text.trim()) ?? 0;
        return {
          'name': r.nameController.text.trim(),
          'qty': qty,
          'estimatedPriceCents': _moneyToCents(price),
        };
      })
      .toList();

  int get _partsTotalCents => _partsData.fold<int>(
        0,
        (sum, p) => sum +
            _lineTotalCents(
              p['qty'] as num,
              _centsToMoney(p['estimatedPriceCents'] as int),
            ),
      );

  int get _estimatedTotalCents =>
      _partsTotalCents + _moneyToCents(num.tryParse(_labourController.text.trim()) ?? 0);

  Future<void> _submitForApproval() async {
    if (_noteController.text.trim().isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Please enter the mechanical note.')),
      );
      return;
    }
    if (_garageId == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Please select a garage.')),
      );
      return;
    }
    final confirmed = await showAppConfirmDialog(
      context: context,
      title: 'Submit For Approval?',
      message: 'Estimated total: ${_formatMoney(_centsToMoney(_estimatedTotalCents))}.',
      confirmLabel: 'Submit',
    );
    if (!confirmed) return;

    try {
      final uid = FirebaseAuth.instance.currentUser?.uid ?? '';
      final userDoc = await FirebaseFirestore.instance.collection('users').doc(uid).get();
      final userName = (userDoc.data()?['name'] ?? 'Unknown').toString();

      DocumentReference jobRef;
      String jobNoForEvent;
      final isResubmit = _jobId != null;
      if (isResubmit) {
        jobRef = FirebaseFirestore.instance.collection('repair_jobs').doc(_jobId);
        jobNoForEvent = (_jobData?['jobNo'] ?? '').toString();
        await jobRef.update({
          'confirmedDiagnosis': _noteController.text.trim(),
          'mechanicalSupervisorId': uid,
          'mechanicalSupervisorName': userName,
          'partsList': _partsData,
          'labourCostCents': _moneyToCents(num.tryParse(_labourController.text.trim()) ?? 0),
          'garageId': _garageId,
          'garageName': _garageName,
          'callAt': _callAt != null ? Timestamp.fromDate(_callAt!) : null,
          'calledWithName': _calledWithController.text.trim(),
          'plannedRepairDate':
              _plannedRepairDate != null ? Timestamp.fromDate(_plannedRepairDate!) : null,
          'estimatedTotalCents': _estimatedTotalCents,
          'repairStatus': RepairStatus.pendingApproval,
          'returnReason': null,
          'returnedBy': null,
          'returnedByName': null,
          'returnedAt': null,
          'updatedBy': uid,
          'updatedByName': userName,
          'updatedAt': FieldValue.serverTimestamp(),
        });
      } else {
        jobRef = FirebaseFirestore.instance.collection('repair_jobs').doc();
        final jobNo = await _nextRepairSequenceNumber('repair_jobs', 'REP');
        jobNoForEvent = jobNo;
        await jobRef.set({
          'jobNo': jobNo,
          'vehicleNumber': _vehicleNumber,
          'defectIds': [widget.defectId],
          'priority': 'MEDIUM',
          'repairStatus': RepairStatus.pendingApproval,
          'paymentStatus': 'NOT_BILLED',
          'simpleMode': true,
          'systemCategory': _category,
          'mechanicalSupervisorId': uid,
          'mechanicalSupervisorName': userName,
          'confirmedDiagnosis': _noteController.text.trim(),
          'rootCause': null,
          'recommendedRepair': null,
          'safetyAssessment': null,
          'partsList': _partsData,
          'labourCostCents': _moneyToCents(num.tryParse(_labourController.text.trim()) ?? 0),
          'garageId': _garageId,
          'garageName': _garageName,
          'callAt': _callAt != null ? Timestamp.fromDate(_callAt!) : null,
          'calledWithName': _calledWithController.text.trim(),
          'plannedRepairDate':
              _plannedRepairDate != null ? Timestamp.fromDate(_plannedRepairDate!) : null,
          'estimatedTotalCents': _estimatedTotalCents,
          'openedAt': FieldValue.serverTimestamp(),
          'diagnosedAt': FieldValue.serverTimestamp(),
          'closedAt': null,
          'createdBy': uid,
          'createdByName': userName,
          'createdByEmail': FirebaseAuth.instance.currentUser?.email,
          'createdAt': FieldValue.serverTimestamp(),
          'updatedBy': uid,
          'updatedByName': userName,
          'updatedAt': FieldValue.serverTimestamp(),
        });
        await FirebaseFirestore.instance
            .collection('defect_reports')
            .doc(widget.defectId)
            .update({
          'status': 'REPAIR_CREATED',
          'repairJobId': jobRef.id,
          'updatedAt': FieldValue.serverTimestamp(),
        });
        await _writeRepairEvent(
          collection: 'defect_reports',
          docId: widget.defectId!,
          action: 'STATUS_CHANGED',
          summary: 'Repair job created ($jobNo)',
          actorUid: uid,
          actorName: userName,
        );
      }

      final settings = await _fetchRepairWorkflowSettings();
      final requiredLevel = _estimatedTotalCents <= _moneyToCents(settings.managerApprovalLimit)
          ? 'MANAGER'
          : 'OWNER';
      final approvalNo = await _nextRepairSequenceNumber('repair_approvals', 'APR');
      final approvalRef = FirebaseFirestore.instance.collection('repair_approvals').doc();
      await approvalRef.set({
        'approvalNo': approvalNo,
        'approvalType': 'SIMPLE_REPAIR',
        'repairJobId': jobRef.id,
        'vehicleNumber': _vehicleNumber,
        'quotationId': null,
        'garageId': _garageId,
        'garageName': _garageName,
        'amountCents': _estimatedTotalCents,
        'requiredLevel': requiredLevel,
        'decision': 'PENDING',
        'requestedBy': uid,
        'requestedByName': userName,
        'requestedAt': FieldValue.serverTimestamp(),
        'createdAt': FieldValue.serverTimestamp(),
      });
      await jobRef.update({'activeApprovalId': approvalRef.id});
      await _writeRepairEvent(
        collection: 'repair_approvals',
        docId: approvalRef.id,
        action: 'REQUESTED',
        summary: '$approvalNo requested by $userName — '
            '${_formatMoney(_centsToMoney(_estimatedTotalCents))} ($requiredLevel)',
        actorUid: uid,
        actorName: userName,
      );
      await _writeRepairEvent(
        collection: 'repair_jobs',
        docId: jobRef.id,
        action: isResubmit ? 'RESUBMITTED_FOR_APPROVAL' : 'CREATED',
        summary: isResubmit
            ? 'Resubmitted for approval by $userName'
            : 'Repair job created ($jobNoForEvent) and submitted for approval by $userName',
        actorUid: uid,
        actorName: userName,
      );

      if (!mounted) return;
      await showDialog<void>(
        context: context,
        builder: (dialogContext) => AlertDialog(
          title: const Text('Sent For Approval'),
          content: Text(
            'SENT FOR APPROVAL ($requiredLevel LEVEL, '
            '${_formatMoney(_centsToMoney(_estimatedTotalCents))})',
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dialogContext),
              child: const Text('Close'),
            ),
            ElevatedButton(
              onPressed: () {
                Navigator.pop(dialogContext);
                pushWebAware(
                  context,
                  RepairApprovalDetailScreen(approvalId: approvalRef.id, currentUid: uid),
                );
              },
              child: const Text('OPEN APPROVAL CENTER'),
            ),
          ],
        ),
      );
      if (mounted) Navigator.pop(context);
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Failed to submit: $e')),
        );
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<bool>(
      future: _permFuture,
      builder: (context, permSnap) {
        if (permSnap.connectionState != ConnectionState.done) {
          return const TruckRepairScaffold(body: LoadingState());
        }
        if (permSnap.hasError) {
          debugPrint('DefectMechanicFormScreen: permission check failed: ${permSnap.error}');
          return TruckRepairScaffold(
            body: ErrorState(
              message: 'Failed to check permissions: ${permSnap.error}',
              onRetry: () => setState(() {
                _permFuture = _currentUserHasAnyRepairPerm([kPermDiagnose, kPermRepairJobs]);
              }),
            ),
          );
        }
        if (permSnap.data != true) {
          return const TruckRepairScaffold(
            body: EmptyState(
              icon: Icons.lock_outline,
              title: 'NO ACCESS',
              hint: 'ASK THE ADMIN TO GRANT THIS TRUCK REPAIR PERMISSION',
            ),
          );
        }
        if (_loading) return const TruckRepairScaffold(body: LoadingState());
        if (_loadError != null) {
          return TruckRepairScaffold(
            body: ErrorState(
              message: _loadError is TimeoutException
                  ? 'Taking too long — RETRY'
                  : 'Failed to load: $_loadError',
              onRetry: _load,
