        }
        final photos =
            (_defectData?['photos'] as List?)?.cast<Map<String, dynamic>>() ?? const [];
        final voices =
            (_defectData?['voices'] as List?)?.cast<Map<String, dynamic>>() ?? const [];
        return TruckRepairScaffold(
          appBar: AppBar(
            title: Text('Diagnose — $_vehicleNumber'),
            backgroundColor: AppColors.navy,
