// ---------------- TRUCK REPAIR MANAGEMENT — PHASE 2 ----------------
// Garage Quotations -> Verification -> Manager/Owner Approval, built on
// top of Phase 1 (defect_reports, repair_jobs, events). New collections:
// repair_garages, repair_quotations, repair_approvals, settings
// (settings/repair_workflow doc). No Phase 1 code is modified except
// additive fields on repair_jobs and inserting 'VERIFIED' into
// kRepairStageOrder (see that constant's own comment).

// ---- Money ----
// All money math is done in integer cents, never double arithmetic —
// summing decimal doubles directly is exactly the kind of thing that
// drifts (0.1 + 0.2 style) across a quotation with several line items.
// Firestore still stores plain decimal numbers (2dp) for readability/
// compatibility with other tooling — only the CALCULATIONS happen in
// cents, converted back to decimal once at the end.
int _moneyToCents(num amount) => (amount * 100).round();
double _centsToMoney(int cents) => cents / 100;

int _lineTotalCents(num qty, num unitPrice) =>
    (qty * _moneyToCents(unitPrice)).round();

int _quotationTotalCents({
  required List<({num qty, num unitPrice})> items,
  required num labourCost,
  required num otherCharges,
  required num taxes,
}) {
  var totalCents = 0;
  for (final item in items) {
    totalCents += _lineTotalCents(item.qty, item.unitPrice);
  }
  totalCents += _moneyToCents(labourCost);
  totalCents += _moneyToCents(otherCharges);
  totalCents += _moneyToCents(taxes);
  return totalCents;
}

String _formatMoney(num amount) {
  final cents = _moneyToCents(amount);
  final isNegative = cents < 0;
  final absCents = cents.abs();
  final whole = absCents ~/ 100;
  final frac = (absCents % 100).toString().padLeft(2, '0');
  final wholeStr = whole.toString();
  final buffer = StringBuffer();
  for (var i = 0; i < wholeStr.length; i++) {
    if (i != 0 && (wholeStr.length - i) % 3 == 0) buffer.write(',');
    buffer.write(wholeStr[i]);
  }
  return 'Rs. ${isNegative ? '-' : ''}$buffer.$frac';
}

// ---- Settings (settings/repair_workflow) ----
class RepairWorkflowSettings {
  final num managerApprovalLimit;
  final num multiQuotationThreshold;
  final int multiQuotationMinCount;
  // Default OFF, and never turned on by the app itself — only an explicit
  // admin/owner toggle in RepairSettingsScreen ever sets this true.
  final bool testModeAllowSameUser;
  // Default ON — the Daily Vehicle Inspection flow is simple-mode unless an
  // admin/owner explicitly turns on ADVANCED MODE in RepairSettingsScreen
  // (which sets this false), same on/off convention as testModeAllowSameUser.
  final bool simpleMode;
  // ON TIME vs "LATE BY n km" tolerance for a completed service milestone —
  // see evaluateServiceTiming(). Default 500km per the task.
  final num lateToleranceKm;
  // Default ON (must-complete) — a driver with an active truck session and
  // an un-submitted daily_checks doc for today is auto-prompted with
  // DriverDailyCheckScreen and gets no SKIP button; turning this off (or
  // being admin/owner, which always bypasses regardless of this flag) adds
  // a SKIP — DO LATER button. See dailyCheckAllowSkip().
  final bool requireDailyCheck;
  const RepairWorkflowSettings({
    required this.managerApprovalLimit,
    required this.multiQuotationThreshold,
    required this.multiQuotationMinCount,
    this.testModeAllowSameUser = false,
    this.simpleMode = true,
    this.lateToleranceKm = 500,
    this.requireDailyCheck = true,
  });
}

// Optional `db` override for widget tests (defaults to the real
// FirebaseFirestore.instance) — every existing call site is unaffected
// since the parameter is optional.
Future<RepairWorkflowSettings> _fetchRepairWorkflowSettings({FirebaseFirestore? db}) async {
  final doc = await (db ?? FirebaseFirestore.instance)
      .collection('settings')
      .doc('repair_workflow')
      .get();
  final data = doc.data();
  return RepairWorkflowSettings(
    managerApprovalLimit: (data?['managerApprovalLimit'] as num?) ?? 100000,
    multiQuotationThreshold: (data?['multiQuotationThreshold'] as num?) ?? 50000,
    multiQuotationMinCount:
        (data?['multiQuotationMinCount'] as num?)?.toInt() ?? 2,
    testModeAllowSameUser: data?['testModeAllowSameUser'] == true,
    simpleMode: data?['simpleMode'] != false,
    lateToleranceKm: (data?['lateToleranceKm'] as num?) ?? 500,
    requireDailyCheck: data?['requireDailyCheck'] != false,
  );
}

// Cheap live check for the red TEST MODE banner (every Truck Repair screen
// needs this, so it's a plain settings stream rather than routing through
// _fetchRepairWorkflowSettings()'s one-shot Future each time).
Stream<bool> _testModeStream() {
  return FirebaseFirestore.instance
      .collection('settings')
      .doc('repair_workflow')
      .snapshots()
      .map((doc) => doc.data()?['testModeAllowSameUser'] == true);
}


// Persistent red banner shown on every Truck Repair screen while Test Mode
// is on — identity-exclusion checks (verifier != enterer etc.) are skipped
// app-wide while this is true, but permissions and amount limits are not.
class TestModeBanner extends StatelessWidget {
  const TestModeBanner({super.key});

  @override
  Widget build(BuildContext context) {
    return StreamBuilder<bool>(
      stream: _testModeStream(),
      builder: (context, snap) {
        if (snap.data != true) return const SizedBox.shrink();
        return Container(
          width: double.infinity,
          color: AppColors.danger,
          padding: const EdgeInsets.symmetric(vertical: 6, horizontal: 12),
          child: const Text(
            'TEST MODE ON — SAME USER MAY VERIFY / APPROVE / INSPECT',
            textAlign: TextAlign.center,
            style: TextStyle(
              color: Colors.white,
              fontWeight: FontWeight.bold,
              fontSize: 12,
            ),
          ),
        );
      },
    );
  }
}

// Small inline chip shown next to a timeline entry whose event was recorded
// with testModeOverride: true.
