// ---- Quotation Files (photos + PDFs, {n,url,path,name}) ----
// A separate component from _InspectionAttachmentsSection (Phase 1) on
// purpose — that one is photos+voice only and Phase 1 code must stay
// untouched. This one handles the photo-OR-PDF mix repair_quotations.files
// needs, reusing the same image compression helper
// (_compressInspectionPhotoBytes) and upload-at-save/retry shape.

class QuotationFileResult {
  final List<Map<String, dynamic>> files;
  final bool hadFailures;
  const QuotationFileResult({required this.files, required this.hadFailures});
}

class _QuotationFileItem {
  Uint8List? bytes;
  String? url;
  String? path;
  String name;
  bool isPdf;
  String? error;
  bool uploading = false;
  _QuotationFileItem({
    this.bytes,
    this.url,
    this.path,
    required this.name,
    required this.isPdf,
  });
}

class _QuotationFilesSection extends StatefulWidget {
  final List<Map<String, dynamic>> initialFiles;
  final Future<void> Function(QuotationFileResult result)? onRetrySaved;
  final bool photosOnly;
  final String label;

  const _QuotationFilesSection({
    super.key,
    this.initialFiles = const [],
    this.onRetrySaved,
    this.photosOnly = false,
    this.label = 'Files',
  });

  @override
  State<_QuotationFilesSection> createState() => _QuotationFilesSectionState();
}

class _QuotationFilesSectionState extends State<_QuotationFilesSection> {
  final List<_QuotationFileItem> _files = [];
  final Set<String> _removedStoragePaths = {};
  bool _busy = false;
  bool _retrying = false;
  String? _lastStoragePathPrefix;

  static const _maxImageBytes = 6 * 1024 * 1024;
  static const _maxPdfBytes = 10 * 1024 * 1024;

  @override
  void initState() {
    super.initState();
    for (final f in widget.initialFiles) {
      final name = (f['name'] ?? '').toString();
      _files.add(
        _QuotationFileItem(
          url: f['url'] as String?,
          path: f['path'] as String?,
          name: name,
          isPdf: name.toLowerCase().endsWith('.pdf'),
        ),
      );
    }
  }

  void _showSnack(String message) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(message)));
  }

  bool get _hasFailures => _files.any((f) => f.error != null);

  Future<void> _addPhoto(bool fromCamera) async {
    List<Uint8List> picked = [];
    List<String> names = [];
    try {
      if (fromCamera) {
        final xfile = await ImagePicker().pickImage(source: ImageSource.camera);
        if (xfile != null) {
          picked.add(await xfile.readAsBytes());
          names.add(xfile.name);
        }
      } else if (kIsWeb) {
        final selected = await FilePicker.pickFiles(type: FileType.image);
        for (final f in selected) {
          picked.add(await f.readAsBytes());
          names.add(f.name);
        }
      } else {
        final xfiles = await ImagePicker().pickMultiImage();
        for (final f in xfiles) {
          picked.add(await f.readAsBytes());
          names.add(f.name);
        }
      }
    } catch (e) {
      _showSnack('Failed to pick photo: $e');
      return;
    }
    if (picked.isEmpty) return;
    final remaining = 10 - _files.length;
    if (picked.length > remaining) {
      _showSnack('Only $remaining more file(s) can be added (max 10).');
      picked = picked.sublist(0, remaining);
      names = names.sublist(0, remaining);
    }
    setState(() => _busy = true);
    final compressed = <Uint8List>[];
    final compressedNames = <String>[];
    var skippedTooLarge = 0;
    for (var i = 0; i < picked.length; i++) {
      Uint8List result;
      try {
        result = await compute(_compressInspectionPhotoBytes, picked[i]);
      } catch (_) {
        result = picked[i];
      }
      // Compression already targets 5MB internally, but re-check against
      // this component's own 6MB limit defensively (e.g. if compression
      // silently fell back to the uncompressed original above).
      if (result.length > _maxImageBytes) {
        skippedTooLarge++;
        continue;
      }
      compressed.add(result);
      compressedNames.add(i < names.length ? names[i] : 'photo_${i + 1}.jpg');
    }
    if (!mounted) return;
    setState(() {
      for (var i = 0; i < compressed.length; i++) {
        _files.add(
          _QuotationFileItem(
            bytes: compressed[i],
            name: compressedNames[i],
            isPdf: false,
          ),
        );
      }
      _busy = false;
    });
    if (skippedTooLarge > 0) {
      _showSnack('$skippedTooLarge photo(s) skipped — still over 6MB after compression.');
    }
  }

  Future<void> _addPdf() async {
    if (_files.length >= 10) {
      _showSnack('Maximum 10 files.');
      return;
    }
    List<PlatformFile> picked;
    try {
      picked = await FilePicker.pickFiles(
        type: FileType.custom,
        allowedExtensions: ['pdf'],
      );
    } catch (e) {
      _showSnack('Failed to pick PDF: $e');
      return;
    }
    if (picked.isEmpty) return;
    final file = picked.first;
    final bytes = await file.readAsBytes();
    if (bytes.length > _maxPdfBytes) {
      _showSnack('PDF must be under 10MB.');
      return;
    }
    setState(() {
      _files.add(
        _QuotationFileItem(bytes: bytes, name: file.name, isPdf: true),
      );
    });
  }

  Future<void> _showAddSheet() async {
    if (_files.length >= 10) {
      _showSnack('Maximum 10 files.');
      return;
    }
    final choice = await showModalBottomSheet<String>(
      context: context,
      builder: (sheetContext) => SafeArea(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            ListTile(
              leading: const Icon(Icons.camera_alt, color: AppColors.primary),
              title: const Text('Take Photo'),
              onTap: () => Navigator.pop(sheetContext, 'camera'),
            ),
            ListTile(
              leading: const Icon(Icons.photo_library, color: AppColors.primary),
              title: Text(kIsWeb ? 'Choose Files' : 'Choose from Gallery'),
              onTap: () => Navigator.pop(sheetContext, 'gallery'),
            ),
            if (!widget.photosOnly)
              ListTile(
                leading: const Icon(Icons.picture_as_pdf, color: AppColors.primary),
                title: const Text('Choose PDF'),
                onTap: () => Navigator.pop(sheetContext, 'pdf'),
              ),
          ],
        ),
      ),
    );
    if (choice == 'camera') {
      await _addPhoto(true);
    } else if (choice == 'gallery') {
      await _addPhoto(false);
    } else if (choice == 'pdf') {
      await _addPdf();
    }
  }

  void _removeFile(int index) {
    setState(() {
      final removed = _files.removeAt(index);
      if (removed.path != null) _removedStoragePaths.add(removed.path!);
    });
  }

  Future<QuotationFileResult> uploadAndFinalize(String storagePathPrefix) async {
    _lastStoragePathPrefix = storagePathPrefix;
    var hadFailures = false;

    for (final path in _removedStoragePaths) {
      try {
        await FirebaseStorage.instance.ref(path).delete();
      } catch (_) {}
    }
    _removedStoragePaths.clear();

    for (var i = 0; i < _files.length; i++) {
      final item = _files[i];
      if (item.url != null) continue;
      if (mounted) setState(() => item.uploading = true);
      try {
        final n = i + 1;
        final ext = item.isPdf ? 'pdf' : 'jpg';
        final path =
            '$storagePathPrefix/files/${n}_${DateTime.now().millisecondsSinceEpoch}.$ext';
        final ref = FirebaseStorage.instance.ref(path);
        await ref.putData(
          item.bytes!,
          SettableMetadata(
            contentType: item.isPdf ? 'application/pdf' : 'image/jpeg',
          ),
        );
        item.url = await ref.getDownloadURL();
        item.path = path;
        item.error = null;
      } catch (e) {
        item.error = e.toString();
        hadFailures = true;
      } finally {
        if (mounted) setState(() => item.uploading = false);
      }
    }

    final files = <Map<String, dynamic>>[];
    for (var i = 0; i < _files.length; i++) {
      final item = _files[i];
      if (item.url == null) continue;
      files.add({
        'n': i + 1,
        'url': item.url,
        'path': item.path,
        'name': item.name,
      });
    }
    return QuotationFileResult(files: files, hadFailures: hadFailures);
  }

  Future<void> _retryFailed() async {
    final prefix = _lastStoragePathPrefix;
    if (prefix == null || _retrying) return;
    setState(() => _retrying = true);
    try {
      final result = await uploadAndFinalize(prefix);
      if (widget.onRetrySaved != null) await widget.onRetrySaved!(result);
    } finally {
      if (mounted) setState(() => _retrying = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Row(
          children: [
            Text('${widget.label} (${_files.length}/10)', style: AppText.section),
            const Spacer(),
            TextButton.icon(
              onPressed: (_files.length >= 10 || _busy) ? null : _showAddSheet,
              icon: const Icon(Icons.attach_file, size: 18),
              label: const Text('Add File'),
            ),
          ],
        ),
        if (_files.isNotEmpty)
          Wrap(
            spacing: 8,
            runSpacing: 8,
            children: List.generate(_files.length, (index) {
              final item = _files[index];
              return SizedBox(
                width: 84,
                height: 84,
                child: Stack(
                  children: [
                    Positioned.fill(
                      child: ClipRRect(
                        borderRadius: BorderRadius.circular(8),
                        child: item.isPdf
                            ? Container(
                                color: AppColors.background,
                                alignment: Alignment.center,
                                child: const Icon(
                                  Icons.picture_as_pdf,
                                  color: AppColors.danger,
                                  size: 32,
                                ),
                              )
                            : item.bytes != null
                            ? Image.memory(item.bytes!, fit: BoxFit.cover)
                            : Image.network(
                                item.url!,
                                fit: BoxFit.cover,
                                cacheWidth: 252,
                                cacheHeight: 252,
                                errorBuilder: (_, __, ___) => Container(
                                  color: Colors.grey[300],
                                  child: const Icon(Icons.broken_image),
                                ),
                              ),
                      ),
                    ),
                    Positioned(
                      top: 3,
                      left: 3,
                      child: CircleAvatar(
                        radius: 10,
                        backgroundColor: Colors.black54,
                        child: Text(
                          '${index + 1}',
                          style: const TextStyle(
                            fontSize: 11,
                            color: Colors.white,
                          ),
                        ),
                      ),
                    ),
                    Positioned(
                      top: 0,
                      right: 0,
                      child: InkWell(
                        onTap: () => _removeFile(index),
                        child: const CircleAvatar(
                          radius: 10,
                          backgroundColor: AppColors.danger,
                          child: Icon(Icons.close, size: 13, color: Colors.white),
                        ),
                      ),
                    ),
                    if (item.uploading)
                      const Positioned.fill(
                        child: ColoredBox(
                          color: Colors.black38,
                          child: Center(
                            child: SizedBox(
                              width: 20,
                              height: 20,
                              child: CircularProgressIndicator(
                                strokeWidth: 2,
                                color: Colors.white,
                              ),
                            ),
                          ),
                        ),
                      ),
                    if (item.error != null)
                      Positioned(
                        bottom: 0,
                        left: 0,
                        right: 0,
                        child: Container(
                          color: AppColors.danger.withOpacity(0.85),
                          padding: const EdgeInsets.symmetric(vertical: 2),
                          child: const Icon(
                            Icons.error_outline,
                            size: 14,
                            color: Colors.white,
                          ),
                        ),
                      ),
                  ],
                ),
              );
            }),
          ),
        if (_hasFailures)
          Container(
            margin: const EdgeInsets.only(top: 8),
            padding: const EdgeInsets.all(10),
            decoration: BoxDecoration(
              color: AppColors.dangerBg,
              borderRadius: BorderRadius.circular(8),
              border: Border.all(color: AppColors.danger),
            ),
            child: Row(
              children: [
                const Icon(Icons.error_outline, color: AppColors.danger, size: 18),
                const SizedBox(width: 8),
                const Expanded(
                  child: Text(
                    'Some files failed to upload.',
                    style: TextStyle(fontSize: 12),
                  ),
                ),
                TextButton(
                  onPressed: _retrying ? null : _retryFailed,
                  child: _retrying
                      ? const SizedBox(
                          width: 16,
                          height: 16,
                          child: CircularProgressIndicator(strokeWidth: 2),
                        )
                      : const Text('RETRY'),
                ),
              ],
            ),
          ),
      ],
    );
  }
}


// ---------------- REPAIR GARAGES ----------------
Future<Map<String, String>?> _showGaragePicker(BuildContext context) {
  return showModalBottomSheet<Map<String, String>>(
    context: context,
    isScrollControlled: true,
    shape: const RoundedRectangleBorder(
      borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
    ),
    builder: (sheetContext) {
      String searchText = '';
      return StatefulBuilder(
        builder: (sheetContext, setSheetState) {
          return Padding(
            padding: EdgeInsets.only(
              bottom: MediaQuery.of(sheetContext).viewInsets.bottom,
            ),
            child: SizedBox(
              height: MediaQuery.of(sheetContext).size.height * 0.75,
              child: Column(
                children: [
                  const SizedBox(height: 12),
                  Container(
                    width: 40,
                    height: 4,
                    decoration: BoxDecoration(
                      color: Colors.grey[300],
                      borderRadius: BorderRadius.circular(2),
                    ),
                  ),
                  Padding(
                    padding: const EdgeInsets.all(16),
                    child: TextField(
                      autofocus: true,
                      inputFormatters: [UpperCaseTextFormatter()],
                      textCapitalization: TextCapitalization.characters,
                      decoration: InputDecoration(
                        hintText: 'Search garage name',
                        prefixIcon: const Icon(Icons.search),
                        border: OutlineInputBorder(
                          borderRadius: BorderRadius.circular(12),
                        ),
                      ),
                      onChanged: (val) => setSheetState(() => searchText = val),
                    ),
                  ),
                  Expanded(
                    child: StreamBuilder<QuerySnapshot>(
                      stream: FirebaseFirestore.instance
                          .collection('repair_garages')
                          .where('isActive', isEqualTo: true)
                          .snapshots(),
                      builder: (context, snapshot) {
                        if (!snapshot.hasData) {
                          return const Center(child: CircularProgressIndicator());
                        }
                        final filtered = snapshot.data!.docs.where((doc) {
                              final name =
                                  ((doc.data() as Map<String, dynamic>)['name'] ?? '')
                                      .toString();
                              return name.toLowerCase().contains(
                                searchText.toLowerCase(),
                              );
                            }).toList()
                          ..sort((a, b) {
                            final an =
                                ((a.data() as Map<String, dynamic>)['name'] ?? '')
                                    .toString();
                            final bn =
                                ((b.data() as Map<String, dynamic>)['name'] ?? '')
                                    .toString();
                            return an.compareTo(bn);
                          });
                        return ListView(
                          children: [
                            ...filtered.map((doc) {
                              final data = doc.data() as Map<String, dynamic>;
                              return ListTile(
                                leading: const Icon(
                                  Icons.garage,
                                  color: AppColors.primary,
                                ),
                                title: Text((data['name'] ?? '').toString()),
                                subtitle: Text(
                                  (data['contactPerson'] ?? '').toString(),
                                ),
                                onTap: () => Navigator.pop(sheetContext, {
                                  'id': doc.id,
                                  'name': (data['name'] ?? '').toString(),
                                }),
                              );
                            }),
                            if (searchText.trim().isNotEmpty)
                              ListTile(
                                leading: const Icon(
                                  Icons.add_circle,
                                  color: AppColors.success,
                                ),
                                title: Text(
                                  'Add "${searchText.trim()}" as a new garage',
                                ),
                                onTap: () async {
                                  final uid =
                                      FirebaseAuth.instance.currentUser?.uid ?? '';
                                  final userDoc = await FirebaseFirestore.instance
                                      .collection('users')
                                      .doc(uid)
                                      .get();
                                  final userName =
                                      (userDoc.data()?['name'] ?? 'Unknown')
                                          .toString();
                                  final newRef = await FirebaseFirestore.instance
                                      .collection('repair_garages')
                                      .add({
                                        'name': searchText.trim().toUpperCase(),
                                        'address': '',
                                        'contactPerson': '',
                                        'phone': '',
                                        'registrationNo': '',
                                        'taxNo': '',
                                        'isActive': true,
                                        'createdBy': uid,
                                        'createdByName': userName,
                                        'createdAt': FieldValue.serverTimestamp(),
                                        'updatedBy': uid,
                                        'updatedByName': userName,
                                        'updatedAt': FieldValue.serverTimestamp(),
                                      });
                                  if (sheetContext.mounted) {
                                    Navigator.pop(sheetContext, {
                                      'id': newRef.id,
                                      'name': searchText.trim().toUpperCase(),
                                    });
                                  }
                                },
                              ),
                          ],
                        );
                      },
                    ),
                  ),
                ],
              ),
            ),
          );
        },
      );
    },
  );
}

class RepairGaragesScreen extends StatefulWidget {
  const RepairGaragesScreen({super.key});

  @override
  State<RepairGaragesScreen> createState() => _RepairGaragesScreenState();
}

class _RepairGaragesScreenState extends State<RepairGaragesScreen> {
  final _searchController = TextEditingController();
  String _searchText = '';

  late final Future<bool> _isAdminOrOwner = _currentUserHasRepairPerm(kPermGarages);

  late final Stream<QuerySnapshot> _garagesStream =
      FirebaseFirestore.instance.collection('repair_garages').snapshots();

  @override
  void dispose() {
    _searchController.dispose();
    super.dispose();
  }

  Future<void> _showAddEditDialog({DocumentSnapshot? existing}) async {
    final data = existing?.data() as Map<String, dynamic>?;
    final nameController = TextEditingController(
      text: (data?['name'] ?? '').toString(),
    );
    final addressController = TextEditingController(
      text: (data?['address'] ?? '').toString(),
    );
    final contactController = TextEditingController(
      text: (data?['contactPerson'] ?? '').toString(),
    );
    final phoneController = TextEditingController(
      text: (data?['phone'] ?? '').toString(),
    );
    final regNoController = TextEditingController(
      text: (data?['registrationNo'] ?? '').toString(),
    );
    final taxNoController = TextEditingController(
      text: (data?['taxNo'] ?? '').toString(),
    );

    await showDialog(
      context: context,
      builder: (dialogContext) => AlertDialog(
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(AppRadius.card),
        ),
        title: Text(existing == null ? 'Add Garage' : 'Edit Garage'),
        content: SizedBox(
          width: 420,
          child: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                TextField(
                  controller: nameController,
                  inputFormatters: [UpperCaseTextFormatter()],
                  textCapitalization: TextCapitalization.characters,
                  decoration: const InputDecoration(labelText: 'Garage Name'),
                ),
                const SizedBox(height: 10),
                TextField(
                  controller: addressController,
                  inputFormatters: [UpperCaseTextFormatter()],
                  textCapitalization: TextCapitalization.characters,
                  decoration: const InputDecoration(labelText: 'Address'),
                ),
                const SizedBox(height: 10),
                TextField(
                  controller: contactController,
                  inputFormatters: [UpperCaseTextFormatter()],
                  textCapitalization: TextCapitalization.characters,
                  decoration: const InputDecoration(
                    labelText: 'Contact Person',
                  ),
                ),
                const SizedBox(height: 10),
                TextField(
                  controller: phoneController,
                  keyboardType: TextInputType.phone,
                  decoration: const InputDecoration(labelText: 'Phone'),
                ),
                const SizedBox(height: 10),
                TextField(
                  controller: regNoController,
                  inputFormatters: [UpperCaseTextFormatter()],
                  textCapitalization: TextCapitalization.characters,
                  decoration: const InputDecoration(
                    labelText: 'Registration No. (optional)',
                  ),
                ),
                const SizedBox(height: 10),
                TextField(
                  controller: taxNoController,
                  inputFormatters: [UpperCaseTextFormatter()],
                  textCapitalization: TextCapitalization.characters,
                  decoration: const InputDecoration(
                    labelText: 'Tax No. (optional)',
                  ),
                ),
              ],
            ),
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext),
            child: const Text('Cancel'),
          ),
          ElevatedButton(
            onPressed: () async {
              if (nameController.text.trim().isEmpty) return;
              final uid = FirebaseAuth.instance.currentUser?.uid ?? '';
              final userDoc = await FirebaseFirestore.instance
                  .collection('users')
                  .doc(uid)
                  .get();
              final userName =
                  (userDoc.data()?['name'] ?? 'Unknown').toString();
              if (existing == null) {
                await FirebaseFirestore.instance
                    .collection('repair_garages')
                    .add({
                      'name': nameController.text.trim(),
                      'address': addressController.text.trim(),
                      'contactPerson': contactController.text.trim(),
                      'phone': phoneController.text.trim(),
                      'registrationNo': regNoController.text.trim(),
                      'taxNo': taxNoController.text.trim(),
                      'isActive': true,
                      'createdBy': uid,
                      'createdByName': userName,
                      'createdAt': FieldValue.serverTimestamp(),
                      'updatedBy': uid,
                      'updatedByName': userName,
                      'updatedAt': FieldValue.serverTimestamp(),
                    });
              } else {
                await existing.reference.update({
                  'name': nameController.text.trim(),
                  'address': addressController.text.trim(),
                  'contactPerson': contactController.text.trim(),
                  'phone': phoneController.text.trim(),
                  'registrationNo': regNoController.text.trim(),
                  'taxNo': taxNoController.text.trim(),
                  'updatedBy': uid,
                  'updatedByName': userName,
                  'updatedAt': FieldValue.serverTimestamp(),
                });
              }
              if (dialogContext.mounted) Navigator.pop(dialogContext);
            },
            child: const Text('SAVE'),
          ),
        ],
      ),
    );
  }

  Future<void> _toggleActive(DocumentSnapshot doc, bool newValue) async {
    final uid = FirebaseAuth.instance.currentUser?.uid ?? '';
    final userDoc =
        await FirebaseFirestore.instance.collection('users').doc(uid).get();
    final userName = (userDoc.data()?['name'] ?? 'Unknown').toString();
    await doc.reference.update({
      'isActive': newValue,
      'updatedBy': uid,
      'updatedByName': userName,
      'updatedAt': FieldValue.serverTimestamp(),
    });
  }

  @override
  Widget build(BuildContext context) {
    return TruckRepairScaffold(
      appBar: AppBar(
        title: const Text('Repair Garages'),
        backgroundColor: AppColors.navy,
        foregroundColor: Colors.white,
      ),
      body: FutureBuilder<bool>(
        future: _isAdminOrOwner,
        builder: (context, adminSnap) {
          final canManage = adminSnap.data == true;
          return Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              TextField(
                controller: _searchController,
                inputFormatters: [UpperCaseTextFormatter()],
                textCapitalization: TextCapitalization.characters,
                decoration: const InputDecoration(
                  hintText: 'Search garage name',
                  prefixIcon: Icon(Icons.search),
                ),
                onChanged: (val) => setState(() => _searchText = val),
              ),
              const SizedBox(height: AppSpacing.md),
              Expanded(
                child: StreamBuilder<QuerySnapshot>(
                  stream: _garagesStream,
                  builder: (context, snapshot) {
                    if (snapshot.hasError) {
                      return ErrorState(
                        message: 'Failed to load garages: ${snapshot.error}',
                        onRetry: () => setState(() {}),
                      );
                    }
                    if (snapshot.connectionState == ConnectionState.waiting &&
                        !snapshot.hasData) {
                      return const LoadingState();
                    }
                    final trimmedSearch = _searchText.trim().toLowerCase();
                    final docs = (snapshot.data?.docs ?? []).where((doc) {
                          if (trimmedSearch.isEmpty) return true;
                          final name =
                              ((doc.data() as Map<String, dynamic>)['name'] ?? '')
                                  .toString()
                                  .toLowerCase();
                          return name.contains(trimmedSearch);
                        }).toList()
                      ..sort((a, b) {
                        final an =
                            ((a.data() as Map<String, dynamic>)['name'] ?? '')
                                .toString();
                        final bn =
                            ((b.data() as Map<String, dynamic>)['name'] ?? '')
                                .toString();
                        return an.compareTo(bn);
                      });

                    if (docs.isEmpty) {
                      return const EmptyState(
                        icon: Icons.garage,
                        title: 'No repair garages yet.',
                      );
                    }

                    return ListView.builder(
                      padding: const EdgeInsets.all(AppSpacing.md),
                      itemCount: docs.length,
                      itemBuilder: (context, index) {
                        final doc = docs[index];
                        final data = doc.data() as Map<String, dynamic>;
                        final isActive = data['isActive'] != false;
                        return AppStaggeredFadeIn(
                          index: index,
                          child: Padding(
                            padding: const EdgeInsets.only(
                              bottom: AppSpacing.sm,
                            ),
                            child: AppCard(
                              onTap: canManage
                                  ? () => _showAddEditDialog(existing: doc)
                                  : null,
                              child: Row(
                                children: [
                                  Expanded(
                                    child: Column(
                                      crossAxisAlignment:
                                          CrossAxisAlignment.start,
                                      children: [
                                        Text(
                                          (data['name'] ?? '').toString(),
                                          style: AppText.section,
                                        ),
                                        Text(
                                          '${data['contactPerson'] ?? ''} • '
                                          '${data['phone'] ?? ''}',
                                          style: AppText.caption,
                                        ),
                                      ],
                                    ),
                                  ),
                                  StatusChip(
                                    status: isActive ? 'ACTIVE' : 'INACTIVE',
                                  ),
                                  if (canManage)
                                    Switch(
                                      value: isActive,
                                      onChanged: (val) =>
                                          _toggleActive(doc, val),
                                    ),
                                ],
                              ),
                            ),
                          ),
                        );
                      },
                    );
                  },
                ),
              ),
              if (canManage)
                Padding(
                  padding: const EdgeInsets.only(top: AppSpacing.md),
                  child: SizedBox(
                    width: double.infinity,
                    child: ElevatedButton.icon(
                      onPressed: () => _showAddEditDialog(),
                      icon: const Icon(Icons.add),
                      label: const Text('ADD GARAGE'),
                    ),
                  ),
                )
              else
                Padding(
                  padding: const EdgeInsets.only(top: AppSpacing.md),
                  child: Text(
                    'Read-only for your role.',
                    style: AppText.caption,
                  ),
                ),
            ],
          );
        },
      ),
    );
  }
}

// ---------------- REPAIR SETTINGS (admin/owner only edit) ----------------
// ---------------- WORKFLOW INSPECTOR (admin/owner) ----------------
// Pick a repair job and see exactly where it's stuck: every quotation,
// approval, the invoice, payments, the computed next step, and an
// ENABLED/DISABLED + reason line for each of the main action buttons —
// all read-only, for diagnosing a stalled job without guessing.
class WorkflowInspectorScreen extends StatefulWidget {
  const WorkflowInspectorScreen({super.key});

  @override
  State<WorkflowInspectorScreen> createState() => _WorkflowInspectorScreenState();
}

class _WorkflowInspectorScreenState extends State<WorkflowInspectorScreen> {
  final _searchController = TextEditingController();
  String _search = '';
  String? _selectedJobId;
  // Cached once (same pattern as RepairJobsScreen's own _recordsStream) —
  // the query never varies with _search/_selectedJobId (filtering is all
  // client-side below), so this must not sit inline in build(): every
  // search-box keystroke calls setState, and a literal
  // `FirebaseFirestore.instance...snapshots()` written directly in the
  // StreamBuilder's `stream:` property would tear down and resubscribe a
  // brand-new listener — re-fetching the whole collection — on every
  // keystroke instead of once.
  late final Stream<QuerySnapshot> _jobsStream =
      FirebaseFirestore.instance.collection('repair_jobs').snapshots();

  @override
  void dispose() {
    _searchController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return TruckRepairScaffold(
      appBar: AppBar(
        title: const Text('Workflow Inspector'),
        backgroundColor: AppColors.navy,
        foregroundColor: Colors.white,
      ),
      body: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Padding(
            padding: const EdgeInsets.only(bottom: AppSpacing.md),
            child: TextField(
              controller: _searchController,
              inputFormatters: [UpperCaseTextFormatter()],
              textCapitalization: TextCapitalization.characters,
              decoration: const InputDecoration(
                hintText: 'SEARCH BY JOB NO. OR VEHICLE NUMBER',
                prefixIcon: Icon(Icons.search),
              ),
              onChanged: (v) => setState(() => _search = v.trim()),
            ),
          ),
          if (_selectedJobId == null)
            Expanded(
              child: StreamBuilder<QuerySnapshot>(
                stream: _jobsStream,
                builder: (context, snap) {
                  if (snap.hasError) {
                    return ErrorState(
                      message: 'Failed to load: ${snap.error}',
                      onRetry: () => setState(() {}),
                    );
                  }
                  if (!snap.hasData) return const LoadingState();
                  var docs = snap.data!.docs;
                  if (_search.isNotEmpty) {
                    docs = docs.where((d) {
                      final m = d.data() as Map<String, dynamic>;
                      final jobNo = (m['jobNo'] ?? '').toString();
                      final vehicle = (m['vehicleNumber'] ?? '').toString();
                      return jobNo.contains(_search) || vehicle.contains(_search);
                    }).toList();
                  }
                  if (docs.isEmpty) {
                    return const EmptyState(icon: Icons.search_off, title: 'NO JOBS FOUND');
                  }
                  return ListView.builder(
                    itemCount: docs.length,
                    itemBuilder: (context, i) {
                      final m = docs[i].data() as Map<String, dynamic>;
                      return ListTile(
                        title: Text('${m['jobNo'] ?? ''} — ${m['vehicleNumber'] ?? ''}'),
                        subtitle: Text((m['repairStatus'] ?? '').toString()),
                        onTap: () => setState(() => _selectedJobId = docs[i].id),
                      );
                    },
                  );
                },
              ),
            )
          else
            Expanded(
              child: _WorkflowInspectorDetail(
                jobId: _selectedJobId!,
                onBack: () => setState(() => _selectedJobId = null),
              ),
            ),
        ],
      ),
    );
  }
}

class _WorkflowInspectorDetail extends StatelessWidget {
  final String jobId;
  final VoidCallback onBack;
  const _WorkflowInspectorDetail({required this.jobId, required this.onBack});

  Widget _kv(String k, String v) => Padding(
        padding: const EdgeInsets.only(bottom: 2),
        child: Row(
          children: [
            SizedBox(width: 160, child: Text(k, style: AppText.caption)),
            Expanded(child: Text(v, style: AppText.body)),
          ],
        ),
      );

  @override
  Widget build(BuildContext context) {
    return StreamBuilder<DocumentSnapshot>(
      stream: FirebaseFirestore.instance.collection('repair_jobs').doc(jobId).snapshots(),
      builder: (context, jobSnap) {
        if (!jobSnap.hasData) return const LoadingState();
        if (!jobSnap.data!.exists) {
          return const EmptyState(icon: Icons.error_outline, title: 'Job no longer exists.');
        }
        final job = jobSnap.data!.data() as Map<String, dynamic>;
        return StreamBuilder<QuerySnapshot>(
          stream: FirebaseFirestore.instance
              .collection('repair_quotations')
              .where('repairJobId', isEqualTo: jobId)
              .snapshots(),
          builder: (context, qSnap) {
            final quotations = (qSnap.data?.docs ?? []).map((d) {
              final m = Map<String, dynamic>.from(d.data() as Map<String, dynamic>);
              m['_id'] = d.id;
              return m;
            }).toList();
            return StreamBuilder<QuerySnapshot>(
              stream: FirebaseFirestore.instance
                  .collection('repair_approvals')
                  .where('repairJobId', isEqualTo: jobId)
                  .snapshots(),
              builder: (context, aSnap) {
                final approvals = (aSnap.data?.docs ?? [])
                    .map((d) => d.data() as Map<String, dynamic>)
                    .toList();
                final invoiceId = job['invoiceId'] as String?;
                return FutureBuilder<Map<String, dynamic>?>(
                  future: invoiceId == null
                      ? Future.value(null)
                      : FirebaseFirestore.instance
                          .collection('repair_invoices')
                          .doc(invoiceId)
                          .get()
                          .then((s) => s.data()),
                  builder: (context, invSnap) {
                    final invoice = invSnap.data;
                    return FutureBuilder<Map<String, dynamic>?>(
                      future: () async {
                        final uid = FirebaseAuth.instance.currentUser?.uid;
                        if (uid == null) return null;
                        final doc = await FirebaseFirestore.instance
                            .collection('users')
                            .doc(uid)
                            .get();
                        return doc.data();
                      }(),
                      builder: (context, userSnap) {
                        final userData = userSnap.data;
                        final role = userData?['role'] as String?;
                        final isAdminOrOwner = role == 'admin' || role == 'owner';
                        final perms = ((userData?['repairPermissions'] as List?) ?? const [])
                            .map((e) => e.toString())
                            .toSet();
                        final step = nextStepFor(
                          job: job,
                          quotations: quotations,
                          isAdminOrOwner: isAdminOrOwner,
                          userPerms: perms,
                          currentUid: FirebaseAuth.instance.currentUser?.uid,
                        );
                        return SingleChildScrollView(
                          padding: const EdgeInsets.all(AppSpacing.md),
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              OutlinedButton.icon(
                                onPressed: onBack,
                                icon: const Icon(Icons.arrow_back, size: 16),
                                label: const Text('BACK TO SEARCH'),
                              ),
                              const SizedBox(height: AppSpacing.md),
                              AppCard(
                                child: Column(
                                  crossAxisAlignment: CrossAxisAlignment.start,
                                  children: [
                                    Text('Job', style: AppText.section),
                                    const Divider(),
                                    _kv('jobNo', '${job['jobNo']}'),
                                    _kv('vehicleNumber', '${job['vehicleNumber']}'),
                                    _kv('repairStatus', '${job['repairStatus']}'),
                                    _kv('selectedQuotationId', '${job['selectedQuotationId']}'),
                                    _kv('approvedAmountCents', '${job['approvedAmountCents']}'),
                                    _kv('additionalCostPending', '${job['additionalCostPending']}'),
                                    _kv('invoiceId', '${job['invoiceId']}'),
                                    _kv('paymentStatus', '${job['paymentStatus']}'),
                                  ],
                                ),
                              ),
                              const SizedBox(height: AppSpacing.md),
                              AppCard(
                                child: Column(
                                  crossAxisAlignment: CrossAxisAlignment.start,
                                  children: [
                                    Text('Quotations (${quotations.length})', style: AppText.section),
                                    const Divider(),
                                    if (quotations.isEmpty) const Text('None.'),
                                    ...quotations.map((q) => Padding(
                                          padding: const EdgeInsets.only(bottom: 6),
                                          child: Text(
                                            '${q['_id']} — status=${q['status']} '
                                            'selected=${q['_id'] == job['selectedQuotationId']} '
                                            'verifiedBy=${(q['verification'] as Map?)?['verifiedBy']} '
                                            'total=${_formatMoney(_centsToMoney((q['totalCents'] as num?)?.toInt() ?? 0))}',
                                            style: AppText.caption,
                                          ),
                                        )),
                                  ],
                                ),
                              ),
                              const SizedBox(height: AppSpacing.md),
                              AppCard(
                                child: Column(
                                  crossAxisAlignment: CrossAxisAlignment.start,
                                  children: [
                                    Text('Approvals (${approvals.length})', style: AppText.section),
                                    const Divider(),
                                    if (approvals.isEmpty) const Text('None.'),
                                    ...approvals.map((a) => Padding(
                                          padding: const EdgeInsets.only(bottom: 6),
                                          child: Text(
                                            'decision=${a['decision']} level=${a['requiredLevel']} '
                                            'amount=${_formatMoney(_centsToMoney((a['amountCents'] as num?)?.toInt() ?? 0))} '
                                            'type=${a['approvalType'] ?? 'QUOTATION'}',
                                            style: AppText.caption,
                                          ),
                                        )),
                                  ],
                                ),
                              ),
                              const SizedBox(height: AppSpacing.md),
                              AppCard(
                                child: Column(
                                  crossAxisAlignment: CrossAxisAlignment.start,
                                  children: [
                                    Text('Invoice & Payments', style: AppText.section),
                                    const Divider(),
                                    if (invoice == null)
                                      const Text('No invoice yet.')
                                    else ...[
                                      _kv('verification.status',
                                          '${(invoice['verification'] as Map?)?['status']}'),
                                      _kv('totalCents', '${invoice['totalCents']}'),
                                      _kv('paidCents', '${invoice['paidCents']}'),
                                      _kv('outstandingCents', '${invoice['outstandingCents']}'),
                                      _kv('paymentStatus', '${invoice['paymentStatus']}'),
                                    ],
                                  ],
                                ),
                              ),
                              const SizedBox(height: AppSpacing.md),
                              AppCard(
                                child: Column(
                                  crossAxisAlignment: CrossAxisAlignment.start,
                                  children: [
                                    Text('Computed Next Step', style: AppText.section),
                                    const Divider(),
                                    _kv('title', step.title),
                                    _kv('description', step.description),
                                    _kv('actionable', '${step.actionable}'),
                                    if (step.disabledReason != null)
                                      _kv('disabledReason', step.disabledReason!),
                                  ],
                                ),
                              ),
                              const SizedBox(height: AppSpacing.md),
                              AppCard(
                                child: Column(
                                  crossAxisAlignment: CrossAxisAlignment.start,
                                  children: [
                                    Text('Button Status', style: AppText.section),
                                    const Divider(),
                                    _kv(
                                      'DIAGNOSE',
                                      isAdminOrOwner || perms.contains(kPermDiagnose)
                                          ? 'ENABLED'
                                          : 'DISABLED — needs DIAGNOSE permission',
                                    ),
                                    _kv(
                                      'QUOTATIONS (add/revise/select)',
                                      isAdminOrOwner || perms.contains(kPermQuotations)
                                          ? 'ENABLED'
                                          : 'DISABLED — needs QUOTATIONS permission',
                                    ),
                                    _kv(
                                      'VERIFY_QUOTATION',
                                      isAdminOrOwner || perms.contains(kPermVerifyQuotation)
                                          ? 'ENABLED (subject to identity exclusion)'
                                          : 'DISABLED — needs VERIFY_QUOTATION permission',
                                    ),
                                    _kv(
                                      'REQUEST_APPROVAL',
                                      isAdminOrOwner || perms.contains(kPermRequestApproval)
                                          ? 'ENABLED'
                                          : 'DISABLED — needs REQUEST_APPROVAL permission',
                                    ),
                                    _kv(
                                      'APPROVE',
                                      isAdminOrOwner || perms.contains(kPermApprove)
                                          ? 'ENABLED (subject to identity exclusion + level)'
                                          : 'DISABLED — needs APPROVE permission',
                                    ),
                                    _kv(
                                      'REPAIR_WORK',
                                      isAdminOrOwner || perms.contains(kPermRepairWork)
                                          ? 'ENABLED'
                                          : 'DISABLED — needs REPAIR_WORK permission',
                                    ),
                                    _kv(
                                      'FINAL_INSPECTION',
                                      isAdminOrOwner || perms.contains(kPermFinalInspection)
                                          ? 'ENABLED (subject to identity exclusion)'
                                          : 'DISABLED — needs FINAL_INSPECTION permission',
                                    ),
                                    _kv(
                                      'INVOICES',
                                      isAdminOrOwner || perms.contains(kPermInvoices)
                                          ? 'ENABLED'
                                          : 'DISABLED — needs INVOICES permission',
                                    ),
                                    _kv(
                                      'VERIFY_INVOICE',
                                      isAdminOrOwner || perms.contains(kPermVerifyInvoice)
                                          ? 'ENABLED (subject to identity exclusion)'
                                          : 'DISABLED — needs VERIFY_INVOICE permission',
                                    ),
                                    _kv(
                                      'PAYMENTS',
                                      isAdminOrOwner || perms.contains(kPermPayments)
                                          ? 'ENABLED'
                                          : 'DISABLED — needs PAYMENTS permission',
                                    ),
                                    _kv(
                                      'CLOSE_JOB',
                                      isAdminOrOwner || perms.contains(kPermCloseJob)
                                          ? 'ENABLED'
                                          : 'DISABLED — needs CLOSE_JOB permission',
                                    ),
                                  ],
                                ),
                              ),
                            ],
                          ),
                        );
                      },
                    );
                  },
                );
              },
            );
          },
        );
      },
    );
  }
}

class RepairSettingsScreen extends StatefulWidget {
  const RepairSettingsScreen({super.key});

  @override
  State<RepairSettingsScreen> createState() => _RepairSettingsScreenState();
}

class _RepairSettingsScreenState extends State<RepairSettingsScreen> {
  final _managerLimitController = TextEditingController();
  final _multiQuoteThresholdController = TextEditingController();
  final _multiQuoteMinCountController = TextEditingController();
  bool _loading = true;
  bool _saving = false;
  bool _canEdit = false;
  bool _testModeOn = false;
  bool _togglingTestMode = false;
  bool _simpleModeOn = true;
  bool _togglingSimpleMode = false;
  bool _requireDailyCheckOn = true;
  bool _togglingRequireDailyCheck = false;

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    final uid = FirebaseAuth.instance.currentUser?.uid;
    if (uid != null) {
      final userDoc =
          await FirebaseFirestore.instance.collection('users').doc(uid).get();
      final role = userDoc.data()?['role'] as String?;
      _canEdit = role == 'admin' || role == 'owner';
    }
    final settings = await _fetchRepairWorkflowSettings();
    _managerLimitController.text = settings.managerApprovalLimit.toString();
    _multiQuoteThresholdController.text =
        settings.multiQuotationThreshold.toString();
    _multiQuoteMinCountController.text =
        settings.multiQuotationMinCount.toString();
    _testModeOn = settings.testModeAllowSameUser;
    _simpleModeOn = settings.simpleMode;
    _requireDailyCheckOn = settings.requireDailyCheck;
    if (mounted) setState(() => _loading = false);
  }

  Future<void> _toggleRequireDailyCheck(bool newValue) async {
    setState(() => _togglingRequireDailyCheck = true);
    try {
      final uid = FirebaseAuth.instance.currentUser?.uid ?? '';
      final userDoc =
          await FirebaseFirestore.instance.collection('users').doc(uid).get();
      final userName = (userDoc.data()?['name'] ?? 'Unknown').toString();
      await FirebaseFirestore.instance
          .collection('settings')
          .doc('repair_workflow')
          .set({'requireDailyCheck': newValue}, SetOptions(merge: true));
      await _writeRepairEvent(
        collection: 'settings',
        docId: 'repair_workflow',
        action: newValue ? 'REQUIRE_DAILY_CHECK_ON' : 'REQUIRE_DAILY_CHECK_OFF',
        summary:
            'Require Daily Vehicle Check turned ${newValue ? 'ON' : 'OFF'} by $userName',
        actorUid: uid,
        actorName: userName,
      );
      if (mounted) setState(() => _requireDailyCheckOn = newValue);
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Failed to change this setting: $e')),
        );
      }
    } finally {
      if (mounted) setState(() => _togglingRequireDailyCheck = false);
    }
  }

  Future<void> _toggleAdvancedMode(bool advancedOn) async {
    final newSimpleMode = !advancedOn;
    final confirmed = await showAppConfirmDialog(
      context: context,
      title: advancedOn ? 'Turn ADVANCED MODE ON?' : 'Turn ADVANCED MODE OFF?',
      message: advancedOn
          ? 'Brings back garage quotation compare, invoices, cash payments '
              'and the final inspection screens for new repair jobs.'
          : 'New repair jobs go back to the simple flow: Add Defect -> '
              'Mechanic form -> Supervisor approval -> Mark Done. Jobs '
              'already in progress keep the mode they were created under.',
      confirmLabel: advancedOn ? 'Turn On' : 'Turn Off',
    );
    if (!confirmed) return;
    setState(() => _togglingSimpleMode = true);
    try {
      final uid = FirebaseAuth.instance.currentUser?.uid ?? '';
      final userDoc =
          await FirebaseFirestore.instance.collection('users').doc(uid).get();
      final userName = (userDoc.data()?['name'] ?? 'Unknown').toString();
      await FirebaseFirestore.instance
          .collection('settings')
          .doc('repair_workflow')
          .set({'simpleMode': newSimpleMode}, SetOptions(merge: true));
      await _writeRepairEvent(
        collection: 'settings',
        docId: 'repair_workflow',
        action: advancedOn ? 'ADVANCED_MODE_ON' : 'ADVANCED_MODE_OFF',
        summary: 'Advanced Mode turned ${advancedOn ? 'ON' : 'OFF'} by $userName',
        actorUid: uid,
        actorName: userName,
      );
      if (mounted) setState(() => _simpleModeOn = newSimpleMode);
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Failed to change Advanced Mode: $e')),
        );
      }
    } finally {
      if (mounted) setState(() => _togglingSimpleMode = false);
    }
  }

  Future<void> _toggleTestMode(bool newValue) async {
    final confirmed = await showAppConfirmDialog(
      context: context,
      title: newValue ? 'Turn Test Mode ON?' : 'Turn Test Mode OFF?',
      message: newValue
          ? 'This weakens fraud controls: the same person will be able to '
              'verify, approve and inspect their own work across the whole '
              'Truck Repair module. A red banner shows on every screen while '
              'this is on. Only use this for testing.'
          : 'Identity-exclusion checks (verifier ≠ enterer, approver ≠ '
              'requester, inspector ≠ completer) go back to being enforced.',
      confirmLabel: newValue ? 'Turn On' : 'Turn Off',
    );
    if (!confirmed) return;
    setState(() => _togglingTestMode = true);
    try {
      final uid = FirebaseAuth.instance.currentUser?.uid ?? '';
      final userDoc =
          await FirebaseFirestore.instance.collection('users').doc(uid).get();
      final userName = (userDoc.data()?['name'] ?? 'Unknown').toString();
      await FirebaseFirestore.instance
          .collection('settings')
          .doc('repair_workflow')
          .set({'testModeAllowSameUser': newValue}, SetOptions(merge: true));
      await _writeRepairEvent(
        collection: 'settings',
        docId: 'repair_workflow',
        action: newValue ? 'TEST_MODE_ON' : 'TEST_MODE_OFF',
        summary: 'Test Mode turned ${newValue ? 'ON' : 'OFF'} by $userName',
        actorUid: uid,
        actorName: userName,
      );
      if (mounted) setState(() => _testModeOn = newValue);
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Failed to change Test Mode: $e')),
        );
      }
    } finally {
      if (mounted) setState(() => _togglingTestMode = false);
    }
  }

  @override
  void dispose() {
    _managerLimitController.dispose();
    _multiQuoteThresholdController.dispose();
    _multiQuoteMinCountController.dispose();
    super.dispose();
  }

  Future<void> _save() async {
    final limit = num.tryParse(_managerLimitController.text.trim());
    final threshold = num.tryParse(_multiQuoteThresholdController.text.trim());
    final minCount = int.tryParse(_multiQuoteMinCountController.text.trim());
    if (limit == null || threshold == null || minCount == null || minCount < 1) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Please enter valid numbers.')),
      );
      return;
    }
    setState(() => _saving = true);
    try {
      await FirebaseFirestore.instance
          .collection('settings')
          .doc('repair_workflow')
          .set({
            'managerApprovalLimit': limit,
            'multiQuotationThreshold': threshold,
            'multiQuotationMinCount': minCount,
          }, SetOptions(merge: true));
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Settings saved.')),
        );
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Failed to save: $e')),
        );
      }
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return TruckRepairScaffold(
      appBar: AppBar(
        title: const Text('Repair Settings'),
        backgroundColor: AppColors.navy,
        foregroundColor: Colors.white,
      ),
      body: _loading
          ? const LoadingState()
          : SingleChildScrollView(
              child: Align(
                alignment: Alignment.topCenter,
                child: ConstrainedBox(
                  constraints: const BoxConstraints(maxWidth: 480),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text('Approval Limits', style: AppText.title),
                      const SizedBox(height: AppSpacing.lg),
                      TextField(
                        controller: _managerLimitController,
                        enabled: _canEdit,
                        keyboardType: const TextInputType.numberWithOptions(
                          decimal: true,
                        ),
                        decoration: const InputDecoration(
                          labelText: 'Manager Approval Limit (Rs.)',
                          helperText:
                              'Totals at or below this can be approved by a '
                              'manager with Can Approve Repairs; above it, '
                              'only Owner/Admin can approve.',
                        ),
                      ),
                      const SizedBox(height: AppSpacing.lg),
                      TextField(
                        controller: _multiQuoteThresholdController,
                        enabled: _canEdit,
                        keyboardType: const TextInputType.numberWithOptions(
                          decimal: true,
                        ),
                        decoration: const InputDecoration(
                          labelText: 'Multi-Quotation Threshold (Rs.)',
                          helperText:
                              'Totals above this require at least the '
                              'minimum number of quotations below.',
                        ),
                      ),
                      const SizedBox(height: AppSpacing.lg),
                      TextField(
                        controller: _multiQuoteMinCountController,
                        enabled: _canEdit,
                        keyboardType: TextInputType.number,
                        decoration: const InputDecoration(
                          labelText: 'Minimum Quotations Required',
                        ),
                      ),
                      const SizedBox(height: AppSpacing.xl),
                      if (_canEdit)
                        SizedBox(
                          width: double.infinity,
                          child: ElevatedButton(
                            onPressed: _saving ? null : _save,
                            child: _saving
                                ? const SizedBox(
                                    width: 20,
                                    height: 20,
                                    child: CircularProgressIndicator(
                                      strokeWidth: 2,
                                      color: Colors.white,
                                    ),
                                  )
                                : const Text('SAVE'),
                          ),
                        )
                      else
                        Text(
                          'Admins and Owners only — read-only for your role.',
                          style: AppText.caption,
                        ),
                      const SizedBox(height: AppSpacing.xl),
                      const Divider(),
                      const SizedBox(height: AppSpacing.md),
                      Text('Advanced Mode', style: AppText.title),
                      const SizedBox(height: AppSpacing.sm),
                      Text(
                        'Default flow is simple: Add Defect -> Mechanic form -> '
                        'Supervisor approval -> Mark Done. Turn this ON to bring '
                        'back garage quotation compare, invoices, cash payments '
                        'and the final inspection screens for NEW repair jobs. '
                        'Jobs already in progress keep the mode they started in.',
                        style: AppText.caption,
                      ),
                      const SizedBox(height: AppSpacing.sm),
                      if (_canEdit)
                        SwitchListTile(
                          contentPadding: EdgeInsets.zero,
                          title: const Text('Advanced Mode (quotations, invoices, payments)'),
                          value: !_simpleModeOn,
                          onChanged: _togglingSimpleMode
                              ? null
                              : (val) => _toggleAdvancedMode(val),
                        )
                      else
                        Text(
                          _simpleModeOn
                              ? 'Simple Mode is currently ON (Advanced Mode OFF).'
                              : 'Advanced Mode is currently ON.',
                          style: AppText.caption,
                        ),
                      const SizedBox(height: AppSpacing.xl),
                      const Divider(),
                      const SizedBox(height: AppSpacing.md),
                      Text('Test Mode', style: AppText.title),
                      const SizedBox(height: AppSpacing.sm),
                      Text(
                        'While on, the same person may verify/approve/inspect '
                        'their own work (identity-exclusion checks are '
                        'skipped). Permissions and amount limits still apply. '
                        'A red banner shows on every Truck Repair screen.',
                        style: AppText.caption,
                      ),
                      const SizedBox(height: AppSpacing.sm),
                      if (_canEdit)
                        SwitchListTile(
                          contentPadding: EdgeInsets.zero,
                          title: const Text('Test Mode (same-user overrides)'),
                          value: _testModeOn,
                          onChanged: _togglingTestMode
                              ? null
                              : (val) => _toggleTestMode(val),
                        )
                      else
                        Text(
                          _testModeOn ? 'Test Mode is currently ON.' : 'Test Mode is OFF.',
                          style: AppText.caption,
                        ),
                      const SizedBox(height: AppSpacing.xl),
                      const Divider(),
                      const SizedBox(height: AppSpacing.md),
                      Text('Daily Vehicle Check', style: AppText.title),
                      const SizedBox(height: AppSpacing.sm),
                      Text(
                        'While ON, a driver with an active truck and no daily '
                        'water/oil level check submitted today is auto-prompted '
                        'and cannot skip it. Turning this OFF adds a '
                        'SKIP — DO LATER button. Admin/Owner can always skip, '
                        'regardless of this setting.',
                        style: AppText.caption,
                      ),
                      const SizedBox(height: AppSpacing.sm),
                      if (_canEdit)
                        SwitchListTile(
                          contentPadding: EdgeInsets.zero,
                          title: const Text('Require Daily Vehicle Check Before Trips'),
                          value: _requireDailyCheckOn,
                          onChanged: _togglingRequireDailyCheck
                              ? null
                              : (val) => _toggleRequireDailyCheck(val),
                        )
                      else
                        Text(
                          _requireDailyCheckOn
                              ? 'Daily Vehicle Check is currently required.'
                              : 'Daily Vehicle Check is currently optional (SKIP allowed).',
                          style: AppText.caption,
                        ),
                    ],
                  ),
                ),
              ),
            ),
    );
  }
}

// ---------------- ADD / REVISE QUOTATION ----------------
class _QuotationItemRow {
  final descController = TextEditingController();
  final qtyController = TextEditingController(text: '1');
  final priceController = TextEditingController();
  _QuotationItemRow();
  void dispose() {
    descController.dispose();
    qtyController.dispose();
    priceController.dispose();
  }
}

class AddQuotationScreen extends StatefulWidget {
  final String jobId;
  final String vehicleNumber;
  final DocumentSnapshot? revisionOf;
  const AddQuotationScreen({
    super.key,
    required this.jobId,
    required this.vehicleNumber,
    this.revisionOf,
  });

  @override
  State<AddQuotationScreen> createState() => _AddQuotationScreenState();
}

class _AddQuotationScreenState extends State<AddQuotationScreen> {
  final _filesKey = GlobalKey<_QuotationFilesSectionState>();
  String? _garageId;
  String? _garageName;
  final _garageRefController = TextEditingController();
  DateTime? _validUntil;
  final List<_QuotationItemRow> _items = [_QuotationItemRow()];
  final _labourController = TextEditingController(text: '0');
  final _otherController = TextEditingController(text: '0');
  final _taxController = TextEditingController(text: '0');
  final _notesController = TextEditingController();
  bool _saving = false;
  String? _savedQuotationId;
  String? _savedQuotationNo;

  List<Map<String, dynamic>> get _initialFiles {
    final existing = widget.revisionOf?.data() as Map<String, dynamic>?;
    final files = existing?['files'] as List?;
    if (files == null) return const [];
    return files.map((f) => f as Map<String, dynamic>).toList();
  }

  @override
  void initState() {
    super.initState();
    final existing = widget.revisionOf?.data() as Map<String, dynamic>?;
    if (existing != null) {
      _garageId = existing['garageId'] as String?;
      _garageName = existing['garageName'] as String?;
      _garageRefController.text = (existing['garageRefNo'] ?? '').toString();
      final vu = existing['validUntil'];
      if (vu is Timestamp) _validUntil = vu.toDate();
      final items = (existing['items'] as List?) ?? const [];
      if (items.isNotEmpty) {
        _items.clear();
        for (final it in items) {
          final m = it as Map<String, dynamic>;
          final row = _QuotationItemRow();
          row.descController.text = (m['description'] ?? '').toString();
          row.qtyController.text = (m['qty'] ?? '').toString();
          final unitPriceCents = (m['unitPriceCents'] as num?)?.toInt() ?? 0;
          row.priceController.text =
              _centsToMoney(unitPriceCents).toStringAsFixed(2);
          _items.add(row);
        }
      }
      _labourController.text = _centsToMoney(
        ((existing['labourCostCents'] as num?)?.toInt() ?? 0),
      ).toStringAsFixed(2);
      _otherController.text = _centsToMoney(
        ((existing['otherChargesCents'] as num?)?.toInt() ?? 0),
      ).toStringAsFixed(2);
      _taxController.text = _centsToMoney(
        ((existing['taxesCents'] as num?)?.toInt() ?? 0),
      ).toStringAsFixed(2);
      _notesController.text = (existing['notes'] ?? '').toString();
    }
  }

  @override
  void dispose() {
    _garageRefController.dispose();
    _labourController.dispose();
    _otherController.dispose();
    _taxController.dispose();
    _notesController.dispose();
    for (final row in _items) {
      row.dispose();
    }
    super.dispose();
  }

  void _addItemRow() => setState(() => _items.add(_QuotationItemRow()));

  void _removeItemRow(int index) => setState(() {
    _items[index].dispose();
    _items.removeAt(index);
  });

  Future<void> _pickGarage() async {
    final picked = await _showGaragePicker(context);
    if (picked != null) {
      setState(() {
        _garageId = picked['id'];
        _garageName = picked['name'];
      });
    }
  }

  Future<void> _pickValidUntil() async {
    final picked = await showDatePicker(
      context: context,
      initialDate: _validUntil ?? DateTime.now().add(const Duration(days: 14)),
      firstDate: DateTime.now().subtract(const Duration(days: 1)),
      lastDate: DateTime.now().add(const Duration(days: 365)),
    );
    if (picked != null) setState(() => _validUntil = picked);
  }

  List<({num qty, num unitPrice})> get _itemsForTotal => _items
      .map(
        (r) => (
          qty: num.tryParse(r.qtyController.text.trim()) ?? 0,
          unitPrice: num.tryParse(r.priceController.text.trim()) ?? 0,
        ),
      )
      .toList();

  int get _totalCents => _quotationTotalCents(
    items: _itemsForTotal,
    labourCost: num.tryParse(_labourController.text.trim()) ?? 0,
    otherCharges: num.tryParse(_otherController.text.trim()) ?? 0,
    taxes: num.tryParse(_taxController.text.trim()) ?? 0,
  );

  Future<void> _save() async {
    if (_garageId == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Please select a garage.')),
      );
      return;
    }
    final validItems = _items
        .where(
          (r) =>
              r.descController.text.trim().isNotEmpty &&
              (num.tryParse(r.qtyController.text.trim()) ?? 0) > 0,
        )
        .toList();
    if (validItems.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Please add at least one item with a quantity.'),
        ),
      );
      return;
    }
    final confirmed = await showAppConfirmDialog(
      context: context,
      title: widget.revisionOf == null
          ? 'Submit Quotation?'
          : 'Submit Revised Quotation?',
      message: 'Total: ${_formatMoney(_centsToMoney(_totalCents))}.'
          '${widget.revisionOf != null ? " This supersedes the previous revision." : ""}',
      confirmLabel: 'Submit',
    );
    if (!confirmed) return;

    setState(() => _saving = true);
    try {
      final uid = FirebaseAuth.instance.currentUser?.uid ?? '';
      final userDoc =
          await FirebaseFirestore.instance.collection('users').doc(uid).get();
      final userName = (userDoc.data()?['name'] ?? 'Unknown').toString();

      final jobRef =
          FirebaseFirestore.instance.collection('repair_jobs').doc(widget.jobId);
      final docRef = FirebaseFirestore.instance.collection('repair_quotations').doc();
      final uploadResult = await _filesKey.currentState!.uploadAndFinalize(
        _quotationStoragePathPrefix(docRef.id),
      );

      final quotationNo =
          await _nextRepairSequenceNumber('repair_quotations', 'QUO');
      final revision =
          ((widget.revisionOf?.data() as Map<String, dynamic>?)?['revision']
                  as num?)
              ?.toInt() ??
          0;
      final itemsData = validItems.map((r) {
        final qty = num.tryParse(r.qtyController.text.trim()) ?? 0;
        final unitPrice = num.tryParse(r.priceController.text.trim()) ?? 0;
        return {
          'description': r.descController.text.trim(),
          'qty': qty,
          'unitPriceCents': _moneyToCents(unitPrice),
          'lineTotalCents': _lineTotalCents(qty, unitPrice),
        };
      }).toList();

      await docRef.set({
        'quotationNo': quotationNo,
        'repairJobId': widget.jobId,
        'vehicleNumber': widget.vehicleNumber,
        'garageId': _garageId,
        'garageName': _garageName,
        'garageRefNo': _garageRefController.text.trim(),
        'validUntil':
            _validUntil != null ? Timestamp.fromDate(_validUntil!) : null,
        'items': itemsData,
        'labourCostCents': _moneyToCents(
          num.tryParse(_labourController.text.trim()) ?? 0,
        ),
        'otherChargesCents': _moneyToCents(
          num.tryParse(_otherController.text.trim()) ?? 0,
        ),
        'taxesCents': _moneyToCents(
          num.tryParse(_taxController.text.trim()) ?? 0,
        ),
        'totalCents': _totalCents,
        'notes': _notesController.text.trim(),
        'files': uploadResult.files,
        'revision': revision + 1,
        'supersedesId': widget.revisionOf?.id,
        'status': 'SUBMITTED',
        'enteredBy': uid,
        'enteredByName': userName,
        'enteredAt': FieldValue.serverTimestamp(),
        'createdAt': FieldValue.serverTimestamp(),
        'updatedBy': uid,
        'updatedByName': userName,
        'updatedAt': FieldValue.serverTimestamp(),
      });
      await _writeRepairEvent(
        collection: 'repair_quotations',
        docId: docRef.id,
        action: 'SUBMITTED',
        summary:
            '$quotationNo submitted by $userName — '
            '${_formatMoney(_centsToMoney(_totalCents))}',
        actorUid: uid,
        actorName: userName,
      );

      if (widget.revisionOf != null) {
        await widget.revisionOf!.reference.update({
          'status': 'SUPERSEDED',
          'supersededBy': uid,
          'supersededByName': userName,
          'supersededAt': FieldValue.serverTimestamp(),
        });
        await _writeRepairEvent(
          collection: 'repair_quotations',
          docId: widget.revisionOf!.id,
          action: 'SUPERSEDED',
          summary: 'Superseded by $quotationNo (revision ${revision + 1})',
          actorUid: uid,
          actorName: userName,
        );
      }

      final jobSnap = await jobRef.get();
      final currentStatus = jobSnap.data()?['repairStatus'] ?? 'OPEN';
      if (kRepairStageOrder.indexOf(currentStatus.toString()) <
          kRepairStageOrder.indexOf('QUOTING')) {
        await jobRef.update({
          'repairStatus': 'QUOTING',
          'updatedBy': uid,
          'updatedByName': userName,
          'updatedAt': FieldValue.serverTimestamp(),
        });
        await _writeRepairEvent(
          collection: 'repair_jobs',
          docId: widget.jobId,
          action: 'QUOTING',
          summary: 'Moved to Quoting by $userName',
          actorUid: uid,
          actorName: userName,
        );
      }

      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              uploadResult.hadFailures
                  ? 'Quotation $quotationNo saved — some files failed to '
                        'upload. Retry below, then tap Done.'
                  : 'Quotation $quotationNo saved.',
            ),
          ),
        );
        if (uploadResult.hadFailures) {
          setState(() {
            _savedQuotationId = docRef.id;
            _savedQuotationNo = quotationNo;
          });
        } else {
          Navigator.pop(context);
        }
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Failed to save quotation: $e')),
        );
      }
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }

  Future<void> _onFilesRetrySaved(QuotationFileResult result) async {
    final quotationId = _savedQuotationId;
    if (quotationId == null) return;
    await FirebaseFirestore.instance
        .collection('repair_quotations')
        .doc(quotationId)
        .update({'files': result.files});
    if (!result.hadFailures && mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('All files uploaded.')),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<bool>(
      future: _currentUserHasRepairPerm(kPermQuotations),
      builder: (context, permSnap) {
        if (permSnap.connectionState != ConnectionState.done) {
          return const TruckRepairScaffold(body: LoadingState());
        }
        if (permSnap.data != true) {
          return const TruckRepairScaffold(
            body: EmptyState(
              icon: Icons.lock_outline,
              title: 'NO ACCESS',
              hint: 'ASK THE ADMIN TO GRANT THIS TRUCK REPAIR PERMISSION',
            ),
          );
        }
        return TruckRepairScaffold(
      appBar: AppBar(
        title: Text(
          widget.revisionOf == null ? 'Add Quotation' : 'Revise Quotation',
        ),
        backgroundColor: AppColors.navy,
        foregroundColor: Colors.white,
      ),
      body: SingleChildScrollView(
        child: Align(
          alignment: Alignment.topCenter,
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 640),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                AppCard(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text('Garage', style: AppText.section),
                      const SizedBox(height: AppSpacing.sm),
                      InkWell(
                        onTap: _pickGarage,
                        child: InputDecorator(
                          decoration: const InputDecoration(
                            labelText: 'Garage',
                            suffixIcon: Icon(Icons.arrow_drop_down),
                          ),
                          child: Text(_garageName ?? 'Select garage'),
                        ),
                      ),
                      const SizedBox(height: AppSpacing.sm),
                      TextField(
                        controller: _garageRefController,
                        inputFormatters: [UpperCaseTextFormatter()],
                        textCapitalization: TextCapitalization.characters,
                        decoration: const InputDecoration(
                          labelText: 'Garage Quotation Ref. (optional)',
                        ),
                      ),
                      const SizedBox(height: AppSpacing.sm),
                      InkWell(
                        onTap: _pickValidUntil,
                        child: InputDecorator(
                          decoration: const InputDecoration(
                            labelText: 'Valid Until (optional)',
                            suffixIcon: Icon(Icons.calendar_today),
                          ),
                          child: Text(
                            _validUntil == null
                                ? 'Not set'
                                : _repairYmd(_validUntil!),
                          ),
                        ),
                      ),
                    ],
                  ),
                ),
                const SizedBox(height: AppSpacing.lg),
                AppCard(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Row(
                        children: [
                          Text('Items', style: AppText.section),
                          const Spacer(),
                          TextButton.icon(
                            onPressed: _addItemRow,
                            icon: const Icon(Icons.add, size: 16),
                            label: const Text('Add Item'),
                          ),
                        ],
                      ),
                      ...List.generate(_items.length, (i) {
                        final row = _items[i];
                        return Padding(
                          padding: const EdgeInsets.only(bottom: 6),
                          child: Row(
                            children: [
                              Expanded(
                                flex: 3,
                                child: TextField(
                                  controller: row.descController,
                                  inputFormatters: [UpperCaseTextFormatter()],
                                  textCapitalization:
                                      TextCapitalization.characters,
                                  decoration: const InputDecoration(
                                    hintText: 'Description',
                                    isDense: true,
                                  ),
                                  onChanged: (_) => setState(() {}),
                                ),
                              ),
                              const SizedBox(width: 6),
                              Expanded(
                                child: TextField(
                                  controller: row.qtyController,
                                  keyboardType:
                                      const TextInputType.numberWithOptions(
                                        decimal: true,
                                      ),
                                  decoration: const InputDecoration(
                                    hintText: 'Qty',
                                    isDense: true,
                                  ),
                                  onChanged: (_) => setState(() {}),
                                ),
                              ),
                              const SizedBox(width: 6),
                              Expanded(
                                flex: 2,
                                child: TextField(
                                  controller: row.priceController,
                                  keyboardType:
                                      const TextInputType.numberWithOptions(
                                        decimal: true,
                                      ),
                                  decoration: const InputDecoration(
                                    hintText: 'Unit Price',
                                    isDense: true,
                                  ),
                                  onChanged: (_) => setState(() {}),
                                ),
                              ),
                              if (_items.length > 1)
                                IconButton(
                                  icon: const Icon(
                                    Icons.close,
                                    size: 18,
                                    color: AppColors.danger,
                                  ),
                                  onPressed: () => _removeItemRow(i),
                                ),
                            ],
                          ),
                        );
                      }),
                      const Divider(),
                      TextField(
                        controller: _labourController,
                        keyboardType: const TextInputType.numberWithOptions(
                          decimal: true,
                        ),
                        decoration: const InputDecoration(
                          labelText: 'Labour Cost (Rs.)',
                        ),
                        onChanged: (_) => setState(() {}),
                      ),
                      const SizedBox(height: AppSpacing.sm),
                      TextField(
                        controller: _otherController,
                        keyboardType: const TextInputType.numberWithOptions(
                          decimal: true,
                        ),
                        decoration: const InputDecoration(
                          labelText: 'Other Charges (Rs.)',
                        ),
                        onChanged: (_) => setState(() {}),
                      ),
                      const SizedBox(height: AppSpacing.sm),
                      TextField(
                        controller: _taxController,
                        keyboardType: const TextInputType.numberWithOptions(
                          decimal: true,
                        ),
                        decoration: const InputDecoration(
                          labelText: 'Taxes (Rs.)',
                        ),
                        onChanged: (_) => setState(() {}),
                      ),
                      const SizedBox(height: AppSpacing.md),
                      Row(
                        children: [
                          Text('Total', style: AppText.section),
                          const Spacer(),
                          Text(
                            _formatMoney(_centsToMoney(_totalCents)),
                            style: AppText.title,
                          ),
                        ],
                      ),
                    ],
                  ),
                ),
                const SizedBox(height: AppSpacing.lg),
                AppCard(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      TextField(
                        controller: _notesController,
                        inputFormatters: [UpperCaseTextFormatter()],
                        textCapitalization: TextCapitalization.characters,
                        maxLines: 3,
                        decoration: const InputDecoration(
                          labelText: 'Notes (optional)',
                        ),
                      ),
                      const SizedBox(height: AppSpacing.md),
                      _QuotationFilesSection(
                        key: _filesKey,
                        initialFiles: _initialFiles,
                        onRetrySaved: _onFilesRetrySaved,
                      ),
                    ],
                  ),
                ),
                const SizedBox(height: AppSpacing.xl),
                if (_savedQuotationId != null) ...[
                  Text(
                    'Quotation $_savedQuotationNo saved. Retry any failed '
                    'files above, then tap Done.',
                    style: AppText.caption,
                  ),
                  const SizedBox(height: AppSpacing.sm),
                ],
                SizedBox(
                  width: double.infinity,
                  child: ElevatedButton(
                    onPressed: _saving
                        ? null
                        : (_savedQuotationId != null
                              ? () => Navigator.pop(context)
                              : _save),
                    child: _saving
                        ? const SizedBox(
                            width: 20,
                            height: 20,
                            child: CircularProgressIndicator(
                              strokeWidth: 2,
                              color: Colors.white,
                            ),
                          )
                        : Text(
                            _savedQuotationId != null
                                ? 'DONE'
                                : 'SUBMIT QUOTATION',
                          ),
                  ),
                ),
                const SizedBox(height: AppSpacing.lg),
              ],
            ),
          ),
        ),
      ),
    );
      },
    );
  }
}

// ---------------- SELECT QUOTATION (shared by list + compare view) ----------------
Future<void> _selectQuotation({
  required BuildContext context,
  required String jobId,
  required QueryDocumentSnapshot quotation,
  required List<QueryDocumentSnapshot> activeQuotations,
  required RepairWorkflowSettings settings,
}) async {
  final data = quotation.data() as Map<String, dynamic>;
  final totalCents = (data['totalCents'] as num?)?.toInt() ?? 0;
  final thresholdCents = _moneyToCents(settings.multiQuotationThreshold);
  final activeCount = activeQuotations.length;
  if (!isMultiQuotationThresholdMet(
    totalCents: totalCents,
    thresholdCents: thresholdCents,
    activeCount: activeCount,
    minCount: settings.multiQuotationMinCount,
  )) {
    await showDialog(
      context: context,
      builder: (dialogContext) => AlertDialog(
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(AppRadius.card),
        ),
        title: const Text('More Quotations Needed'),
        content: Text(
          'Totals over ${_formatMoney(settings.multiQuotationThreshold)} need at '
          'least ${settings.multiQuotationMinCount} quotations before one can be '
          'selected. Currently $activeCount active quotation(s) on this job.',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext),
            child: const Text('OK'),
          ),
        ],
      ),
    );
    return;
  }

  final reasonController = TextEditingController();
  final confirmed = await showDialog<bool>(
    context: context,
    builder: (dialogContext) => AlertDialog(
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(AppRadius.card),
      ),
      title: const Text('Select This Quotation?'),
      content: TextField(
        controller: reasonController,
        inputFormatters: [UpperCaseTextFormatter()],
        textCapitalization: TextCapitalization.characters,
        maxLines: 2,
        decoration: const InputDecoration(labelText: 'Reason for selection'),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.pop(dialogContext, false),
          child: const Text('Cancel'),
        ),
        ElevatedButton(
          onPressed: () => Navigator.pop(dialogContext, true),
          child: const Text('Select'),
        ),
      ],
    ),
  );
  if (confirmed != true) return;
  if (reasonController.text.trim().isEmpty) {
    if (context.mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Please enter a reason for selection.')),
      );
    }
    return;
  }

  try {
    final uid = FirebaseAuth.instance.currentUser?.uid ?? '';
    final userDoc =
        await FirebaseFirestore.instance.collection('users').doc(uid).get();
    final userName = (userDoc.data()?['name'] ?? 'Unknown').toString();

    final batch = FirebaseFirestore.instance.batch();
    batch.update(quotation.reference, {
      'selection': {
        'reason': reasonController.text.trim(),
        'selectedBy': uid,
        'selectedByName': userName,
        'selectedAt': FieldValue.serverTimestamp(),
      },
    });
    for (final other in activeQuotations) {
      if (other.id == quotation.id) continue;
      batch.update(other.reference, {'status': 'NOT_SELECTED'});
    }
    final jobRef = FirebaseFirestore.instance.collection('repair_jobs').doc(jobId);
    batch.update(jobRef, {
      'selectedQuotationId': quotation.id,
      'updatedBy': uid,
      'updatedByName': userName,
      'updatedAt': FieldValue.serverTimestamp(),
    });
    await batch.commit();

    await _writeRepairEvent(
      collection: 'repair_quotations',
      docId: quotation.id,
      action: 'SELECTED',
      summary:
          '${(data['quotationNo'] ?? '').toString()} selected by $userName — '
          '${reasonController.text.trim()}',
      actorUid: uid,
      actorName: userName,
    );
    await _writeRepairEvent(
      collection: 'repair_jobs',
      docId: jobId,
      action: 'QUOTATION_SELECTED',
      summary: '${(data['quotationNo'] ?? '').toString()} selected by $userName',
      actorUid: uid,
      actorName: userName,
    );
    if (context.mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Quotation selected.')),
      );
    }
  } catch (e) {
    if (context.mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Failed to select quotation: $e')),
      );
    }
  }
}

// ---------------- APPROVAL PENDING BADGE (hub tile trailing) ----------------
class _ApprovalPendingBadge extends StatelessWidget {
  const _ApprovalPendingBadge();

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<DocumentSnapshot?>(
      future: () async {
        final uid = FirebaseAuth.instance.currentUser?.uid;
        if (uid == null) return null;
        return FirebaseFirestore.instance.collection('users').doc(uid).get();
      }(),
      builder: (context, userSnap) {
        final userData = userSnap.data?.data() as Map<String, dynamic>?;
        final role = userData?['role'] as String?;
        final isAdminOrOwner = role == 'admin' || role == 'owner';
        final isApprovingManager =
            !isAdminOrOwner && hasRepairPerm(userData, kPermApprove);
        if (!isAdminOrOwner && !isApprovingManager) return const SizedBox.shrink();
        return StreamBuilder<QuerySnapshot>(
          stream: FirebaseFirestore.instance
              .collection('repair_approvals')
              .where('decision', isEqualTo: 'PENDING')
              .snapshots(),
          builder: (context, snap) {
            if (!snap.hasData) return const SizedBox.shrink();
            final count = snap.data!.docs
                .where((d) => isApprovalVisibleForLevel(
                      approval: d.data() as Map<String, dynamic>,
                      isAdminOrOwner: isAdminOrOwner,
                    ))
                .length;
            if (count == 0) return const SizedBox.shrink();
            return Container(
              margin: const EdgeInsets.only(right: 8),
              padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 2),
              decoration: BoxDecoration(
                color: AppColors.danger,
                borderRadius: BorderRadius.circular(AppRadius.chip),
              ),
              child: Text(
                '$count',
                style: const TextStyle(
                  color: Colors.white,
                  fontSize: 12,
                  fontWeight: FontWeight.w700,
                ),
              ),
            );
          },
        );
      },
    );
  }
}

// Mirrors _ApprovalPendingBadge's shape for the "Defects To Check" hub tile —
// counts fresh REPORTED defects plus RETURNED simple-mode jobs, same two
// queries DefectsToCheckScreen itself merges.
class _DefectsToCheckBadge extends StatelessWidget {
  const _DefectsToCheckBadge();

  @override
  Widget build(BuildContext context) {
    return StreamBuilder<QuerySnapshot>(
      stream: FirebaseFirestore.instance
          .collection('defect_reports')
          .where('status', isEqualTo: 'OPEN')
          .snapshots(),
      builder: (context, defectSnap) {
        return StreamBuilder<QuerySnapshot>(
          stream: FirebaseFirestore.instance
              .collection('repair_jobs')
              .where('simpleMode', isEqualTo: true)
              .where('repairStatus', isEqualTo: RepairStatus.diagnosed)
              .snapshots(),
          builder: (context, jobSnap) {
            if (!defectSnap.hasData || !jobSnap.hasData) {
              return const SizedBox.shrink();
            }
            final returnedCount = jobSnap.data!.docs
                .where((d) => (d.data() as Map<String, dynamic>)['returnReason'] != null)
                .length;
            final count = defectSnap.data!.docs.length + returnedCount;
            if (count == 0) return const SizedBox.shrink();
            return Container(
              margin: const EdgeInsets.only(right: 8),
              padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 2),
              decoration: BoxDecoration(
                color: AppColors.danger,
                borderRadius: BorderRadius.circular(AppRadius.chip),
              ),
              child: Text(
                '$count',
                style: const TextStyle(
                  color: Colors.white,
                  fontSize: 12,
                  fontWeight: FontWeight.w700,
                ),
              ),
            );
          },
        );
      },
    );
  }
}

// ---------------- QUOTATIONS SECTION (embedded in RepairJobDetailScreen) ----------------
class _QuotationsSection extends StatefulWidget {
  final String jobId;
  final String vehicleNumber;
  final Map<String, dynamic> jobData;
  final String repairStatus;
  const _QuotationsSection({
    required this.jobId,
    required this.vehicleNumber,
    required this.jobData,
    required this.repairStatus,
  });

  @override
  State<_QuotationsSection> createState() => _QuotationsSectionState();
}

class _QuotationsSectionState extends State<_QuotationsSection> {
  // [0] QUOTATIONS (add/revise/select), [1] VERIFY_QUOTATION, [2] REQUEST_APPROVAL.
  late final Future<List<bool>> _permsFuture = Future.wait([
    _currentUserHasRepairPerm(kPermQuotations),
    _currentUserHasRepairPerm(kPermVerifyQuotation),
    _currentUserHasRepairPerm(kPermRequestApproval),
  ]);
  late final Future<RepairWorkflowSettings> _settingsFuture =
      _fetchRepairWorkflowSettings();
  final String? _currentUid = FirebaseAuth.instance.currentUser?.uid;
  // Double-tap guard shared by Select/Verify/Return/Request Approval —
  // each is a write-triggering action with no other loading indicator.
  bool _busy = false;

  Future<void> _guarded(Future<void> Function() action) async {
    if (_busy) return;
    setState(() => _busy = true);
    try {
      await action();
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  Future<void> _showVerifyDialog(QueryDocumentSnapshot quotation) async {
    bool siteVisitDone = false;
    bool diagnosisMatches = false;
    bool pricesReasonable = false;
    DateTime? siteVisitDate;
    final commentsController = TextEditingController();

    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => StatefulBuilder(
        builder: (dialogContext, setDialogState) => AlertDialog(
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(AppRadius.card),
          ),
          title: const Text('Verify Quotation'),
          content: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                CheckboxListTile(
                  contentPadding: EdgeInsets.zero,
                  title: const Text('Site visit done'),
                  value: siteVisitDone,
                  onChanged: (v) =>
                      setDialogState(() => siteVisitDone = v ?? false),
                ),
                CheckboxListTile(
                  contentPadding: EdgeInsets.zero,
                  title: const Text('Diagnosis matches'),
                  value: diagnosisMatches,
                  onChanged: (v) =>
                      setDialogState(() => diagnosisMatches = v ?? false),
                ),
                CheckboxListTile(
                  contentPadding: EdgeInsets.zero,
                  title: const Text('Prices reasonable'),
                  value: pricesReasonable,
                  onChanged: (v) =>
                      setDialogState(() => pricesReasonable = v ?? false),
                ),
                ListTile(
                  contentPadding: EdgeInsets.zero,
                  title: Text(
                    siteVisitDate == null
                        ? 'Site visit date (optional)'
                        : _repairYmd(siteVisitDate!),
                  ),
                  trailing: const Icon(Icons.calendar_today, size: 18),
                  onTap: () async {
                    final picked = await showDatePicker(
                      context: dialogContext,
                      initialDate: DateTime.now(),
                      firstDate: DateTime.now().subtract(
                        const Duration(days: 365),
                      ),
                      lastDate: DateTime.now(),
                    );
                    if (picked != null) {
                      setDialogState(() => siteVisitDate = picked);
                    }
                  },
                ),
                TextField(
                  controller: commentsController,
                  inputFormatters: [UpperCaseTextFormatter()],
                  textCapitalization: TextCapitalization.characters,
                  maxLines: 2,
                  decoration: const InputDecoration(labelText: 'Comments'),
                ),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dialogContext, false),
              child: const Text('Cancel'),
            ),
            ElevatedButton(
              onPressed: () => Navigator.pop(dialogContext, true),
              child: const Text('Verify'),
            ),
          ],
        ),
      ),
    );
    if (confirmed != true) return;

    try {
      final uid = FirebaseAuth.instance.currentUser?.uid ?? '';
      final userDoc =
          await FirebaseFirestore.instance.collection('users').doc(uid).get();
      final userName = (userDoc.data()?['name'] ?? 'Unknown').toString();

      await quotation.reference.update({
        'status': 'VERIFIED',
        'verification': {
          'siteVisitDone': siteVisitDone,
          'diagnosisMatches': diagnosisMatches,
          'pricesReasonable': pricesReasonable,
          'siteVisitDate': siteVisitDate != null
              ? Timestamp.fromDate(siteVisitDate!)
              : null,
          'comments': commentsController.text.trim(),
          'verifiedBy': uid,
          'verifiedByName': userName,
          'verifiedAt': FieldValue.serverTimestamp(),
        },
      });
      final jobRef =
          FirebaseFirestore.instance.collection('repair_jobs').doc(widget.jobId);
      await jobRef.update({
        'repairStatus': 'VERIFIED',
        'updatedBy': uid,
        'updatedByName': userName,
        'updatedAt': FieldValue.serverTimestamp(),
      });
      final data = quotation.data() as Map<String, dynamic>;
      await _writeRepairEvent(
        collection: 'repair_quotations',
        docId: quotation.id,
        action: 'VERIFIED',
        summary: '${(data['quotationNo'] ?? '').toString()} verified by $userName',
        actorUid: uid,
        actorName: userName,
      );
      await _writeRepairEvent(
        collection: 'repair_jobs',
        docId: widget.jobId,
        action: 'VERIFIED',
        summary: 'Quotation verified by $userName',
        actorUid: uid,
        actorName: userName,
      );
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Quotation verified.')),
        );
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Failed to verify quotation: $e')),
        );
      }
    }
  }

  Future<void> _showReturnDialog(QueryDocumentSnapshot quotation) async {
    final reasonController = TextEditingController();
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(AppRadius.card),
        ),
        title: const Text('Return For Correction'),
        content: TextField(
          controller: reasonController,
          inputFormatters: [UpperCaseTextFormatter()],
          textCapitalization: TextCapitalization.characters,
          maxLines: 3,
          decoration: const InputDecoration(labelText: 'Reason (required)'),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('Cancel'),
          ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(backgroundColor: AppColors.danger),
            onPressed: () => Navigator.pop(dialogContext, true),
            child: const Text('Return'),
          ),
        ],
      ),
    );
    if (confirmed != true) return;
    if (reasonController.text.trim().isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Please enter a reason.')),
      );
      return;
    }

    try {
      final uid = FirebaseAuth.instance.currentUser?.uid ?? '';
      final userDoc =
          await FirebaseFirestore.instance.collection('users').doc(uid).get();
      final userName = (userDoc.data()?['name'] ?? 'Unknown').toString();

      await quotation.reference.update({
        'status': 'RETURNED',
        'returnReason': reasonController.text.trim(),
        'returnedBy': uid,
        'returnedByName': userName,
        'returnedAt': FieldValue.serverTimestamp(),
      });
      final jobRef =
          FirebaseFirestore.instance.collection('repair_jobs').doc(widget.jobId);
      await jobRef.update({
        'repairStatus': 'QUOTING',
        'selectedQuotationId': null,
        'updatedBy': uid,
        'updatedByName': userName,
        'updatedAt': FieldValue.serverTimestamp(),
      });
      final data = quotation.data() as Map<String, dynamic>;
      await _writeRepairEvent(
        collection: 'repair_quotations',
        docId: quotation.id,
        action: 'RETURNED',
        summary:
            '${(data['quotationNo'] ?? '').toString()} returned by $userName — '
            '${reasonController.text.trim()}',
        actorUid: uid,
        actorName: userName,
      );
      await _writeRepairEvent(
        collection: 'repair_jobs',
        docId: widget.jobId,
        action: 'RETURNED_TO_QUOTING',
        summary: 'Returned for correction by $userName',
        actorUid: uid,
        actorName: userName,
      );
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Returned for correction.')),
        );
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Failed to return quotation: $e')),
        );
      }
    }
  }

  Future<void> _requestApproval(
    QueryDocumentSnapshot quotation,
    RepairWorkflowSettings settings,
  ) async {
    final confirmed = await showAppConfirmDialog(
      context: context,
      title: 'Request Approval?',
      message: 'This sends the verified quotation for approval.',
      confirmLabel: 'Request',
    );
    if (!confirmed) return;

    try {
      final uid = FirebaseAuth.instance.currentUser?.uid ?? '';
      final userDoc =
          await FirebaseFirestore.instance.collection('users').doc(uid).get();
      final userName = (userDoc.data()?['name'] ?? 'Unknown').toString();
      final data = quotation.data() as Map<String, dynamic>;
      final totalCents = (data['totalCents'] as num?)?.toInt() ?? 0;
      final requiredLevel =
          totalCents <= _moneyToCents(settings.managerApprovalLimit)
          ? 'MANAGER'
          : 'OWNER';
      final approvalNo = await _nextRepairSequenceNumber('repair_approvals', 'APR');

      final approvalRef =
          FirebaseFirestore.instance.collection('repair_approvals').doc();
      await approvalRef.set({
        'approvalNo': approvalNo,
        'repairJobId': widget.jobId,
        'vehicleNumber': widget.vehicleNumber,
        'quotationId': quotation.id,
        'garageId': data['garageId'],
        'garageName': data['garageName'],
        'amountCents': totalCents,
        'requiredLevel': requiredLevel,
        'decision': 'PENDING',
        'requestedBy': uid,
        'requestedByName': userName,
        'requestedAt': FieldValue.serverTimestamp(),
        'createdAt': FieldValue.serverTimestamp(),
      });
      final jobRef =
          FirebaseFirestore.instance.collection('repair_jobs').doc(widget.jobId);
      await jobRef.update({
        'repairStatus': 'PENDING_APPROVAL',
        'activeApprovalId': approvalRef.id,
        'updatedBy': uid,
        'updatedByName': userName,
        'updatedAt': FieldValue.serverTimestamp(),
      });
      await _writeRepairEvent(
        collection: 'repair_approvals',
        docId: approvalRef.id,
        action: 'REQUESTED',
        summary:
            '$approvalNo requested by $userName — '
            '${_formatMoney(_centsToMoney(totalCents))} ($requiredLevel)',
        actorUid: uid,
        actorName: userName,
      );
      await _writeRepairEvent(
        collection: 'repair_jobs',
        docId: widget.jobId,
        action: 'PENDING_APPROVAL',
        summary: 'Approval requested by $userName ($requiredLevel)',
        actorUid: uid,
        actorName: userName,
      );
      if (mounted) {
        await showDialog<void>(
          context: context,
          builder: (dialogContext) => AlertDialog(
            shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(AppRadius.card),
            ),
            title: const Text('Sent For Approval'),
            content: Text(
              'SENT FOR APPROVAL ($requiredLevel LEVEL, '
              '${_formatMoney(_centsToMoney(totalCents))})',
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(dialogContext),
                child: const Text('Close'),
              ),
              ElevatedButton(
                onPressed: () {
                  Navigator.pop(dialogContext);
                  pushWebAware(
                    context,
                    RepairApprovalDetailScreen(
                      approvalId: approvalRef.id,
                      currentUid: uid,
                    ),
                  );
                },
                child: const Text('OPEN APPROVAL CENTER'),
              ),
            ],
          ),
        );
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Failed to request approval: $e')),
        );
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    final diagnosedIndex = kRepairStageOrder.indexOf('DIAGNOSED');
    final currentIndex = kRepairStageOrder.indexOf(widget.repairStatus);
    if (currentIndex < diagnosedIndex) {
      return AppCard(
        child: Text(
          'Available once mechanical diagnosis is saved.',
          style: AppText.caption,
        ),
      );
    }

    return FutureBuilder<List<bool>>(
      future: _permsFuture,
      builder: (context, permsSnap) {
        final perms = permsSnap.data ?? const [false, false, false];
        final canEnter = perms[0];
        final canVerifyPerm = perms[1];
        final canRequestApprovalPerm = perms[2];
        return FutureBuilder<RepairWorkflowSettings>(
          future: _settingsFuture,
          builder: (context, settingsSnap) {
            final settings = settingsSnap.data;
            return StreamBuilder<QuerySnapshot>(
              stream: FirebaseFirestore.instance
                  .collection('repair_quotations')
                  .where('repairJobId', isEqualTo: widget.jobId)
                  .snapshots(),
              builder: (context, snapshot) {
                if (snapshot.hasError) {
                  return ErrorState(
                    message: 'Failed to load quotations: ${snapshot.error}',
                    onRetry: () => setState(() {}),
                  );
                }
                if (!snapshot.hasData) return const LoadingState();
                final allDocs = snapshot.data!.docs;
                final active = allDocs
                    .where(
                      (d) => ['SUBMITTED', 'VERIFIED'].contains(
                        (d.data() as Map<String, dynamic>)['status'],
                      ),
                    )
                    .toList();
                final sortedAll = [...allDocs]..sort((a, b) {
                  final ac =
                      ((a.data() as Map<String, dynamic>)['createdAt']
                              as Timestamp?)
                          ?.millisecondsSinceEpoch ??
                      0;
                  final bc =
                      ((b.data() as Map<String, dynamic>)['createdAt']
                              as Timestamp?)
                          ?.millisecondsSinceEpoch ??
                      0;
                  return bc.compareTo(ac);
                });
                final selectedQuotationId =
                    widget.jobData['selectedQuotationId'] as String?;
                final mechSupervisorId =
                    widget.jobData['mechanicalSupervisorId'] as String?;

                return Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Row(
                      children: [
                        Text('Quotations', style: AppText.section),
                        const Spacer(),
                        if (active.length > 1)
                          TextButton.icon(
                            onPressed: () => pushWebAware(
                              context,
                              QuotationCompareScreen(jobId: widget.jobId),
                            ),
                            icon: const Icon(Icons.compare_arrows, size: 16),
                            label: const Text('Compare'),
                          ),
                        if (canEnter && widget.repairStatus != 'CLOSED')
                          TextButton.icon(
                            onPressed: () => pushWebAware(
                              context,
                              AddQuotationScreen(
                                jobId: widget.jobId,
                                vehicleNumber: widget.vehicleNumber,
                              ),
                            ),
                            icon: const Icon(Icons.add, size: 16),
                            label: const Text('Add'),
                          ),
                      ],
                    ),
                    if (sortedAll.isEmpty)
                      const EmptyState(
                        icon: Icons.request_quote,
                        title: 'No quotations yet.',
                        hint: 'Add a quotation from a garage.',
                      )
                    else
                      ...sortedAll.map((doc) {
                        final data = doc.data() as Map<String, dynamic>;
                        final status = (data['status'] ?? '').toString();
                        final isSelected = doc.id == selectedQuotationId;
                        final totalCents = (data['totalCents'] as num?)?.toInt() ?? 0;

                        return Padding(
                          padding: const EdgeInsets.only(bottom: AppSpacing.sm),
                          child: AppCard(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Row(
                                  children: [
                                    Expanded(
                                      child: Text(
                                        '${data['quotationNo'] ?? ''} — '
                                        '${data['garageName'] ?? ''}'
                                        '${(data['revision'] ?? 1) > 1 ? " (Rev ${data['revision']})" : ""}',
                                        style: AppText.body.copyWith(
                                          fontWeight: FontWeight.w600,
                                        ),
                                      ),
                                    ),
                                    StatusChip(status: status),
                                  ],
                                ),
                                const SizedBox(height: 4),
                                Text(
                                  _formatMoney(_centsToMoney(totalCents)),
                                  style: AppText.title,
                                ),
                                if (isSelected) ...[
                                  const SizedBox(height: 4),
                                  const Text(
                                    'SELECTED',
                                    style: TextStyle(
                                      color: AppColors.success,
                                      fontWeight: FontWeight.w700,
                                      fontSize: 12,
                                    ),
                                  ),
                                ],
                                if (status == QuotationStatus.returned &&
                                    data['returnReason'] != null) ...[
                                  const SizedBox(height: 4),
                                  Text(
                                    'Return reason: ${data['returnReason']}',
                                    style: AppText.caption.copyWith(
                                      color: AppColors.danger,
                                    ),
                                  ),
                                ],
                                if (status == QuotationStatus.rejected &&
                                    data['approvalRejectReason'] != null) ...[
                                  const SizedBox(height: 4),
                                  Text(
                                    'Approval rejected: ${data['approvalRejectReason']}',
                                    style: AppText.caption.copyWith(
                                      color: AppColors.danger,
                                    ),
                                  ),
                                ],
                                const SizedBox(height: AppSpacing.sm),
                                Wrap(
                                  spacing: 8,
                                  runSpacing: 8,
                                  children: [
                                    if ((status == QuotationStatus.submitted ||
                                            status == QuotationStatus.returned ||
                                            status == QuotationStatus.rejected) &&
                                        canEnter)
                                      OutlinedButton(
                                        onPressed: () => pushWebAware(
                                          context,
                                          AddQuotationScreen(
                                            jobId: widget.jobId,
                                            vehicleNumber: widget.vehicleNumber,
                                            revisionOf: doc,
                                          ),
                                        ),
                                        child: const Text('REVISE'),
                                      ),
                                    if (status == 'SUBMITTED' &&
                                        !isSelected &&
                                        settings != null &&
                                        canEnter)
                                      OutlinedButton(
                                        onPressed: _busy
                                            ? null
                                            : () => _guarded(() => _selectQuotation(
                                          context: context,
                                          jobId: widget.jobId,
                                          quotation: doc,
                                          activeQuotations: active,
                                          settings: settings,
                                        )),
                                        child: const Text('SELECT'),
                                      ),
                                    if (isSelected && status == QuotationStatus.submitted)
                                      Builder(
                                        builder: (context) {
                                          final canVerify = canVerifyQuotation(
                                            quotation: data,
                                            isSelected: isSelected,
                                            hasVerifyPerm: canVerifyPerm,
                                            currentUid: _currentUid,
                                            mechanicalSupervisorId: mechSupervisorId,
                                            testMode: settings?.testModeAllowSameUser == true,
                                          );
                                          if (!canVerify) {
                                            return Text(
                                              'Verification requires a different '
                                              'person than the diagnosis/quotation '
                                              'entry.',
                                              style: AppText.caption,
                                            );
                                          }
                                          return Row(
                                            mainAxisSize: MainAxisSize.min,
                                            children: [
                                              ElevatedButton(
                                                onPressed: _busy
                                                    ? null
                                                    : () => _guarded(
                                                        () => _showVerifyDialog(doc)),
                                                child: const Text('VERIFY'),
                                              ),
                                              const SizedBox(width: 8),
                                              OutlinedButton(
                                                onPressed: _busy
                                                    ? null
                                                    : () => _guarded(
                                                        () => _showReturnDialog(doc)),
                                                child: const Text('RETURN'),
                                              ),
                                            ],
                                          );
                                        },
                                      ),
                                    if (settings != null &&
                                        canRequestApproval(
                                          quotation: data,
                                          isSelected: isSelected,
                                          jobRepairStatus: widget.repairStatus,
                                          hasRequestApprovalPerm: canRequestApprovalPerm,
                                        ))
                                      ElevatedButton(
                                        onPressed: _busy
                                            ? null
                                            : () => _guarded(
                                                () => _requestApproval(doc, settings)),
                                        child: const Text('REQUEST APPROVAL'),
                                      ),
                                  ],
                                ),
                              ],
                            ),
                          ),
                        );
                      }),
                  ],
                );
              },
            );
          },
        );
      },
    );
  }
}

// ---------------- COMPARE QUOTATIONS ----------------
class QuotationCompareScreen extends StatefulWidget {
  final String jobId;
  const QuotationCompareScreen({super.key, required this.jobId});

  @override
  State<QuotationCompareScreen> createState() => _QuotationCompareScreenState();
}

class _QuotationCompareScreenState extends State<QuotationCompareScreen> {
  late final Future<bool> _canEnterFuture = _currentUserHasRepairPerm(kPermQuotations);
  late final Future<RepairWorkflowSettings> _settingsFuture =
      _fetchRepairWorkflowSettings();
  bool _busy = false;

  Future<void> _guarded(Future<void> Function() action) async {
    if (_busy) return;
    setState(() => _busy = true);
    try {
      await action();
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return TruckRepairScaffold(
      appBar: AppBar(
        title: const Text('Compare Quotations'),
        backgroundColor: AppColors.navy,
        foregroundColor: Colors.white,
      ),
      body: StreamBuilder<DocumentSnapshot>(
        stream: FirebaseFirestore.instance
            .collection('repair_jobs')
            .doc(widget.jobId)
            .snapshots(),
        builder: (context, jobSnap) {
          if (!jobSnap.hasData) return const LoadingState();
          final jobData = jobSnap.data!.data() as Map<String, dynamic>? ?? {};
          final selectedQuotationId = jobData['selectedQuotationId'] as String?;

          return StreamBuilder<QuerySnapshot>(
            stream: FirebaseFirestore.instance
                .collection('repair_quotations')
                .where('repairJobId', isEqualTo: widget.jobId)
                .snapshots(),
            builder: (context, snapshot) {
              if (snapshot.hasError) {
                return ErrorState(
                  message: 'Failed to load: ${snapshot.error}',
                  onRetry: () => setState(() {}),
                );
              }
              if (!snapshot.hasData) return const LoadingState();
              final active = snapshot.data!.docs
                  .where(
                    (d) => ['SUBMITTED', 'VERIFIED'].contains(
                      (d.data() as Map<String, dynamic>)['status'],
                    ),
                  )
                  .toList()
                ..sort((a, b) {
                  final at =
                      ((a.data() as Map<String, dynamic>)['totalCents'] as num?) ??
                      0;
                  final bt =
                      ((b.data() as Map<String, dynamic>)['totalCents'] as num?) ??
                      0;
                  return at.compareTo(bt);
                });
              if (active.isEmpty) {
                return const EmptyState(
                  icon: Icons.request_quote,
                  title: 'No active quotations to compare.',
                );
              }
              final lowestCents =
                  ((active.first.data() as Map<String, dynamic>)['totalCents']
                      as num?) ??
                  0;

              return FutureBuilder<bool>(
                future: _canEnterFuture,
                builder: (context, canEnterSnap) {
                  final canEnter = canEnterSnap.data == true;
                  return FutureBuilder<RepairWorkflowSettings>(
                    future: _settingsFuture,
                    builder: (context, settingsSnap) {
                      final settings = settingsSnap.data;
                      return SingleChildScrollView(
                        scrollDirection: Axis.horizontal,
                        child: Padding(
                          padding: const EdgeInsets.all(AppSpacing.lg),
                          child: Row(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: active.map((doc) {
                              final data = doc.data() as Map<String, dynamic>;
                              final totalCents =
                                  (data['totalCents'] as num?)?.toInt() ?? 0;
                              final isLowest = totalCents == lowestCents;
                              final isSelected = doc.id == selectedQuotationId;
                              final items = (data['items'] as List?) ?? const [];
                              return Padding(
                                padding: const EdgeInsets.only(
                                  right: AppSpacing.md,
                                ),
                                child: SizedBox(
                                  width: 260,
                                  child: AppCard(
                                    child: Column(
                                      crossAxisAlignment:
                                          CrossAxisAlignment.start,
                                      children: [
                                        Row(
                                          children: [
                                            Expanded(
                                              child: Text(
                                                '${data['garageName'] ?? ''}',
                                                style: AppText.section,
                                              ),
                                            ),
                                            if (isLowest)
                                              const Icon(
                                                Icons.star,
                                                color: AppColors.warning,
                                                size: 18,
                                              ),
                                          ],
                                        ),
                                        Text(
                                          '${data['quotationNo'] ?? ''}',
                                          style: AppText.caption,
                                        ),
                                        const Divider(),
                                        ...items.map((it) {
                                          final m = it as Map<String, dynamic>;
                                          return Padding(
                                            padding: const EdgeInsets.only(
                                              bottom: 4,
                                            ),
                                            child: Row(
                                              children: [
                                                Expanded(
                                                  child: Text(
                                                    '${m['description'] ?? ''} '
                                                    'x${m['qty'] ?? ''}',
                                                    style: AppText.caption,
                                                  ),
                                                ),
                                                Text(
                                                  _formatMoney(
                                                    _centsToMoney(
                                                      ((m['lineTotalCents']
                                                                  as num?)
                                                              ?.toInt() ??
                                                          0),
                                                    ),
                                                  ),
                                                  style: AppText.caption,
                                                ),
                                              ],
                                            ),
                                          );
                                        }),
                                        const Divider(),
                                        Row(
                                          children: [
                                            Text('Total', style: AppText.section),
                                            const Spacer(),
                                            Text(
                                              _formatMoney(
                                                _centsToMoney(totalCents),
                                              ),
                                              style: AppText.title.copyWith(
                                                color: isLowest
                                                    ? AppColors.success
                                                    : null,
                                              ),
                                            ),
                                          ],
                                        ),
                                        const SizedBox(height: AppSpacing.sm),
                                        if (isSelected)
                                          const Text(
                                            'SELECTED',
                                            style: TextStyle(
                                              color: AppColors.success,
                                              fontWeight: FontWeight.w700,
                                            ),
                                          )
                                        else if (canEnter && settings != null)
                                          SizedBox(
                                            width: double.infinity,
                                            child: OutlinedButton(
                                              onPressed: _busy
                                                  ? null
                                                  : () => _guarded(() => _selectQuotation(
                                                context: context,
                                                jobId: widget.jobId,
                                                quotation: doc,
                                                activeQuotations: active,
                                                settings: settings,
                                              )),
                                              child: const Text('SELECT'),
                                            ),
                                          ),
                                      ],
                                    ),
                                  ),
                                ),
                              );
                            }).toList(),
                          ),
                        ),
                      );
                    },
                  );
                },
              );
            },
          );
        },
      ),
    );
  }
}

// ---------------- APPROVAL CENTER ----------------
class RepairApprovalCenterScreen extends StatefulWidget {
  // Test-only injection seam, same shape/intent as
  // RepairApprovalDetailScreen.firestoreOverride — null in every production
  // call site. currentUidOverride lets a widget test drive this screen
  // without a real signed-in FirebaseAuth user.
  final FirebaseFirestore? firestoreOverride;
  final String? currentUidOverride;
  const RepairApprovalCenterScreen({
    super.key,
    this.firestoreOverride,
    this.currentUidOverride,
  });

  @override
  State<RepairApprovalCenterScreen> createState() =>
      _RepairApprovalCenterScreenState();
}

class _RepairApprovalCenterScreenState
    extends State<RepairApprovalCenterScreen> {
  FirebaseFirestore get _db => widget.firestoreOverride ?? FirebaseFirestore.instance;
  String? get _uid => widget.currentUidOverride ?? FirebaseAuth.instance.currentUser?.uid;

  late final Future<DocumentSnapshot?> _userFuture = () async {
    final uid = _uid;
    if (uid == null) return null;
    return _db.collection('users').doc(uid).get();
  }();

  @override
  Widget build(BuildContext context) {
    return TruckRepairScaffold(
      appBar: AppBar(
        title: const Text('Approval Center'),
        backgroundColor: AppColors.navy,
        foregroundColor: Colors.white,
      ),
      body: FutureBuilder<DocumentSnapshot?>(
        future: _userFuture,
        builder: (context, userSnap) {
          if (userSnap.connectionState != ConnectionState.done) {
            return const LoadingState();
          }
          final userData = userSnap.data?.data() as Map<String, dynamic>?;
          final uid = _uid;
          final role = userData?['role'] as String?;
          final isAdminOrOwner = role == 'admin' || role == 'owner';

          return StreamBuilder<QuerySnapshot>(
            stream: _db
                .collection('repair_approvals')
                .orderBy('requestedAt', descending: true)
                .snapshots(),
            builder: (context, snapshot) {
              if (snapshot.hasError) {
                return ErrorState(
                  message: 'Failed to load approvals: ${snapshot.error}',
                  onRetry: () => setState(() {}),
                );
              }
              if (!snapshot.hasData) return const LoadingState();
              final allDocs = snapshot.data!.docs;
              var docs = allDocs
                  .where((d) => isApprovalVisibleForLevel(
                        approval: d.data() as Map<String, dynamic>,
                        isAdminOrOwner: isAdminOrOwner,
                      ))
                  .toList();
              docs = [...docs]..sort((a, b) {
                final ad =
                    (a.data() as Map<String, dynamic>)['decision'] == 'PENDING'
                    ? 0
                    : 1;
                final bd =
                    (b.data() as Map<String, dynamic>)['decision'] == 'PENDING'
                    ? 0
                    : 1;
                return ad.compareTo(bd);
              });

              bool isPending(QueryDocumentSnapshot d) =>
                  (d.data() as Map<String, dynamic>)['decision'] == 'PENDING';
              final pendingVisibleCount = docs.where(isPending).length;
              final hiddenPendingCount = allDocs
                  .where(isPending)
                  .where((d) => !isApprovalVisibleForLevel(
                        approval: d.data() as Map<String, dynamic>,
                        isAdminOrOwner: isAdminOrOwner,
                      ))
                  .length;
              final countLine = Padding(
                padding: const EdgeInsets.fromLTRB(
                  AppSpacing.md,
                  AppSpacing.sm,
                  AppSpacing.md,
                  0,
                ),
                child: Text(
                  hiddenPendingCount > 0
                      ? '$pendingVisibleCount PENDING ($hiddenPendingCount HIDDEN FOR YOUR LEVEL)'
                      : '$pendingVisibleCount PENDING',
                  style: AppText.caption,
                ),
              );

              if (docs.isEmpty) {
                return Column(
                  children: [
                    countLine,
                    const Expanded(
                      child: EmptyState(
                        icon: Icons.task_alt,
                        title: 'NO PENDING APPROVALS',
                        hint: 'A JOB APPEARS HERE AFTER A VERIFIED QUOTATION IS SENT FOR APPROVAL',
                      ),
                    ),
                  ],
                );
              }

              return Column(
                children: [
                  countLine,
                  Expanded(
                    child: ListView.builder(
                padding: const EdgeInsets.all(AppSpacing.md),
                itemCount: docs.length,
                itemBuilder: (context, index) {
                  final doc = docs[index];
                  final data = doc.data() as Map<String, dynamic>;
                  final decision = (data['decision'] ?? 'PENDING').toString();
                  final amountCents = (data['amountCents'] as num?)?.toInt() ?? 0;
                  return AppStaggeredFadeIn(
                    index: index,
                    child: Padding(
                      padding: const EdgeInsets.only(bottom: AppSpacing.sm),
                      child: AppCard(
                        onTap: () {
                          debugPrint(
                            '[APPROVAL] tap id=${doc.id} type=${data['approvalType']} '
                            'quotationId=${data['quotationId']} '
                            'repairJobId=${data['repairJobId']}',
                          );
                          pushWebAware(
                            context,
                            RepairApprovalDetailScreen(
                              approvalId: doc.id,
                              currentUid: uid ?? '',
                              firestoreOverride: widget.firestoreOverride,
                            ),
                          );
                        },
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Row(
                              children: [
                                Expanded(
                                  child: Text(
                                    '${data['approvalNo'] ?? ''} — '
                                    '${data['vehicleNumber'] ?? ''}',
                                    style: AppText.section,
                                  ),
                                ),
                                StatusChip(status: decision),
                              ],
                            ),
                            Text(
                              '${data['approvalType'] == 'ADDITIONAL_COST' ? 'Additional Cost' : (data['garageName'] ?? '')} • '
                              '${_formatMoney(_centsToMoney(amountCents))} • '
                              '${data['requiredLevel'] ?? ''}',
                              style: AppText.caption,
                            ),
                          ],
                        ),
                      ),
                    ),
                  );
                },
              ),
            ),
          ],
        );
            },
          );
        },
      ),
    );
  }
}

// ---------------- APPROVAL DETAIL ----------------
class RepairApprovalDetailScreen extends StatefulWidget {
  final String approvalId;
  final String currentUid;
  // Test-only injection seam — null in every production call site, which
  // falls back to the real FirebaseFirestore.instance. Lets widget tests
  // pass a FakeFirebaseFirestore (see repair_approval_detail_test.dart)
  // without touching any other call site in this 56k-line file.
  final FirebaseFirestore? firestoreOverride;
  const RepairApprovalDetailScreen({
    super.key,
    required this.approvalId,
    required this.currentUid,
    this.firestoreOverride,
  });

  @override
  State<RepairApprovalDetailScreen> createState() =>
      _RepairApprovalDetailScreenState();
}

class _RepairApprovalDetailScreenState
    extends State<RepairApprovalDetailScreen> {
  bool _deciding = false;

  FirebaseFirestore get _db => widget.firestoreOverride ?? FirebaseFirestore.instance;

  static const _loadTimeout = Duration(seconds: 15);

  // Debug-only (kDebugMode) on-screen footer — approval id, build count,
  // and which sub-load the screen is currently showing/waiting on/erroring
  // on. Stacked under the real content so it never shifts layout.
  Widget _debugWrap(Widget child, String status) {
    if (!kDebugMode) return child;
    return Stack(
      children: [
        Positioned.fill(child: child),
        Positioned(
          left: 0,
          right: 0,
          bottom: 0,
          child: Container(
            color: Colors.black87,
            padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 4),
            child: Text(
              '[APPROVAL] id=${widget.approvalId} build#$_buildCount $status',
              style: const TextStyle(color: Colors.lightGreenAccent, fontSize: 10),
            ),
          ),
        ),
      ],
    );
  }

  // Re-derived independently of widget.canDecideRole (passed in only as a
  // hint from the list screen) so direct navigation to this screen can't
  // bypass the APPROVE check — see canDecideRole below, computed fresh from
  // this and the approval doc's own requiredLevel. Bundled with the
  // workflow settings (for Test Mode's identity-exclusion bypass) in one
  // Future so build() only needs a single extra FutureBuilder. A mutable
  // field (not `late final`) + initState()/retry so a timeout or error can
  // actually be retried with a fresh Future, instead of FutureBuilder
  // replaying the same completed-with-error Future forever.
  late Future<(Map<String, dynamic>?, RepairWorkflowSettings)> _userDataFuture;

  // Cached by a key derived from the approval doc's own fields, so a
  // document-level rebuild (e.g. another user deciding, or the harmless
  // cache-then-server double emission every Firestore listener produces)
  // does NOT recreate this Future on every build() — ROOT CAUSE of the
  // "stuck on loading forever" bug: a FutureBuilder whose `future:` is a
  // fresh instance on every rebuild resets to ConnectionState.waiting
  // before the previous call can ever resolve and render, so a document
  // that updates even moderately often (or a `repair_jobs` read slower
  // than the next rebuild) could show nothing but a spinner indefinitely.
  String? _jobOrQuotationKey;
  Future<Map<String, dynamic>?>? _jobOrQuotationFuture;

  String? _defectKey;
  Future<Map<String, dynamic>?>? _defectFuture;

  // Diagnostics only (all prefixed '[APPROVAL]' per the bug report) — a
  // climbing _buildCount that never stops climbing is the signature of a
  // rebuild loop; if that's what's happening, every Future/Stream below
  // gets torn down and replaced before it can ever finish, which is why a
  // 15s timeout would never visibly fire (no single Future lives 15s).
  int _buildCount = 0;

  // Built ONCE in initState (not inline in build()) — this was the one
  // remaining "stream built inside build()" spot: the previous fix cached
  // the job/quotation/defect loads but left THIS, the outermost stream
  // driving the whole screen, recreated on every build() via the `_ref`
  // getter. Cloud Firestore's .snapshots() returns a new Stream object
  // every call, and StreamBuilder resets to ConnectionState.waiting
  // whenever its `stream:` identity changes — so if ANYTHING caused this
  // State to rebuild repeatedly, this stream would restart every time and
  // could never settle, no matter how fast repair_approvals/<id> itself
  // loads.
  late Stream<DocumentSnapshot> _approvalStream;

  @override
  void initState() {
    super.initState();
    debugPrint('[APPROVAL] initState approvalId=${widget.approvalId} '
        'currentUid=${widget.currentUid}');
    _approvalStream = _ref.snapshots().timeout(
      _loadTimeout,
      onTimeout: (sink) {
        debugPrint(
          '[APPROVAL] TIMEOUT repair_approvals/${widget.approvalId} produced '
          'no snapshot within $_loadTimeout',
        );
        sink.addError(
          TimeoutException('Taking too long to load this approval.'),
        );
      },
    );
    _loadUserData();
  }

  void _loadUserData() {
    debugPrint('[APPROVAL] _loadUserData START approvalId=${widget.approvalId}');
    _userDataFuture = () async {
      final uid = widget.currentUid;
      final results = await Future.wait([
        uid.isEmpty
            ? Future.value(null)
            : _db
                .collection('users')
                .doc(uid)
                .get()
                .then((d) => d.data()),
        _fetchRepairWorkflowSettings(db: _db),
      ]);
      return (
        results[0] as Map<String, dynamic>?,
        results[1] as RepairWorkflowSettings,
      );
    }().timeout(_loadTimeout).then((result) {
      debugPrint('[APPROVAL] _loadUserData DONE approvalId=${widget.approvalId} '
          'userFound=${result.$1 != null}');
      return result;
    }).catchError((Object e, StackTrace st) {
      debugPrint('[APPROVAL] _loadUserData ERROR approvalId=${widget.approvalId}: $e');
      throw e;
    });
  }

  // Simple-mode approvals have no quotation — quotationRef is null, so this
  // fetches the repair_job itself instead (same "no quotation" shape as
  // ADDITIONAL_COST, which never calls this at all).
  Future<Map<String, dynamic>?> _getJobOrQuotationFuture({
    required bool isSimpleRepair,
    required DocumentReference? quotationRef,
    required DocumentReference jobRef,
  }) {
    final key = isSimpleRepair ? 'job:${jobRef.path}' : 'quotation:${quotationRef?.path ?? 'none'}';
    if (_jobOrQuotationKey != key) {
      _jobOrQuotationKey = key;
      final collection = isSimpleRepair ? 'repair_jobs' : 'repair_quotations';
      debugPrint('[APPROVAL] jobOrQuotation START key=$key');
      final load = isSimpleRepair
          ? jobRef.get().then((s) => s.data() as Map<String, dynamic>?)
          : (quotationRef == null
              ? Future.value(null)
              : quotationRef.get().then((s) => s.data() as Map<String, dynamic>?));
      _jobOrQuotationFuture = load.timeout(_loadTimeout).then((data) {
        debugPrint('[APPROVAL] jobOrQuotation DONE key=$key found=${data != null}');
        return data;
      }).catchError((Object e, StackTrace st) {
        debugPrint('[APPROVAL] jobOrQuotation ERROR key=$key collection=$collection: $e');
        throw e;
      });
    }
    return _jobOrQuotationFuture!;
  }

  void _retryJobOrQuotation() => setState(() => _jobOrQuotationKey = null);

  Future<Map<String, dynamic>?> _getDefectFuture(String defectId) {
    if (_defectKey != defectId) {
      _defectKey = defectId;
      debugPrint('[APPROVAL] defect START defectId=$defectId');
      _defectFuture = _db
          .collection('defect_reports')
          .doc(defectId)
          .get()
          .then((s) => s.data())
          .timeout(_loadTimeout)
          .then((data) {
        debugPrint('[APPROVAL] defect DONE defectId=$defectId found=${data != null}');
        return data;
      }).catchError((Object e, StackTrace st) {
        debugPrint('[APPROVAL] defect ERROR defectId=$defectId: $e');
        throw e;
      });
    }
    return _defectFuture!;
  }

  void _retryDefect() => setState(() => _defectKey = null);

  DocumentReference get _ref =>
      _db.collection('repair_approvals').doc(widget.approvalId);

  Future<void> _decide({
    required bool approve,
    required Map<String, dynamic> approvalData,
    required DocumentReference? quotationRef,
    required DocumentReference jobRef,
  }) async {
    final isAdditionalCost = approvalData['approvalType'] == 'ADDITIONAL_COST';
    final isSimpleRepair = approvalData['approvalType'] == 'SIMPLE_REPAIR';
    String? rejectReason;
    if (!approve) {
      final controller = TextEditingController();
      final confirmed = await showDialog<bool>(
        context: context,
        builder: (dialogContext) => AlertDialog(
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(AppRadius.card),
          ),
          title: Text(isSimpleRepair ? 'Return To Mechanic' : 'Reject Approval'),
          content: TextField(
            controller: controller,
            inputFormatters: [UpperCaseTextFormatter()],
            textCapitalization: TextCapitalization.characters,
            maxLines: 3,
            decoration: InputDecoration(
              labelText: isSimpleRepair ? 'Reason for return (required)' : 'Reason (required)',
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dialogContext, false),
              child: const Text('Cancel'),
            ),
            ElevatedButton(
              style: ElevatedButton.styleFrom(backgroundColor: AppColors.danger),
              onPressed: () => Navigator.pop(dialogContext, true),
              child: Text(isSimpleRepair ? 'Return' : 'Reject'),
            ),
          ],
        ),
      );
      if (confirmed != true) return;
      if (controller.text.trim().isEmpty) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Please enter a reason.')),
        );
        return;
      }
      rejectReason = controller.text.trim();
    } else {
      final confirmed = await showAppConfirmDialog(
        context: context,
        title: isAdditionalCost ? 'Approve Additional Cost?' : 'Approve This Repair?',
        message: isAdditionalCost
            ? 'This approves an additional '
                '${_formatMoney(_centsToMoney(((approvalData['amountCents'] as num?)?.toInt() ?? 0)))} '
                'for ${approvalData['vehicleNumber'] ?? ''}.'
            : 'This approves '
                '${_formatMoney(_centsToMoney(((approvalData['amountCents'] as num?)?.toInt() ?? 0)))} '
                'for ${approvalData['vehicleNumber'] ?? ''}.',
        confirmLabel: 'Approve',
      );
      if (!confirmed) return;
    }

    setState(() => _deciding = true);
    try {
      final uid = FirebaseAuth.instance.currentUser?.uid ?? '';
      final userDoc =
          await FirebaseFirestore.instance.collection('users').doc(uid).get();
      final userName = (userDoc.data()?['name'] ?? 'Unknown').toString();

      await _ref.update({
        'decision': approve ? 'APPROVED' : 'REJECTED',
        'decidedBy': uid,
        'decidedByName': userName,
        'decidedAt': FieldValue.serverTimestamp(),
        if (!approve) 'rejectReason': rejectReason,
      });

      if (isAdditionalCost) {
        final extraCents = (approvalData['amountCents'] as num?)?.toInt() ?? 0;
        if (approve) {
          await jobRef.update({
            'approvedAmountCents': FieldValue.increment(extraCents),
            'additionalCostPending': false,
            'updatedBy': uid,
            'updatedByName': userName,
            'updatedAt': FieldValue.serverTimestamp(),
          });
        } else {
          await jobRef.update({
            'additionalCostPending': false,
            'updatedBy': uid,
            'updatedByName': userName,
            'updatedAt': FieldValue.serverTimestamp(),
          });
        }
      } else if (isSimpleRepair) {
        // Simple mode has no quotation to update — quotationRef is null
        // here (same no-quotation shape as the ADDITIONAL_COST branch
        // above). RETURN sends the job back to DIAGNOSED (the mechanic's
        // "Defects To Check" list picks it up again) instead of QUOTING,
        // since simple mode has no quoting stage.
        if (approve) {
          await jobRef.update({
            'repairStatus': RepairStatus.approved,
            'approvedAmountCents': approvalData['amountCents'],
            'approvedBy': uid,
            'approvedByName': userName,
            'approvedAt': FieldValue.serverTimestamp(),
            'updatedBy': uid,
            'updatedByName': userName,
            'updatedAt': FieldValue.serverTimestamp(),
          });
        } else {
          await jobRef.update({
            'repairStatus': RepairStatus.diagnosed,
            'returnReason': rejectReason,
            'returnedBy': uid,
            'returnedByName': userName,
            'returnedAt': FieldValue.serverTimestamp(),
            'updatedBy': uid,
            'updatedByName': userName,
            'updatedAt': FieldValue.serverTimestamp(),
          });
        }
      } else if (approve) {
        await quotationRef!.update({'status': QuotationStatus.approved});
        await jobRef.update({
          'repairStatus': RepairStatus.approved,
          'approvedAmountCents': approvalData['amountCents'],
          'approvedBy': uid,
          'approvedByName': userName,
          'approvedAt': FieldValue.serverTimestamp(),
          'updatedBy': uid,
          'updatedByName': userName,
          'updatedAt': FieldValue.serverTimestamp(),
        });
      } else {
        // BUG FIX: the quotation used to stay at status 'VERIFIED' forever
        // here — no button anywhere matches (isSelected && status ==
        // VERIFIED && repairStatus == QUOTING), so a rejected approval
        // permanently dead-ended the job. Resetting to REJECTED makes the
        // existing REVISE condition (status in [SUBMITTED, RETURNED,
        // REJECTED]) pick it back up.
        await quotationRef!.update({
          'status': QuotationStatus.rejected,
          'approvalRejectedBy': uid,
          'approvalRejectedByName': userName,
          'approvalRejectedAt': FieldValue.serverTimestamp(),
          'approvalRejectReason': rejectReason,
        });
        await jobRef.update({
          'repairStatus': RepairStatus.quoting,
          'selectedQuotationId': null,
          'updatedBy': uid,
          'updatedByName': userName,
          'updatedAt': FieldValue.serverTimestamp(),
        });
      }

      await _writeRepairEvent(
        collection: 'repair_approvals',
        docId: widget.approvalId,
        action: approve ? 'APPROVED' : 'REJECTED',
        summary: approve
            ? 'Approved by $userName'
            : 'Rejected by $userName — $rejectReason',
        actorUid: uid,
        actorName: userName,
      );
      await _writeRepairEvent(
        collection: 'repair_jobs',
        docId: jobRef.id,
        action: isAdditionalCost
            ? (approve ? 'ADDITIONAL_COST_APPROVED' : 'ADDITIONAL_COST_REJECTED')
            : isSimpleRepair
                ? (approve ? 'APPROVED' : 'RETURNED_TO_MECHANIC')
                : (approve ? 'APPROVED' : 'REJECTED_TO_QUOTING'),
        summary: isAdditionalCost
            ? (approve
                ? 'Additional cost approved by $userName'
                : 'Additional cost rejected by $userName')
            : isSimpleRepair
                ? (approve
                    ? 'Repair approved by $userName'
                    : 'Returned to mechanic by $userName — $rejectReason')
                : (approve
                    ? 'Repair approved by $userName'
                    : 'Rejected by $userName, back to Quoting'),
        actorUid: uid,
        actorName: userName,
      );

      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              approve ? 'Approved.' : (isSimpleRepair ? 'Returned to mechanic.' : 'Rejected.'),
            ),
          ),
        );
        Navigator.pop(context);
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Failed to save decision: $e')),
        );
      }
    } finally {
      if (mounted) setState(() => _deciding = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    _buildCount++;
    debugPrint('[APPROVAL] build() call #$_buildCount approvalId=${widget.approvalId}');
    return TruckRepairScaffold(
      appBar: AppBar(
        title: const Text('Approval Detail'),
        backgroundColor: AppColors.navy,
        foregroundColor: Colors.white,
      ),
      body: StreamBuilder<DocumentSnapshot>(
        stream: _approvalStream,
        builder: (context, snapshot) {
          if (snapshot.hasError) {
            debugPrint(
              '[APPROVAL] approvalStream ERROR approvalId=${widget.approvalId}: '
              '${snapshot.error}',
            );
            return _debugWrap(
              ErrorState(
                message: snapshot.error is TimeoutException
                    ? 'Taking too long — RETRY'
                    : 'Failed to load: ${snapshot.error}',
                onRetry: () => setState(() {}),
              ),
              'approval=ERROR ${snapshot.error}',
            );
          }
          if (!snapshot.hasData) {
            return _debugWrap(const LoadingState(), 'approval=PENDING');
          }
          if (!snapshot.data!.exists) {
            debugPrint('[APPROVAL] approvalStream DONE approvalId=${widget.approvalId} '
                'exists=false');
            return const EmptyState(
              icon: Icons.error_outline,
              title: 'This approval no longer exists.',
            );
          }
          final approvalData = snapshot.data!.data() as Map<String, dynamic>;
          debugPrint(
            '[APPROVAL] approvalStream DONE approvalId=${widget.approvalId} '
            'type=${approvalData['approvalType']} quotationId=${approvalData['quotationId']} '
            'repairJobId=${approvalData['repairJobId']}',
          );
          final decision = (approvalData['decision'] ?? 'PENDING').toString();
          final isAdditionalCost = approvalData['approvalType'] == 'ADDITIONAL_COST';
          final isSimpleRepair = approvalData['approvalType'] == 'SIMPLE_REPAIR';
          final quotationId = (approvalData['quotationId'] ?? '').toString();
          final jobId = (approvalData['repairJobId'] ?? '').toString();
          final quotationRef = quotationId.isEmpty
              ? null
              : _db.collection('repair_quotations').doc(quotationId);
          final jobRef = _db.collection('repair_jobs').doc(jobId);

          return FutureBuilder<(Map<String, dynamic>?, RepairWorkflowSettings)>(
            future: _userDataFuture,
            builder: (context, userDataSnap) {
              if (userDataSnap.connectionState != ConnectionState.done) {
                return _debugWrap(const LoadingState(), 'approval=DONE user=PENDING');
              }
              if (userDataSnap.hasError) {
                debugPrint(
                  '[APPROVAL] userData ERROR approvalId=${widget.approvalId}: '
                  '${userDataSnap.error}',
                );
                return _debugWrap(
                  ErrorState(
                    message: userDataSnap.error is TimeoutException
                        ? 'Taking too long — RETRY'
                        : 'Failed to load: ${userDataSnap.error}',
                    onRetry: () => setState(_loadUserData),
                  ),
                  'approval=DONE user=ERROR ${userDataSnap.error}',
                );
              }
              final userData = userDataSnap.data?.$1;
              final testModeOn = userDataSnap.data?.$2.testModeAllowSameUser == true;
              final role = userData?['role'] as String?;
              final isAdminOrOwner = role == 'admin' || role == 'owner';
              final canDecideRole = isAdminOrOwner ||
                  (hasRepairPerm(userData, kPermApprove) &&
                      approvalData['requiredLevel'] == 'MANAGER');
              return FutureBuilder<Map<String, dynamic>?>(
            future: _getJobOrQuotationFuture(
              isSimpleRepair: isSimpleRepair,
              quotationRef: quotationRef,
              jobRef: jobRef,
            ),
            builder: (context, quotationSnap) {
              if (quotationSnap.connectionState != ConnectionState.done) {
                return _debugWrap(
                  const LoadingState(),
                  'approval=DONE user=DONE ${isSimpleRepair ? 'job' : 'quotation'}=PENDING',
                );
              }
              if (quotationSnap.hasError) {
                debugPrint(
                  '[APPROVAL] ${isSimpleRepair ? 'job' : 'quotation'} ERROR '
                  'approvalId=${widget.approvalId}: ${quotationSnap.error}',
                );
                return _debugWrap(
                  ErrorState(
                    message: quotationSnap.error is TimeoutException
                        ? 'Taking too long — RETRY'
                        : 'Failed to load: ${quotationSnap.error}',
                    onRetry: _retryJobOrQuotation,
                  ),
                  'approval=DONE user=DONE '
                  '${isSimpleRepair ? 'job' : 'quotation'}=ERROR ${quotationSnap.error}',
                );
              }
              debugPrint(
                '[APPROVAL] ${isSimpleRepair ? 'job' : 'quotation'} DONE '
                'approvalId=${widget.approvalId} found=${quotationSnap.data != null}',
              );
              final quotationData = quotationSnap.data ?? {};
              final enteredBy = isSimpleRepair
                  ? quotationData['mechanicalSupervisorId'] as String?
