                              child: verification == null
                                  ? Text('Not verified.', style: AppText.caption)
                                  : Column(
                                      crossAxisAlignment:
                                          CrossAxisAlignment.start,
                                      children: [
                                        Text(
                                          'Verified by: '
                                          '${verification['verifiedByName'] ?? ''}',
                                        ),
                                        Text(
                                          'Site visit done: '
                                          '${verification['siteVisitDone'] == true ? 'Yes' : 'No'}',
                                        ),
                                        Text(
                                          'Diagnosis matches: '
                                          '${verification['diagnosisMatches'] == true ? 'Yes' : 'No'}',
                                        ),
                                        Text(
                                          'Prices reasonable: '
                                          '${verification['pricesReasonable'] == true ? 'Yes' : 'No'}',
                                        ),
                                        if ((verification['comments'] ?? '')
                                            .toString()
                                            .isNotEmpty)
                                          Text(
                                            'Comments: ${verification['comments']}',
                                          ),
                                      ],
                                    ),
                            ),
                          ],
                          const SizedBox(height: AppSpacing.lg),
                          if (decision == 'PENDING') ...[
                            if (!canDecideRole)
                              Text(
                                'Read-only for your role.',
                                style: AppText.caption,
                              )
                            else if (!canDecide)
                              Text(
                                'You cannot decide this approval because you '
                                'entered, verified, or requested it.',
                                style: AppText.caption.copyWith(
                                  color: AppColors.danger,
                                ),
                              )
                            else
                              Row(
                                children: [
                                  Expanded(
                                    child: ElevatedButton(
                                      onPressed: _deciding
                                          ? null
