// Single unfiltered read of repair_invoices (no where/orderBy at all) with
// client-side grouping-by-garage — a management summary screen, so reading
// the whole (modest-sized) collection per load is fine and needs no index.
class _OutstandingTab extends StatelessWidget {
  const _OutstandingTab();

  @override
  Widget build(BuildContext context) {
    return StreamBuilder<QuerySnapshot>(
      stream: FirebaseFirestore.instance.collection('repair_invoices').snapshots(),
      builder: (context, snapshot) {
        if (snapshot.hasError) {
          return ErrorState(message: 'Failed to load: ${snapshot.error}', onRetry: () {});
        }
        if (!snapshot.hasData) return const LoadingState();
        final byGarage = <String, int>{};
        final namesByGarage = <String, String>{};
        for (final doc in snapshot.data!.docs) {
          final d = doc.data() as Map<String, dynamic>;
          final outstanding = (d['outstandingCents'] as num?)?.toInt() ?? 0;
          if (outstanding <= 0) continue;
          final garageId = (d['garageId'] ?? 'unknown').toString();
          byGarage[garageId] = (byGarage[garageId] ?? 0) + outstanding;
          namesByGarage[garageId] = (d['garageName'] ?? 'Unknown Garage').toString();
        }
        final entries = byGarage.entries.toList()..sort((a, b) => b.value.compareTo(a.value));
        if (entries.isEmpty) {
          return const EmptyState(icon: Icons.check_circle_outline, title: 'No outstanding balances.');
        }
        final grandTotal = entries.fold<int>(0, (sum, e) => sum + e.value);
        return ListView(
          padding: const EdgeInsets.all(AppSpacing.md),
          children: [
            AppCard(
              child: Row(
                children: [
                  Expanded(child: Text('Total Outstanding', style: AppText.section)),
                  Text(
                    _formatMoney(_centsToMoney(grandTotal)),
                    style: AppText.title.copyWith(color: AppColors.danger),
                  ),
                ],
              ),
            ),
            const SizedBox(height: AppSpacing.md),
            ...entries.map((e) => Padding(
                  padding: const EdgeInsets.only(bottom: AppSpacing.sm),
                  child: AppCard(
                    child: Row(
                      children: [
                        Expanded(child: Text(namesByGarage[e.key] ?? '', style: AppText.section)),
                        Text(
                          _formatMoney(_centsToMoney(e.value)),
                          style: AppText.section.copyWith(color: AppColors.danger),
                        ),
                      ],
                    ),
                  ),
                )),
          ],
        );
      },
    );
  }
}

class _InvoicesTab extends StatefulWidget {
  const _InvoicesTab();

  @override
  State<_InvoicesTab> createState() => _InvoicesTabState();
}

class _InvoicesTabState extends State<_InvoicesTab> {
  String _statusFilter = 'ALL';
  final _garageController = TextEditingController();
  DateTimeRange? _dateRange;

  @override
  void dispose() {
    _garageController.dispose();
    super.dispose();
  }

  Future<void> _pickDateRange() async {
    final picked = await showDateRangePicker(
      context: context,
      firstDate: DateTime(2020),
      lastDate: DateTime.now().add(const Duration(days: 1)),
      initialDateRange: _dateRange,
    );
    if (picked != null) setState(() => _dateRange = picked);
  }

  @override
  Widget build(BuildContext context) {
    return StreamBuilder<QuerySnapshot>(
      stream: FirebaseFirestore.instance.collection('repair_invoices').snapshots(),
      builder: (context, snapshot) {
        if (snapshot.hasError) {
          return ErrorState(message: 'Failed to load: ${snapshot.error}', onRetry: () => setState(() {}));
        }
        if (!snapshot.hasData) return const LoadingState();
        var docs = snapshot.data!.docs;
        if (_statusFilter != 'ALL') {
          docs = docs
              .where((d) =>
                  ((d.data() as Map<String, dynamic>)['verification']
                      as Map<String, dynamic>?)?['status'] ==
                  _statusFilter)
              .toList();
        }
        final garageQuery = _garageController.text.trim().toLowerCase();
        if (garageQuery.isNotEmpty) {
          docs = docs
              .where((d) => ((d.data() as Map<String, dynamic>)['garageName'] ?? '')
                  .toString()
                  .toLowerCase()
                  .contains(garageQuery))
              .toList();
        }
        if (_dateRange != null) {
          docs = docs.where((d) {
            final ts = (d.data() as Map<String, dynamic>)['invoiceDate'] as Timestamp?;
            if (ts == null) return false;
            final dt = ts.toDate();
            return !dt.isBefore(_dateRange!.start) &&
                !dt.isAfter(_dateRange!.end.add(const Duration(days: 1)));
          }).toList();
        }
        docs = [...docs]..sort((a, b) {
            final at =
                ((a.data() as Map<String, dynamic>)['createdAt'] as Timestamp?)
                        ?.millisecondsSinceEpoch ??
                    0;
            final bt =
                ((b.data() as Map<String, dynamic>)['createdAt'] as Timestamp?)
                        ?.millisecondsSinceEpoch ??
                    0;
            return bt.compareTo(at);
          });

        return Column(
          children: [
            Padding(
              padding: const EdgeInsets.all(AppSpacing.md),
              child: Column(
                children: [
                  Row(
                    children: [
                      Expanded(
                        child: DropdownButtonFormField<String>(
                          initialValue: _statusFilter,
                          decoration: const InputDecoration(labelText: 'Status', isDense: true),
                          items: const ['ALL', 'PENDING', 'VERIFIED', 'RETURNED']
                              .map((s) => DropdownMenuItem(value: s, child: Text(s)))
                              .toList(),
                          onChanged: (v) => setState(() => _statusFilter = v ?? 'ALL'),
                        ),
                      ),
                      const SizedBox(width: 8),
                      IconButton(icon: const Icon(Icons.date_range), onPressed: _pickDateRange),
                      if (_dateRange != null)
                        IconButton(
                          icon: const Icon(Icons.clear),
                          onPressed: () => setState(() => _dateRange = null),
                        ),
                    ],
                  ),
                  TextField(
                    controller: _garageController,
                    inputFormatters: [UpperCaseTextFormatter()],
                    textCapitalization: TextCapitalization.characters,
                    decoration: const InputDecoration(
                      labelText: 'Search Garage',
                      prefixIcon: Icon(Icons.search),
                      isDense: true,
                    ),
                    onChanged: (_) => setState(() {}),
                  ),
                ],
              ),
            ),
            Expanded(
              child: docs.isEmpty
                  ? const EmptyState(icon: Icons.receipt_long, title: 'No invoices found.')
                  : ListView.builder(
                      padding: const EdgeInsets.all(AppSpacing.md),
                      itemCount: docs.length,
                      itemBuilder: (context, index) {
                        final doc = docs[index];
                        final d = doc.data() as Map<String, dynamic>;
                        final vStatus = ((d['verification'] as Map<String, dynamic>?)?['status'] ??
                                'PENDING')
                            .toString();
                        final totalCents = (d['totalCents'] as num?)?.toInt() ?? 0;
                        return Padding(
                          padding: const EdgeInsets.only(bottom: AppSpacing.sm),
                          child: AppCard(
                            onTap: () => pushWebAware(context, InvoiceDetailScreen(invoiceId: doc.id)),
                            child: Row(
                              children: [
                                Expanded(
                                  child: Column(
                                    crossAxisAlignment: CrossAxisAlignment.start,
                                    children: [
                                      Text('${d['invoiceNo'] ?? ''} — ${d['garageName'] ?? ''}',
                                          style: AppText.section),
                                      Text(
                                        '${_formatMoney(_centsToMoney(totalCents))} • '
                                        '${d['paymentStatus'] ?? ''}',
                                        style: AppText.caption,
                                      ),
                                    ],
                                  ),
                                ),
                                StatusChip(status: vStatus),
                              ],
                            ),
                          ),
                        );
                      },
                    ),
            ),
          ],
        );
      },
    );
  }
}

