// Same purpose/shape as _GarageNotificationsTab — every item (any category)
// at or below its own lowStockThreshold, worst-first. A collectionGroup
// isn't needed since warehouse_items is already a flat top-level
// collection; unlike Garage's per-truck GPS fetch this is a single
// Firestore query with no external API calls.
class _WarehouseNotificationsTab extends StatelessWidget {
  const _WarehouseNotificationsTab();

  @override
  Widget build(BuildContext context) {
    return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
      stream: FirebaseFirestore.instance
          .collection(kWarehouseItemsCollection)
          .snapshots(),
      builder: (context, snapshot) {
        if (snapshot.connectionState == ConnectionState.waiting) {
          return const Center(child: CircularProgressIndicator());
        }
        if (snapshot.hasError) {
          return Center(child: Text('Failed to load: ${snapshot.error}'));
        }
        final lowItems =
            (snapshot.data?.docs ?? []).where((doc) {
                final data = doc.data();
                final currentQuantity =
                    (data['currentQuantity'] as num?)?.toDouble() ?? 0;
                final lowStockThreshold =
                    (data['lowStockThreshold'] as num?)?.toDouble() ?? 0;
                return currentQuantity <= lowStockThreshold;
              }).toList()
              ..sort((a, b) {
                final aRemaining =
                    (a.data()['currentQuantity'] as num?)?.toDouble() ?? 0;
                final bRemaining =
                    (b.data()['currentQuantity'] as num?)?.toDouble() ?? 0;
                return aRemaining.compareTo(bRemaining);
              });
        if (lowItems.isEmpty) {
          return const Center(
            child: Text(
              'No low-stock items.',
              style: TextStyle(color: Colors.grey),
            ),
          );
        }
        return ListView.builder(
          padding: const EdgeInsets.all(12),
          itemCount: lowItems.length,
          itemBuilder: (context, index) {
            final data = lowItems[index].data();
            final currentQuantity =
                (data['currentQuantity'] as num?)?.toDouble() ?? 0;
            final unit = (data['unit'] ?? '').toString();
            return Card(
              color: Colors.red[50],
              margin: const EdgeInsets.only(bottom: 10),
              child: ListTile(
                leading: const Icon(
                  Icons.warning_amber_rounded,
                  color: Colors.red,
                ),
                title: Text(
                  (data['itemName'] ?? '').toString(),
                  style: const TextStyle(fontWeight: FontWeight.bold),
                ),
                subtitle: Text(
                  '${warehouseCategoryLabel((data['category'] ?? '').toString())} — '
                  'Low Stock: ${currentQuantity.toStringAsFixed(1)} $unit remaining',
                  style: const TextStyle(color: Colors.red),
                ),
              ),
            );
          },
        );
      },
    );
  }
}

// ============================================================
// TRUCK REPAIR v2 (REPORTED -> LISTED -> IN_PROGRESS ->
// DONE_PENDING_APPROVAL -> COMPLETED; RETURNED/REJECTED)
// ============================================================
// Replacement for the old defect_reports/repair_jobs/quotations/invoices/
// payments pipeline (kept untouched elsewhere in this file for now — see
// the rebuild plan this was built from). STEP 1: purely additive — nothing
// below is referenced by any existing screen yet, so no old screen's
// behavior changes from this addition. Wiring (Step 2) and the dashboard/
// permission rebuild (Step 3) come later.

class RepairItemStatus {
  static const reported = 'REPORTED';
  static const listed = 'LISTED';
  static const inProgress = 'IN_PROGRESS';
  static const donePendingApproval = 'DONE_PENDING_APPROVAL';
  static const completed = 'COMPLETED';
  static const returned = 'RETURNED';
  static const rejected = 'REJECTED';

  static const List<String> all = [
    reported,
    listed,
    inProgress,
    donePendingApproval,
    completed,
    returned,
    rejected,
  ];

  // "Still needs technical's attention" — drives REPAIRS TO DO's query.
  static const List<String> technicalQueue = [listed, inProgress, returned];

  // No more technical action pending (approved, rejected before listing, or
  // waiting on management) — drives repair_lists' doneCount/ALL_DONE calc.
  static bool isTechnicalDone(String s) =>
      s == donePendingApproval || s == completed || s == rejected;
}

class RepairListStatus {
  static const draft = 'DRAFT';
  static const submitted = 'SUBMITTED';
  static const allDone = 'ALL_DONE';
}

const String kRepairSeverityNormal = 'NORMAL';
const String kRepairSeverityUrgent = 'URGENT';
const List<String> kRepairSeverities = [kRepairSeverityNormal, kRepairSeverityUrgent];

class RepairCategorySeed {
  final String code;
  final String name;
  const RepairCategorySeed(this.code, this.name);
}

const List<RepairCategorySeed> kDefaultRepairCategories = [
  RepairCategorySeed('ENG', 'Engine'),
  RepairCategorySeed('BRK', 'Brakes'),
  RepairCategorySeed('TYR', 'Tyres and wheels'),
  RepairCategorySeed('GBX', 'Gearbox and transmission'),
  RepairCategorySeed('CLT', 'Clutch'),
  RepairCategorySeed('STR', 'Steering'),
  RepairCategorySeed('SUS', 'Suspension'),
  RepairCategorySeed('ELE', 'Battery and electrical'),
  RepairCategorySeed('LGT', 'Lights and indicators'),
  RepairCategorySeed('COL', 'Cooling system and radiator'),
  RepairCategorySeed('FUE', 'Fuel system'),
  RepairCategorySeed('HYD', 'Hydraulic system'),
  RepairCategorySeed('BDY', 'Chassis and body'),
  RepairCategorySeed('OTH', 'Other components'),
];

// Pure — "{prefix}/{CAT}/{yy}{4-digit running}", e.g. NOD/ENG/260001.
String buildRepairCode({
  required String companyPrefix,
  required String categoryCode,
  required int year,
  required int runningNumber,
}) {
  final yy = (year % 100).toString().padLeft(2, '0');
  return '$companyPrefix/$categoryCode/$yy${runningNumber.toString().padLeft(4, '0')}';
}

String repairCounterId(String categoryCode, int year) {
  final yy = (year % 100).toString().padLeft(2, '0');
  return 'repair_${categoryCode}_$yy';
}

// Transaction-safe sibling of _nextRepairSequenceNumber (Phase 1 repair
// flow) — that one counter never resets and has no category dimension, so
// it can't be reused for a per-category-per-year running number. Counter
// doc: counters/repair_{CAT}_{yy}.
Future<String> nextRepairCode({
  required String companyPrefix,
  required String categoryCode,
  FirebaseFirestore? db,
  DateTime? now,
}) {
  final firestore = db ?? FirebaseFirestore.instance;
  final year = (now ?? DateTime.now()).year;
  final ref = firestore.collection('counters').doc(repairCounterId(categoryCode, year));
  return firestore.runTransaction<String>((transaction) async {
    final snap = await transaction.get(ref);
    final current = (snap.data()?['value'] as num?)?.toInt() ?? 0;
    final next = current + 1;
    transaction.set(ref, {'value': next}, SetOptions(merge: true));
    return buildRepairCode(
      companyPrefix: companyPrefix,
      categoryCode: categoryCode,
      year: year,
      runningNumber: next,
    );
  });
}

// Pure — true when an open (not COMPLETED/REJECTED) repair already exists
// for this vehicle+category, driving the "LINK / ADD ANYWAY" warning.
bool hasOpenDuplicateRepair({
  required List<Map<String, dynamic>> existingRepairs,
  required String vehicleNumber,
  required String categoryCode,
}) {
  return existingRepairs.any((r) =>
      (r['vehicleNumber'] ?? '').toString() == vehicleNumber &&
      (r['categoryCode'] ?? '').toString() == categoryCode &&
      r['status'] != RepairItemStatus.completed &&
      r['status'] != RepairItemStatus.rejected);
}

// Pure — mirrors the Firestore rules: REPAIR_WORK may move a repair that is
// currently LISTED/IN_PROGRESS/RETURNED into IN_PROGRESS or
// DONE_PENDING_APPROVAL only (never LISTED/REPORTED/REJECTED/RETURNED/
// COMPLETED).
bool canTechnicalSetRepairStatus(String from, String to) =>
    RepairItemStatus.technicalQueue.contains(from) &&
    (to == RepairItemStatus.inProgress || to == RepairItemStatus.donePendingApproval);

// Pure — mirrors the Firestore rules: only APPROVE holders ever set
// LISTED/REPORTED/REJECTED/RETURNED/COMPLETED.
bool canManagementSetRepairStatus(String from, String to) {
  const targets = {
    RepairItemStatus.listed,
    RepairItemStatus.reported,
    RepairItemStatus.rejected,
    RepairItemStatus.returned,
    RepairItemStatus.completed,
  };
  return targets.contains(to);
}

// Pure — recomputes a repair_lists doc's own status/doneCount from its
// member repairs' current statuses. Called by both the technical
// MARK DONE flow and the management RETURN flow (every write to
// repair_lists.status/doneCount/updatedAt goes through this, never a
// hand-rolled calculation at the call site).
({String status, int doneCount}) computeRepairListProgress(List<String> itemStatuses) {
  final doneCount = itemStatuses.where(RepairItemStatus.isTechnicalDone).length;
  final status = (itemStatuses.isNotEmpty && doneCount == itemStatuses.length)
      ? RepairListStatus.allDone
      : RepairListStatus.submitted;
  return (status: status, doneCount: doneCount);
}

// Root-cause fix for the RepairCategoriesScreen "Taking too long" bug
// (confirmed live: console showed repair_categories DONE with 14 docs,
// then a timeout fired anyway). Stream.timeout() resets its internal timer
// on EVERY event, data or error — it does not stop once the first event
// has arrived. So a real-time Firestore listener that delivers one
// snapshot and then goes quiet (nothing changed) for `duration` is
// INCORRECTLY timed out, discarding already-loaded data. This wraps a
// source stream so the timeout only ever guards the wait for the FIRST
// event; once anything (data or error) has been delivered, every
// subsequent event — including a later real error — passes through
// untouched and no further synthetic timeout is ever produced. Used by
// every repair v2 and Service-module screen that listens to a collection
// via .snapshots() (see this session's report for the full file:line
// list) in place of the previous `source.snapshots().timeout(duration,
// onTimeout: ...)` pattern.
Stream<T> timeoutFirstEventOnly<T>(
  Stream<T> source,
  Duration duration, {
  required TimeoutException Function() onTimeout,
}) {
  var firstEventSeen = false;
  Timer? timer;
  final controller = StreamController<T>();

  void cancelTimer() {
    timer?.cancel();
    timer = null;
  }

  final subscription = source.listen(
    (event) {
      firstEventSeen = true;
      cancelTimer();
      controller.add(event);
    },
    onError: (Object error, StackTrace stackTrace) {
      firstEventSeen = true;
      cancelTimer();
      controller.addError(error, stackTrace);
    },
    onDone: () {
      cancelTimer();
      controller.close();
    },
  );
  timer = Timer(duration, () {
    if (!firstEventSeen) {
      controller.addError(onTimeout());
    }
  });
  controller.onCancel = () {
    cancelTimer();
    return subscription.cancel();
  };
  return controller.stream;
}

// ---------------- REPAIR CATEGORIES (admin) ----------------
class RepairCategoriesScreen extends StatefulWidget {
  final FirebaseFirestore? firestoreOverride;
  final String? currentUidOverride;
  // Test-only seam — shortens the first-event wait so a widget test can
  // prove the timeout never re-fires after the first snapshot without
  // waiting 15 real seconds. Defaults to 15s in production.
  final Duration categoriesTimeout;
  const RepairCategoriesScreen({
    super.key,
    this.firestoreOverride,
    this.currentUidOverride,
    this.categoriesTimeout = const Duration(seconds: 15),
  });

  @override
  State<RepairCategoriesScreen> createState() => _RepairCategoriesScreenState();
}

class _RepairCategoriesScreenState extends State<RepairCategoriesScreen> {
  FirebaseFirestore get _db => widget.firestoreOverride ?? FirebaseFirestore.instance;
  String? get _uid => widget.currentUidOverride ?? FirebaseAuth.instance.currentUser?.uid;
  late Future<bool> _accessFuture = _loadAccess();
  final _table = DataTableController<QueryDocumentSnapshot>();
  late Stream<QuerySnapshot> _categoriesStream = _buildCategoriesStream();
  bool _busy = false;

  // TEMPORARY [REPCAT] debug logging — added to diagnose the "Taking too
  // long" timeout on RepairCategoriesScreen. Remove once the root cause
  // (missing firestore.rules coverage for repair_categories/
  // settings/repair_numbering — see the audit report) is confirmed fixed
  // live.
  Future<bool> _loadAccess() async {
    final uid = _uid;
    if (uid == null) {
      debugPrint('[REPCAT] _loadAccess: no signed-in uid, denying access');
      return false;
    }
    debugPrint('[REPCAT] _loadAccess: start — users/$uid');
    try {
      final doc = await _db
          .collection('users')
          .doc(uid)
          .get()
          .timeout(const Duration(seconds: 15));
      final role = doc.data()?['role'] as String?;
      final allowed = role == 'admin' || role == 'owner';
      debugPrint('[REPCAT] _loadAccess: done — role=$role allowed=$allowed');
      return allowed;
    } catch (e) {
      final msg = e is FirebaseException ? '${e.code}: ${e.message}' : e.toString();
      debugPrint('[REPCAT] _loadAccess: ERROR reading users/$uid — $msg');
      rethrow;
    }
  }

  // Cached once (not rebuilt inline in build(), unlike before) — matches
  // NewRepairsInboxScreen/RepairsToDoScreen/RepairFinalApprovalScreen's
  // pattern. Uses timeoutFirstEventOnly, not Stream.timeout() directly —
  // confirmed live that Stream.timeout() re-fires after the FIRST snapshot
  // if the collection then goes quiet (nothing changed) for the timeout
  // duration, discarding already-loaded data; this only ever guards the
  // wait for the first snapshot. .handleError logs the real Firestore
  // error the moment it arrives, independent of whether it wins or loses
  // that initial race against the timer.
  Stream<QuerySnapshot> _buildCategoriesStream() {
    debugPrint('[REPCAT] repair_categories: start — orderBy(sortOrder)');
    final source = _db
        .collection('repair_categories')
        .orderBy('sortOrder')
        .snapshots()
        .handleError((Object e, StackTrace st) {
          final msg = e is FirebaseException ? '${e.code}: ${e.message}' : e.toString();
          debugPrint('[REPCAT] repair_categories: ERROR — $msg');
          throw e;
        })
        .map((snap) {
          debugPrint('[REPCAT] repair_categories: done — ${snap.docs.length} doc(s)');
          return snap;
        });
    return timeoutFirstEventOnly(
      source,
      widget.categoriesTimeout,
      onTimeout: () {
        debugPrint(
          '[REPCAT] repair_categories: TIMEOUT — no first snapshot and no '
          'error received from Firestore within ${widget.categoriesTimeout}.',
        );
        return TimeoutException('Taking too long to load categories.');
      },
    );
  }

  Future<void> _guarded(Future<void> Function() action) async {
    if (_busy) return;
    setState(() => _busy = true);
    try {
      await action();
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  Future<void> _seedDefaults() async {
    final existing = await _db.collection('repair_categories').get();
    final existingCodes = existing.docs.map((d) => d.id).toSet();
    final missing =
        kDefaultRepairCategories.where((c) => !existingCodes.contains(c.code)).toList();
    if (missing.isEmpty) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Default categories already seeded.')),
        );
      }
      return;
    }
    final batch = _db.batch();
    var sortOrder = existing.docs.length;
    for (final c in missing) {
      batch.set(_db.collection('repair_categories').doc(c.code), {
        'code': c.code,
        'name': c.name,
        'sortOrder': sortOrder++,
        'active': true,
      });
    }
    await batch.commit();
    if (mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Seeded ${missing.length} categories.')),
      );
    }
  }

  Future<void> _addCategory() async {
    final codeController = TextEditingController();
    final nameController = TextEditingController();
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Add Category'),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            TextField(
              controller: codeController,
              maxLength: 3,
              textCapitalization: TextCapitalization.characters,
              inputFormatters: [UpperCaseTextFormatter()],
              decoration: const InputDecoration(labelText: 'Code (3 letters)'),
            ),
            TextField(
              controller: nameController,
              decoration: const InputDecoration(labelText: 'Name'),
            ),
          ],
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('CANCEL'),
          ),
          ElevatedButton(
            onPressed: () => Navigator.pop(dialogContext, true),
            child: const Text('ADD'),
          ),
        ],
      ),
    );
    if (confirmed != true) return;
    final code = codeController.text.trim().toUpperCase();
    final name = nameController.text.trim();
    if (code.length != 3 || name.isEmpty) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Enter a 3-letter code and a name.')),
        );
      }
      return;
    }
    final ref = _db.collection('repair_categories').doc(code);
    final existingDoc = await ref.get();
    if (existingDoc.exists) {
      if (mounted) {
        ScaffoldMessenger.of(context)
            .showSnackBar(SnackBar(content: Text('Code $code already exists.')));
      }
      return;
    }
    final countSnap = await _db.collection('repair_categories').get();
    await ref.set({
      'code': code,
      'name': name,
      'sortOrder': countSnap.docs.length,
      'active': true,
    });
  }

  Future<void> _renameCategory(String code, String currentName) async {
    final nameController = TextEditingController(text: currentName);
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: Text('Rename $code'),
        content: TextField(
          controller: nameController,
          decoration: const InputDecoration(labelText: 'Name'),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('CANCEL'),
          ),
          ElevatedButton(
            onPressed: () => Navigator.pop(dialogContext, true),
            child: const Text('SAVE'),
          ),
        ],
      ),
    );
    if (confirmed != true) return;
    final name = nameController.text.trim();
    if (name.isEmpty) return;
    await _db.collection('repair_categories').doc(code).update({'name': name});
  }

  Future<void> _toggleActive(String code, bool active) async {
    await _db.collection('repair_categories').doc(code).update({'active': !active});
  }

  Future<void> _savePrefix(String prefix) async {
    final trimmed = prefix.trim().toUpperCase();
    if (trimmed.isEmpty) return;
    await _db
        .collection('settings')
        .doc('repair_numbering')
        .set({'companyPrefix': trimmed}, SetOptions(merge: true));
    if (mounted) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Prefix saved.')));
    }
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<bool>(
      future: _accessFuture,
      builder: (context, accessSnap) {
        if (accessSnap.connectionState != ConnectionState.done) {
          return const TruckRepairScaffold(body: LoadingState());
        }
        if (accessSnap.hasError) {
          final err = accessSnap.error;
          final msg = err is FirebaseException ? '${err.code}: ${err.message}' : '$err';
          return TruckRepairScaffold(
            body: ErrorState(
              message: 'Failed to check access: $msg',
              onRetry: () => setState(() => _accessFuture = _loadAccess()),
            ),
          );
        }
        if (accessSnap.data != true) {
          return const TruckRepairScaffold(
            body: EmptyState(
              icon: Icons.lock_outline,
              title: 'NO ACCESS',
              hint: 'ADMIN OR OWNER ONLY',
            ),
          );
        }
        return TruckRepairScaffold(
          appBar: AppBar(
            title: const Text('Repair Categories'),
            backgroundColor: AppColors.navy,
            foregroundColor: Colors.white,
          ),
          body: StreamBuilder<QuerySnapshot>(
            stream: _categoriesStream,
            builder: (context, snapshot) {
              if (snapshot.hasError) {
                final err = snapshot.error;
                final msg = err is FirebaseException
                    ? '${err.code}: ${err.message}'
                    : err is TimeoutException
                        ? 'Could not load categories. Check your connection and try again.'
                        : '$err';
                return ErrorState(
                  message: 'Failed to load categories: $msg',
                  onRetry: () => setState(() => _categoriesStream = _buildCategoriesStream()),
                );
              }
              if (!snapshot.hasData) return const LoadingState();
              final docs = snapshot.data!.docs;
              return Column(
                children: [
                  Padding(
                    padding: const EdgeInsets.all(AppSpacing.md),
                    child: _CompanyPrefixField(db: _db, onSaved: _savePrefix),
                  ),
                  Padding(
                    padding: const EdgeInsets.symmetric(horizontal: AppSpacing.md),
                    child: Row(
                      children: [
                        Expanded(
                          child: OutlinedButton.icon(
                            onPressed: _busy ? null : () => _guarded(_seedDefaults),
                            icon: const Icon(Icons.playlist_add),
                            label: const Text('SEED DEFAULT CATEGORIES'),
                          ),
                        ),
                        const SizedBox(width: AppSpacing.sm),
                        Expanded(
                          child: ElevatedButton.icon(
                            onPressed: _busy ? null : () => _guarded(_addCategory),
                            icon: const Icon(Icons.add),
                            label: const Text('ADD'),
                          ),
                        ),
                      ],
                    ),
                  ),
                  const SizedBox(height: AppSpacing.sm),
                  Expanded(
                    child: docs.isEmpty
                        ? const EmptyState(
                            icon: Icons.category_outlined,
                            title: 'NO CATEGORIES YET',
                            hint: 'SEED THE DEFAULTS OR ADD ONE',
                          )
                        : Padding(
                            padding: const EdgeInsets.all(AppSpacing.md),
                            child: Column(
                              children: [
                                DataTableToolbar(
                                  onExport: (f) => exportDataTable<QueryDocumentSnapshot>(
                                    context,
                                    format: f,
                                    controller: _table,
                                    title: 'Repair Categories',
                                    db: widget.firestoreOverride,
                                    uid: widget.currentUidOverride,
                                  ),
                                ),
                                const SizedBox(height: AppSpacing.sm),
                                Expanded(
                                  child: DataTableView<QueryDocumentSnapshot>(
                              rows: docs,
                              controller: _table,
                              rowKey: (d) => d.id,
                              columns: [
                                DataTableColumn(
                                  label: 'Category',
                                  width: 220,
                                  cellBuilder: (_, d) {
                                    final data = d.data() as Map<String, dynamic>;
                                    return Text(
                                      '${(data['code'] ?? d.id)} — ${data['name'] ?? ''}',
                                      style: const TextStyle(fontWeight: FontWeight.w700),
                                    );
                                  },
                                  compare: (a, b) => a.id.compareTo(b.id),
                                  exportValue: (d) {
                                    final data = d.data() as Map<String, dynamic>;
                                    return '${(data['code'] ?? d.id)} - ${data['name'] ?? ''}';
                                  },
                                ),
                                DataTableColumn(
                                  label: 'Status',
                                  width: 120,
                                  cellBuilder: (_, d) => StatusChip(
                                    status: (d.data() as Map<String, dynamic>)['active'] != false
                                        ? 'active'
                                        : 'inactive',
                                  ),
                                  compare: (a, b) =>
                                      ((a.data() as Map)['active'] != false ? 0 : 1)
                                          .compareTo((b.data() as Map)['active'] != false ? 0 : 1),
                                  exportValue: (d) =>
                                      (d.data() as Map)['active'] != false ? 'Active' : 'Inactive',
                                ),
                                DataTableColumn(
                                  label: 'Order',
                                  width: 80,
                                  numeric: true,
                                  cellBuilder: (_, d) =>
                                      Text('${(d.data() as Map)['sortOrder'] ?? '—'}'),
                                  compare: (a, b) => _compareNullable(
                                      (a.data() as Map)['sortOrder'] as num?,
                                      (b.data() as Map)['sortOrder'] as num?),
                                  exportValue: (d) => '${(d.data() as Map)['sortOrder'] ?? '-'}',
                                ),
                                DataTableColumn(
                                  label: 'Rename',
                                  width: 90,
                                  cellBuilder: (_, d) {
                                    final data = d.data() as Map<String, dynamic>;
                                    return IconButton(
                                      icon: const Icon(Icons.edit_outlined),
                                      tooltip: 'Rename',
                                      onPressed: () => _renameCategory(
                                        (data['code'] ?? d.id).toString(),
                                        (data['name'] ?? '').toString(),
                                      ),
                                    );
                                  },
                                ),
                                DataTableColumn(
                                  label: 'Active',
                                  width: 90,
                                  cellBuilder: (_, d) {
                                    final data = d.data() as Map<String, dynamic>;
                                    final active = data['active'] != false;
                                    return Switch(
                                      value: active,
                                      onChanged: (_) => _toggleActive(
                                        (data['code'] ?? d.id).toString(),
                                        active,
                                      ),
                                    );
                                  },
                                ),
                              ],
                                  ),
                                ),
                              ],
                            ),
                          ),
                  ),
                ],
              );
            },
          ),
        );
      },
    );
  }
}

class _CompanyPrefixField extends StatefulWidget {
  final FirebaseFirestore db;
  final Future<void> Function(String) onSaved;
  const _CompanyPrefixField({required this.db, required this.onSaved});

  @override
  State<_CompanyPrefixField> createState() => _CompanyPrefixFieldState();
}

class _CompanyPrefixFieldState extends State<_CompanyPrefixField> {
  final _controller = TextEditingController();
  late final Future<void> _future = _load();

  // TEMPORARY [REPCAT] debug logging — see RepairCategoriesScreen's doc
  // comment. This read previously had no timeout AND its FutureBuilder
  // never checked snap.hasError, so a failed/denied read here went
  // completely silent (blank prefix field, no error anywhere) — fixed to
  // log and fall back to 'NOD' rather than fail invisibly.
  Future<void> _load() async {
    debugPrint('[REPCAT] settings/repair_numbering: start');
    try {
      final doc = await widget.db
          .collection('settings')
          .doc('repair_numbering')
          .get()
          .timeout(const Duration(seconds: 15));
      final prefix = (doc.data()?['companyPrefix'] ?? 'NOD').toString();
      debugPrint(
        '[REPCAT] settings/repair_numbering: done — exists=${doc.exists} '
        'companyPrefix=$prefix',
      );
      _controller.text = prefix;
    } catch (e) {
      final msg = e is FirebaseException ? '${e.code}: ${e.message}' : e.toString();
      debugPrint('[REPCAT] settings/repair_numbering: ERROR — $msg');
      _controller.text = 'NOD';
    }
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<void>(
      future: _future,
      builder: (context, snap) {
        if (snap.connectionState != ConnectionState.done) {
          return const SizedBox(height: 48, child: LoadingState());
        }
        return Row(
          children: [
            Expanded(
              child: TextField(
                controller: _controller,
                textCapitalization: TextCapitalization.characters,
                inputFormatters: [UpperCaseTextFormatter()],
                decoration: const InputDecoration(labelText: 'Company Prefix'),
              ),
            ),
            const SizedBox(width: AppSpacing.sm),
            ElevatedButton(
              onPressed: () => widget.onSaved(_controller.text),
              child: const Text('SAVE'),
            ),
          ],
        );
      },
    );
  }
}

// ---------------- ADD REPAIR ----------------
// New general entry point for the Vehicle Inspection forms (and any other
// screen that finds a problem on a vehicle) — replaces ReportDefectScreen/
// AddDefectScreen once Step 2 rewires their call sites. Lets the
// driver/inspector log several repairs in one sitting, each with its own
// category/description/severity/photos/voice, then submit them all with
// one button. Writes `repairs` docs with a generated code and status
// REPORTED.
class _AddRepairDraft {
  String? categoryCode;
  String severity = kRepairSeverityNormal;
  final descController = TextEditingController();
  final attachmentsKey = GlobalKey<_InspectionAttachmentsSectionState>();
  void dispose() => descController.dispose();
}

class AddRepairScreen extends StatefulWidget {
  final String userName;
  final String vehicleNumber;
  final String? sourceInspectionId;
  final num? odometerKm;
  // Pre-fills the first draft's category/description — used by
  // DailyChecksScreen's LOW-row "REPORT DEFECT" quick action; still fully
  // editable before submit.
  final String? prefillCategoryCode;
  final String? prefillDescription;
  final FirebaseFirestore? firestoreOverride;
  final String? currentUidOverride;
  const AddRepairScreen({
    super.key,
    required this.userName,
    required this.vehicleNumber,
    this.sourceInspectionId,
    this.odometerKm,
    this.prefillCategoryCode,
    this.prefillDescription,
    this.firestoreOverride,
    this.currentUidOverride,
  });

  @override
  State<AddRepairScreen> createState() => _AddRepairScreenState();
}

class _AddRepairScreenState extends State<AddRepairScreen> {
  FirebaseFirestore get _db => widget.firestoreOverride ?? FirebaseFirestore.instance;
  String? get _uid => widget.currentUidOverride ?? FirebaseAuth.instance.currentUser?.uid;
  late final List<_AddRepairDraft> _drafts = [
    _AddRepairDraft()
      ..categoryCode = widget.prefillCategoryCode
      ..descController.text = widget.prefillDescription ?? '',
  ];
  bool _busy = false;
  late final Future<bool> _permFuture =
      _currentUserHasRepairPerm(kPermReportDefect, db: _db, uidOverride: _uid);
  late final Future<List<Map<String, dynamic>>> _categoriesFuture = _loadCategories();

  Future<List<Map<String, dynamic>>> _loadCategories() async {
    final snap = await _db.collection('repair_categories').orderBy('sortOrder').get();
    return snap.docs.map((d) => d.data()).where((c) => c['active'] != false).toList();
  }

  @override
  void dispose() {
    for (final d in _drafts) {
      d.dispose();
    }
    super.dispose();
  }

  Future<void> _guarded(Future<void> Function() action) async {
    if (_busy) return;
    setState(() => _busy = true);
    try {
      await action();
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  void _addDraft() => setState(() => _drafts.add(_AddRepairDraft()));

  void _removeDraft(int index) => setState(() {
        _drafts[index].dispose();
        _drafts.removeAt(index);
      });

  Future<bool> _confirmDuplicate(String vehicleNumber, String categoryName) async {
    final choice = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Open Repair Already Exists'),
        content: Text(
          'There is already an open repair for $vehicleNumber in "$categoryName". '
          'Add this one anyway, or skip it since it is already covered?',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('LINK (SKIP)'),
          ),
          ElevatedButton(
            onPressed: () => Navigator.pop(dialogContext, true),
            child: const Text('ADD ANYWAY'),
          ),
        ],
      ),
    );
    return choice ?? false;
  }

  Future<void> _submit() async {
    for (final d in _drafts) {
      if (d.categoryCode == null) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Please select a category for every repair.')),
        );
        return;
      }
      if (d.descController.text.trim().isEmpty) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Please describe every repair.')),
        );
        return;
      }
    }
    final count = _drafts.length;
    final confirmed = await showAppConfirmDialog(
      context: context,
      title: 'Submit $count Repair${count > 1 ? 's' : ''}?',
      message: 'This reports $count repair${count > 1 ? 's' : ''} for ${widget.vehicleNumber}.',
      confirmLabel: 'Submit',
    );
    if (!confirmed) return;

    try {
      final uid = _uid ?? '';
      final categories = await _categoriesFuture;
      final prefixDoc = await _db.collection('settings').doc('repair_numbering').get();
      final companyPrefix = (prefixDoc.data()?['companyPrefix'] ?? 'NOD').toString();
      final existingSnap = await _db
          .collection('repairs')
          .where('vehicleNumber', isEqualTo: widget.vehicleNumber)
          .get();
      final existingRepairs = existingSnap.docs.map((d) => d.data()).toList();

      var createdCount = 0;
      for (final d in _drafts) {
        final categoryCode = d.categoryCode!;
        final categoryName = categories
            .firstWhere(
              (c) => c['code'] == categoryCode,
              orElse: () => {'name': categoryCode},
            )['name']
            .toString();
        if (hasOpenDuplicateRepair(
          existingRepairs: existingRepairs,
          vehicleNumber: widget.vehicleNumber,
          categoryCode: categoryCode,
        )) {
          final addAnyway = await _confirmDuplicate(widget.vehicleNumber, categoryName);
          if (!addAnyway) continue;
        }
        final docRef = _db.collection('repairs').doc();
        final code = await nextRepairCode(
          db: _db,
          companyPrefix: companyPrefix,
          categoryCode: categoryCode,
        );
        final attachments = await d.attachmentsKey.currentState!.uploadAndFinalize(
          'repairs/items/${docRef.id}',
        );
        await docRef.set({
          'code': code,
          'vehicleNumber': widget.vehicleNumber,
          'categoryCode': categoryCode,
          'categoryName': categoryName,
          'inspectionId': widget.sourceInspectionId,
          'description': d.descController.text.trim(),
          'severity': d.severity,
          'photos': attachments.photos,
          'voices': attachments.voices,
          'odometerKm': widget.odometerKm,
          'reportedBy': uid,
          'reportedByName': widget.userName,
          'reportedAt': FieldValue.serverTimestamp(),
          'status': RepairItemStatus.reported,
          'listId': null,
          'technicalNote': null,
          'garageName': null,
          'garageContact': null,
          'costCents': null,
          'partsUsed': const <Map<String, dynamic>>[],
          'afterPhotos': const <Map<String, dynamic>>[],
          'afterVoices': const <Map<String, dynamic>>[],
          'returnReason': null,
          'rejectReason': null,
          'createdAt': FieldValue.serverTimestamp(),
          'updatedAt': FieldValue.serverTimestamp(),
        });
        await _writeRepairEvent(
          collection: 'repairs',
          docId: docRef.id,
          action: 'CREATED',
          summary: 'Repair reported ($code)',
          actorUid: uid,
          actorName: widget.userName,
        );
        existingRepairs.add({
          'vehicleNumber': widget.vehicleNumber,
          'categoryCode': categoryCode,
          'status': RepairItemStatus.reported,
        });
        createdCount++;
      }

      if (!mounted) return;
      if (createdCount == 0) {
        Navigator.pop(context);
        return;
      }
      final addAnother = await showDialog<bool>(
        context: context,
        builder: (dialogContext) => AlertDialog(
          title: const Text('Repairs Reported'),
          content: Text(
            '$createdCount repair${createdCount > 1 ? 's' : ''} reported and sent to '
            'management for review.',
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dialogContext, true),
              child: const Text('ADD ANOTHER REPAIR'),
            ),
            ElevatedButton(
              onPressed: () => Navigator.pop(dialogContext, false),
              child: const Text('OK'),
            ),
          ],
        ),
      );
      if (!mounted) return;
      if (addAnother == true) {
        setState(() {
          for (final d in _drafts) {
            d.dispose();
          }
          _drafts.clear();
          _drafts.add(_AddRepairDraft());
        });
        return;
      }
      Navigator.pop(context);
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Failed to submit repairs: $e')),
        );
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<bool>(
      future: _permFuture,
      builder: (context, permSnap) {
        if (permSnap.connectionState != ConnectionState.done) {
          return const TruckRepairScaffold(body: LoadingState());
        }
        if (permSnap.data != true) {
          return const TruckRepairScaffold(
            body: EmptyState(
              icon: Icons.lock_outline,
              title: 'NO ACCESS',
              hint: 'ASK THE ADMIN TO GRANT THIS TRUCK REPAIR PERMISSION',
            ),
          );
        }
        return FutureBuilder<List<Map<String, dynamic>>>(
          future: _categoriesFuture,
          builder: (context, catSnap) {
            if (catSnap.connectionState != ConnectionState.done) {
              return const TruckRepairScaffold(body: LoadingState());
            }
            if (catSnap.hasError) {
              return TruckRepairScaffold(
                body: ErrorState(
                  message: 'Failed to load categories: ${catSnap.error}',
                  onRetry: () => setState(() {}),
                ),
              );
            }
            final categories = catSnap.data ?? const [];
            if (categories.isEmpty) {
              return const TruckRepairScaffold(
                body: EmptyState(
