class NewRepairsInboxScreen extends StatefulWidget {
  final FirebaseFirestore? firestoreOverride;
  final String? currentUidOverride;
  const NewRepairsInboxScreen({super.key, this.firestoreOverride, this.currentUidOverride});

  @override
  State<NewRepairsInboxScreen> createState() => _NewRepairsInboxScreenState();
}

class _NewRepairsInboxScreenState extends State<NewRepairsInboxScreen> {
  FirebaseFirestore get _db => widget.firestoreOverride ?? FirebaseFirestore.instance;
  String? get _uid => widget.currentUidOverride ?? FirebaseAuth.instance.currentUser?.uid;
  late final Future<bool> _permFuture =
      _currentUserHasRepairPerm(kPermApprove, db: _db, uidOverride: _uid);
  late final Stream<QuerySnapshot> _stream = timeoutFirstEventOnly(
    _db
        .collection('repairs')
        .where('status', isEqualTo: RepairItemStatus.reported)
        .orderBy('reportedAt', descending: true)
        .snapshots(),
    const Duration(seconds: 15),
    onTimeout: () => TimeoutException('Taking too long to load repairs.'),
  );

  final _searchController = TextEditingController();
  String _search = '';

  final _table = DataTableController<RepairRow>();
  late final UserDirectory _users = UserDirectory.of(db: widget.firestoreOverride);

  void _onUsersChanged() {
    if (mounted) setState(() {});
  }

  String _nameOf(String? uid, String? storedName) => _users.nameOf(uid, storedName: storedName);

  void _exportRepairs(String format, String title, List<String> filters) {
    exportDataTable<RepairRow>(
      context,
      format: format,
      controller: _table,
      title: title,
      filters: filters,
      db: widget.firestoreOverride,
      uid: widget.currentUidOverride,
    );
  }

  @override
  void initState() {
    super.initState();
    _users.version.addListener(_onUsersChanged);
  }

  @override
  void dispose() {
    _users.version.removeListener(_onUsersChanged);
    _searchController.dispose();
    super.dispose();
  }

  void _openVehicle(String v) => pushWebAware(
        context,
        NewRepairsVehicleScreen(
          vehicleNumber: v,
          firestoreOverride: widget.firestoreOverride,
          currentUidOverride: widget.currentUidOverride,
        ),
      );

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<bool>(
      future: _permFuture,
      builder: (context, permSnap) {
        if (permSnap.connectionState != ConnectionState.done) {
          return const TruckRepairScaffold(body: LoadingState());
        }
        if (permSnap.data != true) {
          return const TruckRepairScaffold(
            body: EmptyState(
              icon: Icons.lock_outline,
              title: 'NO ACCESS',
              hint: 'ASK THE ADMIN TO GRANT THIS TRUCK REPAIR PERMISSION',
            ),
          );
        }
        return TruckRepairScaffold(
          appBar: AppBar(
            title: const Text('New Repairs'),
            backgroundColor: AppColors.navy,
            foregroundColor: Colors.white,
          ),
          body: StreamBuilder<QuerySnapshot>(
            stream: _stream,
            builder: (context, snapshot) {
              if (snapshot.hasError) {
                return ErrorState(
                  message: snapshot.error is TimeoutException
                      ? 'Taking too long — RETRY'
                      : 'Failed to load repairs: ${snapshot.error}',
                  onRetry: () => setState(() {}),
                );
              }
              if (!snapshot.hasData) return const LoadingState();
              final docs = snapshot.data!.docs;
              if (docs.isEmpty) {
                return const EmptyState(
                  icon: Icons.inbox_outlined,
                  title: 'NO NEW REPAIRS',
                  hint: 'EVERYTHING REPORTED HAS BEEN ADDED TO A LIST',
                );
              }
              final all = docs.map(RepairRow.fromDoc).toList();
              // How many NEW repairs each vehicle has waiting — the batch
              // REVIEW opens (same per-vehicle grouping the old cards showed).
              final perVehicle = <String, int>{};
              for (final r in all) {
                perVehicle[r.vehicleNumber] = (perVehicle[r.vehicleNumber] ?? 0) + 1;
              }
              final rows = filterRepairRows(all, search: _search);
              return Padding(
                padding: const EdgeInsets.all(AppSpacing.md),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    DataTableToolbar(
                      searchController: _searchController,
                      searchHint: 'Search repair code or vehicle number',
                      onSearchChanged: (v) => setState(() => _search = v),
                      onExport: (f) => _exportRepairs(
                        f,
                        'New Repairs',
                        describeTableFilters(search: _search, extra: {'Status': 'REPORTED'}),
                      ),
                    ),
                    const SizedBox(height: AppSpacing.sm),
                    Expanded(
                      child: RepairsTable(
                        rows: rows,
                        resetPageKey: _search,
                        controller: _table,
                        nameOf: _nameOf,
                        columns: const [
                          RepairCol.code,
                          RepairCol.reportedDate,
                          RepairCol.vehicle,
                          RepairCol.category,
                          RepairCol.description,
                          RepairCol.severity,
                          RepairCol.reportedBy,
                          RepairCol.status,
                        ],
                        extraColumns: [
                          DataTableColumn<RepairRow>(
                            label: 'Vehicle queue',
                            width: 120,
                            cellBuilder: (_, r) => DataTableStatusChip(
                              label: '${perVehicle[r.vehicleNumber] ?? 0} NEW',
                              color: AppColors.danger,
                            ),
                            compare: (a, b) => (perVehicle[a.vehicleNumber] ?? 0)
                                .compareTo(perVehicle[b.vehicleNumber] ?? 0),
                            exportValue: (r) => '${perVehicle[r.vehicleNumber] ?? 0} NEW',
                          ),
                        ],
                        actionWidth: 120,
                        actionBuilder: (_, r) => OutlinedButton(
                          style: _kTableButtonStyle,
                          onPressed: () => _openVehicle(r.vehicleNumber),
                          child: const Text('REVIEW'),
                        ),
                        onRowTap: (r) => _openVehicle(r.vehicleNumber),
                        emptyState: const EmptyState(
                          icon: Icons.search_off,
                          title: 'NO REPAIRS MATCH THIS SEARCH',
                        ),
                      ),
                    ),
                  ],
                ),
              );
            },
          ),
        );
      },
    );
  }
}

class NewRepairsVehicleScreen extends StatefulWidget {
  final String vehicleNumber;
  final FirebaseFirestore? firestoreOverride;
  final String? currentUidOverride;
  const NewRepairsVehicleScreen({
    super.key,
    required this.vehicleNumber,
    this.firestoreOverride,
    this.currentUidOverride,
  });

  @override
  State<NewRepairsVehicleScreen> createState() => _NewRepairsVehicleScreenState();
}

class _NewRepairsVehicleScreenState extends State<NewRepairsVehicleScreen> {
  FirebaseFirestore get _db => widget.firestoreOverride ?? FirebaseFirestore.instance;
  String? get _uid => widget.currentUidOverride ?? FirebaseAuth.instance.currentUser?.uid;
  final Set<String> _selected = {};
  bool _busy = false;
  late final Stream<QuerySnapshot> _stream = timeoutFirstEventOnly(
    _db
        .collection('repairs')
        .where('vehicleNumber', isEqualTo: widget.vehicleNumber)
        .where('status', isEqualTo: RepairItemStatus.reported)
        .orderBy('reportedAt', descending: true)
        .snapshots(),
    const Duration(seconds: 15),
    onTimeout: () => TimeoutException('Taking too long to load repairs.'),
  );

  Future<void> _guarded(Future<void> Function() action) async {
    if (_busy) return;
    setState(() => _busy = true);
    try {
      await action();
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  Future<void> _reject(String repairId, String code) async {
    final reasonController = TextEditingController();
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: Text('Reject $code'),
        content: TextField(
          controller: reasonController,
          maxLines: 3,
          decoration: const InputDecoration(labelText: 'Reason (required)'),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('CANCEL'),
          ),
          ElevatedButton(
            onPressed: () => Navigator.pop(dialogContext, true),
            child: const Text('REJECT'),
          ),
        ],
      ),
    );
    if (confirmed != true) return;
    final reason = reasonController.text.trim();
    if (reason.isEmpty) {
      if (mounted) {
        ScaffoldMessenger.of(context)
            .showSnackBar(const SnackBar(content: Text('A reason is required to reject.')));
      }
      return;
    }
    await _guarded(() async {
      final uid = _uid ?? '';
      await _db.collection('repairs').doc(repairId).update({
        'status': RepairItemStatus.rejected,
        'rejectReason': reason,
        'rejectedBy': uid,
        'updatedAt': FieldValue.serverTimestamp(),
      });
      await _writeRepairEvent(
        collection: 'repairs',
        docId: repairId,
        action: 'REJECTED',
        summary: 'Rejected: $reason',
        actorUid: uid,
        actorName: FirebaseAuth.instance.currentUser?.displayName ?? 'Management',
      );
      _selected.remove(repairId);
    });
  }

  Future<void> _submitList() async {
    if (_selected.isEmpty) return;
    final count = _selected.length;
    final confirmed = await showAppConfirmDialog(
      context: context,
      title: 'Submit Final Repair List?',
      message: 'This sends $count repair(s) for ${widget.vehicleNumber} to the technical team.',
      confirmLabel: 'Submit',
    );
    if (!confirmed) return;
    await _guarded(() async {
      final uid = _uid ?? '';
      final listRef = _db.collection('repair_lists').doc();
      final itemIds = _selected.toList();
      final batch = _db.batch();
      batch.set(listRef, {
        'vehicleNumber': widget.vehicleNumber,
        'itemIds': itemIds,
        'status': RepairListStatus.submitted,
        'createdBy': uid,
        'submittedAt': FieldValue.serverTimestamp(),
        'doneCount': 0,
        'updatedAt': FieldValue.serverTimestamp(),
      });
      for (final id in itemIds) {
        batch.update(_db.collection('repairs').doc(id), {
          'status': RepairItemStatus.listed,
          'listId': listRef.id,
          'updatedAt': FieldValue.serverTimestamp(),
        });
      }
      await batch.commit();
      for (final id in itemIds) {
        await _writeRepairEvent(
          collection: 'repairs',
          docId: id,
          action: 'LISTED',
          summary: 'Added to final repair list and submitted to the technical team',
          actorUid: uid,
          actorName: FirebaseAuth.instance.currentUser?.displayName ?? 'Management',
        );
      }
      _selected.clear();
      if (mounted) {
        ScaffoldMessenger.of(context)
            .showSnackBar(SnackBar(content: Text('$count repair(s) submitted.')));
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    return TruckRepairScaffold(
      appBar: AppBar(
        title: Text(widget.vehicleNumber),
        backgroundColor: AppColors.navy,
        foregroundColor: Colors.white,
      ),
      body: StreamBuilder<QuerySnapshot>(
        stream: _stream,
        builder: (context, snapshot) {
          if (snapshot.hasError) {
            return ErrorState(
              message: snapshot.error is TimeoutException
                  ? 'Taking too long — RETRY'
                  : 'Failed to load repairs: ${snapshot.error}',
              onRetry: () => setState(() {}),
            );
          }
          if (!snapshot.hasData) return const LoadingState();
          final docs = snapshot.data!.docs;
          if (docs.isEmpty) {
            return const EmptyState(
              icon: Icons.inbox_outlined,
              title: 'NO NEW REPAIRS FOR THIS VEHICLE',
            );
          }
          return Column(
            children: [
              Expanded(
                child: ListView.builder(
                  padding: const EdgeInsets.all(AppSpacing.md),
                  itemCount: docs.length,
                  itemBuilder: (context, index) {
                    final doc = docs[index];
                    final data = doc.data() as Map<String, dynamic>;
                    final selected = _selected.contains(doc.id);
                    return AppStaggeredFadeIn(
                      index: index,
                      child: Padding(
                        padding: const EdgeInsets.only(bottom: AppSpacing.sm),
                        child: AppCard(
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Row(
                                children: [
                                  Expanded(
                                    child: Text(
                                      '${data['code'] ?? ''} — ${data['categoryName'] ?? ''}',
                                      style: AppText.section,
                                      softWrap: true,
                                    ),
                                  ),
                                  const SizedBox(width: AppSpacing.sm),
                                  Flexible(
                                    child: StatusChip(
                                      status: (data['severity'] ?? 'NORMAL').toString(),
                                    ),
                                  ),
                                ],
                              ),
                              const SizedBox(height: 4),
                              Text(
                                (data['description'] ?? '').toString(),
                                style: AppText.body,
                                softWrap: true,
                              ),
                              const SizedBox(height: AppSpacing.sm),
                              Row(
                                children: [
                                  Expanded(
                                    child: OutlinedButton.icon(
                                      onPressed: _busy
                                          ? null
                                          : () => _reject(
                                                doc.id,
                                                (data['code'] ?? '').toString(),
                                              ),
                                      icon: const Icon(Icons.close),
                                      label: const Text('REJECT'),
                                    ),
                                  ),
                                  const SizedBox(width: 8),
                                  Expanded(
                                    child: selected
                                        ? OutlinedButton.icon(
                                            onPressed: () =>
                                                setState(() => _selected.remove(doc.id)),
                                            icon: const Icon(
                                              Icons.check_circle,
                                              color: AppColors.success,
                                            ),
                                            label: const Text('ADDED'),
                                          )
                                        : ElevatedButton.icon(
                                            onPressed: () =>
                                                setState(() => _selected.add(doc.id)),
                                            icon: const Icon(Icons.add),
                                            label: const Text('ADD'),
                                          ),
                                  ),
                                ],
                              ),
                            ],
                          ),
                        ),
                      ),
                    );
                  },
                ),
              ),
              if (_selected.isNotEmpty)
                Container(
                  padding: const EdgeInsets.all(AppSpacing.md),
                  decoration: BoxDecoration(
                    color: AppColors.card,
                    border: Border(top: BorderSide(color: AppColors.border)),
                  ),
                  child: Row(
                    children: [
                      Expanded(
                        child: Text(
                          'FINAL REPAIR LIST (${_selected.length})',
                          style: AppText.section,
                        ),
                      ),
                      ElevatedButton(
                        onPressed: _busy ? null : _submitList,
                        child: _busy
                            ? const SizedBox(
                                width: 20,
                                height: 20,
                                child:
                                    CircularProgressIndicator(strokeWidth: 2, color: Colors.white),
                              )
                            : const Text('SUBMIT'),
                      ),
                    ],
                  ),
                ),
            ],
          );
        },
      ),
    );
  }
}

// ---------------- REPAIRS TO DO (technical) ----------------
class _RepairPartDraft {
  final nameController = TextEditingController();
  final qtyController = TextEditingController(text: '1');
  final priceController = TextEditingController();
  final whereController = TextEditingController();

  void dispose() {
    nameController.dispose();
    qtyController.dispose();
    priceController.dispose();
    whereController.dispose();
  }

  Map<String, dynamic> toMap() => {
        'name': nameController.text.trim(),
        'qty': num.tryParse(qtyController.text.trim()) ?? 1,
        'priceCents': ((double.tryParse(priceController.text.trim()) ?? 0) * 100).round(),
        'whereBought': whereController.text.trim(),
      };
}

// Recomputes a repair_lists doc's status/doneCount from its member
// repairs' current statuses — shared by the technical MARK DONE flow and
// the management RETURN flow so the two never drift from the same
// calculation (computeRepairListProgress).
Future<void> recomputeRepairListProgress(FirebaseFirestore db, String? listId) async {
  if (listId == null) return;
  final listRef = db.collection('repair_lists').doc(listId);
  final listDoc = await listRef.get();
  final itemIds =
      ((listDoc.data()?['itemIds'] as List?) ?? const []).map((e) => e.toString()).toList();
  if (itemIds.isEmpty) return;
  // One whereIn batch per chunk of 30 ids instead of one
  // .collection('repairs').doc(id).get() PER item (N+1) —
  // computeRepairListProgress only counts statuses, so result order
  // doesn't matter; a deleted/missing repair doc still contributes an
  // empty-string status (same as the old d.data()?['status'] ?? '' on a
  // non-existent doc), so a list's doneCount/allDone math is unchanged.
  final statuses = <String>[];
  for (var i = 0; i < itemIds.length; i += 30) {
    final chunk = itemIds.sublist(i, min(i + 30, itemIds.length));
    final snap = await db
        .collection('repairs')
        .where(FieldPath.documentId, whereIn: chunk)
        .get();
    final statusById = {
      for (final d in snap.docs) d.id: (d.data()['status'] ?? '').toString(),
    };
    for (final id in chunk) {
      statuses.add(statusById[id] ?? '');
    }
  }
  final progress = computeRepairListProgress(statuses);
  await listRef.update({
    'status': progress.status,
    'doneCount': progress.doneCount,
    'updatedAt': FieldValue.serverTimestamp(),
  });
}

// ---------------- REPAIR TABLE (shared by the v2 repair list screens) ----------------
// One repairs/{id} doc as a table row. Wraps the already-streamed doc data
// — building one never reads Firestore.
class RepairRow {
  final String id;
  final Map<String, dynamic> data;
  const RepairRow(this.id, this.data);

  factory RepairRow.fromDoc(QueryDocumentSnapshot doc) =>
      RepairRow(doc.id, doc.data() as Map<String, dynamic>);

  String _s(String f) => (data[f] ?? '').toString();
  static DateTime? _ts(Object? v) =>
      v is Timestamp ? v.toDate() : (v is DateTime ? v : null);

  String get code => _s('code');
  String get vehicleNumber => _s('vehicleNumber');
  String get categoryCode => _s('categoryCode');
  String get categoryName => _s('categoryName');
  String get description => _s('description');
  String get severity => _s('severity');
  String get reportedByName => _s('reportedByName');
  // uids only — repairs docs store no name for these; resolved through the
  // shared UserDirectory ("-" when unavailable).
  String? get reportedByUid => data['reportedBy'] as String?;
  String? get startedByUid => data['startedBy'] as String?;
  String? get doneByUid => data['doneBy'] as String?;
  String? get completedByUid => data['completedBy'] as String?;
  String get status => _s('status');
  String get returnReason => _s('returnReason');
  String get rejectReason => _s('rejectReason');
  String get technicalNote => _s('technicalNote');
  String get garageName => _s('garageName');
  String get garageContact => _s('garageContact');
  String? get listId => data['listId'] as String?;
  DateTime? get reportedAt => _ts(data['reportedAt']);
  DateTime? get doneAt => _ts(data['doneAt']);
  DateTime? get completedAt => _ts(data['completedAt']);
  int? get costCents => (data['costCents'] as num?)?.toInt();
  List get partsUsed => (data['partsUsed'] as List?) ?? const [];
  List get afterPhotos => (data['afterPhotos'] as List?) ?? const [];
}

// Filter-chip buckets over the real RepairItemStatus values:
//   PENDING           = REPORTED, LISTED (not started yet)
//   IN PROGRESS       = IN_PROGRESS, RETURNED (being worked / reworked)
//   AWAITING APPROVAL = DONE_PENDING_APPROVAL (technical done, management to decide)
//   COMPLETED         = COMPLETED (approved by management)
//   REJECTED          = REJECTED
class RepairFilter {
  static const all = 'ALL';
  static const pending = 'PENDING';
  static const inProgress = 'IN_PROGRESS';
  static const awaitingApproval = 'AWAITING_APPROVAL';
  static const completed = 'COMPLETED';
  static const rejected = 'REJECTED';
}

String repairFilterBucket(String status) {
  switch (status) {
    case RepairItemStatus.reported:
    case RepairItemStatus.listed:
      return RepairFilter.pending;
    case RepairItemStatus.inProgress:
    case RepairItemStatus.returned:
      return RepairFilter.inProgress;
    case RepairItemStatus.donePendingApproval:
      return RepairFilter.awaitingApproval;
    case RepairItemStatus.completed:
      return RepairFilter.completed;
    case RepairItemStatus.rejected:
      return RepairFilter.rejected;
    default:
      return RepairFilter.pending;
  }
}

// Awaiting approval first, then pending, then in progress, then done.
const Map<String, int> _kRepairBucketRank = {
  RepairFilter.awaitingApproval: 0,
  RepairFilter.pending: 1,
  RepairFilter.inProgress: 2,
  RepairFilter.completed: 3,
  RepairFilter.rejected: 4,
};

// Newest reportedAt first; missing dates last; then code for stability.
int compareRepairRowsNewestFirst(RepairRow a, RepairRow b) {
  final at = a.reportedAt, bt = b.reportedAt;
  if (at != null && bt != null) {
    final c = bt.compareTo(at);
    if (c != 0) return c;
  } else if (at != null) {
    return -1;
  } else if (bt != null) {
    return 1;
  }
  return a.code.compareTo(b.code);
}

// Default repair order: status group (see _kRepairBucketRank), newest
// first inside each group.
int compareRepairRowsByStatus(RepairRow a, RepairRow b) {
  final r = (_kRepairBucketRank[repairFilterBucket(a.status)] ?? 9)
      .compareTo(_kRepairBucketRank[repairFilterBucket(b.status)] ?? 9);
  if (r != 0) return r;
  return compareRepairRowsNewestFirst(a, b);
}

// Client-side only — search matches repair code OR vehicle number.
List<RepairRow> filterRepairRows(
  List<RepairRow> rows, {
  String bucket = RepairFilter.all,
  String search = '',
}) {
  final q = search.trim().toUpperCase();
  return rows.where((r) {
    if (bucket != RepairFilter.all && repairFilterBucket(r.status) != bucket) return false;
    if (q.isNotEmpty &&
        !r.code.toUpperCase().contains(q) &&
        !r.vehicleNumber.toUpperCase().contains(q)) {
      return false;
    }
    return true;
  }).toList();
}

String repairStatusLabel(String status) {
  switch (status) {
    case RepairItemStatus.reported:
      return 'REPORTED';
    case RepairItemStatus.listed:
      return 'LISTED';
    case RepairItemStatus.inProgress:
      return 'IN PROGRESS';
    case RepairItemStatus.donePendingApproval:
      return 'AWAITING APPROVAL';
    case RepairItemStatus.completed:
      return 'COMPLETED';
    case RepairItemStatus.returned:
      return 'RETURNED';
    case RepairItemStatus.rejected:
      return 'REJECTED';
    default:
      return status.isEmpty ? '—' : status;
  }
}

Color repairStatusColor(String status) {
  switch (status) {
    case RepairItemStatus.reported:
    case RepairItemStatus.returned:
      return AppColors.danger;
    case RepairItemStatus.donePendingApproval:
      return AppColors.warning;
    case RepairItemStatus.listed:
    case RepairItemStatus.inProgress:
      return AppColors.info;
    case RepairItemStatus.completed:
      return AppColors.success;
    default:
      return AppColors.textMuted;
  }
}

// Filter chips with live counts for whichever buckets a screen can have.
List<DataTableFilterOption> repairFilterOptions(
  List<RepairRow> searched, {
  List<String> buckets = const [
    RepairFilter.pending,
    RepairFilter.inProgress,
    RepairFilter.awaitingApproval,
    RepairFilter.completed,
    RepairFilter.rejected,
  ],
}) {
  int count(String b) => searched.where((r) => repairFilterBucket(r.status) == b).length;
  const labels = {
    RepairFilter.pending: 'PENDING',
    RepairFilter.inProgress: 'IN PROGRESS',
    RepairFilter.awaitingApproval: 'AWAITING APPROVAL',
    RepairFilter.completed: 'COMPLETED',
    RepairFilter.rejected: 'REJECTED',
  };
  const colors = {
    RepairFilter.pending: AppColors.danger,
    RepairFilter.inProgress: AppColors.info,
    RepairFilter.awaitingApproval: AppColors.warning,
    RepairFilter.completed: AppColors.success,
    RepairFilter.rejected: AppColors.textMuted,
  };
  return [
    DataTableFilterOption(value: RepairFilter.all, label: 'ALL', count: searched.length),
    for (final b in buckets)
      DataTableFilterOption(value: b, label: labels[b]!, count: count(b), color: colors[b]),
  ];
}

enum RepairCol {
  code,
  vehicle,
  category,
  description,
  severity,
  reportedBy,
  reportedDate,
  status,
  doneDate,
  technicalNote,
  garage,
  cost,
  approvedDate,
  workedBy,
  approvedBy,
}

// The one repair table every v2 list screen uses — each screen just picks
// which columns it needs. First column is pinned on narrow screens.
class RepairsTable extends StatelessWidget {
  final List<RepairRow> rows;
  final List<RepairCol> columns;
  // Inserted after `columns`, before Actions (screen-specific extras).
  final List<DataTableColumn<RepairRow>> extraColumns;
  final Widget Function(BuildContext context, RepairRow row)? actionBuilder;
  final double actionWidth;
  final void Function(RepairRow row)? onRowTap;
  final Widget? emptyState;
  final Object? resetPageKey;
  // Column whose comparator is the default sort; null keeps row order.
  final RepairCol? initialSort;
  final bool initialSortAscending;
  final int pageSize;
  final DataTableController<RepairRow>? controller;
  // uid -> display name (UserDirectory). Default: stored names only.
  final PersonNameResolver nameOf;

  const RepairsTable({
    super.key,
    required this.rows,
    required this.columns,
    this.extraColumns = const [],
    this.actionBuilder,
    this.actionWidth = 140,
    this.onRowTap,
    this.emptyState,
    this.resetPageKey,
    this.initialSort = RepairCol.status,
    this.initialSortAscending = true,
    this.pageSize = 25,
    this.controller,
    this.nameOf = _noDirectoryName,
  });

  static String _ts(Object? v) => formatTableDate(v is Timestamp ? v.toDate() : null);
  static String _dash(String s) => s.isEmpty ? '-' : s;
  static String _costText(RepairRow r) =>
      r.costCents == null ? '-' : _formatMoney(_centsToMoney(r.costCents!));

  String reportedBy(RepairRow r) => nameOf(r.reportedByUid, r.reportedByName);
  // MARK DONE's doneBy, else START's startedBy (still in progress).
  String workedBy(RepairRow r) => nameOf(r.doneByUid ?? r.startedByUid, null);
  // Only COMPLETED repairs were approved (completedBy is set on approve).
  String approvedBy(RepairRow r) =>
      r.status == RepairItemStatus.completed ? nameOf(r.completedByUid, null) : '-';

  static Text _muted(String s) => Text(
        s,
        style: const TextStyle(color: AppColors.textMuted),
      );

  static Widget _textOrDash(String s) => s.isEmpty ? _muted('—') : Text(s);

  DataTableColumn<RepairRow> _col(RepairCol c) {
    switch (c) {
      case RepairCol.code:
        return DataTableColumn(
          label: 'Repair code',
          width: 150,
          cellBuilder: (_, r) =>
              Text(r.code.isEmpty ? '—' : r.code, style: const TextStyle(fontWeight: FontWeight.w700)),
          compare: (a, b) => a.code.compareTo(b.code),
          exportValue: (r) => _dash(r.code),
        );
      case RepairCol.vehicle:
        return DataTableColumn(
          label: 'Vehicle',
          width: 110,
          cellBuilder: (_, r) => Text(r.vehicleNumber),
          compare: (a, b) => a.vehicleNumber.compareTo(b.vehicleNumber),
          exportValue: (r) => _dash(r.vehicleNumber),
        );
      case RepairCol.category:
        return DataTableColumn(
          label: 'Category',
          width: 150,
          cellBuilder: (_, r) => _textOrDash(r.categoryName.isEmpty ? r.categoryCode : r.categoryName),
          compare: (a, b) => a.categoryName.compareTo(b.categoryName),
          exportValue: (r) => _dash(r.categoryName.isEmpty ? r.categoryCode : r.categoryName),
        );
      case RepairCol.description:
        return DataTableColumn(
          label: 'Description',
          width: 250,
          cellBuilder: (_, r) => Tooltip(message: r.description, child: _textOrDash(r.description)),
          exportValue: (r) => _dash(r.description),
        );
      case RepairCol.severity:
        return DataTableColumn(
          label: 'Severity',
          width: 105,
          cellBuilder: (_, r) => r.severity == kRepairSeverityUrgent
              ? const DataTableStatusChip(label: 'URGENT', color: AppColors.danger)
              : _textOrDash(r.severity),
          compare: (a, b) => (a.severity == kRepairSeverityUrgent ? 0 : 1)
              .compareTo(b.severity == kRepairSeverityUrgent ? 0 : 1),
          exportValue: (r) => _dash(r.severity),
        );
      case RepairCol.reportedBy:
        return DataTableColumn(
          label: 'Reported by',
          width: 140,
          cellBuilder: (_, r) => Text(reportedBy(r)),
          compare: (a, b) => reportedBy(a).compareTo(reportedBy(b)),
          exportValue: reportedBy,
        );
      case RepairCol.reportedDate:
        return DataTableColumn(
          label: 'Date',
          width: 115,
          isDate: true,
          cellBuilder: (_, r) => Tooltip(
            message: 'Reported ${_repairFormatDateTime(r.data['reportedAt'])}',
            child: Text(_ts(r.data['reportedAt'])),
          ),
          compare: (a, b) => -compareRepairRowsNewestFirst(a, b),
          exportValue: (r) => _ts(r.data['reportedAt']),
        );
      case RepairCol.status:
        return DataTableColumn(
          label: 'Status',
          width: 180,
          cellBuilder: (_, r) {
            final reason = r.status == RepairItemStatus.returned
                ? r.returnReason
                : r.status == RepairItemStatus.rejected
                    ? r.rejectReason
                    : '';
            return Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                DataTableStatusChip(
                  label: repairStatusLabel(r.status),
                  color: repairStatusColor(r.status),
                ),
                if (reason.isNotEmpty)
                  Padding(
                    padding: const EdgeInsets.only(top: 2),
                    child: Tooltip(
                      message: reason,
                      child: Text(
                        reason,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                          color: AppColors.danger,
                          fontSize: 11,
                          fontWeight: FontWeight.w600,
                        ),
                      ),
                    ),
                  ),
              ],
            );
          },
          compare: compareRepairRowsByStatus,
          exportValue: (r) {
            final reason = r.status == RepairItemStatus.returned
                ? r.returnReason
                : r.status == RepairItemStatus.rejected
                    ? r.rejectReason
                    : '';
            return reason.isEmpty
                ? repairStatusLabel(r.status)
                : '${repairStatusLabel(r.status)}: $reason';
          },
        );
      case RepairCol.doneDate:
        return DataTableColumn(
          label: 'Done',
          width: 115,
          cellBuilder: (_, r) => Text(_ts(r.data['doneAt'])),
          compare: (a, b) => _compareNullable(a.doneAt, b.doneAt),
          exportValue: (r) => _ts(r.data['doneAt']),
        );
      case RepairCol.technicalNote:
        return DataTableColumn(
          label: 'Technical note',
          width: 220,
          cellBuilder: (_, r) =>
              Tooltip(message: r.technicalNote, child: _textOrDash(r.technicalNote)),
          exportValue: (r) => _dash(r.technicalNote),
        );
      case RepairCol.garage:
        return DataTableColumn(
          label: 'Garage',
          width: 160,
          cellBuilder: (_, r) => _textOrDash(r.garageName),
          compare: (a, b) => a.garageName.compareTo(b.garageName),
          exportValue: (r) => _dash(r.garageName),
        );
      case RepairCol.cost:
        return DataTableColumn(
          label: 'Cost',
          width: 115,
          numeric: true,
          cellBuilder: (_, r) => r.costCents == null
              ? _muted('—')
              : Text(_formatMoney(_centsToMoney(r.costCents!))),
          compare: (a, b) => _compareNullable(a.costCents, b.costCents),
          exportValue: _costText,
        );
      case RepairCol.approvedDate:
        // WHEN it was approved; WHO is RepairCol.approvedBy (uid resolved
        // through the shared UserDirectory).
        return DataTableColumn(
          label: 'Approved on',
          width: 115,
          cellBuilder: (_, r) => Text(_ts(r.data['completedAt'])),
          compare: (a, b) => _compareNullable(a.completedAt, b.completedAt),
          exportValue: (r) => _ts(r.data['completedAt']),
        );
      case RepairCol.workedBy:
        return DataTableColumn(
          label: 'Worked by',
          width: 140,
          cellBuilder: (_, r) => Text(workedBy(r)),
          compare: (a, b) => workedBy(a).compareTo(workedBy(b)),
          exportValue: workedBy,
        );
      case RepairCol.approvedBy:
        return DataTableColumn(
          label: 'Approved by',
          width: 140,
          cellBuilder: (_, r) => Text(approvedBy(r)),
          compare: (a, b) => approvedBy(a).compareTo(approvedBy(b)),
          exportValue: approvedBy,
        );
    }
  }

  @override
  Widget build(BuildContext context) {
    final cols = <DataTableColumn<RepairRow>>[
      for (final c in columns) _col(c),
      ...extraColumns,
      if (actionBuilder != null)
        DataTableColumn(
          label: 'Actions',
          width: actionWidth,
          cellBuilder: actionBuilder!,
        ),
    ];
    final sortIndex = initialSort == null ? -1 : columns.indexOf(initialSort!);
    return DataTableView<RepairRow>(
      rows: rows,
      columns: cols,
      rowHeight: 60,
      pageSize: pageSize,
      initialSortColumn: sortIndex < 0 ? null : sortIndex,
      initialSortAscending: initialSortAscending,
      resetPageKey: resetPageKey,
      rowKey: (r) => r.id,
      controller: controller,
      onRowTap: onRowTap,
      emptyState: emptyState,
    );
  }
}

// Read-only detail popup for one repair row — everything the old cards
// showed (note, garage, cost, parts, after photos) plus the existing
// activity timeline (the same _RepairEventTimeline the old card's
// ACTIVITY expander loaded, still only on demand).
Future<void> showRepairRowDetails(
  BuildContext context,
  RepairRow r, {
  FirebaseFirestore? firestoreOverride,
  bool showTimeline = true,
}) {
  Widget line(String label, String value) => value.isEmpty
      ? const SizedBox.shrink()
      : Padding(
          padding: const EdgeInsets.only(bottom: 4),
          child: Text('$label: $value', style: AppText.caption),
        );
  return showDialog<void>(
    context: context,
    builder: (dialogContext) => AlertDialog(
      title: Text('${r.code} — ${r.vehicleNumber}'),
      content: SizedBox(
        width: 480,
        child: SingleChildScrollView(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              DataTableStatusChip(
                label: repairStatusLabel(r.status),
                color: repairStatusColor(r.status),
              ),
              const SizedBox(height: AppSpacing.sm),
              Text(r.description, style: AppText.body),
              const SizedBox(height: AppSpacing.sm),
              line('Category', r.categoryName),
              line('Severity', r.severity),
              line('Reported by', r.reportedByName),
              line('Reported', _repairFormatDateTime(r.data['reportedAt'])),
              line('Technical note', r.technicalNote),
              line('Garage',
                  r.garageName.isEmpty ? '' : '${r.garageName} (${r.garageContact.isEmpty ? '—' : r.garageContact})'),
              line('Cost',
                  r.costCents == null ? '' : _formatMoney(_centsToMoney(r.costCents!))),
              line('Parts', r.partsUsed.map((p) => (p as Map)['name']).join(', ')),
              line('After photos',
                  r.afterPhotos.isEmpty ? '' : '${r.afterPhotos.length} attached'),
              line('Returned', r.returnReason),
              line('Rejected', r.rejectReason),
              if (showTimeline) ...[
                const SizedBox(height: AppSpacing.sm),
                Text('ACTIVITY', style: AppText.caption.copyWith(fontWeight: FontWeight.w700)),
                _RepairEventTimeline(
                  collection: 'repairs',
                  docId: r.id,
                  firestoreOverride: firestoreOverride,
                ),
              ],
            ],
          ),
        ),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.pop(dialogContext),
          child: const Text('CLOSE'),
        ),
      ],
    ),
  );
}

class RepairsToDoScreen extends StatefulWidget {
  final FirebaseFirestore? firestoreOverride;
  final String? currentUidOverride;
  const RepairsToDoScreen({super.key, this.firestoreOverride, this.currentUidOverride});

  @override
  State<RepairsToDoScreen> createState() => _RepairsToDoScreenState();
}

class _RepairsToDoScreenState extends State<RepairsToDoScreen> {
  FirebaseFirestore get _db => widget.firestoreOverride ?? FirebaseFirestore.instance;
  String? get _uid => widget.currentUidOverride ?? FirebaseAuth.instance.currentUser?.uid;
  late final Future<bool> _permFuture =
      _currentUserHasRepairPerm(kPermRepairWork, db: _db, uidOverride: _uid);
  late final Stream<QuerySnapshot> _stream = timeoutFirstEventOnly(
    _db
        .collection('repairs')
        .where('status', whereIn: RepairItemStatus.technicalQueue)
        .snapshots(),
    const Duration(seconds: 15),
    onTimeout: () => TimeoutException('Taking too long to load repairs.'),
  );

  final _searchController = TextEditingController();
  String _search = '';
  String _filter = RepairFilter.all;

  final _table = DataTableController<RepairRow>();
  late final UserDirectory _users = UserDirectory.of(db: widget.firestoreOverride);

  void _onUsersChanged() {
    if (mounted) setState(() {});
  }

  String _nameOf(String? uid, String? storedName) => _users.nameOf(uid, storedName: storedName);

  void _exportRepairs(String format, String title, List<String> filters) {
    exportDataTable<RepairRow>(
      context,
      format: format,
      controller: _table,
      title: title,
      filters: filters,
      db: widget.firestoreOverride,
      uid: widget.currentUidOverride,
    );
  }

  @override
  void initState() {
    super.initState();
    _users.version.addListener(_onUsersChanged);
  }

  @override
  void dispose() {
    _users.version.removeListener(_onUsersChanged);
    _searchController.dispose();
    super.dispose();
  }

  void _openWork(RepairRow r) => pushWebAware(
        context,
        _RepairWorkScreen(
          row: r,
          firestoreOverride: widget.firestoreOverride,
          currentUidOverride: widget.currentUidOverride,
        ),
      );

  Widget? _action(BuildContext context, RepairRow r) {
    if (r.status == RepairItemStatus.listed || r.status == RepairItemStatus.returned) {
      return _RepairStartButton(
        row: r,
        db: _db,
        uid: _uid,
        // Same flow as before: START then straight into the work form.
        onStarted: () => _openWork(RepairRow(r.id, {
          ...r.data,
          'status': RepairItemStatus.inProgress,
        })),
      );
    }
    if (r.status == RepairItemStatus.inProgress) {
      return ElevatedButton(
        style: _kTableButtonStyle,
        onPressed: () => _openWork(r),
        child: const Text('MARK DONE'),
      );
    }
    return null;
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<bool>(
      future: _permFuture,
      builder: (context, permSnap) {
        if (permSnap.connectionState != ConnectionState.done) {
          return const TruckRepairScaffold(body: LoadingState());
        }
        if (permSnap.data != true) {
          return const TruckRepairScaffold(
            body: EmptyState(
              icon: Icons.lock_outline,
              title: 'NO ACCESS',
              hint: 'ASK THE ADMIN TO GRANT THIS TRUCK REPAIR PERMISSION',
            ),
          );
        }
        return TruckRepairScaffold(
          appBar: AppBar(
            title: const Text('Repairs To Do'),
            backgroundColor: AppColors.navy,
            foregroundColor: Colors.white,
          ),
          body: StreamBuilder<QuerySnapshot>(
            stream: _stream,
            builder: (context, snapshot) {
              if (snapshot.hasError) {
                return ErrorState(
                  message: snapshot.error is TimeoutException
                      ? 'Taking too long — RETRY'
                      : 'Failed to load repairs: ${snapshot.error}',
                  onRetry: () => setState(() {}),
                );
              }
              if (!snapshot.hasData) return const LoadingState();
              final docs = snapshot.data!.docs;
              if (docs.isEmpty) {
                return const EmptyState(
                  icon: Icons.task_alt,
                  title: 'NO REPAIRS TO DO',
                  hint: 'EVERYTHING IS UP TO DATE',
                );
              }
              final all = docs.map(RepairRow.fromDoc).toList();
              final searched = filterRepairRows(all, search: _search);
              final rows = filterRepairRows(searched, bucket: _filter);
              return Padding(
                padding: const EdgeInsets.all(AppSpacing.md),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    DataTableToolbar(
                      searchController: _searchController,
                      searchHint: 'Search repair code or vehicle number',
                      onSearchChanged: (v) => setState(() => _search = v),
                      onExport: (f) => _exportRepairs(
                        f,
                        'Repairs To Do',
                        describeTableFilters(
                          statusLabel: _filter.replaceAll('_', ' '),
                          search: _search,
                        ),
                      ),
                      selectedFilter: _filter,
                      onFilterChanged: (v) => setState(() => _filter = v),
                      filters: repairFilterOptions(
                        searched,
                        buckets: const [RepairFilter.pending, RepairFilter.inProgress],
                      ),
                    ),
                    const SizedBox(height: AppSpacing.sm),
                    Expanded(
                      child: RepairsTable(
                        rows: rows,
                        resetPageKey: '$_filter|$_search',
                        controller: _table,
                        nameOf: _nameOf,
                        columns: const [
                          RepairCol.code,
                          RepairCol.reportedDate,
                          RepairCol.vehicle,
                          RepairCol.category,
                          RepairCol.description,
                          RepairCol.severity,
                          RepairCol.status,
                          RepairCol.reportedBy,
                          RepairCol.workedBy,
                        ],
                        actionWidth: 130,
                        actionBuilder: (ctx, r) => _action(ctx, r) ?? const SizedBox.shrink(),
                        onRowTap: (r) => r.status == RepairItemStatus.inProgress
                            ? _openWork(r)
                            : showRepairRowDetails(
                                context,
                                r,
                                firestoreOverride: widget.firestoreOverride,
                              ),
                        emptyState: const EmptyState(
                          icon: Icons.filter_alt_off,
                          title: 'NO REPAIRS MATCH THIS FILTER',
                        ),
                      ),
                    ),
                  ],
                ),
              );
            },
          ),
        );
      },
    );
  }
}

// START for one LISTED/RETURNED repair — shared by the Repairs To Do
// table's START button and _RepairsToDoItemCard so both write exactly the
// same fields + STARTED event.
Future<void> startRepairItem(FirebaseFirestore db, String repairId, String uid) async {
  await db.collection('repairs').doc(repairId).update({
    'status': RepairItemStatus.inProgress,
    'startedAt': FieldValue.serverTimestamp(),
    'startedBy': uid,
    'updatedAt': FieldValue.serverTimestamp(),
  });
  await _writeRepairEvent(
    collection: 'repairs',
    docId: repairId,
    action: 'STARTED',
    summary: 'Repair started',
    actorUid: uid,
    actorName: FirebaseAuth.instance.currentUser?.displayName ?? 'Technical',
  );
}

// Table-cell START button — same guard/snackbar-on-failure as the card's
// own _guarded(), then hands the now-IN_PROGRESS repair to onStarted.
class _RepairStartButton extends StatefulWidget {
  final RepairRow row;
  final FirebaseFirestore db;
  final String? uid;
  final VoidCallback? onStarted;
  const _RepairStartButton({required this.row, required this.db, this.uid, this.onStarted});

  @override
  State<_RepairStartButton> createState() => _RepairStartButtonState();
}

class _RepairStartButtonState extends State<_RepairStartButton> {
  bool _busy = false;

  Future<void> _start() async {
    if (_busy) return;
    setState(() => _busy = true);
    var ok = false;
    try {
      await startRepairItem(widget.db, widget.row.id, widget.uid ?? '');
      ok = true;
    } catch (e) {
      final msg = e is FirebaseException ? '${e.code}: ${e.message}' : e.toString();
      debugPrint('[APPROVAL] RepairsToDoScreen action failed — $msg');
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('Failed: $msg')));
      }
    } finally {
      if (mounted) setState(() => _busy = false);
    }
    if (ok) widget.onStarted?.call();
  }

  @override
  Widget build(BuildContext context) {
    return ElevatedButton(
      style: _kTableButtonStyle,
      onPressed: _busy ? null : _start,
      child: _busy
          ? const SizedBox(
              width: 18,
              height: 18,
              child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white),
            )
          : const Text('START'),
    );
  }
}

// Full-page host for the unchanged _RepairsToDoItemCard (technical note,
// garage, cost, parts, after photos, MARK DONE) — a form that long can't
// live inside a table row. Pops back to the table once MARK DONE succeeds.
class _RepairWorkScreen extends StatelessWidget {
  final RepairRow row;
  final FirebaseFirestore? firestoreOverride;
  final String? currentUidOverride;
