class _RepairsToDoItemCard extends StatefulWidget {
  final String repairId;
  final Map<String, dynamic> data;
  final FirebaseFirestore? firestoreOverride;
  final String? currentUidOverride;
  // Called only after MARK DONE's write succeeded (not on a failed or
  // blocked write) — lets the hosting page close itself.
  final VoidCallback? onMarkedDone;
  const _RepairsToDoItemCard({
    required this.repairId,
    required this.data,
    this.firestoreOverride,
    this.currentUidOverride,
    this.onMarkedDone,
  });

  @override
  State<_RepairsToDoItemCard> createState() => _RepairsToDoItemCardState();
}

class _RepairsToDoItemCardState extends State<_RepairsToDoItemCard> {
  FirebaseFirestore get _db => widget.firestoreOverride ?? FirebaseFirestore.instance;
  String? get _uid => widget.currentUidOverride ?? FirebaseAuth.instance.currentUser?.uid;
  bool _busy = false;
  late final _noteController =
      TextEditingController(text: (widget.data['technicalNote'] ?? '').toString());
  late final _garageNameController =
      TextEditingController(text: (widget.data['garageName'] ?? '').toString());
  late final _garageContactController =
      TextEditingController(text: (widget.data['garageContact'] ?? '').toString());
  late final _costController = TextEditingController(
    text: widget.data['costCents'] != null
        ? _centsToMoney((widget.data['costCents'] as num).toInt()).toStringAsFixed(2)
        : '',
  );
  final List<_RepairPartDraft> _parts = [];
  final _afterAttachmentsKey = GlobalKey<_InspectionAttachmentsSectionState>();

  @override
  void initState() {
    super.initState();
    final existingParts = (widget.data['partsUsed'] as List?) ?? const [];
    for (final p in existingParts) {
      final m = p as Map<String, dynamic>;
      final draft = _RepairPartDraft();
      draft.nameController.text = (m['name'] ?? '').toString();
      draft.qtyController.text = (m['qty'] ?? 1).toString();
      draft.priceController.text = m['priceCents'] != null
          ? _centsToMoney((m['priceCents'] as num).toInt()).toStringAsFixed(2)
          : '';
      draft.whereController.text = (m['whereBought'] ?? '').toString();
      _parts.add(draft);
    }
  }

  @override
  void dispose() {
    _noteController.dispose();
    _garageNameController.dispose();
    _garageContactController.dispose();
    _costController.dispose();
    for (final p in _parts) {
      p.dispose();
    }
    super.dispose();
  }

  Future<void> _guarded(Future<void> Function() action) async {
    if (_busy) return;
    setState(() => _busy = true);
    try {
      await action();
    } catch (e) {
      // Previously swallowed entirely — a write blocked by Firestore
      // rules (e.g. permission-denied) reverted the busy spinner with
      // zero feedback, looking exactly like a successful MARK DONE that
      // just never showed up for management. See [APPROVAL] audit.
      final msg = e is FirebaseException ? '${e.code}: ${e.message}' : e.toString();
      debugPrint('[APPROVAL] RepairsToDoScreen action failed — $msg');
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Failed: $msg')),
        );
      }
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  Future<void> _start() async {
    await _guarded(() => startRepairItem(_db, widget.repairId, _uid ?? ''));
  }

  Future<void> _markDone() async {
    if (_noteController.text.trim().isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('A technical note is required to mark this done.')),
      );
      return;
    }
    var markedDone = false;
    await _guarded(() async {
      final uid = _uid ?? '';
      final afterAttachments = await _afterAttachmentsKey.currentState!.uploadAndFinalize(
        'repairs/items/${widget.repairId}/after',
      );
      final costText = _costController.text.trim();
      final costCents =
          costText.isEmpty ? null : ((double.tryParse(costText) ?? 0) * 100).round();
      await _db.collection('repairs').doc(widget.repairId).update({
        'status': RepairItemStatus.donePendingApproval,
        'technicalNote': _noteController.text.trim(),
        'garageName':
            _garageNameController.text.trim().isEmpty ? null : _garageNameController.text.trim(),
        'garageContact': _garageContactController.text.trim().isEmpty
            ? null
            : _garageContactController.text.trim(),
        'costCents': costCents,
        'partsUsed': _parts.map((p) => p.toMap()).toList(),
        'afterPhotos': afterAttachments.photos,
        'afterVoices': afterAttachments.voices,
        'doneAt': FieldValue.serverTimestamp(),
        'doneBy': uid,
        'updatedAt': FieldValue.serverTimestamp(),
      });
      debugPrint(
        '[APPROVAL] MARK DONE: repairs/${widget.repairId} -> '
        '${RepairItemStatus.donePendingApproval}',
      );
      await _writeRepairEvent(
        collection: 'repairs',
        docId: widget.repairId,
        action: 'MARKED_DONE',
        summary: 'Marked done, waiting for management approval',
        actorUid: uid,
        actorName: FirebaseAuth.instance.currentUser?.displayName ?? 'Technical',
      );
      await recomputeRepairListProgress(_db, widget.data['listId'] as String?);
      markedDone = true;
    });
    if (markedDone && mounted) widget.onMarkedDone?.call();
  }

  void _addPart() => setState(() => _parts.add(_RepairPartDraft()));
  void _removePart(int i) => setState(() {
        _parts[i].dispose();
        _parts.removeAt(i);
      });

  @override
  Widget build(BuildContext context) {
    final data = widget.data;
    final status = (data['status'] ?? '').toString();
    return AppCard(
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Expanded(child: Text('${data['code'] ?? ''}', style: AppText.section)),
              const SizedBox(width: AppSpacing.sm),
              // Flexible, not a bare sibling — DONE_PENDING_APPROVAL
              // renders as "DONE PENDING APPROVAL" (21 chars) and would
              // otherwise squeeze the code text with no wrap allowance.
              Flexible(child: StatusChip(status: status)),
            ],
          ),
          const SizedBox(height: 4),
          Text((data['description'] ?? '').toString(), style: AppText.body),
          if (status == RepairItemStatus.returned &&
              (data['returnReason'] ?? '').toString().isNotEmpty) ...[
            const SizedBox(height: 4),
            Text(
              'RETURNED: ${data['returnReason']}',
              style: AppText.caption.copyWith(color: AppColors.danger, fontWeight: FontWeight.w600),
            ),
          ],
          const SizedBox(height: AppSpacing.sm),
          if (status == RepairItemStatus.listed || status == RepairItemStatus.returned)
            SizedBox(
              width: double.infinity,
              child: ElevatedButton(
                onPressed: _busy ? null : _start,
                child: const Text('START'),
              ),
            ),
          if (status == RepairItemStatus.inProgress) ...[
            Text('Technical Note (required)', style: AppText.caption),
            const SizedBox(height: 4),
            TextField(
              controller: _noteController,
              maxLines: 2,
              decoration: InputDecoration(
                border: OutlineInputBorder(borderRadius: BorderRadius.circular(AppRadius.button)),
              ),
            ),
            const SizedBox(height: AppSpacing.sm),
            TextField(
              controller: _garageNameController,
              decoration: const InputDecoration(labelText: 'Garage Name (optional)'),
            ),
            const SizedBox(height: AppSpacing.sm),
            TextField(
              controller: _garageContactController,
              decoration: const InputDecoration(labelText: 'Garage Contact (optional)'),
            ),
            const SizedBox(height: AppSpacing.sm),
            TextField(
              controller: _costController,
              keyboardType: TextInputType.number,
              decoration: const InputDecoration(labelText: 'Cost (optional)'),
            ),
            const SizedBox(height: AppSpacing.sm),
            Text('Parts Used (optional)', style: AppText.caption),
            for (var i = 0; i < _parts.length; i++)
              Padding(
                padding: const EdgeInsets.only(top: AppSpacing.xs),
                child: Row(
                  children: [
                    Expanded(
                      flex: 3,
                      child: TextField(
                        controller: _parts[i].nameController,
                        decoration: const InputDecoration(hintText: 'Part'),
                      ),
                    ),
                    const SizedBox(width: 4),
                    Expanded(
                      child: TextField(
                        controller: _parts[i].qtyController,
                        keyboardType: TextInputType.number,
                        decoration: const InputDecoration(hintText: 'Qty'),
                      ),
                    ),
                    const SizedBox(width: 4),
                    Expanded(
                      flex: 2,
                      child: TextField(
                        controller: _parts[i].priceController,
                        keyboardType: TextInputType.number,
                        decoration: const InputDecoration(hintText: 'Price'),
                      ),
                    ),
                    const SizedBox(width: 4),
                    Expanded(
                      flex: 2,
                      child: TextField(
                        controller: _parts[i].whereController,
                        decoration: const InputDecoration(hintText: 'Where bought'),
                      ),
                    ),
                    IconButton(
                      icon: const Icon(Icons.close, size: 18),
                      onPressed: () => _removePart(i),
                    ),
                  ],
                ),
              ),
            Align(
              alignment: Alignment.centerLeft,
              child: TextButton.icon(
                onPressed: _addPart,
                icon: const Icon(Icons.add),
                label: const Text('ADD PART'),
              ),
            ),
            const SizedBox(height: AppSpacing.sm),
            Text('After Photos (optional)', style: AppText.caption),
            _InspectionAttachmentsSection(key: _afterAttachmentsKey),
            const SizedBox(height: AppSpacing.sm),
            SizedBox(
              width: double.infinity,
              child: ElevatedButton(
                onPressed: _busy ? null : _markDone,
                child: _busy
                    ? const SizedBox(
                        width: 20,
                        height: 20,
                        child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white),
                      )
                    : const Text('MARK DONE'),
              ),
            ),
          ],
        ],
      ),
    );
  }
}

// ---------------- FINAL APPROVAL (management) ----------------
class RepairFinalApprovalScreen extends StatefulWidget {
  final FirebaseFirestore? firestoreOverride;
  final String? currentUidOverride;
  const RepairFinalApprovalScreen({super.key, this.firestoreOverride, this.currentUidOverride});

  @override
  State<RepairFinalApprovalScreen> createState() => _RepairFinalApprovalScreenState();
}

class _RepairFinalApprovalScreenState extends State<RepairFinalApprovalScreen> {
  FirebaseFirestore get _db => widget.firestoreOverride ?? FirebaseFirestore.instance;
  String? get _uid => widget.currentUidOverride ?? FirebaseAuth.instance.currentUser?.uid;
  late final Future<bool> _permFuture =
      _currentUserHasRepairPerm(kPermApprove, db: _db, uidOverride: _uid);
  late final Stream<QuerySnapshot> _stream = () {
    debugPrint(
      '[APPROVAL] Final Approval query: start — repairs where status=='
      '${RepairItemStatus.donePendingApproval}',
    );
    return timeoutFirstEventOnly(
      _db
          .collection('repairs')
          .where('status', isEqualTo: RepairItemStatus.donePendingApproval)
          .snapshots(),
      const Duration(seconds: 15),
      onTimeout: () => TimeoutException('Taking too long to load repairs.'),
    );
  }();

  final _searchController = TextEditingController();
  String _search = '';

  final _table = DataTableController<RepairRow>();
  late final UserDirectory _users = UserDirectory.of(db: widget.firestoreOverride);

  void _onUsersChanged() {
    if (mounted) setState(() {});
  }

  String _nameOf(String? uid, String? storedName) => _users.nameOf(uid, storedName: storedName);

  void _exportRepairs(String format, String title, List<String> filters) {
    exportDataTable<RepairRow>(
      context,
      format: format,
      controller: _table,
      title: title,
      filters: filters,
      db: widget.firestoreOverride,
      uid: widget.currentUidOverride,
    );
  }

  @override
  void initState() {
    super.initState();
    _users.version.addListener(_onUsersChanged);
  }

  @override
  void dispose() {
    _users.version.removeListener(_onUsersChanged);
    _searchController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<bool>(
      future: _permFuture,
      builder: (context, permSnap) {
        if (permSnap.connectionState != ConnectionState.done) {
          return const TruckRepairScaffold(body: LoadingState());
        }
        if (permSnap.data != true) {
          return const TruckRepairScaffold(
            body: EmptyState(
              icon: Icons.lock_outline,
              title: 'NO ACCESS',
              hint: 'ASK THE ADMIN TO GRANT THIS TRUCK REPAIR PERMISSION',
            ),
          );
        }
        return TruckRepairScaffold(
          appBar: AppBar(
            title: const Text('Final Approval'),
            backgroundColor: AppColors.navy,
            foregroundColor: Colors.white,
          ),
          body: StreamBuilder<QuerySnapshot>(
            stream: _stream,
            builder: (context, snapshot) {
              if (snapshot.hasError) {
                final err = snapshot.error;
                final code = err is FirebaseException ? err.code : 'unknown';
                final message = err is FirebaseException ? err.message : err.toString();
                debugPrint(
                  '[APPROVAL] Final Approval query: ERROR code=$code message=$message',
                );
                return ErrorState(
                  message: snapshot.error is TimeoutException
                      ? 'Taking too long — RETRY'
                      : 'Failed to load repairs: ${snapshot.error}',
                  onRetry: () => setState(() {}),
                );
              }
              if (!snapshot.hasData) return const LoadingState();
              final docs = snapshot.data!.docs;
              debugPrint('[APPROVAL] Final Approval query: doc count=${docs.length}');
              if (docs.isEmpty) {
                return const EmptyState(
                  icon: Icons.task_alt,
                  title: 'NOTHING WAITING FOR APPROVAL',
                );
              }
              final all = docs.map(RepairRow.fromDoc).toList();
              final rows = filterRepairRows(all, search: _search);
              return Padding(
                padding: const EdgeInsets.all(AppSpacing.md),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    DataTableToolbar(
                      searchController: _searchController,
                      searchHint: 'Search repair code or vehicle number',
                      onSearchChanged: (v) => setState(() => _search = v),
                      onExport: (f) => _exportRepairs(
                        f,
                        'Repairs Awaiting Approval',
                        describeTableFilters(
                          search: _search,
                          extra: {'Status': 'AWAITING APPROVAL'},
                        ),
                      ),
                    ),
                    const SizedBox(height: AppSpacing.sm),
                    Expanded(
                      child: RepairsTable(
                        rows: rows,
                        resetPageKey: _search,
                        controller: _table,
                        nameOf: _nameOf,
                        columns: const [
                          RepairCol.code,
                          RepairCol.reportedDate,
                          RepairCol.vehicle,
                          RepairCol.category,
                          RepairCol.description,
                          RepairCol.technicalNote,
                          RepairCol.cost,
                          RepairCol.garage,
                          RepairCol.reportedBy,
                          RepairCol.workedBy,
                          RepairCol.doneDate,
                          RepairCol.status,
                        ],
                        actionWidth: 270,
                        actionBuilder: (_, r) => _FinalApprovalActions(
                          repairId: r.id,
                          data: r.data,
                          firestoreOverride: widget.firestoreOverride,
                          currentUidOverride: widget.currentUidOverride,
                        ),
                        onRowTap: (r) => showRepairRowDetails(
                          context,
                          r,
                          firestoreOverride: widget.firestoreOverride,
                        ),
                        emptyState: const EmptyState(
                          icon: Icons.search_off,
                          title: 'NO REPAIRS MATCH THIS SEARCH',
                        ),
                      ),
                    ),
                  ],
                ),
              );
            },
          ),
        );
      },
    );
  }
}

// APPROVE / RETURN for one DONE_PENDING_APPROVAL repair, shown in the
// Final Approval table's Actions cell. _approve/_returnForRework are the
// same code the old per-repair card ran; only the layout moved.
class _FinalApprovalActions extends StatefulWidget {
  final String repairId;
  final Map<String, dynamic> data;
  final FirebaseFirestore? firestoreOverride;
  final String? currentUidOverride;
  const _FinalApprovalActions({
    required this.repairId,
    required this.data,
    this.firestoreOverride,
    this.currentUidOverride,
  });

  @override
  State<_FinalApprovalActions> createState() => _FinalApprovalActionsState();
}

class _FinalApprovalActionsState extends State<_FinalApprovalActions> {
  FirebaseFirestore get _db => widget.firestoreOverride ?? FirebaseFirestore.instance;
  String? get _uid => widget.currentUidOverride ?? FirebaseAuth.instance.currentUser?.uid;
  bool _busy = false;

  Future<void> _guarded(Future<void> Function() action) async {
    if (_busy) return;
    setState(() => _busy = true);
    try {
      await action();
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  Future<void> _approve() async {
    final confirmed = await showAppConfirmDialog(
      context: context,
      title: 'Approve Repair?',
      message: 'This marks ${widget.data['code'] ?? 'this repair'} as COMPLETED.',
      confirmLabel: 'Approve',
    );
    if (!confirmed) return;
    await _guarded(() async {
      final uid = _uid ?? '';
      await _db.collection('repairs').doc(widget.repairId).update({
        'status': RepairItemStatus.completed,
        'completedAt': FieldValue.serverTimestamp(),
        'completedBy': uid,
        'updatedAt': FieldValue.serverTimestamp(),
      });
      await _writeRepairEvent(
        collection: 'repairs',
        docId: widget.repairId,
        action: 'COMPLETED',
        summary: 'Approved and completed',
        actorUid: uid,
        actorName: FirebaseAuth.instance.currentUser?.displayName ?? 'Management',
      );
    });
  }

  Future<void> _returnForRework() async {
    final reasonController = TextEditingController();
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Return For Rework'),
        content: TextField(
          controller: reasonController,
          maxLines: 3,
          decoration: const InputDecoration(labelText: 'Reason (required)'),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('CANCEL'),
          ),
          ElevatedButton(
            onPressed: () => Navigator.pop(dialogContext, true),
            child: const Text('RETURN'),
          ),
        ],
      ),
    );
    if (confirmed != true) return;
    final reason = reasonController.text.trim();
    if (reason.isEmpty) {
      if (mounted) {
        ScaffoldMessenger.of(context)
            .showSnackBar(const SnackBar(content: Text('A reason is required to return this.')));
      }
      return;
    }
    await _guarded(() async {
      final uid = _uid ?? '';
      await _db.collection('repairs').doc(widget.repairId).update({
        'status': RepairItemStatus.returned,
        'returnReason': reason,
        'returnedAt': FieldValue.serverTimestamp(),
        'returnedBy': uid,
        'updatedAt': FieldValue.serverTimestamp(),
      });
      await _writeRepairEvent(
        collection: 'repairs',
        docId: widget.repairId,
        action: 'RETURNED',
        summary: 'Returned for rework: $reason',
        actorUid: uid,
        actorName: FirebaseAuth.instance.currentUser?.displayName ?? 'Management',
      );
      await recomputeRepairListProgress(_db, widget.data['listId'] as String?);
    });
  }

  @override
  Widget build(BuildContext context) {
    // scaleDown: never overflows the fixed-width cell, even with a large
    // system font size.
    return FittedBox(
      fit: BoxFit.scaleDown,
      alignment: Alignment.centerLeft,
      child: Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        OutlinedButton(
          style: _kTableButtonStyle,
          onPressed: _busy ? null : _returnForRework,
          child: const Text('RETURN'),
        ),
        const SizedBox(width: 8),
        ElevatedButton(
          style: _kTableButtonStyle,
          onPressed: _busy ? null : _approve,
          child: _busy
              ? const SizedBox(
                  width: 18,
                  height: 18,
                  child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white),
                )
              : const Text('APPROVE'),
        ),
      ],
      ),
    );
  }
}

// ---------------- VEHICLE REPAIR HISTORY (v2) ----------------
class RepairHistoryScreen extends StatefulWidget {
  final String? prefillVehicleNumber;
  final FirebaseFirestore? firestoreOverride;
  final String? currentUidOverride;
  const RepairHistoryScreen({
    super.key,
    this.prefillVehicleNumber,
    this.firestoreOverride,
    this.currentUidOverride,
  });

  @override
  State<RepairHistoryScreen> createState() => _RepairHistoryScreenState();
}

class _RepairHistoryScreenState extends State<RepairHistoryScreen> {
  FirebaseFirestore get _db => widget.firestoreOverride ?? FirebaseFirestore.instance;
  String? get _uid => widget.currentUidOverride ?? FirebaseAuth.instance.currentUser?.uid;
  late final Future<bool> _permFuture =
      _currentUserHasRepairPerm(kPermHistoryView, db: _db, uidOverride: _uid);
  late final Future<List<Map<String, dynamic>>> _categoriesFuture = _loadCategories();
  late final TextEditingController _searchController =
      TextEditingController(text: widget.prefillVehicleNumber ?? '');
  String _categoryFilter = 'ALL';
  String _statusFilter = RepairFilter.all;
  late Stream<QuerySnapshot>? _stream = _buildStream();

  Future<List<Map<String, dynamic>>> _loadCategories() async {
    final snap = await _db.collection('repair_categories').orderBy('sortOrder').get();
    return snap.docs.map((d) => d.data()).toList();
  }

  Stream<QuerySnapshot>? _buildStream() {
    final vehicleNumber = normalizeVehicleNumber(_searchController.text);
    if (vehicleNumber.isEmpty) return null;
    return timeoutFirstEventOnly(
      _db
          .collection('repairs')
          .where('vehicleNumber', isEqualTo: vehicleNumber)
          .orderBy('reportedAt', descending: true)
          .snapshots(),
      const Duration(seconds: 15),
      onTimeout: () => TimeoutException('Taking too long to load history.'),
    );
  }

  void _search() => setState(() => _stream = _buildStream());

  final _table = DataTableController<RepairRow>();
  late final UserDirectory _users = UserDirectory.of(db: widget.firestoreOverride);

  void _onUsersChanged() {
    if (mounted) setState(() {});
  }

  String _nameOf(String? uid, String? storedName) => _users.nameOf(uid, storedName: storedName);

  void _exportRepairs(String format, String title, List<String> filters) {
    exportDataTable<RepairRow>(
      context,
      format: format,
      controller: _table,
      title: title,
      filters: filters,
      db: widget.firestoreOverride,
      uid: widget.currentUidOverride,
    );
  }

  @override
  void initState() {
    super.initState();
    _users.version.addListener(_onUsersChanged);
  }

  @override
  void dispose() {
    _users.version.removeListener(_onUsersChanged);
    _searchController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<bool>(
      future: _permFuture,
      builder: (context, permSnap) {
        if (permSnap.connectionState != ConnectionState.done) {
          return const TruckRepairScaffold(body: LoadingState());
        }
        if (permSnap.data != true) {
          return const TruckRepairScaffold(
            body: EmptyState(
              icon: Icons.lock_outline,
              title: 'NO ACCESS',
              hint: 'ASK THE ADMIN TO GRANT THIS TRUCK REPAIR PERMISSION',
            ),
          );
        }
        return TruckRepairScaffold(
          appBar: AppBar(
            title: const Text('Repair History'),
            backgroundColor: AppColors.navy,
            foregroundColor: Colors.white,
          ),
          body: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Padding(
                padding: const EdgeInsets.all(AppSpacing.md),
                child: Row(
                  children: [
                    Expanded(
                      child: TextField(
                        controller: _searchController,
                        textCapitalization: TextCapitalization.characters,
                        inputFormatters: [UpperCaseTextFormatter()],
                        decoration: const InputDecoration(labelText: 'Vehicle Number'),
                        onSubmitted: (_) => _search(),
                      ),
                    ),
                    const SizedBox(width: AppSpacing.sm),
                    ElevatedButton(onPressed: _search, child: const Text('SEARCH')),
                  ],
                ),
              ),
              Padding(
                padding: const EdgeInsets.symmetric(horizontal: AppSpacing.md),
                child: FutureBuilder<List<Map<String, dynamic>>>(
                  future: _categoriesFuture,
                  builder: (context, catSnap) {
                    final categories = catSnap.data ?? const [];
                    return DropdownButtonFormField<String>(
                      initialValue: _categoryFilter,
                      isExpanded: true,
                      decoration: const InputDecoration(labelText: 'Category'),
                      items: [
                        const DropdownMenuItem(value: 'ALL', child: Text('All Categories')),
                        ...categories.map(
                          (c) => DropdownMenuItem<String>(
                            value: c['code'].toString(),
                            child: Text(
                              '${c['code']} — ${c['name']}',
                              overflow: TextOverflow.ellipsis,
                            ),
                          ),
                        ),
                      ],
                      onChanged: (v) => setState(() => _categoryFilter = v ?? 'ALL'),
                    );
                  },
                ),
              ),
              Expanded(
                child: _stream == null
                    ? const EmptyState(
                        icon: Icons.search,
                        title: 'ENTER A VEHICLE NUMBER',
                        hint: 'SEARCH TO SEE ITS REPAIR HISTORY',
                      )
                    : StreamBuilder<QuerySnapshot>(
                        stream: _stream,
                        builder: (context, snapshot) {
                          if (snapshot.hasError) {
                            return ErrorState(
                              message: snapshot.error is TimeoutException
                                  ? 'Taking too long — RETRY'
                                  : 'Failed to load history: ${snapshot.error}',
                              onRetry: _search,
                            );
                          }
                          if (!snapshot.hasData) return const LoadingState();
                          final byCategory = snapshot.data!.docs
                              .where((d) =>
                                  _categoryFilter == 'ALL' ||
                                  (d.data() as Map<String, dynamic>)['categoryCode'] ==
                                      _categoryFilter)
                              .map(RepairRow.fromDoc)
                              .toList();
                          if (byCategory.isEmpty) {
                            return const EmptyState(
                              icon: Icons.history,
                              title: 'NO REPAIR HISTORY',
                            );
                          }
                          final rows = filterRepairRows(byCategory, bucket: _statusFilter);
                          return Padding(
                            padding: const EdgeInsets.all(AppSpacing.md),
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                DataTableToolbar(
                                  onExport: (f) => _exportRepairs(
                                    f,
                                    'Vehicle Repair History',
                                    describeTableFilters(
                                      statusLabel: _statusFilter.replaceAll('_', ' '),
                                      extra: {
                                        'Vehicle': normalizeVehicleNumber(_searchController.text),
                                        if (_categoryFilter != 'ALL') 'Category': _categoryFilter,
                                      },
                                    ),
                                  ),
                                  selectedFilter: _statusFilter,
                                  onFilterChanged: (v) => setState(() => _statusFilter = v),
                                  filters: repairFilterOptions(byCategory),
                                ),
                                const SizedBox(height: AppSpacing.sm),
                                Expanded(
                                  child: RepairsTable(
                                    rows: rows,
                                    resetPageKey: '$_statusFilter|$_categoryFilter',
                                    controller: _table,
                                    nameOf: _nameOf,
                                    columns: const [
                                      RepairCol.code,
                                      RepairCol.reportedDate,
                                      RepairCol.category,
                                      RepairCol.description,
                                      RepairCol.status,
                                      RepairCol.reportedBy,
                                      RepairCol.workedBy,
                                      RepairCol.approvedBy,
                                      RepairCol.approvedDate,
                                      RepairCol.cost,
                                    ],
                                    actionWidth: 130,
                                    actionBuilder: (_, r) => TextButton(
                                      style: _kTableButtonStyle,
                                      onPressed: () => showRepairRowDetails(
                                        context,
                                        r,
                                        firestoreOverride: widget.firestoreOverride,
                                      ),
                                      child: const Text('ACTIVITY'),
                                    ),
                                    onRowTap: (r) => showRepairRowDetails(
                                      context,
                                      r,
                                      firestoreOverride: widget.firestoreOverride,
                                    ),
                                    emptyState: const EmptyState(
                                      icon: Icons.filter_alt_off,
                                      title: 'NO REPAIRS MATCH THIS FILTER',
                                    ),
                                  ),
                                ),
                              ],
                            ),
                          );
                        },
                      ),
              ),
            ],
          ),
        );
      },
    );
  }
}

// ---------------- REPAIR ALERTS (standalone counts/badges) ----------------
// Deliberately NOT routed through ServiceAlert/computeServiceAlerts/
// ServiceAlertKind (those stay untouched in this step) — these are simple
// status counts, not the per-vehicle milestone math ServiceAlert exists
// for, so they get their own small standalone fetch, same shape as
// ServiceFleetSummaryCounts.
Future<({bool qualifies, bool isManagement, int reported, int waitingApproval, int toDo, int returned, List<String> reportedVehicles})>
    _loadRepairCountsForCurrentUser({FirebaseFirestore? db, String? uid}) async {
  final firestore = db ?? FirebaseFirestore.instance;
  Map<String, dynamic>? userData;
  if (uid != null) {
    final doc = await firestore.collection('users').doc(uid).get();
    userData = doc.data();
  }
  final role = userData?['role'] as String?;
  final isAdminOrOwner = role == 'admin' || role == 'owner';
  final isManagement = isAdminOrOwner || hasRepairPerm(userData, kPermApprove);
  final isTechnical = isAdminOrOwner || hasRepairPerm(userData, kPermRepairWork);
  final qualifies = isManagement || isTechnical;
  if (!qualifies) {
    return (
      qualifies: false,
      isManagement: false,
      reported: 0,
      waitingApproval: 0,
      toDo: 0,
      returned: 0,
      reportedVehicles: const <String>[],
    );
  }
  final snap = await firestore.collection('repairs').get();
  final docs = snap.docs.map((d) => d.data()).toList();
  final reportedDocs = docs.where((d) => d['status'] == RepairItemStatus.reported).toList();
  final waitingApproval =
      docs.where((d) => d['status'] == RepairItemStatus.donePendingApproval).length;
  final toDo = docs
      .where((d) =>
          d['status'] == RepairItemStatus.listed || d['status'] == RepairItemStatus.inProgress)
      .length;
  final returnedCount = docs.where((d) => d['status'] == RepairItemStatus.returned).length;
  return (
    qualifies: true,
    isManagement: isManagement,
    reported: reportedDocs.length,
    waitingApproval: waitingApproval,
    toDo: toDo,
    returned: returnedCount,
    reportedVehicles:
        reportedDocs.map((d) => (d['vehicleNumber'] ?? '').toString()).toSet().toList(),
  );
}

// NEW REPAIRS / WAITING APPROVAL / TO DO / RETURNED fleet-wide count row —
// same shape as ServiceFleetSummaryCounts (Scheduled Vehicle Service).
// Also fires a once-per-device-per-day summary SnackBar for management the
// first time it builds with new REPORTED repairs present.
class RepairFleetSummaryCounts extends StatefulWidget {
  final FirebaseFirestore? firestoreOverride;
  final String? currentUidOverride;
  const RepairFleetSummaryCounts({super.key, this.firestoreOverride, this.currentUidOverride});

  @override
  State<RepairFleetSummaryCounts> createState() => _RepairFleetSummaryCountsState();
}

class _RepairFleetSummaryCountsState extends State<RepairFleetSummaryCounts> {
  FirebaseFirestore get _db => widget.firestoreOverride ?? FirebaseFirestore.instance;
  String? get _uid => widget.currentUidOverride ?? FirebaseAuth.instance.currentUser?.uid;
  late final Future<({bool qualifies, bool isManagement, int reported, int waitingApproval, int toDo, int returned, List<String> reportedVehicles})>
      _future = _loadRepairCountsForCurrentUser(db: _db, uid: _uid);

  static const _lastShownPrefsKey = 'repair_new_reports_daily_summary_last_shown';

  Future<void> _maybeShowDailySummary(int reported, List<String> vehicles) async {
    if (reported == 0) return;
    try {
      final prefs = await SharedPreferences.getInstance();
      final todayKey = dailyCheckDateKey(DateTime.now());
      if (prefs.getString(_lastShownPrefsKey) == todayKey) return;
      await prefs.setString(_lastShownPrefsKey, todayKey);
      if (!mounted) return;
      final message = vehicles.length == 1
          ? '$reported new repair(s) on ${vehicles.first}'
          : '$reported new repairs across ${vehicles.length} vehicles';
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(message), duration: const Duration(seconds: 4)),
      );
    } catch (e) {
      debugPrint('RepairFleetSummaryCounts: daily summary snackbar failed: $e');
    }
  }

  Widget _countTile(String label, int count, Color color) {
    return Expanded(
      child: Container(
        padding: const EdgeInsets.symmetric(vertical: 10),
        decoration: BoxDecoration(
          color: color.withOpacity(0.12),
          borderRadius: BorderRadius.circular(AppRadius.card),
        ),
        child: Column(
          children: [
            Text(
              '$count',
              style: TextStyle(color: color, fontWeight: FontWeight.bold, fontSize: 20),
            ),
            const SizedBox(height: 2),
            Text(
              label,
              style: TextStyle(color: color, fontSize: 10, fontWeight: FontWeight.w600),
              textAlign: TextAlign.center,
            ),
          ],
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder(
      future: _future,
      builder: (context, snap) {
        if (snap.connectionState != ConnectionState.done || snap.data?.qualifies != true) {
          return const SizedBox.shrink();
        }
        final d = snap.data!;
        if (d.isManagement) {
          WidgetsBinding.instance.addPostFrameCallback((_) {
            if (mounted) _maybeShowDailySummary(d.reported, d.reportedVehicles);
          });
        }
        return Padding(
          padding: const EdgeInsets.only(bottom: AppSpacing.md),
          child: Row(
            children: [
              _countTile('NEW REPAIRS', d.reported, AppColors.danger),
              const SizedBox(width: 8),
              _countTile('WAITING APPROVAL', d.waitingApproval, AppColors.warning),
              const SizedBox(width: 8),
              _countTile('TO DO', d.toDo, AppColors.info),
              const SizedBox(width: 8),
              _countTile('RETURNED', d.returned, AppColors.danger),
            ],
          ),
        );
      },
    );
  }
}

// Small red count badge for a repair tile (NEW REPAIRS/REPAIRS TO
