// ---------------- SCHEDULED VEHICLE SERVICE ----------------
// Mechanic submits a completed service (items ticked + extras) -> manager
// approves -> that record becomes the new "last done" baseline for every
// item it ticked. New collections (service_items, service_records) rather
// than extending the existing GPS-based Garage "Log Service"/serviceTypes
// feature (trucks/{id}/serviceHistory, trucks/{id}/serviceTypes, gated by
// canAccessGarage) — that feature has no submit/approve concept at all
// (every write takes effect immediately) and a different, unrelated
// permission flag; adding status/items/photos/garage-contact fields to its
// minimal shape would risk GarageScreen's existing history list rendering
// a pending record as if it were already done. Both features coexist
// untouched; see kPermServiceSetup's doc comment.

// Best-effort current KM for a vehicle, reusing the exact same GPS/Traccar
// path the existing Garage feature already uses (GarageService.fetchStatus)
// — so "current km" here is the SAME number GarageScreen's Trucks tab
// would show, not a second, possibly-disagreeing source. Returns null for
// any vehicle without isCompanyTruck+gpsDeviceId (most non-fleet trucks, and
// any vehicle this call can't resolve for any reason) — callers MUST treat
// null as "unknown", never as 0.
// db override so widget tests never touch the real FirebaseFirestore.instance
// (an un-mocked platform-channel call can hang rather than fail fast) —
// defaults to it in every production call site, unchanged behavior.
Future<double?> _fetchLiveKmForVehicle(
  String vehicleNumber, {
  FirebaseFirestore? db,
  bool forceRefresh = false,
  String? uidOverride,
  bool allowSummaryFallback = true,
}) async {
  try {
    final truckSnap = await (db ?? FirebaseFirestore.instance)
        .collection('trucks')
        .where('truckNumber', isEqualTo: vehicleNumber)
        .limit(1)
        .get();
    if (truckSnap.docs.isEmpty) return null;
    final status = await GarageService.fetchStatus(
      truckSnap.docs.first,
      forceRefresh: forceRefresh,
      db: db,
      uidOverride: uidOverride,
      allowSummaryFallback: allowSummaryFallback,
    );
    return status?.currentTotalKm;
  } catch (e) {
    // Covers a timed-out/failed VehicleKmCache call too (fetchStatus
    // doesn't catch that itself) — callers below always treat this as
    // "unknown" and fall back to service_records/manual_km_logs, same as
    // any other GPS failure.
    debugPrint('_fetchLiveKmForVehicle($vehicleNumber): $e');
    return null;
  }
}

// Current km + a short label saying where it came from, so staleness is
// never hidden from the screens that show it. Source order: fresh Traccar
// -> vehicle_km_cache (last known GPS reading, labelled with its age) ->
// manual_km_logs/service_records (freshest of the two wins) -> unknown.
// Never fakes a value.
Future<({double? km, String source})> fetchBestKnownKm(
  String vehicleNumber, {
  FirebaseFirestore? db,
  bool forceRefresh = false,
  String? uidOverride,
  bool allowSummaryFallback = true,
}) async {
  final live = await _fetchLiveKmForVehicle(
    vehicleNumber,
    db: db,
    forceRefresh: forceRefresh,
    uidOverride: uidOverride,
    allowSummaryFallback: allowSummaryFallback,
  );
  if (live != null) return (km: live, source: 'live GPS reading');

  final cached = await readVehicleKmCache(vehicleNumber, db: db);
  if (cached != null) {
    return (
      km: cached.km,
      source: 'last known GPS reading (as of ${formatVehicleKmCacheAge(cached.updatedAt)})',
    );
  }

  double? bestKm;
  var bestMillis = -1;
  var bestSource = '';
  try {
    final recordsSnap = await (db ?? FirebaseFirestore.instance)
        .collection('service_records')
        .where('vehicleNumber', isEqualTo: vehicleNumber)
        .get();
    for (final doc in recordsSnap.docs) {
      final data = doc.data();
      final ts = data['serviceDate'];
      final millis = ts is Timestamp ? ts.millisecondsSinceEpoch : 0;
      final km = (data['currentKm'] as num?)?.toDouble();
      if (km != null && millis > bestMillis) {
        bestMillis = millis;
        bestKm = km;
        bestSource = 'last recorded service — no GPS, may be stale';
      }
    }
  } catch (e) {
    debugPrint('fetchBestKnownKm($vehicleNumber) service_records: $e');
  }
  // A technician's manual odometer entry (see logManualKm) wins over a
  // stale service record when it's the more recent of the two.
  try {
    final manualSnap = await (db ?? FirebaseFirestore.instance)
        .collection('manual_km_logs')
        .where('vehicleNumber', isEqualTo: vehicleNumber)
        .get();
    for (final doc in manualSnap.docs) {
      final data = doc.data();
      final ts = data['enteredAt'];
      final millis = ts is Timestamp ? ts.millisecondsSinceEpoch : 0;
      final km = (data['km'] as num?)?.toDouble();
      if (km != null && millis > bestMillis) {
        bestMillis = millis;
        bestKm = km;
        bestSource = 'manually entered — no GPS, may be stale';
      }
    }
  } catch (e) {
    debugPrint('fetchBestKnownKm($vehicleNumber) manual_km_logs: $e');
  }
  if (bestKm != null) return (km: bestKm, source: bestSource);
  return (km: null, source: 'unknown — no GPS and no service history yet');
}

// Batch version of fetchBestKnownKm's GPS->manual-fallback priority, for
// the RED ALERTS feature's ~76-truck fleet-wide computation — calling
// fetchBestKnownKm once per vehicle would cost up to ~76 separate Traccar
// HTTP round-trips AND ~76 separate full-collection-filtered
// service_records queries. This costs ONE shared Traccar devices() call
// (via GarageService.fetchAllStatuses, already built for the Garage
// Notifications tab) plus one fetchDistanceSummary() per GPS truck, and —
// when `serviceRecords` isn't already in hand — ONE unfiltered
// service_records read grouped client-side by vehicleNumber for every
// vehicle GPS didn't resolve. fetchServiceAlertsData always passes its own
// already-fetched records here instead, so the collection is only ever
// read once per cache refresh.
Future<Map<String, ({double? km, String source})>> fetchKmByVehicleForAlerts({
  required List<String> vehicleNumbers,
  FirebaseFirestore? db,
  List<Map<String, dynamic>>? serviceRecords,
  // Lets fetchServiceAlertsData track GPS specifically as its own
  // independent "source" (debugPrint + failedSources) without this
  // function needing to throw — it never does; a GPS failure always
  // degrades to the manual-km fallback (or 'unknown') below, same as
  // before this callback existed.
  void Function(Object error)? onGpsBatchError,
}) async {
  final result = <String, ({double? km, String source})>{};

  // Instant tier: the one cached vehicle_km_cache collection read (TTL 5
  // min) — fills in every vehicle this cache already knows about, even a
  // stale entry ("still use it, just mark it" — see
  // VehicleKmCacheEntry.isLabelStale), before Traccar is ever touched.
  Map<String, VehicleKmCacheEntry> bulk = const {};
  try {
    bulk = await VehicleKmCache.allCached(db: db);
  } catch (e) {
    debugPrint('fetchKmByVehicleForAlerts: vehicle_km_cache bulk read failed: $e');
  }
  for (final v in vehicleNumbers) {
    final entry = bulk[v];
    if (entry == null) continue;
    result[v] = (
      km: entry.km,
      source: 'last known GPS reading (as of ${formatVehicleKmCacheAge(entry.updatedAt)})'
          '${entry.isLabelStale ? ' — stale' : ''}',
    );
  }

  // Live tier: only vehicles missing from the cache or whose entry needs a
  // refresh (>= 30 min old, same threshold VehicleKmCacheEntry uses for
  // fleet screens generally) go through the heavier Traccar batch below —
  // a fully warm cache skips this block entirely.
  final needsLive =
      vehicleNumbers.where((v) => bulk[v]?.needsBackgroundRefresh ?? true).toSet();
  if (needsLive.isNotEmpty) {
    try {
      // Bounded wait: GarageService.fetchAllStatuses() calls
      // FirebaseFirestore.instance directly (no db override) and a real
      // Traccar HTTP round-trip per GPS truck — either can be slow/down, and
      // under TestWidgetsFlutterBinding specifically an unmocked Firestore
      // platform channel call hangs rather than failing fast (confirmed:
      // completes immediately under a plain `test()` body, never completes
      // under `testWidgets()` without this timeout). 2s is generous for a
      // real Traccar response and still keeps this feature's "don't block
      // on GPS" promise.
      // Fleet-wide badge computation: positions-only live km (see
      // VehicleKmCache.currentTotalKm) — no per-truck summary calls.
      final batch = await GarageService.fetchAllStatuses(allowSummaryFallback: false)
          .timeout(const Duration(seconds: 2));
      for (final status in batch.vehicleStatuses) {
        if (status.isBike) continue;
        if (!needsLive.contains(status.vehicleNumber)) continue;
        result[status.vehicleNumber] = (km: status.currentTotalKm, source: 'live GPS reading');
      }
    } catch (e) {
      debugPrint('fetchKmByVehicleForAlerts: GPS batch failed: $e');
      onGpsBatchError?.call(e);
    }
  }
  final remaining = vehicleNumbers.where((v) => !result.containsKey(v)).toSet();
  if (remaining.isNotEmpty) {
    final lastMillis = <String, int>{};
    final lastKm = <String, double>{};
    final lastSource = <String, String>{};
    try {
      final records = serviceRecords ??
          (await (db ?? FirebaseFirestore.instance).collection('service_records').get())
              .docs
              .map((d) => d.data())
              .toList();
      for (final data in records) {
        final vehicleNumber = (data['vehicleNumber'] ?? '').toString();
        if (!remaining.contains(vehicleNumber)) continue;
        final ts = data['serviceDate'];
        final millis = ts is Timestamp
            ? ts.millisecondsSinceEpoch
            : (ts is DateTime ? ts.millisecondsSinceEpoch : 0);
        if (millis >= (lastMillis[vehicleNumber] ?? -1)) {
          final km = (data['currentKm'] as num?)?.toDouble();
          if (km != null) {
            lastMillis[vehicleNumber] = millis;
            lastKm[vehicleNumber] = km;
            lastSource[vehicleNumber] = 'last recorded service — no GPS, may be stale';
          }
        }
      }
    } catch (e) {
      debugPrint('fetchKmByVehicleForAlerts: service_records fallback failed: $e');
    }
    // A technician's manual odometer entry (see logManualKm) wins over a
    // stale service record when it's the more recent of the two — same
    // "freshest reading wins" comparison as fetchBestKnownKm below.
    try {
      final manualSnap =
          await (db ?? FirebaseFirestore.instance).collection('manual_km_logs').get();
      for (final doc in manualSnap.docs) {
        final data = doc.data();
        final vehicleNumber = (data['vehicleNumber'] ?? '').toString();
        if (!remaining.contains(vehicleNumber)) continue;
        final ts = data['enteredAt'];
        final millis = ts is Timestamp ? ts.millisecondsSinceEpoch : 0;
        if (millis >= (lastMillis[vehicleNumber] ?? -1)) {
          final km = (data['km'] as num?)?.toDouble();
          if (km != null) {
            lastMillis[vehicleNumber] = millis;
            lastKm[vehicleNumber] = km;
            lastSource[vehicleNumber] = 'manually entered — no GPS, may be stale';
          }
        }
      }
    } catch (e) {
      debugPrint('fetchKmByVehicleForAlerts: manual_km_logs fallback failed: $e');
    }
    for (final v in remaining) {
      final km = lastKm[v];
      result[v] = km != null
          ? (km: km, source: lastSource[v]!)
          : (km: null, source: 'unknown — no GPS and no service history yet');
    }
  }
  return result;
}

class ServiceAlertsData {
  final List<ServiceAlert> alerts;
  final DateTime computedAt;
  // Which source(s) failed this round (e.g. 'service_records',
  // 'defect_reports') — never includes a source that was simply not
  // fetched because this viewer's permissions didn't need it (that's a
  // scoping decision, not a failure). Empty means a clean, complete fetch.
  final List<String> failedSources;
  const ServiceAlertsData({
    required this.alerts,
    required this.computedAt,
    this.failedSources = const [],
  });
  bool get hasPartialData => failedSources.isNotEmpty;
}

String _serviceAlertsErrorCode(Object e) =>
    e is FirebaseException ? e.code : e.runtimeType.toString();

// The one place that gathers every collection RED ALERTS needs, normalizes
// Firestore Timestamp fields to plain DateTime (so the pure builders above
// never touch a Firestore type), and feeds them to
// computeServiceAlerts/serviceReturnedAlerts/etc.
//
// Every source is fetched independently with its own try/catch: a failing
// source is logged (debugPrint('[ALERTS] source <name> ERR <code>')),
// recorded in the returned failedSources list, and simply drops the
// alert(s) that need it rather than throwing and losing everything else.
// service_records is the one exception that needs care rather than just
// "substitute an empty list": computeServiceAlerts' milestone math treats
// an empty approvedRecords as "never serviced", which would FABRICATE
// false OVERDUE/MISSED alerts if the real reason the list is empty is a
// failed read, not an actual empty collection — so a failed
// service_records fetch suppresses computeServiceAlerts' output entirely
// instead of substituting an empty list for it.
//
// `canSeeMechanic`/`canSeeManagement` (the same flags
// filterServiceAlertsForUser uses) also SCOPE which sources are even
// attempted: defect_reports is mechanic-only data, daily_checks/
// truck_sessions are management-only, so a mechanic-only viewer's cold
// fetch never touches those collections at all. This narrows the live
// Firestore read surface each role actually needs (see the rule-needs
// list in this feature's report) and — combined with the per-uid cache —
// means an admin's broader fetch is never the one feeding a mechanic's
// alert list.
//
// Every query here is either a full-collection read (grouped client-side)
// or a single-field equality filter — no new composite indexes, same
// convention as the rest of this feature set.
Future<ServiceAlertsData> fetchServiceAlertsData({
  FirebaseFirestore? db,
  required bool canSeeMechanic,
  required bool canSeeManagement,
}) async {
  final firestore = db ?? FirebaseFirestore.instance;
  final now = DateTime.now();
  final failedSources = <String>[];

  void logFailure(String source, Object e) {
    final code = _serviceAlertsErrorCode(e);
    debugPrint('[ALERTS] source $source ERR $code');
    failedSources.add(source);
  }

  DateTime? toDate(Object? v) => v is Timestamp ? v.toDate() : (v is DateTime ? v : null);
  Map<String, dynamic> normalizeRecord(QueryDocumentSnapshot<Map<String, dynamic>> d) {
    final data = Map<String, dynamic>.from(d.data());
    data['id'] = d.id;
    data['serviceDate'] = toDate(data['serviceDate']);
    data['submittedAt'] = toDate(data['submittedAt']);
    data['returnedAt'] = toDate(data['returnedAt']);
    return data;
  }

  var vehicles = <Map<String, dynamic>>[];
  var vehicleNumbers = <String>[];
  try {
    final trucksSnap = await firestore.collection('trucks').get();
    vehicles = trucksSnap.docs.map((d) => d.data()).toList();
    vehicleNumbers = vehicles
        .map((v) => (v['truckNumber'] ?? '').toString())
        .where((v) => v.isNotEmpty)
        .toList();
  } catch (e) {
    logFailure('trucks', e);
  }

  var schedules = <Map<String, dynamic>>[];
  try {
    final itemsSnap = await firestore.collection('service_items').get();
    schedules = itemsSnap.docs.map((d) {
      final data = Map<String, dynamic>.from(d.data());
      data['id'] = d.id;
      return data;
    }).toList();
  } catch (e) {
    logFailure('service_items', e);
  }

  // All three slices are fetched unconditionally now — SERVICE_DUE's
  // PROVISIONAL logic (computeScheduleStatus) needs to know about pending
  // SUBMITTED and not-yet-resubmitted RETURNED records to compute the
  // right status for EVERY qualifying viewer, not just the audience that
  // separately sees the serviceReturnedAlerts/serviceSubmittedPendingAlerts
  // alert kinds (those two stay audience-gated below; only the underlying
  // read is now unconditional).
  var approvedRecords = <Map<String, dynamic>>[];
  var returnedRecords = <Map<String, dynamic>>[];
  var submittedRecords = <Map<String, dynamic>>[];
  var serviceRecordsOk = true;
  try {
    final approvedSnap = await firestore
        .collection('service_records')
        .where('status', isEqualTo: ServiceRecordStatus.approved)
        .get();
    approvedRecords = approvedSnap.docs.map(normalizeRecord).toList();
    final returnedSnap = await firestore
        .collection('service_records')
        .where('status', isEqualTo: ServiceRecordStatus.returned)
        .get();
    returnedRecords = returnedSnap.docs.map(normalizeRecord).toList();
    final submittedSnap = await firestore
        .collection('service_records')
        .where('status', isEqualTo: ServiceRecordStatus.submitted)
        .get();
    submittedRecords = submittedSnap.docs.map(normalizeRecord).toList();
  } catch (e) {
    logFailure('service_records', e);
    serviceRecordsOk = false;
  }

  var kmByVehicle = <String, ({double? km, String source})>{};
  try {
    kmByVehicle = await fetchKmByVehicleForAlerts(
      vehicleNumbers: vehicleNumbers,
      db: firestore,
      // Already-read records are reused when available; on a failed
      // service_records fetch, passing an empty (not null) list stops
      // this from retrying the same doomed read a second time internally.
      serviceRecords: serviceRecordsOk
          ? [...approvedRecords, ...returnedRecords, ...submittedRecords]
          : const [],
      onGpsBatchError: (e) => logFailure('gps_km', e),
    );
  } catch (e) {
    // fetchKmByVehicleForAlerts never actually throws (both its internal
    // paths catch their own errors) — this is defense in depth only.
    logFailure('gps_km', e);
  }

  var openDefects = <Map<String, dynamic>>[];
  if (canSeeMechanic) {
    try {
      final defectsSnap =
          await firestore.collection('defect_reports').where('status', isEqualTo: 'OPEN').get();
      openDefects = defectsSnap.docs.map((d) {
        final data = Map<String, dynamic>.from(d.data());
        data['id'] = d.id;
        data['reportedAt'] = toDate(data['reportedAt']);
        return data;
      }).toList();
    } catch (e) {
      logFailure('defect_reports', e);
    }
  }

  final todayKey = dailyCheckDateKey(now);
  var dailyChecks = <Map<String, dynamic>>[];
  var dailyChecksOk = false;
  if (canSeeManagement) {
    try {
      final checksSnap =
          await firestore.collection('daily_checks').where('date', isEqualTo: todayKey).get();
      dailyChecks = checksSnap.docs.map((d) {
        final data = Map<String, dynamic>.from(d.data());
        data['id'] = d.id;
        return data;
      }).toList();
      dailyChecksOk = true;
    } catch (e) {
      logFailure('daily_checks', e);
    }
  }

  // "Not checked today" needs BOTH collections to mean anything — if
  // either failed (or isn't needed for this viewer), it's simply not
  // computed rather than computed from half the data.
  var notChecked = <({String vehicleNumber, String driverName})>[];
  if (canSeeManagement && dailyChecksOk) {
    try {
      final sessionsSnap = await firestore
          .collection('truck_sessions')
          .where('date', isEqualTo: todayKey)
          .where('status', isEqualTo: 'active')
          .get();
      final activeByTruck = <String, String>{};
      for (final d in sessionsSnap.docs) {
        final data = d.data();
        final truckNumber = normalizeVehicleNumber((data['truckNumber'] ?? '').toString());
        if (truckNumber.isEmpty) continue;
        activeByTruck[truckNumber] = (data['driverName'] ?? '').toString();
      }
      final checkedVehicleNumbers = dailyChecks
          .map((c) => normalizeVehicleNumber((c['vehicleNumber'] ?? '').toString()))
          .toSet();
      notChecked = activeByTruck.entries
          .where((e) => !checkedVehicleNumbers.contains(e.key))
          .map((e) => (vehicleNumber: e.key, driverName: e.value))
          .toList();
    } catch (e) {
      logFailure('truck_sessions', e);
    }
  }

  final alerts = <ServiceAlert>[
    if (serviceRecordsOk)
      ...computeServiceAlerts(
        vehicles: vehicles,
        schedules: schedules,
        approvedRecords: approvedRecords,
        submittedRecords: submittedRecords,
        returnedRecords: returnedRecords,
        kmByVehicle: kmByVehicle,
        now: now,
      ),
    if (canSeeMechanic) ...serviceReturnedAlerts(returnedRecords),
    // Excludes a viewer who also canSeeManagement (admin/owner, or anyone
    // holding SERVICE_APPROVE/SERVICE_VIEW) — they already get the
    // management alert on the same records below, and a viewer who
    // qualifies for both audiences at once must never see the same
    // submitted record presented as two separate alert cards.
    if (canSeeMechanic && !canSeeManagement) ...serviceAwaitingApprovalAlerts(submittedRecords),
    if (canSeeManagement) ...serviceSubmittedPendingAlerts(submittedRecords, now: now),
    if (canSeeMechanic) ...defectPendingAlerts(openDefects, now: now),
    if (canSeeManagement) ...dailyCheckLowAlerts(dailyChecks),
    if (canSeeManagement) ...dailyCheckNotDoneAlerts(notChecked),
  ];
  return ServiceAlertsData(alerts: alerts, computedAt: now, failedSources: failedSources);
}

// Shared, single-listener cache for small reference collections (sites,
// trucks, machines, bikes) that dozens of unrelated widgets each display
// — previously every one of those widgets opened its own independent
// FirebaseFirestore.instance.collection(name).snapshots() listener for the
// identical unfiltered query, meaning the SAME small collection was
// streamed live by ~25 (sites) / ~15 (trucks) / ~10 (machines) / a couple
// (bikes) separate Firestore listeners at once. This keeps exactly ONE
// real listener per collection name, shared (Firestore's own
// Stream<QuerySnapshot> is already broadcast-capable — multiple
// StreamBuilders can subscribe to the SAME Stream object) across every
// caller. These collections are small and rarely change, so there's no
// TTL — it's a live stream, same up-to-the-second behavior every caller
// already had; forceRefresh (a RETRY button) drops the cached Stream so
// the next call opens a fresh listener instead of continuing to reuse one
// stuck in an error state. NEVER use this for a FILTERED query (.where/
// .orderBy/.limit) — those must stay their own, independent query exactly
// as before.
// One upstream subscription shared by every listener; a new listener first
// gets the latest event (data or error), then live updates. When the last
// listener cancels, the upstream listen stops and the cached event is
// dropped, so the next listener starts fresh (same lifetime as before).
class ReplayLatestStream<T> {
  ReplayLatestStream(this._source);

  final Stream<T> _source;
  final Set<MultiStreamController<T>> _listeners = {};
  StreamSubscription<T>? _sub;
  bool _hasLatest = false;
  T? _latest;
  Object? _latestError;
  StackTrace? _latestStack;

  late final Stream<T> stream = Stream<T>.multi(_onListen, isBroadcast: true);

  void _onListen(MultiStreamController<T> c) {
    if (_hasLatest) {
      if (_latestError != null) {
        c.addError(_latestError!, _latestStack);
      } else {
        c.add(_latest as T);
      }
    }
    _listeners.add(c);
    _sub ??= _source.listen(
      (v) {
        _hasLatest = true;
        _latest = v;
        _latestError = null;
        _latestStack = null;
        for (final l in [..._listeners]) {
          l.add(v);
        }
      },
      onError: (Object e, StackTrace st) {
        _hasLatest = true;
        _latestError = e;
        _latestStack = st;
        for (final l in [..._listeners]) {
          l.addError(e, st);
        }
      },
      onDone: () {
        for (final l in [..._listeners]) {
          l.close();
        }
        _listeners.clear();
        _reset();
      },
    );
    c.onCancel = () {
      _listeners.remove(c);
      if (_listeners.isEmpty) {
        _sub?.cancel();
        _reset();
      }
    };
  }

  void _reset() {
    _sub = null;
    _hasLatest = false;
    _latest = null;
    _latestError = null;
    _latestStack = null;
  }
}

class ReferenceCollectionCache {
  ReferenceCollectionCache._();

  static final Map<String, Stream<QuerySnapshot<Map<String, dynamic>>>> _streams = {};

  static Stream<QuerySnapshot<Map<String, dynamic>>> stream(
    String collectionName, {
    FirebaseFirestore? db,
    bool forceRefresh = false,
  }) {
    final firestore = db ?? FirebaseFirestore.instance;
    // Keyed by db identity too, not just the collection name: every
    // production call site omits `db` and so always shares one real
    // FirebaseFirestore.instance entry, exactly as intended — but a
    // widget test that passes its own FakeFirebaseFirestore must NOT
    // collide with another test's (or production's) cached stream for
    // the same collection name.
    final key = '$collectionName::${identityHashCode(firestore)}';
    if (forceRefresh) _streams.remove(key);
    // Wrapped so a widget that subscribes while another one is ALREADY
    // listening still gets the current snapshot at once. Firestore's
    // snapshots() is a broadcast stream with no replay: a late subscriber
    // used to get nothing until the next change — e.g. Live Tracking's
    // Vehicle Speed picker never received `trucks` because the Trucks
    // sidebar was still subscribed when the picker replaced it.
    return _streams.putIfAbsent(
      key,
      () => ReplayLatestStream(firestore.collection(collectionName).snapshots()).stream,
    );
  }

  // Test-only — this cache is process-global, not scoped per test, same
  // convention as ServiceAlertsCache.reset()/VehicleKmCache.reset().
  @visibleForTesting
  static void reset() {
    _streams.clear();
  }
}

// ---------------- USER DIRECTORY (uid -> display name) ----------------
// "Who did it" columns (Reported / Worked / Approved / Recorded by) need a
// name for records that only store a uid. Every table resolves those from
// ONE shared users listener (ReferenceCollectionCache — the same single
// live stream any other screen showing users already reuses), never a
// read per row. If rules deny the users collection the directory is just
// empty: every uid-only field shows "-" (logged once), nothing is guessed.
String resolvePersonName({
  String? storedName,
  String? uid,
  Map<String, String> namesByUid = const {},
}) {
  final stored = (storedName ?? '').trim();
  if (stored.isNotEmpty) return stored;
  final id = (uid ?? '').trim();
  if (id.isEmpty) return '-';
  final name = (namesByUid[id] ?? '').trim();
  return name.isEmpty ? '-' : name;
}

class UserDirectory {
  UserDirectory._(this._db);

  final FirebaseFirestore _db;
  final ValueNotifier<int> version = ValueNotifier(0);
  Map<String, String> _names = const {};
  bool denied = false;
  StreamSubscription<QuerySnapshot<Map<String, dynamic>>>? _sub;

  static final Map<int, UserDirectory> _byDb = {};

  // One directory (one listener) per Firestore instance — production only
  // ever has the one; tests' FakeFirebaseFirestore instances stay separate.
  static UserDirectory of({FirebaseFirestore? db}) {
    final firestore = db ?? FirebaseFirestore.instance;
    return _byDb.putIfAbsent(identityHashCode(firestore), () => UserDirectory._(firestore).._listen());
  }

  Map<String, String> get namesByUid => _names;

  void _listen() {
    _sub = ReferenceCollectionCache.stream('users', db: _db).listen(
      (snap) {
        _names = {
          for (final d in snap.docs)
            if ((d.data()['name'] ?? '').toString().trim().isNotEmpty)
              d.id: (d.data()['name'] ?? '').toString().trim(),
        };
        version.value++;
      },
      onError: (Object e) {
        if (!denied) {
          debugPrint(
            '[USERS] users collection not readable for name lookups ($e) — '
            'uid-only "who" fields will show "-". Logged once.',
          );
        }
        denied = true;
        version.value++;
      },
    );
  }

  String nameOf(String? uid, {String? storedName}) =>
      resolvePersonName(storedName: storedName, uid: uid, namesByUid: _names);

  @visibleForTesting
  static void reset() {
    for (final d in _byDb.values) {
      d._sub?.cancel();
    }
    _byDb.clear();
  }
}

// "Name (role)" of whoever is exporting — ONE doc read at export time
// (the user's own users/{uid}, which every signed-in user can already
// read for their permission checks). "-" when unknown.
Future<String> currentUserExportLabel({FirebaseFirestore? db, String? uid}) async {
  final id = uid ?? FirebaseAuth.instance.currentUser?.uid;
  if (id == null) return '-';
  try {
    final doc = await (db ?? FirebaseFirestore.instance).collection('users').doc(id).get();
    final name = (doc.data()?['name'] ?? '').toString().trim();
    final role = (doc.data()?['role'] ?? '').toString().trim();
    if (name.isEmpty) return '-';
    return role.isEmpty ? name : '$name ($role)';
  } catch (e) {
    debugPrint('currentUserExportLabel: $e');
    return '-';
  }
}

// Active-filter lines for an export header — only the filters that are
// actually narrowing the table are listed.
List<String> describeTableFilters({
  String? statusLabel,
  String? search,
  Map<String, String> extra = const {},
}) {
  return [
    if (statusLabel != null && statusLabel.isNotEmpty && statusLabel != 'ALL') 'Status: $statusLabel',
    if ((search ?? '').trim().isNotEmpty) 'Search: "${search!.trim()}"',
    for (final e in extra.entries)
      if (e.value.isNotEmpty) '${e.key}: ${e.value}',
  ];
}

// The one export entry point every table's EXPORT menu calls. Exports
// exactly what the table holds right now: every filtered row (all pages,
// not just the visible 25) in the on-screen sort.
Future<void> exportDataTable<T>(
  BuildContext context, {
  required String format,
  required DataTableController<T> controller,
  required String title,
  List<String> filters = const [],
  FirebaseFirestore? db,
  String? uid,
}) async {
  final messenger = ScaffoldMessenger.maybeOf(context);
  if (!controller.isAttached) {
    messenger?.showSnackBar(const SnackBar(content: Text('Nothing to export yet.')));
    return;
  }
  try {
    final by = await currentUserExportLabel(db: db, uid: uid);
    final export = buildTableExport<T>(
      title: title,
      columns: controller.columns,
      rows: controller.sortedRows,
      generatedBy: by,
      filters: filters,
      sortDescription: controller.sortDescription,
    );
    if (format == DataTableToolbar.exportPdf) {
      await exportTablePdf(export);
    } else {
      await exportTablePng(export);
    }
  } catch (e) {
    debugPrint('exportDataTable($title): $e');
    messenger?.showSnackBar(SnackBar(content: Text('Export failed: $e')));
  }
}

// Per-user cache (keyed by uid) so navigating between the bell badge, the
// ALERTS screen, the hub banner and the management dashboard banner
// doesn't each independently re-run the ~76-truck fleet computation (and
// its Traccar calls) — within one signed-in user's session they all share
// one entry. Keying by uid (rather than one shared app-wide entry) means
// an admin's broader cold fetch is never what feeds a mechanic's narrower
// alert list, or vice versa — each uid's entry is fetched fresh under
// that uid's own canSeeMechanic/canSeeManagement scope. Refreshes
// automatically every 5 minutes and on demand via forceRefresh
// (pull-to-refresh); concurrent callers for the SAME uid during a cold
// fetch share the same in-flight Future rather than each starting their
// own.
class ServiceAlertsCache {
  ServiceAlertsCache._();

  static const refreshInterval = Duration(minutes: 5);
  static final Map<String, ServiceAlertsData> _dataByUid = {};
  static final Map<String, DateTime> _fetchedAtByUid = {};
  static final Map<String, Future<ServiceAlertsData>> _inFlightByUid = {};

  static Future<ServiceAlertsData> get({
    required String uidKey,
    required bool canSeeMechanic,
    required bool canSeeManagement,
    FirebaseFirestore? db,
    bool forceRefresh = false,
  }) {
    final cachedData = _dataByUid[uidKey];
    final fetchedAt = _fetchedAtByUid[uidKey];
    final isFresh = !forceRefresh &&
        cachedData != null &&
        fetchedAt != null &&
        DateTime.now().difference(fetchedAt) < refreshInterval;
    if (isFresh) return Future.value(cachedData);
    final inFlight = _inFlightByUid[uidKey];
    if (inFlight != null && !forceRefresh) return inFlight;
    final future = fetchServiceAlertsData(
      db: db,
      canSeeMechanic: canSeeMechanic,
      canSeeManagement: canSeeManagement,
    ).then((data) {
      _dataByUid[uidKey] = data;
      _fetchedAtByUid[uidKey] = DateTime.now();
      _inFlightByUid.remove(uidKey);
      return data;
    }, onError: (Object e, StackTrace st) {
      _inFlightByUid.remove(uidKey);
      throw e;
    });
    _inFlightByUid[uidKey] = future;
    return future;
  }

  // Test-only — each widget test needs a clean slate since this cache is
  // process-global, not scoped to a FakeFirebaseFirestore instance.
  @visibleForTesting
  static void reset() {
    _dataByUid.clear();
    _fetchedAtByUid.clear();
    _inFlightByUid.clear();
  }
}

Color _serviceAlertSeverityColor(String severity) {
  switch (severity) {
    case ServiceAlertSeverity.missed:
      return const Color(0xFF7F1D1D); // dark red
    case ServiceAlertSeverity.overdue:
      return AppColors.danger;
    case ServiceAlertSeverity.dueSoon:
    case ServiceAlertSeverity.kmUnknown:
      return AppColors.warning;
    default:
      return AppColors.textSecondary;
  }
}

String _serviceAlertSeverityLabel(String severity) {
  switch (severity) {
    case ServiceAlertSeverity.missed:
      return 'MISSED';
    case ServiceAlertSeverity.overdue:
      return 'OVERDUE';
    case ServiceAlertSeverity.dueSoon:
      return 'DUE SOON';
    case ServiceAlertSeverity.kmUnknown:
      return 'KM UNKNOWN';
    default:
      return 'OTHER';
  }
}

// Current signed-in user's role/perm flags, fetched once per screen —
// shared by the bell badge, the banners and the hub tile badges so they
// all filter the SAME cached alert list identically. `qualifies` is the
// bell/banner's own visibility gate ("every user who has SERVICE_DO,
// SERVICE_APPROVE, SERVICE_VIEW, DIAGNOSE or admin/owner") — distinct from
// `alerts` being merely empty, since a qualifying user with zero alerts
// should still see the bell (no badge), not have it disappear.
// `hasPartialData` surfaces fetchServiceAlertsData's failedSources as a
// single flag for the ALERTS screen's "some alerts unavailable" note.
// Non-qualifying users never touch ServiceAlertsCache at all — not even a
// cache miss — since there's nothing for them to see.
Future<({bool qualifies, List<ServiceAlert> alerts, bool hasPartialData, bool canDoService})>
    _loadAlertsForCurrentUser({
  FirebaseFirestore? db,
  String? uid,
  bool forceRefresh = false,
}) async {
  final firestore = db ?? FirebaseFirestore.instance;
  Map<String, dynamic>? userData;
  if (uid != null) {
    final doc = await firestore.collection('users').doc(uid).get();
    userData = doc.data();
  }
  final role = userData?['role'] as String?;
  final isAdminOrOwner = role == 'admin' || role == 'owner';
  final hasServiceDo = hasRepairPerm(userData, kPermServiceDo);
  final hasServiceApprove = hasRepairPerm(userData, kPermServiceApprove);
  final hasServiceView = hasRepairPerm(userData, kPermServiceView);
  final hasDiagnose = hasRepairPerm(userData, kPermDiagnose);
  final canSeeMechanic = isAdminOrOwner || hasServiceDo || hasDiagnose;
  final canSeeManagement = isAdminOrOwner || hasServiceApprove || hasServiceView;
  final qualifies = canSeeMechanic || canSeeManagement;
  if (!qualifies) {
    return (
      qualifies: false,
      alerts: const <ServiceAlert>[],
      hasPartialData: false,
      canDoService: false,
    );
  }
  final data = await ServiceAlertsCache.get(
    uidKey: uid ?? 'anon',
    canSeeMechanic: canSeeMechanic,
    canSeeManagement: canSeeManagement,
    db: firestore,
    forceRefresh: forceRefresh,
  );
  // Redundant with fetchServiceAlertsData's own scoping in practice (a
  // user's cache entry only ever contains what their own scope fetched)
  // — kept as a defense-in-depth safety net, and because it's the
  // directly-unit-tested audience/permission gate.
  final alerts = filterServiceAlertsForUser(
    data.alerts,
    isAdminOrOwner: isAdminOrOwner,
    hasServiceDo: hasServiceDo,
    hasServiceApprove: hasServiceApprove,
    hasServiceView: hasServiceView,
    hasDiagnose: hasDiagnose,
  );
  return (
    qualifies: true,
    alerts: alerts,
    hasPartialData: data.hasPartialData,
    canDoService: hasServiceDo,
  );
}

// Small SERVICE: <severity> chip for one vehicle's row in any list (Garage
// trucks, vehicle pickers) — reuses whichever already-fetched
// _loadAlertsForCurrentUser() future the parent screen fetched once for
// its whole list, never issuing its own Firestore read. Renders nothing
// while loading, on error, or when the vehicle has no outstanding
// serviceDue alert (green).
class _ServiceDueRowChip extends StatelessWidget {
  final Future<({bool qualifies, List<ServiceAlert> alerts, bool hasPartialData, bool canDoService})>
      alertsFuture;
  final String vehicleNumber;
  const _ServiceDueRowChip({required this.alertsFuture, required this.vehicleNumber});

  @override
  Widget build(BuildContext context) {
    return FutureBuilder(
      future: alertsFuture,
      builder: (context, snap) {
        if (snap.connectionState != ConnectionState.done || snap.data == null) {
          return const SizedBox.shrink();
        }
        final alert = worstServiceDueAlertFor(snap.data!.alerts, vehicleNumber);
        if (alert == null) return const SizedBox.shrink();
        final color = _serviceAlertSeverityColor(alert.severity);
        final label = _serviceAlertSeverityLabel(alert.severity);
        return Container(
          margin: const EdgeInsets.only(top: 4),
          padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
          decoration: BoxDecoration(
            color: color.withOpacity(0.15),
            borderRadius: BorderRadius.circular(AppRadius.chip),
          ),
          child: Text(
            'SERVICE: $label',
            style: TextStyle(color: color, fontSize: 10, fontWeight: FontWeight.bold),
          ),
        );
      },
    );
  }
}

// Bell icon + red count badge — shown in the app bar of every screen whose
