// Red "N vehicles overdue for service" banner — SERVICE_DUE alerts at
// OVERDUE/MISSED severity only (DUE_SOON/KM_UNKNOWN and the "others"
// bucket don't belong in a banner meant to read as urgent). Shown atop
// TruckRepairHubScreen and ManagementDashboard. Also fires the
// once-per-device-per-day summary SnackBar the first time either of those
// screens builds with alerts present.
class ServiceAlertsBanner extends StatefulWidget {
  final FirebaseFirestore? firestoreOverride;
  final String? currentUidOverride;
  const ServiceAlertsBanner({super.key, this.firestoreOverride, this.currentUidOverride});

  @override
  State<ServiceAlertsBanner> createState() => _ServiceAlertsBannerState();
}

class _ServiceAlertsBannerState extends State<ServiceAlertsBanner> {
  FirebaseFirestore get _db => widget.firestoreOverride ?? FirebaseFirestore.instance;
  String? get _uid => widget.currentUidOverride ?? FirebaseAuth.instance.currentUser?.uid;
  late final Future<({bool qualifies, List<ServiceAlert> alerts, bool hasPartialData, bool canDoService})> _future =
      _loadAlertsForCurrentUser(db: _db, uid: _uid);

  static const _lastShownPrefsKey = 'service_alerts_daily_summary_last_shown';

  Future<void> _maybeShowDailySummary(List<ServiceAlert> alerts) async {
    if (alerts.isEmpty) return;
    try {
      final prefs = await SharedPreferences.getInstance();
      final todayKey = dailyCheckDateKey(DateTime.now());
      if (prefs.getString(_lastShownPrefsKey) == todayKey) return;
      await prefs.setString(_lastShownPrefsKey, todayKey);
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('${alerts.length} alert(s) need attention today.'),
            duration: const Duration(seconds: 4),
          ),
        );
      }
    } catch (e) {
      debugPrint('ServiceAlertsBanner: daily summary snackbar failed: $e');
    }
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<({bool qualifies, List<ServiceAlert> alerts, bool hasPartialData, bool canDoService})>(
      future: _future,
      builder: (context, snap) {
        final alerts = snap.data?.alerts ?? const [];
        final overdueCount = alerts
            .where((a) =>
                a.kind == ServiceAlertKind.serviceDue &&
                (a.severity == ServiceAlertSeverity.overdue ||
                    a.severity == ServiceAlertSeverity.missed))
            .map((a) => a.vehicleNumber)
            .toSet()
            .length;
        if (snap.connectionState == ConnectionState.done) {
          WidgetsBinding.instance.addPostFrameCallback((_) {
            if (mounted) _maybeShowDailySummary(alerts);
          });
        }
        if (overdueCount == 0) return const SizedBox.shrink();
        return Padding(
          padding: const EdgeInsets.only(bottom: AppSpacing.md),
          child: GestureDetector(
            onTap: () => pushWebAware(
              context,
              ServiceAlertsScreen(
                firestoreOverride: widget.firestoreOverride,
                currentUidOverride: widget.currentUidOverride,
              ),
            ),
            child: Container(
              width: double.infinity,
              padding: const EdgeInsets.symmetric(horizontal: AppSpacing.md, vertical: AppSpacing.sm),
              decoration: BoxDecoration(
                color: AppColors.danger,
                borderRadius: BorderRadius.circular(AppRadius.card),
              ),
              child: Row(
                children: [
                  const Icon(Icons.warning_amber_rounded, color: Colors.white, size: 20),
                  const SizedBox(width: AppSpacing.sm),
                  Expanded(
                    child: Text(
                      '$overdueCount vehicle(s) overdue for service — tap to view',
                      style: const TextStyle(color: Colors.white, fontWeight: FontWeight.bold),
                    ),
                  ),
                  const Icon(Icons.chevron_right, color: Colors.white),
                ],
              ),
            ),
          ),
        );
      },
    );
  }
}

// Technician's manual "log today's odometer" entry — the fallback
// current-km source when GPS/Traccar is unavailable (see
// fetchBestKnownKm/fetchKmByVehicleForAlerts above). Append-only: never
// overwrites a previous entry, so there's always a dated history to pick
// the freshest reading from.
Future<void> logManualKm({
  required FirebaseFirestore db,
  required String vehicleNumber,
  required double km,
  required String uid,
  required String userName,
}) {
  return db.collection('manual_km_logs').doc().set({
    'vehicleNumber': vehicleNumber,
    'km': km,
    'enteredAt': FieldValue.serverTimestamp(),
    'enteredBy': uid,
    'enteredByName': userName,
  });
}

// Lightweight "I don't have GPS, here's today's odometer" entry point —
// opened from a KM_UNKNOWN alert's ENTER KM button (ServiceAlertsScreen's
// _actionButton below), so a technician never has to fill out a full
// ServiceRecordFormScreen (checklist + garage + price all required) just
// to log one number. Returns true once a km value has actually been
// saved, so the caller can refresh whatever alert/status it was showing.
Future<bool> showManualKmEntryDialog(
  BuildContext context, {
  required String vehicleNumber,
  FirebaseFirestore? firestoreOverride,
  String? currentUidOverride,
}) async {
  final controller = TextEditingController();
  final saved = await showDialog<bool>(
    context: context,
    builder: (dialogContext) => AlertDialog(
      title: Text('Enter Current KM — $vehicleNumber'),
      content: TextField(
        controller: controller,
        keyboardType: TextInputType.number,
        autofocus: true,
        decoration: const InputDecoration(labelText: 'Current odometer (km)'),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.pop(dialogContext, false),
          child: const Text('Cancel'),
        ),
        ElevatedButton(
          onPressed: () async {
            final km = double.tryParse(controller.text.trim());
            if (km == null) {
              ScaffoldMessenger.of(dialogContext).showSnackBar(
                const SnackBar(content: Text('Enter a valid number.')),
              );
              return;
            }
            final db = firestoreOverride ?? FirebaseFirestore.instance;
            final uid = currentUidOverride ?? FirebaseAuth.instance.currentUser?.uid ?? '';
            final userDoc = await db.collection('users').doc(uid).get();
            final userName = (userDoc.data()?['name'] ?? 'Unknown').toString();
            await logManualKm(
              db: db,
              vehicleNumber: vehicleNumber,
              km: km,
              uid: uid,
              userName: userName,
            );
            if (dialogContext.mounted) Navigator.pop(dialogContext, true);
          },
          child: const Text('SAVE'),
        ),
      ],
    ),
  );
  return saved ?? false;
}

// ---------------- RED ALERTS screen ----------------
class ServiceAlertsScreen extends StatefulWidget {
  final FirebaseFirestore? firestoreOverride;
  final String? currentUidOverride;
  const ServiceAlertsScreen({super.key, this.firestoreOverride, this.currentUidOverride});

  @override
  State<ServiceAlertsScreen> createState() => _ServiceAlertsScreenState();
}

class _ServiceAlertsScreenState extends State<ServiceAlertsScreen> {
  FirebaseFirestore get _db => widget.firestoreOverride ?? FirebaseFirestore.instance;
  String? get _uid => widget.currentUidOverride ?? FirebaseAuth.instance.currentUser?.uid;

  bool _loading = true;
  Object? _loadError;
  bool _canDoService = false;
  bool _hasPartialData = false;
  List<ServiceAlert> _alerts = const [];
  final _searchController = TextEditingController();
  String _search = '';
  String _filter = kServiceTableFilterAll;
  final _table = DataTableController<ServiceAlert>();
  late final UserDirectory _users = UserDirectory.of(db: widget.firestoreOverride);

  void _onUsersChanged() {
    if (mounted) setState(() {});
  }

  // Due date when the alert has one, else the last service / submit date.
  static DateTime? _alertDate(ServiceAlert a) => a.dueDate ?? a.lastServiceDate;
  static String _alertDateText(ServiceAlert a) => _alertDate(a) == null
      ? '-'
      : '${formatTableDate(_alertDate(a))}${a.dueDate != null ? ' (due)' : ''}';
  String _servicedBy(ServiceAlert a) => resolvePersonName(storedName: a.lastGarageName);
  String _recordedBy(ServiceAlert a) =>
      _users.nameOf(a.lastSubmitterUid, storedName: a.lastSubmitterName);
  String _approvedBy(ServiceAlert a) =>
      _users.nameOf(a.lastApproverUid, storedName: a.lastApproverName);
  static String _kmText(ServiceAlert a) => a.kind != ServiceAlertKind.serviceDue
      ? '-'
      : (a.currentKm == null ? 'unknown' : _fmtKm(a.currentKm));

  @override
  void initState() {
    super.initState();
    _users.version.addListener(_onUsersChanged);
    _load();
  }

  @override
  void dispose() {
    _users.version.removeListener(_onUsersChanged);
    _searchController.dispose();
    super.dispose();
  }

  Future<void> _load({bool forceRefresh = false}) async {
    setState(() {
      _loading = true;
      _loadError = null;
    });
    try {
      final result = await _loadAlertsForCurrentUser(
        db: _db,
        uid: _uid,
        forceRefresh: forceRefresh,
      );
      if (mounted) {
        setState(() {
          _alerts = result.alerts;
          _canDoService = result.canDoService;
          _hasPartialData = result.hasPartialData;
          _loading = false;
        });
      }
    } catch (e) {
      debugPrint('ServiceAlertsScreen: load error: $e');
      if (mounted) {
        setState(() {
          _loadError = e;
          _loading = false;
        });
      }
    }
  }

  // Filter bucket for one alert — same grouping the old card sections
  // used: MISSED+OVERDUE, DUE SOON+KM UNKNOWN, everything else OTHER.
  static String _bucket(ServiceAlert a) {
    switch (a.severity) {
      case ServiceAlertSeverity.missed:
      case ServiceAlertSeverity.overdue:
        return ServiceAlertSeverity.overdue;
      case ServiceAlertSeverity.dueSoon:
      case ServiceAlertSeverity.kmUnknown:
        return ServiceAlertSeverity.dueSoon;
      default:
        return ServiceAlertSeverity.info;
    }
  }

  static const Map<String, int> _bucketRank = {
    ServiceAlertSeverity.overdue: 0,
    ServiceAlertSeverity.dueSoon: 1,
    ServiceAlertSeverity.info: 2,
  };

  // Default sort: OVERDUE (MISSED first within it), DUE SOON, OTHER; then
  // vehicle number.
  static int _compareBySeverity(ServiceAlert a, ServiceAlert b) {
    final r = (_bucketRank[_bucket(a)] ?? 9).compareTo(_bucketRank[_bucket(b)] ?? 9);
    if (r != 0) return r;
    final s = (_kServiceAlertSeverityRank[a.severity] ?? 9)
        .compareTo(_kServiceAlertSeverityRank[b.severity] ?? 9);
    if (s != 0) return s;
    return a.vehicleNumber.compareTo(b.vehicleNumber);
  }

  List<ServiceAlert> get _searched {
    final q = _search.trim().toUpperCase();
    return q.isEmpty
        ? _alerts
        : _alerts.where((a) => a.vehicleNumber.toUpperCase().contains(q)).toList();
  }

  Widget? _actionButton(ServiceAlert a) {
    switch (a.kind) {
      case ServiceAlertKind.serviceDue:
        // KM_UNKNOWN never opens the full service form (checklist/garage/
        // price) just to log one number — a lightweight manual entry
        // instead, same permission boundary as DO SERVICE below.
        if (_canDoService && a.severity == ServiceAlertSeverity.kmUnknown) {
          return ElevatedButton(
            style: _kTableButtonStyle,
            onPressed: () async {
              final saved = await showManualKmEntryDialog(
                context,
                vehicleNumber: a.vehicleNumber,
                firestoreOverride: widget.firestoreOverride,
                currentUidOverride: widget.currentUidOverride,
              );
              if (saved) _load(forceRefresh: true);
            },
            child: const Text('ENTER KM'),
          );
        }
        if (_canDoService) {
          return ElevatedButton(
            style: _kTableButtonStyle,
            onPressed: () => pushWebAware(
              context,
              ServiceRecordFormScreen(
                vehicleNumber: a.vehicleNumber,
                preselectScheduleId: a.scheduleId,
                firestoreOverride: widget.firestoreOverride,
                currentUidOverride: widget.currentUidOverride,
              ),
            ),
            child: const Text('DO SERVICE'),
          );
        }
        return OutlinedButton(
          style: _kTableButtonStyle,
          onPressed: () => pushWebAware(
            context,
            VehicleServiceHistoryScreen(
              vehicleNumber: a.vehicleNumber,
              firestoreOverride: widget.firestoreOverride,
              currentUidOverride: widget.currentUidOverride,
            ),
          ),
          child: const Text('VIEW'),
        );
      case ServiceAlertKind.serviceReturned:
        return ElevatedButton(
          style: _kTableButtonStyle,
          onPressed: () => pushWebAware(
            context,
            ServiceRecordFormScreen(
              recordId: a.recordId,
              firestoreOverride: widget.firestoreOverride,
              currentUidOverride: widget.currentUidOverride,
            ),
          ),
          child: const Text('DO SERVICE'),
        );
      case ServiceAlertKind.serviceSubmittedPending:
        return OutlinedButton(
          style: _kTableButtonStyle,
          onPressed: () => pushWebAware(
            context,
            ServiceApprovalDetailScreen(
              recordId: a.recordId ?? '',
              firestoreOverride: widget.firestoreOverride,
              currentUidOverride: widget.currentUidOverride,
            ),
          ),
          child: const Text('APPROVE'),
        );
      case ServiceAlertKind.defectPending:
        return OutlinedButton(
          style: _kTableButtonStyle,
          onPressed: () => pushWebAware(context, const NewRepairsInboxScreen()),
          child: const Text('VIEW'),
        );
      case ServiceAlertKind.dailyCheckLow:
      case ServiceAlertKind.dailyCheckNotDone:
        return OutlinedButton(
          style: _kTableButtonStyle,
          onPressed: () => pushWebAware(
            context,
            DailyChecksScreen(
              firestoreOverride: widget.firestoreOverride,
              currentUidOverride: widget.currentUidOverride,
            ),
          ),
          child: const Text('VIEW'),
        );
    }
    return null;
  }

  Widget _alertsTable() {
    final searched = _searched;
    final rows = _filter == kServiceTableFilterAll
        ? searched
        : searched.where((a) => _bucket(a) == _filter).toList();
    int count(String b) => searched.where((a) => _bucket(a) == b).length;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        DataTableToolbar(
          searchController: _searchController,
          onSearchChanged: (v) => setState(() => _search = v),
          onExport: (f) => exportDataTable<ServiceAlert>(
            context,
            format: f,
            controller: _table,
            title: 'Service Alerts',
            filters: describeTableFilters(
              statusLabel: _filter == ServiceAlertSeverity.info ? 'OTHER' : _filter.replaceAll('_', ' '),
              search: _search,
            ),
            db: widget.firestoreOverride,
            uid: widget.currentUidOverride,
          ),
          selectedFilter: _filter,
          onFilterChanged: (v) => setState(() => _filter = v),
          filters: [
            DataTableFilterOption(
                value: kServiceTableFilterAll, label: 'ALL', count: searched.length),
            DataTableFilterOption(
              value: ServiceAlertSeverity.overdue,
              label: 'OVERDUE',
              count: count(ServiceAlertSeverity.overdue),
              color: AppColors.danger,
            ),
            DataTableFilterOption(
              value: ServiceAlertSeverity.dueSoon,
              label: 'DUE SOON',
              count: count(ServiceAlertSeverity.dueSoon),
              color: AppColors.warning,
            ),
            DataTableFilterOption(
              value: ServiceAlertSeverity.info,
              label: 'OTHER',
              count: count(ServiceAlertSeverity.info),
            ),
          ],
        ),
        const SizedBox(height: AppSpacing.sm),
        Expanded(
          child: DataTableView<ServiceAlert>(
            rows: rows,
            rowHeight: 58,
            initialSortColumn: 8,
            controller: _table,
            resetPageKey: '$_filter|$_search',
            emptyState: const EmptyState(
              icon: Icons.filter_alt_off,
              title: 'NO ALERTS MATCH THIS FILTER',
            ),
            columns: [
              DataTableColumn(
                label: 'Vehicle',
                width: 110,
                cellBuilder: (_, a) =>
                    Text(a.vehicleNumber, style: const TextStyle(fontWeight: FontWeight.w700)),
                compare: (x, y) => x.vehicleNumber.compareTo(y.vehicleNumber),
                exportValue: (a) => a.vehicleNumber,
              ),
              DataTableColumn(
                label: 'Date',
                width: 130,
                isDate: true,
                cellBuilder: (_, a) => Text(_alertDateText(a)),
                compare: (x, y) => _compareNullable(_alertDate(x), _alertDate(y)),
                exportValue: _alertDateText,
              ),
              DataTableColumn(
                label: 'Alert',
                width: 190,
                cellBuilder: (_, a) => Text(a.title),
                compare: (x, y) => x.title.compareTo(y.title),
                exportValue: (a) => a.title,
              ),
              DataTableColumn(
                label: 'Detail',
                width: 230,
                cellBuilder: (_, a) => Text(
                  a.detail,
                  style: TextStyle(
                    color: _serviceAlertSeverityColor(a.severity),
                    fontWeight: FontWeight.w600,
                  ),
                ),
                exportValue: (a) => a.detail,
              ),
              DataTableColumn(
                label: 'Serviced by',
                width: 150,
                cellBuilder: (_, a) => Text(_servicedBy(a)),
                compare: (x, y) => _servicedBy(x).compareTo(_servicedBy(y)),
                exportValue: _servicedBy,
              ),
              DataTableColumn(
                label: 'Recorded by',
                width: 140,
                cellBuilder: (_, a) => Text(_recordedBy(a)),
                compare: (x, y) => _recordedBy(x).compareTo(_recordedBy(y)),
                exportValue: _recordedBy,
              ),
              DataTableColumn(
                label: 'Approved by',
                width: 140,
                cellBuilder: (_, a) => Text(_approvedBy(a)),
                compare: (x, y) => _approvedBy(x).compareTo(_approvedBy(y)),
                exportValue: _approvedBy,
              ),
              DataTableColumn(
                label: 'Current km',
                width: 115,
                numeric: true,
                cellBuilder: (_, a) {
                  if (a.kind != ServiceAlertKind.serviceDue) return const Text('-');
                  return Tooltip(
                    message: 'KM source: ${a.kmSource}',
                    child: Text(
                      _kmText(a),
                      style: a.currentKm == null
                          ? const TextStyle(
                              color: AppColors.textMuted, fontStyle: FontStyle.italic)
                          : null,
                    ),
                  );
                },
                compare: (x, y) => _compareNullable(x.currentKm, y.currentKm),
                exportValue: _kmText,
              ),
              DataTableColumn(
                label: 'Status',
                width: 120,
                cellBuilder: (_, a) => DataTableStatusChip(
                  label: _serviceAlertSeverityLabel(a.severity),
                  color: _serviceAlertSeverityColor(a.severity),
                ),
                compare: _compareBySeverity,
                exportValue: (a) => _serviceAlertSeverityLabel(a.severity),
              ),
              DataTableColumn(
                label: 'Action',
                width: 140,
                cellBuilder: (_, a) => _actionButton(a) ?? const SizedBox.shrink(),
              ),
            ],
          ),
        ),
      ],
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Alerts'),
        backgroundColor: AppColors.navy,
        foregroundColor: Colors.white,
      ),
      backgroundColor: AppColors.background,
      body: _loading
          ? const LoadingState()
          : _loadError != null
              ? ErrorState(message: 'Failed to load: $_loadError', onRetry: _load)
              : Column(
                  children: [
                    if (_hasPartialData)
                      Container(
                        width: double.infinity,
                        padding: const EdgeInsets.symmetric(
                          horizontal: AppSpacing.md,
                          vertical: AppSpacing.sm,
                        ),
                        color: AppColors.warningBg,
                        child: Row(
                          children: [
                            const Icon(Icons.info_outline, color: AppColors.warning, size: 16),
                            const SizedBox(width: AppSpacing.sm),
                            Expanded(
                              child: Text(
                                'Some alerts unavailable — a data source failed to load.',
                                style: AppText.caption.copyWith(color: AppColors.warning),
                              ),
                            ),
                          ],
                        ),
                      ),
                    Expanded(
                      child: RefreshIndicator(
                        onRefresh: () => _load(forceRefresh: true),
                        child: _alerts.isEmpty
                            ? const EmptyState(
                                icon: Icons.check_circle_outline,
                                title: 'NO ALERTS',
                                hint: 'EVERYTHING IS UP TO DATE',
                              )
                            : Padding(
                                padding: const EdgeInsets.all(AppSpacing.md),
                                child: _alertsTable(),
                              ),
                      ),
                    ),
                  ],
                ),
    );
  }
}

// Plain-map normalization of one service_records doc for the pure
// latestApprovedDoneForItem()/computeServiceItemDue() functions.
Map<String, dynamic> _normalizeServiceRecordForDue(Map<String, dynamic> data) {
  final items = (data['items'] as List?) ?? const [];
  final ts = data['serviceDate'];
  return {
    'status': (data['status'] ?? ServiceRecordStatus.submitted).toString(),
    'itemIds': items
        .map((it) => ((it as Map<String, dynamic>)['itemId'] ?? '').toString())
        .toList(),
    'currentKm': data['currentKm'],
    'serviceDateMillis': ts is Timestamp ? ts.millisecondsSinceEpoch : 0,
  };
}

const Map<String, int> _kServiceDueStatusRank = {
  ServiceItemDueStatus.missed: 0,
  ServiceItemDueStatus.overdue: 1,
  ServiceItemDueStatus.dueSoon: 2,
  ServiceItemDueStatus.kmUnknown: 3,
  ServiceItemDueStatus.neverServiced: 4,
  ServiceItemDueStatus.ok: 5,
};

// Every active service_items entry that applies to this vehicle, each with
// its live due-ness + PROVISIONAL state computed by the shared
// computeScheduleStatus() — MISSED/OVERDUE first, per spec. Fetches this
// vehicle's own service_records ONCE (every status, not just APPROVED —
// needed for the PROVISIONAL override) and reuses them for every
// schedule (no N+1 queries).
Future<List<ServiceItemDue>> fetchServiceItemsDueForVehicle(
  String vehicleNumber, {
  double? currentKm,
  FirebaseFirestore? db,
}) async {
  final firestore = db ?? FirebaseFirestore.instance;
  final itemsSnap =
      await firestore.collection('service_items').where('active', isEqualTo: true).get();
  final applicable = itemsSnap.docs.where((doc) {
    final data = doc.data();
    if (data['appliesTo'] != 'SELECTED') return true;
    final vehicleNumbers = (data['vehicleNumbers'] as List?)?.cast<String>() ?? const [];
    return vehicleNumbers.contains(vehicleNumber);
  }).toList();
  if (applicable.isEmpty) return const [];

  final recordsSnap = await firestore
      .collection('service_records')
      .where('vehicleNumber', isEqualTo: vehicleNumber)
      .get();
  DateTime? toDate(Object? v) => v is Timestamp ? v.toDate() : (v is DateTime ? v : null);
  // Grouped by scheduleId — legacy/freeform records with no scheduleId
  // (on-demand services logged before this milestone extension, or ones
  // with no matching schedule at all) simply never complete a milestone,
  // same as a schedule that has never been serviced.
  final recordsByScheduleId = <String, List<Map<String, dynamic>>>{};
  for (final doc in recordsSnap.docs) {
    final data = Map<String, dynamic>.from(doc.data());
    final scheduleId = (data['scheduleId'] ?? '').toString();
    if (scheduleId.isEmpty) continue;
    data['serviceDate'] = toDate(data['serviceDate']);
    data['submittedAt'] = toDate(data['submittedAt']);
    data['returnedAt'] = toDate(data['returnedAt']);
    recordsByScheduleId.putIfAbsent(scheduleId, () => []).add(data);
  }

  final now = DateTime.now();
  final due = applicable.map((doc) {
    final data = doc.data();
    final scheduleRecords = recordsByScheduleId[doc.id] ?? const [];
    return computeScheduleStatus(
      scheduleId: doc.id,
      scheduleName: (data['name'] ?? '').toString(),
      intervalKm: ((data['intervalKm'] as num?) ?? 0).toDouble(),
      intervalDays: (data['intervalDays'] as num?)?.toInt(),
      warnBeforeKm: ((data['warnBeforeKm'] as num?) ?? 1000).toDouble(),
      approvedRecords:
          scheduleRecords.where((r) => r['status'] == ServiceRecordStatus.approved).toList(),
      pendingOrReturned: latestPendingOrReturnedRecord(scheduleRecords),
      currentKm: currentKm,
      now: now,
    );
  }).toList();

  due.sort(
    (a, b) => (_kServiceDueStatusRank[a.status] ?? 9)
        .compareTo(_kServiceDueStatusRank[b.status] ?? 9),
  );
  return due;
}

Color _serviceDueStatusColor(String status) {
  switch (status) {
    case ServiceItemDueStatus.missed:
      return AppColors.danger;
    case ServiceItemDueStatus.overdue:
      return AppColors.danger;
    case ServiceItemDueStatus.dueSoon:
      return AppColors.warning;
    case ServiceItemDueStatus.kmUnknown:
      return AppColors.warning;
    case ServiceItemDueStatus.neverServiced:
      return AppColors.textMuted;
    default:
      return AppColors.success;
  }
}

String _serviceDueStatusLabel(String status) {
  switch (status) {
    case ServiceItemDueStatus.missed:
      return 'MISSED';
    case ServiceItemDueStatus.overdue:
      return 'OVERDUE';
    case ServiceItemDueStatus.dueSoon:
      return 'DUE SOON';
    case ServiceItemDueStatus.kmUnknown:
      return 'KM UNKNOWN';
    case ServiceItemDueStatus.neverServiced:
      return 'NEVER SERVICED';
    default:
      return 'OK';
  }
}

// ---------------- SERVICE ITEMS (admin/owner setup) ----------------
// One checklist line being edited in ServiceItemsScreen's add/edit dialog —
// mutable (unlike the Firestore-shaped {id, name, sortOrder, active} map)
// so the dialog can reorder/toggle/rename in place before SAVE serializes
// it back to that shape.
class _ChecklistRow {
  final String id;
  String name;
  bool active;
  _ChecklistRow({required this.id, required this.name, this.active = true});
}

class ServiceItemsScreen extends StatefulWidget {
  final FirebaseFirestore? firestoreOverride;
  final String? currentUidOverride;
  const ServiceItemsScreen({super.key, this.firestoreOverride, this.currentUidOverride});

  @override
  State<ServiceItemsScreen> createState() => _ServiceItemsScreenState();
}

class _ServiceItemsScreenState extends State<ServiceItemsScreen> {
  FirebaseFirestore get _db => widget.firestoreOverride ?? FirebaseFirestore.instance;
  late final Future<bool> _permFuture = _currentUserHasRepairPerm(
    kPermServiceSetup,
    db: _db,
    uidOverride: widget.currentUidOverride,
  );
  late final Stream<QuerySnapshot> _itemsStream = timeoutFirstEventOnly(
    _db.collection('service_items').orderBy('sortOrder').snapshots(),
    const Duration(seconds: 15),
    onTimeout: () => TimeoutException('Taking too long to load service items.'),
  );
  final _table = DataTableController<QueryDocumentSnapshot>();

  Future<void> _showItemDialog({DocumentSnapshot? existing}) async {
    final data = existing?.data() as Map<String, dynamic>?;
    final nameController = TextEditingController(text: (data?['name'] ?? '').toString());
    final intervalKmController = TextEditingController(
      text: data?['intervalKm'] != null ? (data!['intervalKm'] as num).toString() : '',
    );
    final intervalDaysController = TextEditingController(
      text: data?['intervalDays'] != null ? (data!['intervalDays'] as num).toString() : '',
    );
    final warnBeforeKmController = TextEditingController(
      text: ((data?['warnBeforeKm'] as num?) ?? 1000).toString(),
    );
    String appliesTo = (data?['appliesTo'] ?? 'ALL').toString();
    final vehicleNumbersController = TextEditingController(
      text: ((data?['vehicleNumbers'] as List?) ?? const []).join(', '),
    );

    // Checklist lines — {id, nameController, active}. Existing lines keep
    // their id (and stay in the list even if deactivated — "never delete");
    // a newly-added, never-saved line can simply be dropped again before
    // SAVE since nothing has persisted it yet. Old service_items with no
    // checklist at all start with an empty list here, which is exactly the
    // "schedule with empty checklist" backward-compatible shape the task
    // asked for.
    final existingChecklist = ((data?['checklist'] as List?) ?? const [])
        .map((e) => e as Map<String, dynamic>)
        .toList()
      ..sort((a, b) => ((a['sortOrder'] as num?) ?? 0).compareTo((b['sortOrder'] as num?) ?? 0));
    final checklistRows = existingChecklist
        .map((e) => _ChecklistRow(
              id: (e['id'] ?? '').toString(),
              name: (e['name'] ?? '').toString(),
              active: e['active'] != false,
            ))
        .toList();
    final newChecklistLineController = TextEditingController();

    final saved = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => StatefulBuilder(
        builder: (dialogContext, setDialogState) => AlertDialog(
          shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(AppRadius.card)),
          title: Text(existing == null ? 'Add Service Item' : 'Edit Service Item'),
          content: ConstrainedBox(
            // maxWidth, not a fixed SizedBox width — a tight 420px forced
            // this dialog wider than the screen at 360-390px (AlertDialog's
            // own insetPadding leaves far less than 420px available there).
            constraints: const BoxConstraints(maxWidth: 420),
            child: SingleChildScrollView(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                mainAxisSize: MainAxisSize.min,
                children: [
                  TextField(
                    controller: nameController,
                    inputFormatters: [UpperCaseTextFormatter()],
                    textCapitalization: TextCapitalization.characters,
                    decoration:
                        const InputDecoration(labelText: 'Name (e.g. Engine Oil + Filter)'),
                  ),
                  const SizedBox(height: 12),
                  TextField(
                    controller: intervalKmController,
                    keyboardType: const TextInputType.numberWithOptions(decimal: true),
                    decoration: const InputDecoration(labelText: 'Interval (km) *'),
                  ),
                  const SizedBox(height: 12),
                  TextField(
                    controller: intervalDaysController,
                    keyboardType: TextInputType.number,
                    decoration: const InputDecoration(labelText: 'Interval (days, optional)'),
                  ),
                  const SizedBox(height: 12),
                  TextField(
                    controller: warnBeforeKmController,
                    keyboardType: const TextInputType.numberWithOptions(decimal: true),
                    decoration: const InputDecoration(labelText: 'Warn before (km)'),
                  ),
                  const SizedBox(height: 12),
                  const Text('Applies To', style: TextStyle(fontWeight: FontWeight.bold)),
                  const SizedBox(height: 6),
                  Wrap(
                    spacing: 8,
                    children: ['ALL', 'SELECTED'].map((v) {
                      return ChoiceChip(
                        label: Text(v == 'ALL' ? 'All Vehicles' : 'Selected Vehicles'),
                        selected: appliesTo == v,
                        onSelected: (_) => setDialogState(() => appliesTo = v),
                      );
                    }).toList(),
                  ),
                  if (appliesTo == 'SELECTED') ...[
                    const SizedBox(height: 12),
                    TextField(
                      controller: vehicleNumbersController,
                      inputFormatters: [UpperCaseTextFormatter()],
                      textCapitalization: TextCapitalization.characters,
                      maxLines: 2,
                      decoration: const InputDecoration(
                        labelText: 'Vehicle Numbers (comma separated)',
                      ),
                    ),
                  ],
                  const SizedBox(height: 16),
                  const Divider(),
                  const SizedBox(height: 8),
                  const Text(
                    'Checklist (optional — leave empty for a single-item schedule)',
                    style: TextStyle(fontWeight: FontWeight.bold),
                  ),
                  const SizedBox(height: 8),
                  for (var i = 0; i < checklistRows.length; i++)
                    Padding(
                      padding: const EdgeInsets.only(bottom: 6),
                      child: Row(
                        children: [
                          Expanded(
                            child: TextField(
                              controller:
                                  TextEditingController(text: checklistRows[i].name)
                                    ..selection = TextSelection.collapsed(
                                      offset: checklistRows[i].name.length,
                                    ),
                              inputFormatters: [UpperCaseTextFormatter()],
                              textCapitalization: TextCapitalization.characters,
                              style: checklistRows[i].active
                                  ? null
                                  : const TextStyle(color: Colors.grey),
                              decoration: const InputDecoration(isDense: true),
                              onChanged: (val) => checklistRows[i].name = val,
                            ),
                          ),
                          IconButton(
                            icon: const Icon(Icons.arrow_upward, size: 18),
                            onPressed: i == 0
                                ? null
                                : () => setDialogState(() {
                                      final row = checklistRows.removeAt(i);
                                      checklistRows.insert(i - 1, row);
                                    }),
                          ),
                          IconButton(
                            icon: const Icon(Icons.arrow_downward, size: 18),
                            onPressed: i == checklistRows.length - 1
                                ? null
                                : () => setDialogState(() {
                                      final row = checklistRows.removeAt(i);
                                      checklistRows.insert(i + 1, row);
                                    }),
                          ),
                          IconButton(
                            icon: Icon(
                              checklistRows[i].active
                                  ? Icons.visibility
                                  : Icons.visibility_off,
                              size: 18,
                            ),
                            tooltip: checklistRows[i].active ? 'Deactivate' : 'Activate',
                            onPressed: () => setDialogState(
                              () => checklistRows[i].active = !checklistRows[i].active,
                            ),
                          ),
                        ],
                      ),
                    ),
                  Row(
                    children: [
                      Expanded(
                        child: TextField(
                          controller: newChecklistLineController,
                          inputFormatters: [UpperCaseTextFormatter()],
                          textCapitalization: TextCapitalization.characters,
                          decoration: const InputDecoration(
                            hintText: 'New checklist line (e.g. Tyres)',
                            isDense: true,
                          ),
                        ),
                      ),
                      IconButton(
                        icon: const Icon(Icons.add_circle, color: AppColors.primary),
                        onPressed: () {
                          final name = newChecklistLineController.text.trim();
                          if (name.isEmpty) return;
                          setDialogState(() {
                            checklistRows.add(
                              _ChecklistRow(
                                id: FirebaseFirestore.instance
                                    .collection('service_items')
                                    .doc()
                                    .id,
                                name: name,
                              ),
                            );
                            newChecklistLineController.clear();
                          });
                        },
                      ),
                    ],
                  ),
                ],
              ),
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dialogContext, false),
              child: const Text('Cancel'),
            ),
            ElevatedButton(
              onPressed: () => Navigator.pop(dialogContext, true),
              child: const Text('SAVE'),
            ),
          ],
        ),
      ),
    );
    if (saved != true) return;

    final intervalKm = num.tryParse(intervalKmController.text.trim());
    if (nameController.text.trim().isEmpty || intervalKm == null || intervalKm <= 0) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Please enter a name and a valid interval (km).')),
        );
      }
      return;
    }
    try {
      final uid = FirebaseAuth.instance.currentUser?.uid ?? '';
      final userDoc = await _db.collection('users').doc(uid).get();
      final userName = (userDoc.data()?['name'] ?? 'Unknown').toString();
      final vehicleNumbers = appliesTo == 'SELECTED'
          ? vehicleNumbersController.text
              .split(',')
              .map((s) => s.trim())
              .where((s) => s.isNotEmpty)
              .toList()
          : <String>[];
      final checklist = [
        for (var i = 0; i < checklistRows.length; i++)
          if (checklistRows[i].name.trim().isNotEmpty)
            {
              'id': checklistRows[i].id,
              'name': checklistRows[i].name.trim(),
              'sortOrder': i,
              'active': checklistRows[i].active,
            },
      ];
      final payload = {
        'name': nameController.text.trim(),
        'intervalKm': intervalKm,
        'intervalDays': int.tryParse(intervalDaysController.text.trim()),
        'warnBeforeKm': num.tryParse(warnBeforeKmController.text.trim()) ?? 1000,
        'appliesTo': appliesTo,
        'vehicleNumbers': vehicleNumbers,
        'checklist': checklist,
        'active': data?['active'] ?? true,
        'sortOrder': data?['sortOrder'] ?? DateTime.now().millisecondsSinceEpoch,
        'updatedBy': uid,
        'updatedByName': userName,
        'updatedAt': FieldValue.serverTimestamp(),
      };
      DocumentReference ref;
      if (existing == null) {
        ref = _db.collection('service_items').doc();
        await ref.set({
          ...payload,
          'createdBy': uid,
          'createdByName': userName,
          'createdAt': FieldValue.serverTimestamp(),
        });
      } else {
        ref = existing.reference;
        await ref.update(payload);
      }
      await _writeRepairEvent(
        collection: 'service_items',
        docId: ref.id,
        action: existing == null ? 'CREATED' : 'UPDATED',
        summary: '${existing == null ? 'Created' : 'Updated'} by $userName',
        actorUid: uid,
        actorName: userName,
      );
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('Failed to save: $e')));
      }
    }
  }

  Future<void> _toggleActive(DocumentSnapshot doc, bool active) async {
    try {
      final uid = FirebaseAuth.instance.currentUser?.uid ?? '';
      final userDoc = await _db.collection('users').doc(uid).get();
      final userName = (userDoc.data()?['name'] ?? 'Unknown').toString();
      await doc.reference.update({
        'active': active,
        'updatedBy': uid,
        'updatedByName': userName,
        'updatedAt': FieldValue.serverTimestamp(),
      });
      await _writeRepairEvent(
        collection: 'service_items',
        docId: doc.id,
        action: active ? 'ACTIVATED' : 'DEACTIVATED',
        summary: '${active ? 'Activated' : 'Deactivated'} by $userName',
        actorUid: uid,
        actorName: userName,
      );
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('Failed to update: $e')));
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<bool>(
      future: _permFuture,
      builder: (context, permSnap) {
        if (permSnap.connectionState != ConnectionState.done) {
          return const TruckRepairScaffold(body: LoadingState());
        }
        if (permSnap.data != true) {
          return const TruckRepairScaffold(
            body: EmptyState(
              icon: Icons.lock_outline,
              title: 'NO ACCESS',
              hint: 'ASK THE ADMIN TO GRANT THIS TRUCK REPAIR PERMISSION',
            ),
          );
        }
        return TruckRepairScaffold(
          appBar: AppBar(
            title: const Text('Service Items'),
            backgroundColor: AppColors.navy,
            foregroundColor: Colors.white,
          ),
          floatingActionButton: FloatingActionButton(
            onPressed: () => _showItemDialog(),
            backgroundColor: AppColors.navy,
            child: const Icon(Icons.add, color: Colors.white),
          ),
          body: StreamBuilder<QuerySnapshot>(
            stream: _itemsStream,
            builder: (context, snapshot) {
              if (snapshot.hasError) {
                debugPrint('ServiceItemsScreen: load error: ${snapshot.error}');
                return ErrorState(
                  message: snapshot.error is TimeoutException
                      ? 'Taking too long — RETRY'
                      : 'Failed to load: ${snapshot.error}',
                  onRetry: () => setState(() {}),
                );
              }
              if (!snapshot.hasData) return const LoadingState();
              final docs = snapshot.data!.docs;
              if (docs.isEmpty) {
                return const EmptyState(
                  icon: Icons.build_circle,
                  title: 'NO SERVICE ITEMS YET',
                  hint: 'TAP + TO ADD ONE',
                );
              }
              Map<String, dynamic> d(QueryDocumentSnapshot doc) =>
                  doc.data() as Map<String, dynamic>;
              num? n(QueryDocumentSnapshot doc, String f) => d(doc)[f] as num?;
              String appliesTo(QueryDocumentSnapshot doc) {
                if (d(doc)['appliesTo'] != 'SELECTED') return 'All vehicles';
                final list = (d(doc)['vehicleNumbers'] as List?) ?? const [];
                return 'Selected (${list.length}): ${list.join(', ')}';
              }

              return Padding(
                padding: const EdgeInsets.all(AppSpacing.md),
                child: Column(
                  children: [
                    DataTableToolbar(
                      onExport: (f) => exportDataTable<QueryDocumentSnapshot>(
                        context,
                        format: f,
                        controller: _table,
                        title: 'Service Items',
                        db: widget.firestoreOverride,
                        uid: widget.currentUidOverride,
                      ),
                    ),
                    const SizedBox(height: AppSpacing.sm),
                    Expanded(
                      child: DataTableView<QueryDocumentSnapshot>(
                  rows: docs,
                  controller: _table,
                  onRowTap: (doc) => _showItemDialog(existing: doc),
                  columns: [
                    DataTableColumn(
                      label: 'Service',
                      width: 190,
                      cellBuilder: (_, doc) => Text((d(doc)['name'] ?? '').toString(),
                          style: const TextStyle(fontWeight: FontWeight.w700)),
                      compare: (a, b) => (d(a)['name'] ?? '')
                          .toString()
                          .compareTo((d(b)['name'] ?? '').toString()),
                      exportValue: (doc) => (d(doc)['name'] ?? '').toString(),
                    ),
                    DataTableColumn(
                      label: 'Every (km)',
                      width: 110,
                      numeric: true,
                      cellBuilder: (_, doc) => Text('${n(doc, 'intervalKm') ?? 0}'),
                      compare: (a, b) => _compareNullable(n(a, 'intervalKm'), n(b, 'intervalKm')),
                      exportValue: (doc) => '${n(doc, 'intervalKm') ?? 0}',
                    ),
                    DataTableColumn(
                      label: 'Every (days)',
                      width: 115,
                      numeric: true,
                      cellBuilder: (_, doc) => Text('${n(doc, 'intervalDays') ?? '—'}'),
                      compare: (a, b) =>
                          _compareNullable(n(a, 'intervalDays'), n(b, 'intervalDays')),
                      exportValue: (doc) => '${n(doc, 'intervalDays') ?? '-'}',
                    ),
                    DataTableColumn(
                      label: 'Warn before',
                      width: 115,
                      numeric: true,
                      cellBuilder: (_, doc) => Text('${n(doc, 'warnBeforeKm') ?? 1000} km'),
                      exportValue: (doc) => '${n(doc, 'warnBeforeKm') ?? 1000} km',
                    ),
                    DataTableColumn(
                      label: 'Applies to',
                      width: 180,
                      cellBuilder: (_, doc) => Text(appliesTo(doc)),
                      exportValue: appliesTo,
                    ),
                    DataTableColumn(
                      label: 'Active',
                      width: 90,
                      cellBuilder: (_, doc) => Switch(
                        value: d(doc)['active'] != false,
                        onChanged: (val) => _toggleActive(doc, val),
                      ),
                      compare: (a, b) => (d(a)['active'] != false ? 0 : 1)
                          .compareTo(d(b)['active'] != false ? 0 : 1),
                      exportValue: (doc) => d(doc)['active'] != false ? 'Active' : 'Inactive',
                    ),
                  ],
                      ),
                    ),
                  ],
                ),
              );
            },
          ),
        );
      },
    );
  }
}

class _ExtraServiceItemRow {
  final nameController = TextEditingController();
  final costController = TextEditingController(text: '0');
  void dispose() {
    nameController.dispose();
    costController.dispose();
  }
}

// ---------------- MECHANIC: DO / RESUBMIT A SERVICE ----------------
// Reached either with vehicleNumber (fresh submission — the hub tile picks
// the vehicle first, same convention as AddDefectScreen) or recordId (a
// RETURNED record being edited and resubmitted). Exactly one of the two is
// ever provided by this file's own navigation; the assert below is a
// defensive backstop (stripped in release builds, like
// DefectMechanicFormScreen's identical guard).
// One checklist line's result on the mechanic form — DONE, or NOT DONE with
// a required reason, plus an optional per-line note.
class _ChecklistLineInput {
  final String itemId;
  final String name;
  bool done;
  final notDoneReasonController = TextEditingController();
  final noteController = TextEditingController();
  _ChecklistLineInput({required this.itemId, required this.name, this.done = true});
  void dispose() {
    notDoneReasonController.dispose();
    noteController.dispose();
  }
}

class ServiceRecordFormScreen extends StatefulWidget {
  final String? vehicleNumber;
  final String? recordId;
  // RED ALERTS "DO SERVICE" deep link — skips Step 1's schedule picker and
  // jumps straight to the checklist for this schedule, same as if the
  // mechanic had tapped it themselves. Ignored when recordId is set (a
  // resubmit already knows its own scheduleId).
  final String? preselectScheduleId;
  final FirebaseFirestore? firestoreOverride;
  final String? currentUidOverride;
  const ServiceRecordFormScreen({
    super.key,
    this.vehicleNumber,
    this.recordId,
    this.preselectScheduleId,
    this.firestoreOverride,
    this.currentUidOverride,
  }) : assert(vehicleNumber != null || recordId != null);

  @override
  State<ServiceRecordFormScreen> createState() => _ServiceRecordFormScreenState();
}

class _ServiceRecordFormScreenState extends State<ServiceRecordFormScreen> {
  FirebaseFirestore get _db => widget.firestoreOverride ?? FirebaseFirestore.instance;

  bool _loading = true;
  Object? _loadError;
  bool _busy = false;
  late final Future<bool> _permFuture = _currentUserHasRepairPerm(
    kPermServiceDo,
    db: _db,
    uidOverride: widget.currentUidOverride,
  );

  String _vehicleNumber = '';
  Map<String, dynamic>? _existingData;
  List<ServiceItemDue> _dueItems = const [];
  String _kmSource = '';

  // Step 1 (schedule pick) state — null scheduleId with _scheduleChosen
  // true means an explicit "log without a schedule" on-demand service.
  String? _selectedScheduleId;
  Map<String, dynamic>? _selectedScheduleData;
  double? _selectedMilestoneKm;
  bool _scheduleChosen = false;
  final List<_ChecklistLineInput> _checklistRows = [];

  final List<_ExtraServiceItemRow> _extraItemRows = [_ExtraServiceItemRow()];

  DateTime _serviceDate = DateTime.now();
  final _currentKmController = TextEditingController();
  final _garageNameController = TextEditingController();
  final _garageContactController = TextEditingController();
  final _totalPriceController = TextEditingController(text: '0');
  final _noteController = TextEditingController();
  final _attachmentsKey = GlobalKey<_InspectionAttachmentsSectionState>();

  @override
  void initState() {
    super.initState();
    _load();
  }

  @override
  void dispose() {
    _currentKmController.dispose();
    _garageNameController.dispose();
    _garageContactController.dispose();
    _totalPriceController.dispose();
    _noteController.dispose();
    for (final r in _extraItemRows) {
      r.dispose();
    }
    for (final r in _checklistRows) {
      r.dispose();
    }
    super.dispose();
  }

  // Builds _checklistRows from a schedule's ACTIVE checklist lines. For a
  // resubmit, `priorResults` (the previously-stored lineResults, keyed by
  // itemId) seeds each line's done/reason/note so editing after a RETURN
  // doesn't lose what was already entered — any line added to the schedule
  // since then simply defaults to DONE, same as a fresh pick.
  void _buildChecklistRows(
    Map<String, dynamic> scheduleData, {
    Map<String, Map<String, dynamic>>? priorResults,
  }) {
    for (final r in _checklistRows) {
      r.dispose();
    }
    _checklistRows.clear();
    final lines = ((scheduleData['checklist'] as List?) ?? const [])
        .map((e) => e as Map<String, dynamic>)
        .where((e) => e['active'] != false)
        .toList()
      ..sort((a, b) => ((a['sortOrder'] as num?) ?? 0).compareTo((b['sortOrder'] as num?) ?? 0));
    for (final line in lines) {
      final id = (line['id'] ?? '').toString();
      final prior = priorResults?[id];
      final row = _ChecklistLineInput(
        itemId: id,
        name: (line['name'] ?? '').toString(),
        done: prior == null ? true : prior['done'] != false,
      );
      if (prior != null) {
        row.notDoneReasonController.text = (prior['notDoneReason'] ?? '').toString();
        row.noteController.text = (prior['note'] ?? '').toString();
      }
      _checklistRows.add(row);
    }
  }

  Future<void> _selectSchedule(String scheduleId, double milestoneKm) async {
    final doc = await _db.collection('service_items').doc(scheduleId).get();
    final data = doc.data() ?? <String, dynamic>{};
    setState(() {
      _selectedScheduleId = scheduleId;
      _selectedScheduleData = data;
      _selectedMilestoneKm = milestoneKm;
      _scheduleChosen = true;
      _buildChecklistRows(data);
    });
  }

  void _logWithoutSchedule() => setState(() {
    _selectedScheduleId = null;
    _selectedScheduleData = null;
    _selectedMilestoneKm = null;
    _scheduleChosen = true;
    for (final r in _checklistRows) {
      r.dispose();
    }
    _checklistRows.clear();
  });

  Future<void> _load() async {
    setState(() {
      _loading = true;
      _loadError = null;
    });
    try {
      Map<String, Map<String, dynamic>>? priorResults;
      String? existingScheduleId;
      if (widget.recordId != null) {
        final snap = await _db.collection('service_records').doc(widget.recordId).get();
        if (!snap.exists) {
          throw Exception('This service record no longer exists.');
        }
        final data = snap.data()!;
        _existingData = data;
        _vehicleNumber = (data['vehicleNumber'] ?? '').toString();
        existingScheduleId = (data['scheduleId'] as String?);
        if (existingScheduleId != null && existingScheduleId.isNotEmpty) {
          _selectedScheduleId = existingScheduleId;
          _selectedMilestoneKm = (data['milestoneKm'] as num?)?.toDouble();
        }
        _scheduleChosen = true;
        final serviceDate = data['serviceDate'];
        if (serviceDate is Timestamp) _serviceDate = serviceDate.toDate();
        _currentKmController.text = ((data['currentKm'] as num?) ?? 0).toString();
        _garageNameController.text = (data['garageName'] ?? '').toString();
        _garageContactController.text = (data['garageContactNumber'] ?? '').toString();
        _totalPriceController.text = _centsToMoney(
          ((data['totalPriceCents'] as num?)?.toInt() ?? 0),
        ).toStringAsFixed(2);
        _noteController.text = (data['note'] ?? '').toString();
        priorResults = {
          for (final r in ((data['lineResults'] as List?) ?? const []))
            (r as Map<String, dynamic>)['itemId'].toString(): r,
        };
        final extra = (data['extraItems'] as List?) ?? const [];
        if (extra.isNotEmpty) {
          _extraItemRows.clear();
          for (final e in extra) {
            final m = e as Map<String, dynamic>;
            final row = _ExtraServiceItemRow();
            row.nameController.text = (m['name'] ?? '').toString();
            row.costController.text = _centsToMoney(
              ((m['costCents'] as num?)?.toInt() ?? 0),
            ).toStringAsFixed(2);
            _extraItemRows.add(row);
          }
        }
      } else {
        _vehicleNumber = widget.vehicleNumber!;
      }

      final best = await fetchBestKnownKm(_vehicleNumber, db: _db);
      _kmSource = best.source;
      if (_currentKmController.text.trim().isEmpty && best.km != null) {
        _currentKmController.text = best.km!.toStringAsFixed(0);
      }
      _dueItems = await fetchServiceItemsDueForVehicle(
        _vehicleNumber,
        currentKm: best.km,
        db: _db,
      );
      if (existingScheduleId != null && existingScheduleId.isNotEmpty) {
        final doc = await _db.collection('service_items').doc(existingScheduleId).get();
        _selectedScheduleData = doc.data();
        if (_selectedScheduleData != null) {
          _buildChecklistRows(_selectedScheduleData!, priorResults: priorResults);
        }
      } else if (widget.preselectScheduleId != null &&
          widget.preselectScheduleId!.isNotEmpty) {
        final preselectId = widget.preselectScheduleId!;
        final dueMatch = _dueItems.where((d) => d.itemId == preselectId);
        double? milestoneKm = dueMatch.isNotEmpty ? dueMatch.first.milestoneKm : null;
        if (milestoneKm == null) {
          // Not (or no longer) in the due list — still honor the deep
          // link by looking the schedule up directly and using its next
          // milestone, same math fetchServiceItemsDueForVehicle used.
          final doc = await _db.collection('service_items').doc(preselectId).get();
          final data = doc.data();
          if (data != null) {
            final intervalKm = (data['intervalKm'] as num?)?.toDouble();
            if (intervalKm != null && intervalKm > 0) milestoneKm = intervalKm;
          }
        }
        if (milestoneKm != null) {
          await _selectSchedule(preselectId, milestoneKm);
        }
      }
      if (mounted) setState(() => _loading = false);
    } catch (e) {
      debugPrint('ServiceRecordFormScreen: load error: $e');
      if (mounted) {
        setState(() {
          _loading = false;
          _loadError = e;
        });
      }
    }
  }

  void _addExtraRow() => setState(() => _extraItemRows.add(_ExtraServiceItemRow()));
  void _removeExtraRow(int index) => setState(() {
    _extraItemRows[index].dispose();
    _extraItemRows.removeAt(index);
  });

  Future<void> _pickServiceDate() async {
    final picked = await showDatePicker(
      context: context,
      initialDate: _serviceDate,
      firstDate: DateTime.now().subtract(const Duration(days: 365)),
      lastDate: DateTime.now().add(const Duration(days: 1)),
    );
    if (picked != null) setState(() => _serviceDate = picked);
  }

  Future<void> _guarded(Future<void> Function() action) async {
    if (_busy) return;
    setState(() => _busy = true);
    try {
      await action();
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  Future<void> _submit() async {
    final currentKm = num.tryParse(_currentKmController.text.trim());
    if (currentKm == null || currentKm < 0) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Please enter a valid current km.')),
      );
      return;
    }
    if (_garageNameController.text.trim().isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Please enter the service center / garage name.')),
      );
      return;
    }
    if (_garageContactController.text.trim().isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Please enter the garage contact number.')),
      );
      return;
    }
    final totalPrice = num.tryParse(_totalPriceController.text.trim());
    if (totalPrice == null || totalPrice < 0) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Please enter a valid total price.')),
      );
      return;
    }
    final lineResultsForValidation = _checklistRows
        .map((r) => {
              'done': r.done,
              'notDoneReason': r.notDoneReasonController.text.trim(),
            })
        .toList();
    if (!isChecklistSubmitValid(lineResultsForValidation)) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Every NOT DONE checklist line needs a reason.'),
        ),
      );
      return;
    }
    final confirmed = await showAppConfirmDialog(
      context: context,
      title: 'Submit For Approval?',
      message: 'This sends the service for $_vehicleNumber to management for approval.',
      confirmLabel: 'Submit',
    );
    if (!confirmed) return;

    try {
      final currentUser = FirebaseAuth.instance.currentUser;
      final uid = currentUser?.uid ?? '';
      final userDoc = await _db.collection('users').doc(uid).get();
      final userName = (userDoc.data()?['name'] ?? 'Unknown').toString();

      final lineResults = _checklistRows
          .map((r) => {
                'itemId': r.itemId,
                'name': r.name,
                'done': r.done,
                'notDoneReason': r.done ? null : r.notDoneReasonController.text.trim(),
                'note': r.noteController.text.trim(),
              })
          .toList();
      final extraItems = _extraItemRows
          .where((r) => r.nameController.text.trim().isNotEmpty)
          .map((r) => {
                'name': r.nameController.text.trim(),
                'costCents': _moneyToCents(num.tryParse(r.costController.text.trim()) ?? 0),
              })
          .toList();
      final milestoneKm = _selectedMilestoneKm;
      final lateKm = milestoneKm == null ? null : (currentKm - milestoneKm).round();
      final intervalDays = (_selectedScheduleData?['intervalDays'] as num?)?.toInt();
      final scheduleName = (_selectedScheduleData?['name'] ?? '').toString();

      final isResubmit = widget.recordId != null;
      final ref = isResubmit
          ? _db.collection('service_records').doc(widget.recordId)
          : _db.collection('service_records').doc();
      final attachments = await _attachmentsKey.currentState!.uploadAndFinalize(
        _serviceRecordStoragePathPrefix(ref.id),
      );

      final payload = {
        'vehicleNumber': _vehicleNumber,
        'status': ServiceRecordStatus.submitted,
        'scheduleId': _selectedScheduleId,
        'scheduleName': scheduleName,
        'milestoneKm': milestoneKm,
        'doneKm': currentKm,
        'lateKm': lateKm,
        if (intervalDays != null) 'dueIntervalDays': intervalDays,
        'serviceDate': Timestamp.fromDate(_serviceDate),
        'doneDate': Timestamp.fromDate(_serviceDate),
        'currentKm': currentKm,
        'lineResults': lineResults,
        'extraItems': extraItems,
        'garageName': _garageNameController.text.trim(),
        'garageContactNumber': _garageContactController.text.trim(),
        'totalPriceCents': _moneyToCents(totalPrice),
        'note': _noteController.text.trim(),
        'photos': attachments.photos,
        'voices': attachments.voices,
        'submittedBy': uid,
        'submittedByName': userName,
        'submittedByEmail': currentUser?.email,
        'submittedAt': FieldValue.serverTimestamp(),
        'returnReason': null,
        'returnedBy': null,
        'returnedByName': null,
        'returnedAt': null,
        'updatedBy': uid,
        'updatedByName': userName,
        'updatedAt': FieldValue.serverTimestamp(),
      };

      String recordNoForEvent;
      if (isResubmit) {
        recordNoForEvent = (_existingData?['recordNo'] ?? '').toString();
        await ref.update(payload);
      } else {
        recordNoForEvent = await _nextRepairSequenceNumber('service_records', 'SVC');
        await ref.set({
          ...payload,
          'recordNo': recordNoForEvent,
          'createdAt': FieldValue.serverTimestamp(),
        });
      }
      await _writeRepairEvent(
        collection: 'service_records',
        docId: ref.id,
        action: isResubmit ? 'RESUBMITTED' : 'SUBMITTED',
        summary:
            '$recordNoForEvent ${isResubmit ? 'resubmitted' : 'submitted'} by $userName',
        actorUid: uid,
        actorName: userName,
      );
      // So this technical user's own red/amber clears to the PROVISIONAL
      // "AWAITING APPROVAL" green immediately, without waiting for
      // ServiceAlertsCache's 5-minute refreshInterval, and management's
      // pending-approval alert appears right away too.
      unawaited(_loadAlertsForCurrentUser(
        db: _db,
        uid: widget.currentUidOverride ?? uid,
        forceRefresh: true,
      ));

      if (!mounted) return;
      await showDialog<void>(
        context: context,
        builder: (dialogContext) => AlertDialog(
          title: const Text('Submitted'),
          content: Text('$recordNoForEvent sent to management for approval.'),
          actions: [
            ElevatedButton(
              onPressed: () => Navigator.pop(dialogContext),
              child: const Text('OK'),
            ),
          ],
        ),
      );
      if (mounted) Navigator.pop(context);
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Failed to submit: $e')),
        );
      }
    }
  }

  Widget _scheduleChip(String status) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
      decoration: BoxDecoration(
        color: _serviceDueStatusColor(status).withOpacity(0.12),
        borderRadius: BorderRadius.circular(AppRadius.chip),
      ),
      child: Text(
        _serviceDueStatusLabel(status),
        style: TextStyle(
          color: _serviceDueStatusColor(status),
          fontSize: 11,
          fontWeight: FontWeight.bold,
        ),
      ),
    );
  }

  // STEP 1 — pick which schedule this service is for (or log without one).
  Widget _buildSchedulePicker() {
    return SingleChildScrollView(
      padding: const EdgeInsets.all(AppSpacing.md),
      child: Align(
        alignment: Alignment.topCenter,
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 560),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              const SectionHeader(title: 'Pick A Schedule'),
              const SizedBox(height: AppSpacing.sm),
              Text('Current km source: $_kmSource', style: AppText.caption),
              const SizedBox(height: AppSpacing.sm),
              if (_dueItems.isEmpty)
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: AppSpacing.sm),
                  child: Text(
                    'No service schedules set up yet for this vehicle.',
                    style: AppText.caption,
                  ),
                )
              else
                ..._dueItems.map((due) {
                  return Padding(
                    padding: const EdgeInsets.only(bottom: AppSpacing.sm),
                    child: AppCard(
                      onTap: due.milestoneKm == null
                          ? null
                          : () => _selectSchedule(due.itemId, due.milestoneKm!),
                      child: Row(
                        children: [
                          Expanded(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Text(due.itemName, style: AppText.section),
                                if (due.milestoneNumber != null)
                                  Text(
                                    'Milestone ${due.milestoneNumber}: '
                                    '${due.milestoneKm?.toStringAsFixed(0)} km'
                                    '${due.kmRemaining != null ? (due.kmRemaining! >= 0 ? ' (${due.kmRemaining!.toStringAsFixed(0)} km to go)' : ' (${(-due.kmRemaining!).toStringAsFixed(0)} km past)') : ''}',
                                    style: AppText.caption,
                                  ),
                              ],
                            ),
                          ),
                          _scheduleChip(due.status),
                        ],
                      ),
                    ),
                  );
                }),
              const SizedBox(height: AppSpacing.md),
              SizedBox(
                width: double.infinity,
                child: OutlinedButton.icon(
                  onPressed: _logWithoutSchedule,
                  icon: const Icon(Icons.add_circle_outline),
                  label: const Text(
                    'LOG WITHOUT A SCHEDULE (ON-DEMAND)',
                    softWrap: true,
                    textAlign: TextAlign.center,
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  // STEP 2 — the actual form (checklist if a schedule was picked, extra
  // items, garage/price/km/date/photos, submit).
  Widget _buildForm() {
    return SingleChildScrollView(
      padding: const EdgeInsets.all(AppSpacing.md),
      child: Align(
        alignment: Alignment.topCenter,
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 560),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              if (_existingData?['returnReason'] != null)
                Container(
                  width: double.infinity,
                  padding: const EdgeInsets.all(AppSpacing.sm),
                  margin: const EdgeInsets.only(bottom: AppSpacing.md),
                  decoration: BoxDecoration(
                    color: AppColors.danger.withOpacity(0.08),
                    borderRadius: BorderRadius.circular(AppRadius.card),
                    border: Border.all(color: AppColors.danger.withOpacity(0.4)),
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        'RETURNED BY MANAGEMENT',
                        style: AppText.caption.copyWith(
                          fontWeight: FontWeight.bold,
                          color: AppColors.danger,
                        ),
                      ),
                      const SizedBox(height: 4),
                      Text(
                        (_existingData?['returnReason'] ?? '').toString(),
                        style: AppText.body,
