class _KmHistoryPanel extends StatefulWidget {
  final String truckNumber;
  final int deviceId;
  final String username;
  final String password;

  const _KmHistoryPanel({
    super.key,
    required this.truckNumber,
    required this.deviceId,
    required this.username,
    required this.password,
  });

  @override
  State<_KmHistoryPanel> createState() => _KmHistoryPanelState();
}

class _KmHistoryPanelState extends State<_KmHistoryPanel> {
  late final Future<double> _totalMetersFuture;
  late final Future<List<MapEntry<DateTime, double>>> _dailyKmFuture;

  @override
  void initState() {
    super.initState();
    final now = DateTime.now();
    _totalMetersFuture = VehicleKmCache.withSummarySlot(
      () => TraccarService.fetchDistanceSummary(
        username: widget.username,
        password: widget.password,
        deviceId: widget.deviceId,
        from: DateTime(2020, 1, 1),
        to: now,
      ),
    );
    _dailyKmFuture = _fetchDailyKm(now);
  }

  // No "daily" flag on /api/reports/summary (confirmed against Traccar's
  // OpenAPI spec) — one call per day, run concurrently rather than
  // sequentially so 30 days doesn't mean 30x the wait.
  Future<List<MapEntry<DateTime, double>>> _fetchDailyKm(DateTime now) async {
    final today = DateTime(now.year, now.month, now.day);
    final days = List.generate(30, (i) => today.subtract(Duration(days: i)));
    final results = await Future.wait(
      days.map((day) async {
        // App-wide 3-at-a-time limit (was 30 parallel calls).
        final meters = await VehicleKmCache.withSummarySlot(
          () => TraccarService.fetchDistanceSummary(
            username: widget.username,
            password: widget.password,
            deviceId: widget.deviceId,
            from: day,
            to: day.add(const Duration(days: 1)),
          ),
        );
        return MapEntry(day, meters);
      }),
    );
    return results;
  }

  String _formatDate(DateTime d) =>
      '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';

  @override
  Widget build(BuildContext context) {
    return SingleChildScrollView(
      padding: const EdgeInsets.all(16),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            widget.truckNumber,
            style: const TextStyle(fontSize: 18, fontWeight: FontWeight.bold),
          ),
          const SizedBox(height: 12),
          FutureBuilder<double>(
            future: _totalMetersFuture,
            builder: (context, snapshot) {
              if (snapshot.connectionState == ConnectionState.waiting) {
                return const LinearProgressIndicator();
              }
              if (snapshot.hasError) {
                return Text('Failed to load Total KM: ${snapshot.error}');
              }
              final km = (snapshot.data ?? 0) / 1000;
              return Card(
                color: AppTheme.primaryMid.withOpacity(0.08),
                child: Padding(
                  padding: const EdgeInsets.all(16),
                  child: Row(
                    children: [
                      const Icon(Icons.route, color: AppTheme.primaryMid),
                      const SizedBox(width: 12),
                      Text(
                        'Total Distance: ${km.toStringAsFixed(1)} km',
                        style: const TextStyle(
                          fontSize: 16,
                          fontWeight: FontWeight.bold,
                        ),
                      ),
                    ],
                  ),
                ),
              );
            },
          ),
          const SizedBox(height: 20),
          const Text(
            'Daily KM History (Last 30 Days)',
            style: TextStyle(fontWeight: FontWeight.bold, fontSize: 14),
          ),
          const SizedBox(height: 8),
          FutureBuilder<List<MapEntry<DateTime, double>>>(
            future: _dailyKmFuture,
            builder: (context, snapshot) {
              if (snapshot.connectionState == ConnectionState.waiting) {
                return const Padding(
                  padding: EdgeInsets.symmetric(vertical: 20),
                  child: Center(child: CircularProgressIndicator()),
                );
              }
              if (snapshot.hasError) {
                return Text(
                  'Failed to load Daily KM History: ${snapshot.error}',
                );
              }
              final daily = snapshot.data ?? [];
              return ListView.separated(
                shrinkWrap: true,
                physics: const NeverScrollableScrollPhysics(),
                itemCount: daily.length,
                separatorBuilder: (_, _) => const Divider(height: 1),
                itemBuilder: (context, index) {
                  final entry = daily[index];
                  final km = entry.value / 1000;
                  return ListTile(
                    dense: true,
                    title: Text(_formatDate(entry.key)),
                    trailing: Text(
                      '${km.toStringAsFixed(1)} km',
                      style: const TextStyle(fontWeight: FontWeight.bold),
                    ),
                  );
                },
              );
            },
          ),
        ],
      ),
    );
  }
}

// ---------------- LIVE TRACKING SCREEN (GPS Live Tracking, web-only — Phase 1) ----------------
// Admin/Owner/Management-only live fleet map, reached from each dashboard's
// sidebar (see AdminDashboard/OwnerDashboard/ManagementDashboard's
// menuItems). Web-only: the Google Maps JS API key is compiled into
// web/index.html and the Traccar credentials below are compiled into this
// client bundle — both visible to anyone who opens browser devtools on this
// build. That's an accepted Phase-1 tradeoff for an internal, low-user-count
// web dashboard; kIsWeb-gating the whole screen (not just its sidebar entry)
// keeps that exposure confined to the web build and out of the mobile app,
// which never even links this code path.
// ---- Live Tracking vehicle type (truck / bike / unknown) ----
// One rule for every icon in Live Tracking (map markers, Speed picker,
// sidebar): the app's own data wins. A vehicle registered in `trucks`
// (same GPS Device ID or same vehicle number) is a truck even if the same
// device/number was also entered on a bike; only then `bikes`; only then
// the Traccar device category; anything else is unknown (neutral pin,
// never the bike icon).
enum LiveVehicleType { truck, bike, unknown }

const Set<String> _kTraccarTruckCategories = {'truck', 'tractor', 'crane'};
const Set<String> _kTraccarBikeCategories = {'motorcycle', 'scooter', 'bicycle'};

LiveVehicleType liveVehicleTypeFromTraccarCategory(String? category) {
  final c = (category ?? '').trim().toLowerCase();
  if (_kTraccarTruckCategories.contains(c)) return LiveVehicleType.truck;
  if (_kTraccarBikeCategories.contains(c)) return LiveVehicleType.bike;
  return LiveVehicleType.unknown;
}

class LiveVehicleIndex {
  final Set<String> truckGpsIds;
  final Set<String> truckNumbers;
  final Set<String> bikeGpsIds;
  final Set<String> bikeNumbers;

  const LiveVehicleIndex({
    this.truckGpsIds = const {},
    this.truckNumbers = const {},
    this.bikeGpsIds = const {},
    this.bikeNumbers = const {},
  });

  static String _gps(Object? v) => (v ?? '').toString().trim();
  static String _num(Object? v) => normalizeVehicleNumber((v ?? '').toString());

  factory LiveVehicleIndex.fromData({
    required Iterable<Map<String, dynamic>> trucks,
    required Iterable<Map<String, dynamic>> bikes,
  }) {
    Set<String> collect(Iterable<Map<String, dynamic>> docs, String Function(Map<String, dynamic>) f) =>
        {for (final d in docs) f(d)}..remove('');
    return LiveVehicleIndex(
      truckGpsIds: collect(trucks, (d) => _gps(d['gpsDeviceId'])),
      truckNumbers: collect(trucks, (d) => _num(d['truckNumber'])),
      bikeGpsIds: collect(bikes, (d) => _gps(d['gpsDeviceId'])),
      bikeNumbers: collect(bikes, (d) => _num(d['bikeNumber'])),
    );
  }

  LiveVehicleType resolve({
    String? gpsDeviceId,
    String? vehicleNumber,
    String? traccarCategory,
  }) {
    final gps = _gps(gpsDeviceId);
    final number = _num(vehicleNumber);
    if ((gps.isNotEmpty && truckGpsIds.contains(gps)) ||
        (number.isNotEmpty && truckNumbers.contains(number))) {
      return LiveVehicleType.truck;
    }
    if ((gps.isNotEmpty && bikeGpsIds.contains(gps)) ||
        (number.isNotEmpty && bikeNumbers.contains(number))) {
      return LiveVehicleType.bike;
    }
    return liveVehicleTypeFromTraccarCategory(traccarCategory);
  }

  // A bike doc that is really one of the trucks (its GPS Device ID or its
  // number is on a truck) — shown once, as the truck, never as a bike.
  bool bikeDocIsReallyTruck(Map<String, dynamic> bike) =>
      resolve(gpsDeviceId: bike['gpsDeviceId'] as String?, vehicleNumber: (bike['bikeNumber'] ?? '').toString()) ==
      LiveVehicleType.truck;
}

// Which marker each Traccar device (by uniqueId) gets on the map: one
// entry per device, type from LiveVehicleIndex. Devices that are neither a
// registered truck nor a registered bike are left out (as before — they
// have no vehicle number/bill to show).
Map<String, ({LiveVehicleType type, String number})> resolveLiveTrackedVehicles({
  required Iterable<Map<String, dynamic>> devices,
  required Iterable<Map<String, dynamic>> trucks,
  required Iterable<Map<String, dynamic>> bikes,
}) {
  final index = LiveVehicleIndex.fromData(trucks: trucks, bikes: bikes);
  final truckByGps = <String, String>{};
  for (final t in trucks) {
    final gps = (t['gpsDeviceId'] ?? '').toString().trim();
    if (gps.isNotEmpty) truckByGps[gps] = (t['truckNumber'] ?? '').toString();
  }
  final bikeByGps = <String, String>{};
  for (final b in bikes) {
    final gps = (b['gpsDeviceId'] ?? '').toString().trim();
    if (gps.isNotEmpty) bikeByGps[gps] = (b['bikeNumber'] ?? '').toString();
  }
  final out = <String, ({LiveVehicleType type, String number})>{};
  for (final device in devices) {
    final uniqueId = device['uniqueId'];
    if (uniqueId is! String || uniqueId.trim().isEmpty) continue;
    final gps = uniqueId.trim();
    final type = index.resolve(
      gpsDeviceId: gps,
      vehicleNumber: (device['name'] ?? '').toString(),
      traccarCategory: device['category'] as String?,
    );
    if (type == LiveVehicleType.truck && truckByGps.containsKey(gps)) {
      out[uniqueId] = (type: type, number: truckByGps[gps]!);
    } else if (type == LiveVehicleType.bike && bikeByGps.containsKey(gps)) {
      out[uniqueId] = (type: type, number: bikeByGps[gps]!);
    }
  }
  return out;
}

// The canvas-drawn map marker, as a widget for lists/panels — the same
// paintLiveTruckIcon/paintLiveBikeIcon the GoogleMap markers are made from.
class LiveVehicleIcon extends StatelessWidget {
  final LiveVehicleType type;
  final double size;
  const LiveVehicleIcon({super.key, required this.type, this.size = 32});

  @override
  Widget build(BuildContext context) {
    if (type == LiveVehicleType.unknown) {
      return Icon(Icons.place, size: size, color: Colors.grey[700]);
    }
    return SizedBox.square(
      dimension: size,
      child: CustomPaint(painter: _LiveVehicleIconPainter(type)),
    );
  }
}

class _LiveVehicleIconPainter extends CustomPainter {
  final LiveVehicleType type;
  _LiveVehicleIconPainter(this.type);

  @override
  void paint(Canvas canvas, Size size) {
    canvas.save();
    canvas.scale(size.width / 100, size.height / 100);
    if (type == LiveVehicleType.truck) {
      paintLiveTruckIcon(canvas);
    } else {
      paintLiveBikeIcon(canvas);
    }
    canvas.restore();
  }

  @override
  bool shouldRepaint(_LiveVehicleIconPainter old) => old.type != type;
}

void paintLiveTruckIcon(Canvas canvas) {
  const size = 100.0;
  const center = Offset(size / 2, size / 2);
  // Truck silhouette geometry (side profile) — cargo box (taller, rear)
  // overlapping a cab (shorter, front), which is what actually produces
  // the "L-shaped" truck outline: two rounded rects sharing an edge
  // rather than a real Path boolean union, since both are filled with
  // no visible seam between them.
  final cargoRRect = RRect.fromRectAndRadius(
    const Rect.fromLTRB(40, 28, 86, 62),
    const Radius.circular(6),
  );
  final cabRRect = RRect.fromRectAndRadius(
    const Rect.fromLTRB(16, 40, 44, 62),
    const Radius.circular(6),
  );
  const windshieldRect = Rect.fromLTRB(19, 43, 37, 51);
  const leftWheelCenter = Offset(28, 66);
  const rightWheelCenter = Offset(74, 66);
  const wheelRadius = 8.0;

  // Slight Canvas.skew() applied to the whole truck (body + wheels),
  // for a Google-Maps-style angled/leaning illusion rather than a true
  // isometric 3D model.
  canvas.save();
  canvas.translate(center.dx, center.dy);
  canvas.skew(-0.12, 0);
  canvas.translate(-center.dx, -center.dy);

  // Drop shadow — one combined silhouette path (cargo + cab + both
  // wheels) so it reads as a single "floating above the map" shadow
  // rather than three separate ones.
  final silhouettePath = Path()
    ..addRRect(cargoRRect)
    ..addRRect(cabRRect)
    ..addOval(Rect.fromCircle(center: leftWheelCenter, radius: wheelRadius))
    ..addOval(
      Rect.fromCircle(center: rightWheelCenter, radius: wheelRadius),
    );
  canvas.drawShadow(silhouettePath, Colors.black, 6, false);

  // Cargo body — primary brand truck color (matches Manage Trucks/
  // Vehicle Registration's existing deepOrange theming; AppTheme has no
  // literal orange/amber constant to reuse). Lighter top / darker
  // bottom gradient for the "light hits the top" 3D depth illusion.
  final cargoPaint = Paint()
    ..shader = ui.Gradient.linear(
      Offset(cargoRRect.center.dx, cargoRRect.top),
      Offset(cargoRRect.center.dx, cargoRRect.bottom),
      [Colors.deepOrange.shade300, Colors.deepOrange.shade800],
    );
  canvas.drawRRect(cargoRRect, cargoPaint);

  // Cab — darker navy shade, same top-light/bottom-dark gradient
  // treatment as the cargo body.
  final cabPaint = Paint()
    ..shader = ui.Gradient.linear(
      Offset(cabRRect.center.dx, cabRRect.top),
      Offset(cabRRect.center.dx, cabRRect.bottom),
      [
        Color.lerp(AppTheme.primaryMid, Colors.white, 0.15)!,
        AppTheme.primaryDark,
      ],
    );
  canvas.drawRRect(cabRRect, cabPaint);

  // Windshield — a lighter accent-color stroke standing in for the
  // window frame/glass line called for in the design.
  final windshieldPaint = Paint()
    ..color = AppTheme.accent
    ..style = PaintingStyle.stroke
    ..strokeWidth = 2;
  canvas.drawRRect(
    RRect.fromRectAndRadius(windshieldRect, const Radius.circular(2)),
    windshieldPaint,
  );

  // Wheels — dark tires with a lighter hub circle for a touch of detail
  // without overcomplicating the silhouette.
  final tirePaint = Paint()..color = const Color(0xFF212121);
  final hubPaint = Paint()..color = const Color(0xFF616161);
  for (final wheelCenter in [leftWheelCenter, rightWheelCenter]) {
    canvas.drawCircle(wheelCenter, wheelRadius, tirePaint);
    canvas.drawCircle(wheelCenter, wheelRadius * 0.45, hubPaint);
  }

  // White outline around the whole silhouette so it stands out against
  // the map background.
  final borderPaint = Paint()
    ..color = Colors.white
    ..style = PaintingStyle.stroke
    ..strokeWidth = 2;
  canvas.drawRRect(cargoRRect, borderPaint);
  canvas.drawRRect(cabRRect, borderPaint);
  for (final wheelCenter in [leftWheelCenter, rightWheelCenter]) {
    canvas.drawCircle(wheelCenter, wheelRadius, borderPaint);
  }
  canvas.restore();
}

void paintLiveBikeIcon(Canvas canvas) {
  const leftWheelCenter = Offset(32, 66);
  const rightWheelCenter = Offset(68, 66);
  const seatPoint = Offset(50, 34);
  const wheelRadius = 14.0;

  // Simple two-wheeler frame — seat post + handlebar mast + connecting
  // bar — rather than a literal motorbike illustration, same "reads
  // clearly at marker size" goal as the truck icon's simplified
  // cab/cargo shapes.
  final framePaint = Paint()
    ..color = Colors.blue.shade700
    ..style = PaintingStyle.stroke
    ..strokeWidth = 6
    ..strokeCap = StrokeCap.round;
  canvas.drawLine(leftWheelCenter, seatPoint, framePaint);
  canvas.drawLine(rightWheelCenter, seatPoint, framePaint);
  canvas.drawLine(leftWheelCenter, rightWheelCenter, framePaint);

  final seatPaint = Paint()..color = Colors.blue.shade900;
  canvas.drawRRect(
    RRect.fromRectAndRadius(
      const Rect.fromLTRB(40, 30, 60, 38),
      const Radius.circular(3),
    ),
    seatPaint,
  );

  // Wheels — dark tires with a lighter hub, same treatment as the
  // truck icon's own wheels for visual consistency between the two.
  final tirePaint = Paint()..color = const Color(0xFF212121);
  final hubPaint = Paint()..color = Colors.blue.shade200;
  for (final wheelCenter in [leftWheelCenter, rightWheelCenter]) {
    canvas.drawCircle(wheelCenter, wheelRadius, tirePaint);
    canvas.drawCircle(wheelCenter, wheelRadius * 0.4, hubPaint);
  }

  // White outline so it stands out against the map background, same
  // purpose as the truck icon's own border.
  final borderPaint = Paint()
    ..color = Colors.white
    ..style = PaintingStyle.stroke
    ..strokeWidth = 2;
  for (final wheelCenter in [leftWheelCenter, rightWheelCenter]) {
    canvas.drawCircle(wheelCenter, wheelRadius, borderPaint);
  }
}

class LiveTrackingScreen extends StatefulWidget {
  const LiveTrackingScreen({super.key});

  @override
  State<LiveTrackingScreen> createState() => _LiveTrackingScreenState();
}

class _LiveTrackingScreenState extends State<LiveTrackingScreen>
    with TickerProviderStateMixin {
  // See dispose() — guards the marker-glide callbacks against running
  // (and double-disposing their controller) after the screen is gone.
  bool _disposed = false;

  static const String _traccarUsername = 'it.noda.main01@gmail.com';
  static const String _traccarPassword = 'IT@2026';

  static const CameraPosition _initialCameraPosition = CameraPosition(
    target: LatLng(7.8731, 80.7718),
    zoom: 8,
  );

  // Stable identity for the GoogleMap platform view across every rebuild
  // (poll ticks, icon-ready/error-banner toggles, isWide changes) — a
  // GlobalKey created ONCE per State (not inline in build(), which would
  // make a brand new key — and therefore a brand new Element — every
  // single build) gives Flutter the strongest possible guarantee that this
  // exact Element/platform view is preserved, on top of (not instead of)
  // the structural body fix in build() below.
  final GlobalKey _mapKey = GlobalKey();
  BitmapDescriptor? _truckIcon;
  Timer? _refreshTimer;
  // Skips a 15s tick instead of firing an overlapping fetch when the
  // previous one (against a slow Traccar server) hasn't finished yet — see
  // SingleFlightGuard's doc comment.
  final _refreshGuard = SingleFlightGuard();
  Set<Marker> _markers = {};
  // Set by tapping a truck marker (see _onTruckTapped) and deliberately
  // never touched by _refreshPositions' periodic marker rebuild — it only
  // changes when a different truck is tapped, so it stays on screen across
  // the 15s refresh, per this feature's requirement.
  Set<Polyline> _polylines = {};
  // Loaded once in initState (see _loadSiteMarkers), not on the 15s
  // truck-position timer — site locations don't change nearly as often as
  // truck positions do, so there's no need to refetch them periodically.
  Set<Marker> _siteMarkers = {};
  String? _errorText;
  bool _iconReady = false;

  // Smooth truck marker gliding (see _animateMarkerTo/_refreshPositions):
  // last position a marker actually finished gliding to, the latest target
  // from Traccar, and what's currently on screen mid-glide, all keyed by
  // the truck's gpsDeviceId uniqueId — plus one AnimationController per
  // truck currently animating, and the marker metadata (truckNumber/
  // deviceId/speed) needed to rebuild the Marker objects from just the
  // positions above.
  final Map<String, LatLng> _previousPositions = {};
  final Map<String, LatLng> _targetPositions = {};
  final Map<String, LatLng> _displayedPositions = {};
  final Map<String, AnimationController> _markerAnimationControllers = {};
  Map<String, _TruckMarkerInfo> _truckMarkerInfo = {};
  // PART A (isolated addition) — bikes on the same map, with their own
  // icon/gliding state fully separate from the truck maps above (not
  // reusing them, even though both are keyed by gpsDeviceId uniqueId and
  // could in principle share storage) specifically so nothing here can
  // collide with or alter the existing truck stale-id cleanup/glide logic.
  BitmapDescriptor? _bikeIcon;
  final Map<String, LatLng> _bikePreviousPositions = {};
  final Map<String, LatLng> _bikeTargetPositions = {};
  final Map<String, LatLng> _bikeDisplayedPositions = {};
  final Map<String, AnimationController> _bikeMarkerAnimationControllers = {};
  Map<String, _BikeMarkerInfo> _bikeMarkerInfo = {};
  // Bill number of each truck's current active load, by truckNumber — see
  // _refreshPositions' activeLoadsSnap query. Absent entry means that truck
  // has no active load right now.
  Map<String, String> _activeBillByTruckNumber = {};

  // Progressive route-drawing animation (see _animateRoute/_onTruckTapped).
  List<LatLng> _fullRoutePoints = [];
  List<LatLng> _animatedRoutePoints = [];
  Timer? _routeAnimationTimer;
  String? _activeRouteTruckNumber;
  // Which exact work_record's route should keep being re-fetched/extended
  // on every 15s _refreshPositions cycle while it's still active — set on
  // Truck Tap / sidebar Bill Select, cleared once that specific record
  // completes (see _refreshPositions and
  // _onTruckTapped/_onSidebarBillSelected). Deliberately the document
  // reference, not just a truck number: a truck can pick up a second
  // active load while an older one for that same truck is still the one
  // displayed, and keying only on truck number would silently start
  // showing the newer load's route/KM under the older bill's still-open
  // card. Distinct from _activeRouteTruckNumber above, which _animateRoute
  // sets on every draw regardless of whether live extension continues.
  DocumentReference<Map<String, dynamic>>? _selectedRouteRecordRef;
  String? _selectedRouteTruckNumber;
  // Live Total KM for whichever bill the sidebar has selected, computed
  // from the same position-history fetch _drawRouteForTruck already does
  // for the route polyline — no separate Traccar call. Passed down into
  // _LiveTrackingSidebar as liveKmUpdate; null while nothing's selected yet
  // or briefly right after a new selection, before the first fetch lands.
  double? _liveTotalKmForSelectedRoute;
  // Real-time completion notification (see
  // AutoArrivalDetectionService.onLoadCompleted / _onLoadCompleted below).
  StreamSubscription<LoadCompletionEvent>? _loadCompletionSubscription;

  // ---- VEHICLE SPEED (isolated feature) ----
  // Deliberately its own state, never read or written by anything above
  // this point — see build()'s doc comment for the necessary render-time
  // touches (swapping which marker/polyline Sets go to GoogleMap) and
  // _refreshPositions' own isolated "VEHICLE SPEED" block below for the
  // live-extension touch (an ADDED block, not a modification of the
  // existing truck/bike/bill logic already in that method).
  bool _speedModeActive = false;
  Set<Polyline> _speedPolylines = {};
  // Selected vehicle, reported up by SpeedVehiclePicker's onVehicleChanged
  // whenever it changes (including back to null) — gpsDeviceId is the
  // Traccar uniqueId, the same key _truckMarkerInfo/_bikeMarkerInfo/
  // _displayedPositions/_bikeDisplayedPositions already use, so the
  // selected vehicle's live marker/position can be looked up directly
  // without any new Traccar call. deviceId is the resolved numeric Traccar
  // id, needed for the live-extension Traccar call in _refreshPositions.
  String? _speedSelectedVehicleId; // Firestore doc id (trucks/bikes)
  bool _speedSelectedIsBike = false;
  String? _speedSelectedGpsDeviceId;
  int? _speedSelectedDeviceId;
  DateTime? _speedSelectedDay;
  bool _speedSelectedIsToday = false;
  // Live-extension bookkeeping (today only) — the fixTime/point/band of the
  // most recently drawn point, so the next 15s cycle knows exactly where to
  // resume fetching from and whether to continue the last Polyline or
  // start a new one. Reset whenever the selected vehicle or day changes
  // (PART 5's requirement) so a stale continuation can never happen.
  DateTime? _speedLastFixTime;
  LatLng? _speedLastPoint;
  Color? _speedLastBandColor;
  // Current live speed for the on-map badge — updated by both the initial
  // load (_onSpeedRouteReady) and every live-extension cycle.
  double? _speedLiveSpeedKmh;
  // False when the latest point had no numeric speed (badge shows '-').
  bool _speedLiveHasSpeed = true;

  @override
  void initState() {
    super.initState();
    _loadCompletionSubscription = AutoArrivalDetectionService.onLoadCompleted
        .listen(_onLoadCompleted);
    // No frame-timing dependency here — unlike the earlier
    // RepaintBoundary/toImage() approach (which needed the widget tree
    // fully painted first, via addPostFrameCallback, and still hit
    // "Assertion failed: !debugNeedsPaint is not true" because
    // RenderRepaintBoundary.toImage() can run before paint is actually
    // complete), drawing straight onto a ui.PictureRecorder/Canvas has no
    // widget tree to wait on, so this can run immediately. dart:ui's Canvas
    // API is cross-platform (not web-only), so this runs the same way on
    // Android — see build()'s doc comment for the same reasoning applied to
    // the map itself.
    _generateTruckIcon();
    _loadSiteMarkers();
    // PART A (isolated addition) — independent of _generateTruckIcon: does
    // not touch _iconReady or start any timer itself (that stays solely
    // _generateTruckIcon's job, unchanged).
    _generateBikeIcon();
  }

  @override
  void dispose() {
    // Set BEFORE disposing the controllers: disposing one cancels its
    // ticker, which fires its whenCompleteOrCancel callback synchronously —
    // that callback used to find the controller still in the map and
    // dispose it a second time ("AnimationController.dispose() called
    // more than once"). The maps are also emptied first for the same
    // reason.
    _disposed = true;
    _refreshTimer?.cancel();
    _routeAnimationTimer?.cancel();
    _loadCompletionSubscription?.cancel();
    final controllers = [
      ..._markerAnimationControllers.values,
      ..._bikeMarkerAnimationControllers.values,
    ];
    _markerAnimationControllers.clear();
    _bikeMarkerAnimationControllers.clear();
    for (final controller in controllers) {
      controller.dispose();
    }
    super.dispose();
  }

  void _onLoadCompleted(LoadCompletionEvent event) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        backgroundColor: Colors.green[700],
        duration: const Duration(seconds: 5),
        content: Row(
          children: [
            const Icon(Icons.check_circle, color: Colors.white),
            const SizedBox(width: 12),
            Expanded(
              child: Text(
                '✅ Load Completed! Truck ${event.truckNumber} - '
                'Bill ${event.billNumber} - Unloaded at ${event.siteName}',
                style: const TextStyle(color: Colors.white),
              ),
            ),
          ],
        ),
      ),
    );
  }

  // Builds the custom truck marker icon by drawing directly on a
  // dart:ui Canvas (PictureRecorder -> Canvas -> Picture -> Image -> PNG
  // bytes) instead of rasterizing a widget via RepaintBoundary — sidesteps
  // widget-tree paint timing entirely. Runs once (cached in _truckIcon, not
  // regenerated on every 15s refresh), then starts the position-refresh
  // timer.
  Future<void> _generateTruckIcon() async {
    try {
      final recorder = ui.PictureRecorder();
      final canvas = Canvas(recorder);
      const size = 100.0;
      // Same drawing as LiveVehicleIcon in the lists (see paintLiveTruckIcon).
      paintLiveTruckIcon(canvas);

      final picture = recorder.endRecording();
      final image = await picture.toImage(size.toInt(), size.toInt());
      final byteData = await image.toByteData(format: ui.ImageByteFormat.png);
      if (byteData == null) return;
      final bytes = byteData.buffer.asUint8List();
      if (!mounted) return;
      setState(() {
        // BitmapDescriptor.bytes replaces the deprecated
        // BitmapDescriptor.fromBytes — same result, PNG bytes in, usable as
        // a Marker.icon.
        _truckIcon = BitmapDescriptor.bytes(bytes);
        _iconReady = true;
      });
    } catch (e) {
      debugPrint('Failed to generate truck marker icon: $e');
      if (mounted) setState(() => _iconReady = true);
    }
    unawaited(_refreshGuard.run(_refreshPositions));
    _refreshTimer = Timer.periodic(
      const Duration(seconds: 15),
      (_) => _refreshGuard.run(_refreshPositions),
    );
  }

  // PART A (isolated addition) — same Canvas/PictureRecorder pattern as
  // _generateTruckIcon above, but a distinct, simpler two-wheeler
  // silhouette in a different color so a bike is never mistaken for a
  // truck on the map. Deliberately does not touch _iconReady or start the
  // refresh timer — both stay solely _generateTruckIcon's responsibility,
  // unchanged. Falls back to the platform default marker until this
  // finishes (or if it fails), same as _truckIcon does before it's ready.
  Future<void> _generateBikeIcon() async {
    try {
      final recorder = ui.PictureRecorder();
      final canvas = Canvas(recorder);
      const size = 100.0;

      paintLiveBikeIcon(canvas);

      final picture = recorder.endRecording();
      final image = await picture.toImage(size.toInt(), size.toInt());
      final byteData = await image.toByteData(format: ui.ImageByteFormat.png);
      if (byteData == null) return;
      final bytes = byteData.buffer.asUint8List();
      if (!mounted) return;
      setState(() => _bikeIcon = BitmapDescriptor.bytes(bytes));
    } catch (e) {
      debugPrint('Failed to generate bike marker icon: $e');
    }
  }

  // TEMPORARY speed audit log (kDebugMode only — compiled out of release
  // builds). Compares the raw Traccar /api/positions values with what the
  // app shows, for the first few trucks plus BLO-8390 / 9210188420.
  // Remove once the speed issue is confirmed fixed on real data.
  static const Set<String> _kSpeedDebugWatch = {'BLO-8390', '9210188420'};
  int _speedDebugLogged = 0;
  void _debugLogTruckSpeed(
    String truckNumber,
    String uniqueId,
    Map<String, dynamic> position,
    LiveSpeedReading speed,
  ) {
    if (!kDebugMode) return;
    final watched =
        _kSpeedDebugWatch.contains(normalizeVehicleNumber(truckNumber)) ||
        _kSpeedDebugWatch.contains(uniqueId.trim());
    if (!watched && _speedDebugLogged >= 4) return;
    if (!watched) _speedDebugLogged++;
    final attrs = position['attributes'];
    final age = speed.fixTime == null
        ? '?'
        : '${DateTime.now().difference(speed.fixTime!).inSeconds}s';
    debugPrint(
      '[SPEED_DEBUG] $truckNumber uniqueId=$uniqueId '
      'deviceId=${position['deviceId']} '
      'traccarSpeed=${position['speed']} (knots, '
      '${position['speed'].runtimeType}) '
      'fixTime=${position['fixTime']} age=$age valid=${position['valid']} '
      'motion=${attrs is Map ? attrs['motion'] : null} '
      'ignition=${attrs is Map ? attrs['ignition'] : null} '
      '-> app=${speed.label()} (${speed.band().name})',
    );
  }

  Future<void> _refreshPositions() async {
    _speedDebugLogged = 0;
    try {
      final positions = await TraccarService.fetchPositions(
        username: _traccarUsername,
        password: _traccarPassword,
      );
      // Shared with VehicleKmCache's device-list cache (2 min TTL) rather
      // than a fresh /api/devices call every 15s tick — see
      // AutoArrivalDetectionService.checkAllActiveLoads' matching comment,
      // which runs on this same timer and needs the identical list.
      final devices = await VehicleKmCache.devices();
      // position.deviceId is Traccar's internal numeric device id, not the
      // uniqueId/Identifier string stored on trucks/{id}.gpsDeviceId — this
      // map bridges the two (see TraccarService.fetchDevices' doc comment).
      final uniqueIdByDeviceId = <int, String>{
        for (final device in devices)
          if (device['id'] is int && device['uniqueId'] is String)
            device['id'] as int: device['uniqueId'] as String,
      };

      final trucksSnap = await FirebaseFirestore.instance
          .collection('trucks')
          .get();
      // Bikes are read here too (was further down, same one read per
      // cycle) so every device resolves to exactly ONE type before any
      // marker is built — see resolveLiveTrackedVehicles. A GPS device /
      // number that is on a truck stays a truck even if it was also
      // entered on a bike (it used to get a bike marker on top of it).
      final bikesSnap = await FirebaseFirestore.instance
          .collection('bikes')
          .get();
      final trackedVehicles = resolveLiveTrackedVehicles(
        devices: devices,
        trucks: trucksSnap.docs.map((d) => d.data()),
        bikes: bikesSnap.docs.map((d) => d.data()),
      );
      final truckNumberByGpsId = <String, String>{
        for (final e in trackedVehicles.entries)
          if (e.value.type == LiveVehicleType.truck) e.key: e.value.number,
      };

      // Active-load bill numbers, by truck — same isCompleted == false
      // lookup _onTruckTapped uses for a single truck, but fetched once for
      // every truck here rather than per-marker, since marker Sets get
      // rebuilt on every glide animation frame (see
      // _buildMarkersFromDisplayedPositions) and re-querying Firestore that
      // often would be wasteful. Cached in _activeBillByTruckNumber for the
      // whole 15s refresh cycle.
      final activeLoadsSnap = await FirebaseFirestore.instance
          .collectionGroup('work_records')
          .where('isCompleted', isEqualTo: false)
          .get();
      final newActiveBillByTruckNumber = <String, String>{};
      final latestLoadStartByTruckNumber = <String, Timestamp>{};
      for (final doc in activeLoadsSnap.docs) {
        final data = doc.data();
        final truckNumber = (data['truckNumber'] ?? '').toString();
        final billNumber = (data['billNumber'] ?? '').toString();
        final loadStartedAt = data['loadStartedAt'] as Timestamp?;
        if (truckNumber.isEmpty ||
            billNumber.isEmpty ||
            loadStartedAt == null) {
          continue;
        }
        final latestStart = latestLoadStartByTruckNumber[truckNumber];
        if (latestStart == null || loadStartedAt.compareTo(latestStart) > 0) {
          latestLoadStartByTruckNumber[truckNumber] = loadStartedAt;
          newActiveBillByTruckNumber[truckNumber] = billNumber;
        }
      }

      final newTargets = <String, LatLng>{};
      final newInfo = <String, _TruckMarkerInfo>{};
      for (final position in positions) {
        final deviceId = position['deviceId'];
        final lat = (position['latitude'] as num?)?.toDouble();
        final lng = (position['longitude'] as num?)?.toDouble();
        if (deviceId is! int || lat == null || lng == null) continue;
        final uniqueId = uniqueIdByDeviceId[deviceId];
        if (uniqueId == null) continue;
        final truckNumber = truckNumberByGpsId[uniqueId];
        if (truckNumber == null) continue;
        // Traccar reports speed in knots; converted (and checked for
        // staleness via fixTime) by LiveSpeedReading. No '?? 0' fallback —
        // a missing speed shows as '-', not a fake 0.
        final speed = LiveSpeedReading.fromTraccarPosition(position);
        newTargets[uniqueId] = LatLng(lat, lng);
        newInfo[uniqueId] = _TruckMarkerInfo(
          truckNumber: truckNumber,
          deviceId: deviceId,
          speed: speed,
        );
        _debugLogTruckSpeed(truckNumber, uniqueId, position, speed);
      }

      if (!mounted) return;
      _truckMarkerInfo = newInfo;
      _activeBillByTruckNumber = newActiveBillByTruckNumber;

      // Trucks no longer reporting a position — drop their tracked state
      // and cancel any in-flight glide for them.
      final staleIds = _targetPositions.keys
          .where((id) => !newTargets.containsKey(id))
          .toList();
      for (final id in staleIds) {
        _targetPositions.remove(id);
        _previousPositions.remove(id);
        _displayedPositions.remove(id);
        _markerAnimationControllers.remove(id)?.dispose();
      }

      // Glide each truck marker from its last displayed position to the
      // new one instead of jumping there instantly — see _animateMarkerTo.
      // A truck seen for the first time is placed directly, since there's
      // no previous position to glide from.
      for (final entry in newTargets.entries) {
        final uniqueId = entry.key;
        final newPos = entry.value;
        final oldTarget = _targetPositions[uniqueId];
        _targetPositions[uniqueId] = newPos;
        if (oldTarget == null) {
          _previousPositions[uniqueId] = newPos;
          _displayedPositions[uniqueId] = newPos;
          continue;
        }
        if (oldTarget.latitude == newPos.latitude &&
            oldTarget.longitude == newPos.longitude) {
          continue;
        }
        _animateMarkerTo(uniqueId, newPos);
      }

      // ---- PART A (isolated addition): bikes on the same map ----
      // Reuses the `positions`/`uniqueIdByDeviceId` already fetched above
      // for trucks — no extra Traccar call. Entirely separate state
      // (_bike*, not _truckMarkerInfo/_targetPositions/etc.) so none of
      // the truck logic above is touched or affected.
      final bikeNumberByGpsId = <String, String>{
        for (final e in trackedVehicles.entries)
          if (e.value.type == LiveVehicleType.bike) e.key: e.value.number,
      };

      final newBikeTargets = <String, LatLng>{};
      final newBikeInfo = <String, _BikeMarkerInfo>{};
      for (final position in positions) {
        final deviceId = position['deviceId'];
        final lat = (position['latitude'] as num?)?.toDouble();
        final lng = (position['longitude'] as num?)?.toDouble();
        if (deviceId is! int || lat == null || lng == null) continue;
        final uniqueId = uniqueIdByDeviceId[deviceId];
        if (uniqueId == null) continue;
        final bikeNumber = bikeNumberByGpsId[uniqueId];
        if (bikeNumber == null) continue;
        // Same conversion/staleness handling as trucks above.
        newBikeTargets[uniqueId] = LatLng(lat, lng);
        newBikeInfo[uniqueId] = _BikeMarkerInfo(
          bikeNumber: bikeNumber,
          deviceId: deviceId,
          speed: LiveSpeedReading.fromTraccarPosition(position),
        );
      }

      if (!mounted) return;
      _bikeMarkerInfo = newBikeInfo;

      // Bikes no longer reporting a position — same stale-cleanup idea as
      // trucks above, against the separate bike maps.
      final staleBikeIds = _bikeTargetPositions.keys
          .where((id) => !newBikeTargets.containsKey(id))
          .toList();
      for (final id in staleBikeIds) {
        _bikeTargetPositions.remove(id);
        _bikePreviousPositions.remove(id);
        _bikeDisplayedPositions.remove(id);
        _bikeMarkerAnimationControllers.remove(id)?.dispose();
      }

      for (final entry in newBikeTargets.entries) {
        final uniqueId = entry.key;
        final newPos = entry.value;
        final oldTarget = _bikeTargetPositions[uniqueId];
        _bikeTargetPositions[uniqueId] = newPos;
        if (oldTarget == null) {
          _bikePreviousPositions[uniqueId] = newPos;
          _bikeDisplayedPositions[uniqueId] = newPos;
          continue;
        }
        if (oldTarget.latitude == newPos.latitude &&
            oldTarget.longitude == newPos.longitude) {
          continue;
        }
        _animateBikeMarkerTo(uniqueId, newPos);
      }
      // ---- end PART A bikes block ----

      setState(() {
        _markers = _buildAllMarkers();
        _errorText = null;
      });

      // ---- VEHICLE SPEED: live route extension (PART 3, isolated) ----
      // Only runs while speed mode is on AND the selected day is Today —
      // past days are static (PART 2's requirement), so this block is a
      // pure no-op for them. Fetches only the points after the last one
      // already drawn (not the whole day again), extends _speedPolylines
      // incrementally, and updates the live speed badge. A failure here is
      // swallowed silently (next cycle just retries from the same
      // _speedLastFixTime) rather than touching _errorText, which is
      // reserved for the existing truck/bike position-refresh failures
      // above.
      if (_speedModeActive &&
          _speedSelectedIsToday &&
          _speedSelectedDeviceId != null) {
        final requestVehicleId = _speedSelectedVehicleId;
        final requestDeviceId = _speedSelectedDeviceId!;
        final requestDay = _speedSelectedDay;
        final from =
            _speedLastFixTime ??
            DateTime.now().subtract(const Duration(seconds: 20));
        try {
          final newPoints = await TraccarService.fetchPositionsWithSpeed(
            username: _traccarUsername,
            password: _traccarPassword,
            deviceId: requestDeviceId,
            from: from,
            to: DateTime.now(),
          );
          // Staleness guard — the user may have changed vehicle/day or
          // left speed mode entirely while this fetch was in flight.
          final stillCurrent =
              mounted &&
              _speedModeActive &&
              _speedSelectedIsToday &&
              _speedSelectedDeviceId == requestDeviceId &&
              _speedSelectedDay == requestDay;
          if (stillCurrent && newPoints.isNotEmpty) {
            final freshPoints = _speedLastFixTime == null
                ? newPoints
                : newPoints
                      .where(
                        (p) =>
                            (p['fixTime'] as DateTime).isAfter(
                              _speedLastFixTime!,
                            ),
                      )
                      .toList();
            if (freshPoints.isNotEmpty) {
              setState(() {
                _speedPolylines = _extendSpeedPolylines(freshPoints);
                _speedLiveSpeedKmh = freshPoints.last['speedKmh'] as double;
                _speedLiveHasSpeed = freshPoints.last['hasSpeed'] != false;
              });
              if (requestVehicleId != null && requestDay != null) {
                _SpeedVehiclePickerState.appendToCache(
                  requestVehicleId,
                  requestDay,
                  freshPoints,
                );
              }
            }
          }
        } catch (_) {
          // Silent — see doc comment above.
        }
      }

      // Awaited HERE, before the live route extension block below, rather
      // than fired-and-forgotten at the end of this cycle (where it used to
      // sit) — markers above are already on-screen by this point, so
      // awaiting it doesn't delay anything the user perceives, but it
      // closes a real lag window: with the old ordering, this cycle's own
      // arrival detection couldn't possibly land before this cycle's own
      // "is this record still active" re-check ran, so an arrival was
      // always at least one 15s cycle late to freeze the route/KM. Now the
      // freeze can happen on the very same cycle the truck arrives.
      await AutoArrivalDetectionService.checkAllActiveLoads();

      // Live route extension for whichever specific work_record is
      // currently selected (Truck Tap / sidebar Bill Select — see
      // _selectedRouteRecordRef's doc comment) — re-fetches and redraws its
      // route on every cycle so the line keeps up with the truck instead
      // of going stale. Re-reads this one record directly (a single cheap
      // Firestore document get, not a Traccar call) rather than reusing
      // latestLoadStartByTruckNumber above, since that map reflects
      // "whichever load is newest for this truck right now" and would
      // silently swap to a different, newer load if the truck picks one up
      // while this older record is still the one displayed — which is
      // exactly what caused route/KM to mix between a truck's older and
      // newer loads.
      final selectedRouteRecordRef = _selectedRouteRecordRef;
      if (selectedRouteRecordRef != null) {
        final freshSnap = await selectedRouteRecordRef.get();
        final freshData = freshSnap.data();
        final isStillActive =
            freshData != null && freshData['isCompleted'] == false;
        // Temporary — confirms, per cycle, exactly which record the route
        // guard is watching and what it just read for isCompleted, so a
        // report of "route doesn't stop" can be told apart from "route IS
        // stopping, but for a different/stale record than the one the user
        // is watching complete." Remove once confirmed.
        print(
          '[ROUTE_STOP_DEBUG] Tracking ${selectedRouteRecordRef.path}, '
          'isCompleted=${freshData?['isCompleted']}, '
          'isStillActive=$isStillActive',
        );
        if (!isStillActive) {
          // Completed (or the record is gone) since the last cycle — stop
          // extending it. The sidebar's last-pushed route/KM values simply
          // stop updating, freezing at whatever they were.
          _selectedRouteRecordRef = null;
          _selectedRouteTruckNumber = null;
        } else {
          final loadStartedAt = freshData['loadStartedAt'] as Timestamp?;
          final truckNumber = _selectedRouteTruckNumber;
          if (loadStartedAt != null && truckNumber != null) {
            _TruckMarkerInfo? info;
            for (final candidate in newInfo.values) {
              if (candidate.truckNumber == truckNumber) {
                info = candidate;
                break;
              }
            }
            if (info != null) {
              unawaited(
                _drawRouteForTruck(
                  recordRef: selectedRouteRecordRef,
                  truckNumber: truckNumber,
                  deviceId: info.deviceId,
                  from: loadStartedAt.toDate(),
                  to: DateTime.now(),
                ),
              );
            }
          }
        }
      }
    } catch (e) {
      if (!mounted) return;
      // Deliberately never touches _markers/_polylines/_siteMarkers here —
      // whatever was on screen from the last successful cycle stays up,
      // never a blank map, while this banner explains why it's stale.
      setState(() => _errorText = 'Live data delayed, retrying — $e');
    }
  }

  // Glides a single truck marker from wherever it's currently displayed to
  // [target] over ~1 second, instead of jumping there instantly. Each truck
  // gets its own AnimationController (tracked in
  // _markerAnimationControllers) so multiple trucks can glide at the same
  // time without interfering with each other. If this truck is already
  // mid-glide when a newer position arrives, the old controller is disposed
  // and the new glide starts from the current on-screen position rather
  // than stacking animations.
  void _animateMarkerTo(String uniqueId, LatLng target) {
    // A position refresh can resolve after the screen is gone.
    if (_disposed || !mounted) return;
    _markerAnimationControllers.remove(uniqueId)?.dispose();
    final from = _displayedPositions[uniqueId] ?? target;
    final controller = AnimationController(
      duration: const Duration(seconds: 1),
      vsync: this,
    );
    _markerAnimationControllers[uniqueId] = controller;
    final animation = Tween<double>(
      begin: 0.0,
      end: 1.0,
    ).animate(CurvedAnimation(parent: controller, curve: Curves.easeInOut));
    animation.addListener(() {
      if (!mounted) return;
      final t = animation.value;
      setState(() {
        _displayedPositions[uniqueId] = LatLng(
          from.latitude + (target.latitude - from.latitude) * t,
          from.longitude + (target.longitude - from.longitude) * t,
        );
        // Merged with bike markers (see _buildAllMarkers) so a truck's own
        // glide frame doesn't momentarily blank out bike markers already on
        // screen — _buildMarkersFromDisplayedPositions itself is unchanged.
        _markers = _buildAllMarkers();
      });
    });
    controller.forward().whenCompleteOrCancel(() {
      // Only finalize/dispose if this is still the tracked controller for
      // this truck — a newer glide may have already replaced (and
      // disposed) it before this fires.
      if (_disposed) return;
      if (_markerAnimationControllers[uniqueId] == controller) {
        _previousPositions[uniqueId] = target;
        _markerAnimationControllers.remove(uniqueId)?.dispose();
      }
    });
  }

  // PART A (isolated addition) — bike equivalent of _animateMarkerTo above,
  // against the separate _bike* maps so it can never interact with truck
  // gliding state.
  void _animateBikeMarkerTo(String uniqueId, LatLng target) {
    if (_disposed || !mounted) return;
    _bikeMarkerAnimationControllers.remove(uniqueId)?.dispose();
    final from = _bikeDisplayedPositions[uniqueId] ?? target;
    final controller = AnimationController(
      duration: const Duration(seconds: 1),
      vsync: this,
    );
    _bikeMarkerAnimationControllers[uniqueId] = controller;
    final animation = Tween<double>(
      begin: 0.0,
      end: 1.0,
    ).animate(CurvedAnimation(parent: controller, curve: Curves.easeInOut));
    animation.addListener(() {
      if (!mounted) return;
      final t = animation.value;
      setState(() {
        _bikeDisplayedPositions[uniqueId] = LatLng(
          from.latitude + (target.latitude - from.latitude) * t,
          from.longitude + (target.longitude - from.longitude) * t,
        );
        _markers = _buildAllMarkers();
      });
    });
    controller.forward().whenCompleteOrCancel(() {
      if (_disposed) return;
      if (_bikeMarkerAnimationControllers[uniqueId] == controller) {
        _bikePreviousPositions[uniqueId] = target;
        _bikeMarkerAnimationControllers.remove(uniqueId)?.dispose();
      }
    });
  }

  // Rebuilds the truck marker Set from the current displayed positions
  // (which may be mid-glide) plus the last-fetched marker metadata — called
  // both right after a position refresh and on every animation frame while
  // a marker is gliding.
  Map<String, LiveSpeedReading> get _liveSpeedByTruckNumber => {
    for (final info in _truckMarkerInfo.values)
      normalizeVehicleNumber(info.truckNumber): info.speed,
  };

  Set<Marker> _buildMarkersFromDisplayedPositions() {
    final markers = <Marker>{};
    for (final entry in _truckMarkerInfo.entries) {
      final uniqueId = entry.key;
      final position = _displayedPositions[uniqueId];
      if (position == null) continue;
      final info = entry.value;
      final activeBillNumber = _activeBillByTruckNumber[info.truckNumber];
      final snippet = (activeBillNumber == null || activeBillNumber.isEmpty)
          ? info.speed.snippet()
          : '${info.speed.snippet()} | Bill: $activeBillNumber';
      markers.add(
        Marker(
          markerId: MarkerId(uniqueId),
          position: position,
          icon: _truckIcon ?? BitmapDescriptor.defaultMarker,
          infoWindow: InfoWindow(title: info.truckNumber, snippet: snippet),
          onTap: () => _onTruckTapped(info.truckNumber, info.deviceId),
        ),
      );
    }
    return markers;
  }

  // PART A (isolated addition) — bike equivalent of
  // _buildMarkersFromDisplayedPositions above. Deliberately no `onTap`: a
  // bike has no work_records/route/bill concept, so tapping one only shows
  // its InfoWindow (Google Maps' own default marker behavior) and triggers
  // no app logic at all, unlike a truck tap (_onTruckTapped).
  Set<Marker> _buildBikeMarkersFromDisplayedPositions() {
    final markers = <Marker>{};
    for (final entry in _bikeMarkerInfo.entries) {
      final uniqueId = entry.key;
      final position = _bikeDisplayedPositions[uniqueId];
      if (position == null) continue;
      final info = entry.value;
      markers.add(
        Marker(
          markerId: MarkerId('bike_$uniqueId'),
          position: position,
          icon: _bikeIcon ?? BitmapDescriptor.defaultMarker,
          infoWindow: InfoWindow(
            title: info.bikeNumber,
            snippet: info.speed.snippet(),
          ),
        ),
      );
    }
    return markers;
  }

  // The one shared merge point between truck and bike markers (see PART
  // A's doc comments above) — every place that used to assign
  // `_buildMarkersFromDisplayedPositions()` directly to _markers now goes
  // through this instead, so bikes always stay on screen alongside trucks
  // regardless of which one's glide/refresh triggered the rebuild.
  Set<Marker> _buildAllMarkers() => {
    ..._buildMarkersFromDisplayedPositions(),
    ..._buildBikeMarkersFromDisplayedPositions(),
  };

  // Draws the route for a truck's current active load, from when it
  // started loading up to now. Looks up the most recent incomplete
  // work_record for this truck client-side (rather than combining a
  // truckNumber equality filter with an orderBy on loadStartedAt in the
  // query itself) — a composite Firestore index for that exact shape isn't
  // guaranteed to exist on this project, the same constraint
  // _showEndDayDialog already works around the same way.
  Future<void> _onTruckTapped(String truckNumber, int deviceId) async {
    try {
      final snap = await FirebaseFirestore.instance
          .collectionGroup('work_records')
          .where('truckNumber', isEqualTo: truckNumber)
          .get();

      print(
        '[ROUTE_DEBUG] work_records found for truckNumber=$truckNumber: '
        '${snap.docs.length}',
      );

      QueryDocumentSnapshot<Map<String, dynamic>>? activeLoadDoc;
      Timestamp? activeLoadStart;
      var activeLoadIsRunning = false;
      for (final doc in snap.docs) {
        final data = doc.data();
        if (data['isCompleted'] != false) continue;
        print(
          '[ROUTE_DEBUG] candidate incomplete record ${doc.id}: '
          'isLoadingCategory=${data['isLoadingCategory']}, '
          'status=${data['status']}, '
          'loadStartedAt=${data['loadStartedAt']}',
        );
        final loadStartedAt = data['loadStartedAt'] as Timestamp?;
        if (loadStartedAt == null) continue;
        // A truck can genuinely have several isCompleted: false records at
        // once — starting any new task only pauses the previous one (see
        // _pauseRunningRecord), it doesn't complete it. Picking purely by
        // "most recently started" could jump to a brand-new task the
        // moment it's created, even while an older one is still the
        // actively-running record the user means to track. A running
        // record always wins over a merely-paused one; "most recently
        // started" only breaks ties within the same tier.
        final isRunning = data['status'] == 'running';
        final isBetterCandidate =
            activeLoadDoc == null ||
            (isRunning && !activeLoadIsRunning) ||
            (isRunning == activeLoadIsRunning &&
                loadStartedAt.compareTo(activeLoadStart!) > 0);
        if (isBetterCandidate) {
          activeLoadDoc = doc;
          activeLoadStart = loadStartedAt;
          activeLoadIsRunning = isRunning;
        }
      }

      if (activeLoadDoc == null || activeLoadStart == null) {
        print(
          '[ROUTE_DEBUG] no candidate had a non-null loadStartedAt — '
          'treating as idle, no route drawn.',
        );
        // Idle truck — no active load to draw a route for, and nothing to
        // keep live-extending on future refresh cycles.
        _selectedRouteRecordRef = null;
        _selectedRouteTruckNumber = null;
        _routeAnimationTimer?.cancel();
        if (mounted) {
          setState(() {
            _polylines = {};
            _liveTotalKmForSelectedRoute = null;
          });
        }
        return;
      }

      // Tracked so _refreshPositions' 15s cycle keeps this exact record's
      // route extended while it's still active, and clears it once this
      // record (not just "whatever's active for this truck") completes.
      // Live KM reset to null here (rather than left showing the
      // previously-selected bill's figure) until this record's first fetch
      // lands inside _drawRouteForTruck below.
      // Temporary — proves whether _selectedRouteRecordRef changes between
      // cycles because of a re-tap (this print firing again with a
      // different record id) versus something else entirely. Remove once
      // confirmed.
      print(
        '[ROUTE_SELECT_DEBUG] _onTruckTapped: truck=$truckNumber, '
        'previous=${_selectedRouteRecordRef?.path}, '
        'new=${activeLoadDoc.reference.path}',
      );
      _selectedRouteRecordRef = activeLoadDoc.reference;
      _selectedRouteTruckNumber = truckNumber;
      if (mounted) setState(() => _liveTotalKmForSelectedRoute = null);
      await _drawRouteForTruck(
        recordRef: activeLoadDoc.reference,
        truckNumber: truckNumber,
        deviceId: deviceId,
        from: activeLoadStart.toDate(),
        to: DateTime.now(),
      );
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text('Failed to load route: $e')));
      }
    }
  }

  // Shared by _onTruckTapped's active-load auto-lookup above and the
  // sidebar's Bill Select flow (_onSidebarBillSelected) — fetches this
  // truck's Traccar position history for [from, to] and progressively
  // animates it onto the map via _animateRoute. Has its own try/catch since
  // the sidebar caller doesn't have _onTruckTapped's surrounding one.
  Future<void> _drawRouteForTruck({
    required DocumentReference<Map<String, dynamic>> recordRef,
    required String truckNumber,
    required int deviceId,
    required DateTime from,
    required DateTime to,
  }) async {
    try {
      // Temporary — confirms whether [from] (this record's loadStartedAt)
      // stays constant for the same record across repeated 15s-cycle
      // calls, or whether it's a different record/value each time. Remove
      // once confirmed.
      print(
        '[TIME_WINDOW_DEBUG] Record ID: ${recordRef.id}, '
        'loadStartedAt Value: $from',
      );
      print('[ROUTE_DEBUG] loadStartedAt: $from');
      print('[ROUTE_DEBUG] Fetching position history from $from to $to');
      final points = await TraccarService.fetchPositionHistory(
        username: _traccarUsername,
        password: _traccarPassword,
        deviceId: deviceId,
        from: from,
        to: to,
      );
      print('[ROUTE_DEBUG] Points returned: ${points.length}');

      if (!mounted) return;
      // Single staleness guard for BOTH the KM figure and the route
      // polyline below — a fetch for a record the user has since moved
      // away from (different bill tapped/selected, or this cycle's own
      // fresh selectedRef check in _refreshPositions already moved on)
      // must not overwrite what's currently displayed with stale data.
      // Compares the exact record reference, not just a truck number —
      // see _selectedRouteRecordRef's doc comment for why that matters.
      if (recordRef.path != _selectedRouteRecordRef?.path) return;

      // Reuses this same position-history fetch for the sidebar's live
      // Total KM figure (see _LiveTrackingSidebar.liveKmUpdate) instead of
      // a second, separate Traccar call.
      var totalMeters = 0.0;
      for (var i = 1; i < points.length; i++) {
        totalMeters += Geolocator.distanceBetween(
          points[i - 1]['latitude']!,
          points[i - 1]['longitude']!,
          points[i]['latitude']!,
          points[i]['longitude']!,
        );
      }
      setState(() => _liveTotalKmForSelectedRoute = totalMeters / 1000);

      _animateRoute(
        truckNumber,
        points.map((p) => LatLng(p['latitude']!, p['longitude']!)).toList(),
      );
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text('Failed to load route: $e')));
      }
    }
  }

  // Sidebar's Bill Select callback (see _LiveTrackingSidebar.onBillSelected)
  // — resolves the truck's numeric Traccar device id from the same
  // _truckMarkerInfo the map markers already use (populated by
  // _refreshPositions' 15s cycle), rather than a fresh fetchDevices() call.
  void _onSidebarBillSelected(
    String truckNumber,
    DateTime from,
    DateTime to,
    DocumentReference<Map<String, dynamic>> recordRef,
  ) {
    _TruckMarkerInfo? info;
    for (final candidate in _truckMarkerInfo.values) {
      if (candidate.truckNumber == truckNumber) {
        info = candidate;
        break;
      }
    }
    if (info == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('No live GPS data available for this truck.'),
        ),
      );
      return;
    }
    // Tracked so _refreshPositions' 15s cycle keeps this exact record's
    // route extended while it's still active. If the selected bill was
    // already completed (a historical to, not "now"), the very next
    // refresh cycle's own isCompleted check on this record clears this
    // again — see _refreshPositions.
    // Temporary — see _onTruckTapped's matching print. Remove once
    // confirmed.
    print(
      '[ROUTE_SELECT_DEBUG] _onSidebarBillSelected: truck=$truckNumber, '
      'previous=${_selectedRouteRecordRef?.path}, new=${recordRef.path}',
    );
    _selectedRouteRecordRef = recordRef;
    _selectedRouteTruckNumber = truckNumber;
    // Reset rather than leaving the previously-selected bill's figure
    // showing until this bill's own fetch lands inside _drawRouteForTruck.
    setState(() => _liveTotalKmForSelectedRoute = null);
    _drawRouteForTruck(
      recordRef: recordRef,
      truckNumber: truckNumber,
      deviceId: info.deviceId,
      from: from,
      to: to,
    );
  }

  // Tick interval for _animateRoute — fixed and small enough (within the
  // 30-50ms range) to look smooth. How many points get added per tick is
  // derived from the route length (see _animateRoute) so the whole route
  // finishes drawing in roughly this duration regardless of how many points
  // it has.
  static const _routeAnimationTick = Duration(milliseconds: 40);
  static const _routeAnimationDuration = Duration(milliseconds: 1500);

  // Progressively draws the route polyline point-by-point instead of
  // setting the whole thing at once, so it reads as the route being drawn
  // live rather than appearing instantly. When this is called again for the
  // same truck with a longer point list that still starts where the
  // current one does (see _refreshPositions' live route extension), it
  // continues animating from wherever the line currently ends instead of
  // restarting from scratch — otherwise every 15s refresh would flash the
  // whole route back to a single point before redrawing it.
  void _animateRoute(String truckNumber, List<LatLng> fullPoints) {
    final isExtendingSameRoute =
        truckNumber == _activeRouteTruckNumber &&
        _fullRoutePoints.isNotEmpty &&
        fullPoints.length >= _fullRoutePoints.length &&
        fullPoints.first.latitude == _fullRoutePoints.first.latitude &&
        fullPoints.first.longitude == _fullRoutePoints.first.longitude;
    final previousAnimatedCount = _animatedRoutePoints.length;

    _routeAnimationTimer?.cancel();
    _activeRouteTruckNumber = truckNumber;
    _fullRoutePoints = fullPoints;

    if (_fullRoutePoints.length <= 1) {
      _animatedRoutePoints = _fullRoutePoints;
      setState(() => _polylines = _buildRoutePolylines());
      return;
    }

    final totalTicks =
        (_routeAnimationDuration.inMilliseconds /
                _routeAnimationTick.inMilliseconds)
            .ceil();
    final pointsPerTick = max(1, (_fullRoutePoints.length / totalTicks).ceil());

    final startCount = isExtendingSameRoute
        ? min(previousAnimatedCount, _fullRoutePoints.length)
        : 1;
    _animatedRoutePoints = _fullRoutePoints.sublist(0, max(1, startCount));
    setState(() => _polylines = _buildRoutePolylines());

    if (_animatedRoutePoints.length >= _fullRoutePoints.length) return;

    _routeAnimationTimer = Timer.periodic(_routeAnimationTick, (timer) {
      if (!mounted) {
        timer.cancel();
        return;
      }
      final nextCount = min(
        _animatedRoutePoints.length + pointsPerTick,
        _fullRoutePoints.length,
      );
      setState(() {
        _animatedRoutePoints = _fullRoutePoints.sublist(0, nextCount);
        _polylines = _buildRoutePolylines();
      });
      if (nextCount >= _fullRoutePoints.length) {
        timer.cancel();
      }
    });
  }

  Set<Polyline> _buildRoutePolylines() {
    if (_animatedRoutePoints.isEmpty || _activeRouteTruckNumber == null) {
      return {};
    }
    return {
      Polyline(
        polylineId: PolylineId(_activeRouteTruckNumber!),
        points: _animatedRoutePoints,
        color: Colors.blue,
        width: 4,
      ),
    };
  }

  // One-time fetch (not a stream, not on the truck-position timer) — a
  // plain full-collection get() + client-side latitude/longitude filter
  // rather than a Firestore query, since Firestore only allows one
  // inequality/not-null filter per query and this needs both fields set.
  // "sites" is a small reference collection, so fetching it whole is cheap.
  Future<void> _loadSiteMarkers() async {
    try {
      final snap = await FirebaseFirestore.instance.collection('sites').get();
      print('[SITE_MARKER_DEBUG] Total sites fetched: ${snap.docs.length}');
      final markers = <Marker>{};
      var validCount = 0;
      for (final doc in snap.docs) {
        final data = doc.data();
        final siteName = (data['name'] ?? '').toString();
        // siteGpsLocations() handles both the newer multi-entrance
        // gpsLocations list and the older single latitude/longitude
        // fields — one marker per entry, so a multi-gate site shows every
        // gate on the map, not just one point.
        final locations = siteGpsLocations(data);
        print(
          '[SITE_MARKER_DEBUG] Site: $siteName, '
          'gpsLocations: ${locations.length}, '
          'canBeLoadingSite: ${data['canBeLoadingSite']}',
        );
        if (locations.isEmpty) continue;
        // Defaults to true when absent (see _addSite), matching every other
        // loading-capability check already in this codebase.
        final canBeLoadingSite = data['canBeLoadingSite'] != false;
        for (var i = 0; i < locations.length; i++) {
          final lat = (locations[i]['latitude'] as num?)?.toDouble();
          final lng = (locations[i]['longitude'] as num?)?.toDouble();
          if (lat == null || lng == null) continue;
          validCount++;
          final label = (locations[i]['label'] ?? 'Location ${i + 1}')
              .toString();
          markers.add(
            Marker(
              markerId: MarkerId('site_${doc.id}_$i'),
              position: LatLng(lat, lng),
              // Loading takes priority when a site is both — green if it
              // can be loaded at all, blue otherwise (covers both the
              // unloading-only and neither case the same way).
              icon: BitmapDescriptor.defaultMarkerWithHue(
                canBeLoadingSite
                    ? BitmapDescriptor.hueGreen
                    : BitmapDescriptor.hueBlue,
              ),
              infoWindow: InfoWindow(title: '$siteName ($label)'),
              onTap: () => _showSiteLoadCountDialog(siteName),
            ),
          );
        }
      }
      print('[SITE_MARKER_DEBUG] Sites with valid coordinates: $validCount');
      if (!mounted) return;
      setState(() => _siteMarkers = markers);
      print('[SITE_MARKER_DEBUG] Final marker count: ${_siteMarkers.length}');
    } catch (e) {
      debugPrint('Failed to load site markers: $e');
    }
  }

  Future<_SiteLoadCounts> _fetchSiteLoadCounts(String siteName) async {
    // Single equality filter, same as _onTruckTapped's active-load lookup —
    // no orderBy paired with it, so no composite Firestore index risk.
    final snap = await FirebaseFirestore.instance
        .collectionGroup('work_records')
        .where('siteName', isEqualTo: siteName)
        .get();
    final today = DateTime.now();
    final todayString =
        "${today.year}-${today.month.toString().padLeft(2, '0')}-${today.day.toString().padLeft(2, '0')}";
    var todayCount = 0;
    for (final doc in snap.docs) {
      if (doc.data()['date'] == todayString) todayCount++;
    }
    return _SiteLoadCounts(total: snap.docs.length, today: todayCount);
  }

  void _showSiteLoadCountDialog(String siteName) {
    showDialog(
      context: context,
      builder: (dialogContext) => AlertDialog(
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
        title: Text(siteName),
        content: SizedBox(
          width: 260,
          child: FutureBuilder<_SiteLoadCounts>(
            future: _fetchSiteLoadCounts(siteName),
            builder: (context, snapshot) {
              if (snapshot.connectionState == ConnectionState.waiting) {
                return const Padding(
                  padding: EdgeInsets.symmetric(vertical: 24),
                  child: Center(
                    child: Column(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        CircularProgressIndicator(),
                        SizedBox(height: 12),
                        Text('Loading counts...'),
                      ],
                    ),
                  ),
                );
              }
              if (snapshot.hasError) {
                return Text('Failed to load counts: ${snapshot.error}');
              }
              final counts = snapshot.data!;
              return Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    'Total Loads: ${counts.total}',
                    style: const TextStyle(
                      fontWeight: FontWeight.bold,
                      fontSize: 16,
                    ),
                  ),
                  const SizedBox(height: 8),
                  Text(
                    "Today's Loads: ${counts.today}",
                    style: const TextStyle(fontSize: 14),
                  ),
                ],
              );
            },
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext),
            child: const Text('Close'),
          ),
        ],
      ),
    );
  }

  // ---- VEHICLE SPEED (isolated feature) ----
  // Toggles speed mode on/off. Deliberately touches only this feature's own
  // state — nothing about _polylines/_selectedRouteRecordRef/_markers or
  // any other existing state is read or written here.
  void _toggleSpeedMode() {
    setState(() {
      _speedModeActive = !_speedModeActive;
      if (!_speedModeActive) {
        _speedPolylines = {};
        _speedSelectedVehicleId = null;
        _speedSelectedIsBike = false;
        _speedSelectedGpsDeviceId = null;
        _speedSelectedDeviceId = null;
        _speedSelectedDay = null;
        _speedSelectedIsToday = false;
        _speedLastFixTime = null;
        _speedLastPoint = null;
        _speedLastBandColor = null;
        _speedLiveSpeedKmh = null;
      }
    });
  }

  // Speed band thresholds exactly as specified — a plain if-chain rather
  // than a lookup table since the bands are contiguous ranges, not
  // discrete values.
  Color _speedBandColor(double speedKmh) {
    if (speedKmh >= 80) return const Color(0xFFD51906);
    if (speedKmh >= 70) return const Color(0xFFF94E39);
    if (speedKmh >= 60) return const Color(0xFFF9887B);
    if (speedKmh >= 50) return const Color(0xFFFFBF00);
    return Colors.green.shade400;
  }

  // Turns one day's raw {latitude, longitude, speedKmh, fixTime} points
  // (see TraccarService.fetchPositionsWithSpeed) into a small number of
  // Polylines — one per contiguous run of same-speed-band points, so a day
  // with 8000+ points doesn't become 8000 one-segment Polylines. A gap of
  // more than 5 minutes between consecutive points ends the current
  // Polyline outright rather than bridging it with a straight line across
  // whatever the truck/bike did while GPS wasn't reporting.
  Set<Polyline> _buildSpeedPolylines(List<Map<String, dynamic>> points) {
    if (points.length < 2) return {};
    final sorted = [...points]
      ..sort(
        (a, b) =>
            (a['fixTime'] as DateTime).compareTo(b['fixTime'] as DateTime),
      );

    final polylines = <Polyline>{};
    var segmentIndex = 0;
    var currentColor = _speedBandColor(sorted.first['speedKmh'] as double);
    var currentSegment = <LatLng>[
      LatLng(
        sorted.first['latitude'] as double,
        sorted.first['longitude'] as double,
      ),
    ];

    void flush() {
      if (currentSegment.length < 2) return;
      polylines.add(
        Polyline(
          polylineId: PolylineId('speed_${segmentIndex++}'),
          points: List.of(currentSegment),
          color: currentColor,
          width: 4,
        ),
      );
    }

    for (var i = 1; i < sorted.length; i++) {
      final prevTime = sorted[i - 1]['fixTime'] as DateTime;
      final currTime = sorted[i]['fixTime'] as DateTime;
      final point = LatLng(
        sorted[i]['latitude'] as double,
        sorted[i]['longitude'] as double,
      );

      if (currTime.difference(prevTime) > const Duration(minutes: 5)) {
        flush();
        currentColor = _speedBandColor(sorted[i]['speedKmh'] as double);
        currentSegment = [point];
        continue;
      }

      final color = _speedBandColor(sorted[i]['speedKmh'] as double);
      if (color != currentColor) {
        // Extend the ending segment to this point first (so the two bands
        // visually meet with no gap), then start the new-color segment
        // from that same point.
        currentSegment.add(point);
        flush();
        currentColor = color;
        currentSegment = [point];
      } else {
        currentSegment.add(point);
      }
    }
    flush();
    return polylines;
  }

  // Finds the highest existing "speed_N" polyline id so live-extension
  // additions never collide with ids _buildSpeedPolylines already used.
  int _nextSpeedPolylineIndex(Iterable<Polyline> polylines) {
    var next = 0;
    for (final p in polylines) {
      final match = RegExp(r'^speed_(\d+)$').firstMatch(p.polylineId.value);
      if (match == null) continue;
      final n = int.parse(match.group(1)!) + 1;
      if (n > next) next = n;
    }
    return next;
  }

  // Live route extension (PART 3) — appends newly-fetched points to the
  // existing _speedPolylines instead of rebuilding from scratch, extending
  // the last-drawn Polyline if the band hasn't changed since
  // _speedLastBandColor, or starting a fresh one if it has (or a >5min gap
  // is hit, same rule as _buildSpeedPolylines). Reads/writes
  // _speedLastFixTime/_speedLastPoint/_speedLastBandColor as it goes, so
  // the next 15s cycle picks up exactly where this one left off.
  Set<Polyline> _extendSpeedPolylines(List<Map<String, dynamic>> newPoints) {
    if (newPoints.isEmpty) return _speedPolylines;
    final sorted = [...newPoints]
      ..sort(
        (a, b) =>
            (a['fixTime'] as DateTime).compareTo(b['fixTime'] as DateTime),
      );

    final polylines = _speedPolylines.toList();
    final nextIndex = _nextSpeedPolylineIndex(polylines);
    var segmentIndex = nextIndex;

    List<LatLng> currentSegment;
    Color currentColor;
    if (_speedLastPoint != null &&
        _speedLastBandColor != null &&
        polylines.isNotEmpty &&
        polylines.last.color == _speedLastBandColor) {
      // Continue the polyline that ended at _speedLastPoint — pop it off
      // so flush() below re-adds it (possibly under the same id) extended
      // with the new points, rather than leaving a short stub behind.
      currentSegment = polylines.removeLast().points.toList();
      currentColor = _speedLastBandColor!;
      segmentIndex = _nextSpeedPolylineIndex(polylines);
    } else {
      currentSegment = _speedLastPoint != null ? [_speedLastPoint!] : [];
      currentColor = _speedBandColor(sorted.first['speedKmh'] as double);
    }

    void flush() {
      if (currentSegment.length < 2) return;
      polylines.add(
        Polyline(
          polylineId: PolylineId('speed_${segmentIndex++}'),
          points: List.of(currentSegment),
          color: currentColor,
          width: 4,
        ),
      );
    }

    var prevFixTime = _speedLastFixTime;
    for (final p in sorted) {
      final fixTime = p['fixTime'] as DateTime;
      // Duplicate fixTime (or older than what's already drawn) — skip.
      if (prevFixTime != null && !fixTime.isAfter(prevFixTime)) continue;
      final point = LatLng(p['latitude'] as double, p['longitude'] as double);
      final color = _speedBandColor(p['speedKmh'] as double);

      if (prevFixTime != null &&
          fixTime.difference(prevFixTime) > const Duration(minutes: 5)) {
        flush();
        currentColor = color;
        currentSegment = [point];
      } else if (currentSegment.isNotEmpty && color != currentColor) {
        currentSegment.add(point);
        flush();
        currentColor = color;
        currentSegment = [point];
      } else {
        currentSegment.add(point);
      }
      prevFixTime = fixTime;
      _speedLastPoint = point;
      _speedLastBandColor = color;
    }
    flush();
    _speedLastFixTime = prevFixTime;

    return polylines.toSet();
  }

  // SpeedVehiclePicker's callback once a day's points have loaded (initial
  // fetch or a cache hit) — the only place besides live-extension above
  // that writes _speedPolylines. Also seeds the live-extension bookkeeping
  // fields from this same data, so if the selected day is Today, the very
  // next 15s cycle can continue smoothly from the last point here instead
  // of re-fetching the whole day.
  void _onSpeedRouteReady(List<Map<String, dynamic>> points) {
    if (!mounted) return;
    setState(() {
      _speedPolylines = _buildSpeedPolylines(points);
      if (points.isEmpty) {
        _speedLastFixTime = null;
        _speedLastPoint = null;
        _speedLastBandColor = null;
        _speedLiveSpeedKmh = null;
      } else {
        final sorted = [...points]
          ..sort(
            (a, b) => (a['fixTime'] as DateTime).compareTo(
              b['fixTime'] as DateTime,
            ),
          );
        final last = sorted.last;
        _speedLastFixTime = last['fixTime'] as DateTime;
        _speedLastPoint = LatLng(
          last['latitude'] as double,
          last['longitude'] as double,
        );
        final lastSpeed = last['speedKmh'] as double;
        _speedLastBandColor = _speedBandColor(lastSpeed);
        if (_speedSelectedIsToday) {
          _speedLiveSpeedKmh = lastSpeed;
          _speedLiveHasSpeed = last['hasSpeed'] != false;
        }
      }
    });
  }

  // Reported by SpeedVehiclePicker whenever the selected vehicle changes,
  // including back to null (deselecting). Resets live-extension bookkeeping
  // per PART 5's requirement — a vehicle change must never let a stale
  // continuation from the PREVIOUS vehicle leak into the new one's route.
  void _onSpeedVehicleChanged({
    required String? vehicleId,
    required bool isBike,
    required String? gpsDeviceId,
    required int? deviceId,
  }) {
    if (!mounted) return;
    setState(() {
      _speedSelectedVehicleId = vehicleId;
      _speedSelectedIsBike = isBike;
      _speedSelectedGpsDeviceId = gpsDeviceId;
      _speedSelectedDeviceId = deviceId;
      _speedLastFixTime = null;
      _speedLastPoint = null;
      _speedLastBandColor = null;
      _speedLiveSpeedKmh = null;
    });
  }

  // Reported by SpeedVehiclePicker whenever the selected day changes,
  // including back to null. Same reset reasoning as
  // _onSpeedVehicleChanged — a day change (even Today -> Today, e.g. via
  // the picker's own re-selection) must start live-extension fresh rather
  // than continuing from a previous day's bookkeeping.
  void _onSpeedDayChanged(DateTime? day, bool isToday) {
    if (!mounted) return;
    setState(() {
      _speedSelectedDay = day;
      _speedSelectedIsToday = isToday;
      _speedPolylines = {};
      _speedLastFixTime = null;
      _speedLastPoint = null;
      _speedLastBandColor = null;
      _speedLiveSpeedKmh = null;
    });
  }

  // PART 1 (isolated) — vehicle markers shown while in speed mode: no
  // onTap at all (so a tap can never reach _onTruckTapped/bill-route
  // logic), snippet is speed-only (no bill number). Reuses the exact same
  // _truckMarkerInfo/_bikeMarkerInfo/_displayedPositions/
  // _bikeDisplayedPositions/_truckIcon/_bikeIcon that the existing,
  // untouched _buildMarkersFromDisplayedPositions/
  // _buildBikeMarkersFromDisplayedPositions already maintain via the
  // regular 15s refresh cycle — this only reads that state, never writes
  // it, and doesn't change how any of it gets populated or animated. The
  // selected vehicle (PART 2's highlight) gets a colored default pin
  // instead of the normal custom icon, which is simpler and more clearly
  // distinct than trying to generate a second "highlighted" Canvas icon.
  Set<Marker> _buildSpeedModeMarkers() {
    final markers = <Marker>{};
    for (final entry in _truckMarkerInfo.entries) {
      final uniqueId = entry.key;
      final position = _displayedPositions[uniqueId];
      if (position == null) continue;
      final info = entry.value;
      final isSelected =
          !_speedSelectedIsBike && uniqueId == _speedSelectedGpsDeviceId;
      markers.add(
        Marker(
          markerId: MarkerId('speed_truck_$uniqueId'),
          position: position,
          icon: isSelected
              ? BitmapDescriptor.defaultMarkerWithHue(
                  BitmapDescriptor.hueYellow,
                )
              : (_truckIcon ?? BitmapDescriptor.defaultMarker),
          infoWindow: InfoWindow(
            title: info.truckNumber,
            snippet: info.speed.snippet(),
          ),
        ),
      );
    }
    for (final entry in _bikeMarkerInfo.entries) {
      final uniqueId = entry.key;
      final position = _bikeDisplayedPositions[uniqueId];
      if (position == null) continue;
      final info = entry.value;
      final isSelected =
          _speedSelectedIsBike && uniqueId == _speedSelectedGpsDeviceId;
      markers.add(
        Marker(
          markerId: MarkerId('speed_bike_$uniqueId'),
          position: position,
          icon: isSelected
              ? BitmapDescriptor.defaultMarkerWithHue(
                  BitmapDescriptor.hueYellow,
                )
              : (_bikeIcon ?? BitmapDescriptor.defaultMarker),
          infoWindow: InfoWindow(
            title: info.bikeNumber,
            snippet: info.speed.snippet(),
          ),
        ),
      );
    }
    return markers;
  }

  // Mirrors _showSidebarBottomSheet below exactly (draggable bottom sheet
  // on narrow screens), just for SpeedVehiclePicker instead of
  // _LiveTrackingSidebar — see build()'s FAB, which picks whichever of the
  // two applies.
  void _showSpeedBottomSheet() {
    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (sheetContext) => DraggableScrollableSheet(
        initialChildSize: 0.55,
        minChildSize: 0.3,
        maxChildSize: 0.9,
        expand: false,
        builder: (context, scrollController) => DecoratedBox(
          decoration: const BoxDecoration(
            color: Colors.white,
            borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
          ),
          child: Column(
            children: [
              const SizedBox(height: 8),
              Container(
                width: 40,
                height: 4,
                decoration: BoxDecoration(
                  color: Colors.grey[400],
                  borderRadius: BorderRadius.circular(2),
                ),
              ),
              Expanded(
                child: SpeedVehiclePicker(
                  onRouteReady: _onSpeedRouteReady,
                  onVehicleChanged: _onSpeedVehicleChanged,
                  onDayChanged: _onSpeedDayChanged,
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  // Opens the Trucks -> Bill -> KM sidebar as a draggable bottom sheet on
  // narrow screens (see build()) — the map itself is the primary content
  // there, so the sidebar becomes an on-demand overlay instead of a
  // permanent side panel. Closes itself as soon as a bill is selected (same
  // "Live Total KM" flow build()'s onBillSelected wiring already drives),
  // so picking a bill drops straight back into the map with the route just
  // drawn — no separate step to dismiss the sheet.
  void _showSidebarBottomSheet() {
    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (sheetContext) => DraggableScrollableSheet(
        initialChildSize: 0.55,
        minChildSize: 0.3,
        maxChildSize: 0.9,
        expand: false,
        builder: (context, scrollController) => DecoratedBox(
          decoration: const BoxDecoration(
            color: Colors.white,
            borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
          ),
          child: Column(
            children: [
              const SizedBox(height: 8),
              Container(
                width: 40,
                height: 4,
                decoration: BoxDecoration(
                  color: Colors.grey[400],
                  borderRadius: BorderRadius.circular(2),
                ),
              ),
              Expanded(
                child: _LiveTrackingSidebar(
                  onBillSelected: (truckNumber, from, to, recordRef) {
                    Navigator.pop(sheetContext);
                    _onSidebarBillSelected(truckNumber, from, to, recordRef);
                  },
                  liveKmUpdate: _liveTotalKmForSelectedRoute,
                  liveSpeedByTruckNumber: _liveSpeedByTruckNumber,
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    // google_maps_flutter renders via the platform's native Maps SDK on
    // both web and Android (see AndroidManifest.xml's Maps API key), so
    // this same widget tree works unchanged on mobile — no
    // platform-specific branch needed here.
    //
    // Same WebAppShell.desktopBreakpoint (900px) the Garage/GPS Devices
    // screens use — above it, today's side-by-side Row (unchanged); below
    // it, the map becomes the full-screen primary content (this is a live
    // GPS map, not a form or list — squeezing it next to a fixed sidebar
    // the way a list/detail screen could tolerate would make it far less
    // usable) and the Trucks->Bill->KM sidebar moves into an on-demand
    // bottom sheet instead, opened via the FAB below.
    final isWide =
        MediaQuery.of(context).size.width > WebAppShell.desktopBreakpoint;

    final mapStack = Stack(
      children: [
        GoogleMap(
          key: _mapKey,
          initialCameraPosition: _initialCameraPosition,
          // Speed-mode markers are a separate build (_buildSpeedModeMarkers,
          // no onTap at all) layered with _siteMarkers — the surest way to
          // guarantee a tap can never reach _onTruckTapped's bill-route
          // logic, with zero changes to how the normal markers/onTap are
          // actually built. Site markers stay for map context either way.
          markers: _speedModeActive
              ? {..._buildSpeedModeMarkers(), ..._siteMarkers}
              : {..._markers, ..._siteMarkers},
          // Existing bill-route polylines are hidden (not cleared) while in
          // speed mode, and restored the instant it's turned off — nothing
          // about _polylines/_selectedRouteRecordRef's own state is ever
          // touched here.
          polylines: _speedModeActive ? _speedPolylines : _polylines,
          myLocationButtonEnabled: false,
        ),
        if (!_iconReady)
          const Positioned.fill(
            child: IgnorePointer(
              child: Center(child: CircularProgressIndicator()),
            ),
          ),
        if (_errorText != null)
          Positioned(
            top: 12,
            left: 12,
            right: 12,
            // Amber, not red — this is a transient "still retrying" state,
            // not a terminal failure: the map above keeps showing whatever
            // positions/markers it last successfully loaded, never blank.
            child: Material(
              color: Colors.orange[800],
              borderRadius: BorderRadius.circular(8),
              child: Padding(
                padding: const EdgeInsets.all(12),
                child: Text(
                  _errorText!,
                  style: const TextStyle(color: Colors.white, fontSize: 12),
                ),
              ),
            ),
          ),
        // Vehicle Speed toggle — same button, same position, on both web
        // and mobile (it's part of mapStack, not the AppBar, so there's no
        // platform split to keep in sync).
        Positioned(
          top: 12,
          right: 12,
          child: Material(
            color: _speedModeActive ? AppTheme.primaryDark : Colors.white,
            borderRadius: BorderRadius.circular(20),
            elevation: 3,
            child: InkWell(
              borderRadius: BorderRadius.circular(20),
              onTap: _toggleSpeedMode,
              child: Padding(
                padding: const EdgeInsets.symmetric(
                  horizontal: 12,
                  vertical: 8,
                ),
                child: Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Icon(
                      Icons.speed,
                      size: 16,
                      color: _speedModeActive
                          ? Colors.white
                          : AppTheme.primaryDark,
                    ),
                    const SizedBox(width: 6),
                    Text(
                      'Vehicle Speed',
                      style: TextStyle(
                        fontSize: 12,
                        fontWeight: FontWeight.bold,
                        color: _speedModeActive
                            ? Colors.white
                            : AppTheme.primaryDark,
                      ),
                    ),
                  ],
                ),
              ),
            ),
          ),
        ),
        // Live speed badge (PART 2) — only ever non-null while Today is
        // selected (see _onSpeedRouteReady/the live-extension block in
        // _refreshPositions, both of which only set _speedLiveSpeedKmh when
        // _speedSelectedIsToday), so a past day's selection naturally never
        // shows or updates this, satisfying that requirement without an
        // extra explicit check here.
        if (_speedModeActive && _speedLiveSpeedKmh != null)
          Positioned(
            top: 60,
            right: 12,
            child: Builder(
              builder: (context) {
                // Live badge uses the shared live-speed bands (grey when
                // the latest fix is > kLiveSpeedStaleAfter old), with a
                // text label next to the color. Route colors below keep
                // their own _speedBandColor bands.
                final reading = LiveSpeedReading(
                  kmh: _speedLiveHasSpeed ? _speedLiveSpeedKmh!.round() : null,
                  fixTime: _speedLastFixTime,
                );
                return Material(
                  key: const ValueKey('live-speed-badge'),
                  color: liveSpeedBandColor(reading.band()),
                  borderRadius: BorderRadius.circular(12),
                  elevation: 4,
                  child: Padding(
                    padding: const EdgeInsets.symmetric(
                      horizontal: 16,
                      vertical: 10,
                    ),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.end,
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        Text(
                          reading.label(),
                          style: const TextStyle(
                            color: Colors.white,
                            fontWeight: FontWeight.bold,
                            fontSize: 18,
                          ),
                        ),
                        Text(
                          liveSpeedUpdatedLabel(reading.fixTime),
                          style: const TextStyle(
                            color: Colors.white,
                            fontSize: 11,
                          ),
                        ),
                      ],
                    ),
                  ),
                );
              },
            ),
          ),
        if (_speedModeActive)
          Positioned(
            bottom: 12,
            left: 12,
            child: Material(
              elevation: 2,
              borderRadius: BorderRadius.circular(8),
              color: Colors.white,
              child: Padding(
                padding: const EdgeInsets.all(10),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    const Text(
                      'Speed (km/h)',
                      style: TextStyle(
                        fontWeight: FontWeight.bold,
                        fontSize: 11,
                      ),
                    ),
                    const SizedBox(height: 6),
                    _speedLegendRow(Colors.green.shade400, '< 50'),
                    _speedLegendRow(const Color(0xFFFFBF00), '50-59'),
                    _speedLegendRow(const Color(0xFFF9887B), '60-69'),
                    _speedLegendRow(const Color(0xFFF94E39), '70-79'),
                    _speedLegendRow(const Color(0xFFD51906), '80+'),
                  ],
                ),
              ),
            ),
          ),
      ],
    );

    return Scaffold(
      appBar: AppBar(
        title: const Text('Live Tracking'),
        backgroundColor: AppTheme.primaryDark,
        foregroundColor: Colors.white,
      ),
      // Root-cause fix for the GoogleMap platform view getting torn down
      // and recreated while it was still initialising (the "Failed to
      // execute 'observe' on 'IntersectionObserver'... Node cannot be
      // found" Chrome error): `body` used to be `isWide ? Row(...) :
      // mapStack` — swapping the WIDGET TYPE at the Scaffold.body slot
      // between a Row and a bare Stack. Flutter's reconciliation only
      // reuses an Element when the widget at a given slot keeps the same
      // runtimeType across builds; a Row-vs-Stack swap at body unmounts
      // the ENTIRE old subtree — including the Stack/GoogleMap buried
      // inside the Row branch — and mounts a brand new one from scratch,
      // regardless of `mapStack` being "the same Dart object" in both
      // branches. On web this can happen within the first second of this
      // screen's life: MediaQuery's very first reported size (before the
      // browser's real viewport metrics settle, which a local/dev build
      // hits far more often than an already-warmed-up published build)
      // can land on the opposite side of the 900px breakpoint from the
      // very next build a few milliseconds later (triggered by
      // _generateTruckIcon's setState, then _refreshPositions' own) —
      // exactly the kind of double-rebuild that tears the half-initialised
      // map out from under its own async platform-view setup.
      //
      // Fix: `body` is now ALWAYS a Row (same runtimeType every build);
      // only the LEADING sidebar/divider children are added or omitted
      // via `if (isWide) ...`, with `Expanded(child: mapStack)` always
      // last. Flutter's multi-child reconciliation matches a stable
      // trailing child from the END of the list even when the number of
      // leading items changes, so the Stack/GoogleMap's Element is never
      // torn down no matter how `isWide` moves across rebuilds — visually
      // identical either way (no sidebar space taken on narrow screens,
      // exactly as mapStack alone used to render).
      body: Row(
        children: [
          if (isWide) ...[
            SizedBox(
              width: 300,
              // Swapped based on mode; _LiveTrackingSidebar itself
              // (used whenever speed mode is off, i.e. unchanged
              // day-to-day behavior) is completely untouched.
              child: _speedModeActive
                  ? SpeedVehiclePicker(
                      onRouteReady: _onSpeedRouteReady,
                      onVehicleChanged: _onSpeedVehicleChanged,
                      onDayChanged: _onSpeedDayChanged,
                    )
                  : _LiveTrackingSidebar(
                      onBillSelected: _onSidebarBillSelected,
                      liveKmUpdate: _liveTotalKmForSelectedRoute,
                      liveSpeedByTruckNumber: _liveSpeedByTruckNumber,
                    ),
            ),
            const VerticalDivider(width: 1),
          ],
          Expanded(child: mapStack),
        ],
      ),
      floatingActionButton: isWide
          ? null
          : FloatingActionButton.extended(
              onPressed: _speedModeActive
                  ? _showSpeedBottomSheet
                  : _showSidebarBottomSheet,
              backgroundColor: AppTheme.primaryDark,
              icon: Icon(
                _speedModeActive ? Icons.speed : Icons.local_shipping,
                color: Colors.white,
              ),
              label: Text(
                _speedModeActive ? 'Select Vehicle' : 'Trucks',
                style: const TextStyle(color: Colors.white),
              ),
            ),
    );
  }

  Widget _speedLegendRow(Color color, String label) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 3),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Container(width: 14, height: 8, color: color),
          const SizedBox(width: 6),
          Text(label, style: const TextStyle(fontSize: 10)),
        ],
      ),
    );
  }
}

// ---- Vehicle Speed picker: truck rows ----
// Every trucks doc becomes one row. Selectable only when its GPS Device ID
// matches a Traccar device (uniqueId, trimmed); a truck without a recent
// position is still listed (with "No recent position · last seen …"),
// never hidden. Trucks with no GPS Device ID, or one Traccar doesn't know,
// are listed greyed with the reason so nobody mistakes them for missing.
enum SpeedPickerTruckStatus { tracked, noGpsDevice, deviceNotFound }

class SpeedPickerTruckRow {
  final String docId;
  final String truckNumber;
  final String gpsDeviceId;
  final SpeedPickerTruckStatus status;
  final DateTime? lastSeen;
  final String? traccarStatus;

  const SpeedPickerTruckRow({
    required this.docId,
    required this.truckNumber,
    required this.gpsDeviceId,
    required this.status,
    this.lastSeen,
    this.traccarStatus,
  });

  bool get selectable => status == SpeedPickerTruckStatus.tracked;
}

const Duration kSpeedPickerRecentPosition = Duration(minutes: 30);

List<SpeedPickerTruckRow> buildSpeedPickerTruckRows({
  required List<({String id, Map<String, dynamic> data})> trucks,
  required List<Map<String, dynamic>> devices,
  bool log = false,
}) {
  final deviceByUniqueId = <String, Map<String, dynamic>>{
    for (final d in devices)
      if ((d['uniqueId'] ?? '').toString().trim().isNotEmpty)
        (d['uniqueId'] ?? '').toString().trim(): d,
  };
  final rows = <SpeedPickerTruckRow>[];
  for (final t in trucks) {
    final number = (t.data['truckNumber'] ?? '').toString().trim();
    final gps = (t.data['gpsDeviceId'] ?? '').toString().trim();
    final device = gps.isEmpty ? null : deviceByUniqueId[gps];
    final status = gps.isEmpty
        ? SpeedPickerTruckStatus.noGpsDevice
        : device == null
            ? SpeedPickerTruckStatus.deviceNotFound
            : SpeedPickerTruckStatus.tracked;
    rows.add(SpeedPickerTruckRow(
      docId: t.id,
      truckNumber: number.isEmpty ? t.id : number,
      gpsDeviceId: gps,
      status: status,
      lastSeen: DateTime.tryParse((device?['lastUpdate'] ?? '').toString())?.toLocal(),
      traccarStatus: device?['status']?.toString(),
    ));
  }
  int byNumber(SpeedPickerTruckRow a, SpeedPickerTruckRow b) =>
      normalizeVehicleNumber(a.truckNumber).compareTo(normalizeVehicleNumber(b.truckNumber));
  // Selectable trucks first (by number), then the greyed ones (by number).
  rows.sort((a, b) {
    if (a.selectable != b.selectable) return a.selectable ? -1 : 1;
    return byNumber(a, b);
  });
  if (log && kDebugMode) {
    final withGps = rows.where((r) => r.status != SpeedPickerTruckStatus.noGpsDevice).length;
    final matched = rows.where((r) => r.selectable).length;
    final dropped = rows.where((r) => !r.selectable).toList();
    debugPrint('[SPEED_PICKER] trucks loaded=${rows.length} withGpsDeviceId=$withGps '
        'matchedTraccar=$matched notSelectable=${dropped.length} '
        '(traccarDevices=${devices.length})');
    for (final r in dropped) {
      debugPrint('[SPEED_PICKER]   ${r.truckNumber}: '
          '${r.status == SpeedPickerTruckStatus.noGpsDevice ? 'no GPS Device ID' : 'GPS Device ID "${r.gpsDeviceId}" not found in Traccar'}');
    }
  }
  return rows;
}

String speedPickerTruckSubtitle(SpeedPickerTruckRow r, {DateTime? now}) {
  switch (r.status) {
    case SpeedPickerTruckStatus.noGpsDevice:
      return 'No GPS device';
    case SpeedPickerTruckStatus.deviceNotFound:
      return 'GPS device not found in Traccar';
    case SpeedPickerTruckStatus.tracked:
      final seen = r.lastSeen;
      if (seen == null) return 'No recent position';
      String two(int v) => v.toString().padLeft(2, '0');
      final label = '${two(seen.day)}/${two(seen.month)} ${two(seen.hour)}:${two(seen.minute)}';
      final recent = (now ?? DateTime.now()).difference(seen) <= kSpeedPickerRecentPosition;
      return recent ? 'Last seen $label' : 'No recent position · last seen $label';
  }
}

// Vehicle Speed's vehicle/day picker (PART of the isolated Vehicle Speed
// feature — see _LiveTrackingScreenState's doc comments). Fully
// self-contained on purpose, same philosophy as _LiveTrackingSidebar below
// it: does its own Firestore (trucks/bikes) and Traccar fetching, and its
// own in-memory caching (static, so it survives this widget's State being
// recreated when Vehicle Speed mode is toggled off and back on — same idea
// as _DailyKmHistorySectionState's cache in the Garage module). The only
// thing it reports up to the parent is onRouteReady(points) once a day's
// data has loaded, so the parent can turn that into map Polylines — it
// never touches _LiveTrackingScreenState's truck/bill/route state itself,
// and works identically whether it's embedded inline (web side panel) or
// inside a modal bottom sheet (mobile): everything it needs to react to is
// its own State, not anything from an ancestor.
class SpeedVehiclePicker extends StatefulWidget {
  final void Function(List<Map<String, dynamic>> points) onRouteReady;
  // Reported up so the parent can highlight the selected vehicle on the map
  // and drive the live speed badge/live route extension — see
  // _LiveTrackingScreenState._onSpeedVehicleChanged/_onSpeedDayChanged.
  // deviceId is null until resolved (async), then reported again once known.
  final void Function({
    required String? vehicleId,
    required bool isBike,
    required String? gpsDeviceId,
    required int? deviceId,
  })
  onVehicleChanged;
  final void Function(DateTime? day, bool isToday) onDayChanged;

  // Test seams only — production uses FirebaseFirestore.instance and the
  // shared VehicleKmCache device list (no extra reads).
  final FirebaseFirestore? firestoreOverride;
  final Future<List<Map<String, dynamic>>> Function()? devicesLoader;

  const SpeedVehiclePicker({
    super.key,
    required this.onRouteReady,
    required this.onVehicleChanged,
    required this.onDayChanged,
    this.firestoreOverride,
    this.devicesLoader,
  });

  @override
  State<SpeedVehiclePicker> createState() => _SpeedVehiclePickerState();
}

class _SpeedVehiclePickerState extends State<SpeedVehiclePicker> {
  static final Map<String, List<Map<String, dynamic>>> _cache = {};

  static String cacheKeyFor(String vehicleId, DateTime day) =>
      '$vehicleId/${day.year}-${day.month}-${day.day}';

  // Called by _LiveTrackingScreenState's 15s refresh cycle to append
  // freshly-fetched live points to today's cached list (so re-opening the
  // picker for the same vehicle/day this session sees the extended route).
  static void appendToCache(
    String vehicleId,
    DateTime day,
    List<Map<String, dynamic>> newPoints,
  ) {
    final key = cacheKeyFor(vehicleId, day);
    final existing = _cache[key];
    if (existing == null) {
      _cache[key] = List.of(newPoints);
    } else {
      existing.addAll(newPoints);
    }
  }

  late Stream<QuerySnapshot<Map<String, dynamic>>> _trucksStream =
      ReferenceCollectionCache.stream('trucks', db: widget.firestoreOverride);
  late Stream<QuerySnapshot<Map<String, dynamic>>> _bikesStream =
      ReferenceCollectionCache.stream(kBikesCollection, db: widget.firestoreOverride);
  late Future<List<Map<String, dynamic>>> _devicesFuture = _loadDevices();
  String? _lastLogKey;

  QueryDocumentSnapshot? _selectedVehicle;
  bool _selectedIsBike = false;
  DateTime? _selectedDay;
  Future<List<Map<String, dynamic>>>? _pointsFuture;
  // Resolved numeric Traccar device id for the currently selected vehicle,
  // cached locally so _loadPoints doesn't re-resolve it on every day switch.
  int? _resolvedDeviceId;
  String? _resolvedForVehicleId;

  List<DateTime> get _last7Days {
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    return List.generate(7, (i) => today.subtract(Duration(days: i)));
  }

  String _dayLabel(DateTime day) {
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    if (day == today) return 'Today';
    if (day == today.subtract(const Duration(days: 1))) return 'Yesterday';
    const weekdays = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
    return '${weekdays[day.weekday - 1]} ${day.day}/${day.month}';
  }

  void _selectVehicle(QueryDocumentSnapshot doc, bool isBike) {
    final vehicleData = doc.data() as Map<String, dynamic>;
    final gpsDeviceId = (vehicleData['gpsDeviceId'] as String).trim();
    setState(() {
      _selectedVehicle = doc;
      _selectedIsBike = isBike;
      _selectedDay = null;
      _pointsFuture = null;
      _resolvedDeviceId = null;
      _resolvedForVehicleId = null;
    });
    widget.onVehicleChanged(
      vehicleId: doc.id,
      isBike: isBike,
      gpsDeviceId: gpsDeviceId,
      deviceId: null,
    );
    _resolveDeviceId(doc.id, gpsDeviceId);
  }

  // Resolves the numeric Traccar device id in the background and reports it
  // up once known, guarding against the selection having changed/cleared
  // while the async fetchDevices() call was in flight.
  Future<int?> _resolveDeviceId(String vehicleId, String gpsDeviceId) async {
    final devices = await VehicleKmCache.devices();
    final deviceId = GarageService._resolveDeviceId(devices, gpsDeviceId);
    final stillCurrent = mounted && _selectedVehicle?.id == vehicleId;
    if (stillCurrent && deviceId != null) {
      setState(() {
        _resolvedDeviceId = deviceId;
        _resolvedForVehicleId = vehicleId;
      });
      widget.onVehicleChanged(
        vehicleId: vehicleId,
        isBike: _selectedIsBike,
        gpsDeviceId: gpsDeviceId,
        deviceId: deviceId,
      );
    }
    return deviceId;
  }

  void _selectDay(DateTime day) {
    final vehicle = _selectedVehicle;
    if (vehicle == null) return;
    final now = DateTime.now();
    final isToday =
        day.year == now.year && day.month == now.month && day.day == now.day;
    setState(() {
      _selectedDay = day;
      _pointsFuture = _loadPoints(vehicle, day);
    });
    widget.onDayChanged(day, isToday);
  }

  void _retry() {
    final day = _selectedDay;
    if (day != null) _selectDay(day);
  }

  // Numeric Traccar device id resolution reuses GarageService's existing
  // helper directly (same library, so its privacy doesn't block this) —
  // same pattern every other screen in this app already uses, not a new
  // one invented for this feature.
  Future<List<Map<String, dynamic>>> _loadPoints(
    QueryDocumentSnapshot vehicleDoc,
    DateTime day,
  ) async {
    final vehicleData = vehicleDoc.data() as Map<String, dynamic>;
    final gpsDeviceId = (vehicleData['gpsDeviceId'] as String).trim();
    final now = DateTime.now();
    final isToday =
        day.year == now.year && day.month == now.month && day.day == now.day;
    final cacheKey = cacheKeyFor(vehicleDoc.id, day);
    if (!isToday && _cache.containsKey(cacheKey)) {
      final cached = _cache[cacheKey]!;
      widget.onRouteReady(cached);
      return cached;
    }
    int? deviceId = _resolvedForVehicleId == vehicleDoc.id
        ? _resolvedDeviceId
        : null;
    if (deviceId == null) {
      deviceId = await _resolveDeviceId(vehicleDoc.id, gpsDeviceId);
    }
    if (deviceId == null) {
      throw Exception(
        'No matching Traccar device found for GPS Device ID '
        '"$gpsDeviceId".',
      );
    }
    final points = await TraccarService.fetchPositionsWithSpeed(
      username: _LiveTrackingScreenState._traccarUsername,
      password: _LiveTrackingScreenState._traccarPassword,
      deviceId: deviceId,
      from: day,
      to: day.add(const Duration(days: 1)),
    );
    _cache[cacheKey] = points;
    widget.onRouteReady(points);
    return points;
  }

  Widget _sectionHeader(String text) => Padding(
        padding: const EdgeInsets.fromLTRB(12, 8, 12, 4),
        child: Text(
          text,
          style: TextStyle(
            fontWeight: FontWeight.bold,
            fontSize: 12,
            color: Colors.grey[600],
          ),
        ),
      );

  Widget _loadingView(String text) => Center(
        key: const ValueKey('speed-picker-loading'),
        child: Padding(
          padding: const EdgeInsets.all(12),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              const CircularProgressIndicator(),
              const SizedBox(height: 8),
              Text(text, style: const TextStyle(fontSize: 12)),
            ],
          ),
        ),
      );

  Widget _errorView(String what, Object? error) => Center(
        key: const ValueKey('speed-picker-error'),
        child: Padding(
          padding: const EdgeInsets.all(12),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(
                'Could not load $what: $error',
                style: const TextStyle(fontSize: 12),
                textAlign: TextAlign.center,
              ),
              const SizedBox(height: 8),
              OutlinedButton.icon(
                key: const ValueKey('speed-picker-retry'),
                onPressed: _retryVehicleList,
                icon: const Icon(Icons.refresh),
                label: const Text('RETRY'),
              ),
            ],
          ),
        ),
      );

  void _retryVehicleList() {
    setState(() {
      _trucksStream = ReferenceCollectionCache.stream('trucks', db: widget.firestoreOverride, forceRefresh: true);
      _bikesStream = ReferenceCollectionCache.stream(kBikesCollection, db: widget.firestoreOverride, forceRefresh: true);
      _devicesFuture = _loadDevices(forceRefresh: true);
    });
  }

  Future<List<Map<String, dynamic>>> _loadDevices({bool forceRefresh = false}) =>
      widget.devicesLoader?.call() ?? VehicleKmCache.devices(forceRefresh: forceRefresh);

  Widget _buildVehicleList() {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        const Padding(
          padding: EdgeInsets.fromLTRB(12, 12, 12, 4),
          child: Text(
            'Select a Vehicle',
            style: TextStyle(fontWeight: FontWeight.bold, fontSize: 14),
          ),
        ),
        Expanded(
          child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
            stream: _trucksStream,
            builder: (context, truckSnap) {
              return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
                stream: _bikesStream,
                builder: (context, bikeSnap) {
                  return FutureBuilder<List<Map<String, dynamic>>>(
                    future: _devicesFuture,
                    builder: (context, devicesSnap) {
                      // Never an empty list while something is still
                      // loading or has failed — that looked like "no trucks".
                      if (truckSnap.hasError) return _errorView('trucks', truckSnap.error);
                      if (bikeSnap.hasError) return _errorView('bikes', bikeSnap.error);
                      if (devicesSnap.hasError) {
                        return _errorView('GPS devices (Traccar)', devicesSnap.error);
                      }
                      if (!truckSnap.hasData || !bikeSnap.hasData) {
                        return _loadingView('Loading vehicles…');
                      }
                      if (devicesSnap.connectionState != ConnectionState.done) {
                        return _loadingView('Loading GPS devices…');
                      }
                      return _buildVehicleRows(
                        truckSnap.data!.docs,
                        bikeSnap.data!.docs,
                        devicesSnap.data ?? const [],
                      );
                    },
                  );
                },
              );
            },
          ),
        ),
      ],
    );
  }

  Widget _buildVehicleRows(
    List<QueryDocumentSnapshot<Map<String, dynamic>>> truckDocs,
    List<QueryDocumentSnapshot<Map<String, dynamic>>> bikeDocs,
    List<Map<String, dynamic>> devices,
  ) {
    final truckDocById = {for (final d in truckDocs) d.id: d};
    // Log only when the inputs change, not on every rebuild.
    final logKey = '${truckDocs.length}/${bikeDocs.length}/${devices.length}/'
        '${identityHashCode(truckDocs)}';
    final shouldLog = logKey != _lastLogKey;
    _lastLogKey = logKey;
    final truckRows = buildSpeedPickerTruckRows(
      trucks: [for (final d in truckDocs) (id: d.id, data: d.data())],
      devices: devices,
      log: shouldLog,
    );
    // Same rule as the map markers (LiveVehicleIndex): a bike doc carrying
    // a truck's GPS Device ID / number is that truck, already listed under
    // Trucks — never a bike.
    final index = LiveVehicleIndex.fromData(
      trucks: truckDocs.map((d) => d.data()),
      bikes: bikeDocs.map((d) => d.data()),
    );
    final bikes = bikeDocs.where((doc) {
      final data = doc.data();
      final id = (data['gpsDeviceId'] ?? '').toString();
      return id.trim().isNotEmpty && !index.bikeDocIsReallyTruck(data);
    }).toList()
      ..sort((a, b) => normalizeVehicleNumber((a.data()['bikeNumber'] ?? '').toString())
          .compareTo(normalizeVehicleNumber((b.data()['bikeNumber'] ?? '').toString())));
    if (shouldLog && kDebugMode) {
      debugPrint('[SPEED_PICKER] bikes loaded=${bikeDocs.length} listed=${bikes.length} '
          '(duplicates of a truck or without GPS Device ID are not listed)');
    }
    if (truckRows.isEmpty && bikes.isEmpty) {
      return const Padding(
        key: ValueKey('speed-picker-empty'),
        padding: EdgeInsets.all(12),
        child: Text(
          'No trucks or bikes registered yet.',
          style: TextStyle(fontSize: 12),
        ),
      );
    }
    return ListView(
      children: [
        if (truckRows.isNotEmpty) ...[
          _sectionHeader('Trucks'),
          ...truckRows.map((r) {
            final doc = truckDocById[r.docId]!;
            return Opacity(
              opacity: r.selectable ? 1 : 0.45,
              child: ListTile(
                key: ValueKey('speed-truck-${r.docId}'),
                dense: true,
                enabled: r.selectable,
                leading: const LiveVehicleIcon(
                  key: ValueKey('live-icon-truck'),
                  type: LiveVehicleType.truck,
                ),
                title: Text(r.truckNumber),
                subtitle: Text(speedPickerTruckSubtitle(r)),
                onTap: r.selectable ? () => _selectVehicle(doc, false) : null,
              ),
            );
          }),
        ],
        if (bikes.isNotEmpty) ...[
          _sectionHeader('Bikes'),
          ...bikes.map((doc) {
            final data = doc.data();
            return ListTile(
              key: ValueKey('speed-bike-${doc.id}'),
              dense: true,
              leading: const LiveVehicleIcon(
                key: ValueKey('live-icon-bike'),
                type: LiveVehicleType.bike,
              ),
              title: Text((data['bikeNumber'] ?? '').toString()),
              onTap: () => _selectVehicle(doc, true),
            );
          }),
        ],
      ],
    );
  }

  Widget _buildDayAndStatusPanel(QueryDocumentSnapshot vehicle) {
    final data = vehicle.data() as Map<String, dynamic>;
    final label = _selectedIsBike
        ? (data['bikeNumber'] ?? '').toString()
        : (data['truckNumber'] ?? '').toString();
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        Padding(
          padding: const EdgeInsets.fromLTRB(4, 8, 12, 4),
          child: Row(
            children: [
              IconButton(
                icon: const Icon(Icons.arrow_back),
                onPressed: () {
                  setState(() {
                    _selectedVehicle = null;
                    _selectedDay = null;
                    _pointsFuture = null;
                    _resolvedDeviceId = null;
                    _resolvedForVehicleId = null;
                  });
                  widget.onVehicleChanged(
                    vehicleId: null,
                    isBike: false,
                    gpsDeviceId: null,
                    deviceId: null,
                  );
                  widget.onDayChanged(null, false);
                },
              ),
              LiveVehicleIcon(
                type: _selectedIsBike
                    ? LiveVehicleType.bike
                    : LiveVehicleType.truck,
                size: 28,
              ),
              const SizedBox(width: 8),
              Expanded(
                child: Text(
                  label,
                  style: const TextStyle(
                    fontWeight: FontWeight.bold,
                    fontSize: 14,
                  ),
                  overflow: TextOverflow.ellipsis,
                ),
              ),
            ],
          ),
        ),
        Padding(
          padding: const EdgeInsets.symmetric(horizontal: 12),
          child: Text(
            'Last 7 Days',
            style: TextStyle(
              fontWeight: FontWeight.bold,
              fontSize: 12,
              color: Colors.grey[600],
            ),
          ),
        ),
        SizedBox(
          height: 44,
          child: ListView(
            scrollDirection: Axis.horizontal,
            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
            children: _last7Days.map((day) {
              final isSelected =
                  _selectedDay != null &&
                  _selectedDay!.year == day.year &&
                  _selectedDay!.month == day.month &&
                  _selectedDay!.day == day.day;
              return Padding(
                padding: const EdgeInsets.only(right: 6),
                child: ChoiceChip(
                  label: Text(_dayLabel(day)),
                  selected: isSelected,
                  onSelected: (_) => _selectDay(day),
                ),
              );
            }).toList(),
          ),
        ),
        const Divider(height: 1),
        Expanded(
          child: _selectedDay == null
              ? const Center(
                  child: Padding(
                    padding: EdgeInsets.all(12),
                    child: Text(
                      'Select a day to view its route.',
                      style: TextStyle(fontSize: 12),
                      textAlign: TextAlign.center,
                    ),
                  ),
                )
              : FutureBuilder<List<Map<String, dynamic>>>(
                  future: _pointsFuture,
                  builder: (context, snapshot) {
                    if (snapshot.connectionState ==
                        ConnectionState.waiting) {
                      return const Center(
                        child: CircularProgressIndicator(),
                      );
                    }
                    if (snapshot.hasError) {
                      return Center(
                        child: Padding(
                          padding: const EdgeInsets.all(12),
                          child: Column(
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              Text(
                                'Failed to load: ${snapshot.error}',
                                style: const TextStyle(fontSize: 12),
                                textAlign: TextAlign.center,
                              ),
                              const SizedBox(height: 8),
                              OutlinedButton.icon(
                                onPressed: _retry,
                                icon: const Icon(Icons.refresh),
                                label: const Text('Retry'),
                              ),
                            ],
                          ),
                        ),
                      );
                    }
                    final points = snapshot.data ?? [];
                    if (points.isEmpty) {
                      return const Center(
                        child: Text(
                          'No data for this day.',
                          style: TextStyle(fontSize: 12),
                        ),
                      );
                    }
                    return const Center(
                      child: Padding(
                        padding: EdgeInsets.all(12),
                        child: Text(
                          'Route drawn on the map.',
                          style: TextStyle(fontSize: 12, color: Colors.grey),
                          textAlign: TextAlign.center,
                        ),
                      ),
                    );
                  },
                ),
        ),
      ],
    );
  }

  @override
  Widget build(BuildContext context) {
    final vehicle = _selectedVehicle;
    return vehicle == null
        ? _buildVehicleList()
        : _buildDayAndStatusPanel(vehicle);
  }
}

// Live Tracking's left sidebar — Truck -> Bill Number -> KM detail drill
// down. Self-contained (does its own Firestore/Traccar fetching) so it
// doesn't need to touch _LiveTrackingScreenState's existing marker state at
// all; see LiveTrackingScreen's build() for where this plugs in. The one
// exception is onBillSelected, which reports a selected bill's
// loadStartedAt/loadCompletedAt (or now) up to the parent so it can draw
// that load's route on the map via its existing route-drawing logic (see
// _LiveTrackingScreenState._onSidebarBillSelected/_drawRouteForTruck).
class _LiveTrackingSidebar extends StatefulWidget {
  final void Function(
    String truckNumber,
    DateTime from,
    DateTime to,
    DocumentReference<Map<String, dynamic>> recordRef,
  )
  onBillSelected;
  // Live Total KM for the currently-selected bill, lifted up from
  // _LiveTrackingScreenState (see its _liveTotalKmForSelectedRoute) —
  // computed there from the same position-history fetch that draws the
  // route polyline, so this sidebar makes no Traccar calls of its own for
  // this figure. Null until the first fetch for the current selection
  // lands.
  final double? liveKmUpdate;
  // Latest live speed per truck number (normalizeVehicleNumber), from the
  // parent's 15s position refresh — display only, no fetching here.
  final Map<String, LiveSpeedReading> liveSpeedByTruckNumber;

  const _LiveTrackingSidebar({
    required this.onBillSelected,
    required this.liveKmUpdate,
    this.liveSpeedByTruckNumber = const {},
  });

  @override
  State<_LiveTrackingSidebar> createState() => _LiveTrackingSidebarState();
}

class _LiveTrackingSidebarState extends State<_LiveTrackingSidebar> {
  String? _selectedTruckNumber;
  Future<List<QueryDocumentSnapshot<Map<String, dynamic>>>>? _billsFuture;
  QueryDocumentSnapshot<Map<String, dynamic>>? _selectedBillDoc;

  // gpsDeviceId is no longer tracked here — now that _fetchTotalKm is gone
  // (see liveKmUpdate), this sidebar no longer needs it for anything of
  // its own; the parent resolves a truck's numeric Traccar device id from
  // its own _truckMarkerInfo instead (see _onSidebarBillSelected).
  void _selectTruck(String truckNumber) {
    setState(() {
      _selectedTruckNumber = truckNumber;
      _selectedBillDoc = null;
      _billsFuture = _fetchBillsForTruck(truckNumber);
    });
  }

  void _selectBill(QueryDocumentSnapshot<Map<String, dynamic>> doc) {
    setState(() => _selectedBillDoc = doc);
    final data = doc.data();
    final loadStartedAt = data['loadStartedAt'] as Timestamp?;
    // No loadStartedAt means no route to draw — same guard
    // _onTruckTapped's own lookup uses.
    if (loadStartedAt == null || _selectedTruckNumber == null) return;
    final loadCompletedAt = data['loadCompletedAt'] as Timestamp?;
    widget.onBillSelected(
      _selectedTruckNumber!,
      loadStartedAt.toDate(),
      loadCompletedAt?.toDate() ?? DateTime.now(),
      doc.reference,
    );
  }

  // Recent 20 work_records for the selected truck, sorted client-side by
  // loadStartedAt descending — a single truckNumber equality filter with no
  // orderBy, same composite-index-avoidance reasoning as every other
  // collectionGroup('work_records') query in this codebase (see
  // AutoArrivalDetectionService.checkAllActiveLoads' doc comment).
  Future<List<QueryDocumentSnapshot<Map<String, dynamic>>>> _fetchBillsForTruck(
    String truckNumber,
  ) async {
    final snap = await FirebaseFirestore.instance
        .collectionGroup('work_records')
        .where('truckNumber', isEqualTo: truckNumber)
        .get();
    final docs = snap.docs.toList()
      ..sort((a, b) {
        final aTime = a.data()['loadStartedAt'] as Timestamp?;
        final bTime = b.data()['loadStartedAt'] as Timestamp?;
        if (aTime == null && bTime == null) return 0;
        if (aTime == null) return 1;
        if (bTime == null) return -1;
        return bTime.compareTo(aTime);
      });
    return docs.take(20).toList();
  }

  // A private load's auto-completed unloadingSiteName is left empty (see
  // AutoArrivalDetectionService._checkPrivateLoadReturn) — this fills in
  // the same human-readable label for display here.
  String _displayEndLocation(Map<String, dynamic> data) {
    final raw = (data['unloadingSiteName'] ?? '').toString();
    if (raw.isEmpty || raw.contains('Private Delivery')) {
      return 'Private Delivery (GPS Auto-Detected)';
    }
    return raw;
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        const Padding(
          padding: EdgeInsets.fromLTRB(12, 12, 12, 4),
          child: Text(
            'Trucks',
            style: TextStyle(fontWeight: FontWeight.bold, fontSize: 14),
          ),
        ),
        Expanded(
          child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
            stream: ReferenceCollectionCache.stream('trucks'),
            builder: (context, snapshot) {
              final docs = snapshot.data?.docs ?? [];
              final trucksWithGps = docs.where((doc) {
                final gpsDeviceId = (doc.data()['gpsDeviceId'] as String?)
                    ?.trim();
                return gpsDeviceId != null && gpsDeviceId.isNotEmpty;
              }).toList();
              if (trucksWithGps.isEmpty) {
                return const Padding(
                  padding: EdgeInsets.all(12),
                  child: Text(
                    'No trucks have a GPS Device ID set yet.',
                    style: TextStyle(fontSize: 12),
                  ),
                );
              }
              return ListView.builder(
                itemCount: trucksWithGps.length,
                itemBuilder: (context, index) {
                  final doc = trucksWithGps[index];
                  final truckNumber = (doc.data()['truckNumber'] ?? '')
                      .toString();
                  final isSelected = truckNumber == _selectedTruckNumber;
                  return ListTile(
                    dense: true,
                    selected: isSelected,
                    selectedTileColor: AppTheme.primaryMid.withOpacity(0.08),
                    leading: const LiveVehicleIcon(type: LiveVehicleType.truck),
                    title: Text(truckNumber),
                    trailing: LiveSpeedChip(
                      reading: widget.liveSpeedByTruckNumber[
                          normalizeVehicleNumber(truckNumber)],
                    ),
                    onTap: () => _selectTruck(truckNumber),
                  );
                },
              );
            },
          ),
        ),
        const Divider(height: 1),
        const Padding(
          padding: EdgeInsets.fromLTRB(12, 12, 12, 4),
          child: Text(
            'Bill Numbers',
            style: TextStyle(fontWeight: FontWeight.bold, fontSize: 14),
          ),
        ),
        Expanded(
          child: _selectedTruckNumber == null
              ? const Padding(
                  padding: EdgeInsets.all(12),
                  child: Text(
                    'Select a truck to view its bill numbers.',
                    style: TextStyle(fontSize: 12),
                  ),
                )
              : FutureBuilder<
                  List<QueryDocumentSnapshot<Map<String, dynamic>>>
                >(
                  future: _billsFuture,
                  builder: (context, snapshot) {
                    if (snapshot.connectionState == ConnectionState.waiting) {
                      return const Center(child: CircularProgressIndicator());
                    }
                    if (snapshot.hasError) {
                      return Padding(
                        padding: const EdgeInsets.all(12),
                        child: Text(
                          'Failed to load bills: ${snapshot.error}',
                          style: const TextStyle(fontSize: 12),
                        ),
                      );
                    }
                    final bills = snapshot.data ?? [];
                    if (bills.isEmpty) {
                      return const Padding(
                        padding: EdgeInsets.all(12),
                        child: Text(
                          'No bill records for this truck.',
                          style: TextStyle(fontSize: 12),
                        ),
                      );
                    }
                    return ListView.builder(
                      itemCount: bills.length,
                      itemBuilder: (context, index) {
                        final doc = bills[index];
                        final data = doc.data();
                        final billNumber = (data['billNumber'] ?? '')
                            .toString();
                        final isSelected = doc.id == _selectedBillDoc?.id;
                        return ListTile(
                          dense: true,
                          selected: isSelected,
                          selectedTileColor: AppTheme.primaryMid.withOpacity(
                            0.08,
                          ),
                          leading: const Icon(Icons.receipt_long),
                          title: Text(
                            billNumber.isEmpty
                                ? '(No Bill Number)'
                                : billNumber,
                          ),
                          onTap: () => _selectBill(doc),
                        );
                      },
                    );
                  },
                ),
        ),
        if (_selectedBillDoc != null) ...[
          const Divider(height: 1),
          Padding(
            padding: const EdgeInsets.all(12),
            child: Card(
              color: AppTheme.primaryMid.withOpacity(0.08),
              child: Padding(
                padding: const EdgeInsets.all(12),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    // Live-updated by the parent on every 15s refresh
                    // cycle while this bill's load is still active — see
                    // _LiveTrackingScreenState._liveTotalKmForSelectedRoute.
                    // Freezes at its last value once the load completes
                    // (that state simply stops being updated), and shows a
                    // loading indicator until the first fetch for this
                    // selection lands.
                    widget.liveKmUpdate == null
                        ? const Padding(
                            padding: EdgeInsets.symmetric(vertical: 4),
                            child: LinearProgressIndicator(),
                          )
                        : Text(
                            'Total KM: ${widget.liveKmUpdate!.toStringAsFixed(1)} km',
                            style: const TextStyle(
                              fontWeight: FontWeight.bold,
                              fontSize: 14,
                            ),
                          ),
                    const SizedBox(height: 8),
                    Text(
                      'Start: '
                      '${(_selectedBillDoc!.data()['siteName'] ?? '').toString()}',
                      style: const TextStyle(fontSize: 12),
                    ),
                    const SizedBox(height: 4),
                    Text(
                      'End: '
                      '${_displayEndLocation(_selectedBillDoc!.data())}',
                      style: const TextStyle(fontSize: 12),
                    ),
                  ],
                ),
              ),
            ),
          ),
        ],
      ],
    );
  }
}

