// ---------------- LIVE SPEED: thresholds, conversion, color bands ----------------
// One place for every live-speed display (map marker label, Live Tracking
// sidebar row, Vehicle Speed live badge). Change the numbers here only.
// The Vehicle Speed ROUTE polyline/legend (history) keeps its own
// _speedBandColor bands and is not affected by these.
const double kKnotsToKmh = 1.852; // Traccar always reports speed in knots.
const Duration kLiveSpeedStaleAfter = Duration(minutes: 5);
const int kLiveSpeedNormalMaxKmh = 40; // 1..40 -> green
const int kLiveSpeedModerateMaxKmh = 60; // 41..60 -> amber, 61+ -> red

enum LiveSpeedBand { offline, parked, normal, moderate, fast }

// Traccar knots -> whole km/h. null (not 0) when the position carries no
// numeric speed, so the UI can show '-' instead of a fake 0.
int? knotsToKmh(Object? knots) =>
    knots is num ? (knots.toDouble() * kKnotsToKmh).round() : null;

// Offline when there's no speed, no fix time, or the fix is older than
// kLiveSpeedStaleAfter — an old position's speed is not the current speed.
LiveSpeedBand liveSpeedBand(int? kmh, DateTime? fixTime, {DateTime? now}) {
  if (kmh == null || fixTime == null) return LiveSpeedBand.offline;
  if ((now ?? DateTime.now()).difference(fixTime) > kLiveSpeedStaleAfter) {
    return LiveSpeedBand.offline;
  }
  if (kmh <= 0) return LiveSpeedBand.parked;
  if (kmh <= kLiveSpeedNormalMaxKmh) return LiveSpeedBand.normal;
  if (kmh <= kLiveSpeedModerateMaxKmh) return LiveSpeedBand.moderate;
  return LiveSpeedBand.fast;
}

Color liveSpeedBandColor(LiveSpeedBand band) {
  switch (band) {
    case LiveSpeedBand.offline:
      return Colors.grey.shade600;
    case LiveSpeedBand.parked:
      return Colors.blueGrey.shade600;
    case LiveSpeedBand.normal:
      return Colors.green.shade700;
    case LiveSpeedBand.moderate:
      return Colors.amber.shade800;
    case LiveSpeedBand.fast:
      return Colors.red.shade700;
  }
}

// Text label that always accompanies the color (color-blind friendly).
String liveSpeedLabel(int? kmh, LiveSpeedBand band) {
  switch (band) {
    case LiveSpeedBand.offline:
      return 'Offline / no recent data';
    case LiveSpeedBand.parked:
      return '0 km/h · Parked';
    case LiveSpeedBand.normal:
      return '$kmh km/h · Normal';
    case LiveSpeedBand.moderate:
      return '$kmh km/h · Moderate';
    case LiveSpeedBand.fast:
      return '$kmh km/h · Fast';
  }
}

String liveSpeedUpdatedLabel(DateTime? fixTime, {DateTime? now}) {
  if (fixTime == null) return 'Updated: -';
  final t = fixTime.toLocal();
  final n = (now ?? DateTime.now()).toLocal();
  String two(int v) => v.toString().padLeft(2, '0');
  final time = '${two(t.hour)}:${two(t.minute)}';
  final sameDay = t.year == n.year && t.month == n.month && t.day == n.day;
  return sameDay
      ? 'Updated $time'
      : 'Updated ${two(t.day)}/${two(t.month)} $time';
}

// One live reading, as shown on a marker / sidebar row / badge.
class LiveSpeedReading {
  final int? kmh;
  final DateTime? fixTime;
  const LiveSpeedReading({this.kmh, this.fixTime});

  factory LiveSpeedReading.fromTraccarPosition(Map<String, dynamic> p) =>
      LiveSpeedReading(
        kmh: knotsToKmh(p['speed']),
        fixTime: DateTime.tryParse((p['fixTime'] ?? '').toString())?.toLocal(),
      );

  LiveSpeedBand band({DateTime? now}) => liveSpeedBand(kmh, fixTime, now: now);
  String label({DateTime? now}) => liveSpeedLabel(kmh, band(now: now));
  // Marker InfoWindow snippet — text only (Google Maps InfoWindows can't be
  // colored), so the band label carries the meaning there.
  String snippet({DateTime? now}) =>
      'Speed: ${label(now: now)} · ${liveSpeedUpdatedLabel(fixTime, now: now)}';
}

// Small colored chip + text label, used by the sidebar row.
class LiveSpeedChip extends StatelessWidget {
  final LiveSpeedReading? reading;
  const LiveSpeedChip({super.key, required this.reading});

  @override
  Widget build(BuildContext context) {
    final r = reading ?? const LiveSpeedReading();
    final band = r.band();
    final short = band == LiveSpeedBand.offline
        ? 'Offline'
        : liveSpeedLabel(r.kmh, band);
    return Tooltip(
      message: '${r.label()} · ${liveSpeedUpdatedLabel(r.fixTime)}',
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
        decoration: BoxDecoration(
          color: liveSpeedBandColor(band),
          borderRadius: BorderRadius.circular(10),
        ),
        child: Text(
          short,
          style: const TextStyle(
            color: Colors.white,
            fontSize: 10,
            fontWeight: FontWeight.bold,
          ),
        ),
      ),
    );
  }
}

