// ---------------- USER PROFILE SCREEN ----------------
class UserProfileScreen extends StatelessWidget {
  final String userId;
  final String userName;
  final String userEmail;
  final String userRole;
  final String? photoBase64;

  const UserProfileScreen({
    super.key,
    required this.userId,
    required this.userName,
    required this.userEmail,
    required this.userRole,
    this.photoBase64,
  });

  static const List<Color> _dayColors = [
    Color(0xFF3D9DE0),
    Color(0xFF4CAF7D),
    Color(0xFFE0A93D),
    Color(0xFF9B6BE0),
    Color(0xFFE05C97),
    Color(0xFF3DBFC4),
    Color(0xFFEF6C57),
    Color(0xFF7D8CE0),
  ];

  String get _collectionName =>
      userRole == 'driver' ? 'driver_sessions' : 'daily_sessions';
  String get _uidField => userRole == 'driver' ? 'driverUid' : 'supervisorUid';

  String _formatTime(dynamic ts) {
    if (ts == null) return '-';
    DateTime dt;
    if (ts is Timestamp) {
      dt = ts.toDate();
    } else {
      return '-';
    }
    final hour = dt.hour % 12 == 0 ? 12 : dt.hour % 12;
    final period = dt.hour >= 12 ? 'PM' : 'AM';
    final minute = dt.minute.toString().padLeft(2, '0');
    return '$hour:$minute $period';
  }

  String _formatDateHeader(String dateString) {
    final parts = dateString.split('-');
    if (parts.length != 3) return dateString;
    final date = DateTime(
      int.parse(parts[0]),
      int.parse(parts[1]),
      int.parse(parts[2]),
    );
    final today = DateTime.now();
    final todayStr =
        "${today.year}-${today.month.toString().padLeft(2, '0')}-${today.day.toString().padLeft(2, '0')}";
    if (dateString == todayStr) return 'Today';

    final yesterday = today.subtract(const Duration(days: 1));
    final yestStr =
        "${yesterday.year}-${yesterday.month.toString().padLeft(2, '0')}-${yesterday.day.toString().padLeft(2, '0')}";
    if (dateString == yestStr) return 'Yesterday';

    const months = [
      'Jan',
      'Feb',
      'Mar',
      'Apr',
      'May',
      'Jun',
      'Jul',
      'Aug',
      'Sep',
      'Oct',
      'Nov',
      'Dec',
    ];
    return '${date.day} ${months[date.month - 1]} ${date.year}';
  }

  // Now reads from the batch loadWorkRecordsBySessionDate already fetched
  // (see build()) instead of re-querying work_records per row — same
  // role-conditional filtering as before (drivers see every task,
  // everyone else sees isCompleted-only).
  int _loadCountFromRecords(List<Map<String, dynamic>> records) {
    if (userRole == 'driver') {
      return records.length; // count of tasks
    }
    return records.where((d) => d['isCompleted'] == true).length;
  }

  int _totalSecondsFromRecords(List<Map<String, dynamic>> records) {
    int total = 0;
    for (final data in records) {
      int seconds = (data['totalDurationSeconds'] ?? 0) as int;
      if (data['status'] == 'running' && data['lastResumedAt'] != null) {
        final lastResumedAt = (data['lastResumedAt'] as Timestamp).toDate();
        seconds += DateTime.now().difference(lastResumedAt).inSeconds;
      }
      total += seconds;
    }
    return total;
  }

  String _formatDuration(int seconds) {
    final h = seconds ~/ 3600;
    final m = (seconds % 3600) ~/ 60;
    return '${h}h ${m}m';
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Container(
        decoration: const BoxDecoration(gradient: AppTheme.mainGradient),
        child: SafeArea(
          child: Column(
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 8, 16, 0),
                child: Row(
                  children: [
                    IconButton(
                      icon: const Icon(Icons.arrow_back, color: Colors.white),
                      onPressed: () => Navigator.pop(context),
                    ),
                    const Text(
                      'User Profile',
                      style: TextStyle(
                        fontSize: 18,
                        fontWeight: FontWeight.bold,
                        color: Colors.white,
                      ),
                    ),
                  ],
                ),
              ),
              Expanded(
                child: SingleChildScrollView(
                  padding: const EdgeInsets.all(16),
                  child: Column(
                    children: [
                      // Profile header card
                      GlassCard(
                        child: Column(
                          children: [
                            CircleAvatar(
                              radius: 45,
                              backgroundColor: Colors.white.withOpacity(0.2),
                              backgroundImage: photoBase64 != null
                                  ? MemoryImage(base64Decode(photoBase64!))
                                  : null,
                              child: photoBase64 == null
                                  ? const Icon(
                                      Icons.person,
                                      size: 45,
                                      color: Colors.white,
                                    )
                                  : null,
                            ),
                            const SizedBox(height: 12),
                            Text(
                              userName,
                              style: const TextStyle(
                                color: Colors.white,
                                fontWeight: FontWeight.bold,
                                fontSize: 18,
                              ),
                            ),
                            const SizedBox(height: 4),
                            Text(
                              userEmail,
                              style: TextStyle(
                                color: Colors.white.withOpacity(0.7),
                                fontSize: 13,
                              ),
                            ),
                            const SizedBox(height: 8),
                            Container(
                              padding: const EdgeInsets.symmetric(
                                horizontal: 12,
                                vertical: 4,
                              ),
                              decoration: BoxDecoration(
                                color: AppTheme.accent.withOpacity(0.2),
                                borderRadius: BorderRadius.circular(20),
                                border: Border.all(color: AppTheme.accent),
                              ),
                              child: Text(
                                userRole.toUpperCase(),
                                style: const TextStyle(
                                  color: AppTheme.accent,
                                  fontSize: 11,
                                  fontWeight: FontWeight.bold,
                                ),
                              ),
                            ),
                          ],
                        ),
                      ),
                      const SizedBox(height: 20),

                      Align(
                        alignment: Alignment.centerLeft,
                        child: Text(
                          'Work History',
                          style: const TextStyle(
                            fontSize: 16,
                            fontWeight: FontWeight.bold,
                            color: Colors.white,
                          ),
                        ),
                      ),
                      const SizedBox(height: 12),

                      StreamBuilder<QuerySnapshot>(
                        stream: FirebaseFirestore.instance
                            .collection(_collectionName)
                            .where(_uidField, isEqualTo: userId)
                            .snapshots(),
                        builder: (context, snapshot) {
                          if (!snapshot.hasData) {
                            return const Padding(
                              padding: EdgeInsets.symmetric(vertical: 30),
                              child: CircularProgressIndicator(
                                color: Colors.white,
                              ),
                            );
                          }
                          final sessions = snapshot.data!.docs;
                          if (sessions.isEmpty) {
                            return const Padding(
                              padding: EdgeInsets.symmetric(vertical: 20),
                              child: Text(
                                'No work history yet.',
                                style: TextStyle(color: Colors.white),
                              ),
                            );
                          }

                          final Map<String, List<QueryDocumentSnapshot>>
                          grouped = {};
                          for (final doc in sessions) {
                            final data = doc.data() as Map<String, dynamic>;
                            final date = data['date'] ?? 'unknown';
                            grouped.putIfAbsent(date, () => []).add(doc);
                          }
                          final sortedDates = grouped.keys.toList()
                            ..sort((a, b) => b.compareTo(a));

                          // ONE batched query for every session on screen
                          // (see loadWorkRecordsBySessionDate's doc
                          // comment) instead of 2 work_records
                          // subcollection reads PER ROW. Every row's
                          // FutureBuilder below shares this SAME Future
                          // instance.
                          final recordsBySessionFuture =
                              loadWorkRecordsBySessionDate(sessions);

                          return Column(
                            children: List.generate(sortedDates.length, (
                              dateIndex,
                            ) {
                              final date = sortedDates[dateIndex];
                              final dayColor =
                                  _dayColors[dateIndex % _dayColors.length];
                              final daySessions = grouped[date]!;

                              return Padding(
                                padding: const EdgeInsets.only(bottom: 20),
                                child: Column(
                                  crossAxisAlignment: CrossAxisAlignment.start,
                                  children: [
                                    Row(
                                      children: [
                                        Container(
                                          width: 10,
                                          height: 10,
                                          decoration: BoxDecoration(
                                            color: dayColor,
                                            shape: BoxShape.circle,
                                          ),
                                        ),
                                        const SizedBox(width: 8),
                                        Text(
                                          _formatDateHeader(date),
                                          style: const TextStyle(
                                            color: Colors.white,
                                            fontWeight: FontWeight.bold,
                                            fontSize: 15,
                                          ),
                                        ),
                                      ],
                                    ),
                                    const SizedBox(height: 10),
                                    ...daySessions.map((doc) {
                                      final data =
                                          doc.data() as Map<String, dynamic>;
                                      final isActive =
                                          data['status'] == 'active';

                                      return Padding(
                                        padding: const EdgeInsets.only(
                                          bottom: 10,
                                          left: 18,
                                        ),
                                        child: Container(
                                          decoration: BoxDecoration(
                                            color: Colors.white.withOpacity(
                                              0.1,
                                            ),
                                            borderRadius: BorderRadius.circular(
                                              14,
                                            ),
                                            border: Border(
                                              left: BorderSide(
                                                color: dayColor,
                                                width: 4,
                                              ),
                                            ),
                                          ),
                                          padding: const EdgeInsets.all(14),
                                          child: Column(
                                            crossAxisAlignment:
                                                CrossAxisAlignment.start,
                                            children: [
                                              Row(
                                                mainAxisAlignment:
                                                    MainAxisAlignment
                                                        .spaceBetween,
                                                children: [
                                                  Expanded(
                                                    child: Text(
                                                      '${data['machineName'] ?? ''} • ${data['siteName'] ?? ''}',
                                                      style: const TextStyle(
                                                        color: Colors.white,
                                                        fontWeight:
                                                            FontWeight.bold,
                                                        fontSize: 14,
                                                      ),
                                                    ),
                                                  ),
                                                  Container(
                                                    padding:
                                                        const EdgeInsets.symmetric(
                                                          horizontal: 8,
                                                          vertical: 3,
                                                        ),
                                                    decoration: BoxDecoration(
                                                      color: isActive
                                                          ? Colors.green
                                                          : Colors.grey,
                                                      borderRadius:
                                                          BorderRadius.circular(
                                                            20,
                                                          ),
                                                    ),
                                                    child: Text(
                                                      isActive
                                                          ? 'ACTIVE'
                                                          : 'DONE',
                                                      style: const TextStyle(
                                                        color: Colors.white,
                                                        fontSize: 10,
                                                      ),
                                                    ),
                                                  ),
                                                ],
                                              ),
                                              const SizedBox(height: 4),
                                              Text(
                                                'Started: ${_formatTime(data['createdAt'])}'
                                                '${data['completedAt'] != null ? "  •  Ended: ${_formatTime(data['completedAt'])}" : ""}',
                                                style: TextStyle(
                                                  color: Colors.white
                                                      .withOpacity(0.6),
                                                  fontSize: 11,
                                                ),
                                              ),
                                              if (data['startMeter'] !=
                                                  null) ...[
                                                const SizedBox(height: 4),
                                                Text(
                                                  'Start Meter: ${data['startMeter']}'
                                                  '${data['endMeter'] != null ? "  •  End Meter: ${data['endMeter']}" : ""}',
                                                  style: TextStyle(
                                                    color: Colors.white
                                                        .withOpacity(0.7),
                                                    fontSize: 12,
                                                  ),
                                                ),
                                              ],
                                              const SizedBox(height: 8),
                                              FutureBuilder<
                                                  Map<String,
                                                      List<Map<String, dynamic>>>>(
                                                future: recordsBySessionFuture,
                                                builder: (context, futureSnap) {
                                                  if (!futureSnap.hasData) {
                                                    return const SizedBox(
                                                      height: 16,
                                                      width: 16,
                                                      child:
                                                          CircularProgressIndicator(
                                                            strokeWidth: 2,
                                                            color: Colors.white,
                                                          ),
                                                    );
                                                  }
                                                  final records =
                                                      futureSnap
                                                          .data![doc.id] ??
                                                          const [];
                                                  final count =
                                                      _loadCountFromRecords(
                                                          records);
                                                  final seconds =
                                                      _totalSecondsFromRecords(
                                                          records);
                                                  return Row(
                                                    children: [
                                                      Icon(
                                                        userRole == 'driver'
                                                            ? Icons.checklist
                                                            : Icons
                                                                  .local_shipping,
                                                        size: 14,
                                                        color: Colors.white
                                                            .withOpacity(0.7),
                                                      ),
                                                      const SizedBox(width: 4),
                                                      Text(
                                                        userRole == 'driver'
                                                            ? '$count tasks'
