// ---------------- DRIVER → TRUCK ASSIGNMENT ----------------
// The only assignment record in the app is on the TRUCK side:
// trucks/{id}.assignedDriverUid (+ assignedDriverName for display), written
// by Vehicle Registration (_VehicleRegistrationTab) and Truck Profile's
// "Change Assigned Driver" dialog. One truck → at most one driver uid; the
// same uid may be set on several trucks, so a driver can have 0, 1 or many.
// A manually typed name leaves assignedDriverUid null and so never matches
// a logged-in driver.
const String kNoTruckAssignedMessage = 'No truck assigned, contact admin.';
const String kTruckNotAssignedMessage = 'This truck is not assigned to you.';

bool isTruckAssignedTo(Map<String, dynamic>? truckData, String? uid) {
  if (truckData == null || uid == null || uid.isEmpty) return false;
  final assigned = truckData['assignedDriverUid'];
  return assigned is String && assigned.isNotEmpty && assigned == uid;
}

/// Add User default: every role=='driver' account can drive trucks; a
/// field_worker keeps its checkbox; every other role is false.
bool newUserCanDriveTruck(String role, bool fieldWorkerCanDriveTruck) {
  if (role == 'driver') return true;
  if (role == 'field_worker') return fieldWorkerCanDriveTruck;
  return false;
}

/// Who may be picked in the "Assign Driver" / "Change Assigned Driver"
/// lists: every role=='driver' user, plus field_workers with
/// canDriveTruck==true. Every other role is excluded.
bool isAssignableTruckDriver(Map<String, dynamic>? user) {
  if (user == null) return false;
  final role = user['role'];
  if (role == 'driver') return true;
  return role == 'field_worker' && user['canDriveTruck'] == true;
}

/// One query for both lists (role in [driver, field_worker] — a
/// single-field filter, no composite index), then filtered + sorted by
/// name client-side.
Stream<QuerySnapshot<Map<String, dynamic>>> assignableTruckDriversStream(
    {FirebaseFirestore? db}) {
  return (db ?? FirebaseFirestore.instance)
      .collection('users')
      .where('role', whereIn: ['driver', 'field_worker']).snapshots();
}

List<T> assignableTruckDrivers<T extends DocumentSnapshot>(Iterable<T> users) {
  String nameOf(T d) =>
      ((d.data() as Map<String, dynamic>?)?['name'] ?? '').toString();
  return users
      .where((d) => isAssignableTruckDriver(d.data() as Map<String, dynamic>?))
      .toList()
    ..sort((a, b) => nameOf(a).toLowerCase().compareTo(nameOf(b).toLowerCase()));
}

/// A truck that has a driver NAME but no assignedDriverUid (typed name, or
/// an old record) — no logged-in driver can ever match it.
const String kDriverNotLinkedMessage = 'Driver not linked - re-assign';

bool truckDriverNotLinked(Map<String, dynamic>? truck) {
  if (truck == null) return false;
  final name = (truck['assignedDriverName'] ?? '').toString().trim();
  final uid = (truck['assignedDriverUid'] ?? '').toString().trim();
  return name.isNotEmpty && uid.isEmpty;
}

