    );
  }
}

/// Trucks assigned to [uid], sorted by truck number.
List<T> trucksAssignedTo<T extends DocumentSnapshot>(
    Iterable<T> trucks, String? uid) {
  final list = trucks
      .where((d) => isTruckAssignedTo(d.data() as Map<String, dynamic>?, uid))
      .toList()
    ..sort((a, b) => ((a.data() as Map<String, dynamic>?)?['truckNumber'] ?? '')
        .toString()
        .compareTo(
            ((b.data() as Map<String, dynamic>?)?['truckNumber'] ?? '').toString()));
  return list;
}

/// Gate for every driver truck-session start (list tap, or any future QR /
/// deep-link path): null = allowed, otherwise the message to show.
String? driverTruckStartBlockReason({
  required String? uid,
  required Map<String, dynamic>? truckData,
}) {
  if (uid == null || uid.isEmpty) return 'Not signed in — please log in again.';
  if (isTruckAssignedTo(truckData, uid)) return null;
  return kTruckNotAssignedMessage;
}

/// Reuses the driver's own active truck_sessions doc for this truck today,
/// or creates one. Only the driver's OWN sessions are queried
/// (driverUid == uid): the rules only let a driver read their own session
/// docs, and two drivers on the same truck/day each get their own.
Future<({String sessionId, String? siteId})> ensureDriverTruckSession({
  required FirebaseFirestore db,
  required String uid,
  required String driverName,
  required String truckId,
  required String truckNumber,
  Map<String, dynamic> extraFields = const {},
}) async {
  final dateString = dailyCheckDateKey(DateTime.now());
  debugPrint('[DRIVER] session create/lookup START truckId=$truckId date=$dateString');
  final existing = await logDriverFs(
    'QUERY truck_sessions where driverUid=$uid truckId=$truckId '
    'date=$dateString status=active',
    () => db
        .collection('truck_sessions')
        .where('driverUid', isEqualTo: uid)
        .where('truckId', isEqualTo: truckId)
        .where('date', isEqualTo: dateString)
        .where('status', isEqualTo: 'active')
        .limit(1)
        .get(),
  );
  if (existing.docs.isNotEmpty) {
    final id = existing.docs.first.id;
    debugPrint('[DRIVER] session create/lookup DONE reused sessionId=$id');
    return (sessionId: id, siteId: existing.docs.first.data()['siteId'] as String?);
  }
  final docRef = await logDriverFs(
    'ADD truck_sessions driverUid=$uid truckId=$truckId date=$dateString',
    () => db.collection('truck_sessions').add({
      'driverUid': uid,
      'driverName': driverName,
      'truckId': truckId,
      'truckNumber': truckNumber,
      'date': dateString,
      'status': 'active',
      'createdAt': FieldValue.serverTimestamp(),
      ...extraFields,
    }),
  );
  debugPrint('[DRIVER] session create/lookup DONE created sessionId=${docRef.id}');
  return (sessionId: docRef.id, siteId: null);
}

// ---------------- DRIVER HOME (daily check only) ----------------
// Home for role 'driver' and for a field_worker who can ONLY drive trucks.
// Drivers do nothing in this system except the Daily Check of their
// assigned truck(s): no Machines, no trips/bill/cube/work entry.
//
// A truck_sessions doc is still created when the driver STARTS a check
// (mode: 'daily_check_only', no trips/location_points) because the
// "NOT CHECKED TODAY" lists (Service Alerts + Daily Checks screen) are
// computed as "active truck_sessions today with no daily_checks doc", and
// Truck Profile's session history shows who had the truck. It is marked
// completed as soon as the check is submitted.
String formatClockTime(Object? ts) {
  if (ts is! Timestamp) return '-';
  final d = ts.toDate();
  return '${d.hour.toString().padLeft(2, '0')}:${d.minute.toString().padLeft(2, '0')}';
}

class DriverHomeScreen extends StatefulWidget {
  final String name;
  final FirebaseFirestore? firestoreOverride;
  final String? currentUidOverride;
  final DailyCheckPhotoUploader? photoUploaderOverride;
  final Map<String, Uint8List>? debugInitialPhotos;
  const DriverHomeScreen({
    super.key,
    required this.name,
    this.firestoreOverride,
    this.currentUidOverride,
    this.photoUploaderOverride,
    this.debugInitialPhotos,
  });

  @override
  State<DriverHomeScreen> createState() => _DriverHomeScreenState();
}

class _DriverHomeScreenState extends State<DriverHomeScreen> {
  FirebaseFirestore get _db => widget.firestoreOverride ?? FirebaseFirestore.instance;
  String? get _uid => widget.currentUidOverride ?? FirebaseAuth.instance.currentUser?.uid;

  late Stream<QuerySnapshot> _trucksStream;
  final Map<String, Future<Map<String, dynamic>?>> _todayCheck = {};
  bool _busy = false;

  @override
  void initState() {
    super.initState();
    _trucksStream = ReferenceCollectionCache.stream('trucks', db: _db);
  }

  void _retry() {
    setState(() {
      _trucksStream =
          ReferenceCollectionCache.stream('trucks', db: _db, forceRefresh: true);
      _todayCheck.clear();
    });
  }

  // Today's daily_checks/{TRUCK}_{date} doc (same deterministic id the
  // form writes), or null when not submitted / unreadable.
  Future<Map<String, dynamic>?> _loadTodayCheck(String truckNumber) async {
    try {
      final snap = await _db
          .collection('daily_checks')
          .doc(dailyCheckDocId(truckNumber, DateTime.now()))
          .get();
      return snap.exists ? snap.data() : null;
    } catch (e) {
      debugPrint('[DRIVER] today check read ERROR $truckNumber: $e');
      return null;
    }
  }

  Future<Map<String, dynamic>?> _checkFor(String truckNumber) =>
      _todayCheck.putIfAbsent(truckNumber, () => _loadTodayCheck(truckNumber));

  void _snack(String message) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text(message), backgroundColor: Colors.red[700]),
    );
  }

  Future<void> _startCheck(QueryDocumentSnapshot truckDoc) async {
    if (_busy) return;
    setState(() => _busy = true);
    try {
      var data = truckDoc.data() as Map<String, dynamic>;
      try {
        final fresh = await _db.collection('trucks').doc(truckDoc.id).get();
        if (fresh.exists && fresh.data() != null) data = fresh.data()!;
      } catch (e) {
        debugPrint('[DRIVER] truck re-check read ERROR (using list data): $e');
      }
      final uid = _uid;
      final blocked = driverTruckStartBlockReason(uid: uid, truckData: data);
      if (blocked != null) {
        _snack(blocked);
        return;
      }
      final truckNumber = normalizeVehicleNumber((data['truckNumber'] ?? '').toString());

      // Non-blocking: the session only feeds the NOT CHECKED TODAY lists;
      // a failure must never stop the driver doing the check itself.
      String? sessionId;
      String? siteId;
      try {
        final s = await ensureDriverTruckSession(
          db: _db,
          uid: uid!,
          driverName: widget.name,
          truckId: truckDoc.id,
          truckNumber: truckNumber,
          extraFields: const {'mode': 'daily_check_only'},
        );
        sessionId = s.sessionId;
        siteId = s.siteId;
      } catch (e) {
        debugPrint('[DRIVER] daily-check session create FAILED (continuing): $e');
      }

      if (!mounted) return;
      final submitted = await Navigator.push<bool>(
        context,
        MaterialPageRoute(
          builder: (_) => DriverDailyCheckScreen(
            vehicleNumber: truckNumber,
            driverName: widget.name,
            siteId: siteId,
            showSuccessScreen: true,
            firestoreOverride: widget.firestoreOverride,
            currentUidOverride: widget.currentUidOverride,
            photoUploaderOverride: widget.photoUploaderOverride,
            debugInitialPhotos: widget.debugInitialPhotos,
          ),
        ),
      );
      if (submitted == true && sessionId != null) {
        try {
          await _db.collection('truck_sessions').doc(sessionId).update({
            'status': 'completed',
            'completedAt': FieldValue.serverTimestamp(),
            'dailyCheckSubmitted': true,
          });
        } catch (e) {
          debugPrint('[DRIVER] daily-check session close FAILED: $e');
        }
      }
      if (mounted) {
        setState(() {
          _todayCheck.remove(truckNumber);
        });
      }
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  Widget _messageView(String text, {Key? key}) => Center(
        key: key,
        child: Padding(
          padding: const EdgeInsets.all(24),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              const Icon(Icons.local_shipping_outlined, color: Colors.white, size: 40),
              const SizedBox(height: 12),
              Text(
                text,
                style: const TextStyle(color: Colors.white, fontWeight: FontWeight.bold),
                textAlign: TextAlign.center,
              ),
              const SizedBox(height: 16),
              OutlinedButton(
                onPressed: _retry,
                style: OutlinedButton.styleFrom(
                  foregroundColor: Colors.white,
                  side: const BorderSide(color: Colors.white),
                ),
                child: const Text('RETRY'),
              ),
            ],
          ),
        ),
      );

  Widget _truckCard(QueryDocumentSnapshot truck) {
    final truckNumber = normalizeVehicleNumber(
        ((truck.data() as Map<String, dynamic>)['truckNumber'] ?? '').toString());
    return Card(
      key: ValueKey('driver-home-truck-${truck.id}'),
      margin: const EdgeInsets.only(bottom: 12),
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: FutureBuilder<Map<String, dynamic>?>(
          future: _checkFor(truckNumber),
          builder: (context, snap) {
            final header = Row(
              children: [
                const Icon(Icons.local_shipping, color: Colors.deepOrange),
                const SizedBox(width: 8),
                Expanded(
                  child: Text(
                    truckNumber,
                    style: const TextStyle(fontSize: 18, fontWeight: FontWeight.bold),
                  ),
                ),
              ],
            );
            if (snap.connectionState != ConnectionState.done) {
              return Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  header,
                  const SizedBox(height: 12),
                  const LinearProgressIndicator(),
                ],
              );
            }
            final check = snap.data;
            if (check != null) {
              return Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  header,
                  const SizedBox(height: 12),
                  Row(
                    children: [
                      Icon(Icons.check_circle, color: AppColors.success),
                      const SizedBox(width: 8),
                      Expanded(
                        child: Text(
                          "Today's daily check is done "
                          '(${formatClockTime(check['submittedAt'] ?? check['updatedAt'])})',
                          key: const ValueKey('driver-check-done'),
                          style: TextStyle(
                            color: AppColors.success,
                            fontWeight: FontWeight.w600,
                          ),
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 8),
                  Align(
                    alignment: Alignment.centerRight,
                    child: OutlinedButton.icon(
                      key: const ValueKey('driver-check-view'),
                      icon: const Icon(Icons.visibility),
                      label: const Text('VIEW'),
                      onPressed: () => Navigator.push(
                        context,
                        MaterialPageRoute(
                          builder: (_) => DailyCheckReadOnlyScreen(
                            truckNumber: truckNumber,
                            data: check,
                          ),
                        ),
                      ),
                    ),
                  ),
                ],
              );
            }
            return Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                header,
                const SizedBox(height: 4),
                const Text("Today's daily check is not done yet."),
                const SizedBox(height: 12),
                SizedBox(
                  width: double.infinity,
                  child: ElevatedButton.icon(
                    key: const ValueKey('driver-check-start'),
                    onPressed: _busy ? null : () => _startCheck(truck),
                    style: ElevatedButton.styleFrom(
                      backgroundColor: AppColors.navy,
                      foregroundColor: Colors.white,
                      padding: const EdgeInsets.symmetric(vertical: 14),
                    ),
                    icon: const Icon(Icons.fact_check),
                    label: const Text('START DAILY CHECK'),
                  ),
                ),
              ],
            );
          },
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Container(
        decoration: const BoxDecoration(gradient: AppTheme.mainGradient),
        child: SafeArea(
          child: Column(
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 8, 16, 0),
                child: Row(
                  children: [
                    Expanded(
                      child: Text(
                        'Welcome, ${widget.name}',
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                          fontSize: 18,
                          fontWeight: FontWeight.bold,
                          color: Colors.white,
                        ),
                      ),
                    ),
                    IconButton(
                      icon: const Icon(Icons.logout, color: Colors.white),
                      onPressed: () async {
                        await FirebaseAuth.instance.signOut();
                        if (context.mounted) {
                          Navigator.pushReplacement(
                            context,
                            MaterialPageRoute(builder: (_) => const LoginScreen()),
                          );
                        }
                      },
                    ),
                  ],
                ),
              ),
              Expanded(
                child: StreamBuilder<QuerySnapshot>(
                  stream: _trucksStream,
                  builder: (context, snapshot) {
                    if (snapshot.hasError) {
                      return _messageView('Failed to load trucks: ${snapshot.error}');
                    }
                    if (!snapshot.hasData) {
                      return const Center(
                        child: CircularProgressIndicator(color: Colors.white),
                      );
                    }
                    final assigned = trucksAssignedTo(snapshot.data!.docs, _uid);
                    if (assigned.isEmpty) {
                      return _messageView(kNoTruckAssignedMessage,
                          key: const ValueKey('driver-no-truck'));
                    }
                    return Center(
                      child: ConstrainedBox(
                        constraints: const BoxConstraints(maxWidth: 560),
                        child: ListView(
                          padding: const EdgeInsets.all(16),
                          children: [
                            Text(
                              assigned.length == 1
                                  ? 'Your assigned truck'
                                  : 'Your assigned trucks',
                              style: TextStyle(
                                color: Colors.white.withOpacity(0.85),
                                fontWeight: FontWeight.w600,
                              ),
                            ),
                            const SizedBox(height: 4),
                            Text(
                              'Daily Vehicle Check',
                              style: TextStyle(
                                color: Colors.white.withOpacity(0.7),
                                fontSize: 13,
                              ),
                            ),
                            const SizedBox(height: 12),
                            for (final t in assigned) _truckCard(t),
                          ],
                        ),
                      ),
                    );
                  },
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

