// ---------------- TRUCK: SELECT TRUCK ----------------
// Driver-only screen (role 'driver' via DriverTypeScreen, or a
// field_worker with canDriveTruck). Shows ONLY the trucks assigned to the
// signed-in driver; there is no free picker any more.
class TruckTypeScreen extends StatefulWidget {
  final String name;
  final FirebaseFirestore? firestoreOverride;
  final String? currentUidOverride;
  const TruckTypeScreen({
    super.key,
    required this.name,
    this.firestoreOverride,
    this.currentUidOverride,
  });

  @override
  State<TruckTypeScreen> createState() => _TruckTypeScreenState();
}

class _TruckTypeScreenState extends State<TruckTypeScreen> {
  FirebaseFirestore get _db => widget.firestoreOverride ?? FirebaseFirestore.instance;
  String? get _uid => widget.currentUidOverride ?? FirebaseAuth.instance.currentUser?.uid;

  bool _busy = false;
  late Stream<QuerySnapshot> _trucksStream;
  // The driver's open (status=active, today) truck session, if any —
  // loaded once so an assignment change made while it is open is shown
  // next to it instead of the session being dropped silently.
  late Future<QueryDocumentSnapshot<Map<String, dynamic>>?> _openSessionFuture;

  @override
  void initState() {
    super.initState();
    _trucksStream = ReferenceCollectionCache.stream('trucks', db: _db);
    _openSessionFuture = _loadOpenSession();
  }

  void _retry() {
    debugPrint('[DRIVER] trucks stream RETRY');
    setState(() {
      _trucksStream = ReferenceCollectionCache.stream('trucks', db: _db, forceRefresh: true);
      _openSessionFuture = _loadOpenSession();
    });
  }

  Future<QueryDocumentSnapshot<Map<String, dynamic>>?> _loadOpenSession() async {
    final uid = _uid;
    if (uid == null) return null;
    try {
      // Same driverUid+status filter DriverTypeScreen already uses; the
      // date is matched client-side so no new composite index is needed.
      final snap = await _db
          .collection('truck_sessions')
          .where('driverUid', isEqualTo: uid)
          .where('status', isEqualTo: 'active')
          .get();
      final today = dailyCheckDateKey(DateTime.now());
      for (final d in snap.docs) {
        if (d.data()['date'] == today) return d;
      }
    } catch (e) {
      debugPrint('[DRIVER] open truck session lookup ERROR: $e');
    }
    return null;
  }

  void _continueSession(QueryDocumentSnapshot<Map<String, dynamic>> session) {
    final data = session.data();
    Navigator.push(
      context,
      MaterialPageRoute(
        builder: (_) => TruckWorkAreaScreen(
          sessionId: session.id,
          truckNumber: (data['truckNumber'] ?? '').toString(),
          siteName: '',
          driverName: widget.name,
        ),
      ),
    );
  }

  void _showMessage(String message) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text(message), backgroundColor: Colors.red[700]),
    );
  }

  Widget _noTruckAssigned() {
    return Center(
      key: const ValueKey('driver-no-truck'),
      child: Padding(
        padding: const EdgeInsets.all(24),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            const Icon(Icons.local_shipping_outlined, color: Colors.white, size: 40),
            const SizedBox(height: 12),
            const Text(
              kNoTruckAssignedMessage,
              style: TextStyle(color: Colors.white, fontWeight: FontWeight.bold),
              textAlign: TextAlign.center,
            ),
            const SizedBox(height: 16),
            OutlinedButton(
              onPressed: _retry,
              style: OutlinedButton.styleFrom(
                foregroundColor: Colors.white,
                side: const BorderSide(color: Colors.white),
              ),
              child: const Text('RETRY'),
            ),
          ],
        ),
      ),
    );
  }

  Widget _staleSessionCard(
    QueryDocumentSnapshot<Map<String, dynamic>> session,
    List<QueryDocumentSnapshot> assigned,
  ) {
    final oldNumber = (session.data()['truckNumber'] ?? '').toString();
    final newNumbers = assigned
        .map((d) => ((d.data() as Map<String, dynamic>)['truckNumber'] ?? '').toString())
        .join(', ');
    return Container(
      key: const ValueKey('driver-stale-session'),
      margin: const EdgeInsets.only(bottom: 16),
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: Colors.amber[50],
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: Colors.amber[700]!),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            'Your truck assignment has changed.',
            style: TextStyle(fontWeight: FontWeight.bold, color: Colors.brown[800]),
          ),
          const SizedBox(height: 4),
          Text(
            'You still have an open session on $oldNumber today. '
            '${assigned.isEmpty ? 'You have no truck assigned now.' : 'Now assigned: $newNumbers.'} '
            'End the day on $oldNumber when you finish.',
            style: TextStyle(color: Colors.brown[800]),
          ),
          const SizedBox(height: 8),
          Align(
            alignment: Alignment.centerRight,
            child: ElevatedButton(
              key: const ValueKey('driver-continue-session'),
              onPressed: () => _continueSession(session),
              style: ElevatedButton.styleFrom(backgroundColor: Colors.amber[800]),
              child: Text('CONTINUE $oldNumber',
                  style: const TextStyle(color: Colors.white)),
            ),
          ),
        ],
      ),
    );
  }

  Future<void> _selectTruck(QueryDocumentSnapshot truckDoc) async {
    if (_busy) return;
    var data = truckDoc.data() as Map<String, dynamic>;
    final truckNumber = normalizeVehicleNumber((data['truckNumber'] ?? '').toString());
    debugPrint('[DRIVER] tapped truck id=${truckDoc.id} truckNumber=$truckNumber');
    setState(() => _busy = true);
    try {
      final uid = _uid;
      // Re-check the assignment against the live truck doc right before a
      // session is created, so a stale list (assignment just changed) or
      // any other entry path can't start a session on someone else's truck.
      try {
        final fresh = await _db.collection('trucks').doc(truckDoc.id).get();
        if (fresh.exists && fresh.data() != null) data = fresh.data()!;
      } catch (e) {
        debugPrint('[DRIVER] truck re-check read ERROR (using list data): $e');
      }
      final blocked = driverTruckStartBlockReason(uid: uid, truckData: data);
      if (blocked != null) {
        debugPrint('[DRIVER] session start BLOCKED truck=$truckNumber: $blocked');
        _showMessage(blocked);
        return;
      }
      if (uid == null) {
        throw Exception('Not signed in — please log in again.');
      }
      final session = await ensureDriverTruckSession(
        db: _db,
        uid: uid,
        driverName: widget.name,
        truckId: truckDoc.id,
        truckNumber: truckNumber,
      );
      final sessionId = session.sessionId;
      final siteId = session.siteId;

      if (!mounted) return;

      // Non-blocking: truck selection must never abort just because these
      // two reads (whether today's check exists, whether it can be
      // skipped) failed — e.g. live permission-denied while this app's own
      // widget tests can't reproduce rules at all. On failure, fall back
      // to the safest assumption (not submitted yet, must complete) and
      // surface a small warning instead of aborting into the outer catch.
      bool submittedToday;
      try {
        submittedToday = await dailyCheckSubmittedToday(truckNumber, db: _db, uid: uid);
        debugPrint('[DRIVER] daily check submittedToday=$submittedToday for $truckNumber');
      } catch (e) {
        debugPrint('[DRIVER] daily check read FAILED — treating as NOT submitted: $e');
        submittedToday = false;
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text("Couldn't confirm today's check status — opening it anyway. $e"),
              duration: const Duration(seconds: 4),
            ),
          );
        }
      }
      if (!submittedToday) {
        bool allowSkip;
        try {
          allowSkip = await fetchDailyCheckAllowSkip(db: _db, uid: uid);
        } catch (e) {
          debugPrint(
              '[DRIVER] allow-skip settings read FAILED — defaulting requireDailyCheck=true: $e');
          allowSkip = false;
          if (mounted) {
            ScaffoldMessenger.of(context).showSnackBar(
              SnackBar(
                content: Text("Couldn't load check settings — treating it as required. $e"),
                duration: const Duration(seconds: 4),
              ),
            );
          }
        }
        debugPrint('[DRIVER] auto-opening daily check for $truckNumber allowSkip=$allowSkip');
        if (!mounted) return;
        await Navigator.push(
          context,
          MaterialPageRoute(
            builder: (_) => DriverDailyCheckScreen(
              vehicleNumber: truckNumber,
              driverName: widget.name,
              siteId: siteId,
              allowSkip: allowSkip,
              firestoreOverride: widget.firestoreOverride,
              currentUidOverride: widget.currentUidOverride,
            ),
          ),
        );
      }

      if (!mounted) return;
      debugPrint('[DRIVER] navigating to TruckWorkAreaScreen sessionId=$sessionId');
      Navigator.push(
        context,
        MaterialPageRoute(
          builder: (_) => TruckWorkAreaScreen(
            sessionId: sessionId,
            truckNumber: truckNumber,
            siteName: '',
            driverName: widget.name,
          ),
        ),
      );
    } catch (e, st) {
      debugPrint('[DRIVER] select truck ERROR: $e\n$st');
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Could not select this truck: $e')),
        );
      }
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Container(
        decoration: const BoxDecoration(gradient: AppTheme.mainGradient),
        child: SafeArea(
          child: Column(
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 8, 16, 0),
                child: Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    const Text(
                      'Your Truck',
                      style: TextStyle(
                        fontSize: 18,
                        fontWeight: FontWeight.bold,
                        color: Colors.white,
                      ),
                    ),
                    IconButton(
                      icon: const Icon(Icons.logout, color: Colors.white),
                      onPressed: () async {
                        await FirebaseAuth.instance.signOut();
                        if (context.mounted) {
                          Navigator.pushReplacement(
                            context,
                            MaterialPageRoute(
                              builder: (_) => const LoginScreen(),
                            ),
                          );
                        }
                      },
                    ),
                  ],
                ),
              ),
              Expanded(
                child: StreamBuilder<QuerySnapshot>(
                  stream: _trucksStream,
                  builder: (context, snapshot) {
                    if (snapshot.hasError) {
                      debugPrint('[DRIVER] trucks stream ERROR: ${snapshot.error}');
                      return Center(
                        child: Padding(
                          padding: const EdgeInsets.all(24),
                          child: Column(
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              const Icon(Icons.error_outline, color: Colors.white, size: 40),
                              const SizedBox(height: 12),
                              Text(
                                'Failed to load trucks: ${snapshot.error}',
                                style: const TextStyle(color: Colors.white),
                                textAlign: TextAlign.center,
                              ),
                              const SizedBox(height: 16),
                              OutlinedButton(
                                onPressed: _retry,
                                style: OutlinedButton.styleFrom(
                                  foregroundColor: Colors.white,
                                  side: const BorderSide(color: Colors.white),
                                ),
                                child: const Text('RETRY'),
                              ),
                            ],
                          ),
                        ),
                      );
                    }
                    if (!snapshot.hasData) {
                      return const Center(
                        child: CircularProgressIndicator(color: Colors.white),
                      );
                    }
                    final uid = _uid;
                    final assigned =
                        trucksAssignedTo(snapshot.data!.docs, uid);
                    debugPrint('[DRIVER] trucks stream loaded '
                        'total=${snapshot.data!.docs.length} '
                        'assignedToMe=${assigned.length}');
                    return FutureBuilder<
                        QueryDocumentSnapshot<Map<String, dynamic>>?>(
                      future: _openSessionFuture,
                      builder: (context, sessionSnap) {
                        final open = sessionSnap.data;
                        final openTruckId = open?.data()['truckId'];
                        // An open session on a truck that is no longer
                        // assigned: never ended silently — offered as
                        // CONTINUE next to the new assignment.
                        final staleOpen = open != null &&
                                !assigned.any((d) => d.id == openTruckId)
                            ? open
                            : null;
                        if (assigned.isEmpty && staleOpen == null) {
                          return _noTruckAssigned();
                        }
                        return ListView(
                          padding: const EdgeInsets.all(16),
                          children: [
                            if (staleOpen != null)
                              _staleSessionCard(staleOpen, assigned),
                            if (assigned.isEmpty)
                              _noTruckAssigned()
                            else ...[
                              Padding(
                                padding: const EdgeInsets.only(bottom: 12),
                                child: Text(
                                  assigned.length == 1
                                      ? 'Your assigned truck'
                                      : 'Your assigned trucks',
                                  style: TextStyle(
                                    color: Colors.white.withOpacity(0.85),
                                    fontWeight: FontWeight.w600,
                                  ),
                                ),
                              ),
                              for (final truck in assigned)
                                Padding(
                                  key: ValueKey('driver-truck-${truck.id}'),
                                  padding: const EdgeInsets.only(bottom: 12),
                                  child: Opacity(
                                    opacity: _busy ? 0.6 : 1.0,
                                    child: DashboardMenuCard(
                                      icon: Icons.local_shipping,
                                      title: ((truck.data() as Map<String,
                                                  dynamic>)['truckNumber'] ??
                                              '')
                                          .toString(),
                                      subtitle: open?.data()['truckId'] ==
                                              truck.id
                                          ? 'Session open today — tap to continue'
                                          : 'Tap to start your session',
                                      color: Colors.deepOrange,
                                      onTap: _busy
                                          ? () {}
                                          : () => _selectTruck(truck),
                                    ),
                                  ),
                                ),
                            ],
                          ],
                        );
                      },
                    );
                  },
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

// ---------------- TRUCK: SITE SELECT + CODE VERIFY ----------------
class TruckSiteSelectScreen extends StatefulWidget {
  final String name;
  final String truckId;
  final String truckNumber;

  const TruckSiteSelectScreen({
    super.key,
    required this.name,
    required this.truckId,
    required this.truckNumber,
  });

  @override
  State<TruckSiteSelectScreen> createState() => _TruckSiteSelectScreenState();
}

class _TruckSiteSelectScreenState extends State<TruckSiteSelectScreen> {
  String? _selectedSiteId;
  String? _selectedSiteName;
  final _codeController = TextEditingController();
  bool _isLoading = false;

  Future<void> _submit() async {
    if (_selectedSiteId == null) {
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(const SnackBar(content: Text('Please select a site.')));
      return;
    }
    if (_codeController.text.trim().length != 4) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Please enter the 4-digit supervisor code.'),
        ),
      );
      return;
    }

    setState(() => _isLoading = true);

    try {
      final today = DateTime.now();
      final dateString =
          "${today.year}-${today.month.toString().padLeft(2, '0')}-${today.day.toString().padLeft(2, '0')}";

      final supervisorMatch = await FirebaseFirestore.instance
          .collection('daily_sessions')
          .where('siteId', isEqualTo: _selectedSiteId)
          .where('date', isEqualTo: dateString)
          .where('status', isEqualTo: 'active')
          .where('verificationCode', isEqualTo: _codeController.text.trim())
          .limit(1)
          .get();

      if (supervisorMatch.docs.isEmpty) {
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(
              content: Text('Invalid code. Check with your supervisor.'),
            ),
          );
          setState(() => _isLoading = false);
        }
        return;
      }

      final existing = await FirebaseFirestore.instance
          .collection('truck_sessions')
          .where('truckId', isEqualTo: widget.truckId)
          .where('date', isEqualTo: dateString)
          .where('status', isEqualTo: 'active')
          .limit(1)
          .get();

      String sessionId;

      if (existing.docs.isNotEmpty) {
        sessionId = existing.docs.first.id;
      } else {
        final docRef = await FirebaseFirestore.instance
            .collection('truck_sessions')
            .add({
              'driverUid': FirebaseAuth.instance.currentUser!.uid,
              'driverName': widget.name,
              'truckId': widget.truckId,
              'truckNumber': widget.truckNumber,
              'siteId': _selectedSiteId,
              'siteName': _selectedSiteName,
              'supervisorSessionId': supervisorMatch.docs.first.id,
              'date': dateString,
              'status': 'active',
              'createdAt': FieldValue.serverTimestamp(),
            });
        sessionId = docRef.id;
      }

      if (mounted) {
        Navigator.push(
          context,
          MaterialPageRoute(
            builder: (_) => TruckWorkAreaScreen(
              sessionId: sessionId,
              truckNumber: widget.truckNumber,
              siteName: _selectedSiteName ?? '',
              driverName: widget.name,
            ),
          ),
        );
      }
    } catch (e) {
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(SnackBar(content: Text('Error: $e')));
    } finally {
      if (mounted) setState(() => _isLoading = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Container(
        decoration: const BoxDecoration(gradient: AppTheme.mainGradient),
        child: SafeArea(
          child: Column(
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 8, 16, 0),
                child: Row(
                  children: [
                    IconButton(
                      icon: const Icon(Icons.arrow_back, color: Colors.white),
                      onPressed: () => Navigator.pop(context),
                    ),
                    Text(
                      widget.truckNumber,
                      style: const TextStyle(
                        fontSize: 18,
                        fontWeight: FontWeight.bold,
                        color: Colors.white,
                      ),
                    ),
                  ],
                ),
              ),
              Expanded(
                child: Padding(
                  padding: const EdgeInsets.all(16.0),
                  child: GlassCard(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        const Text(
                          'Select Working Site',
                          style: TextStyle(
                            fontWeight: FontWeight.bold,
                            color: Colors.white,
                          ),
                        ),
                        const SizedBox(height: 8),
                        StreamBuilder<QuerySnapshot>(
                          stream: ReferenceCollectionCache.stream('sites'),
                          builder: (context, snapshot) {
                            if (!snapshot.hasData) {
                              return const CircularProgressIndicator(
                                color: Colors.white,
                              );
                            }
                            final sites = snapshot.data!.docs;
                            return DropdownButtonFormField<String>(
                              initialValue: _selectedSiteId,
                              dropdownColor: AppTheme.primaryMid,
                              style: const TextStyle(color: Colors.white),
                              decoration: InputDecoration(
                                hintText: 'Choose a site',
                                hintStyle: TextStyle(
                                  color: Colors.white.withOpacity(0.6),
                                ),
                                prefixIcon: Icon(
                                  Icons.location_on,
                                  color: Colors.white.withOpacity(0.7),
                                ),
                                enabledBorder: OutlineInputBorder(
                                  borderRadius: BorderRadius.circular(12),
                                  borderSide: BorderSide(
                                    color: Colors.white.withOpacity(0.3),
                                  ),
                                ),
                                focusedBorder: OutlineInputBorder(
                                  borderRadius: BorderRadius.circular(12),
                                  borderSide: const BorderSide(
                                    color: AppTheme.accent,
                                  ),
                                ),
                              ),
                              items: sites.map((doc) {
                                final data = doc.data() as Map<String, dynamic>;
                                return DropdownMenuItem<String>(
                                  value: doc.id,
                                  child: Text(data['name'] ?? ''),
                                );
                              }).toList(),
                              onChanged: (val) {
                                final selected = sites.firstWhere(
                                  (d) => d.id == val,
                                );
                                final data =
                                    selected.data() as Map<String, dynamic>;
                                setState(() {
                                  _selectedSiteId = val;
                                  _selectedSiteName = data['name'];
                                });
                              },
                            );
                          },
                        ),
                        const SizedBox(height: 20),
                        const Text(
                          'Supervisor Code',
                          style: TextStyle(
                            fontWeight: FontWeight.bold,
                            color: Colors.white,
                          ),
                        ),
                        const SizedBox(height: 8),
                        TextField(
                          controller: _codeController,
                          keyboardType: TextInputType.number,
                          maxLength: 4,
                          style: const TextStyle(
                            color: Colors.white,
                            fontSize: 20,
                            letterSpacing: 6,
                          ),
                          inputFormatters: [
                            FilteringTextInputFormatter.digitsOnly,
                          ],
                          decoration: InputDecoration(
                            counterText: '',
                            hintText: '••••',
                            hintStyle: TextStyle(
                              color: Colors.white.withOpacity(0.4),
                            ),
                            prefixIcon: Icon(
                              Icons.vpn_key,
                              color: Colors.white.withOpacity(0.7),
                            ),
                            enabledBorder: OutlineInputBorder(
                              borderRadius: BorderRadius.circular(12),
                              borderSide: BorderSide(
                                color: Colors.white.withOpacity(0.3),
                              ),
                            ),
                            focusedBorder: OutlineInputBorder(
                              borderRadius: BorderRadius.circular(12),
                              borderSide: const BorderSide(
                                color: AppTheme.accent,
                              ),
                            ),
                          ),
                        ),
                        const SizedBox(height: 24),
                        _isLoading
                            ? const Center(
                                child: CircularProgressIndicator(
                                  color: Colors.white,
                                ),
                              )
                            : GradientButton(
                                label: 'SUBMIT',
                                icon: Icons.check,
                                onTap: _submit,
                              ),
                      ],
                    ),
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

// ---------------- TRUCK: WORK AREA ----------------
class TruckWorkAreaScreen extends StatefulWidget {
  final String sessionId;
  final String truckNumber;
  final String siteName;
  final String driverName;

  const TruckWorkAreaScreen({
    super.key,
    required this.sessionId,
    required this.truckNumber,
    required this.siteName,
    required this.driverName,
  });

  @override
  State<TruckWorkAreaScreen> createState() => _TruckWorkAreaScreenState();
}

class _TruckWorkAreaScreenState extends State<TruckWorkAreaScreen> {
  @override
  void initState() {
    super.initState();
    TruckLocationService.startTracking(widget.sessionId, widget.truckNumber);
  }

  CollectionReference get _tripsRef => FirebaseFirestore.instance
      .collection('truck_sessions')
      .doc(widget.sessionId)
      .collection('trips');

  Future<bool> _hasOngoingTrip() async {
    final snap = await _tripsRef
        .where('status', isEqualTo: 'ongoing')
        .limit(1)
        .get();
    return snap.docs.isNotEmpty;
  }

  Future<void> _completeTrip(String tripId) async {
    await _tripsRef.doc(tripId).update({
      'status': 'completed',
      'endedAt': FieldValue.serverTimestamp(),
    });

    // Sync this completed trip to Google Sheets
    final updatedDoc = await _tripsRef.doc(tripId).get();
    final data = updatedDoc.data() as Map<String, dynamic>;

    final startedAt = (data['startedAt'] as Timestamp?)?.toDate();
    final endedAt = (data['endedAt'] as Timestamp?)?.toDate();
    String durationText = '-';
    if (startedAt != null && endedAt != null) {
      final diff = endedAt.difference(startedAt);
      final h = diff.inHours;
      final m = diff.inMinutes % 60;
      durationText = '${h}h ${m}m';
    }

    GoogleSheetsService.sendRow(
      sheetName: 'Truck_Trips',
      row: [
        GoogleSheetsService.formatDate(DateTime.now()),
        widget.truckNumber,
        widget.driverName,
        data['startSiteName'] ?? '',
        data['endSiteName'] ?? '',
        data['billNumber'] ?? '',
        GoogleSheetsService.formatTime(data['startedAt']),
        GoogleSheetsService.formatTime(data['endedAt']),
        durationText,
        data['cubeCount'] ?? '',
      ],
    );
  }

  void _showNewTripDialog() async {
    final ongoing = await _hasOngoingTrip();
    if (ongoing) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text(
              'Complete the current trip before starting a new one.',
            ),
          ),
        );
      }
      return;
    }

    if (!mounted) return;

    showDialog(
      context: context,
      builder: (_) => NewTripDialog(
        onSubmit:
            (
              startSiteName,
              endSiteId,
              endSiteName,
              billNumber,
              cubeCount,
            ) async {
              Navigator.pop(context);
              await _tripsRef.add({
                'startSiteName': startSiteName,
                'endSiteId': endSiteId,
                'endSiteName': endSiteName,
                'billNumber': billNumber,
                'cubeCount': cubeCount,
                'status': 'ongoing',
                'startedAt': FieldValue.serverTimestamp(),
                'endedAt': null,
              });
            },
      ),
    );
  }

  void _showEndDayDialog() {
    showDialog(
      context: context,
      builder: (_) => AlertDialog(
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
        title: const Text('End Day'),
        content: const Text('Are you sure you want to end your work day?'),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: const Text('Cancel'),
          ),
          ElevatedButton(
            onPressed: () async {
              final totalKm =
                  await TruckLocationService.stopTrackingAndCalculateDistance();

              await FirebaseFirestore.instance
                  .collection('truck_sessions')
                  .doc(widget.sessionId)
                  .update({
                    'status': 'completed',
                    'completedAt': FieldValue.serverTimestamp(),
                    'totalKm': totalKm,
                  });

              // Columns: Date, Truck Number, Type, Location, Distance So Far (KM), Time
              GoogleSheetsService.sendRow(
                sheetName: 'Truck_Locations',
                row: [
                  GoogleSheetsService.formatDate(DateTime.now()),
                  widget.truckNumber,
                  'DAY SUMMARY',
                  'Total Distance',
                  '${totalKm.toStringAsFixed(2)} km',
                  GoogleSheetsService.formatTime(Timestamp.now()),
                ],
              );

              if (context.mounted) {
                Navigator.pop(context);
                Navigator.popUntil(context, (route) => route.isFirst);
              }
            },
            style: ElevatedButton.styleFrom(backgroundColor: Colors.red[700]),
            child: const Text('END DAY', style: TextStyle(color: Colors.white)),
          ),
        ],
      ),
    );
  }

  String _formatTime(Timestamp? ts) {
    if (ts == null) return '-';
    final dt = ts.toDate();
    final hour = dt.hour % 12 == 0 ? 12 : dt.hour % 12;
    final period = dt.hour >= 12 ? 'PM' : 'AM';
    final minute = dt.minute.toString().padLeft(2, '0');
    return '$hour:$minute $period';
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        leading: IconButton(
          icon: const Icon(Icons.arrow_back),
          onPressed: () {
            if (Navigator.canPop(context)) {
              Navigator.pop(context);
            } else {
              Navigator.pushReplacement(
                context,
                MaterialPageRoute(
                  builder: (_) => TruckTypeScreen(name: widget.driverName),
                ),
              );
            }
          },
        ),
        title: Text(widget.truckNumber),
        backgroundColor: Colors.deepOrange[800],
      ),
      body: Column(
        children: [
          Container(
            width: double.infinity,
            padding: const EdgeInsets.all(12),
            color: Colors.deepOrange[50],
            child: Text(
              'Truck: ${widget.truckNumber}  •  Driver: ${widget.driverName}',
              style: const TextStyle(fontSize: 13),
            ),
          ),
          Expanded(
            child: StreamBuilder<QuerySnapshot>(
              stream: _tripsRef
                  .orderBy('startedAt', descending: true)
                  .snapshots(),
              builder: (context, snapshot) {
                if (!snapshot.hasData) {
                  return const Center(child: CircularProgressIndicator());
                }
                final trips = snapshot.data!.docs;
                if (trips.isEmpty) {
                  return const Center(
                    child: Text(
                      'No trips yet.\nTap "+ NEW TASK" to begin.',
                      textAlign: TextAlign.center,
                    ),
                  );
                }

                return ListView.builder(
                  padding: const EdgeInsets.all(12),
                  itemCount: trips.length,
                  itemBuilder: (context, index) {
                    final doc = trips[index];
                    final data = doc.data() as Map<String, dynamic>;
                    final isOngoing = data['status'] == 'ongoing';

                    return Card(
                      color: isOngoing ? Colors.green[50] : Colors.white,
                      margin: const EdgeInsets.only(bottom: 10),
                      shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(12),
                        side: BorderSide(
                          color: isOngoing ? Colors.green : Colors.grey[300]!,
                          width: isOngoing ? 1.5 : 1,
                        ),
                      ),
                      child: Padding(
                        padding: const EdgeInsets.all(12),
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Row(
                              mainAxisAlignment: MainAxisAlignment.spaceBetween,
                              children: [
                                Expanded(
                                  child: Text(
                                    '${data['startSiteName']} → ${data['endSiteName']}',
                                    style: const TextStyle(
                                      fontWeight: FontWeight.bold,
                                      fontSize: 15,
                                    ),
                                  ),
                                ),
                                Container(
                                  padding: const EdgeInsets.symmetric(
                                    horizontal: 8,
                                    vertical: 4,
                                  ),
                                  decoration: BoxDecoration(
                                    color: isOngoing
                                        ? Colors.green
                                        : Colors.grey[400],
                                    borderRadius: BorderRadius.circular(20),
                                  ),
                                  child: Text(
                                    isOngoing ? 'ONGOING' : 'DONE',
                                    style: const TextStyle(
                                      color: Colors.white,
                                      fontSize: 11,
                                    ),
                                  ),
                                ),
                              ],
                            ),
                            const SizedBox(height: 8),
                            TripTimerText(
                              isOngoing: isOngoing,
                              startedAt: (data['startedAt'] as Timestamp?)
                                  ?.toDate(),
                              endedAt: (data['endedAt'] as Timestamp?)
                                  ?.toDate(),
                            ),
                            if (data['billNumber'] != null &&
                                data['billNumber'].toString().isNotEmpty) ...[
                              const SizedBox(height: 6),
                              Text(
                                'Bill Number: ${data['billNumber']}',
                                style: const TextStyle(fontSize: 13),
                              ),
                            ],
                            const SizedBox(height: 6),
                            Text(
                              'Started: ${_formatTime(data['startedAt'] as Timestamp?)}'
                              '${data['endedAt'] != null ? "  •  Ended: ${_formatTime(data['endedAt'] as Timestamp?)}" : ""}',
                              style: const TextStyle(
                                fontSize: 12,
                                color: Colors.grey,
                              ),
                            ),
                            if (isOngoing) ...[
                              const SizedBox(height: 10),
                              SizedBox(
                                width: double.infinity,
                                child: ElevatedButton.icon(
                                  onPressed: () => _completeTrip(doc.id),
                                  icon: const Icon(
                                    Icons.check,
                                    color: Colors.white,
                                  ),
                                  label: const Text(
                                    'COMPLETE TASK',
                                    style: TextStyle(color: Colors.white),
                                  ),
                                  style: ElevatedButton.styleFrom(
                                    backgroundColor: Colors.green[700],
                                  ),
                                ),
                              ),
                            ],
                          ],
                        ),
                      ),
                    );
                  },
                );
              },
            ),
          ),
        ],
      ),
      floatingActionButton: FloatingActionButton.extended(
        onPressed: _showNewTripDialog,
        backgroundColor: Colors.deepOrange[800],
        icon: const Icon(Icons.add, color: Colors.white),
        label: const Text('NEW TASK', style: TextStyle(color: Colors.white)),
      ),
      bottomNavigationBar: SafeArea(
        child: Padding(
          padding: const EdgeInsets.all(12.0),
          child: SizedBox(
            width: double.infinity,
            height: 48,
            child: ElevatedButton.icon(
              onPressed: _showEndDayDialog,
              icon: const Icon(Icons.flag, color: Colors.white),
              label: const Text(
                'END DAY',
                style: TextStyle(
                  color: Colors.white,
                  fontWeight: FontWeight.bold,
                ),
              ),
              style: ElevatedButton.styleFrom(backgroundColor: Colors.red[700]),
            ),
          ),
        ),
      ),
    );
  }
}

// ---------------- NEW TRIP DIALOG (Truck) ----------------
class NewTripDialog extends StatefulWidget {
  final Function(
    String? startSiteName,
    String? endSiteId,
    String? endSiteName,
    String? billNumber,
    String? cubeCount,
  )
  onSubmit;

  const NewTripDialog({super.key, required this.onSubmit});

  @override
  State<NewTripDialog> createState() => _NewTripDialogState();
}

class _NewTripDialogState extends State<NewTripDialog> {
  String? _selectedStartSiteId;
  String? _selectedStartSiteName;
  String? _selectedEndSiteId;
  String? _selectedEndSiteName;
  final _billNumberController = TextEditingController();
  final _cubeController = TextEditingController();
  String _errorText = '';

  void _handleSubmit() {
    if (_selectedStartSiteId == null) {
      setState(() => _errorText = 'Please select the start site.');
      return;
    }
    if (_selectedEndSiteId == null) {
      setState(() => _errorText = 'Please select the end site.');
      return;
    }
    widget.onSubmit(
      _selectedStartSiteName,
      _selectedEndSiteId,
      _selectedEndSiteName,
      _billNumberController.text.trim().isEmpty
          ? null
          : _billNumberController.text.trim(),
      _cubeController.text.trim().isEmpty ? null : _cubeController.text.trim(),
    );
  }

  @override
  Widget build(BuildContext context) {
    return AlertDialog(
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      title: const Text('Start New Task'),
      content: SingleChildScrollView(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Text(
              'Start Site',
              style: TextStyle(fontWeight: FontWeight.bold),
            ),
            const SizedBox(height: 8),
            StreamBuilder<QuerySnapshot>(
              stream: ReferenceCollectionCache.stream('sites'),
              builder: (context, snapshot) {
                if (!snapshot.hasData) return const CircularProgressIndicator();
                final sites = snapshot.data!.docs;
                return DropdownButtonFormField<String>(
                  initialValue: _selectedStartSiteId,
                  decoration: InputDecoration(
                    hintText: 'Choose start site',
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(10),
                    ),
                  ),
                  items: sites.map((doc) {
                    final data = doc.data() as Map<String, dynamic>;
                    return DropdownMenuItem<String>(
                      value: doc.id,
                      child: Text(data['name'] ?? ''),
                    );
                  }).toList(),
                  onChanged: (val) {
                    final selected = sites.firstWhere((d) => d.id == val);
                    final data = selected.data() as Map<String, dynamic>;
                    setState(() {
                      _selectedStartSiteId = val;
                      _selectedStartSiteName = data['name'];
                    });
                  },
                );
              },
            ),
            const SizedBox(height: 16),
            const Text(
              'End Site',
              style: TextStyle(fontWeight: FontWeight.bold),
            ),
            const SizedBox(height: 8),
            StreamBuilder<QuerySnapshot>(
              stream: ReferenceCollectionCache.stream('sites'),
              builder: (context, snapshot) {
                if (!snapshot.hasData) return const CircularProgressIndicator();
                final sites = snapshot.data!.docs;
                return DropdownButtonFormField<String>(
                  initialValue: _selectedEndSiteId,
                  decoration: InputDecoration(
                    hintText: 'Choose end site',
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(10),
                    ),
                  ),
                  items: sites.map((doc) {
                    final data = doc.data() as Map<String, dynamic>;
                    return DropdownMenuItem<String>(
                      value: doc.id,
                      child: Text(data['name'] ?? ''),
                    );
                  }).toList(),
                  onChanged: (val) {
                    final selected = sites.firstWhere((d) => d.id == val);
                    final data = selected.data() as Map<String, dynamic>;
                    setState(() {
                      _selectedEndSiteId = val;
                      _selectedEndSiteName = data['name'];
                    });
                  },
                );
              },
            ),
            const SizedBox(height: 16),
            TextField(
              controller: _billNumberController,
              keyboardType: TextInputType.number,
              inputFormatters: [FilteringTextInputFormatter.digitsOnly],
              decoration: InputDecoration(
                labelText: 'Bill Number (optional)',
                border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(10),
                ),
              ),
            ),
            const SizedBox(height: 16),
            TextField(
              controller: _cubeController,
              keyboardType: TextInputType.number,
              decoration: InputDecoration(
                labelText: 'Cube (Quantity)',
                border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(10),
                ),
              ),
            ),
            if (_errorText.isNotEmpty) ...[
              const SizedBox(height: 12),
              Text(
                _errorText,
                style: const TextStyle(color: Colors.red, fontSize: 13),
              ),
            ],
          ],
        ),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.pop(context),
          child: const Text('Cancel'),
        ),
        ElevatedButton(
          onPressed: _handleSubmit,
          style: ElevatedButton.styleFrom(
            backgroundColor: Colors.deepOrange[800],
          ),
          child: const Text('START', style: TextStyle(color: Colors.white)),
        ),
      ],
    );
  }
}

// ---------------- VEHICLE REGISTRATION SCREEN (Admin, 2 tabs) ----------------
// Tab 1 reuses TruckManagementScreen as-is (Truck Registration, including
// the Cube Capacity field) — deliberately the same widget, not a
// body-only extract, so it stays a single source of truth for the truck
// form. Tab 2 (QR Generate) picks a registered truck, shows its assigned
// driver + cube capacity read-only, and renders a QR code encoding
// {"truckNumber", "driverName", "cube"} for Supervisor's QR Scan
// (WorkSessionScreen) to scan and submit a load in one step.
class VehicleRegistrationScreen extends StatefulWidget {
  const VehicleRegistrationScreen({super.key});

  @override
  State<VehicleRegistrationScreen> createState() =>
      _VehicleRegistrationScreenState();
}

class _VehicleRegistrationScreenState extends State<VehicleRegistrationScreen>
    with SingleTickerProviderStateMixin {
  late final TabController _tabController;

  @override
  void initState() {
    super.initState();
    _tabController = TabController(length: 2, vsync: this);
  }

  @override
  void dispose() {
    _tabController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Vehicle Registration'),
        backgroundColor: Colors.deepOrange[800],
        bottom: TabBar(
          controller: _tabController,
          indicatorColor: Colors.white,
          labelColor: Colors.white,
          unselectedLabelColor: Colors.white70,
          tabs: const [
            Tab(text: 'Truck Registration'),
            Tab(text: 'QR Generate'),
          ],
        ),
      ),
      body: TabBarView(
        controller: _tabController,
        children: const [_VehicleRegistrationTab(), _QrGenerateTab()],
      ),
    );
  }
}

// Tab 1's Truck/Bike switch. Trucks and bikes are separate collections with
// separate forms (see the Isolated Design note on kBikesCollection), so this
// just picks which of the two existing screens to show — neither form knows
// about the other. The QR Generate tab (Tab 2) stays truck-only: bikes have
// no QR workflow.
class _VehicleRegistrationTab extends StatefulWidget {
  const _VehicleRegistrationTab();

  @override
  State<_VehicleRegistrationTab> createState() => _VehicleRegistrationTabState();
}

class _VehicleRegistrationTabState extends State<_VehicleRegistrationTab> {
  bool _isBike = false;

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        Padding(
          padding: const EdgeInsets.fromLTRB(16, 12, 16, 0),
          child: SizedBox(
            width: double.infinity,
            child: SegmentedButton<bool>(
              segments: const [
                ButtonSegment<bool>(
                  value: false,
                  label: Text('Truck'),
                  icon: Icon(Icons.local_shipping),
                ),
                ButtonSegment<bool>(
                  value: true,
                  label: Text('Bike'),
                  icon: Icon(Icons.two_wheeler),
                ),
