// Shared implementation behind all three screens above — collection/title
// are two of the things that differ between them. pairMode: Unloading
// Amount/Driver Unloading Rate are keyed by a Loading+Unloading site PAIR
// (doc id "{loadingSiteId}_{unloadingSiteId}"), while Loading Amount is
// keyed by Loading Site ALONE (doc id is just loadingSiteId — no
// unloadingSiteId/unloadingSiteName fields at all). See
// _showAddEditDialog/the save handler/the list builder below for where
// this forks. amountLabel only changes the dialog's amount field label
// (default 'Amount', unchanged for Loading/Unloading Amount) — never the
// saved field name, which stays 'amount' for all three.
class _AmountManagementScreen extends StatefulWidget {
  final String collection;
  final String title;
  final bool pairMode;
  final String amountLabel;

  const _AmountManagementScreen({
    required this.collection,
    required this.title,
    required this.pairMode,
    this.amountLabel = 'Amount',
  });

  @override
  State<_AmountManagementScreen> createState() =>
      _AmountManagementScreenState();
}

class _AmountManagementScreenState extends State<_AmountManagementScreen> {
  // late final — same reasoning as ManagementSiteReportsScreen's
  // _sitesStream/_workRecordsStream: the search box and Loading Site filter
  // below only ever call setState, never touch these fields, so neither
  // stream is ever rebuilt/resubscribed by a filter keystroke (which is
  // what caused the flicker that pattern was built to avoid).
  late final Stream<QuerySnapshot> _sitesStream = ReferenceCollectionCache.stream('sites');
  late final Stream<QuerySnapshot> _amountsStream = FirebaseFirestore.instance
      .collection(widget.collection)
      .snapshots();

  final _searchController = TextEditingController();
  String _searchText = '';
  String? _selectedLoadingSiteFilter;
  int _pageSize = 25;
  int _page = 0;
  String _filterSig = '';

  @override
  void dispose() {
    _searchController.dispose();
    super.dispose();
  }

  // Sites fetched once (not streamed) right before the dialog opens — same
  // reason as RouteDistanceManagementScreen._showAddEditDialog: avoids a
  // DropdownButtonFormField assertion crash on Edit, where initialValue is
  // already non-null before a live sites stream's first snapshot has
  // necessarily arrived.
  Future<void> _showAddEditDialog({DocumentSnapshot? existing}) async {
    final data = existing?.data() as Map<String, dynamic>?;
    final isEditing = existing != null;
    String? loadingSiteId = data?['loadingSiteId'] as String?;
    String? unloadingSiteId = data?['unloadingSiteId'] as String?;
    final amountController = TextEditingController(
      text: data == null ? '' : (data['amount']?.toString() ?? ''),
    );
    String? errorText;

    final sitesSnap = await FirebaseFirestore.instance
        .collection('sites')
        .get();
    if (!mounted) return;
    final siteNameById = <String, String>{
      for (final doc in sitesSnap.docs)
        doc.id: (doc.data()['name'] ?? '').toString(),
    };
    final loadingSites = sitesSnap.docs.where((doc) {
      final d = doc.data();
      return d['canBeLoadingSite'] != false || doc.id == loadingSiteId;
    }).toList();
    final unloadingSites = sitesSnap.docs.where((doc) {
      final d = doc.data();
      return d['canBeUnloadingSite'] != false || doc.id == unloadingSiteId;
    }).toList();

    showDialog(
      context: context,
      builder: (dialogContext) => StatefulBuilder(
        builder: (dialogContext, setDialogState) => AlertDialog(
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(16),
          ),
          title: Text(
            isEditing ? 'Edit ${widget.title}' : 'Add ${widget.title}',
          ),
          content: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                const Text(
                  'Loading Site',
                  style: TextStyle(fontWeight: FontWeight.bold),
                ),
                const SizedBox(height: 6),
                // Locked once editing (doc id is "{loadingSiteId}_
                // {unloadingSiteId}" — changing either site here would mean
                // editing a different doc entirely, not updating this one).
                if (isEditing)
                  IgnorePointer(
                    child: InputDecorator(
                      decoration: InputDecoration(
                        border: OutlineInputBorder(
                          borderRadius: BorderRadius.circular(10),
                        ),
                        filled: true,
                        fillColor: Colors.grey[200],
                      ),
                      child: Text(siteNameById[loadingSiteId] ?? ''),
                    ),
                  )
                else
                  DropdownButtonFormField<String>(
                    initialValue: loadingSiteId,
                    decoration: InputDecoration(
                      border: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(10),
                      ),
                    ),
                    items: loadingSites.map((doc) {
                      final d = doc.data();
                      return DropdownMenuItem(
                        value: doc.id,
                        child: Text((d['name'] ?? '').toString()),
                      );
                    }).toList(),
                    onChanged: (val) =>
                        setDialogState(() => loadingSiteId = val),
                  ),
                if (widget.pairMode) ...[
                  const SizedBox(height: 16),
                  const Text(
                    'Unloading Site',
                    style: TextStyle(fontWeight: FontWeight.bold),
                  ),
                  const SizedBox(height: 6),
                  if (isEditing)
                    IgnorePointer(
                      child: InputDecorator(
                        decoration: InputDecoration(
                          border: OutlineInputBorder(
                            borderRadius: BorderRadius.circular(10),
                          ),
                          filled: true,
                          fillColor: Colors.grey[200],
                        ),
                        child: Text(siteNameById[unloadingSiteId] ?? ''),
                      ),
                    )
                  else
                    DropdownButtonFormField<String>(
                      initialValue: unloadingSiteId,
                      decoration: InputDecoration(
                        border: OutlineInputBorder(
                          borderRadius: BorderRadius.circular(10),
                        ),
                      ),
                      items: unloadingSites.map((doc) {
                        final d = doc.data();
                        return DropdownMenuItem(
                          value: doc.id,
                          child: Text((d['name'] ?? '').toString()),
                        );
                      }).toList(),
                      onChanged: (val) =>
                          setDialogState(() => unloadingSiteId = val),
                    ),
                ],
                const SizedBox(height: 16),
                TextField(
                  controller: amountController,
                  keyboardType: const TextInputType.numberWithOptions(
                    decimal: true,
                  ),
                  decoration: InputDecoration(
                    labelText: '${widget.amountLabel} (Rs.)',
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(10),
                    ),
                  ),
                ),
                if (errorText != null) ...[
                  const SizedBox(height: 8),
                  Text(
                    errorText!,
                    style: TextStyle(color: Colors.red[700], fontSize: 12),
                  ),
                ],
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dialogContext),
              child: const Text('Cancel'),
            ),
            ElevatedButton(
              onPressed: () async {
                if (loadingSiteId == null ||
                    (widget.pairMode && unloadingSiteId == null)) {
                  setDialogState(
                    () => errorText = widget.pairMode
                        ? 'Please select both sites first.'
                        : 'Please select a Loading Site first.',
                  );
                  return;
                }
                final amount = double.tryParse(amountController.text.trim());
                if (amount == null || amount <= 0) {
                  setDialogState(
                    () => errorText = 'Please enter a valid amount.',
                  );
                  return;
                }
                try {
                  final docId = widget.pairMode
                      ? '${loadingSiteId}_$unloadingSiteId'
                      : loadingSiteId!;
                  final ref = FirebaseFirestore.instance
                      .collection(widget.collection)
                      .doc(docId);
                  final existingDoc = await ref.get();
                  await ref.set({
                    'loadingSiteId': loadingSiteId,
                    'loadingSiteName': siteNameById[loadingSiteId] ?? '',
                    'amount': amount,
                    'updatedAt': FieldValue.serverTimestamp(),
                    if (!existingDoc.exists)
                      'createdAt': FieldValue.serverTimestamp(),
                    if (widget.pairMode) 'unloadingSiteId': unloadingSiteId,
                    if (widget.pairMode)
                      'unloadingSiteName': siteNameById[unloadingSiteId] ?? '',
                  }, SetOptions(merge: true));
                  if (dialogContext.mounted) Navigator.pop(dialogContext);
                } catch (e) {
                  setDialogState(() => errorText = 'Failed to save: $e');
                }
              },
              child: const Text('SAVE'),
            ),
          ],
        ),
      ),
    );
  }

  Future<void> _delete(String docId) async {
    await FirebaseFirestore.instance
        .collection(widget.collection)
        .doc(docId)
        .delete();
  }

  // Thousand separators + fixed 2 decimals, e.g. 12,345.00.
  String _formatAmount(num amount) {
    final fixed = amount.toStringAsFixed(2);
    final parts = fixed.split('.');
    final isNegative = parts[0].startsWith('-');
    final digits = isNegative ? parts[0].substring(1) : parts[0];
    final buffer = StringBuffer();
    for (var i = 0; i < digits.length; i++) {
      if (i != 0 && (digits.length - i) % 3 == 0) buffer.write(',');
      buffer.write(digits[i]);
    }
    return '${isNegative ? '-' : ''}$buffer.${parts[1]}';
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text(widget.title),
        backgroundColor: Colors.teal[800],
      ),
      floatingActionButton: FloatingActionButton(
        onPressed: () => _showAddEditDialog(),
        tooltip: 'Add ${widget.title}',
        child: const Icon(Icons.add),
      ),
      body: StreamBuilder<QuerySnapshot>(
        stream: _sitesStream,
        builder: (context, sitesSnapshot) {
          final siteDocs = sitesSnapshot.data?.docs ?? const [];
          final siteNameById = <String, String>{
            for (final doc in siteDocs)
              doc.id: ((doc.data() as Map<String, dynamic>)['name'] ?? '')
                  .toString(),
          };
          final loadingSiteOptions = siteDocs.where((doc) {
            final d = doc.data() as Map<String, dynamic>;
            return d['canBeLoadingSite'] != false;
          }).toList();

          return Column(
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(12, 12, 12, 0),
                child: Row(
                  children: [
                    Expanded(
                      child: TextField(
                        controller: _searchController,
                        inputFormatters: [UpperCaseTextFormatter()],
                        textCapitalization: TextCapitalization.characters,
                        decoration: InputDecoration(
                          hintText: 'Search loading or unloading site',
                          prefixIcon: const Icon(Icons.search),
                          isDense: true,
                          border: OutlineInputBorder(
                            borderRadius: BorderRadius.circular(10),
                          ),
                        ),
                        onChanged: (val) =>
                            setState(() => _searchText = val),
                      ),
                    ),
                    const SizedBox(width: 12),
                    SizedBox(
                      width: 220,
                      child: DropdownButtonFormField<String>(
                        initialValue: _selectedLoadingSiteFilter,
                        isExpanded: true,
                        decoration: InputDecoration(
                          labelText: 'Loading Site',
                          isDense: true,
                          border: OutlineInputBorder(
                            borderRadius: BorderRadius.circular(10),
                          ),
                        ),
                        items: [
                          const DropdownMenuItem<String>(
                            value: null,
                            child: Text('All Loading Sites'),
                          ),
                          ...loadingSiteOptions.map((doc) {
                            final d = doc.data() as Map<String, dynamic>;
                            return DropdownMenuItem<String>(
                              value: doc.id,
                              child: Text((d['name'] ?? '').toString()),
                            );
                          }),
                        ],
                        onChanged: (val) => setState(
                          () => _selectedLoadingSiteFilter = val,
                        ),
                      ),
                    ),
                  ],
                ),
              ),
              Expanded(
                child: StreamBuilder<QuerySnapshot>(
                  stream: _amountsStream,
                  builder: (context, snapshot) {
                    if (snapshot.connectionState == ConnectionState.waiting) {
                      return const Center(child: CircularProgressIndicator());
                    }
                    // Loading Amount only: ignores any doc that still carries
                    // a real unloadingSiteId (older pair-style test docs
                    // saved under this collection before this screen became
                    // per-Loading-Site) — they're a different shape and must
                    // never crash or show up here.
                    final allDocs = widget.pairMode
                        ? (snapshot.data?.docs ?? [])
                        : (snapshot.data?.docs ?? []).where((doc) {
                            final uid = (doc.data()
                                as Map<String, dynamic>)['unloadingSiteId'];
                            return uid == null || uid.toString().isEmpty;
                          }).toList();
                    final trimmedSearch = _searchText.trim().toLowerCase();
                    final filtered = allDocs.where((doc) {
                      final data = doc.data() as Map<String, dynamic>;
                      if (_selectedLoadingSiteFilter != null &&
                          data['loadingSiteId'] != _selectedLoadingSiteFilter) {
                        return false;
                      }
                      if (trimmedSearch.isEmpty) return true;
                      final loadingName =
                          (siteNameById[data['loadingSiteId']] ??
                                  data['loadingSiteName'] ??
                                  '')
                              .toString()
                              .toLowerCase();
                      final unloadingName =
                          (siteNameById[data['unloadingSiteId']] ??
                                  data['unloadingSiteName'] ??
                                  '')
                              .toString()
                              .toLowerCase();
                      return loadingName.contains(trimmedSearch) ||
                          unloadingName.contains(trimmedSearch);
                    }).toList();

                    if (filtered.isEmpty) {
                      return Center(
                        child: Text(
                          allDocs.isEmpty
                              ? 'No ${widget.title.toLowerCase()} entries '
                                    'configured yet.'
                              : 'No matching entries.',
                        ),
                      );
                    }

                    final sig =
                        '$_searchText|$_selectedLoadingSiteFilter|$_pageSize';
                    if (sig != _filterSig) {
                      _filterSig = sig;
                      _page = 0;
                    }
                    final totalPages =
                        (filtered.length + _pageSize - 1) ~/ _pageSize;
                    if (_page >= totalPages) _page = totalPages - 1;
                    if (_page < 0) _page = 0;
                    final pageStart = _page * _pageSize;
                    final pageEnd = (pageStart + _pageSize) > filtered.length
                        ? filtered.length
                        : pageStart + _pageSize;
                    final pageDocs = filtered.sublist(pageStart, pageEnd);

                    return Column(
                      children: [
                        Expanded(
                          child: ListView.builder(
                            padding: const EdgeInsets.all(12),
                            itemCount: pageDocs.length,
                            itemBuilder: (context, index) {
                              final doc = pageDocs[index];
                              final data = doc.data() as Map<String, dynamic>;
                              final loadingName =
                                  siteNameById[data['loadingSiteId']] ??
                                  (data['loadingSiteName'] ?? 'Unknown Site')
                                      .toString();
                              final unloadingName =
                                  siteNameById[data['unloadingSiteId']] ??
                                  (data['unloadingSiteName'] ?? 'Unknown Site')
                                      .toString();
                              final amount = (data['amount'] as num?) ?? 0;
                              return _WebStaggeredFadeIn(
                                index: index,
                                child: _WebHoverCard(
                                  child: Card(
                                    margin: const EdgeInsets.only(bottom: 10),
                                    child: ListTile(
                                      leading: CircleAvatar(
                                        backgroundColor: Colors.teal
                                            .withOpacity(0.15),
                                        child: const Icon(
                                          Icons.payments,
                                          color: Colors.teal,
                                        ),
                                      ),
                                      title: Text(
                                        widget.pairMode
                                            ? '$loadingName → $unloadingName'
                                            : loadingName,
                                      ),
                                      subtitle: Text(
                                        'Rs. ${_formatAmount(amount)}',
                                      ),
                                      trailing: Row(
                                        mainAxisSize: MainAxisSize.min,
                                        children: [
                                          IconButton(
                                            icon: const Icon(
                                              Icons.edit,
                                              color: Colors.blue,
                                            ),
                                            tooltip: 'Edit',
                                            onPressed: () =>
                                                _showAddEditDialog(
                                                  existing: doc,
                                                ),
                                          ),
                                          IconButton(
                                            icon: const Icon(
                                              Icons.delete,
                                              color: Colors.red,
                                            ),
                                            tooltip: 'Delete',
                                            onPressed: () => confirmDelete(
                                              context: context,
                                              title: 'Delete ${widget.title}?',
                                              message:
                                                  'Are you sure you want to '
                                                  'delete this '
                                                  '${widget.title.toLowerCase()} '
                                                  'entry? This cannot be '
                                                  'undone.',
                                              onConfirm: () =>
                                                  _delete(doc.id),
                                            ),
                                          ),
                                        ],
                                      ),
                                    ),
                                  ),
                                ),
                              );
                            },
                          ),
                        ),
                        Padding(
                          padding: const EdgeInsets.symmetric(
                            horizontal: 12,
                            vertical: 8,
                          ),
                          child: Row(
                            mainAxisAlignment: MainAxisAlignment.end,
                            children: [
                              const Text('Rows per page: '),
                              DropdownButton<int>(
                                value: _pageSize,
                                items: [25, 50, 100]
                                    .map(
                                      (n) => DropdownMenuItem<int>(
                                        value: n,
                                        child: Text('$n'),
                                      ),
                                    )
                                    .toList(),
                                onChanged: (v) {
                                  if (v != null) {
                                    setState(() => _pageSize = v);
                                  }
                                },
                              ),
                              const SizedBox(width: 16),
                              Text('${pageStart + 1}-$pageEnd of ${filtered.length}'),
                              IconButton(
                                icon: const Icon(Icons.chevron_left),
                                onPressed: _page > 0
                                    ? () => setState(() => _page--)
                                    : null,
                              ),
                              IconButton(
                                icon: const Icon(Icons.chevron_right),
                                onPressed: _page < totalPages - 1
                                    ? () => setState(() => _page++)
                                    : null,
                              ),
                            ],
                          ),
                        ),
                      ],
                    );
                  },
                ),
              ),
            ],
          );
        },
      ),
    );
  }
}

// Looks up the admin-configured fixed distance for a Company Load's
// Loading Site -> Unloading Site pair (see RouteDistanceManagementScreen
// above). Returns null when no such route has been configured yet, in
// which case the caller must block submission entirely — see
// showRouteDistanceNotConfiguredDialog below. Shared by both the QR Scan
// flow (_WorkSessionScreenState) and the manual New Work flow
// (NewWorkDialog) via same-library access, same as every other
// cross-class helper reuse in this codebase.
Future<double?> _lookupRouteDistanceKm(
  String loadingSiteId,
  String unloadingSiteId,
) async {
  final doc = await FirebaseFirestore.instance
      .collection('route_distances')
      .doc('${loadingSiteId}_$unloadingSiteId')
      .get();
  if (!doc.exists) return null;
  return (doc.data()?['distanceKm'] as num?)?.toDouble();
}

// Shared error dialog for a Company Load whose Loading Site -> Unloading
// Site pair has no admin-configured distance yet — used by both the QR
// Scan flow and the manual New Work flow, both of which cancel the whole
// submission (no record created) once this is dismissed.
Future<void> showRouteDistanceNotConfiguredDialog(BuildContext context) {
  return showDialog(
    context: context,
    builder: (dialogContext) => AlertDialog(
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      title: const Text('Distance Not Configured'),
      content: const Text(
        'Distance not configured for this route (Loading Site → '
        'Unloading Site). Please ask Admin/Management to set it in '
        'Route Distances.',
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.pop(dialogContext),
          child: const Text('OK'),
        ),
      ],
    ),
  );
}

// ---------------- UNLOADING FEED (unloading_feed/{siteId}/loads/{loadId}) ----------------
// Safe mirror collection UnloadingSiteViewerScreen reads from instead of
// work_records/manual_site_reports directly (see that screen's own doc
// comment) — Firestore rules scope each unloading_site user to exactly
// their own unloadingSiteIds via this path, so the viewer never needs read
// access to the real records at all.
//
// Every place that creates/edits/deletes a load (work_records doc or
// manual_site_reports doc) stages a matching write/delete on this
// collection in the SAME WriteBatch as the real write, via
// _reconcileUnloadingFeedEntry/_stageUnloadingFeedDelete below — see each
// call site for the file:line list in the task summary.

// Cached sites name(lowercase, trimmed) -> id index. Every current
// unloading-site picker (_showUnloadingSiteFieldPicker and the QR flow's
// own site picker) resolves a real site id at pick time but the caller
// discards it, keeping only the typed/picked name — so this name index is
// the only way most call sites can recover an id at all. Short TTL (not
// one-shot) so a site rename mid-session is picked up without an app
// restart, without re-querying on every single save.
Map<String, String>? _unloadingSitesNameIndexCache;
DateTime? _unloadingSitesNameIndexCachedAt;

Future<Map<String, String>> _unloadingSitesNameIndex() async {
  final now = DateTime.now();
  if (_unloadingSitesNameIndexCache != null &&
      _unloadingSitesNameIndexCachedAt != null &&
      now.difference(_unloadingSitesNameIndexCachedAt!) <
          const Duration(minutes: 5)) {
    return _unloadingSitesNameIndexCache!;
  }
  final snap = await FirebaseFirestore.instance.collection('sites').get();
  final index = <String, String>{};
  for (final doc in snap.docs) {
    final name = (doc.data()['name'] ?? '').toString().trim().toLowerCase();
    if (name.isNotEmpty) index[name] = doc.id;
  }
  _unloadingSitesNameIndexCache = index;
  _unloadingSitesNameIndexCachedAt = now;
  return index;
}

// Prefers an already-known id (when a caller kept the picker's own id)
// over a name lookup, which is the only path every existing call site has
// today.
Future<String?> _resolveUnloadingSiteId(
  String? pickedId,
  String? unloadingSiteName,
) async {
  if (pickedId != null && pickedId.isNotEmpty) return pickedId;
  final name = (unloadingSiteName ?? '').trim();
  if (name.isEmpty) return null;
  final index = await _unloadingSitesNameIndex();
  return index[name.toLowerCase()];
}

void _stageUnloadingFeedDelete({
  required WriteBatch batch,
  required String siteId,
  required String recordId,
}) {
  final ref = FirebaseFirestore.instance
      .collection('unloading_feed')
      .doc(siteId)
      .collection('loads')
      .doc(recordId);
  batch.delete(ref);
}

// The one function every load save/edit/complete path below calls. Stages
// (on the given batch, never commits it) whatever the feed needs given the
// record's OLD resolved site (null for a brand-new record) and its
// CURRENT unloadingSiteName — deletes the old mirror doc first if the
// record moved to a different site (or lost its site), then (merge-)sets
// the new one if it still has one. Returns the resolved siteId so the
// caller can also forward-fix unloadingSiteId onto the real record doc in
// the same batch; returns null when there's no site, or the name can't be
// resolved at all (logged via debugPrint — the real record's save is never
// blocked by this).
Future<String?> _reconcileUnloadingFeedEntry({
  required WriteBatch batch,
  required String recordId,
  required String? oldSiteId,
  String? pickedSiteId,
  required String? unloadingSiteName,
  String? billNumber,
  String? lorryNumber,
  required String? date,
  required dynamic time,
  required String sourceType,
}) async {
  final name = (unloadingSiteName ?? '').trim();
  String? newSiteId;
  if (name.isNotEmpty) {
    newSiteId = await _resolveUnloadingSiteId(pickedSiteId, name);
  }
  if (oldSiteId != null && oldSiteId != newSiteId) {
    _stageUnloadingFeedDelete(
      batch: batch,
      siteId: oldSiteId,
      recordId: recordId,
    );
  }
  if (name.isEmpty) return null;
  if (newSiteId == null) {
    debugPrint(
      '[unloading_feed] Could not resolve unloadingSiteId for site name '
      '"$name" (record $recordId, source $sourceType) — feed mirror not '
      'written for this save. Use the admin "Rebuild Unloading Feed" tool '
      'once the site is registered to backfill it.',
    );
    return null;
  }
  final ref = FirebaseFirestore.instance
      .collection('unloading_feed')
      .doc(newSiteId)
      .collection('loads')
      .doc(recordId);
  batch.set(ref, {
    'billNumber': billNumber ?? '',
    'lorryNumber': lorryNumber ?? '',
    'date': date ?? '',
    'time': time,
    'unloadingSiteId': newSiteId,
    'unloadingSiteName': name,
    'sourceType': sourceType,
    'updatedAt': FieldValue.serverTimestamp(),
  }, SetOptions(merge: true));
  return newSiteId;
}

// ---------------- REBUILD UNLOADING FEED (Admin tool) ----------------
// Backfills/repairs unloading_feed from the real work_records/
// manual_site_reports data for a date range — for records saved before
// this feature existed (no dual-write yet), or anything the dual-write
// paths above couldn't resolve a site for at save time (see
// _reconcileUnloadingFeedEntry's debugPrint). Also optionally removes
// orphan feed docs (source record since deleted) in the same range.
// Read-only on the real collections — never creates/edits/deletes a real
// work_record or manual_site_report, only ever writes unloading_feed and
// (when it resolves a previously-missing id) backfills unloadingSiteId
// onto the source doc.
class RebuildUnloadingFeedScreen extends StatefulWidget {
  const RebuildUnloadingFeedScreen({super.key});

  @override
  State<RebuildUnloadingFeedScreen> createState() =>
      _RebuildUnloadingFeedScreenState();
}

class _RebuildUnloadingFeedScreenState
    extends State<RebuildUnloadingFeedScreen> {
  DateTimeRange? _dateRange;
  bool _removeOrphans = false;
  bool _running = false;
  String _status = '';
  int _processed = 0;
  int _written = 0;
  int _skipped = 0;
  int _deleted = 0;

  String _ymd(DateTime d) =>
      '${d.year.toString().padLeft(4, '0')}-'
      '${d.month.toString().padLeft(2, '0')}-'
      '${d.day.toString().padLeft(2, '0')}';

  Future<void> _pickDateRange() async {
    final picked = await showDateRangePicker(
      context: context,
      firstDate: DateTime(2020),
      lastDate: DateTime.now().add(const Duration(days: 1)),
      initialDateRange: _dateRange,
    );
    if (picked != null) setState(() => _dateRange = picked);
  }

  Future<bool> _confirmOrphanRemoval() async {
    final result = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Remove Orphan Feed Entries?'),
        content: const Text(
          'This permanently deletes any unloading_feed entry in the '
          'selected date range whose source record no longer exists. '
          'This cannot be undone. Continue?',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('Cancel'),
          ),
          ElevatedButton(
            onPressed: () => Navigator.pop(dialogContext, true),
            style: ElevatedButton.styleFrom(backgroundColor: Colors.red[700]),
            child: const Text(
              'REMOVE ORPHANS',
              style: TextStyle(color: Colors.white),
            ),
          ),
        ],
      ),
    );
    return result ?? false;
  }

  Future<void> _runRebuild() async {
    if (_running) return;
    if (_removeOrphans) {
      final confirmed = await _confirmOrphanRemoval();
      if (!confirmed) return;
    }

    final range =
        _dateRange ??
        DateTimeRange(
          start: DateTime.now().subtract(const Duration(days: 30)),
          end: DateTime.now(),
        );
    final start = _ymd(range.start);
    final end = _ymd(range.end);

    setState(() {
      _running = true;
      _status = 'Loading records...';
      _processed = 0;
      _written = 0;
      _skipped = 0;
      _deleted = 0;
    });

    try {
      final workSnap = await FirebaseFirestore.instance
          .collectionGroup('work_records')
          .where('isLoadingCategory', isEqualTo: true)
          .where('date', isGreaterThanOrEqualTo: start)
          .where('date', isLessThanOrEqualTo: end)
          .get();
      final manualSnap = await FirebaseFirestore.instance
          .collection('manual_site_reports')
          .where('date', isGreaterThanOrEqualTo: start)
          .where('date', isLessThanOrEqualTo: end)
          .get();

      final validRecordIds = <String>{};
      var batch = FirebaseFirestore.instance.batch();
      var opsInBatch = 0;

      Future<void> flushIfNeeded() async {
        if (opsInBatch >= 400) {
          await batch.commit();
          batch = FirebaseFirestore.instance.batch();
          opsInBatch = 0;
        }
      }

      final allDocs = [...workSnap.docs, ...manualSnap.docs];
      for (final doc in allDocs) {
        final data = doc.data();
        validRecordIds.add(doc.id);
        _processed++;
        final name = (data['unloadingSiteName'] ?? '').toString().trim();
        if (name.isEmpty) {
          _skipped++;
        } else {
          final isManual = data['isManualEntry'] == true;
          final time =
              data['loadCompletedAt'] ??
              data['loadStartedAt'] ??
              data['createdAt'];
          final existingId = data['unloadingSiteId'] as String?;
          final resolvedId = await _reconcileUnloadingFeedEntry(
            batch: batch,
            recordId: doc.id,
            oldSiteId: existingId,
            unloadingSiteName: name,
            billNumber: (data['billNumber'] ?? '').toString(),
            lorryNumber: (data['truckNumber'] ?? '').toString(),
            date: (data['date'] ?? '').toString(),
            time: time,
            sourceType: isManual ? 'manual_report' : 'work_record',
          );
          if (resolvedId == null) {
            _skipped++;
          } else {
            _written++;
            opsInBatch++;
            if (existingId != resolvedId) {
              batch.update(doc.reference, {'unloadingSiteId': resolvedId});
              opsInBatch++;
            }
          }
        }
        await flushIfNeeded();
        if (_processed % 25 == 0 && mounted) {
          setState(() => _status = 'Processed $_processed of ${allDocs.length}...');
        }
      }
      if (opsInBatch > 0) {
        await batch.commit();
        batch = FirebaseFirestore.instance.batch();
        opsInBatch = 0;
      }

      if (_removeOrphans) {
        if (mounted) {
          setState(() => _status = 'Checking for orphan feed entries...');
        }
        final sitesSnap = await FirebaseFirestore.instance
            .collection('sites')
            .get();
        for (final siteDoc in sitesSnap.docs) {
          final feedSnap = await FirebaseFirestore.instance
              .collection('unloading_feed')
              .doc(siteDoc.id)
              .collection('loads')
              .where('date', isGreaterThanOrEqualTo: start)
              .where('date', isLessThanOrEqualTo: end)
              .get();
          for (final feedDoc in feedSnap.docs) {
            if (!validRecordIds.contains(feedDoc.id)) {
              batch.delete(feedDoc.reference);
              opsInBatch++;
              _deleted++;
              await flushIfNeeded();
            }
          }
        }
        if (opsInBatch > 0) await batch.commit();
      }

      if (mounted) {
        setState(() {
          _status =
              'Done. Processed $_processed, written $_written, '
              'skipped $_skipped'
              '${_removeOrphans ? ', removed $_deleted orphan(s)' : ''}.';
        });
      }
    } catch (e) {
      if (mounted) setState(() => _status = 'Failed: $e');
    } finally {
      if (mounted) setState(() => _running = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Rebuild Unloading Feed'),
        backgroundColor: Colors.blue[800],
        foregroundColor: Colors.white,
      ),
      body: SingleChildScrollView(
        padding: const EdgeInsets.all(16),
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 560),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              const Text(
                'Backfills unloading_feed from work_records and '
                'manual_site_reports for the selected date range '
                '(idempotent — safe to re-run). Also repairs older records '
                'missing unloadingSiteId where the site can now be '
                'resolved by name.',
                style: TextStyle(fontSize: 13, color: Colors.black54),
              ),
              const SizedBox(height: 16),
              OutlinedButton.icon(
                onPressed: _running ? null : _pickDateRange,
                icon: const Icon(Icons.date_range),
                label: Text(
                  _dateRange == null
                      ? 'Last 30 Days'
                      : '${_ymd(_dateRange!.start)} - '
                            '${_ymd(_dateRange!.end)}',
                ),
              ),
              const SizedBox(height: 8),
              CheckboxListTile(
                title: const Text('Remove orphan feed entries in this range'),
                subtitle: const Text(
                  'Deletes feed entries whose source record was deleted.',
                ),
                value: _removeOrphans,
                contentPadding: EdgeInsets.zero,
                controlAffinity: ListTileControlAffinity.leading,
                onChanged: _running
                    ? null
                    : (val) => setState(() => _removeOrphans = val ?? false),
              ),
              const SizedBox(height: 16),
              SizedBox(
                width: double.infinity,
                child: ElevatedButton(
                  onPressed: _running ? null : _runRebuild,
                  style: ElevatedButton.styleFrom(
                    padding: const EdgeInsets.symmetric(vertical: 14),
                    backgroundColor: Colors.blue[700],
                  ),
                  child: _running
                      ? const SizedBox(
                          width: 20,
                          height: 20,
                          child: CircularProgressIndicator(
                            strokeWidth: 2,
                            color: Colors.white,
                          ),
                        )
                      : const Text(
                          'REBUILD',
                          style: TextStyle(color: Colors.white),
                        ),
                ),
              ),
              if (_status.isNotEmpty) ...[
                const SizedBox(height: 16),
                Text(_status, style: const TextStyle(fontSize: 13)),
              ],
            ],
          ),
        ),
      ),
    );
  }
}

// ---------------- WEBSITE CONTENT MANAGEMENT SCREEN (web-only content, Admin) ----------------
class WebsiteContentManagementScreen extends StatefulWidget {
  const WebsiteContentManagementScreen({super.key});

  @override
  State<WebsiteContentManagementScreen> createState() =>
      _WebsiteContentManagementScreenState();
}

class _WebsiteContentManagementScreenState
    extends State<WebsiteContentManagementScreen> {
  final _heroTitleController = TextEditingController();
  final _heroSubtitleController = TextEditingController();
  final _aboutTextController = TextEditingController();
  final _whatsappController = TextEditingController();
  final _contactEmailController = TextEditingController();
  bool _loadingContent = true;
  bool _savingContent = false;

  @override
  void initState() {
    super.initState();
    _loadContent();
  }

  @override
  void dispose() {
    _heroTitleController.dispose();
    _heroSubtitleController.dispose();
    _aboutTextController.dispose();
    _whatsappController.dispose();
    _contactEmailController.dispose();
    super.dispose();
  }

  Future<void> _loadContent() async {
    final doc = await FirebaseFirestore.instance
        .collection('website_content')
        .doc('main')
        .get();
    final data = doc.data();
    if (data != null) {
      _heroTitleController.text = data['heroTitle'] ?? '';
      _heroSubtitleController.text = data['heroSubtitle'] ?? '';
      _aboutTextController.text = data['aboutText'] ?? '';
      _whatsappController.text = data['whatsappNumber'] ?? '';
      _contactEmailController.text = data['contactEmail'] ?? '';
    }
    if (mounted) setState(() => _loadingContent = false);
  }

  Future<void> _saveContent() async {
    setState(() => _savingContent = true);
    try {
      await FirebaseFirestore.instance
          .collection('website_content')
          .doc('main')
          .set({
            'heroTitle': _heroTitleController.text.trim(),
            'heroSubtitle': _heroSubtitleController.text.trim(),
            'aboutText': _aboutTextController.text.trim(),
            'whatsappNumber': _whatsappController.text.trim(),
            'contactEmail': _contactEmailController.text.trim(),
          }, SetOptions(merge: true));
      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(const SnackBar(content: Text('Website content saved.')));
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text('Failed to save: $e')));
      }
    } finally {
      if (mounted) setState(() => _savingContent = false);
    }
  }

  Future<void> _addGalleryPhoto() async {
    try {
      final picker = ImagePicker();
      final pickedFile = await picker.pickImage(
        source: ImageSource.gallery,
        maxWidth: 1200,
        imageQuality: 70,
      );
      if (pickedFile == null) return;

      final bytes = await pickedFile.readAsBytes();
      final base64String = base64Encode(bytes);

      // Firestore document limit is 1MB; keep a safety margin
      if (base64String.length > 700000) {
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(
              content: Text('Image too large. Please choose a smaller photo.'),
            ),
          );
        }
        return;
      }

      final existing = await FirebaseFirestore.instance
          .collection('website_gallery')
          .get();
      int maxOrder = -1;
      for (final doc in existing.docs) {
        final order = (doc.data()['order'] as num?)?.toInt() ?? -1;
        if (order > maxOrder) maxOrder = order;
      }

      await FirebaseFirestore.instance.collection('website_gallery').add({
        'imageBase64': base64String,
        'caption': '',
        'order': maxOrder + 1,
        'createdAt': FieldValue.serverTimestamp(),
      });

      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(const SnackBar(content: Text('Photo added.')));
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text('Error adding photo: $e')));
      }
    }
  }

  Future<void> _editGalleryCaption(String docId, String currentCaption) async {
    final controller = TextEditingController(text: currentCaption);
    final result = await showDialog<String>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Edit Caption'),
        content: TextField(
          controller: controller,
          decoration: const InputDecoration(labelText: 'Caption'),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext),
            child: const Text('Cancel'),
          ),
          ElevatedButton(
            onPressed: () =>
                Navigator.pop(dialogContext, controller.text.trim()),
            child: const Text('Save'),
          ),
        ],
      ),
    );
    if (result != null) {
      await FirebaseFirestore.instance
          .collection('website_gallery')
          .doc(docId)
          .update({'caption': result});
    }
  }

  Future<void> _deleteGalleryPhoto(String docId) async {
    await FirebaseFirestore.instance
        .collection('website_gallery')
        .doc(docId)
        .delete();
  }

  void _showServiceDialog({String? docId, Map<String, dynamic>? existingData}) {
    final titleController = TextEditingController(
      text: existingData?['title'] ?? '',
    );
    final descController = TextEditingController(
      text: existingData?['description'] ?? '',
    );
    String selectedIcon =
        (existingData?['iconName'] as String?) ??
        kWebsiteServiceIcons.keys.first;

    showDialog(
      context: context,
      builder: (dialogContext) => StatefulBuilder(
        builder: (dialogContext, setDialogState) => AlertDialog(
          title: Text(docId == null ? 'Add Service' : 'Edit Service'),
          content: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                TextField(
                  controller: titleController,
                  decoration: const InputDecoration(labelText: 'Title'),
                ),
                const SizedBox(height: 12),
                TextField(
                  controller: descController,
                  decoration: const InputDecoration(labelText: 'Description'),
                  maxLines: 3,
                ),
                const SizedBox(height: 12),
                DropdownButtonFormField<String>(
                  initialValue: selectedIcon,
                  decoration: const InputDecoration(labelText: 'Icon'),
                  items: kWebsiteServiceIcons.entries
                      .map(
                        (e) => DropdownMenuItem(
                          value: e.key,
                          child: Row(
                            children: [
                              Icon(e.value, size: 18),
                              const SizedBox(width: 8),
                              Text(e.key),
                            ],
                          ),
                        ),
                      )
                      .toList(),
                  onChanged: (val) =>
                      setDialogState(() => selectedIcon = val ?? selectedIcon),
                ),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dialogContext),
              child: const Text('Cancel'),
            ),
            ElevatedButton(
              onPressed: () async {
                final title = titleController.text.trim();
                final description = descController.text.trim();
                if (title.isEmpty) return;

                if (docId == null) {
                  final existing = await FirebaseFirestore.instance
                      .collection('website_services')
                      .get();
                  int maxOrder = -1;
                  for (final doc in existing.docs) {
                    final order = (doc.data()['order'] as num?)?.toInt() ?? -1;
                    if (order > maxOrder) maxOrder = order;
                  }
                  await FirebaseFirestore.instance
                      .collection('website_services')
                      .add({
                        'title': title,
                        'description': description,
                        'iconName': selectedIcon,
                        'order': maxOrder + 1,
                        'createdAt': FieldValue.serverTimestamp(),
                      });
                } else {
                  await FirebaseFirestore.instance
                      .collection('website_services')
                      .doc(docId)
                      .update({
                        'title': title,
                        'description': description,
                        'iconName': selectedIcon,
                      });
                }
                if (dialogContext.mounted) Navigator.pop(dialogContext);
              },
              child: const Text('Save'),
            ),
          ],
        ),
      ),
    );
  }

  Future<void> _deleteService(String docId) async {
    await FirebaseFirestore.instance
        .collection('website_services')
        .doc(docId)
        .delete();
  }

  Widget _buildHeroAboutTab() {
    if (_loadingContent) {
      return const Center(child: CircularProgressIndicator());
    }
    return SingleChildScrollView(
      padding: const EdgeInsets.all(16),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          TextField(
            controller: _heroTitleController,
            decoration: InputDecoration(
              labelText: 'Hero Title',
              border: OutlineInputBorder(
                borderRadius: BorderRadius.circular(12),
              ),
