          ),
          const SizedBox(height: 16),
          TextField(
            controller: _heroSubtitleController,
            maxLines: 2,
            decoration: InputDecoration(
              labelText: 'Hero Subtitle',
              border: OutlineInputBorder(
                borderRadius: BorderRadius.circular(12),
              ),
            ),
          ),
          const SizedBox(height: 16),
          TextField(
            controller: _aboutTextController,
            maxLines: 5,
            decoration: InputDecoration(
              labelText: 'About Text',
              border: OutlineInputBorder(
                borderRadius: BorderRadius.circular(12),
              ),
            ),
          ),
          const SizedBox(height: 16),
          TextField(
            controller: _whatsappController,
            decoration: InputDecoration(
              labelText: 'WhatsApp Number',
              hintText: 'e.g. 94XXXXXXXXX',
              border: OutlineInputBorder(
                borderRadius: BorderRadius.circular(12),
              ),
            ),
          ),
          const SizedBox(height: 16),
          TextField(
            controller: _contactEmailController,
            keyboardType: TextInputType.emailAddress,
            // Shown on the public Account Deletion page (see
            // AccountDeletionScreen) — Google Play's Data Safety review
            // actually uses this address, so keep it a real, monitored one.
            decoration: InputDecoration(
              labelText: 'Contact Email',
              hintText: 'e.g. support@nodacivimech.com',
              border: OutlineInputBorder(
                borderRadius: BorderRadius.circular(12),
              ),
            ),
          ),
          const SizedBox(height: 20),
          SizedBox(
            width: double.infinity,
            height: 48,
            child: ElevatedButton(
              onPressed: _savingContent ? null : _saveContent,
              style: ElevatedButton.styleFrom(
                backgroundColor: Colors.indigo[800],
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(12),
                ),
              ),
              child: Text(
                _savingContent ? 'Saving...' : 'SAVE CHANGES',
                style: const TextStyle(color: Colors.white),
              ),
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildGalleryTab() {
    return Column(
      children: [
        Padding(
          padding: const EdgeInsets.all(16),
          child: SizedBox(
            width: double.infinity,
            height: 48,
            child: ElevatedButton.icon(
              onPressed: _addGalleryPhoto,
              icon: const Icon(Icons.add_a_photo, color: Colors.white),
              label: const Text(
                'ADD PHOTO',
                style: TextStyle(color: Colors.white),
              ),
              style: ElevatedButton.styleFrom(
                backgroundColor: Colors.indigo[800],
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(12),
                ),
              ),
            ),
          ),
        ),
        Expanded(
          child: StreamBuilder<QuerySnapshot>(
            stream: FirebaseFirestore.instance
                .collection('website_gallery')
                .orderBy('order')
                .snapshots(),
            builder: (context, snapshot) {
              if (snapshot.connectionState == ConnectionState.waiting) {
                return const Center(child: CircularProgressIndicator());
              }
              final docs = snapshot.data?.docs ?? [];
              if (docs.isEmpty) {
                return const Center(child: Text('No photos added yet.'));
              }
              return GridView.builder(
                padding: const EdgeInsets.all(16),
                gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
                  crossAxisCount: 3,
                  crossAxisSpacing: 12,
                  mainAxisSpacing: 12,
                  childAspectRatio: 0.85,
                ),
                itemCount: docs.length,
                itemBuilder: (context, index) {
                  final doc = docs[index];
                  final data = doc.data() as Map<String, dynamic>;
                  final caption = (data['caption'] ?? '').toString();
                  return Card(
                    clipBehavior: Clip.antiAlias,
                    child: Column(
                      children: [
                        Expanded(
                          child: Image.memory(
                            base64Decode(data['imageBase64']),
                            fit: BoxFit.cover,
                            width: double.infinity,
                          ),
                        ),
                        Padding(
                          padding: const EdgeInsets.symmetric(
                            horizontal: 6,
                            vertical: 4,
                          ),
                          child: Row(
                            children: [
                              Expanded(
                                child: Text(
                                  caption.isEmpty ? 'No caption' : caption,
                                  style: TextStyle(
                                    fontSize: 11,
                                    color: caption.isEmpty
                                        ? Colors.grey
                                        : Colors.black87,
                                  ),
                                  overflow: TextOverflow.ellipsis,
                                ),
                              ),
                              InkWell(
                                onTap: () =>
                                    _editGalleryCaption(doc.id, caption),
                                child: const Icon(
                                  Icons.edit,
                                  size: 16,
                                  color: Colors.indigo,
                                ),
                              ),
                              const SizedBox(width: 6),
                              InkWell(
                                onTap: () => confirmDelete(
                                  context: context,
                                  title: 'Delete Photo?',
                                  message:
                                      'Are you sure you want to delete this photo? This cannot be undone.',
                                  onConfirm: () => _deleteGalleryPhoto(doc.id),
                                ),
                                child: const Icon(
                                  Icons.delete,
                                  size: 16,
                                  color: Colors.red,
                                ),
                              ),
                            ],
                          ),
                        ),
                      ],
                    ),
                  );
                },
              );
            },
          ),
        ),
      ],
    );
  }

  Widget _buildServicesTab() {
    return Column(
      children: [
        Padding(
          padding: const EdgeInsets.all(16),
          child: SizedBox(
            width: double.infinity,
            height: 48,
            child: ElevatedButton.icon(
              onPressed: () => _showServiceDialog(),
              icon: const Icon(Icons.add, color: Colors.white),
              label: const Text(
                'ADD SERVICE',
                style: TextStyle(color: Colors.white),
              ),
              style: ElevatedButton.styleFrom(
                backgroundColor: Colors.indigo[800],
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(12),
                ),
              ),
            ),
          ),
        ),
        Expanded(
          child: StreamBuilder<QuerySnapshot>(
            stream: FirebaseFirestore.instance
                .collection('website_services')
                .orderBy('order')
                .snapshots(),
            builder: (context, snapshot) {
              if (snapshot.connectionState == ConnectionState.waiting) {
                return const Center(child: CircularProgressIndicator());
              }
              final docs = snapshot.data?.docs ?? [];
              if (docs.isEmpty) {
                return const Center(child: Text('No services added yet.'));
              }
              return ListView.builder(
                padding: const EdgeInsets.all(12),
                itemCount: docs.length,
                itemBuilder: (context, index) {
                  final doc = docs[index];
                  final data = doc.data() as Map<String, dynamic>;
                  final iconName = (data['iconName'] ?? '').toString();
                  final icon = kWebsiteServiceIcons[iconName] ?? Icons.build;
                  return Card(
                    margin: const EdgeInsets.only(bottom: 10),
                    child: ListTile(
                      leading: CircleAvatar(
                        backgroundColor: Colors.indigo.withOpacity(0.15),
                        child: Icon(icon, color: Colors.indigo),
                      ),
                      title: Text(data['title'] ?? ''),
                      subtitle: Text(data['description'] ?? ''),
                      trailing: Row(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          IconButton(
                            icon: const Icon(Icons.edit, color: Colors.indigo),
                            onPressed: () => _showServiceDialog(
                              docId: doc.id,
                              existingData: data,
                            ),
                          ),
                          IconButton(
                            icon: const Icon(Icons.delete, color: Colors.red),
                            onPressed: () => confirmDelete(
                              context: context,
                              title: 'Delete Service?',
                              message:
                                  'Are you sure you want to delete this service? This cannot be undone.',
                              onConfirm: () => _deleteService(doc.id),
                            ),
                          ),
                        ],
                      ),
                    ),
                  );
                },
              );
            },
          ),
        ),
      ],
    );
  }

  @override
  Widget build(BuildContext context) {
    return DefaultTabController(
      length: 3,
      child: Scaffold(
        appBar: AppBar(
          title: const Text('Website Content'),
          backgroundColor: Colors.indigo[800],
          bottom: const TabBar(
            tabs: [
              Tab(text: 'Hero & About'),
              Tab(text: 'Gallery'),
              Tab(text: 'Services'),
            ],
          ),
        ),
        body: TabBarView(
          children: [
            _buildHeroAboutTab(),
            _buildGalleryTab(),
            _buildServicesTab(),
          ],
        ),
      ),
    );
  }
}

// OVERDUE/red, DUE SOON/amber, OK/green banner on the Truck Profile — matches
// that screen's own GlassCard/white-on-gradient look rather than importing
// the Truck Repair module's AppCard chrome into a screen that doesn't use
// it anywhere else. Computed once per mount (not rebuilt on every
// truck_sessions/trucks stream tick above it), since it does its own
// GPS/Firestore round trip.
class _TruckServiceStatusBanner extends StatefulWidget {
  final String vehicleNumber;
  final FirebaseFirestore? firestoreOverride;
  const _TruckServiceStatusBanner({required this.vehicleNumber, this.firestoreOverride});

  @override
  State<_TruckServiceStatusBanner> createState() => _TruckServiceStatusBannerState();
}

class _TruckServiceStatusBannerState extends State<_TruckServiceStatusBanner> {
  late Future<
      ({
        String vehicleNumber,
        double? currentKm,
        String kmSource,
        String worstStatus,
        List<ServiceItemDue> due
      })> _future;
  // Instant, Traccar-free placeholder — filled in from vehicle_km_cache
  // (one fast doc read) the moment this banner mounts, shown in place of
  // the bare spinner below while _future (Traccar-first) is still
  // resolving. Left null (falls back to the spinner) if there's no cached
  // entry yet.
  ({double km, String source})? _peek;

  @override
  void initState() {
    super.initState();
    _future = fetchVehicleServiceOverview(widget.vehicleNumber, db: widget.firestoreOverride);
    peekLastKnownKm(widget.vehicleNumber, db: widget.firestoreOverride).then((p) {
      if (p != null && mounted) setState(() => _peek = p);
    });
  }

  // Bypasses VehicleKmCache so a manual retry (or the small refresh icon
  // next to "Current km") always asks Traccar again instead of replaying a
  // cached timeout/failure.
  void _retry() {
    setState(() {
      _future = fetchVehicleServiceOverview(
        widget.vehicleNumber,
        db: widget.firestoreOverride,
        forceRefresh: true,
      );
    });
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder(
      future: _future,
      builder: (context, snap) {
        if (snap.connectionState != ConnectionState.done) {
          if (_peek != null) {
            return GlassCard(
              child: Row(
                children: [
                  const Icon(Icons.history, color: Colors.white54, size: 16),
                  const SizedBox(width: 8),
                  Expanded(
                    child: Text(
                      '${_peek!.source}: ${_peek!.km.toStringAsFixed(0)} km',
                      style: const TextStyle(color: Colors.white70, fontSize: 12),
                    ),
                  ),
                  const SizedBox(
                    width: 14,
                    height: 14,
                    child: CircularProgressIndicator(color: Colors.white54, strokeWidth: 2),
                  ),
                ],
              ),
            );
          }
          return const GlassCard(
            child: SizedBox(
              height: 36,
              child: Center(
                child: CircularProgressIndicator(color: Colors.white, strokeWidth: 2),
              ),
            ),
          );
        }
        if (snap.hasError || snap.data == null) {
          debugPrint('_TruckServiceStatusBanner: ${widget.vehicleNumber}: ${snap.error}');
          return GlassCard(
            child: Row(
              children: [
                const Icon(Icons.wifi_off, color: Colors.white54, size: 16),
                const SizedBox(width: 8),
                Expanded(
                  child: Text(
                    kDebugMode && snap.hasError
                        ? 'Service status unavailable: ${snap.error}'
                        : 'Service status unavailable',
                    style: const TextStyle(color: Colors.white70, fontSize: 12),
                  ),
                ),
                TextButton(
                  onPressed: _retry,
                  child: const Text('RETRY'),
                ),
              ],
            ),
          );
        }
        final overview = snap.data!;
        if (overview.due.isEmpty) return const SizedBox.shrink();
        final color = _serviceDueStatusColor(overview.worstStatus);
        final label = _serviceDueStatusLabel(overview.worstStatus);
        return GlassCard(
          child: InkWell(
            onTap: () => pushWebAware(
              context,
              VehicleServiceHistoryScreen(vehicleNumber: widget.vehicleNumber),
            ),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Row(
                  children: [
                    Icon(Icons.build_circle, color: color),
                    const SizedBox(width: 8),
                    Expanded(
                      child: Text(
                        'SERVICE: $label',
                        style:
                            TextStyle(color: color, fontWeight: FontWeight.bold, fontSize: 14),
                      ),
                    ),
                    const Icon(Icons.chevron_right, color: Colors.white54),
                  ],
                ),
                const SizedBox(height: 8),
                for (final d in overview.due)
                  Padding(
                    padding: const EdgeInsets.only(bottom: 6),
                    child: Row(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Padding(
                          padding: const EdgeInsets.only(top: 4),
                          child: Icon(Icons.circle, size: 8, color: _serviceDueStatusColor(d.status)),
                        ),
                        const SizedBox(width: 6),
                        Expanded(
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Text(
                                '${d.itemName}: ${serviceItemStatusSummary(d)}',
                                style: const TextStyle(
                                  color: Colors.white,
                                  fontSize: 12,
                                  fontWeight: FontWeight.w600,
                                ),
                              ),
                              if (provisionalChipLabel(d.provisional) != null)
                                Padding(
                                  padding: const EdgeInsets.only(top: 2),
                                  child: Container(
                                    padding: const EdgeInsets.symmetric(
                                        horizontal: 6, vertical: 2),
                                    decoration: BoxDecoration(
                                      color: provisionalChipColor(d.provisional).withOpacity(0.18),
                                      borderRadius: BorderRadius.circular(AppRadius.chip),
                                    ),
                                    child: Text(
                                      provisionalChipLabel(d.provisional)!,
                                      style: TextStyle(
                                        color: provisionalChipColor(d.provisional),
                                        fontSize: 10,
                                        fontWeight: FontWeight.bold,
                                      ),
                                    ),
                                  ),
                                ),
                              if (d.lastDoneDate != null)
                                Padding(
                                  padding: const EdgeInsets.only(top: 2),
                                  child: Text(
                                    'Last service: ${_repairYmd(d.lastDoneDate!)}'
                                    '${d.lastDoneKm != null ? ' at ${d.lastDoneKm!.toStringAsFixed(0)} km' : ''}'
                                    '${(d.lastGarageName ?? '').isEmpty ? '' : ' — ${d.lastGarageName}'}',
                                    style: const TextStyle(color: Colors.white54, fontSize: 10),
                                  ),
                                ),
                              if (d.returnReason != null)
                                Padding(
                                  padding: const EdgeInsets.only(top: 2),
                                  child: Text(
                                    'Returned: ${d.returnReason}',
                                    style: const TextStyle(color: Colors.white54, fontSize: 10),
                                  ),
                                ),
                            ],
                          ),
                        ),
                      ],
                    ),
                  ),
                Row(
                  children: [
                    Expanded(
                      child: Text(
                        'Current km: ${overview.currentKm?.toStringAsFixed(0) ?? '—'} '
                        '(${overview.kmSource})',
                        style: const TextStyle(color: Colors.white54, fontSize: 11),
                      ),
                    ),
                    InkWell(
                      onTap: _retry,
                      child: const Padding(
                        padding: EdgeInsets.all(4),
                        child: Icon(Icons.refresh, size: 14, color: Colors.white54),
                      ),
                    ),
                  ],
                ),
              ],
            ),
          ),
        );
      },
    );
  }
}

// ---------------- TRUCK PROFILE SCREEN (Admin/Owner) ----------------
class TruckProfileScreen extends StatelessWidget {
  final String truckId;
  final String truckNumber;
  // Test-only seam — every existing call site omits this and keeps using
  // the real FirebaseFirestore.instance (only the two read streams this
  // page itself builds from; the change-driver/GPS/cube-capacity dialogs
  // below are unaffected, same as every other screen's existing pattern).
  final FirebaseFirestore? firestoreOverride;

  const TruckProfileScreen({
    super.key,
    required this.truckId,
    required this.truckNumber,
    this.firestoreOverride,
  });

  void _showChangeDriverDialog(BuildContext context, String? currentDriverUid) {
    // Ephemeral to this dialog invocation only — same pattern as
    // _showEditSiteNameDialog's nameController, no explicit dispose needed.
    final manualNameController = TextEditingController();
    showDialog(
      context: context,
      builder: (_) => AlertDialog(
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
        title: const Text('Change Assigned Driver'),
        content: SizedBox(
          width: double.maxFinite,
          child: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                StreamBuilder<QuerySnapshot>(
                  stream: assignableTruckDriversStream(db: firestoreOverride),
                  builder: (context, snapshot) {
                    if (!snapshot.hasData) {
                      return const Padding(
                        padding: EdgeInsets.symmetric(vertical: 20),
                        child: Center(child: CircularProgressIndicator()),
                      );
                    }
                    final drivers = assignableTruckDrivers(snapshot.data!.docs);
                    if (drivers.isEmpty) {
                      return const Padding(
                        padding: EdgeInsets.symmetric(vertical: 20),
                        child: Text('No drivers available.'),
                      );
                    }
                    return SizedBox(
                      height: 300,
                      child: ListView.builder(
                        shrinkWrap: true,
                        itemCount: drivers.length,
                        itemBuilder: (context, index) {
                          final data =
                              drivers[index].data() as Map<String, dynamic>;
                          final uid = drivers[index].id;
                          final isSelected = uid == currentDriverUid;
                          return ListTile(
                            leading: CircleAvatar(
                              backgroundColor: Colors.deepOrange.withOpacity(
                                0.15,
                              ),
                              child: const Icon(
                                Icons.person,
                                color: Colors.deepOrange,
                              ),
                            ),
                            title: Text(data['name'] ?? ''),
                            trailing: isSelected
                                ? const Icon(
                                    Icons.check,
                                    color: Colors.deepOrange,
                                  )
                                : null,
                            onTap: () async {
                              await FirebaseFirestore.instance
                                  .collection('trucks')
                                  .doc(truckId)
                                  .update({
                                    'assignedDriverUid': uid,
                                    'assignedDriverName': data['name'] ?? '',
                                  });
                              if (context.mounted) Navigator.pop(context);
                            },
                          );
                        },
                      ),
                    );
                  },
                ),
                const Padding(
                  padding: EdgeInsets.symmetric(vertical: 12),
                  child: Row(
                    children: [
                      Expanded(child: Divider()),
                      Padding(
                        padding: EdgeInsets.symmetric(horizontal: 8),
                        child: Text(
                          'OR',
                          style: TextStyle(
                            fontWeight: FontWeight.bold,
                            color: Colors.grey,
                          ),
                        ),
                      ),
                      Expanded(child: Divider()),
                    ],
                  ),
                ),
                const Text(
                  'Type a name manually',
                  style: TextStyle(fontWeight: FontWeight.bold, fontSize: 13),
                ),
                const SizedBox(height: 4),
                const Text(
                  'For a driver who isn\'t registered in the app (e.g. a '
                  'substitute or contract driver).',
                  style: TextStyle(fontSize: 12, color: Colors.grey),
                ),
                const SizedBox(height: 8),
                TextField(
                  controller: manualNameController,
                  inputFormatters: [UpperCaseTextFormatter()],
                  textCapitalization: TextCapitalization.characters,
                  decoration: const InputDecoration(
                    hintText: 'Driver name',
                    border: OutlineInputBorder(),
                  ),
                ),
                const SizedBox(height: 12),
                SizedBox(
                  width: double.infinity,
                  child: ElevatedButton(
                    style: ElevatedButton.styleFrom(
                      backgroundColor: Colors.deepOrange[800],
                    ),
                    onPressed: () async {
                      final typedName = manualNameController.text.trim();
                      if (typedName.isEmpty) return;
                      // Not a registered user — no canDriveTruck account —
                      // so assignedDriverUid stays null. Auto-fill in the
                      // Loading dialog reads assignedDriverName either way,
                      // so this works there with no further changes.
                      await FirebaseFirestore.instance
                          .collection('trucks')
                          .doc(truckId)
                          .update({
                            'assignedDriverUid': null,
                            'assignedDriverName': typedName,
                          });
                      if (context.mounted) Navigator.pop(context);
                    },
                    child: const Text(
                      'Assign This Name',
                      style: TextStyle(color: Colors.white),
                    ),
                  ),
                ),
              ],
            ),
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: const Text('Cancel'),
          ),
        ],
      ),
    );
  }

  // GPS Live Tracking (Phase 1, web-only — see LiveTrackingScreen): the
  // gpsDeviceId manually entered here is matched against each Traccar
  // position's deviceId to place this truck's marker on the map. It's
  // typed in by hand (copied from the Traccar Devices list's Identifier
  // column) rather than looked up live, since this app has no Traccar
  // device-provisioning integration — Traccar is the source of truth for
  // which identifiers exist.
  void _showSetGpsDeviceDialog(BuildContext context, String? currentDeviceId) {
    final deviceIdController = TextEditingController(
      text: currentDeviceId ?? '',
    );
    showDialog(
      context: context,
      builder: (_) => AlertDialog(
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
        title: const Text('Assigned GPS Device'),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Text(
              'Enter this truck\'s Traccar Device Identifier (copy it from '
              'the Traccar Devices list).',
              style: TextStyle(fontSize: 13, color: Colors.black54),
            ),
            const SizedBox(height: 12),
            TextField(
              controller: deviceIdController,
              autofocus: true,
              decoration: const InputDecoration(
                labelText: 'GPS Device Identifier',
                hintText: 'e.g. 9210188280',
                border: OutlineInputBorder(),
              ),
            ),
          ],
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: const Text('Cancel'),
          ),
          ElevatedButton(
            onPressed: () async {
              final typedId = deviceIdController.text.trim();
              await FirebaseFirestore.instance
                  .collection('trucks')
                  .doc(truckId)
                  .update({'gpsDeviceId': typedId.isEmpty ? null : typedId});
              if (context.mounted) Navigator.pop(context);
            },
            child: const Text('Save'),
          ),
        ],
      ),
    );
  }

  // Cube Capacity (trucks/{id}.cubeCapacity) — shown read-only on Vehicle
  // Registration's QR Generate tab so a supervisor scanning the QR knows
  // this truck's max load without asking, and used by QR Scan's submitted
  // work_records.cubeCount.
  void _showSetCubeCapacityDialog(BuildContext context, double? currentValue) {
    final capacityController = TextEditingController(
      text: currentValue?.toString() ?? '',
    );
    showDialog(
      context: context,
      builder: (_) => AlertDialog(
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
        title: const Text('Cube Capacity'),
        content: TextField(
          controller: capacityController,
          autofocus: true,
          keyboardType: const TextInputType.numberWithOptions(decimal: true),
          decoration: const InputDecoration(
            labelText: 'Cube Capacity',
            border: OutlineInputBorder(),
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: const Text('Cancel'),
          ),
          ElevatedButton(
            onPressed: () async {
              final typedValue = double.tryParse(
                capacityController.text.trim(),
              );
              await FirebaseFirestore.instance
                  .collection('trucks')
                  .doc(truckId)
                  .update({'cubeCapacity': typedValue});
              if (context.mounted) Navigator.pop(context);
            },
            child: const Text('Save'),
          ),
        ],
      ),
    );
  }

  String _formatTime(Timestamp? ts) {
    if (ts == null) return '-';
    final dt = ts.toDate();
    final hour = dt.hour % 12 == 0 ? 12 : dt.hour % 12;
    final period = dt.hour >= 12 ? 'PM' : 'AM';
    final minute = dt.minute.toString().padLeft(2, '0');
    return '$hour:$minute $period';
  }

  String _formatDateHeader(String dateString) {
    final parts = dateString.split('-');
    if (parts.length != 3) return dateString;
    final date = DateTime(
      int.parse(parts[0]),
      int.parse(parts[1]),
      int.parse(parts[2]),
    );
    final today = DateTime.now();
    final todayStr =
        "${today.year}-${today.month.toString().padLeft(2, '0')}-${today.day.toString().padLeft(2, '0')}";
    if (dateString == todayStr) return 'Today';
    final yesterday = today.subtract(const Duration(days: 1));
    final yestStr =
        "${yesterday.year}-${yesterday.month.toString().padLeft(2, '0')}-${yesterday.day.toString().padLeft(2, '0')}";
    if (dateString == yestStr) return 'Yesterday';
    const months = [
      'Jan',
      'Feb',
      'Mar',
      'Apr',
      'May',
      'Jun',
      'Jul',
      'Aug',
      'Sep',
      'Oct',
      'Nov',
      'Dec',
    ];
    return '${date.day} ${months[date.month - 1]} ${date.year}';
  }

  static const List<Color> _dayColors = [
    Color(0xFF3D9DE0),
    Color(0xFF4CAF7D),
    Color(0xFFE0A93D),
    Color(0xFF9B6BE0),
    Color(0xFFE05C97),
    Color(0xFF3DBFC4),
    Color(0xFFEF6C57),
    Color(0xFF7D8CE0),
  ];

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Container(
        decoration: const BoxDecoration(gradient: AppTheme.mainGradient),
        child: SafeArea(
          child: Column(
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 8, 16, 0),
                child: Row(
                  children: [
                    IconButton(
                      icon: const Icon(Icons.arrow_back, color: Colors.white),
                      onPressed: () => Navigator.pop(context),
                    ),
                    Expanded(
                      child: Text(
                        truckNumber,
                        style: const TextStyle(
                          fontSize: 18,
                          fontWeight: FontWeight.bold,
                          color: Colors.white,
                        ),
                        overflow: TextOverflow.ellipsis,
                        maxLines: 1,
                      ),
                    ),
                    IconButton(
                      icon: const Icon(Icons.build_circle, color: Colors.white),
                      tooltip: 'Service History',
                      onPressed: () => pushWebAware(
                        context,
                        VehicleServiceHistoryScreen(
                          vehicleNumber: truckNumber,
                        ),
                      ),
                    ),
                    IconButton(
                      icon: const Icon(Icons.history, color: Colors.white),
                      tooltip: 'Repair History',
                      onPressed: () => pushWebAware(
                        context,
                        RepairHistoryScreen(
                          prefillVehicleNumber: truckNumber,
                        ),
                      ),
                    ),
                    // Admin/owner/management only — VehicleHealthScreen
                    // itself re-checks this (defence in depth); shown
                    // unconditionally here the same way the two icon
                    // buttons above are, since this whole screen is
                    // already only reachable by admin/owner in practice.
                    IconButton(
                      icon: const Icon(Icons.local_shipping_outlined, color: Colors.white),
                      tooltip: 'Vehicle Health',
                      onPressed: () => pushWebAware(
                        context,
                        VehicleHealthScreen(
                          initialVehicleNumber: truckNumber,
                          firestoreOverride: firestoreOverride,
                        ),
                      ),
                    ),
                  ],
                ),
              ),
              Expanded(
                child: StreamBuilder<QuerySnapshot>(
                  stream: (firestoreOverride ?? FirebaseFirestore.instance)
                      .collection('truck_sessions')
                      .where('truckId', isEqualTo: truckId)
                      .snapshots(),
                  builder: (context, snapshot) {
                    if (!snapshot.hasData) {
                      return const Center(
                        child: CircularProgressIndicator(color: Colors.white),
                      );
                    }
                    final sessions = snapshot.data!.docs;

                    // Find current active session for "where is it now" summary
                    QueryDocumentSnapshot? activeSession;
                    for (final doc in sessions) {
                      final data = doc.data() as Map<String, dynamic>;
                      if (data['status'] == 'active') {
                        activeSession = doc;
                        break;
                      }
                    }

                    return SingleChildScrollView(
                      padding: const EdgeInsets.all(16),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          StreamBuilder<DocumentSnapshot>(
                            stream: (firestoreOverride ?? FirebaseFirestore.instance)
                                .collection('trucks')
                                .doc(truckId)
                                .snapshots(),
                            builder: (context, truckSnap) {
                              final truckData =
                                  truckSnap.data?.data()
                                      as Map<String, dynamic>?;
                              final assignedDriverName =
                                  truckData?['assignedDriverName'];
                              final assignedDriverUid =
                                  truckData?['assignedDriverUid'];
                              final gpsDeviceId =
                                  truckData?['gpsDeviceId'] as String?;
                              final cubeCapacity =
                                  (truckData?['cubeCapacity'] as num?)
                                      ?.toDouble();
                              final isCompanyTruck =
                                  truckData?['isCompanyTruck'] == true;

                              return Column(
                                children: [
                                  _TruckServiceStatusBanner(
                                    vehicleNumber: truckNumber,
                                    firestoreOverride: firestoreOverride,
                                  ),
                                  const SizedBox(height: 12),
                                  GlassCard(
                                    child: Column(
                                      children: [
                                        Icon(
                                          activeSession != null
                                              ? Icons.play_circle_fill
                                              : Icons.pause_circle,
                                          color: activeSession != null
                                              ? Colors.green
                                              : Colors.grey,
                                          size: 36,
                                        ),
                                        const SizedBox(height: 8),
                                        Text(
                                          activeSession != null
                                              ? 'Currently Active'
                                              : 'Not Working Now',
                                          style: const TextStyle(
                                            color: Colors.white,
                                            fontWeight: FontWeight.bold,
                                            fontSize: 16,
                                          ),
                                        ),
                                        if (activeSession != null) ...[
                                          const SizedBox(height: 8),
                                          Text(
                                            'Site: ${(activeSession.data() as Map)['siteName'] ?? '-'}',
                                            style: const TextStyle(
                                              color: Colors.white,
                                              fontSize: 13,
                                            ),
                                          ),
                                        ],
                                        const Divider(
                                          color: Colors.white24,
                                          height: 24,
                                        ),
                                        Row(
                                          mainAxisAlignment:
                                              MainAxisAlignment.spaceBetween,
                                          children: [
                                            Expanded(
                                              child: Column(
                                                crossAxisAlignment:
                                                    CrossAxisAlignment.start,
                                                children: [
                                                  Text(
                                                    'Assigned Driver',
                                                    style: TextStyle(
                                                      color: Colors.white
                                                          .withOpacity(0.6),
                                                      fontSize: 11,
                                                    ),
                                                  ),
                                                  Text(
                                                    assignedDriverName ??
                                                        'Not assigned',
                                                    style: const TextStyle(
                                                      color: Colors.white,
                                                      fontWeight: FontWeight.bold,
